pub(crate) fn recognizes(arguments: &[OsString]) -> bool {
    arguments
        .first()
        .and_then(|value| value.to_str())
        .is_some_and(|command| COMMANDS.contains(&command))
}

pub(crate) fn github_dispatch_inputs() -> Result<(String, String, String), String> {
    let event_path = std::env::var_os("GITHUB_EVENT_PATH")
        .ok_or_else(|| "GITHUB_EVENT_PATH is unavailable for dispatch input decoding".to_owned())?;
    github_dispatch_inputs_from(Path::new(&event_path))
}

fn github_dispatch_inputs_from(path: &Path) -> Result<(String, String, String), String> {
    let event = parse_json(&read_text(path)?)?;
    let event = event.object()?;
    let inputs = json_member(event, "inputs")?.object()?;
    exact_keys(
        inputs,
        &[
            "assurance_epoch_sha256",
            "candidate_sha",
            "proposal_artifact_id",
            "proposal_provider_archive_sha256",
            "proposal_package_sha256",
            "proposal_run_attempt",
            "promotion_proposal_sha256",
            "proposal_run_id",
            "require_promotion",
        ],
    )?;
    if json_member(inputs, "require_promotion")?.string()? != "true" {
        return Err("dispatch require_promotion must be the exact string true".to_owned());
    }
    let source = json_member(inputs, "candidate_sha")?.string()?.to_owned();
    require_git_sha_text(&source, "dispatch candidate")?;
    let epoch = json_member(inputs, "assurance_epoch_sha256")?
        .string()?
        .to_owned();
    require_digest(&epoch, "dispatch assurance epoch")?;
    let proposal = json_member(inputs, "promotion_proposal_sha256")?
        .string()?
        .to_owned();
    require_digest(&proposal, "dispatch promotion proposal")?;
    let proposal_run_id = json_member(inputs, "proposal_run_id")?
        .string()?
        .parse::<u64>()
        .map_err(|_| "dispatch proposal_run_id is not an integer".to_owned())?;
    if proposal_run_id == 0 {
        return Err("dispatch proposal_run_id must be nonzero".to_owned());
    }
    for key in ["proposal_run_attempt", "proposal_artifact_id"] {
        let value = json_member(inputs, key)?
            .string()?
            .parse::<u64>()
            .map_err(|_| format!("dispatch {key} is not an integer"))?;
        if value == 0 {
            return Err(format!("dispatch {key} must be nonzero"));
        }
    }
    require_digest(
        json_member(inputs, "proposal_package_sha256")?.string()?,
        "dispatch proposal package",
    )?;
    require_digest(
        json_member(inputs, "proposal_provider_archive_sha256")?.string()?,
        "dispatch proposal provider archive",
    )?;
    Ok((source, epoch, proposal))
}

pub(crate) fn github_dispatch_object(
    expected_keys: &[&str],
) -> Result<BTreeMap<String, String>, String> {
    let event_path = std::env::var_os("GITHUB_EVENT_PATH")
        .ok_or_else(|| "GITHUB_EVENT_PATH is unavailable".to_owned())?;
    let event = parse_json(&read_text(Path::new(&event_path))?)?;
    let inputs = json_member(event.object()?, "inputs")?.object()?;
    exact_keys(inputs, expected_keys)?;
    inputs
        .iter()
        .map(|(key, value)| Ok((key.clone(), value.string()?.to_owned())))
        .collect()
}

