fn validate_proposal_assembly_dispatch(
    root: &Path,
    input: &Path,
) -> Result<ProposalSourceIdentity, String> {
    let event = proposal_assembly_dispatch()?;
    let inputs = json_member(event.object()?, "inputs")?.object()?;
    exact_keys(
        inputs,
        &[
            "candidate_sha",
            "custody_artifact_id",
            "custody_package_sha256",
            "custody_run_attempt",
            "custody_run_id",
            "evidence_artifact_id",
            "evidence_package_sha256",
            "evidence_provider_archive_sha256",
            "evidence_run_attempt",
            "evidence_run_id",
            "merged_manifest_sha256",
            "review_package_run_id",
            "review_package_run_attempt",
            "review_package_artifact_id",
            "review_package_sha256",
            "review_provider_archive_sha256",
            "custody_provider_archive_sha256",
            "primary_scrub_artifact_id",
            "primary_scrub_digests",
            "primary_scrub_run_attempt",
            "primary_scrub_run_id",
            "secondary_scrub_artifact_id",
            "secondary_scrub_digests",
            "secondary_scrub_run_attempt",
            "secondary_scrub_run_id",
        ],
    )?;
    let candidate = json_member(inputs, "candidate_sha")?.string()?;
    require_git_sha_text(candidate, "proposal assembly candidate")?;
    if git_output(root, &["rev-parse", "HEAD"])?.trim() != candidate {
        return Err("proposal assembly checkout does not match candidate input".to_owned());
    }
    let expanded_inputs = expand_scrub_digest_inputs(inputs)?;
    assemble_proposal_source_identity(root, input, &expanded_inputs, candidate)
}

fn expand_scrub_digest_inputs(
    inputs: &BTreeMap<String, JsonValue>,
) -> Result<BTreeMap<String, JsonValue>, String> {
    let mut expanded = inputs.clone();
    for provider in ["primary", "secondary"] {
        let compound_key = format!("{provider}_scrub_digests");
        let encoded = expanded
            .remove(&compound_key)
            .ok_or_else(|| format!("proposal dispatch lacks {compound_key}"))?;
        let document = parse_json(encoded.string()?)?;
        let digests = document.object()?;
        exact_keys(digests, &["packageSha256", "providerArchiveSha256"])?;
        for (source, suffix) in [
            ("packageSha256", "package_sha256"),
            ("providerArchiveSha256", "provider_archive_sha256"),
        ] {
            let value = json_member(digests, source)?.string()?;
            require_digest(value, &format!("{provider} scrub {source}"))?;
            expanded.insert(
                format!("{provider}_scrub_{suffix}"),
                JsonValue::String(value.to_owned()),
            );
        }
    }
    Ok(expanded)
}

fn assemble_proposal_source_identity(
    root: &Path,
    input: &Path,
    inputs: &BTreeMap<String, JsonValue>,
    candidate: &str,
) -> Result<ProposalSourceIdentity, String> {
    let merged_expected = json_member(inputs, "merged_manifest_sha256")?.string()?;
    require_digest(merged_expected, "proposal merged manifest")?;
    verify_file_digest(
        &input.join("merged-native-shards.json"),
        merged_expected,
        "proposal merged manifest",
    )?;
    let review_expected = json_member(inputs, "review_package_sha256")?.string()?;
    require_digest(review_expected, "proposal review package")?;
    let custody_expected = json_member(inputs, "custody_package_sha256")?.string()?;
    require_digest(custody_expected, "proposal custody package")?;
    let custody_directory = input.join("evidence").join("custody");
    let custody_without_scrub =
        directory_manifest_excluding(&custody_directory, Path::new("current-scrub"))?;
    let custody = sha256_bytes(custody_without_scrub.as_bytes()).hex();
    let review_without_custody =
        directory_manifest_excluding(&input.join("evidence"), Path::new("custody"))?;
    if sha256_bytes(review_without_custody.as_bytes()).hex() != review_expected
        || custody != custody_expected
    {
        return Err("proposal review-ready or custody package digest mismatch".to_owned());
    }
    let evidence_run_id = proposal_input_integer(inputs, "evidence_run_id")?;
    let evidence_run_attempt = proposal_input_integer(inputs, "evidence_run_attempt")?;
    let evidence_artifact_id = proposal_input_integer(inputs, "evidence_artifact_id")?;
    let review_run_id = proposal_input_integer(inputs, "review_package_run_id")?;
    let review_run_attempt = proposal_input_integer(inputs, "review_package_run_attempt")?;
    let review_artifact_id = proposal_input_integer(inputs, "review_package_artifact_id")?;
    let custody_run_id = proposal_input_integer(inputs, "custody_run_id")?;
    let custody_run_attempt = proposal_input_integer(inputs, "custody_run_attempt")?;
    let custody_artifact_id = proposal_input_integer(inputs, "custody_artifact_id")?;
    let (primary_scrub, secondary_scrub) =
        proposal_scrub_identifiers(inputs, custody_run_id, custody_run_attempt)?;
    let (primary_scrub_run_id, primary_scrub_run_attempt, primary_scrub_artifact_id) =
        primary_scrub;
    let (secondary_scrub_run_id, secondary_scrub_run_attempt, secondary_scrub_artifact_id) =
        secondary_scrub;
    let evidence_package_sha256 = json_member(inputs, "evidence_package_sha256")?.string()?;
    require_digest(evidence_package_sha256, "proposal evidence package")?;
    let selections = verify_proposal_source_selections(
        root,
        input,
        inputs,
        candidate,
        &ProposalProviderIdentifiers {
            evidence: (evidence_run_id, evidence_run_attempt, evidence_artifact_id),
            review: (review_run_id, review_run_attempt, review_artifact_id),
            custody: (custody_run_id, custody_run_attempt, custody_artifact_id),
            primary_scrub: (
                primary_scrub_run_id,
                primary_scrub_run_attempt,
                primary_scrub_artifact_id,
            ),
            secondary_scrub: (
                secondary_scrub_run_id,
                secondary_scrub_run_attempt,
                secondary_scrub_artifact_id,
            ),
        },
    )?;
    Ok(ProposalSourceIdentity {
        evidence_run_id,
        evidence_run_attempt,
        evidence_artifact_id,
        review_run_id,
        review_run_attempt,
        review_artifact_id,
        custody_run_id,
        custody_run_attempt,
        custody_artifact_id,
        primary_scrub_run_id,
        primary_scrub_run_attempt,
        primary_scrub_artifact_id,
        secondary_scrub_run_id,
        secondary_scrub_run_attempt,
        secondary_scrub_artifact_id,
        evidence_package_sha256: evidence_package_sha256.to_owned(),
        merged_sha256: merged_expected.to_owned(),
        review_sha256: review_expected.to_owned(),
        custody_sha256: json_member(inputs, "custody_package_sha256")?
            .string()?
            .to_owned(),
        primary_scrub_sha256: json_member(inputs, "primary_scrub_package_sha256")?
            .string()?
            .to_owned(),
        secondary_scrub_sha256: json_member(inputs, "secondary_scrub_package_sha256")?
            .string()?
            .to_owned(),
        evidence_selection_sha256: selections[0].clone(),
        review_selection_sha256: selections[1].clone(),
        custody_selection_sha256: selections[2].clone(),
        primary_scrub_selection_sha256: selections[3].clone(),
        secondary_scrub_selection_sha256: selections[4].clone(),
    })
}

fn proposal_scrub_identifiers(
    inputs: &BTreeMap<String, JsonValue>,
    custody_run_id: u64,
    custody_run_attempt: u64,
) -> Result<(ProposalProviderId, ProposalProviderId), String> {
    let primary = (
        proposal_input_integer(inputs, "primary_scrub_run_id")?,
        proposal_input_integer(inputs, "primary_scrub_run_attempt")?,
        proposal_input_integer(inputs, "primary_scrub_artifact_id")?,
    );
    let secondary = (
        proposal_input_integer(inputs, "secondary_scrub_run_id")?,
        proposal_input_integer(inputs, "secondary_scrub_run_attempt")?,
        proposal_input_integer(inputs, "secondary_scrub_artifact_id")?,
    );
    if primary.0 != custody_run_id
        || primary.1 != custody_run_attempt
        || secondary.0 != custody_run_id
        || secondary.1 != custody_run_attempt
    {
        return Err(
            "proposal current scrubs must be the initial independent retrievals from the selected custody run"
                .to_owned(),
        );
    }
    Ok((primary, secondary))
}

fn proposal_input_integer(
    inputs: &BTreeMap<String, JsonValue>,
    field: &str,
) -> Result<u64, String> {
    let value = json_member(inputs, field)?
        .string()?
        .parse::<u64>()
        .map_err(|_| format!("proposal assembly {field} is not an integer"))?;
    if value == 0 {
        return Err(format!("proposal assembly {field} must be nonzero"));
    }
    Ok(value)
}

type ProposalProviderId = (u64, u64, u64);

struct ProposalProviderIdentifiers {
    evidence: ProposalProviderId,
    review: ProposalProviderId,
    custody: ProposalProviderId,
    primary_scrub: ProposalProviderId,
    secondary_scrub: ProposalProviderId,
}

fn proposal_assembly_dispatch() -> Result<JsonValue, String> {
    let path = std::env::var_os("GITHUB_EVENT_PATH")
        .ok_or_else(|| "GITHUB_EVENT_PATH is unavailable for proposal assembly".to_owned())?;
    parse_json(&read_text(Path::new(&path))?)
}

fn verify_proposal_source_selections(
    root: &Path,
    input: &Path,
    inputs: &BTreeMap<String, JsonValue>,
    candidate: &str,
    identifiers: &ProposalProviderIdentifiers,
) -> Result<[String; 5], String> {
    let temporary = create_private_temp_directory("hell-proposal-sources")?;
    let evidence = temporary.join("evidence");
    let review = temporary.join("review");
    copy_record_tree_excluding(input, &evidence, "evidence")?;
    copy_record_tree_excluding(&input.join("evidence"), &review, "custody")?;
    let selection_root = input
        .join("evidence")
        .join("source-selection")
        .join("proposal");
    let primary_scrub_artifact = format!(
        "ephemeralEvidence-current-scrub-primary-worm-{}-{}",
        identifiers.primary_scrub.0, identifiers.primary_scrub.1
    );
    let secondary_scrub_artifact = format!(
        "ephemeralEvidence-current-scrub-secondary-worm-{}-{}",
        identifiers.secondary_scrub.0, identifiers.secondary_scrub.1
    );
    let primary_scrub_source = input
        .join("evidence")
        .join("custody")
        .join("current-scrub")
        .join("primary-worm");
    let secondary_scrub_source = input
        .join("evidence")
        .join("custody")
        .join("current-scrub")
        .join("secondary-worm");
    let specs = [
        ProposalProviderSpec {
            label: "evidence",
            source: &evidence,
            artifact: "native-oracle-merged",
            workflow: ".github/workflows/nightly.yml",
            event: "push",
            ids: identifiers.evidence,
            package_field: "evidence_package_sha256",
            archive_field: "evidence_provider_archive_sha256",
        },
        ProposalProviderSpec {
            label: "review",
            source: &review,
            artifact: "promotion-final-reviewed-evidence",
            workflow: ".github/workflows/evidence-custody.yml",
            event: "workflow_dispatch",
            ids: identifiers.review,
            package_field: "review_package_sha256",
            archive_field: "review_provider_archive_sha256",
        },
        ProposalProviderSpec {
            label: "custody",
            source: &input.join("evidence").join("custody"),
            artifact: "promotion-custody-evidence",
            workflow: ".github/workflows/evidence-custody.yml",
            event: "workflow_dispatch",
            ids: identifiers.custody,
            package_field: "custody_package_sha256",
            archive_field: "custody_provider_archive_sha256",
        },
        ProposalProviderSpec {
            label: "primaryScrub",
            source: &primary_scrub_source,
            artifact: &primary_scrub_artifact,
            workflow: ".github/workflows/evidence-custody.yml",
            event: "workflow_dispatch",
            ids: identifiers.primary_scrub,
            package_field: "primary_scrub_package_sha256",
            archive_field: "primary_scrub_provider_archive_sha256",
        },
        ProposalProviderSpec {
            label: "secondaryScrub",
            source: &secondary_scrub_source,
            artifact: &secondary_scrub_artifact,
            workflow: ".github/workflows/evidence-custody.yml",
            event: "workflow_dispatch",
            ids: identifiers.secondary_scrub,
            package_field: "secondary_scrub_package_sha256",
            archive_field: "secondary_scrub_provider_archive_sha256",
        },
    ];
    let mut digests = Vec::new();
    for spec in specs {
        digests.push(verify_proposal_provider_spec(
            root,
            &selection_root,
            inputs,
            candidate,
            &spec,
        )?);
    }
    verify_review_native_source_join(input, inputs, candidate, identifiers.evidence)?;
    fs::remove_dir_all(&temporary)
        .map_err(|error| format!("cannot remove proposal source staging: {error}"))?;
    digests
        .try_into()
        .map_err(|_| "proposal provider selection count is invalid".to_owned())
}

struct ProposalProviderSpec<'a> {
    label: &'a str,
    source: &'a Path,
    artifact: &'a str,
    workflow: &'a str,
    event: &'a str,
    ids: (u64, u64, u64),
    package_field: &'a str,
    archive_field: &'a str,
}

fn verify_proposal_provider_spec(
    root: &Path,
    selection_root: &Path,
    inputs: &BTreeMap<String, JsonValue>,
    candidate: &str,
    spec: &ProposalProviderSpec<'_>,
) -> Result<String, String> {
    let package_sha256 = json_member(inputs, spec.package_field)?.string()?;
    let archive_sha256 = json_member(inputs, spec.archive_field)?.string()?;
    require_digest(package_sha256, "proposal source package")?;
    require_digest(archive_sha256, "proposal source provider archive")?;
    let output = selection_root.join(spec.label);
    let selection = verify_provider_artifact_selection_to(
        root,
        spec.source,
        &output,
        spec.artifact,
        spec.workflow,
        spec.event,
        spec.ids.0,
        spec.ids.1,
        spec.ids.2,
        candidate,
        package_sha256,
        archive_sha256,
    )?;
    let document = parse_json(&selection)?;
    if json_member(document.object()?, "providerArchiveSha256")?.string()? != archive_sha256 {
        return Err("proposal source provider archive differs from dispatch".to_owned());
    }
    let selection_path = output.join("selection.json");
    write_atomic(&selection_path, selection.as_bytes())?;
    record_digest(&selection_path)
}

fn copy_record_tree_excluding(
    source: &Path,
    destination: &Path,
    excluded_name: &str,
) -> Result<(), String> {
    fs::create_dir(destination)
        .map_err(|error| format!("cannot create proposal source staging: {error}"))?;
    let mut entries = fs::read_dir(source)
        .map_err(|error| format!("cannot enumerate proposal source: {error}"))?
        .collect::<Result<Vec<_>, _>>()
        .map_err(|error| format!("cannot enumerate proposal source: {error}"))?;
    entries.sort_by_key(std::fs::DirEntry::file_name);
    for entry in entries {
        if entry.file_name() == OsStr::new(excluded_name) {
            continue;
        }
        copy_record_tree(&entry.path(), &destination.join(entry.file_name()))?;
    }
    Ok(())
}

fn verify_review_native_source_join(
    input: &Path,
    inputs: &BTreeMap<String, JsonValue>,
    candidate: &str,
    evidence_ids: (u64, u64, u64),
) -> Result<(), String> {
    let path = input
        .join("evidence")
        .join("native")
        .join("native-provider-selection.json");
    let document = parse_json(&read_text(&path)?)?;
    let selection = document.object()?;
    if json_member(selection, "artifact")?.string()? != "native-oracle-merged"
        || json_member(selection, "workflowPath")?.string()? != ".github/workflows/nightly.yml"
        || json_member(selection, "event")?.string()? != "push"
        || json_member(selection, "providerRunId")?.number()? != evidence_ids.0
        || json_member(selection, "providerRunAttempt")?.number()? != evidence_ids.1
        || json_member(selection, "providerArtifactId")?.number()? != evidence_ids.2
        || json_member(selection, "candidateCommit")?.string()? != candidate
        || json_member(selection, "directorySha256")?.string()?
            != json_member(inputs, "evidence_package_sha256")?.string()?
        || record_digest(
            &input
                .join("evidence")
                .join("native")
                .join("merged-native-shards.json"),
        )? != record_digest(&input.join("merged-native-shards.json"))?
    {
        return Err(
            "review package was not derived from the exact native evidence source".to_owned(),
        );
    }
    Ok(())
}

fn promotion_approval_identity(
    root: &Path,
    proposal: &Path,
    epoch: &Digest,
) -> Result<(String, String), String> {
    let event_path = std::env::var_os("GITHUB_EVENT_PATH")
        .ok_or_else(|| "GITHUB_EVENT_PATH is unavailable for proposal approval".to_owned())?;
    let event = parse_json(&read_text(Path::new(&event_path))?)?;
    let inputs = json_member(event.object()?, "inputs")?.object()?;
    exact_keys(
        inputs,
        &[
            "assurance_epoch_sha256",
            "candidate_sha",
            "issued_at",
            "proposal_artifact_id",
            "proposal_provider_archive_sha256",
            "proposal_package_sha256",
            "proposal_run_attempt",
            "promotion_proposal_sha256",
            "proposal_run_id",
            "require_approval",
        ],
    )?;
    if json_member(inputs, "require_approval")?.string()? != "true" {
        return Err("proposal approval requires the exact string true".to_owned());
    }
    let candidate = json_member(inputs, "candidate_sha")?.string()?;
    require_git_sha_text(candidate, "approval candidate")?;
    if git_output(root, &["rev-parse", "HEAD"])?.trim() != candidate {
        return Err("proposal approval checkout does not match the candidate input".to_owned());
    }
    let expected_epoch = json_member(inputs, "assurance_epoch_sha256")?.string()?;
    require_digest(expected_epoch, "approval assurance epoch")?;
    if expected_epoch != epoch.hex() {
        return Err("proposal approval epoch does not match the candidate inputs".to_owned());
    }
    let expected_proposal = json_member(inputs, "promotion_proposal_sha256")?.string()?;
    require_digest(expected_proposal, "approval proposal")?;
    if record_digest(proposal)? != expected_proposal {
        return Err("proposal approval input digest mismatch".to_owned());
    }
    let identifier = |key: &str| -> Result<u64, String> {
        let value = json_member(inputs, key)?
            .string()?
            .parse::<u64>()
            .map_err(|_| format!("approval {key} is not an integer"))?;
        if value == 0 {
            return Err(format!("approval {key} must be nonzero"));
        }
        Ok(value)
    };
    let run_id = identifier("proposal_run_id")?;
    let run_attempt = identifier("proposal_run_attempt")?;
    let artifact_id = identifier("proposal_artifact_id")?;
    let expected_package = json_member(inputs, "proposal_package_sha256")?.string()?;
    let expected_archive = json_member(inputs, "proposal_provider_archive_sha256")?.string()?;
    require_digest(expected_package, "approval proposal package")?;
    require_digest(expected_archive, "approval proposal provider archive")?;
    let proposal_directory = proposal
        .parent()
        .ok_or_else(|| "approval proposal has no package directory".to_owned())?;
    let selection = verify_provider_artifact_selection(
        root,
        proposal_directory,
        "promotion-proposal",
        ".github/workflows/promotion-proposal.yml",
        "workflow_dispatch",
        run_id,
        run_attempt,
        artifact_id,
        candidate,
        expected_package,
        expected_archive,
    )?;
    verify_selection_archive(&selection, expected_archive)?;
    write_atomic(
        &proposal_directory.join("proposal-provider-selection.json"),
        selection.as_bytes(),
    )?;
    let issued_at = json_member(inputs, "issued_at")?.string()?.to_owned();
    validate_utc_timestamp(&issued_at)?;
    Ok((candidate.to_owned(), issued_at))
}

fn promotion_approval_subject(root: &Path, options: &Options) -> Result<String, String> {
    let proposal = required_path(
        &options.input,
        "promotion-approval-subject requires --input proposal",
    )?;
    let output = required_path(
        &options.output,
        "promotion-approval-subject requires --output subject",
    )?;
    let (_, epoch) = epoch(root)?;
    let (candidate, _) = promotion_approval_identity(root, proposal, &epoch)?;
    let proposal_document = parse_json(&read_text(proposal)?)?;
    let proposal_sha256 = record_digest(proposal)?;
    let directory = proposal
        .parent()
        .ok_or_else(|| "promotion proposal has no package directory".to_owned())?;
    let selection = directory.join("proposal-provider-selection.json");
    let selection_sha256 = record_digest(&selection)?;
    let mut artifacts = proposal_review_artifacts(proposal_document.object()?, &proposal_sha256)?;
    artifacts.insert(selection_sha256.clone());
    let document = JsonValue::Object(BTreeMap::from([
        ("schemaVersion".to_owned(), JsonValue::Number(1)),
        (
            "candidateSourceCommit".to_owned(),
            JsonValue::String(candidate),
        ),
        (
            "assuranceEpochSha256".to_owned(),
            JsonValue::String(epoch.hex()),
        ),
        (
            "proposalPath".to_owned(),
            JsonValue::String("promotion-proposal.json".to_owned()),
        ),
        (
            "proposalSha256".to_owned(),
            JsonValue::String(proposal_sha256),
        ),
        (
            "providerSelectionPath".to_owned(),
            JsonValue::String("proposal-provider-selection.json".to_owned()),
        ),
        (
            "providerSelectionSha256".to_owned(),
            JsonValue::String(selection_sha256),
        ),
        (
            "reviewedArtifacts".to_owned(),
            JsonValue::Array(artifacts.into_iter().map(JsonValue::String).collect()),
        ),
    ]));
    write_atomic(output, &canonical_json_bytes(&document)?)?;
    Ok(format!(
        "wrote exact promotion approval subject {}",
        output.display()
    ))
}

fn verify_promotion_approval_subject(
    subject_path: &Path,
    proposal: &Path,
    candidate: &str,
    epoch: &str,
) -> Result<(), String> {
    let subject = parse_json(&read_text(subject_path)?)?;
    let subject = subject.object()?;
    exact_keys(
        subject,
        &[
            "assuranceEpochSha256",
            "candidateSourceCommit",
            "proposalPath",
            "proposalSha256",
            "providerSelectionPath",
            "providerSelectionSha256",
            "reviewedArtifacts",
            "schemaVersion",
        ],
    )?;
    let directory = subject_path
        .parent()
        .ok_or_else(|| "promotion approval subject has no directory".to_owned())?;
    let selection = directory.join("proposal-provider-selection.json");
    let proposal_sha256 = record_digest(proposal)?;
    let selection_sha256 = record_digest(&selection)?;
    let proposal_document = parse_json(&read_text(proposal)?)?;
    let mut artifacts = proposal_review_artifacts(proposal_document.object()?, &proposal_sha256)?;
    artifacts.insert(selection_sha256.clone());
    if json_member(subject, "schemaVersion")?.number()? != 1
        || json_member(subject, "candidateSourceCommit")?.string()? != candidate
        || json_member(subject, "assuranceEpochSha256")?.string()? != epoch
        || json_member(subject, "proposalPath")?.string()? != "promotion-proposal.json"
        || json_member(subject, "providerSelectionPath")?.string()?
            != "proposal-provider-selection.json"
        || json_member(subject, "proposalSha256")?.string()? != proposal_sha256
        || json_member(subject, "providerSelectionSha256")?.string()? != selection_sha256
        || json_member(subject, "reviewedArtifacts")?
            .array()?
            .iter()
            .map(JsonValue::string)
            .collect::<Result<BTreeSet<_>, _>>()?
            != artifacts.iter().map(String::as_str).collect()
    {
        return Err(
            "promotion approval subject does not bind the exact proposal selector".to_owned(),
        );
    }
    Ok(())
}

struct ArtifactFinalizeSource {
    run_id: u64,
    run_attempt: u64,
    artifact_id: u64,
    package_sha256: String,
    archive_sha256: String,
}

struct ArtifactFinalizeDispatch {
    candidate: String,
    primary: ArtifactFinalizeSource,
    independent: ArtifactFinalizeSource,
}

fn artifact_finalize_dispatch(root: &Path) -> Result<ArtifactFinalizeDispatch, String> {
    let event_path = std::env::var_os("GITHUB_EVENT_PATH")
        .ok_or_else(|| "GITHUB_EVENT_PATH is unavailable for artifact review".to_owned())?;
    let event = parse_json(&read_text(Path::new(&event_path))?)?;
    let inputs = json_member(event.object()?, "inputs")?.object()?;
    exact_keys(
        inputs,
        &[
            "candidate_sha",
            "independent_review_archive_sha256",
            "independent_review_artifact_id",
            "independent_review_package_sha256",
            "independent_review_run_attempt",
            "independent_review_run_id",
            "issued_at",
            "primary_packet_archive_sha256",
            "primary_packet_artifact_id",
            "primary_packet_package_sha256",
            "primary_packet_run_attempt",
            "primary_packet_run_id",
            "require_review",
        ],
    )?;
    if json_member(inputs, "require_review")?.string()? != "true" {
        return Err("artifact trust review requires the exact string true".to_owned());
    }
    let candidate = json_member(inputs, "candidate_sha")?.string()?;
    require_git_sha_text(candidate, "artifact review candidate")?;
    if git_output(root, &["rev-parse", "HEAD"])?.trim() != candidate {
        return Err("artifact review checkout does not match candidate input".to_owned());
    }
    validate_utc_timestamp(json_member(inputs, "issued_at")?.string()?)?;
    Ok(ArtifactFinalizeDispatch {
        candidate: candidate.to_owned(),
        primary: artifact_finalize_source(inputs, "primary_packet")?,
        independent: artifact_finalize_source(inputs, "independent_review")?,
    })
}

fn artifact_finalize_source(
    inputs: &BTreeMap<String, JsonValue>,
    prefix: &str,
) -> Result<ArtifactFinalizeSource, String> {
    let integer = |suffix: &str| {
        let key = format!("{prefix}_{suffix}");
        let value = json_member(inputs, &key)?
            .string()?
            .parse::<u64>()
            .map_err(|_| format!("artifact review {key} is not an integer"))?;
        if value == 0 {
            return Err(format!("artifact review {key} must be nonzero"));
        }
        Ok(value)
    };
    let digest = |suffix: &str| -> Result<String, String> {
        let key = format!("{prefix}_{suffix}");
        let value = json_member(inputs, &key)?.string()?.to_owned();
        require_digest(&value, &format!("artifact review {key}"))?;
        Ok(value)
    };
    Ok(ArtifactFinalizeSource {
        run_id: integer("run_id")?,
        run_attempt: integer("run_attempt")?,
        artifact_id: integer("artifact_id")?,
        package_sha256: digest("package_sha256")?,
        archive_sha256: digest("archive_sha256")?,
    })
}

fn validate_utc_timestamp(value: &str) -> Result<(), String> {
    utc_timestamp_seconds(value).map(drop)
}

pub(crate) fn utc_timestamp_seconds(value: &str) -> Result<u64, String> {
    let (date, time) = value
        .strip_suffix('Z')
        .and_then(|value| value.split_once('T'))
        .ok_or_else(|| "review issued_at must be a UTC timestamp".to_owned())?;
    let date = date
        .split('-')
        .map(str::parse::<u32>)
        .collect::<Result<Vec<_>, _>>()
        .map_err(|_| "review issued_at date is invalid".to_owned())?;
    let time = time
        .split(':')
        .map(str::parse::<u32>)
        .collect::<Result<Vec<_>, _>>()
        .map_err(|_| "review issued_at time is invalid".to_owned())?;
    let expected_fields = ["first", "second", "third"];
    if date.len() != expected_fields.len()
        || time.len() != expected_fields.len()
        || !(1..=12).contains(&date[1])
        || date[2] == 0
        || date[2] > utc_days_in_month(date[0], date[1])
        || time[0] > 23
        || time[1] > 59
        || time[2] > 59
    {
        return Err("review issued_at fields are outside UTC timestamp bounds".to_owned());
    }
    let year = i64::from(date[0]);
    let month = i64::from(date[1]);
    let day = i64::from(date[2]);
    let adjusted_year = year - i64::from(month <= 2);
    let era = adjusted_year.div_euclid(400);
    let year_of_era = adjusted_year - era * 400;
    let adjusted_month = month + if month > 2 { -3 } else { 9 };
    let day_of_year = (153 * adjusted_month + 2) / 5 + day - 1;
    let day_of_era = year_of_era * 365 + year_of_era / 4 - year_of_era / 100 + day_of_year;
    let unix_days = era * 146_097 + day_of_era - 719_468;
    if unix_days < 0 {
        return Err("review timestamp predates the Unix epoch".to_owned());
    }
    let seconds = u64::try_from(unix_days)
        .map_err(|_| "review timestamp day count overflows".to_owned())?
        .checked_mul(86_400)
        .and_then(|value| value.checked_add(u64::from(time[0]) * 3_600))
        .and_then(|value| value.checked_add(u64::from(time[1]) * 60))
        .and_then(|value| value.checked_add(u64::from(time[2])))
        .ok_or_else(|| "review timestamp seconds overflow".to_owned())?;
    Ok(seconds)
}

fn utc_days_in_month(year: u32, month: u32) -> u32 {
    match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 if year.is_multiple_of(400) || (year.is_multiple_of(4) && !year.is_multiple_of(100)) => {
            29
        }
        2 => 28,
        _ => 0,
    }
}

fn current_utc_seconds() -> Result<u64, String> {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map_err(|_| "system clock predates Unix epoch".to_owned())
        .map(|duration| duration.as_secs())
}

pub(crate) fn run_cli(root: &Path, arguments: &[OsString]) -> ExitCode {
    let result = parse(arguments).and_then(|(command, options)| dispatch(root, &command, &options));
    match result {
        Ok(message) => {
            println!("{message}");
            ExitCode::SUCCESS
        }
        Err(error) => {
            eprintln!("{error}");
            ExitCode::from(10)
        }
    }
}

#[allow(clippy::too_many_lines)]
pub(crate) fn validate_promotion_dispatch(
    root: &Path,
    retained_input: &Path,
    proposal: &Path,
    expected_source: &str,
    expected_epoch: &str,
    expected_proposal: &str,
) -> Result<(), String> {
    require_digest(expected_epoch, "expected assurance epoch")?;
    require_digest(expected_proposal, "expected promotion proposal")?;
    let source = git_output(root, &["rev-parse", "HEAD"])?;
    if source.trim() != expected_source {
        return Err(format!(
            "promotion dispatch source mismatch: expected {expected_source}, observed {}",
            source.trim()
        ));
    }
    let (_, epoch) = epoch(root)?;
    if epoch.hex() != expected_epoch {
        return Err(format!(
            "promotion dispatch epoch mismatch: expected {expected_epoch}, observed {}",
            epoch.hex()
        ));
    }
    let bytes = read_regular_file(proposal)?;
    let observed = sha256_bytes(&bytes).hex();
    if observed != expected_proposal {
        return Err(format!(
            "promotion proposal digest mismatch: expected {expected_proposal}, observed {observed}"
        ));
    }
    let document =
        std::str::from_utf8(&bytes).map_err(|_| "promotion proposal is not UTF-8".to_owned())?;
    let proposal_json = parse_json(document)?;
    let proposal_object = proposal_json.object()?;
    exact_keys(
        proposal_object,
        &[
            "assuranceEpochSha256",
            "blockerCount",
            "blockers",
            "candidateSourceCommit",
            "finalMergedManifestSha256",
            "mergedManifestSha256",
            "readyForExplicitGate",
            "records",
            "schemaVersion",
            "sourceEvidence",
        ],
    )?;
    if json_member(proposal_object, "schemaVersion")?.number()? != 1
        || json_member(proposal_object, "candidateSourceCommit")?.string()? != expected_source
        || json_member(proposal_object, "assuranceEpochSha256")?.string()? != expected_epoch
        || json_member(proposal_object, "blockerCount")?.number()? != 0
        || !json_member(proposal_object, "readyForExplicitGate")?.boolean()?
    {
        return Err("promotion proposal is not ready or does not bind dispatch inputs".to_owned());
    }
    require_digest(
        json_member(proposal_object, "mergedManifestSha256")?.string()?,
        "proposal merged manifest",
    )?;
    let merged = read_regular_file(&retained_input.join("merged-native-shards.json"))?;
    if sha256_bytes(&merged).hex()
        != json_member(proposal_object, "mergedManifestSha256")?.string()?
    {
        return Err("promotion proposal does not bind the retained merged manifest".to_owned());
    }
    let final_merged = read_regular_file(&retained_input.join("merged-native-shards.final.json"))?;
    verify_final_merged_readiness(proposal_object, &merged, &final_merged)?;
    verify_proposal_source_identity(
        proposal_object,
        &sha256_bytes(&merged).hex(),
        retained_input,
    )?;
    let blockers = json_member(proposal_object, "blockers")?.object()?;
    exact_keys(blockers, PROMOTION_BLOCKERS)?;
    if blockers
        .values()
        .any(|value| value.number().is_err() || value.number().unwrap_or(1) != 0)
    {
        return Err("promotion proposal contains nonzero or malformed blockers".to_owned());
    }
    let records = json_member(proposal_object, "records")?.object()?;
    let required_records = [
        "artifactAuthenticity",
        "claimCoverage",
        "custody",
        "divergence",
        "mutation",
        "normalizerAudit",
        "oracleProvenanceMacos",
        "oracleProvenanceWindows",
        "residualRisk",
        "reviewRoleGraph",
    ];
    let evidence_root = retained_input.join("evidence");
    let mut pointers = BTreeMap::new();
    for name in required_records {
        let record = json_member(records, name)?.object()?;
        exact_keys(record, &["path", "sha256"])?;
        let path = confined_record_path(
            root,
            &evidence_root,
            Path::new(json_member(record, "path")?.string()?),
        )?;
        let expected = json_member(record, "sha256")?.string()?;
        require_digest(expected, name)?;
        let observed = record_digest(&path)?;
        if observed != expected {
            return Err(format!("promotion record {name} digest mismatch"));
        }
        pointers.insert(name, path);
    }
    let allowed_signers = root.join("compat").join("reviews.allowed_signers");
    artifact_verify(
        root,
        &Options {
            input: pointers.get("artifactAuthenticity").cloned(),
            policy: Some(allowed_signers.clone()),
            ..Options::default()
        },
    )?;
    for name in ["oracleProvenanceMacos", "oracleProvenanceWindows"] {
        oracle_provenance(
            root,
            &Options {
                action: Some("verify".to_owned()),
                input: pointers.get(name).cloned(),
                policy: Some(allowed_signers.clone()),
                ..Options::default()
            },
        )?;
    }
    custody_command(&Options {
        action: Some("verify".to_owned()),
        input: pointers.get("custody").cloned(),
        policy: Some(allowed_signers.clone()),
        ..Options::default()
    })?;
    retained_report_command(
        root,
        &Options {
            input: pointers.get("mutation").cloned(),
            policy: Some(allowed_signers.clone()),
            expect_source: Some(expected_source.to_owned()),
            expect_epoch: Some(expected_epoch.to_owned()),
            ..Options::default()
        },
        "mutation",
    )?;
    for (name, kind, role) in [
        ("claimCoverage", "claim-coverage", "claim-reviewer"),
        ("normalizerAudit", "normalizer-audit", "normalizer-reviewer"),
        ("divergence", "divergence", "divergence-reviewer"),
        ("residualRisk", "residual-risk", "residual-risk-reviewer"),
        (
            "reviewRoleGraph",
            "review-role-graph",
            "review-graph-reviewer",
        ),
    ] {
        verify_bound_report(
            pointers
                .get(name)
                .ok_or_else(|| format!("missing proposal record {name}"))?,
            &allowed_signers,
            kind,
            role,
            expected_source,
            expected_epoch,
            &evidence_root,
        )?;
    }
    verify_divergence_tier_approvals(
        pointers
            .get("divergence")
            .ok_or_else(|| "missing divergence proposal record".to_owned())?,
        &evidence_root,
        &allowed_signers,
        expected_source,
        expected_epoch,
    )?;
    verify_claim_status_consistency(
        pointers
            .get("claimCoverage")
            .ok_or_else(|| "missing claim coverage record".to_owned())?,
        pointers
            .get("normalizerAudit")
            .ok_or_else(|| "missing normalizer audit record".to_owned())?,
        pointers
            .get("divergence")
            .ok_or_else(|| "missing divergence record".to_owned())?,
        &evidence_root,
    )?;
    verify_residual_gate_source_records(&pointers, &evidence_root)?;
    let verified_review_graph = verify_actual_review_graph(
        &pointers,
        &evidence_root,
        &allowed_signers,
        expected_source,
        expected_epoch,
    )?;
    let (_, approval_account_id) = verify_proposal_approval(
        proposal_object,
        expected_proposal,
        expected_source,
        expected_epoch,
        &retained_input.join("promotion-proposal-approval.dsse.json"),
        &allowed_signers,
    )?;
    let review_policy = load_review_policy(&repository_root()?)?;
    verify_promotion_approver_independence(
        &verified_review_graph.actions,
        &approval_account_id,
        &review_policy,
    )?;
    Ok(())
}

fn verify_divergence_tier_approvals(
    divergence_record: &Path,
    retained_root: &Path,
    fallback_policy: &Path,
    candidate: &str,
    epoch: &str,
) -> Result<(), String> {
    let wrapper = parse_json(&read_text(divergence_record)?)?;
    let wrapper = wrapper.object()?;
    let repository = repository_root()?;
    let details_path = confined_record_path(
        &repository,
        retained_root,
        Path::new(json_member(wrapper, "detailsPath")?.string()?),
    )?;
    let divergence = parse_json(&read_text(&details_path)?)?;
    let divergence = divergence.object()?;
    let required = required_divergence_roles(divergence)?;
    let observed = divergence_approval_roles(divergence_record, retained_root)?;
    if observed != required {
        return Err(
            "retained divergence approvals are not the exact tier-derived role set".to_owned(),
        );
    }
    let details_sha256 = record_digest(&details_path)?;
    let mut accounts = BTreeSet::new();
    let mut fingerprints = BTreeSet::new();
    for role in required {
        let (authorization_path, review_path) =
            divergence_approval_paths(divergence_record, retained_root, &role)?;
        let (account_id, _, _, _, _) =
            verify_review_authorization(&authorization_path, &role, candidate, &details_path)?;
        let signer_policy = review_policy_for_envelope(&review_path, fallback_policy)?;
        let review = verify_review_envelope(&review_path, &signer_policy)?;
        let expected_artifacts =
            BTreeSet::from([details_sha256.clone(), record_digest(&authorization_path)?]);
        if review.role != role
            || review.candidate_commit != candidate
            || review.assurance_epoch != epoch
            || review.reviewed_artifacts != expected_artifacts
            || !accounts.insert(account_id)
            || !fingerprints.insert(review.signer_fingerprint)
        {
            return Err(format!(
                "divergence approval {role:?} is not uniquely authorized and bound to the exact accepted report"
            ));
        }
    }
    Ok(())
}

fn divergence_approval_roles(
    divergence_record: &Path,
    retained_root: &Path,
) -> Result<BTreeSet<String>, String> {
    let mut roles = BTreeSet::from(["divergence-reviewer".to_owned()]);
    for role in [
        "divergence-platform-reviewer",
        "divergence-implementation-reviewer",
        "divergence-product-reviewer",
        "divergence-security-reviewer",
    ] {
        let (authorization, review) =
            divergence_approval_paths(divergence_record, retained_root, role)?;
        if authorization.is_file() || review.is_file() {
            if !authorization.is_file() || !review.is_file() {
                return Err(format!(
                    "divergence approval {role:?} is only partially retained"
                ));
            }
            roles.insert(role.to_owned());
        }
    }
    Ok(roles)
}

fn divergence_approval_paths(
    divergence_record: &Path,
    retained_root: &Path,
    role: &str,
) -> Result<(PathBuf, PathBuf), String> {
    if role == "divergence-reviewer" {
        let wrapper = parse_json(&read_text(divergence_record)?)?;
        let wrapper = wrapper.object()?;
        let repository = repository_root()?;
        return Ok((
            confined_record_path(
                &repository,
                retained_root,
                Path::new(json_member(wrapper, "authorizationPath")?.string()?),
            )?,
            confined_record_path(
                &repository,
                retained_root,
                Path::new(json_member(wrapper, "reviewPath")?.string()?),
            )?,
        ));
    }
    if !matches!(
        role,
        "divergence-platform-reviewer"
            | "divergence-implementation-reviewer"
            | "divergence-product-reviewer"
            | "divergence-security-reviewer"
    ) {
        return Err(format!("unsupported divergence approval role {role:?}"));
    }
    let directory = retained_root
        .join("review")
        .join("divergence-approvals")
        .join(role);
    Ok((
        directory.join("authorization.json"),
        directory.join("review.dsse.json"),
    ))
}

fn proposal_review_artifacts(
    proposal: &BTreeMap<String, JsonValue>,
    proposal_digest: &str,
) -> Result<BTreeSet<String>, String> {
    require_digest(proposal_digest, "promotion proposal")?;
    exact_keys(
        json_member(proposal, "blockers")?.object()?,
        PROMOTION_BLOCKERS,
    )?;
    let mut artifacts = BTreeSet::from([proposal_digest.to_owned()]);
    let merged = json_member(proposal, "mergedManifestSha256")?
        .string()?
        .to_owned();
    require_digest(&merged, "proposal merged manifest")?;
    artifacts.insert(merged);
    let final_merged = json_member(proposal, "finalMergedManifestSha256")?
        .string()?
        .to_owned();
    require_digest(&final_merged, "proposal final merged manifest")?;
    if !artifacts.insert(final_merged) {
        return Err("final merged manifest duplicates another reviewed artifact".to_owned());
    }
    for record in json_member(proposal, "records")?.object()?.values() {
        let digest = json_member(record.object()?, "sha256")?
            .string()?
            .to_owned();
        require_digest(&digest, "proposal component record")?;
        if !artifacts.insert(digest) {
            return Err("promotion proposal contains duplicate component digests".to_owned());
        }
    }
    Ok(artifacts)
}

fn blocker_set_digest(blockers: &BTreeMap<String, JsonValue>) -> Result<String, String> {
    let document = JsonValue::Object(blockers.clone());
    Ok(sha256_bytes(&canonical_json_bytes(&document)?).hex())
}

fn verify_final_merged_readiness(
    proposal: &BTreeMap<String, JsonValue>,
    merged: &[u8],
    final_merged: &[u8],
) -> Result<(), String> {
    if sha256_bytes(final_merged).hex()
        != json_member(proposal, "finalMergedManifestSha256")?.string()?
    {
        return Err("proposal does not bind the final merged manifest".to_owned());
    }
    let final_document = parse_json(
        std::str::from_utf8(final_merged)
            .map_err(|_| "final merged manifest is not UTF-8".to_owned())?,
    )?;
    let readiness = final_document.object()?;
    exact_keys(
        readiness,
        &[
            "assuranceEpochSha256",
            "blockersSha256",
            "candidateSourceCommit",
            "mechanicalMergedManifestSha256",
            "mechanicalPromotionReady",
            "promotionReady",
            "schemaVersion",
        ],
    )?;
    let blockers = json_member(proposal, "blockers")?.object()?;
    let merged_digest = sha256_bytes(merged).hex();
    if json_member(readiness, "schemaVersion")?.number()? != 1
        || json_member(readiness, "candidateSourceCommit")?.string()?
            != json_member(proposal, "candidateSourceCommit")?.string()?
        || json_member(readiness, "assuranceEpochSha256")?.string()?
            != json_member(proposal, "assuranceEpochSha256")?.string()?
        || json_member(readiness, "mechanicalMergedManifestSha256")?.string()? != merged_digest
        || json_member(readiness, "mechanicalPromotionReady")?.boolean()?
        || !json_member(readiness, "promotionReady")?.boolean()?
        || json_member(readiness, "blockersSha256")?.string()? != blocker_set_digest(blockers)?
        || blockers
            .values()
            .any(|value| value.number().is_err() || value.number().unwrap_or(1) != 0)
    {
        return Err(
            "final merged readiness does not bind a blocker-free mechanical manifest".to_owned(),
        );
    }
    let merged_document = parse_json(
        std::str::from_utf8(merged)
            .map_err(|_| "retained merged manifest is not UTF-8".to_owned())?,
    )?;
    if json_member(merged_document.object()?, "promotionReady")?.boolean()? {
        return Err("mechanical merged manifest must remain promotionReady false".to_owned());
    }
    Ok(())
}

pub fn fuzz_admit_evidence_graph_merge(bytes: &[u8]) -> Result<(), String> {
    let blockers = PROMOTION_BLOCKERS
        .iter()
        .map(|name| ((*name).to_owned(), JsonValue::Number(0)))
        .collect::<BTreeMap<_, _>>();
    let merged = b"{\"promotionReady\":false}\n";
    let proposal = BTreeMap::from([
        (
            "assuranceEpochSha256".to_owned(),
            JsonValue::String(sha256_bytes(b"fuzz-evidence-graph-epoch").hex()),
        ),
        ("blockers".to_owned(), JsonValue::Object(blockers)),
        (
            "candidateSourceCommit".to_owned(),
            JsonValue::String("6666666666666666666666666666666666666666".to_owned()),
        ),
        (
            "finalMergedManifestSha256".to_owned(),
            JsonValue::String(sha256_bytes(bytes).hex()),
        ),
    ]);
    verify_final_merged_readiness(&proposal, merged, bytes)
}

pub fn fuzz_evidence_graph_seed() -> Result<Vec<u8>, String> {
    let blockers = PROMOTION_BLOCKERS
        .iter()
        .map(|name| ((*name).to_owned(), JsonValue::Number(0)))
        .collect::<BTreeMap<_, _>>();
    let merged = b"{\"promotionReady\":false}\n";
    canonical_json_bytes(&JsonValue::Object(BTreeMap::from([
        (
            "assuranceEpochSha256".to_owned(),
            JsonValue::String(sha256_bytes(b"fuzz-evidence-graph-epoch").hex()),
        ),
        (
            "blockersSha256".to_owned(),
            JsonValue::String(blocker_set_digest(&blockers)?),
        ),
        (
            "candidateSourceCommit".to_owned(),
            JsonValue::String("6666666666666666666666666666666666666666".to_owned()),
        ),
        (
            "mechanicalMergedManifestSha256".to_owned(),
            JsonValue::String(sha256_bytes(merged).hex()),
        ),
        (
            "mechanicalPromotionReady".to_owned(),
            JsonValue::Bool(false),
        ),
        ("promotionReady".to_owned(), JsonValue::Bool(true)),
        ("schemaVersion".to_owned(), JsonValue::Number(1)),
    ])))
}

fn verify_proposal_source_identity(
    proposal: &BTreeMap<String, JsonValue>,
    merged_sha256: &str,
    retained_input: &Path,
) -> Result<(), String> {
    let source = json_member(proposal, "sourceEvidence")?.object()?;
    verify_proposal_source_shape(source, merged_sha256)?;
    verify_proposal_source_selection_records(proposal, source, retained_input)
}

fn verify_proposal_source_shape(
    source: &BTreeMap<String, JsonValue>,
    merged_sha256: &str,
) -> Result<(), String> {
    exact_keys(
        source,
        &[
            "evidenceArtifactId",
            "evidenceArtifactName",
            "evidenceRunAttempt",
            "evidenceRunId",
            "evidenceSha256",
            "evidencePackageSha256",
            "evidenceSelectionSha256",
            "reviewArtifactId",
            "reviewArtifactName",
            "reviewRunAttempt",
            "reviewRunId",
            "reviewSha256",
            "reviewSelectionSha256",
            "custodyArtifactId",
            "custodyArtifactName",
            "custodyRunAttempt",
            "custodyRunId",
            "custodySha256",
            "custodySelectionSha256",
            "primaryScrubArtifactId",
            "primaryScrubArtifactName",
            "primaryScrubRunAttempt",
            "primaryScrubRunId",
            "primaryScrubSha256",
            "primaryScrubSelectionSha256",
            "secondaryScrubArtifactId",
            "secondaryScrubArtifactName",
            "secondaryScrubRunAttempt",
            "secondaryScrubRunId",
            "secondaryScrubSha256",
            "secondaryScrubSelectionSha256",
        ],
    )?;
    for field in [
        "evidenceArtifactId",
        "evidenceRunAttempt",
        "evidenceRunId",
        "reviewArtifactId",
        "reviewRunAttempt",
        "reviewRunId",
        "custodyArtifactId",
        "custodyRunAttempt",
        "custodyRunId",
        "primaryScrubArtifactId",
        "primaryScrubRunAttempt",
        "primaryScrubRunId",
        "secondaryScrubArtifactId",
        "secondaryScrubRunAttempt",
        "secondaryScrubRunId",
    ] {
        if json_member(source, field)?.number()? == 0 {
            return Err(format!("promotion source identity {field} must be nonzero"));
        }
    }
    if json_member(source, "evidenceArtifactName")?.string()? != "native-oracle-merged"
        || json_member(source, "reviewArtifactName")?.string()?
            != "promotion-final-reviewed-evidence"
        || json_member(source, "custodyArtifactName")?.string()? != "promotion-custody-evidence"
        || json_member(source, "primaryScrubArtifactName")?.string()?
            != format!(
                "ephemeralEvidence-current-scrub-primary-worm-{}-{}",
                json_member(source, "primaryScrubRunId")?.number()?,
                json_member(source, "primaryScrubRunAttempt")?.number()?
            )
        || json_member(source, "secondaryScrubArtifactName")?.string()?
            != format!(
                "ephemeralEvidence-current-scrub-secondary-worm-{}-{}",
                json_member(source, "secondaryScrubRunId")?.number()?,
                json_member(source, "secondaryScrubRunAttempt")?.number()?
            )
        || json_member(source, "evidenceSha256")?.string()? != merged_sha256
    {
        return Err(
            "promotion source identity does not bind the retained evidence artifact".to_owned(),
        );
    }
    require_digest(
        json_member(source, "reviewSha256")?.string()?,
        "promotion reviewed evidence package",
    )?;
    require_digest(
        json_member(source, "custodySha256")?.string()?,
        "promotion custody evidence package",
    )?;
    require_digest(
        json_member(source, "evidencePackageSha256")?.string()?,
        "promotion native evidence package",
    )?;
    require_digest(
        json_member(source, "primaryScrubSha256")?.string()?,
        "promotion primary scrub package",
    )?;
    require_digest(
        json_member(source, "secondaryScrubSha256")?.string()?,
        "promotion secondary scrub package",
    )?;
    Ok(())
}

fn verify_proposal_source_selection_records(
    proposal: &BTreeMap<String, JsonValue>,
    source: &BTreeMap<String, JsonValue>,
    retained_input: &Path,
) -> Result<(), String> {
    for selection_spec in PROPOSAL_SOURCE_SELECTIONS {
        let directory = retained_input
            .join("evidence")
            .join("source-selection")
            .join("proposal")
            .join(selection_spec.label);
        let selection = directory.join("selection.json");
        verify_file_digest(
            &selection,
            json_member(source, selection_spec.digest_field)?.string()?,
            selection_spec.digest_field,
        )?;
        let workflow = selection_spec
            .workflow_components
            .iter()
            .collect::<PathBuf>();
        let artifact = match selection_spec.prefix {
            "primaryScrub" => format!(
                "ephemeralEvidence-current-scrub-primary-worm-{}-{}",
                source_identity_number(source, "primaryScrub", "RunId")?,
                source_identity_number(source, "primaryScrub", "RunAttempt")?
            ),
            "secondaryScrub" => format!(
                "ephemeralEvidence-current-scrub-secondary-worm-{}-{}",
                source_identity_number(source, "secondaryScrub", "RunId")?,
                source_identity_number(source, "secondaryScrub", "RunAttempt")?
            ),
            _ => selection_spec.artifact.to_owned(),
        };
        verify_retained_proposal_selection(
            &directory,
            &selection,
            source,
            selection_spec.prefix,
            &artifact,
            &workflow,
            selection_spec.event,
            json_member(proposal, "candidateSourceCommit")?.string()?,
        )?;
    }
    Ok(())
}

struct ProposalSourceSelection {
    label: &'static str,
    digest_field: &'static str,
    prefix: &'static str,
    artifact: &'static str,
    workflow_components: &'static [&'static str],
    event: &'static str,
}

