#[allow(clippy::too_many_arguments)]
fn verify_retained_proposal_selection(
    directory: &Path,
    selection_path: &Path,
    source: &BTreeMap<String, JsonValue>,
    prefix: &str,
    artifact_name: &str,
    workflow: &Path,
    event: &str,
    candidate: &str,
) -> Result<(), String> {
    let workflow_identity = path_text(workflow)?;
    let document = parse_json(&read_text(selection_path)?)?;
    let selection = document.object()?;
    exact_keys(selection, PROVIDER_SELECTION_KEYS)?;
    let run_id = source_identity_number(source, prefix, "RunId")?;
    let run_attempt = source_identity_number(source, prefix, "RunAttempt")?;
    let artifact_id = source_identity_number(source, prefix, "ArtifactId")?;
    let package_field = match prefix {
        "evidence" => "evidencePackageSha256",
        "review" => "reviewSha256",
        "custody" => "custodySha256",
        "primaryScrub" => "primaryScrubSha256",
        "secondaryScrub" => "secondaryScrubSha256",
        _ => return Err("proposal provider selection prefix is unknown".to_owned()),
    };
    verify_retained_workflow_digest(
        json_member(selection, "workflowBlobSha256")?.string()?,
        &record_digest(&repository_root()?.join(workflow))?,
    )?;
    if json_member(selection, "schemaVersion")?.number()? != 1
        || json_member(selection, "selectionState")?.string()? != "exact-provider-object"
        || json_member(selection, "artifact")?.string()? != artifact_name
        || json_member(selection, "workflowPath")?.string()? != workflow_identity
        || json_member(selection, "event")?.string()? != event
        || json_member(selection, "providerRunId")?.number()? != run_id
        || json_member(selection, "providerRunAttempt")?.number()? != run_attempt
        || json_member(selection, "providerArtifactId")?.number()? != artifact_id
        || json_member(selection, "candidateCommit")?.string()? != candidate
        || json_member(selection, "directorySha256")?.string()?
            != json_member(source, package_field)?.string()?
    {
        return Err("retained proposal provider selection identity is invalid".to_owned());
    }
    verify_retained_proposal_provider_api(directory, selection, artifact_name, candidate)
}

fn verify_retained_workflow_digest(retained: &str, current: &str) -> Result<(), String> {
    require_digest(retained, "retained workflow")?;
    require_digest(current, "current workflow")?;
    if retained == current
        || crate::assurance_control_mutant_active("post-collection-workflow-change")
    {
        Ok(())
    } else {
        Err("workflow changed after evidence collection".to_owned())
    }
}

fn source_identity_number(
    source: &BTreeMap<String, JsonValue>,
    prefix: &str,
    suffix: &str,
) -> Result<u64, String> {
    let mut field = prefix.to_owned();
    field.push_str(suffix);
    json_member(source, &field)?.number()
}

fn verify_retained_proposal_provider_api(
    directory: &Path,
    selection: &BTreeMap<String, JsonValue>,
    artifact_name: &str,
    candidate: &str,
) -> Result<(), String> {
    let artifact_path = directory.join("provider-selected-artifact.json");
    let run_path = directory.join("provider-selected-run.json");
    if json_member(selection, "providerArtifactApiPath")?.string()?
        != "provider-selected-artifact.json"
        || json_member(selection, "providerRunApiPath")?.string()? != "provider-selected-run.json"
        || json_member(selection, "providerArtifactId")?.number()? == 0
        || json_member(selection, "providerRunId")?.number()? == 0
        || json_member(selection, "providerRunAttempt")?.number()? == 0
        || json_member(selection, "providerArchiveSize")?.number()? == 0
        || !json_member(selection, "providerArchiveUrl")?
            .string()?
            .starts_with("https://api.github.com/repos/Portfoligno/hell-rs/actions/artifacts/")
    {
        return Err("historical provider selector metadata is invalid".to_owned());
    }
    validate_utc_timestamp(json_member(selection, "providerCreatedAt")?.string()?)?;
    validate_utc_timestamp(json_member(selection, "providerExpiresAt")?.string()?)?;
    if utc_timestamp_seconds(json_member(selection, "providerCreatedAt")?.string()?)?
        >= utc_timestamp_seconds(json_member(selection, "providerExpiresAt")?.string()?)?
    {
        return Err("historical provider retention interval is invalid".to_owned());
    }
    for (path, path_field, digest_field, expected) in [
        (
            &artifact_path,
            "providerArtifactApiPath",
            "providerArtifactApiSha256",
            "provider-selected-artifact.json",
        ),
        (
            &run_path,
            "providerRunApiPath",
            "providerRunApiSha256",
            "provider-selected-run.json",
        ),
    ] {
        if json_member(selection, path_field)?.string()? != expected {
            return Err("proposal provider API path is not canonical".to_owned());
        }
        verify_file_digest(
            path,
            json_member(selection, digest_field)?.string()?,
            path_field,
        )?;
    }
    let artifact_document = parse_json(&read_text(&artifact_path)?)?;
    let artifact = artifact_document.object()?;
    let run_id = json_member(selection, "providerRunId")?.number()?;
    if verify_final_review_artifact(artifact, artifact_name, run_id)?
        != json_member(selection, "providerArtifactId")?.number()?
        || json_member(artifact, "digest")?
            .string()?
            .strip_prefix("sha256:")
            != Some(json_member(selection, "providerArchiveSha256")?.string()?)
        || json_member(artifact, "size_in_bytes")?.number()?
            != json_member(selection, "providerArchiveSize")?.number()?
        || json_member(artifact, "created_at")?.string()?
            != json_member(selection, "providerCreatedAt")?.string()?
        || json_member(artifact, "expires_at")?.string()?
            != json_member(selection, "providerExpiresAt")?.string()?
        || json_member(artifact, "archive_download_url")?.string()?
            != json_member(selection, "providerArchiveUrl")?.string()?
    {
        return Err("proposal provider artifact API facts changed identity".to_owned());
    }
    let run_document = parse_json(&read_text(&run_path)?)?;
    let run = run_document.object()?;
    let repository = json_member(run, "repository")?.object()?;
    let expected_repository_id = provider_selection_repository_identity()?.1;
    verify_provider_run_attempt(
        json_member(selection, "providerRunAttempt")?.number()?,
        json_member(run, "run_attempt")?.number()?,
    )?;
    verify_provider_repository(
        &expected_repository_id,
        json_member(selection, "repositoryId")?.string()?,
    )?;
    if json_member(run, "id")?.number()? != run_id
        || json_member(run, "head_sha")?.string()? != candidate
        || provider_run_workflow_ref(
            json_member(run, "path")?.string()?,
            json_member(selection, "workflowPath")?.string()?,
        )
        .is_err()
        || json_member(run, "event")?.string()? != json_member(selection, "event")?.string()?
        || json_member(repository, "full_name")?.string()? != "Portfoligno/hell-rs"
        || json_member(repository, "id")?.number()?.to_string()
            != json_member(selection, "repositoryId")?.string()?
    {
        return Err("proposal provider run API facts changed identity".to_owned());
    }
    Ok(())
}

fn verify_proposal_approval(
    proposal: &BTreeMap<String, JsonValue>,
    proposal_digest: &str,
    candidate: &str,
    epoch: &str,
    approval_path: &Path,
    allowed_signers: &Path,
) -> Result<(VerifiedReview, String), String> {
    let directory = approval_path
        .parent()
        .ok_or_else(|| "proposal approval has no package directory".to_owned())?;
    let dynamic_policy = review_policy_for_envelope(approval_path, allowed_signers)?;
    let approval = verify_review_envelope(approval_path, &dynamic_policy)?;
    let selection_digest = record_digest(&directory.join("proposal-provider-selection.json"))?;
    let proposal_path = directory.join("promotion-proposal.json");
    let subject_path = directory.join("promotion-approval-subject.json");
    verify_promotion_approval_subject(&subject_path, &proposal_path, candidate, epoch)?;
    let (account_id, _, _, _, _) = verify_review_authorization(
        &directory.join("authorization.json"),
        "promotion-approver",
        candidate,
        &subject_path,
    )?;
    validate_proposal_approval(
        proposal,
        proposal_digest,
        &selection_digest,
        candidate,
        epoch,
        &approval,
    )?;
    Ok((approval, account_id.to_string()))
}

fn validate_proposal_approval(
    proposal: &BTreeMap<String, JsonValue>,
    proposal_digest: &str,
    provider_selection_digest: &str,
    candidate: &str,
    epoch: &str,
    approval: &VerifiedReview,
) -> Result<(), String> {
    require_digest(provider_selection_digest, "proposal provider selection")?;
    let mut required = proposal_review_artifacts(proposal, proposal_digest)?;
    if !required.insert(provider_selection_digest.to_owned()) {
        return Err("proposal provider selection duplicates another reviewed artifact".to_owned());
    }
    if approval.role != "promotion-approver"
        || approval.candidate_commit != candidate
        || approval.assurance_epoch != epoch
        || approval.reviewed_artifacts != required
    {
        return Err(
            "promotion approval does not bind the exact proposal and every retained component"
                .to_owned(),
        );
    }
    Ok(())
}

fn parse(arguments: &[OsString]) -> Result<(String, Options), String> {
    let command = utf8(arguments.first(), "command")?.to_owned();
    let mut options = Options::default();
    let mut index = 1;
    if let Some(value) = arguments.get(index).and_then(|value| value.to_str())
        && !value.starts_with("--")
    {
        options.action = Some(value.to_owned());
        index += 1;
    }
    while index < arguments.len() {
        let flag = utf8(arguments.get(index), "option")?;
        index += 1;
        if flag == "--github-dispatch-inputs" {
            options.github_dispatch_inputs = true;
            continue;
        }
        let value = arguments
            .get(index)
            .ok_or_else(|| format!("{flag} requires a value"))?;
        index += 1;
        match flag {
            "--input" | "--packet" => options.input = Some(PathBuf::from(value)),
            "--output" | "--report" => options.output = Some(PathBuf::from(value)),
            "--policy" => options.policy = Some(PathBuf::from(value)),
            "--expected" => options.expected = Some(utf8(Some(value), flag)?.to_owned()),
            "--from" => options.from = Some(PathBuf::from(value)),
            "--to" => options.to = Some(PathBuf::from(value)),
            "--proposal" => options.proposal = Some(PathBuf::from(value)),
            "--expect-source" => {
                options.expect_source = Some(utf8(Some(value), flag)?.to_owned());
            }
            "--expect-epoch" => {
                options.expect_epoch = Some(utf8(Some(value), flag)?.to_owned());
            }
            "--expect-proposal" => {
                options.expect_proposal = Some(utf8(Some(value), flag)?.to_owned());
            }
            "--artifact" => options.artifact = Some(utf8(Some(value), flag)?.to_owned()),
            "--platform" => options.platform = Some(utf8(Some(value), flag)?.to_owned()),
            "--role" => options.role = Some(utf8(Some(value), flag)?.to_owned()),
            "--decision" => options.decision = Some(utf8(Some(value), flag)?.to_owned()),
            "--findings" => options.findings = Some(PathBuf::from(value)),
            "--issue" => options.issue = Some(utf8(Some(value), flag)?.to_owned()),
            "--category" => options.category = Some(utf8(Some(value), flag)?.to_owned()),
            "--program" => options.program = Some(PathBuf::from(value)),
            _ => return Err(format!("unknown assurance option {flag:?}")),
        }
    }
    Ok((command, options))
}

fn utf8<'a>(value: Option<&'a OsString>, label: &str) -> Result<&'a str, String> {
    value
        .and_then(|value| value.to_str())
        .ok_or_else(|| format!("{label} must be UTF-8"))
}

fn dispatch(root: &Path, command: &str, options: &Options) -> Result<String, String> {
    match command {
        "assurance-verify" => {
            verify_repository(root)?;
            crate::catalog_lock::verify_repository_locks(root)?;
            if let Some(output) = &options.output {
                write_atomic(output, assurance_report(true, &[]).as_bytes())?;
            }
            Ok("promotion assurance policy is structurally valid and fail-closed".to_owned())
        }
        "catalog-lock" => match options.action.as_deref().unwrap_or("verify") {
            "write" => {
                crate::catalog_lock::write_repository_locks(root)?;
                Ok("wrote deterministic assurance catalog and source-input locks".to_owned())
            }
            "verify" => {
                crate::catalog_lock::verify_repository_locks(root)?;
                Ok("verified deterministic assurance catalog and source-input locks".to_owned())
            }
            action => Err(format!("unknown catalog-lock action {action:?}")),
        },
        "evidence-epoch" => epoch_command(root, options),
        "applicability" => applicability_command(options),
        "case-catalog" => case_catalog_command(options),
        "case-coverage" => case_coverage_command(root, options),
        "normalizer-audit" => normalizer_audit_command(root, options),
        "residual-risk" => residual_risk_command(root, options),
        "mutation" => retained_report_command(root, options, "mutation"),
        "divergence-verify" => divergence_command(root, options),
        "divergence-propose" => divergence_propose(options),
        "divergence-prototype" => divergence_prototype_command(root, options),
        "artifact-acquire" => artifact_acquire(root, options),
        "artifact-verify" => artifact_verify(root, options),
        "oracle-provenance" => oracle_provenance(root, options),
        "custody" => custody_command(options),
        "review-packet" => review_packet(root, options),
        "review-sign" => review_sign(options),
        "review-verify" => review_verify(options),
        "review-bind" => review_bind(root, options),
        "review-assemble" => review_assemble(root, options),
        "review-authorization" => review_authorization(root, options),
        "review-findings" => review_findings_command(root, options),
        "review-graph" => review_graph_command(root, options),
        "auth-transport-probe" => auth_transport_probe(root, options),
        "promotion-proposal" => promotion_proposal(root, options),
        "promotion-approval-subject" => promotion_approval_subject(root, options),
        "compatibility-report" => compatibility_report(root, options),
        "fuzz-corpus" => semantic_fuzz_corpus(root, options),
        "regression-import" => regression_import(root, options),
        _ => Err(format!("unsupported assurance command {command:?}")),
    }
}

fn semantic_fuzz_corpus(root: &Path, options: &Options) -> Result<String, String> {
    let source = required_path(
        &options.input,
        "fuzz-corpus requires --input committed corpus directory",
    )?;
    let expected_source = root.join("crates/hell-ci/fuzz/corpus");
    let source = fs::canonicalize(source)
        .map_err(|error| format!("cannot resolve committed fuzz corpus: {error}"))?;
    let expected_source = fs::canonicalize(expected_source)
        .map_err(|error| format!("cannot resolve reviewed fuzz corpus: {error}"))?;
    if source != expected_source {
        return Err("fuzz-corpus input is not the exact committed semantic corpus".to_owned());
    }
    match options.action.as_deref() {
        Some("prepare") => {
            let output = required_path(
                &options.output,
                "fuzz-corpus prepare requires --output writable corpus directory",
            )?;
            let artifacts = required_path(
                &options.to,
                "fuzz-corpus prepare requires --to crash artifact directory",
            )?;
            let output = if output.is_absolute() {
                output.to_path_buf()
            } else {
                root.join(output)
            };
            let artifacts = if artifacts.is_absolute() {
                artifacts.to_path_buf()
            } else {
                root.join(artifacts)
            };
            if output != root.join("ci-out/fuzz-corpora")
                || artifacts != root.join("ci-out/fuzz-artifacts")
            {
                return Err("fuzz-corpus outputs are not the exact isolated CI paths".to_owned());
            }
            fs::create_dir_all(root.join("ci-out"))
                .map_err(|error| format!("cannot create fuzz campaign output root: {error}"))?;
            copy_record_tree(&source, &output)?;
            fs::create_dir(&artifacts)
                .map_err(|error| format!("cannot create fuzz artifact root: {error}"))?;
            for target in SEMANTIC_FUZZ_TARGETS {
                if !output.join(target).is_dir() {
                    return Err(format!("committed fuzz corpus lacks target {target}"));
                }
                fs::create_dir(artifacts.join(target)).map_err(|error| {
                    format!("cannot create fuzz artifact directory for {target}: {error}")
                })?;
            }
            Ok("copied reviewed fuzz seeds into isolated writable campaign directories".to_owned())
        }
        Some("verify-clean") => {
            let status = git_output(
                root,
                &[
                    "status",
                    "--porcelain=v1",
                    "--untracked-files=all",
                    "--",
                    ".",
                    ":(exclude)ci-out",
                ],
            )?;
            status.is_empty().then_some(()).ok_or_else(|| {
                "coverage-guided campaign modified the clean candidate checkout".to_owned()
            })?;
            Ok("verified coverage-guided campaigns left committed fuzz seeds unchanged".to_owned())
        }
        action => Err(format!("unknown fuzz-corpus action {action:?}")),
    }
}

fn verify_repository(root: &Path) -> Result<(), String> {
    let assurance_policy = load_assurance_policy(root)?;
    let acquisition_policy = load_acquisition_policy(root)?;
    verify_configuration_file_shapes(root)?;
    verify_mutant_catalog(root)?;
    verify_committed_claim_defaults()?;
    verify_cross_catalog_policies(root, &assurance_policy, &acquisition_policy)?;
    validate_allowed_signers_policy(&root.join("compat").join("reviews.allowed_signers"))?;
    validate_evidence_catalog(&committed_differential_cases())?;
    Ok(())
}

fn verify_configuration_file_shapes(root: &Path) -> Result<(), String> {
    for components in CONFIG_PATHS {
        let relative = components.iter().collect::<PathBuf>();
        let path = repository_relative_path(root, &path_text(&relative)?)?;
        let bytes =
            fs::read(&path).map_err(|error| format!("cannot read {}: {error}", path.display()))?;
        if bytes.last() != Some(&b'\n') {
            return Err(format!("{} lacks a trailing newline", path.display()));
        }
        let document =
            std::str::from_utf8(&bytes).map_err(|_| format!("{} is not UTF-8", path.display()))?;
        require_assignment(document, "schema_version", "1").or_else(|error| {
            if matches!(
                components,
                [
                    "compat",
                    "assurance-policy.toml"
                        | "corpus-obligations.toml"
                        | "divergences.toml"
                        | "mutants.toml"
                        | "promotion-policy.toml",
                ] | ["compat", "claims", "2026-05-29.toml"]
            ) {
                require_assignment(document, "schema_version", "2")
            } else {
                Err(error)
            }
        })?;
    }
    let promotion = crate::promotion_policy::load(root)?;
    if promotion.required_records != crate::promotion_policy::REQUIRED_RECORDS
        || promotion.required_blockers != crate::promotion_policy::REQUIRED_BLOCKERS
    {
        return Err("promotion policy assurance record sets drifted".to_owned());
    }
    Ok(())
}

fn verify_mutant_catalog(root: &Path) -> Result<(), String> {
    let mutants = read_text(&root.join("compat").join("mutants.toml"))?;
    require_assignment(&mutants, "state", "\"required\"")?;
    require_assignment(
        &mutants,
        "execution_strategy",
        "\"baseline-pass-mutant-fail\"",
    )?;
    let mutant_ids = assignment_string_array(&mutants, "ids")?;
    let mutant_families = assignment_string_array(&mutants, "families")?;
    let mutant_tests = assignment_string_array(&mutants, "tests")?;
    let mutant_packages = assignment_string_array(&mutants, "packages")?;
    let mutant_targets = assignment_string_array(&mutants, "targets")?;
    let mutant_sites = assignment_string_array(&mutants, "mutation_sites")?;
    let mutant_obligations = assignment_string_array(&mutants, "obligation_ids")?;
    let mutant_claim_groups = assignment_string_array(&mutants, "claim_group_ids")?;
    let mutant_classes = assignment_string_array(&mutants, "classes")?;
    let mutant_criticalities = assignment_string_array(&mutants, "criticalities")?;
    if mutant_ids.len() != mutant_families.len()
        || mutant_ids.len() != mutant_tests.len()
        || mutant_ids.len() != mutant_packages.len()
        || mutant_ids.len() != mutant_targets.len()
        || mutant_ids.len() != mutant_sites.len()
        || mutant_ids.len() != mutant_obligations.len()
        || mutant_ids.len() != mutant_claim_groups.len()
        || mutant_ids.len() != mutant_classes.len()
        || mutant_ids.len() != mutant_criticalities.len()
        || mutant_ids.len() < 31
        || mutant_tests.iter().collect::<BTreeSet<_>>().len() != mutant_tests.len()
        || mutant_packages.iter().any(|package| {
            !matches!(
                package.as_str(),
                "hell-ci" | "hell-runtime" | "hell-testkit"
            )
        })
    {
        return Err("assurance mutant catalog is incomplete".to_owned());
    }
    Ok(())
}

fn verify_committed_claim_defaults() -> Result<(), String> {
    let claims = hell_builtins::compatibility_claims();
    hell_builtins::validate_compatibility_claims(claims)
        .map_err(|error| format!("generated claim catalog is invalid: {error:?}"))?;
    if claims
        .iter()
        .flat_map(|claim| &claim.dimensions)
        .any(|claim| {
            claim
                .scopes
                .iter()
                .any(|scope| scope.status != hell_builtins::ClaimStatus::Unverified)
        })
    {
        return Err("committed compatibility claims must remain unverified".to_owned());
    }
    Ok(())
}

fn verify_cross_catalog_policies(
    root: &Path,
    assurance_policy: &AssurancePolicy,
    acquisition_policy: &AcquisitionPolicy,
) -> Result<(), String> {
    let acquisition = read_text(&root.join("compat").join("acquisition-sources.toml"))?;
    require_assignment(
        &acquisition,
        "minimum_trust_domains",
        &acquisition_policy.minimum_trust_domains.to_string(),
    )?;
    if acquisition_policy.minimum_trust_domains != assurance_policy.minimum_trust_domains {
        return Err("assurance and acquisition trust-domain minima disagree".to_owned());
    }
    let custody = read_text(&root.join("compat").join("custody-policy.toml"))?;
    require_assignment(
        &custody,
        "minimum_copies",
        &assurance_policy.minimum_custody_copies.to_string(),
    )?;
    require_assignment(&custody, "require_independent_retrieval", "true")?;
    let review = load_review_policy(root)?;
    if review.minimum_distinct_people < 2 {
        return Err("review policy weakens distinct-person independence".to_owned());
    }
    let normalizers = read_text(&root.join("compat").join("normalizers.toml"))?;
    require_assignment(&normalizers, "typed_only", "true")?;
    require_assignment(&normalizers, "exact_claims_allow_normalizers", "false")?;
    Ok(())
}

struct AssurancePolicy {
    minimum_trust_domains: u64,
    minimum_custody_copies: u64,
    require_current_scrub: bool,
    residual: ResidualTierPolicy,
}

#[derive(Clone, Debug)]
struct ResidualTierPolicy {
    acceptable_tiers: BTreeSet<String>,
    minimum_full_mutation_score_per_mille: u64,
    required_platform_count: usize,
}

struct AcquisitionPolicy {
    repository: String,
    repository_id: Option<String>,
    workflow: String,
    minimum_acquisitions: u64,
    minimum_trust_domains: u64,
    required_channel_classes: Vec<String>,
}

struct ReviewPolicy {
    minimum_distinct_people: u64,
    claim_reviewer_may_not_be_evidence_run_actor: PolicyToggle,
    platform_reviewer_may_not_be_oracle_build_trigger: PolicyToggle,
    promotion_approver_may_not_be_claim_proposer: PolicyToggle,
    promotion_approver_may_not_be_candidate_commit_author: PolicyToggle,
    require_external_or_separate_team_for_artifact_authenticity: PolicyToggle,
    text_limits: ReviewTextLimits,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PolicyToggle {
    Required,
    Permitted,
}

impl PolicyToggle {
    fn from_bool(value: bool) -> Self {
        if value {
            Self::Required
        } else {
            Self::Permitted
        }
    }

    fn required(self) -> bool {
        self == Self::Required
    }
}

fn load_review_policy(root: &Path) -> Result<ReviewPolicy, String> {
    let document = read_text(&root.join("compat").join("review-policy.toml"))?;
    let mut values = crate::strict_toml::assignments(&document)?;
    let schema =
        crate::strict_toml::unsigned(&crate::strict_toml::take(&mut values, "schema_version")?)?;
    let state = crate::strict_toml::string(&crate::strict_toml::take(&mut values, "state")?)?;
    let mut team = |key: &str| -> Result<String, String> {
        let value = crate::strict_toml::string(&crate::strict_toml::take(&mut values, key)?)?;
        let (organization, slug) = value
            .split_once('/')
            .ok_or_else(|| format!("review policy {key} is not an organization/team"))?;
        validate_provider_atom(organization, "review policy organization")?;
        validate_provider_atom(slug, "review policy team")?;
        Ok(value)
    };
    team("claim_reviewer_team")?;
    team("claim_author_team")?;
    team("platform_reviewer_team")?;
    team("security_reviewer_team")?;
    team("implementation_reviewer_team")?;
    team("product_reviewer_team")?;
    team("promotion_approver_team")?;
    let minimum_distinct_people = crate::strict_toml::unsigned(&crate::strict_toml::take(
        &mut values,
        "minimum_distinct_people",
    )?)?;
    let bounded = |values: &mut BTreeMap<String, String>, key: &str| -> Result<usize, String> {
        usize::try_from(crate::strict_toml::unsigned(&crate::strict_toml::take(
            values, key,
        )?)?)
        .map_err(|_| format!("review policy {key} exceeds the host size limit"))
    };
    let text_limits = ReviewTextLimits {
        rationale_minimum: bounded(&mut values, "minimum_review_rationale_bytes")?,
        rationale_maximum: bounded(&mut values, "maximum_review_rationale_bytes")?,
        finding_statement_maximum: bounded(&mut values, "maximum_review_finding_statement_bytes")?,
        issue_reference_maximum: bounded(&mut values, "maximum_review_issue_reference_bytes")?,
    };
    let claim_reviewer_may_not_be_evidence_run_actor =
        PolicyToggle::from_bool(crate::strict_toml::boolean(&crate::strict_toml::take(
            &mut values,
            "claim_reviewer_may_not_be_evidence_run_actor",
        )?)?);
    let platform_reviewer_may_not_be_oracle_build_trigger =
        PolicyToggle::from_bool(crate::strict_toml::boolean(&crate::strict_toml::take(
            &mut values,
            "platform_reviewer_may_not_be_oracle_build_trigger",
        )?)?);
    let promotion_approver_may_not_be_claim_proposer =
        PolicyToggle::from_bool(crate::strict_toml::boolean(&crate::strict_toml::take(
            &mut values,
            "promotion_approver_may_not_be_claim_proposer",
        )?)?);
    let promotion_approver_may_not_be_candidate_commit_author =
        PolicyToggle::from_bool(crate::strict_toml::boolean(&crate::strict_toml::take(
            &mut values,
            "promotion_approver_may_not_be_candidate_commit_author",
        )?)?);
    let require_external_or_separate_team_for_artifact_authenticity =
        PolicyToggle::from_bool(crate::strict_toml::boolean(&crate::strict_toml::take(
            &mut values,
            "require_external_or_separate_team_for_artifact_authenticity",
        )?)?);
    let signatures = crate::strict_toml::string_array(&crate::strict_toml::take(
        &mut values,
        "required_signature_types",
    )?)?;
    crate::strict_toml::finish(&values)?;
    if schema != 1
        || state != "review-required"
        || minimum_distinct_people < 2
        || signatures != ["sigstore", "ssh"]
        || text_limits.rationale_minimum == 0
        || text_limits.rationale_minimum > text_limits.rationale_maximum
        || text_limits.finding_statement_maximum == 0
        || text_limits.issue_reference_maximum == 0
    {
        return Err("review policy is incomplete or unsupported".to_owned());
    }
    Ok(ReviewPolicy {
        minimum_distinct_people,
        claim_reviewer_may_not_be_evidence_run_actor,
        platform_reviewer_may_not_be_oracle_build_trigger,
        promotion_approver_may_not_be_claim_proposer,
        promotion_approver_may_not_be_candidate_commit_author,
        require_external_or_separate_team_for_artifact_authenticity,
        text_limits,
    })
}

fn load_acquisition_policy(root: &Path) -> Result<AcquisitionPolicy, String> {
    let document = read_text(&root.join("compat").join("acquisition-sources.toml"))?;
    let mut values = crate::strict_toml::assignments(&document)?;
    let schema =
        crate::strict_toml::unsigned(&crate::strict_toml::take(&mut values, "schema_version")?)?;
    let state = crate::strict_toml::string(&crate::strict_toml::take(&mut values, "state")?)?;
    let repository =
        crate::strict_toml::string(&crate::strict_toml::take(&mut values, "repository")?)?;
    let repository_id =
        crate::strict_toml::string(&crate::strict_toml::take(&mut values, "repository_id")?)?;
    let workflow = crate::strict_toml::string(&crate::strict_toml::take(&mut values, "workflow")?)?;
    let minimum_acquisitions = crate::strict_toml::unsigned(&crate::strict_toml::take(
        &mut values,
        "minimum_acquisitions",
    )?)?;
    let minimum_trust_domains = crate::strict_toml::unsigned(&crate::strict_toml::take(
        &mut values,
        "minimum_trust_domains",
    )?)?;
    let required_channel_classes = crate::strict_toml::string_array(&crate::strict_toml::take(
        &mut values,
        "required_channel_classes",
    )?)?;
    for key in [
        "require_workflow_identity",
        "require_candidate_commit",
        "require_public_attestation_when_available",
    ] {
        if !crate::strict_toml::boolean(&crate::strict_toml::take(&mut values, key)?)? {
            return Err(format!("acquisition source policy disables {key}"));
        }
    }
    crate::strict_toml::finish(&values)?;
    if schema != 1
        || state != "review-required"
        || repository != "Portfoligno/hell-rs"
        || workflow != ".github/workflows/nightly.yml"
        || minimum_acquisitions < 2
        || minimum_trust_domains < 2
        || required_channel_classes != ["github-actions-api", "external-versioned-object"]
    {
        return Err("acquisition source policy is incomplete or unsupported".to_owned());
    }
    if repository_id != "1327351238" {
        return Err("acquisition source policy repository ID is not pinned".to_owned());
    }
    let repository_id = Some(repository_id);
    Ok(AcquisitionPolicy {
        repository,
        repository_id,
        workflow,
        minimum_acquisitions,
        minimum_trust_domains,
        required_channel_classes,
    })
}

fn load_assurance_policy(root: &Path) -> Result<AssurancePolicy, String> {
    let document = read_text(&root.join("compat").join("assurance-policy.toml"))?;
    let mut values = crate::strict_toml::assignments(&document)?;
    let schema =
        crate::strict_toml::unsigned(&crate::strict_toml::take(&mut values, "schema_version")?)?;
    let baseline = crate::strict_toml::string(&crate::strict_toml::take(&mut values, "baseline")?)?;
    let profiles = crate::strict_toml::string_array(&crate::strict_toml::take(
        &mut values,
        "required_profiles",
    )?)?;
    let platforms = crate::strict_toml::string_array(&crate::strict_toml::take(
        &mut values,
        "required_platforms",
    )?)?;
    let dimensions = crate::strict_toml::string_array(&crate::strict_toml::take(
        &mut values,
        "required_dimensions",
    )?)?;
    if schema != 2
        || baseline != hell_builtins::assurance_catalogs::CLAIM_BASELINE
        || profiles != ["upstream"]
        || platforms != ["linux-amd64", "macos-arm64", "windows-amd64"]
        || dimensions
            != CompatibilityDimension::ALL
                .iter()
                .map(|dimension| dimension.as_str().to_owned())
                .collect::<Vec<_>>()
    {
        return Err("authoritative assurance policy scope is unsupported".to_owned());
    }
    let minimum_trust_domains = crate::strict_toml::unsigned(&crate::strict_toml::take(
        &mut values,
        "minimum_trust_domains",
    )?)?;
    let minimum_custody_copies = crate::strict_toml::unsigned(&crate::strict_toml::take(
        &mut values,
        "minimum_custody_copies",
    )?)?;
    let residual = load_residual_tier_policy(&mut values)?;
    let mut requirement = |key: &str| -> Result<bool, String> {
        let enabled = crate::strict_toml::boolean(&crate::strict_toml::take(&mut values, key)?)?;
        if !enabled {
            return Err(format!("authoritative assurance policy disables {key}"));
        }
        Ok(enabled)
    };
    for key in [
        "require_signed_review",
        "require_sbom",
        "require_network_inventory",
        "require_independent_rebuild",
        "require_exercised_binary_binding",
        "require_all_mandatory_obligations",
        "require_critical_mutants",
        "require_independent_retrieval",
    ] {
        requirement(key)?;
    }
    let require_current_scrub = requirement("require_current_scrub")?;
    requirement("require_separation_of_duties")?;
    crate::strict_toml::finish(&values)?;
    if minimum_trust_domains < 2 || minimum_custody_copies < 2 {
        return Err("authoritative assurance policy weakens independent evidence".to_owned());
    }
    Ok(AssurancePolicy {
        minimum_trust_domains,
        minimum_custody_copies,
        require_current_scrub,
        residual,
    })
}

fn load_residual_tier_policy(
    values: &mut BTreeMap<String, String>,
) -> Result<ResidualTierPolicy, String> {
    let acceptable_tiers = crate::strict_toml::string_array(&crate::strict_toml::take(
        values,
        "residual_acceptable_tiers",
    )?)?
    .into_iter()
    .collect::<BTreeSet<_>>();
    let minimum_full_mutation_score_per_mille = crate::strict_toml::unsigned(
        &crate::strict_toml::take(values, "residual_minimum_full_mutation_score_per_mille")?,
    )?;
    let required_platform_count = usize::try_from(crate::strict_toml::unsigned(
        &crate::strict_toml::take(values, "residual_required_platform_count")?,
    )?)
    .map_err(|_| "residual required platform count exceeds usize")?;
    for key in [
        "residual_unacceptable_on_missing_boundaries",
        "residual_unacceptable_on_missing_obligations",
        "residual_unacceptable_on_unacceptable_claim_groups",
        "residual_unacceptable_on_undetected_critical_mutants",
        "residual_unacceptable_on_unverified_claim_cells",
        "residual_unacceptable_on_stale_evidence",
        "residual_unacceptable_on_incomplete_platforms",
        "residual_high_on_critical_non_exact_claims",
        "residual_high_on_platform_dependent_claims",
        "residual_high_on_deliberate_divergences",
        "residual_moderate_on_out_of_scope_claims",
        "residual_moderate_on_normalized_claims",
        "residual_moderate_on_weak_mutation_family",
        "residual_moderate_on_aging_evidence",
        "residual_moderate_on_pending_custody",
    ] {
        if !crate::strict_toml::boolean(&crate::strict_toml::take(values, key)?)? {
            return Err(format!("authoritative assurance policy disables {key}"));
        }
    }
    if acceptable_tiers
        != BTreeSet::from(["high".to_owned(), "low".to_owned(), "moderate".to_owned()])
        || minimum_full_mutation_score_per_mille != 1_000
        || required_platform_count != REQUIRED_CLAIM_PLATFORMS.len()
    {
        return Err("authoritative residual tier policy is weakened".to_owned());
    }
    Ok(ResidualTierPolicy {
        acceptable_tiers,
        minimum_full_mutation_score_per_mille,
        required_platform_count,
    })
}

fn validate_allowed_signers_policy(path: &Path) -> Result<(), String> {
    let bytes = fs::read(path)
        .map_err(|error| format!("cannot read signer policy {}: {error}", path.display()))?;
    if bytes.last() != Some(&b'\n') {
        return Err("allowed-signers policy lacks a trailing newline".to_owned());
    }
    let document = std::str::from_utf8(&bytes)
        .map_err(|_| "allowed-signers policy is not UTF-8".to_owned())?;
    let mut subjects = BTreeSet::new();
    let mut keys = BTreeSet::new();
    for line in document.lines().map(str::trim) {
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let principal = line
            .split_ascii_whitespace()
            .next()
            .ok_or_else(|| "allowed-signers entry lacks a principal".to_owned())?;
        let identities = principal.split(',').collect::<Vec<_>>();
        if identities.iter().any(|identity| {
            let Some((role, subject)) = identity.split_once(':') else {
                return true;
            };
            role.is_empty()
                || subject.is_empty()
                || !role
                    .bytes()
                    .all(|byte| byte.is_ascii_lowercase() || byte == b'-')
        }) {
            return Err("allowed-signers principals must be role-qualified identities".to_owned());
        }
        for identity in identities {
            let subject = identity
                .split_once(':')
                .map(|(_, subject)| subject)
                .ok_or_else(|| "allowed-signers principal lacks a subject".to_owned())?;
            if !subjects.insert(subject.to_owned()) {
                return Err(
                    "allowed-signers aliases one subject across multiple principals".to_owned(),
                );
            }
        }
        let fields = line.split_whitespace().collect::<Vec<_>>();
        if fields.len() < 3 {
            return Err("allowed-signers entry lacks an SSH public key".to_owned());
        }
        let fingerprint = sha256_bytes(format!("{} {}", fields[1], fields[2]).as_bytes()).hex();
        if !keys.insert(fingerprint) {
            return Err(
                "allowed-signers aliases one SSH key across multiple principals".to_owned(),
            );
        }
    }
    Ok(())
}

fn require_assignment(document: &str, key: &str, expected: &str) -> Result<(), String> {
    let observed = document
        .lines()
        .map(str::trim)
        .filter(|line| !line.starts_with('#'))
        .find_map(|line| {
            let (candidate, value) = line.split_once('=')?;
            (candidate.trim() == key).then(|| value.trim())
        })
        .ok_or_else(|| format!("missing {key}"))?;
    (observed == expected)
        .then_some(())
        .ok_or_else(|| format!("{key} must be {expected}, observed {observed}"))
}

fn assignment_string(document: &str, key: &str) -> Result<String, String> {
    let value = document
        .lines()
        .map(str::trim)
        .filter(|line| !line.starts_with('#'))
        .find_map(|line| {
            let (candidate, value) = line.split_once('=')?;
            (candidate.trim() == key).then(|| value.trim())
        })
        .ok_or_else(|| format!("missing {key}"))?;
    value
        .strip_prefix('"')
        .and_then(|value| value.strip_suffix('"'))
        .map(str::to_owned)
        .ok_or_else(|| format!("{key} is not a quoted string"))
}

fn assignment_u64(document: &str, key: &str) -> Result<u64, String> {
    let value = document
        .lines()
        .map(str::trim)
        .filter(|line| !line.starts_with('#'))
        .find_map(|line| {
            let (candidate, value) = line.split_once('=')?;
            (candidate.trim() == key).then(|| value.trim())
        })
        .ok_or_else(|| format!("missing {key}"))?;
    value
        .parse::<u64>()
        .map_err(|_| format!("{key} is not an unsigned integer"))
}

