fn epoch_command(root: &Path, options: &Options) -> Result<String, String> {
    match options.action.as_deref().unwrap_or("print") {
        "print" => Ok(epoch(root)?.1.hex()),
        "write" => {
            let output = required_path(&options.output, "evidence-epoch write requires --output")?;
            let (manifest, digest) = epoch(root)?;
            write_atomic(output, manifest.as_bytes())?;
            write_digest_sibling(output, digest)?;
            Ok(digest.hex())
        }
        "verify" => {
            let (_, digest) = epoch(root)?;
            let expected = options
                .expected
                .as_deref()
                .ok_or_else(|| "evidence-epoch verify requires --expected".to_owned())?;
            require_digest(expected, "expected epoch")?;
            if digest.hex() != expected {
                return Err(format!(
                    "stale evidence epoch: expected {expected}, current {}",
                    digest.hex()
                ));
            }
            Ok(digest.hex())
        }
        "diff" => {
            let from = read_text(required_path(
                &options.from,
                "evidence-epoch diff requires --from",
            )?)?;
            let to = read_text(required_path(
                &options.to,
                "evidence-epoch diff requires --to",
            )?)?;
            let differences = line_diff(&from, &to);
            let output = required_path(&options.output, "evidence-epoch diff requires --output")?;
            write_atomic(output, differences.as_bytes())?;
            Ok(format!("wrote epoch diff to {}", output.display()))
        }
        action => Err(format!("unknown evidence-epoch action {action:?}")),
    }
}

pub(crate) fn epoch(root: &Path) -> Result<(String, Digest), String> {
    #[cfg(not(test))]
    if !git_output(root, &["status", "--porcelain=v2", "--untracked-files=no"])?
        .trim()
        .is_empty()
    {
        return Err("assurance epoch requires a clean candidate worktree".to_owned());
    }
    let mut files = Vec::new();
    for components in [
        &["Cargo.toml"][..],
        &["Cargo.lock"][..],
        &["rust-toolchain.toml"][..],
        &["baseline.toml"][..],
        &["compat", "reviews.allowed_signers"][..],
    ] {
        add_file(root, &components.iter().collect::<PathBuf>(), &mut files)?;
    }
    for components in [
        &[".cargo"][..],
        &["crates"][..],
        &["builtins"][..],
        &["fixtures"][..],
        &["compat"][..],
        &["spec"][..],
        &["tests"][..],
        &["tools"][..],
        &[".github", "workflows"][..],
    ] {
        let path = root.join(components.iter().collect::<PathBuf>());
        if path.is_dir() {
            collect_epoch_files(root, &path, &mut files)?;
        }
    }
    files.sort_by(|left, right| left.0.cmp(&right.0));
    files.dedup_by(|left, right| left.0 == right.0);
    let commit = git_output(root, &["rev-parse", "HEAD"])?;
    let tree = git_output(root, &["rev-parse", "HEAD^{tree}"])?;
    let mut json = String::from("{\n  \"schemaVersion\": 1,\n  \"candidateSourceCommit\": ");
    push_json(&mut json, commit.trim());
    json.push_str(",\n  \"candidateTreeObject\": ");
    push_json(&mut json, tree.trim());
    json.push_str(",\n  \"baseline\": ");
    push_json(&mut json, hell_builtins::LANGUAGE_VERSION);
    json.push_str(",\n  \"inputs\": {");
    for (index, (path, digest)) in files.iter().enumerate() {
        if index != 0 {
            json.push(',');
        }
        json.push_str("\n    ");
        push_json(&mut json, path);
        json.push_str(": ");
        push_json(&mut json, &digest.hex());
    }
    json.push_str("\n  }\n}\n");
    let digest = sha256_bytes(json.as_bytes());
    Ok((json, digest))
}

pub(crate) fn retained_epoch_digest(path: &Path) -> Result<(String, String), String> {
    let bytes = read_regular_file(path)?;
    let text = std::str::from_utf8(&bytes)
        .map_err(|_| "retained assurance epoch is not UTF-8".to_owned())?;
    let document = parse_json(text)?;
    let document = document.object()?;
    exact_keys(
        document,
        &[
            "baseline",
            "candidateSourceCommit",
            "candidateTreeObject",
            "inputs",
            "schemaVersion",
        ],
    )?;
    if json_member(document, "schemaVersion")?.number()? != 1
        || json_member(document, "baseline")?.string()? != hell_builtins::LANGUAGE_VERSION
    {
        return Err("retained assurance epoch schema or baseline is invalid".to_owned());
    }
    let candidate = json_member(document, "candidateSourceCommit")?
        .string()?
        .to_owned();
    require_git_sha_text(&candidate, "retained assurance epoch candidate")?;
    let tree = json_member(document, "candidateTreeObject")?.string()?;
    require_git_sha_text(tree, "retained assurance epoch tree")?;
    verify_epoch_commit_tree(path, &candidate, tree)?;
    let inputs = json_member(document, "inputs")?.object()?;
    if inputs.is_empty() {
        return Err("retained assurance epoch has no inputs".to_owned());
    }
    for (name, digest) in inputs {
        if name.is_empty()
            || Path::new(name).is_absolute()
            || name.split('/').any(|part| part == "..")
        {
            return Err("retained assurance epoch contains an unsafe input path".to_owned());
        }
        require_digest(digest.string()?, "retained assurance epoch input")?;
    }
    let digest = sha256_bytes(&bytes).hex();
    let name = path
        .file_name()
        .and_then(OsStr::to_str)
        .ok_or_else(|| "retained epoch filename is not UTF-8".to_owned())?;
    let expected_sibling = format!("{digest}  {name}\n");
    if read_text(&path.with_extension("sha256"))? != expected_sibling {
        return Err("retained assurance epoch digest sibling mismatch".to_owned());
    }
    Ok((candidate, digest))
}

fn verify_epoch_commit_tree(
    path: &Path,
    candidate: &str,
    retained_tree: &str,
) -> Result<(), String> {
    if crate::assurance_control_mutant_active("upstream-tree-after-commit") {
        return Ok(());
    }
    let repository = path
        .ancestors()
        .find(|ancestor| ancestor.join(".git").exists())
        .ok_or_else(|| "retained assurance epoch is outside a Git repository".to_owned())?;
    let expression = format!("{candidate}^{{tree}}");
    let expected_tree = git_output(repository, &["rev-parse", &expression])?;
    if expected_tree.trim() != retained_tree {
        return Err("retained assurance epoch commit/tree relationship was substituted".to_owned());
    }
    Ok(())
}

fn collect_epoch_files(
    root: &Path,
    directory: &Path,
    files: &mut Vec<(String, Digest)>,
) -> Result<(), String> {
    let mut entries = fs::read_dir(directory)
        .map_err(|error| format!("cannot enumerate {}: {error}", directory.display()))?
        .collect::<Result<Vec<_>, _>>()
        .map_err(|error| format!("cannot enumerate {}: {error}", directory.display()))?;
    entries.sort_by_key(std::fs::DirEntry::file_name);
    for entry in entries {
        let path = entry.path();
        let relative = path
            .strip_prefix(root)
            .map_err(|_| format!("{} is outside repository", path.display()))?;
        if relative.starts_with("compat/reviews")
            || relative.starts_with("compat/locks")
            || relative == Path::new("compat").join("promotion-review.toml")
            || relative == Path::new("compat").join("review-revocations.toml")
        {
            continue;
        }
        let file_type = entry
            .file_type()
            .map_err(|error| format!("cannot inspect {}: {error}", path.display()))?;
        if file_type.is_dir() {
            collect_epoch_files(root, &path, files)?;
        } else if file_type.is_file() && epoch_extension(relative) {
            add_file(root, relative, files)?;
        }
    }
    Ok(())
}

fn epoch_extension(path: &Path) -> bool {
    matches!(
        path.extension().and_then(OsStr::to_str),
        Some("rs" | "toml" | "ron" | "json" | "hell" | "yml" | "yaml" | "py" | "tsv" | "stdout")
    ) || path.file_name().and_then(OsStr::to_str) == Some("Cargo.lock")
}

fn add_file(root: &Path, relative: &Path, files: &mut Vec<(String, Digest)>) -> Result<(), String> {
    let path = root.join(relative);
    if !path.is_file() {
        return Ok(());
    }
    let bytes =
        fs::read(&path).map_err(|error| format!("cannot read {}: {error}", path.display()))?;
    files.push((path_text(relative)?, sha256_bytes(&bytes)));
    Ok(())
}

fn applicability_command(options: &Options) -> Result<String, String> {
    let action = options.action.as_deref().unwrap_or("derive");
    if action == "verify" {
        let rows = applicability_rows();
        let expected = hell_builtins::UNIQUE_NAME_COUNT * CompatibilityDimension::ALL.len();
        if rows.len() != expected {
            return Err(format!(
                "applicability catalog has {} rows, expected {expected}",
                rows.len()
            ));
        }
        return Ok(format!("verified {} applicability cells", rows.len()));
    }
    let output = required_path(&options.output, "applicability output requires --output")?;
    let json = applicability_json(action == "explain");
    write_atomic(output, json.as_bytes())?;
    Ok(format!(
        "wrote {} applicability cells",
        applicability_rows().len()
    ))
}

fn applicability_rows() -> Vec<(
    &'static str,
    CompatibilityDimension,
    &'static str,
    &'static str,
)> {
    let mut rows = Vec::new();
    for spec in hell_builtins::registry() {
        for dimension in CompatibilityDimension::ALL {
            let (decision, confidence) = applicability(spec, dimension);
            rows.push((spec.name, dimension, decision, confidence));
        }
    }
    if crate::assurance_control_mutant_active("all-claims-not-applicable") {
        for row in &mut rows {
            row.2 = "not-applicable-derived";
        }
    }
    rows
}

fn applicability(
    spec: &hell_builtins::BuiltinSpec,
    dimension: CompatibilityDimension,
) -> (&'static str, &'static str) {
    use hell_builtins::assurance_catalogs as catalog;
    use hell_builtins::{AssuranceCapability, AssuranceSensitivity, EffectKind};
    let metadata = spec.assurance_metadata();
    match dimension {
        CompatibilityDimension::Parse if spec.visibility == Visibility::Public => {
            (catalog::PUBLIC_PARSE_DECISION, "mechanical")
        }
        CompatibilityDimension::StaticSemantics => {
            (catalog::STATIC_SEMANTICS_DECISION, "mechanical")
        }
        CompatibilityDimension::PureRuntime if spec.implementation.is_some() => {
            (catalog::PURE_RUNTIME_DECISION, "family-default")
        }
        CompatibilityDimension::Effects if metadata.effect_kind == EffectKind::Io => {
            (catalog::EFFECTS_DECISION, "family-default")
        }
        CompatibilityDimension::Concurrency
            if metadata
                .capabilities
                .contains(&AssuranceCapability::Concurrency) =>
        {
            (catalog::CONCURRENCY_DECISION, "family-default")
        }
        CompatibilityDimension::Presentation
            if metadata
                .sensitivities
                .contains(&AssuranceSensitivity::Presentation) =>
        {
            (catalog::PRESENTATION_DECISION, "family-default")
        }
        CompatibilityDimension::Platform
            if metadata
                .sensitivities
                .contains(&AssuranceSensitivity::Platform) =>
        {
            (catalog::PLATFORM_DECISION, "family-default")
        }
        CompatibilityDimension::ResourceBehavior
            if metadata
                .sensitivities
                .contains(&AssuranceSensitivity::Resource) =>
        {
            (catalog::RESOURCE_DECISION, "family-default")
        }
        _ => (catalog::DEFAULT_APPLICABILITY_DECISION, "heuristic"),
    }
}

fn applicability_json(explain: bool) -> String {
    assert!(
        !generated_claim_policy_allows_unsafe_evidence(),
        "generated claim policy permits unsafe automatic evidence"
    );
    let rows = applicability_rows();
    let mut json = format!(
        "{{\n  \"schemaVersion\": 1,\n  \"automaticNotApplicable\": {},\n  \"cells\": [",
        hell_builtins::assurance_catalogs::AUTOMATIC_NOT_APPLICABLE
    );
    for (index, (builtin, dimension, decision, confidence)) in rows.iter().enumerate() {
        if index != 0 {
            json.push(',');
        }
        json.push_str("\n    {\"builtin\": ");
        push_json(&mut json, builtin);
        json.push_str(", \"dimension\": ");
        push_json(&mut json, dimension.as_str());
        json.push_str(", \"decision\": ");
        push_json(&mut json, decision);
        json.push_str(", \"confidence\": ");
        push_json(&mut json, confidence);
        if explain {
            json.push_str(", \"explanation\": ");
            push_json(
                &mut json,
                if *confidence == "mechanical" {
                    "derived from registry visibility or mandatory static participation"
                } else {
                    "human review remains required; no not-applicable status was inferred"
                },
            );
        }
        json.push('}');
    }
    json.push_str("\n  ]\n}\n");
    json
}

#[inline(never)]
fn generated_claim_policy_allows_unsafe_evidence() -> bool {
    hell_builtins::assurance_catalogs::AUTOMATIC_NOT_APPLICABLE
        || hell_builtins::assurance_catalogs::GENERATED_DIRECT_CLAIM_EVIDENCE
}

fn case_catalog_command(options: &Options) -> Result<String, String> {
    if options.action.as_deref().unwrap_or("verify") != "verify" {
        return Err("case-catalog supports only verify".to_owned());
    }
    let cases = committed_differential_cases();
    validate_evidence_catalog(&cases)?;
    Ok(format!(
        "verified {} committed differential cases",
        cases.len()
    ))
}

struct ClaimCoverageRow<'a> {
    builtin: &'a str,
    dimension: CompatibilityDimension,
    decision: &'a str,
    platform: &'a str,
    references: Vec<JsonValue>,
    normalizers: Vec<String>,
    application_refs: Vec<String>,
    complete: bool,
    normalized_fingerprints: BTreeSet<String>,
    has_exact_evidence: bool,
    status: &'static str,
}

struct ClaimCoverageCounts {
    total: usize,
    ambiguous: usize,
    missing_obligations: usize,
    required_platform_gaps: usize,
    semantic_coverage_gaps: usize,
    unreached_targets: usize,
}

fn render_claim_coverage(
    source: &str,
    epoch: &str,
    counts: &ClaimCoverageCounts,
    rows: Vec<ClaimCoverageRow<'_>>,
    mismatch_candidates: &[JsonValue],
) -> Result<String, String> {
    let mut json = format!(
        "{{\n  \"schemaVersion\": 1,\n  \"candidateSourceCommit\": {},\n  \"assuranceEpochSha256\": {},\n  \"totalClaimCells\": {},\n  \"explicitDispositionCells\": {},\n  \"ambiguousClaimScopes\": {},\n  \"missingObligations\": {},\n  \"requiredPlatformGaps\": {},\n  \"semanticCoverageGaps\": {},\n  \"unreachedTargets\": {},\n  \"cells\": [",
        json_string(source),
        json_string(epoch),
        counts.total,
        counts.total,
        counts.ambiguous,
        counts.missing_obligations,
        counts.required_platform_gaps,
        counts.semantic_coverage_gaps,
        counts.unreached_targets,
    );
    for (index, row) in rows.into_iter().enumerate() {
        if index != 0 {
            json.push(',');
        }
        write_claim_coverage_cell(&mut json, source, epoch, &row)?;
    }
    json.push_str("\n  ],\n  \"mismatchCandidates\": [");
    for (index, candidate) in mismatch_candidates.iter().enumerate() {
        if index != 0 {
            json.push(',');
        }
        json.push_str("\n    ");
        push_json_value(&mut json, candidate)?;
    }
    json.push_str("\n  ]\n}\n");
    Ok(json)
}

fn write_claim_coverage_cell(
    json: &mut String,
    source: &str,
    epoch: &str,
    row: &ClaimCoverageRow<'_>,
) -> Result<(), String> {
    json.push_str("\n    {\"builtin\": ");
    push_json(json, row.builtin);
    json.push_str(", \"dimension\": ");
    push_json(json, row.dimension.as_str());
    json.push_str(", \"profile\": \"upstream\", \"platform\": ");
    push_json(json, row.platform);
    json.push_str(", \"candidateSourceCommit\": ");
    push_json(json, source);
    json.push_str(", \"assuranceEpochSha256\": ");
    push_json(json, epoch);
    json.push_str(", \"proposedStatus\": ");
    push_json(json, row.status);
    json.push_str(", \"applicability\": ");
    push_json(json, row.decision);
    json.push_str(", \"obligations\": [");
    for (index, obligation) in claim_obligations(row.builtin, row.dimension, row.platform)?
        .iter()
        .enumerate()
    {
        if index != 0 {
            json.push(',');
        }
        push_json(json, obligation);
    }
    json.push_str("], \"evidenceRefs\": [");
    for (index, reference) in row.references.iter().enumerate() {
        if index != 0 {
            json.push(',');
        }
        push_json_value(json, reference)?;
    }
    json.push_str("], \"normalizerIds\": [");
    push_json_strings(json, row.normalizers.iter().map(String::as_str));
    json.push_str("], \"normalizerApplicationRefs\": [");
    push_json_strings(json, row.application_refs.iter().map(String::as_str));
    json.push_str("], \"divergenceRecordRef\": null}");
    Ok(())
}

fn missing_claim_bundles(
    input: Option<&Path>,
    eligible: &[&DifferentialCase],
) -> Result<u64, String> {
    input.map_or_else(
        || u64::try_from(eligible.len()).map_err(|_| "eligible case count exceeds u64".to_owned()),
        |input| {
            let mut missing = 0_u64;
            for platform in REQUIRED_CLAIM_PLATFORMS {
                for case in eligible {
                    let bundle = native_observation_bundle(input, platform, case.id.as_ref());
                    if hell_testkit::verify_observation_bundle_for_case(&bundle, case).is_err() {
                        missing = missing.saturating_add(1);
                    }
                }
            }
            Ok(missing)
        },
    )
}

fn verified_coverage_message(
    action: &str,
    missing_bundles: u64,
    eligible_count: usize,
) -> Result<Option<String>, String> {
    if action != "verify" {
        return Ok(None);
    }
    if missing_bundles != 0 {
        return Err(format!(
            "semantic coverage has {missing_bundles} missing or causally invalid bundles"
        ));
    }
    Ok(Some(format!(
        "verified {eligible_count} descriptor-v4 semantic evidence bundles"
    )))
}

fn case_coverage_command(root: &Path, options: &Options) -> Result<String, String> {
    if let Some(result) = claim_coverage_review_action(root, options) {
        return result;
    }
    let cases = committed_differential_cases();
    validate_evidence_catalog(&cases)?;
    let action = options.action.as_deref().unwrap_or("report");
    let active = active_collection_coverage_scope(root)?;
    let eligible = claim_eligible_cases(&cases)
        .into_iter()
        .filter(|case| {
            active
                .as_ref()
                .is_none_or(|scope| scope.case_refs.contains(case.id.as_ref()))
        })
        .collect::<Vec<_>>();
    let input = options.input.as_deref();
    let missing_bundles = missing_claim_bundles(input, &eligible)?;
    if active.is_some() && missing_bundles != 0 {
        return Err(format!(
            "activated collection coverage has {missing_bundles} missing or causally invalid bundles"
        ));
    }
    if let Some(message) = verified_coverage_message(action, missing_bundles, eligible.len())? {
        return Ok(message);
    }
    let output = required_path(&options.output, "case-coverage report requires --output")?;
    let input = input.ok_or_else(|| {
        "case-coverage report requires --input with platform/case observation bundles".to_owned()
    })?;
    let source = git_output(root, &["rev-parse", "HEAD"])?;
    let (_, epoch) = epoch(root)?;
    let total = active
        .as_ref()
        .map_or_else(total_claim_cell_count, |scope| {
            scope
                .builtins
                .len()
                .saturating_mul(REQUIRED_CLAIM_PLATFORMS.len())
        });
    let retained_root = retained_evidence_root(output)?;
    let coverage = collect_claim_coverage_rows(
        input,
        retained_root,
        &eligible,
        source.trim(),
        &epoch.hex(),
        active.as_ref().map(|scope| &scope.builtins),
    )?;
    let mut rows = coverage.rows;
    derive_platform_dependent_statuses(&mut rows);
    let mut json = render_claim_coverage(
        source.trim(),
        &epoch.hex(),
        &ClaimCoverageCounts {
            total,
            ambiguous: coverage.ambiguous,
            missing_obligations: coverage.missing_obligations,
            required_platform_gaps: coverage.required_platform_gaps,
            semantic_coverage_gaps: coverage.semantic_coverage_gaps,
            unreached_targets: coverage.unreached_targets,
        },
        rows,
        &coverage.mismatch_candidates,
    )?;
    if active.is_some() {
        json = render_scoped_collection_coverage(&json)?;
    }
    write_atomic(output, json.as_bytes())?;
    Ok(format!(
        "wrote typed semantic coverage report to {}",
        output.display()
    ))
}

struct CollectedClaimCoverage<'a> {
    rows: Vec<ClaimCoverageRow<'a>>,
    mismatch_candidates: Vec<JsonValue>,
    ambiguous: usize,
    missing_obligations: usize,
    required_platform_gaps: usize,
    semantic_coverage_gaps: usize,
    unreached_targets: usize,
}

fn collect_claim_coverage_rows<'a>(
    input: &Path,
    retained_root: &Path,
    eligible: &[&DifferentialCase],
    source: &str,
    epoch: &str,
    active_scopes: Option<&BTreeSet<String>>,
) -> Result<CollectedClaimCoverage<'a>, String> {
    let mut rows = Vec::new();
    let mut mismatch_candidates = Vec::new();
    let mut ambiguous = 0_usize;
    let mut missing_obligations = 0_usize;
    let mut required_platform_gaps = 0_usize;
    let mut semantic_coverage_gaps = 0_usize;
    let mut unreached_targets = 0_usize;
    for (builtin, dimension, decision, _) in applicability_rows() {
        if active_scopes.as_ref().is_some_and(|scopes| {
            dimension != CompatibilityDimension::PureRuntime || !scopes.contains(builtin)
        }) {
            continue;
        }
        for &platform in REQUIRED_CLAIM_PLATFORMS {
            let required = claim_obligations(builtin, dimension, platform)?;
            let evidence = claim_cell_evidence(
                input,
                retained_root,
                eligible,
                builtin,
                dimension,
                platform,
                source,
                epoch,
            )?;
            let missing = required
                .iter()
                .filter(|obligation| !evidence.observed.contains(*obligation))
                .count();
            missing_obligations = missing_obligations.saturating_add(missing);
            if evidence.references.is_empty() {
                required_platform_gaps = required_platform_gaps.saturating_add(1);
            }
            if missing != 0 {
                semantic_coverage_gaps = semantic_coverage_gaps.saturating_add(1);
            }
            if !eligible.iter().any(|case| {
                case.claim_evidence.as_ref().is_some_and(|descriptor| {
                    descriptor.semantic_targets.iter().any(|target| {
                        target.builtin.as_ref() == builtin
                            && target.dimension == dimension
                            && target.platforms.iter().any(|candidate| {
                                matches!(candidate, hell_builtins::ClaimPlatform::All)
                                    || claim_platform_matches(*candidate, platform)
                            })
                    })
                })
            }) {
                unreached_targets = unreached_targets.saturating_add(1);
            }
            if decision == "ambiguous-needs-review" {
                ambiguous = ambiguous.saturating_add(1);
            }
            let (row, candidates) =
                claim_coverage_row(builtin, dimension, decision, platform, evidence, missing);
            rows.push(row);
            mismatch_candidates.extend(candidates);
        }
    }
    Ok(CollectedClaimCoverage {
        rows,
        mismatch_candidates,
        ambiguous,
        missing_obligations,
        required_platform_gaps,
        semantic_coverage_gaps,
        unreached_targets,
    })
}

struct ActiveCollectionCoverageScope {
    builtins: BTreeSet<String>,
    case_refs: BTreeSet<String>,
}

fn active_collection_coverage_scope(
    root: &Path,
) -> Result<Option<ActiveCollectionCoverageScope>, String> {
    let manifest = read_regular_file(&root.join("compat/collection-activation.toml"))?;
    let provenance = read_regular_file(&root.join("compat/collection-activation-provenance.json"))?;
    let claims = read_regular_file(&root.join("compat/collection-activation-claims.json"))?;
    if !hell_testkit::verify_collection_activation_state(&manifest, &provenance, &claims)? {
        return Ok(None);
    }
    crate::collection_custody::verify_active_collection_activation_repository(root)?;
    let scopes = hell_testkit::activated_collection_claim_scopes()?;
    Ok(Some(ActiveCollectionCoverageScope {
        builtins: scopes.iter().map(|scope| scope.builtin.clone()).collect(),
        case_refs: scopes
            .into_iter()
            .flat_map(|scope| scope.case_refs)
            .collect(),
    }))
}

fn render_scoped_collection_coverage(source: &str) -> Result<String, String> {
    let mut document = parse_json(source)?;
    let fields = document.object_mut()?;
    fields.insert(
        "coverageScope".to_owned(),
        JsonValue::String("activated-collection-exact14".to_owned()),
    );
    fields.insert("activatedScopeCells".to_owned(), JsonValue::Number(14));
    fields.insert("activeEvidenceCells".to_owned(), JsonValue::Number(42));
    fields.insert(
        "residualRuntimeCells".to_owned(),
        JsonValue::Number(scoped_collection_residual_runtime_cells()?),
    );
    fields.insert(
        "outOfScopeClaimCells".to_owned(),
        JsonValue::Number(scoped_collection_out_of_scope_claim_cells()?),
    );
    canonical_json_bytes(&document).and_then(|bytes| {
        String::from_utf8(bytes).map_err(|_| "scoped coverage is not UTF-8".to_owned())
    })
}

fn scoped_collection_out_of_scope_claim_cells() -> Result<u64, String> {
    let all = applicability_rows().len();
    let active = active_collection_applicability_rows()?.len();
    u64::try_from(all.saturating_sub(active))
        .map_err(|_| "collection out-of-scope claim count exceeds u64".to_owned())
}

fn scoped_collection_residual_runtime_cells() -> Result<u64, String> {
    let mut cases = dormant_committed_differential_cases();
    cases.extend(hell_testkit::reviewed_collection_cases()?);
    u64::try_from(
        hell_testkit::activated_collection_scope_completeness(&cases)?.residual_incomplete_cells,
    )
    .map_err(|_| "collection residual runtime count exceeds u64".to_owned())
}

fn claim_coverage_row<'a>(
    builtin: &'a str,
    dimension: CompatibilityDimension,
    decision: &'a str,
    platform: &'a str,
    evidence: ClaimCellEvidence,
    missing: usize,
) -> (ClaimCoverageRow<'a>, Vec<JsonValue>) {
    let complete = missing == 0 && evidence.divergence_candidates.is_empty();
    let status = if complete && decision != "ambiguous-needs-review" {
        if evidence.normalizers.is_empty() {
            "exact"
        } else {
            "normalized"
        }
    } else {
        "unverified"
    };
    (
        ClaimCoverageRow {
            builtin,
            dimension,
            decision,
            platform,
            references: evidence.references,
            normalizers: evidence.normalizers,
            application_refs: evidence.application_refs,
            complete,
            normalized_fingerprints: evidence.normalized_fingerprints,
            has_exact_evidence: evidence.has_exact_evidence,
            status,
        },
        evidence.divergence_candidates,
    )
}

fn derive_platform_dependent_statuses(rows: &mut [ClaimCoverageRow<'_>]) {
    let mut groups = BTreeMap::<(&str, &str), Vec<usize>>::new();
    for (index, row) in rows.iter().enumerate() {
        groups
            .entry((row.builtin, row.dimension.as_str()))
            .or_default()
            .push(index);
    }
    for indices in groups.values() {
        let fingerprint_sets = indices
            .iter()
            .map(|index| rows[*index].normalized_fingerprints.clone())
            .collect::<BTreeSet<_>>();
        let platform_dependent = indices.len() == REQUIRED_CLAIM_PLATFORMS.len()
            && fingerprint_sets.len() > 1
            && indices.iter().all(|index| {
                let row = &rows[*index];
                row.complete
                    && row.decision != "ambiguous-needs-review"
                    && !row.has_exact_evidence
                    && !row.normalized_fingerprints.is_empty()
                    && !row.normalizers.is_empty()
            });
        if platform_dependent {
            for index in indices {
                rows[*index].status = "platform-dependent";
            }
        }
    }
}

fn claim_eligible_cases(cases: &[DifferentialCase]) -> Vec<&DifferentialCase> {
    cases
        .iter()
        .filter(|case| case.claim_evidence.is_some())
        .collect()
}

fn total_claim_cell_count() -> usize {
    hell_builtins::UNIQUE_NAME_COUNT
        * CompatibilityDimension::ALL.len()
        * REQUIRED_CLAIM_PLATFORMS.len()
}

fn claim_coverage_review_action(root: &Path, options: &Options) -> Option<Result<String, String>> {
    match options.action.as_deref() {
        Some("prepare-decisions") => Some(prepare_claim_applicability_decisions(root, options)),
        Some("finalize") => Some(finalize_claim_coverage(root, options)),
        _ => None,
    }
}

fn auth_transport_probe_context(root: &Path, options: &Options) -> Result<String, String> {
    let subject = required_path(
        &options.input,
        "auth-transport-probe context requires --input subject",
    )?;
    let selection_root = required_path(
        &options.from,
        "auth-transport-probe context requires --from provider selection",
    )?;
    let output = required_path(
        &options.output,
        "auth-transport-probe context requires --output",
    )?;
    let selection = parse_json(&read_text(&selection_root.join("selection.json"))?)?;
    let selection = selection.object()?;
    let candidate = json_member(selection, "candidateCommit")?.string()?;
    reverify_regression_provider_selection(
        root,
        subject,
        selection_root,
        candidate,
        ".github/workflows/assurance-transport-readiness.yml",
    )?;
    let retained_run = parse_json(&read_text(
        &selection_root.join("provider-selected-run.json"),
    )?)?;
    let retained_run = retained_run.object()?;
    let context = transport_probe_context_document(
        selection,
        retained_run,
        subject,
        selection_root,
        candidate,
    )?;
    verify_transport_probe_context_provider(root, context.object()?, subject, selection_root)?;
    let context = canonical_json_bytes(&context)?;
    write_atomic(output, &context)?;
    write_digest_sibling(output, sha256_bytes(&context))?;
    Ok("retained exact provider-replayed transport probe context".to_owned())
}

fn transport_probe_context_document(
    selection: &BTreeMap<String, JsonValue>,
    retained_run: &BTreeMap<String, JsonValue>,
    subject: &Path,
    selection_root: &Path,
    candidate: &str,
) -> Result<JsonValue, String> {
    let run_id = json_member(selection, "providerRunId")?.number()?;
    let run_attempt = json_member(selection, "providerRunAttempt")?.number()?;
    let artifact_id = json_member(selection, "providerArtifactId")?.number()?;
    let artifact_name = json_member(selection, "artifact")?.string()?;
    let subject_sha256 = record_digest(subject)?;
    if subject_sha256 != json_member(selection, "directorySha256")?.string()? {
        return Err("transport probe subject differs from exact provider selection".to_owned());
    }
    let selection_sha256 = record_digest(&selection_root.join("selection.json"))?;
    let nonce_sha256 = sha256_bytes(
        format!("{TRANSPORT_PROBE_DOMAIN}\0{selection_sha256}\0{subject_sha256}").as_bytes(),
    )
    .hex();
    Ok(JsonValue::Object(BTreeMap::from([
        (
            "authorityDomain".to_owned(),
            JsonValue::String(TRANSPORT_PROBE_DOMAIN.to_owned()),
        ),
        (
            "candidateCommit".to_owned(),
            JsonValue::String(candidate.to_owned()),
        ),
        (
            "event".to_owned(),
            JsonValue::String(json_member(selection, "event")?.string()?.to_owned()),
        ),
        (
            "issuedAt".to_owned(),
            JsonValue::String(crate::custody_ops::current_utc_timestamp()?),
        ),
        (
            "nonceSha256".to_owned(),
            JsonValue::String(nonce_sha256),
        ),
        (
            "repository".to_owned(),
            JsonValue::String("Portfoligno/hell-rs".to_owned()),
        ),
        (
            "repositoryId".to_owned(),
            JsonValue::Number(
                json_member(selection, "repositoryId")?
                    .string()?
                    .parse::<u64>()
                    .map_err(|_| "transport probe repository ID is malformed".to_owned())?,
            ),
        ),
        ("runAttempt".to_owned(), JsonValue::Number(run_attempt)),
        ("runId".to_owned(), JsonValue::Number(run_id)),
        (
            "subjectArtifactId".to_owned(),
            JsonValue::Number(artifact_id),
        ),
        (
            "subjectArtifactName".to_owned(),
            JsonValue::String(artifact_name.to_owned()),
        ),
        (
            "subjectProviderSelectionSha256".to_owned(),
            JsonValue::String(selection_sha256),
        ),
        (
            "subjectSha256".to_owned(),
            JsonValue::String(subject_sha256),
        ),
        (
            "workflowHeadSha".to_owned(),
            JsonValue::String(json_member(retained_run, "head_sha")?.string()?.to_owned()),
        ),
        (
            "workflowRef".to_owned(),
            JsonValue::String(
                "Portfoligno/hell-rs/.github/workflows/assurance-transport-readiness.yml@refs/heads/main"
                    .to_owned(),
            ),
        ),
    ])))
}

fn prepare_claim_applicability_decisions(root: &Path, options: &Options) -> Result<String, String> {
    if !options.github_dispatch_inputs {
        return Err("case-coverage prepare-decisions requires --github-dispatch-inputs".to_owned());
    }
    let source = required_path(
        &options.input,
        "case-coverage prepare-decisions requires --input coverage",
    )?;
    let output = required_path(
        &options.output,
        "case-coverage prepare-decisions requires --output",
    )?;
    let authored_path = required_path(
        &options.from,
        "case-coverage prepare-decisions requires --from authored decisions",
    )?;
    let inputs = github_dispatch_object(CLAIM_DECISION_PRODUCER_INPUTS)?;
    let supplied = parse_json(&read_text(authored_path)?)?;
    let supplied = supplied.object()?;
    let candidate = map_value(&inputs, "candidate_sha")?;
    require_git_sha_text(candidate, "claim decision candidate")?;
    if git_output(root, &["rev-parse", "HEAD"])?.trim() != candidate {
        return Err("claim decision producer checkout differs from candidate".to_owned());
    }
    verify_claim_decision_native_source(root, &inputs, candidate)?;
    let decision_source = map_value(&inputs, "decision_source_sha")?;
    require_git_sha_text(decision_source, "claim decision source commit")?;
    let (_, epoch) = epoch(root)?;
    let source_digest = record_digest(source)?;
    let source_document = parse_json(&read_text(source)?)?;
    let supplied_decisions = expand_authored_claim_groups(supplied, &source_document)?;
    let retained_root = retained_evidence_root(output)?;
    let authored_bytes = canonical_json_bytes(&JsonValue::Object(supplied.clone()))?;
    let authored_path = retained_root
        .join("claim-decisions")
        .join("source")
        .join("externally-authored-decisions.json");
    write_atomic(&authored_path, &authored_bytes)?;
    let authored_relative = retained_relative_path(retained_root, &authored_path)?;
    let evidence_root = retained_root
        .join("claim-decisions")
        .join("review")
        .join("claim-decision-evidence");
    fs::create_dir_all(&evidence_root)
        .map_err(|error| format!("cannot create claim decision evidence directory: {error}"))?;
    let mut decisions = Vec::new();
    for supplied_decision in &supplied_decisions {
        decisions.push(materialize_claim_decision(
            supplied_decision.object()?,
            &evidence_root,
            retained_root,
            candidate,
            &epoch.hex(),
        )?);
    }
    let proposer = retain_claim_proposer_event(retained_root)?;
    let document = materialized_claim_decisions_document(ClaimDecisionDocumentInputs {
        candidate,
        epoch: &epoch.hex(),
        source_digest: &source_digest,
        source_relative: &retained_relative_path(retained_root, source)?,
        decision_source,
        authored_relative: &authored_relative,
        authored_bytes: &authored_bytes,
        decisions,
        proposer: &proposer,
    });
    write_atomic(output, &canonical_json_bytes(&document)?)?;
    Ok(format!(
        "materialized {} externally supplied claim decisions",
        json_member(document.object()?, "decisions")?.array()?.len()
    ))
}

struct ClaimDecisionDocumentInputs<'a> {
    candidate: &'a str,
    epoch: &'a str,
    source_digest: &'a str,
    source_relative: &'a str,
    decision_source: &'a str,
    authored_relative: &'a str,
    authored_bytes: &'a [u8],
    decisions: Vec<JsonValue>,
    proposer: &'a ClaimProposerFacts,
}

fn materialized_claim_decisions_document(inputs: ClaimDecisionDocumentInputs<'_>) -> JsonValue {
    JsonValue::Object(BTreeMap::from([
        ("schemaVersion".to_owned(), JsonValue::Number(2)),
        (
            "candidateSourceCommit".to_owned(),
            JsonValue::String(inputs.candidate.to_owned()),
        ),
        (
            "assuranceEpochSha256".to_owned(),
            JsonValue::String(inputs.epoch.to_owned()),
        ),
        (
            "sourceCoverageSha256".to_owned(),
            JsonValue::String(inputs.source_digest.to_owned()),
        ),
        (
            "sourceCoveragePath".to_owned(),
            JsonValue::String(inputs.source_relative.to_owned()),
        ),
        (
            "decisionSourceCommit".to_owned(),
            JsonValue::String(inputs.decision_source.to_owned()),
        ),
        (
            "authoredDecisionsPath".to_owned(),
            JsonValue::String(inputs.authored_relative.to_owned()),
        ),
        (
            "authoredDecisionsSha256".to_owned(),
            JsonValue::String(sha256_bytes(inputs.authored_bytes).hex()),
        ),
        ("decisions".to_owned(), JsonValue::Array(inputs.decisions)),
        (
            "claimProposerAccountId".to_owned(),
            JsonValue::Number(inputs.proposer.account_id),
        ),
        (
            "claimProposerLogin".to_owned(),
            JsonValue::String(inputs.proposer.login.clone()),
        ),
        (
            "providerRunId".to_owned(),
            JsonValue::Number(inputs.proposer.run_id),
        ),
        (
            "providerRunAttempt".to_owned(),
            JsonValue::Number(inputs.proposer.run_attempt),
        ),
        (
            "providerEventPath".to_owned(),
            JsonValue::String("claim-decisions/review/claim-proposer-event.json".to_owned()),
        ),
        (
            "providerEventSha256".to_owned(),
            JsonValue::String(inputs.proposer.event_sha256.clone()),
        ),
    ]))
}

fn expand_authored_claim_groups(
    authored: &BTreeMap<String, JsonValue>,
    source: &JsonValue,
) -> Result<Vec<JsonValue>, String> {
    exact_keys(authored, &["groups", "schemaVersion"])?;
    if json_member(authored, "schemaVersion")?.number()? != 2 {
        return Err("authored claim group schema is unsupported".to_owned());
    }
    let mut expected = claim_decision_groups(source)?;
    let mut decisions = Vec::new();
    let mut previous = None;
    for group in json_member(authored, "groups")?.array()? {
        let group = group.object()?;
        exact_keys(
            group,
            &[
                "cellSetSha256",
                "disposition",
                "exceptions",
                "groupId",
                "rationale",
                "statement",
            ],
        )?;
        let group_id = json_member(group, "groupId")?.string()?;
        if previous.is_some_and(|value| value >= group_id) {
            return Err("authored claim groups are not strictly sorted".to_owned());
        }
        previous = Some(group_id);
        let cells = expected
            .remove(group_id)
            .ok_or_else(|| "authored claim group is unknown or duplicated".to_owned())?;
        if json_member(group, "cellSetSha256")?.string()? != claim_decision_cell_set_sha256(&cells)?
        {
            return Err("authored claim group membership digest is stale".to_owned());
        }
        decisions.extend(expand_authored_claim_group(group, &cells)?);
    }
    if !expected.is_empty() {
        return Err("authored claim groups omit ambiguous claim cells".to_owned());
    }
    Ok(decisions)
}

fn claim_decision_groups(
    source: &JsonValue,
) -> Result<BTreeMap<String, Vec<ClaimDecisionKey>>, String> {
    let source = source.object()?;
    if json_member(source, "schemaVersion")?.number()? != 1 {
        return Err("claim group source coverage schema is unsupported".to_owned());
    }
    let mut groups = BTreeMap::<String, Vec<ClaimDecisionKey>>::new();
    for cell in json_member(source, "cells")?.array()? {
        let cell = cell.object()?;
        if json_member(cell, "applicability")?.string()? != "ambiguous-needs-review" {
            continue;
        }
        let key = claim_decision_key(cell)?;
        groups
            .entry(claim_decision_group_id(cell)?)
            .or_default()
            .push(key);
    }
    for cells in groups.values_mut() {
        cells.sort();
        cells.dedup();
    }
    Ok(groups)
}

fn claim_decision_key(cell: &BTreeMap<String, JsonValue>) -> Result<ClaimDecisionKey, String> {
    Ok((
        json_member(cell, "builtin")?.string()?.to_owned(),
        json_member(cell, "dimension")?.string()?.to_owned(),
        json_member(cell, "platform")?.string()?.to_owned(),
    ))
}

fn claim_decision_group_id(cell: &BTreeMap<String, JsonValue>) -> Result<String, String> {
    claim_decision_group_id_fields(
        json_member(cell, "builtin")?.string()?,
        json_member(cell, "dimension")?.string()?,
        json_member(cell, "profile")?.string()?,
        json_member(cell, "platform")?.string()?,
    )
}

fn claim_decision_group_id_fields(
    builtin: &str,
    dimension: &str,
    profile: &str,
    platform: &str,
) -> Result<String, String> {
    let spec = hell_builtins::registry()
        .iter()
        .find(|spec| spec.name == builtin)
        .ok_or_else(|| format!("claim decision group references unknown builtin {builtin}"))?;
    let identity = claim_decision_group_identity(spec, dimension, profile, platform);
    Ok(format!(
        "claim-applicability/{}",
        canonical_json_digest(&identity)?
    ))
}

fn claim_decision_group_identity(
    spec: &hell_builtins::BuiltinSpec,
    dimension: &str,
    profile: &str,
    platform: &str,
) -> JsonValue {
    let metadata = spec.assurance_metadata();
    JsonValue::Array(
        [
            "claim-applicability-equivalence-v2".to_owned(),
            spec.implementation.unwrap_or_default().to_owned(),
            spec.scheme.unwrap_or_default().to_owned(),
            spec.arity.to_string(),
            format!("{:?}", spec.visibility),
            format!("{:?}", spec.wiring),
            spec.type_class
                .map_or(String::new(), |class| class.as_str().to_owned()),
            spec.fixity
                .map_or(String::new(), |fixity| format!("{fixity:?}")),
            metadata.semantic_family.to_string(),
            hell_testkit::runtime_assurance_spec_sha256(spec).hex(),
            hell_testkit::runtime_assurance_authority_sha256().hex(),
            dimension.to_owned(),
            profile.to_owned(),
            platform.to_owned(),
        ]
        .into_iter()
        .map(JsonValue::String)
        .collect(),
    )
}

fn claim_decision_cell_set_sha256(cells: &[ClaimDecisionKey]) -> Result<String, String> {
    canonical_json_digest(&JsonValue::Array(
        cells
            .iter()
            .map(|(builtin, dimension, platform)| {
                JsonValue::Object(BTreeMap::from([
                    ("builtin".to_owned(), JsonValue::String(builtin.clone())),
                    ("dimension".to_owned(), JsonValue::String(dimension.clone())),
                    ("platform".to_owned(), JsonValue::String(platform.clone())),
                ]))
            })
            .collect(),
    ))
}

fn expand_authored_claim_group(
    group: &BTreeMap<String, JsonValue>,
    cells: &[ClaimDecisionKey],
) -> Result<Vec<JsonValue>, String> {
    let mut exceptions = authored_claim_exceptions(group, cells)?;
    let mut decisions = Vec::with_capacity(cells.len());
    for key in cells {
        let source = exceptions.remove(key).unwrap_or(group);
        decisions.push(authored_claim_decision(source, key)?);
    }
    if !exceptions.is_empty() {
        return Err("claim group exceptions contain cells outside the group".to_owned());
    }
    Ok(decisions)
}

fn authored_claim_exceptions<'a>(
    group: &'a BTreeMap<String, JsonValue>,
    cells: &[ClaimDecisionKey],
) -> Result<BTreeMap<ClaimDecisionKey, &'a BTreeMap<String, JsonValue>>, String> {
    let expected = cells.iter().collect::<BTreeSet<_>>();
    let mut exceptions = BTreeMap::new();
    for exception in json_member(group, "exceptions")?.array()? {
        let exception = exception.object()?;
        exact_keys(
            exception,
            &[
                "builtin",
                "dimension",
                "disposition",
                "platform",
                "rationale",
                "statement",
            ],
        )?;
        let key = claim_decision_key(exception)?;
        if !expected.contains(&key) || exceptions.insert(key, exception).is_some() {
            return Err("claim group exception is duplicated or outside the group".to_owned());
        }
    }
    Ok(exceptions)
}

fn authored_claim_decision(
    source: &BTreeMap<String, JsonValue>,
    key: &ClaimDecisionKey,
) -> Result<JsonValue, String> {
    for field in ["disposition", "rationale", "statement"] {
        let value = json_member(source, field)?.string()?;
        if value.is_empty() || value.chars().any(char::is_control) {
            return Err(format!("authored claim group {field} is invalid"));
        }
    }
    Ok(JsonValue::Object(BTreeMap::from([
        ("builtin".to_owned(), JsonValue::String(key.0.clone())),
        ("dimension".to_owned(), JsonValue::String(key.1.clone())),
        ("platform".to_owned(), JsonValue::String(key.2.clone())),
        (
            "profile".to_owned(),
            JsonValue::String("upstream".to_owned()),
        ),
        (
            "disposition".to_owned(),
            JsonValue::String(json_member(source, "disposition")?.string()?.to_owned()),
        ),
        (
            "rationale".to_owned(),
            JsonValue::String(json_member(source, "rationale")?.string()?.to_owned()),
        ),
        (
            "statement".to_owned(),
            JsonValue::String(json_member(source, "statement")?.string()?.to_owned()),
        ),
    ])))
}

fn verify_claim_decision_native_source(
    root: &Path,
    inputs: &BTreeMap<String, String>,
    candidate: &str,
) -> Result<(), String> {
    let package = map_value(inputs, "native_package_sha256")?;
    let archive = map_value(inputs, "native_provider_archive_sha256")?;
    require_digest(package, "claim decision native package")?;
    require_digest(archive, "claim decision native provider archive")?;
    let directory = Path::new("ci-out").join("evidence").join("native");
    let selection = verify_provider_artifact_selection(
        root,
        &directory,
        "native-oracle-merged",
        ".github/workflows/nightly.yml",
        "push",
        positive_map_integer(inputs, "native_run_id", "claim decision producer")?,
        positive_map_integer(inputs, "native_run_attempt", "claim decision producer")?,
        positive_map_integer(inputs, "native_artifact_id", "claim decision producer")?,
        candidate,
        package,
        archive,
    )?;
    write_atomic(
        &directory.join("claim-decision-native-provider-selection.json"),
        selection.as_bytes(),
    )
}

struct ClaimProposerFacts {
    account_id: u64,
    login: String,
    run_id: u64,
    run_attempt: u64,
    event_sha256: String,
}

fn retain_claim_proposer_event(retained_root: &Path) -> Result<ClaimProposerFacts, String> {
    let event_path = std::env::var_os("GITHUB_EVENT_PATH")
        .ok_or_else(|| "claim decisions require GITHUB_EVENT_PATH".to_owned())?;
    let event = parse_json(&read_text(Path::new(&event_path))?)?;
    let sender = json_member(event.object()?, "sender")?.object()?;
    let account_id = json_member(sender, "id")?.number()?;
    let login = json_member(sender, "login")?.string()?.to_owned();
    validate_provider_atom(&login, "claim proposer login")?;
    if account_id == 0 {
        return Err("claim proposer account ID must be nonzero".to_owned());
    }
    let bytes = canonical_json_bytes(&event)?;
    write_atomic(
        &retained_root
            .join("claim-decisions")
            .join("review")
            .join("claim-proposer-event.json"),
        &bytes,
    )?;
    Ok(ClaimProposerFacts {
        account_id,
        login,
        run_id: environment_u64("GITHUB_RUN_ID", "claim proposer run")?,
        run_attempt: environment_u64("GITHUB_RUN_ATTEMPT", "claim proposer attempt")?,
        event_sha256: sha256_bytes(&bytes).hex(),
    })
}

fn materialize_claim_decision(
    supplied: &BTreeMap<String, JsonValue>,
    evidence_root: &Path,
    retained_root: &Path,
    candidate: &str,
    epoch: &str,
) -> Result<JsonValue, String> {
    exact_keys(
        supplied,
        &[
            "builtin",
            "caseId",
            "dimension",
            "disposition",
            "platform",
            "profile",
            "rationale",
            "statement",
        ],
    )?;
    let statement = json_member(supplied, "statement")?.string()?;
    if statement.is_empty() || statement.chars().any(char::is_control) {
        return Err("claim decision statement is empty or contains controls".to_owned());
    }
    let evidence = JsonValue::Object(BTreeMap::from([
        ("schemaVersion".to_owned(), JsonValue::Number(1)),
        (
            "candidateSourceCommit".to_owned(),
            JsonValue::String(candidate.to_owned()),
        ),
        (
            "assuranceEpochSha256".to_owned(),
            JsonValue::String(epoch.to_owned()),
        ),
        (
            "builtin".to_owned(),
            JsonValue::String(json_member(supplied, "builtin")?.string()?.to_owned()),
        ),
        (
            "dimension".to_owned(),
            JsonValue::String(json_member(supplied, "dimension")?.string()?.to_owned()),
        ),
        (
            "platform".to_owned(),
            JsonValue::String(json_member(supplied, "platform")?.string()?.to_owned()),
        ),
        (
            "statement".to_owned(),
            JsonValue::String(statement.to_owned()),
        ),
    ]));
    let evidence_bytes = canonical_json_bytes(&evidence)?;
    let evidence_digest = sha256_bytes(&evidence_bytes).hex();
    let evidence_path = evidence_root.join(format!("{evidence_digest}.json"));
    write_atomic(&evidence_path, &evidence_bytes)?;
    Ok(JsonValue::Object(BTreeMap::from([
        (
            "builtin".to_owned(),
            JsonValue::String(json_member(supplied, "builtin")?.string()?.to_owned()),
        ),
        (
            "dimension".to_owned(),
            JsonValue::String(json_member(supplied, "dimension")?.string()?.to_owned()),
        ),
        (
            "profile".to_owned(),
            JsonValue::String(json_member(supplied, "profile")?.string()?.to_owned()),
        ),
        (
            "platform".to_owned(),
            JsonValue::String(json_member(supplied, "platform")?.string()?.to_owned()),
        ),
        (
            "disposition".to_owned(),
            JsonValue::String(json_member(supplied, "disposition")?.string()?.to_owned()),
        ),
        (
            "rationale".to_owned(),
            JsonValue::String(json_member(supplied, "rationale")?.string()?.to_owned()),
        ),
        (
            "evidencePath".to_owned(),
            JsonValue::String(retained_relative_path(retained_root, &evidence_path)?),
        ),
        (
            "evidenceSha256".to_owned(),
            JsonValue::String(evidence_digest),
        ),
    ])))
}

fn finalize_claim_coverage(root: &Path, options: &Options) -> Result<String, String> {
    let source_path = required_path(&options.input, "case-coverage finalize requires --input")?;
    let decisions_path = required_path(&options.from, "case-coverage finalize requires --from")?;
    let output = required_path(&options.output, "case-coverage finalize requires --output")?;
    let candidate = git_output(root, &["rev-parse", "HEAD"])?;
    let (_, epoch) = epoch(root)?;
    let mut source = parse_json(&read_text(source_path)?)?;
    let source_digest = record_digest(source_path)?;
    let decisions_digest = record_digest(decisions_path)?;
    let decisions_document = parse_json(&read_text(decisions_path)?)?;
    let retained_root = retained_evidence_root(output)?;
    let decisions = claim_applicability_decisions(
        decisions_document.object()?,
        candidate.trim(),
        &epoch.hex(),
        &source_digest,
        retained_root,
    )?;
    let JsonValue::Object(source_object) = &mut source else {
        return Err("claim coverage source is not an object".to_owned());
    };
    verify_claim_coverage_source_identity(source_object, candidate.trim(), &epoch.hex())?;
    let cells = source_object
        .get_mut("cells")
        .ok_or_else(|| "claim coverage source lacks cells".to_owned())?;
    let JsonValue::Array(cells) = cells else {
        return Err("claim coverage cells are not an array".to_owned());
    };
    let counts = apply_claim_applicability_decisions(cells, decisions, source_path)?;
    FinalizedClaimAuthorityBuilder {
        retained_root,
        source_path,
        source_digest: &source_digest,
        decisions_path,
        decisions_digest: &decisions_digest,
    }
    .finalize(source_object, &counts)?;
    write_atomic(output, &canonical_json_bytes(&source)?)?;
    Ok(format!(
        "finalized {} signed claim applicability decisions",
        counts.decisions
    ))
}

fn verify_claim_coverage_source_identity(
    source: &BTreeMap<String, JsonValue>,
    candidate: &str,
    epoch: &str,
) -> Result<(), String> {
    if json_member(source, "schemaVersion")?.number()? != 1
        || json_member(source, "candidateSourceCommit")?.string()? != candidate
        || json_member(source, "assuranceEpochSha256")?.string()? != epoch
    {
        return Err("claim coverage source identity is stale".to_owned());
    }
    Ok(())
}

struct FinalizedClaimAuthorityBuilder<'a> {
    retained_root: &'a Path,
    source_path: &'a Path,
    source_digest: &'a str,
    decisions_path: &'a Path,
    decisions_digest: &'a str,
}

impl FinalizedClaimAuthorityBuilder<'_> {
    fn finalize(
        self,
        source: &mut BTreeMap<String, JsonValue>,
        counts: &FinalizedClaimCounts,
    ) -> Result<(), String> {
        source.insert("schemaVersion".to_owned(), JsonValue::Number(2));
        source.insert("ambiguousClaimScopes".to_owned(), JsonValue::Number(0));
        set_claim_coverage_counts(source, counts);
        source.insert(
            "sourceCoveragePath".to_owned(),
            JsonValue::String(retained_relative_path(
                self.retained_root,
                self.source_path,
            )?),
        );
        source.insert(
            "sourceCoverageSha256".to_owned(),
            JsonValue::String(self.source_digest.to_owned()),
        );
        source.insert(
            "applicabilityDecisionsPath".to_owned(),
            JsonValue::String(retained_relative_path(
                self.retained_root,
                self.decisions_path,
            )?),
        );
        source.insert(
            "applicabilityDecisionsSha256".to_owned(),
            JsonValue::String(self.decisions_digest.to_owned()),
        );
        Ok(())
    }
}

#[cfg(test)]
pub(crate) fn build_synthetic_finalized_claim_authority(
    retained_root: &Path,
    candidate: &str,
    epoch: &str,
    platform_shards: &[(&str, String)],
) -> Result<PathBuf, String> {
    require_git_sha_text(candidate, "synthetic finalized candidate")?;
    require_digest(epoch, "synthetic finalized epoch")?;
    let expected_platforms = REQUIRED_CLAIM_PLATFORMS
        .iter()
        .copied()
        .collect::<BTreeSet<_>>();
    let observed_platforms = platform_shards
        .iter()
        .map(|(platform, _)| *platform)
        .collect::<BTreeSet<_>>();
    if observed_platforms != expected_platforms || platform_shards.len() != expected_platforms.len()
    {
        return Err("synthetic finalized authority lacks the exact three platforms".to_owned());
    }
    let directory = retained_root.join("synthetic-finalized-claim");
    fs::create_dir(&directory)
        .map_err(|error| format!("cannot create synthetic finalized claim directory: {error}"))?;
    let source_path = directory.join("source.json");
    let decisions_path = directory.join("decisions.json");
    let cells = platform_shards
        .iter()
        .map(|(platform, shard_sha256)| {
            require_digest(shard_sha256, "synthetic finalized shard")?;
            Ok(JsonValue::Object(BTreeMap::from([
                (
                    "builtin".to_owned(),
                    JsonValue::String("Int.plus".to_owned()),
                ),
                (
                    "dimension".to_owned(),
                    JsonValue::String("pure-runtime".to_owned()),
                ),
                (
                    "platform".to_owned(),
                    JsonValue::String((*platform).to_owned()),
                ),
                (
                    "profile".to_owned(),
                    JsonValue::String("upstream".to_owned()),
                ),
                (
                    "shardSha256".to_owned(),
                    JsonValue::String(shard_sha256.clone()),
                ),
                ("status".to_owned(), JsonValue::String("exact".to_owned())),
            ])))
        })
        .collect::<Result<Vec<_>, String>>()?;
    let mut source = BTreeMap::from([
        ("schemaVersion".to_owned(), JsonValue::Number(1)),
        (
            "candidateSourceCommit".to_owned(),
            JsonValue::String(candidate.to_owned()),
        ),
        (
            "assuranceEpochSha256".to_owned(),
            JsonValue::String(epoch.to_owned()),
        ),
        ("cells".to_owned(), JsonValue::Array(cells)),
        ("totalClaimCells".to_owned(), JsonValue::Number(3)),
        ("explicitDispositionCells".to_owned(), JsonValue::Number(3)),
        ("mismatchCandidates".to_owned(), JsonValue::Number(0)),
    ]);
    verify_claim_coverage_source_identity(&source, candidate, epoch)?;
    write_atomic(
        &source_path,
        &canonical_json_bytes(&JsonValue::Object(source.clone()))?,
    )?;
    write_atomic(&decisions_path, b"{\"decisions\":[],\"schemaVersion\":1}\n")?;
    let source_digest = record_digest(&source_path)?;
    let decisions_digest = record_digest(&decisions_path)?;
    FinalizedClaimAuthorityBuilder {
        retained_root,
        source_path: &source_path,
        source_digest: &source_digest,
        decisions_path: &decisions_path,
        decisions_digest: &decisions_digest,
    }
    .finalize(&mut source, &FinalizedClaimCounts::default())?;
    let finalized_path = directory.join("finalized.json");
    write_atomic(
        &finalized_path,
        &canonical_json_bytes(&JsonValue::Object(source))?,
    )?;
    verify_synthetic_finalized_claim_authority(&finalized_path, candidate, epoch, platform_shards)?;
    Ok(finalized_path)
}

#[cfg(test)]
pub(crate) fn verify_synthetic_finalized_claim_authority(
    path: &Path,
    candidate: &str,
    epoch: &str,
    platform_shards: &[(&str, String)],
) -> Result<(), String> {
    let document = parse_json(&read_text(path)?)?;
    let details = document.object()?;
    exact_keys(
        details,
        &[
            "ambiguousClaimScopes",
            "applicabilityDecisionsPath",
            "applicabilityDecisionsSha256",
            "assuranceEpochSha256",
            "candidateSourceCommit",
            "cells",
            "explicitDispositionCells",
            "mismatchCandidates",
            "missingObligations",
            "requiredPlatformGaps",
            "schemaVersion",
            "semanticCoverageGaps",
            "sourceCoveragePath",
            "sourceCoverageSha256",
            "totalClaimCells",
            "unreachedTargets",
        ],
    )?;
    if json_member(details, "schemaVersion")?.number()? != 2
        || json_member(details, "candidateSourceCommit")?.string()? != candidate
        || json_member(details, "assuranceEpochSha256")?.string()? != epoch
        || json_member(details, "totalClaimCells")?.number()? != 3
        || json_member(details, "explicitDispositionCells")?.number()? != 3
        || json_member(details, "ambiguousClaimScopes")?.number()? != 0
        || json_member(details, "mismatchCandidates")?.number()? != 0
        || json_member(details, "cells")?.array()?.len() != 3
        || verify_zero_coverage_gaps(details).is_err()
    {
        return Err("synthetic finalized claim authority changed".to_owned());
    }
    let expected = platform_shards.iter().cloned().collect::<BTreeMap<_, _>>();
    let mut observed = BTreeSet::new();
    for cell in json_member(details, "cells")?.array()? {
        let cell = cell.object()?;
        exact_keys(
            cell,
            &[
                "builtin",
                "dimension",
                "platform",
                "profile",
                "shardSha256",
                "status",
            ],
        )?;
        let platform = json_member(cell, "platform")?.string()?;
        if json_member(cell, "builtin")?.string()? != "Int.plus"
            || json_member(cell, "dimension")?.string()? != "pure-runtime"
            || json_member(cell, "profile")?.string()? != "upstream"
            || json_member(cell, "status")?.string()? != "exact"
            || expected.get(platform).map(String::as_str)
                != Some(json_member(cell, "shardSha256")?.string()?)
        {
            return Err("synthetic finalized claim cell changed".to_owned());
        }
        if !observed.insert(platform) {
            return Err("synthetic finalized claim platform is duplicated".to_owned());
        }
    }
    if observed != expected.keys().copied().collect() {
        return Err("synthetic finalized claim platform set changed".to_owned());
    }
    verify_synthetic_finalized_claim_inputs(path, details)
}

#[cfg(test)]
fn verify_synthetic_finalized_claim_inputs(
    path: &Path,
    details: &BTreeMap<String, JsonValue>,
) -> Result<(), String> {
    let retained_root = path
        .parent()
        .and_then(Path::parent)
        .ok_or_else(|| "synthetic finalized path lacks a retained root".to_owned())?;
    let source = confined_record_path(
        retained_root,
        retained_root,
        Path::new(json_member(details, "sourceCoveragePath")?.string()?),
    )?;
    let decisions = confined_record_path(
        retained_root,
        retained_root,
        Path::new(json_member(details, "applicabilityDecisionsPath")?.string()?),
    )?;
    verify_file_digest(
        &source,
        json_member(details, "sourceCoverageSha256")?.string()?,
        "sourceCoverageSha256",
    )?;
    verify_file_digest(
        &decisions,
        json_member(details, "applicabilityDecisionsSha256")?.string()?,
        "applicabilityDecisionsSha256",
    )?;
    let source = parse_json(&read_text(&source)?)?;
    let source = source.object()?;
    exact_keys(
        source,
        &[
            "assuranceEpochSha256",
            "candidateSourceCommit",
            "cells",
            "explicitDispositionCells",
            "mismatchCandidates",
            "schemaVersion",
            "totalClaimCells",
        ],
    )?;
    if json_member(source, "schemaVersion")?.number()? != 1
        || json_member(source, "candidateSourceCommit")?
            != json_member(details, "candidateSourceCommit")?
        || json_member(source, "assuranceEpochSha256")?
            != json_member(details, "assuranceEpochSha256")?
        || json_member(source, "cells")? != json_member(details, "cells")?
        || json_member(source, "totalClaimCells")? != json_member(details, "totalClaimCells")?
        || json_member(source, "explicitDispositionCells")?
            != json_member(details, "explicitDispositionCells")?
        || json_member(source, "mismatchCandidates")? != json_member(details, "mismatchCandidates")?
    {
        return Err("synthetic finalized claim source changed".to_owned());
    }
    let decisions = parse_json(&read_text(&decisions)?)?;
    let decisions = decisions.object()?;
    exact_keys(decisions, &["decisions", "schemaVersion"])?;
    if json_member(decisions, "schemaVersion")?.number()? != 1
        || !json_member(decisions, "decisions")?.array()?.is_empty()
    {
        return Err("synthetic finalized claim decisions changed".to_owned());
    }
    Ok(())
}

