fn retained_relative_path(root: &Path, path: &Path) -> Result<String, String> {
    path_text(
        path.strip_prefix(root)
            .map_err(|_| "claim decision input is outside retained evidence".to_owned())?,
    )
}

fn repository_relative_path(root: &Path, relative: &str) -> Result<PathBuf, String> {
    if relative.is_empty() || relative.starts_with('/') || relative.contains('\\') {
        return Err("repository-relative path is not canonical".to_owned());
    }
    let mut path = root.to_path_buf();
    for component in relative.split('/') {
        if component.is_empty() || matches!(component, "." | "..") {
            return Err("repository-relative path contains an unsafe component".to_owned());
        }
        path = path.join(component);
    }
    Ok(path)
}

fn repository_root() -> Result<PathBuf, String> {
    let current = std::env::current_dir()
        .map_err(|error| format!("cannot resolve repository directory: {error}"))?;
    current
        .ancestors()
        .find(|directory| {
            directory.join("Cargo.toml").is_file()
                && directory
                    .join("compat")
                    .join("review-policy.toml")
                    .is_file()
        })
        .map(Path::to_path_buf)
        .ok_or_else(|| "cannot locate the repository root from the current directory".to_owned())
}

#[derive(Default)]
struct FinalizedClaimCounts {
    decisions: usize,
    missing_obligations: u64,
    required_platform_gaps: u64,
    semantic_coverage_gaps: u64,
    unreached_targets: u64,
}

type ClaimDecisionKey = (String, String, String);

fn claim_applicability_decisions(
    document: &BTreeMap<String, JsonValue>,
    candidate: &str,
    epoch: &str,
    source_digest: &str,
    retained_root: &Path,
) -> Result<BTreeMap<ClaimDecisionKey, JsonValue>, String> {
    exact_keys(
        document,
        &[
            "authoredDecisionsPath",
            "authoredDecisionsSha256",
            "assuranceEpochSha256",
            "candidateSourceCommit",
            "claimProposerAccountId",
            "claimProposerLogin",
            "decisionSourceCommit",
            "decisions",
            "providerEventPath",
            "providerEventSha256",
            "providerRunAttempt",
            "providerRunId",
            "schemaVersion",
            "sourceCoveragePath",
            "sourceCoverageSha256",
        ],
    )?;
    if json_member(document, "schemaVersion")?.number()? != 2
        || json_member(document, "candidateSourceCommit")?.string()? != candidate
        || json_member(document, "assuranceEpochSha256")?.string()? != epoch
        || json_member(document, "sourceCoverageSha256")?.string()? != source_digest
    {
        return Err("claim applicability decisions do not bind the source report".to_owned());
    }
    verify_claim_proposer_event(document, retained_root)?;
    require_git_sha_text(
        json_member(document, "decisionSourceCommit")?.string()?,
        "claim decision source commit",
    )?;
    let mut authored = retained_authored_claim_decisions(document, retained_root)?;
    let mut decisions = BTreeMap::new();
    for decision in json_member(document, "decisions")?.array()? {
        let object = decision.object()?;
        exact_keys(
            object,
            &[
                "builtin",
                "dimension",
                "disposition",
                "evidencePath",
                "evidenceSha256",
                "platform",
                "profile",
                "rationale",
            ],
        )?;
        let disposition = json_member(object, "disposition")?.string()?;
        let rationale = json_member(object, "rationale")?.string()?;
        require_digest(
            json_member(object, "evidenceSha256")?.string()?,
            "claim applicability decision evidence",
        )?;
        if !matches!(
            disposition,
            "applicable-reviewed" | "not-applicable-reviewed"
        ) || rationale.is_empty()
            || rationale.chars().any(char::is_control)
            || json_member(object, "profile")?.string()? != "upstream"
        {
            return Err("claim applicability decision is invalid".to_owned());
        }
        let key = (
            json_member(object, "builtin")?.string()?.to_owned(),
            json_member(object, "dimension")?.string()?.to_owned(),
            json_member(object, "platform")?.string()?.to_owned(),
        );
        let statement = verify_claim_decision_evidence(
            retained_root,
            object,
            candidate,
            epoch,
            (&key.0, &key.1, &key.2),
        )?;
        let authored_decision = authored.remove(&key).ok_or_else(|| {
            "materialized claim decision is absent from authored source".to_owned()
        })?;
        verify_materialized_claim_decision(object, authored_decision.object()?, &statement)?;
        if decisions.insert(key, decision.clone()).is_some() {
            return Err("claim applicability decisions contain a duplicate cell".to_owned());
        }
    }
    if !authored.is_empty() {
        return Err("authored claim decisions were omitted during materialization".to_owned());
    }
    Ok(decisions)
}

fn retained_authored_claim_decisions(
    decisions: &BTreeMap<String, JsonValue>,
    retained_root: &Path,
) -> Result<BTreeMap<ClaimDecisionKey, JsonValue>, String> {
    let repository = repository_root()?;
    let path = confined_record_path(
        &repository,
        retained_root,
        Path::new(json_member(decisions, "authoredDecisionsPath")?.string()?),
    )?;
    verify_file_digest(
        &path,
        json_member(decisions, "authoredDecisionsSha256")?.string()?,
        "authored claim decisions",
    )?;
    let document = parse_json(&read_text(&path)?)?;
    let source_path = confined_record_path(
        &repository,
        retained_root,
        Path::new(json_member(decisions, "sourceCoveragePath")?.string()?),
    )?;
    verify_file_digest(
        &source_path,
        json_member(decisions, "sourceCoverageSha256")?.string()?,
        "claim decision source coverage",
    )?;
    let source = parse_json(&read_text(&source_path)?)?;
    let expanded = expand_authored_claim_groups(document.object()?, &source)?;
    let mut indexed = BTreeMap::new();
    for decision in &expanded {
        let decision = decision.object()?;
        exact_keys(
            decision,
            &[
                "builtin",
                "dimension",
                "disposition",
                "platform",
                "profile",
                "rationale",
                "statement",
            ],
        )?;
        let key = (
            json_member(decision, "builtin")?.string()?.to_owned(),
            json_member(decision, "dimension")?.string()?.to_owned(),
            json_member(decision, "platform")?.string()?.to_owned(),
        );
        if indexed
            .insert(key, JsonValue::Object(decision.clone()))
            .is_some()
        {
            return Err("authored claim decisions contain a duplicate cell".to_owned());
        }
    }
    Ok(indexed)
}

fn verify_materialized_claim_decision(
    materialized: &BTreeMap<String, JsonValue>,
    authored: &BTreeMap<String, JsonValue>,
    statement: &str,
) -> Result<(), String> {
    for field in [
        "builtin",
        "dimension",
        "disposition",
        "platform",
        "profile",
        "rationale",
    ] {
        if json_member(materialized, field)?.string()? != json_member(authored, field)?.string()? {
            return Err("materialized claim decision differs from authored source".to_owned());
        }
    }
    if statement != json_member(authored, "statement")?.string()? {
        return Err("claim decision evidence statement differs from authored source".to_owned());
    }
    Ok(())
}

fn verify_claim_proposer_event(
    decisions: &BTreeMap<String, JsonValue>,
    retained_root: &Path,
) -> Result<(), String> {
    let repository = repository_root()?;
    let event_path = confined_record_path(
        &repository,
        retained_root,
        Path::new(json_member(decisions, "providerEventPath")?.string()?),
    )?;
    verify_file_digest(
        &event_path,
        json_member(decisions, "providerEventSha256")?.string()?,
        "claim proposer event",
    )?;
    let event = parse_json(&read_text(&event_path)?)?;
    let event = event.object()?;
    let sender = json_member(event, "sender")?.object()?;
    let inputs = json_member(event, "inputs")?.object()?;
    if json_member(decisions, "claimProposerAccountId")?.number()? == 0
        || json_member(decisions, "claimProposerAccountId")?.number()?
            != json_member(sender, "id")?.number()?
        || json_member(decisions, "claimProposerLogin")?.string()?
            != json_member(sender, "login")?.string()?
        || json_member(decisions, "providerRunId")?.number()? == 0
        || json_member(decisions, "providerRunAttempt")?.number()? == 0
        || json_member(inputs, "candidate_sha")?.string()?
            != json_member(decisions, "candidateSourceCommit")?.string()?
        || json_member(inputs, "decision_source_sha")?.string()?
            != json_member(decisions, "decisionSourceCommit")?.string()?
    {
        return Err("claim proposer identity does not match retained provider event".to_owned());
    }
    Ok(())
}

fn verify_claim_decision_evidence(
    retained_root: &Path,
    decision: &BTreeMap<String, JsonValue>,
    candidate: &str,
    epoch: &str,
    cell: (&str, &str, &str),
) -> Result<String, String> {
    let repository = repository_root()?;
    let evidence = confined_record_path(
        &repository,
        retained_root,
        Path::new(json_member(decision, "evidencePath")?.string()?),
    )?;
    verify_file_digest(
        &evidence,
        json_member(decision, "evidenceSha256")?.string()?,
        "claim decision evidence",
    )?;
    let document = parse_json(&read_text(&evidence)?)?;
    let document = document.object()?;
    exact_keys(
        document,
        &[
            "assuranceEpochSha256",
            "builtin",
            "candidateSourceCommit",
            "dimension",
            "platform",
            "schemaVersion",
            "statement",
        ],
    )?;
    if json_member(document, "schemaVersion")?.number()? != 1
        || json_member(document, "candidateSourceCommit")?.string()? != candidate
        || json_member(document, "assuranceEpochSha256")?.string()? != epoch
        || json_member(document, "builtin")?.string()? != cell.0
        || json_member(document, "dimension")?.string()? != cell.1
        || json_member(document, "platform")?.string()? != cell.2
        || json_member(document, "statement")?.string()?.is_empty()
    {
        return Err("claim decision evidence does not bind the exact cell".to_owned());
    }
    Ok(json_member(document, "statement")?.string()?.to_owned())
}

fn apply_claim_applicability_decisions(
    cells: &mut [JsonValue],
    mut decisions: BTreeMap<ClaimDecisionKey, JsonValue>,
    source_path: &Path,
) -> Result<FinalizedClaimCounts, String> {
    let mut counts = FinalizedClaimCounts::default();
    for cell in cells {
        let JsonValue::Object(object) = cell else {
            return Err("claim coverage cell is not an object".to_owned());
        };
        let key = (
            json_member(object, "builtin")?.string()?.to_owned(),
            json_member(object, "dimension")?.string()?.to_owned(),
            json_member(object, "platform")?.string()?.to_owned(),
        );
        if json_member(object, "applicability")?.string()? == "ambiguous-needs-review" {
            let decision = decisions.remove(&key).ok_or_else(|| {
                "ambiguous claim cell lacks an exact reviewed decision".to_owned()
            })?;
            let disposition = json_member(decision.object()?, "disposition")?
                .string()?
                .to_owned();
            object.insert(
                "applicability".to_owned(),
                JsonValue::String(disposition.clone()),
            );
            object.insert(
                "applicabilityDecisionSha256".to_owned(),
                JsonValue::String(canonical_json_digest(&decision)?),
            );
            counts.decisions = counts.decisions.saturating_add(1);
            if disposition == "not-applicable-reviewed" {
                clear_not_applicable_claim_cell(object);
                continue;
            }
        } else {
            object.insert("applicabilityDecisionSha256".to_owned(), JsonValue::Null);
        }
        update_finalized_claim_counts(object, source_path, &mut counts)?;
    }
    if !decisions.is_empty() {
        return Err("claim applicability decisions contain extra cells".to_owned());
    }
    Ok(counts)
}

fn clear_not_applicable_claim_cell(cell: &mut BTreeMap<String, JsonValue>) {
    cell.insert(
        "proposedStatus".to_owned(),
        JsonValue::String("not-applicable".to_owned()),
    );
    for field in [
        "obligations",
        "evidenceRefs",
        "normalizerIds",
        "normalizerApplicationRefs",
    ] {
        cell.insert(field.to_owned(), JsonValue::Array(Vec::new()));
    }
    cell.insert("divergenceRecordRef".to_owned(), JsonValue::Null);
}

fn update_finalized_claim_counts(
    cell: &BTreeMap<String, JsonValue>,
    source_path: &Path,
    counts: &mut FinalizedClaimCounts,
) -> Result<(), String> {
    let evidence = json_member(cell, "evidenceRefs")?.array()?;
    if evidence.is_empty() {
        counts.required_platform_gaps = counts.required_platform_gaps.saturating_add(1);
        counts.unreached_targets = counts.unreached_targets.saturating_add(1);
    }
    let dimension = compatibility_dimension(json_member(cell, "dimension")?.string()?)?;
    let mut observed = BTreeSet::new();
    require_unique_claim_evidence_edges(evidence)?;
    for reference in evidence {
        observed.extend(verify_claim_evidence_reference(
            reference,
            source_path,
            json_member(cell, "builtin")?.string()?,
            dimension,
            json_member(cell, "platform")?.string()?,
            json_member(cell, "candidateSourceCommit")?.string()?,
            json_member(cell, "assuranceEpochSha256")?.string()?,
        )?);
    }
    let missing = claim_obligations(
        json_member(cell, "builtin")?.string()?,
        dimension,
        json_member(cell, "platform")?.string()?,
    )?
    .iter()
    .filter(|obligation| !observed.contains(*obligation))
    .count();
    counts.missing_obligations = counts.missing_obligations.saturating_add(
        u64::try_from(missing).map_err(|_| "missing obligation count exceeds u64")?,
    );
    counts.semantic_coverage_gaps = counts
        .semantic_coverage_gaps
        .saturating_add(u64::from(missing != 0));
    Ok(())
}

fn compatibility_dimension(value: &str) -> Result<CompatibilityDimension, String> {
    CompatibilityDimension::ALL
        .iter()
        .copied()
        .find(|dimension| dimension.as_str() == value)
        .ok_or_else(|| "claim decision names an unknown dimension".to_owned())
}

fn set_claim_coverage_counts(
    report: &mut BTreeMap<String, JsonValue>,
    counts: &FinalizedClaimCounts,
) {
    for (field, value) in [
        ("missingObligations", counts.missing_obligations),
        ("requiredPlatformGaps", counts.required_platform_gaps),
        ("semanticCoverageGaps", counts.semantic_coverage_gaps),
        ("unreachedTargets", counts.unreached_targets),
    ] {
        report.insert(field.to_owned(), JsonValue::Number(value));
    }
}

#[allow(clippy::too_many_arguments)]
fn claim_cell_evidence(
    input: &Path,
    retained_root: &Path,
    cases: &[&DifferentialCase],
    builtin: &str,
    dimension: CompatibilityDimension,
    platform: &str,
    candidate: &str,
    epoch: &str,
) -> Result<ClaimCellEvidence, String> {
    let context = ClaimCellEvidenceContext {
        input,
        retained_root,
        builtin,
        dimension,
        platform,
        candidate,
        epoch,
    };
    let mut evidence = ClaimCellEvidenceAccumulator::default();
    for case in cases {
        let Some(descriptor) = &case.claim_evidence else {
            continue;
        };
        for target in descriptor.semantic_targets.iter().filter(|target| {
            target.builtin.as_ref() == builtin
                && target.dimension == dimension
                && target.platforms.iter().copied().any(|candidate| {
                    matches!(candidate, hell_builtins::ClaimPlatform::All)
                        || claim_platform_matches(candidate, platform)
                })
        }) {
            collect_claim_target_evidence(&context, case, target, &mut evidence)?;
        }
    }
    Ok(ClaimCellEvidence {
        references: evidence.references,
        observed: evidence.observed,
        normalizers: evidence.normalizers.into_keys().collect(),
        application_refs: evidence.application_refs.into_iter().collect(),
        divergence_candidates: evidence.divergence_candidates,
        normalized_fingerprints: evidence.normalized_fingerprints,
        has_exact_evidence: evidence.has_exact_evidence,
    })
}

struct ClaimCellEvidenceContext<'a> {
    input: &'a Path,
    retained_root: &'a Path,
    builtin: &'a str,
    dimension: CompatibilityDimension,
    platform: &'a str,
    candidate: &'a str,
    epoch: &'a str,
}

#[derive(Default)]
struct ClaimCellEvidenceAccumulator {
    references: Vec<JsonValue>,
    observed: BTreeSet<String>,
    normalizers: BTreeMap<String, hell_builtins::NormalizerId>,
    application_refs: BTreeSet<String>,
    divergence_candidates: Vec<JsonValue>,
    normalized_fingerprints: BTreeSet<String>,
    has_exact_evidence: bool,
}

fn collect_claim_target_evidence(
    context: &ClaimCellEvidenceContext<'_>,
    case: &DifferentialCase,
    target: &hell_testkit::EvidenceTargetV2,
    evidence: &mut ClaimCellEvidenceAccumulator,
) -> Result<(), String> {
    let bundle = native_observation_bundle(context.input, context.platform, case.id.as_ref());
    let Ok(classification) = hell_testkit::classify_retained_observation_bundle(&bundle, case)
    else {
        return Ok(());
    };
    let obligations = target
        .obligations
        .iter()
        .map(|obligation| obligation.0.as_ref())
        .collect::<Vec<_>>();
    let bundle_sha256 = record_digest(&bundle)?;
    evidence
        .references
        .push(claim_evidence_reference(&ClaimEvidenceReferenceInputs {
            retained_root: context.retained_root,
            bundle: &bundle,
            bundle_sha256: &bundle_sha256,
            case_id: case.id.as_ref(),
            obligations: &obligations,
            platform: context.platform,
            candidate: context.candidate,
            epoch: context.epoch,
        })?);
    match classification {
        hell_testkit::RetainedObservationClassification::Exact => {
            evidence.has_exact_evidence = true;
            evidence
                .observed
                .extend(obligations.iter().map(|value| (*value).to_owned()));
        }
        hell_testkit::RetainedObservationClassification::Normalized {
            normalizers,
            fingerprint_sha256,
            ..
        } => collect_normalized_claim_evidence(
            context,
            &bundle_sha256,
            &obligations,
            normalizers,
            fingerprint_sha256,
            evidence,
        )?,
        hell_testkit::RetainedObservationClassification::Mismatch {
            raw_mismatches,
            normalized_mismatches,
            fingerprint_sha256,
        } => {
            collect_mismatch_claim_evidence(
                context,
                case,
                &ClassifiedClaimMismatch {
                    bundle: &bundle,
                    bundle_sha256: &bundle_sha256,
                    raw: &raw_mismatches,
                    normalized: &normalized_mismatches,
                    fingerprint_sha256: &fingerprint_sha256,
                },
                evidence,
            )?;
        }
    }
    Ok(())
}

fn collect_normalized_claim_evidence(
    context: &ClaimCellEvidenceContext<'_>,
    bundle_sha256: &str,
    obligations: &[&str],
    normalizers: Vec<hell_builtins::NormalizerId>,
    fingerprint_sha256: hell_testkit::Digest,
    evidence: &mut ClaimCellEvidenceAccumulator,
) -> Result<(), String> {
    evidence
        .normalized_fingerprints
        .insert(fingerprint_sha256.hex());
    evidence
        .observed
        .extend(obligations.iter().map(|value| (*value).to_owned()));
    for normalizer in normalizers {
        evidence
            .normalizers
            .insert(normalizer.as_str().to_owned(), normalizer);
        for role in ["candidate", "oracle"] {
            evidence.application_refs.insert(normalizer_application_ref(
                context.builtin,
                context.dimension.as_str(),
                context.platform,
                bundle_sha256,
                role,
                normalizer.as_str(),
                "claim-stderr",
            )?);
        }
    }
    Ok(())
}

struct ClassifiedClaimMismatch<'a> {
    bundle: &'a Path,
    bundle_sha256: &'a str,
    raw: &'a [hell_testkit::RetainedMismatchFact],
    normalized: &'a [hell_testkit::RetainedMismatchFact],
    fingerprint_sha256: &'a hell_testkit::Digest,
}

fn collect_mismatch_claim_evidence(
    context: &ClaimCellEvidenceContext<'_>,
    case: &DifferentialCase,
    mismatch: &ClassifiedClaimMismatch<'_>,
    evidence: &mut ClaimCellEvidenceAccumulator,
) -> Result<(), String> {
    let descriptor = case
        .claim_evidence
        .as_ref()
        .ok_or_else(|| "mismatch case lost its claim descriptor".to_owned())?;
    let bundle_facts = divergence_bundle_facts(
        mismatch.bundle,
        case,
        context.builtin,
        context.dimension,
        mismatch.raw,
        mismatch.normalized,
    )?;
    evidence
        .divergence_candidates
        .push(mismatch_candidate_record(&MismatchCandidateInputs {
            builtin: context.builtin,
            dimension: context.dimension,
            platform: context.platform,
            case_id: case.id.as_ref(),
            case_source_sha256: &descriptor.source_sha256.hex(),
            evidence_ref: mismatch.bundle_sha256,
            evidence_path: &retained_relative_path(context.retained_root, mismatch.bundle)?,
            raw: mismatch.raw,
            normalized: mismatch.normalized,
            mismatch_fingerprint: &mismatch.fingerprint_sha256.hex(),
            bundle_facts: &bundle_facts,
        })?);
    Ok(())
}

struct ClaimEvidenceReferenceInputs<'a> {
    retained_root: &'a Path,
    bundle: &'a Path,
    bundle_sha256: &'a str,
    case_id: &'a str,
    obligations: &'a [&'a str],
    platform: &'a str,
    candidate: &'a str,
    epoch: &'a str,
}

fn claim_evidence_reference(
    inputs: &ClaimEvidenceReferenceInputs<'_>,
) -> Result<JsonValue, String> {
    Ok(JsonValue::Object(BTreeMap::from([
        (
            "assuranceEpochSha256".to_owned(),
            JsonValue::String(inputs.epoch.to_owned()),
        ),
        (
            "bundlePath".to_owned(),
            JsonValue::String(retained_relative_path(inputs.retained_root, inputs.bundle)?),
        ),
        (
            "bundleSha256".to_owned(),
            JsonValue::String(inputs.bundle_sha256.to_owned()),
        ),
        (
            "candidateSourceCommit".to_owned(),
            JsonValue::String(inputs.candidate.to_owned()),
        ),
        (
            "caseId".to_owned(),
            JsonValue::String(inputs.case_id.to_owned()),
        ),
        (
            "obligations".to_owned(),
            JsonValue::Array(
                inputs
                    .obligations
                    .iter()
                    .map(|obligation| JsonValue::String((*obligation).to_owned()))
                    .collect(),
            ),
        ),
        (
            "platform".to_owned(),
            JsonValue::String(inputs.platform.to_owned()),
        ),
        (
            "profile".to_owned(),
            JsonValue::String("upstream".to_owned()),
        ),
    ])))
}

struct ClaimCellEvidence {
    references: Vec<JsonValue>,
    observed: BTreeSet<String>,
    normalizers: Vec<String>,
    application_refs: Vec<String>,
    divergence_candidates: Vec<JsonValue>,
    normalized_fingerprints: BTreeSet<String>,
    has_exact_evidence: bool,
}

struct MismatchCandidateInputs<'a> {
    builtin: &'a str,
    dimension: CompatibilityDimension,
    platform: &'a str,
    case_id: &'a str,
    case_source_sha256: &'a str,
    evidence_ref: &'a str,
    evidence_path: &'a str,
    raw: &'a [hell_testkit::RetainedMismatchFact],
    normalized: &'a [hell_testkit::RetainedMismatchFact],
    mismatch_fingerprint: &'a str,
    bundle_facts: &'a DivergenceBundleFacts,
}

struct DivergenceBundleFacts {
    differing_paths: Vec<String>,
    candidate_implementation_id: String,
    candidate_source_location: String,
    candidate_source_sha256: String,
    baseline_implementation_id: JsonValue,
    baseline_source_identity: JsonValue,
    baseline_source_location: JsonValue,
    candidate_executable_sha256: String,
    baseline_executable_sha256: String,
    affected_examples: Vec<JsonValue>,
    normalizer_analysis: Vec<JsonValue>,
    objective_evidence: JsonValue,
}

fn divergence_bundle_facts(
    bundle: &Path,
    case: &DifferentialCase,
    builtin: &str,
    dimension: CompatibilityDimension,
    raw: &[hell_testkit::RetainedMismatchFact],
    normalized: &[hell_testkit::RetainedMismatchFact],
) -> Result<DivergenceBundleFacts, String> {
    let oracle_path = bundle.join("oracle").join("observation.json");
    let candidate_path = bundle.join("candidate").join("observation.json");
    let oracle = parse_json(&read_text(&oracle_path)?)?;
    let candidate = parse_json(&read_text(&candidate_path)?)?;
    let differing_paths = divergence_differing_paths(&oracle, &candidate, raw, normalized)?;
    let executable_identity = |observation: &JsonValue, role: &str| -> Result<String, String> {
        let identity = json_member(observation.object()?, "identity")?.object()?;
        if json_member(identity, "role")?.string()? != role {
            return Err(format!("divergence observation identity is not {role}"));
        }
        let executable = json_member(identity, "sha256")?.string()?.to_owned();
        require_digest(&executable, "divergence executable identity")?;
        Ok(executable)
    };
    let baseline_executable_sha256 = executable_identity(&oracle, "Oracle")?;
    let candidate_executable_sha256 = executable_identity(&candidate, "Candidate")?;
    let oracle_identity = json_member(oracle.object()?, "identity")?.object()?;
    let baseline_source_identity = JsonValue::Object(BTreeMap::from([
        (
            "acquisitionReceiptId".to_owned(),
            json_member(oracle_identity, "acquisitionReceiptId")?.clone(),
        ),
        (
            "acquisitionReceiptSha256".to_owned(),
            json_member(oracle_identity, "acquisitionReceiptSha256")?.clone(),
        ),
        (
            "acquisitionAttestationSha256".to_owned(),
            json_member(oracle_identity, "acquisitionAttestationSha256")?.clone(),
        ),
    ]));
    let (candidate_implementation_id, candidate_source_location, candidate_source_sha256) =
        builtin_implementation_source_facts(builtin)?;
    let normalizer_analysis = divergence_normalizer_analysis(case);
    let objective_evidence = divergence_objective_evidence(bundle, case, builtin, dimension)?;
    Ok(DivergenceBundleFacts {
        differing_paths: differing_paths.into_iter().collect(),
        candidate_implementation_id,
        candidate_source_location,
        candidate_source_sha256,
        baseline_implementation_id: JsonValue::Null,
        baseline_source_identity,
        baseline_source_location: JsonValue::Null,
        candidate_executable_sha256,
        baseline_executable_sha256,
        affected_examples: vec![JsonValue::Object(BTreeMap::from([
            ("caseId".to_owned(), JsonValue::String(case.id.to_string())),
            (
                "sourcePath".to_owned(),
                JsonValue::String("main.hell".to_owned()),
            ),
            (
                "sourceSha256".to_owned(),
                JsonValue::String(sha256_bytes(case.source.as_bytes()).hex()),
            ),
        ]))],
        normalizer_analysis,
        objective_evidence,
    })
}

fn divergence_objective_evidence(
    bundle: &Path,
    case: &DifferentialCase,
    builtin: &str,
    dimension: CompatibilityDimension,
) -> Result<JsonValue, String> {
    let native_root = bundle
        .ancestors()
        .nth(4)
        .ok_or_else(|| "divergence bundle lacks a native evidence root".to_owned())?;
    let platform_facts = divergence_platform_facts(native_root, case)?;
    let (prior_candidate, prior_state, prior_origin) =
        divergence_prior_candidate_evidence(native_root, bundle, case, builtin, dimension)?;
    let (profile_comparison, sandboxed_resolves) =
        divergence_profile_comparison(native_root, bundle, case)?;
    let (fix_prototype, derived_fixability) =
        divergence_fix_prototype_evidence(native_root, bundle, case, builtin, dimension)?;
    let automated_origin = if prior_origin == "baseline-inherent" {
        prior_origin
    } else if divergence_platform_facts_vary(&platform_facts)? {
        "platform-inherent"
    } else if sandboxed_resolves {
        "policy-driven"
    } else {
        prior_origin
    };
    Ok(JsonValue::Object(BTreeMap::from([
        ("schemaVersion".to_owned(), JsonValue::Number(1)),
        (
            "upstreamPlatformFacts".to_owned(),
            JsonValue::Array(platform_facts),
        ),
        ("profileComparison".to_owned(), profile_comparison),
        ("priorCandidateEvidence".to_owned(), prior_candidate),
        ("fixPrototypeEvidence".to_owned(), fix_prototype),
        (
            "neighboringBoundaryFacts".to_owned(),
            divergence_neighbor_facts(native_root, bundle, case, builtin, dimension)?,
        ),
        (
            "derivedPriorReleaseState".to_owned(),
            JsonValue::String(prior_state.to_owned()),
        ),
        (
            "derivedFixability".to_owned(),
            JsonValue::String(derived_fixability.clone()),
        ),
        (
            "automatedOriginClassification".to_owned(),
            JsonValue::String(automated_origin.to_owned()),
        ),
    ])))
}

fn divergence_fix_prototype_evidence(
    native_root: &Path,
    bundle: &Path,
    case: &DifferentialCase,
    builtin: &str,
    dimension: CompatibilityDimension,
) -> Result<(JsonValue, String), String> {
    let platform = bundle
        .ancestors()
        .nth(3)
        .and_then(Path::file_name)
        .and_then(OsStr::to_str)
        .ok_or_else(|| "divergence prototype platform is unavailable".to_owned())?;
    let directory = native_root
        .join(platform)
        .join("divergence-objective")
        .join(case.id.as_ref())
        .join("fix-prototype");
    let path = directory.join("evidence.json");
    let bytes = fs::read(&path)
        .map_err(|error| format!("cannot read divergence fix prototype evidence: {error}"))?;
    let text = std::str::from_utf8(&bytes)
        .map_err(|_| "divergence fix prototype evidence is not UTF-8".to_owned())?;
    let evidence = parse_json(text)?;
    if canonical_json_bytes(&evidence)? != bytes {
        return Err("divergence fix prototype evidence is not canonical JSON".to_owned());
    }
    let digest = sha256_bytes(&bytes).hex();
    if read_text(&directory.join("evidence.sha256"))? != format!("{digest}  evidence.json\n") {
        return Err("divergence fix prototype digest record changed".to_owned());
    }
    let root = repository_root()?;
    let manifest_path = root.join("compat").join("divergence-prototypes.json");
    let manifest = parse_divergence_prototype_manifest(&root, &manifest_path)?;
    let derived = verify_retained_divergence_prototype(
        &root,
        native_root,
        platform,
        case,
        builtin,
        dimension,
        &directory,
        &manifest,
        &evidence,
    )?;
    Ok((evidence, derived.to_owned()))
}

#[allow(clippy::too_many_arguments)]
fn verify_retained_divergence_prototype(
    root: &Path,
    native_root: &Path,
    platform: &str,
    case: &DifferentialCase,
    builtin: &str,
    dimension: CompatibilityDimension,
    directory: &Path,
    manifest: &DivergencePrototypeManifest,
    evidence: &JsonValue,
) -> Result<&'static str, String> {
    let record = evidence.object()?;
    let state = json_member(record, "state")?.string()?;
    if state == "attempted-unavailable" {
        exact_keys(
            record,
            &[
                "candidateCommit",
                "caseId",
                "derivedFixability",
                "elapsedMilliseconds",
                "manifestSha256",
                "policy",
                "reason",
                "schemaVersion",
                "state",
            ],
        )?;
        verify_divergence_prototype_common(root, case, manifest, record)?;
        if json_member(record, "reason")?.string()? != "no-reviewed-prototype-entry"
            || manifest.entries.contains_key(case.id.as_ref())
            || json_member(record, "elapsedMilliseconds")?.number()? != 0
            || json_member(record, "derivedFixability")?.string()? != "undetermined"
        {
            return Err("unavailable divergence prototype fact was substituted".to_owned());
        }
        return Ok("undetermined");
    }
    if state == "cost-exceeded"
        && json_member(record, "reason")?.string()? == "experiment-timeout-budget-exceeds-policy"
    {
        return verify_cost_exceeded_divergence_prototype(root, case, manifest, record);
    }
    if matches!(state, "attempted-failed" | "cost-exceeded") {
        return verify_failed_divergence_prototype(root, case, manifest, record);
    }
    verify_successful_divergence_prototype(
        root,
        native_root,
        platform,
        case,
        builtin,
        dimension,
        directory,
        manifest,
        record,
    )
}

fn verify_cost_exceeded_divergence_prototype(
    root: &Path,
    case: &DifferentialCase,
    manifest: &DivergencePrototypeManifest,
    record: &BTreeMap<String, JsonValue>,
) -> Result<&'static str, String> {
    exact_keys(
        record,
        &[
            "candidateCommit",
            "caseId",
            "derivedFixability",
            "estimatedExecutionMilliseconds",
            "manifestSha256",
            "policy",
            "reason",
            "schemaVersion",
            "state",
        ],
    )?;
    verify_divergence_prototype_common(root, case, manifest, record)?;
    let entry = manifest
        .entries
        .get(case.id.as_ref())
        .ok_or_else(|| "cost-exceeded prototype has no reviewed manifest entry".to_owned())?;
    let expected = divergence_prototype_experiment_budget_milliseconds(case, entry)?;
    if json_member(record, "estimatedExecutionMilliseconds")?.number()? != expected
        || expected < manifest.policy.elapsed_seconds.saturating_mul(1_000)
        || json_member(record, "reason")?.string()? != "experiment-timeout-budget-exceeds-policy"
        || json_member(record, "derivedFixability")?.string()? != "not-currently-fixable"
    {
        return Err("prototype cost-exceeded derivation was substituted".to_owned());
    }
    Ok("not-currently-fixable")
}

fn verify_divergence_prototype_common(
    root: &Path,
    case: &DifferentialCase,
    manifest: &DivergencePrototypeManifest,
    record: &BTreeMap<String, JsonValue>,
) -> Result<(), String> {
    if json_member(record, "schemaVersion")?.number()? != 1
        || json_member(record, "caseId")?.string()? != case.id.as_ref()
        || json_member(record, "candidateCommit")?.string()?
            != git_output(root, &["rev-parse", "HEAD"])?.trim()
        || json_member(record, "manifestSha256")?.string()? != manifest.sha256
        || json_member(record, "policy")? != &divergence_prototype_policy_json(manifest.policy)
    {
        return Err("divergence prototype common identity changed".to_owned());
    }
    Ok(())
}

fn verify_failed_divergence_prototype(
    root: &Path,
    case: &DifferentialCase,
    manifest: &DivergencePrototypeManifest,
    record: &BTreeMap<String, JsonValue>,
) -> Result<&'static str, String> {
    exact_keys(
        record,
        &[
            "baseTreeId",
            "baseTreeSha256",
            "buildStderrSha256",
            "buildStdoutSha256",
            "candidateCommit",
            "caseId",
            "derivedFixability",
            "elapsedMilliseconds",
            "manifestSha256",
            "patchSha256",
            "patchedTreeId",
            "patchedTreeSha256",
            "policy",
            "reason",
            "schemaVersion",
            "state",
        ],
    )?;
    verify_divergence_prototype_common(root, case, manifest, record)?;
    let entry = manifest
        .entries
        .get(case.id.as_ref())
        .ok_or_else(|| "failed prototype has no reviewed manifest entry".to_owned())?;
    for field in [
        "baseTreeSha256",
        "buildStderrSha256",
        "buildStdoutSha256",
        "patchedTreeSha256",
    ] {
        require_digest(json_member(record, field)?.string()?, "failed prototype")?;
    }
    for field in ["baseTreeId", "patchedTreeId"] {
        require_git_sha_text(json_member(record, field)?.string()?, "prototype tree")?;
        if sha256_bytes(json_member(record, field)?.string()?.as_bytes()).hex()
            != json_member(record, &format!("{}Sha256", field.trim_end_matches("Id")))?.string()?
        {
            return Err("failed prototype tree digest changed".to_owned());
        }
    }
    let state = json_member(record, "state")?.string()?;
    let reason = json_member(record, "reason")?.string()?;
    if json_member(record, "patchSha256")?.string()? != entry.patch_sha256
        || json_member(record, "derivedFixability")?.string()? != "undetermined"
        || !matches!(
            (state, reason),
            ("attempted-failed", "prototype-build-failed")
                | ("cost-exceeded", "prototype-build-timeout")
        )
    {
        return Err("failed prototype result is inconsistent".to_owned());
    }
    Ok("undetermined")
}

#[allow(clippy::too_many_arguments)]
fn verify_successful_divergence_prototype(
    root: &Path,
    native_root: &Path,
    platform: &str,
    case: &DifferentialCase,
    builtin: &str,
    dimension: CompatibilityDimension,
    directory: &Path,
    manifest: &DivergencePrototypeManifest,
    record: &BTreeMap<String, JsonValue>,
) -> Result<&'static str, String> {
    verify_successful_prototype_keys(record)?;
    verify_divergence_prototype_common(root, case, manifest, record)?;
    let entry = manifest
        .entries
        .get(case.id.as_ref())
        .ok_or_else(|| "executed prototype has no reviewed manifest entry".to_owned())?;
    verify_successful_prototype_manifest_join(root, builtin, dimension, entry, record)?;
    verify_successful_prototype_tree(root, entry, record)?;
    let executable_name = json_member(record, "prototypeExecutablePath")?.string()?;
    if executable_name != if cfg!(windows) { "hell.exe" } else { "hell" } {
        return Err("retained prototype executable name changed".to_owned());
    }
    let mut prototype = verify_executable(
        &directory.join(executable_name),
        ExecutableRole::Candidate,
        Some(
            Digest::from_hex(json_member(record, "prototypeExecutableSha256")?.string()?)
                .map_err(|error| format!("invalid prototype executable digest: {error}"))?,
        ),
        hell_builtins::LANGUAGE_VERSION,
    )
    .map_err(|error| format!("cannot reverify prototype executable: {error}"))?;
    let assurance_epoch = verify_retained_prototype_candidate_join(
        native_root,
        platform,
        case,
        builtin,
        dimension,
        record,
    )?;
    prototype.assurance_epoch_sha256 = Some(assurance_epoch);
    let (resolved, preserved) = verify_retained_prototype_experiments(
        native_root,
        platform,
        case,
        builtin,
        dimension,
        directory,
        &prototype,
        record,
    )?;
    let elapsed = json_member(record, "elapsedMilliseconds")?.number()?;
    let within_cost = elapsed <= manifest.policy.elapsed_seconds.saturating_mul(1_000);
    let succeeded = resolved && preserved && within_cost;
    let expected_result = if succeeded {
        "prototype-succeeded"
    } else if !within_cost {
        "cost-exceeded"
    } else if !resolved {
        "prototype-did-not-resolve"
    } else {
        "prototype-regressed-neighbor"
    };
    let expected_fixability = if succeeded {
        "fix-planned"
    } else {
        "undetermined"
    };
    if json_member(record, "currentMismatchResolved")?.boolean()? != resolved
        || json_member(record, "neighborsPreserved")?.boolean()? != preserved
        || json_member(record, "result")?.string()? != expected_result
        || json_member(record, "derivedFixability")?.string()? != expected_fixability
    {
        return Err("prototype outcome or fixability is not evidence-derived".to_owned());
    }
    Ok(expected_fixability)
}

fn verify_successful_prototype_keys(record: &BTreeMap<String, JsonValue>) -> Result<(), String> {
    exact_keys(
        record,
        &[
            "afterSourceSha256",
            "assuranceEpochSha256",
            "baseTreeId",
            "baseTreeSha256",
            "beforeSourceSha256",
            "buildDurationMilliseconds",
            "buildStderrSha256",
            "buildStdoutSha256",
            "builtin",
            "candidateCommit",
            "candidateExecutableSha256",
            "caseId",
            "currentCase",
            "currentMismatchResolved",
            "derivedFixability",
            "dimension",
            "elapsedMilliseconds",
            "manifestSha256",
            "neighborCases",
            "neighborsPreserved",
            "patchPath",
            "patchSha256",
            "patchedTreeId",
            "patchedTreeSha256",
            "planIssueNumber",
            "planOwner",
            "planRationale",
            "policy",
            "prototypeExecutablePath",
            "prototypeExecutableSha256",
            "result",
            "schemaVersion",
            "sourcePath",
            "state",
        ],
    )
}

fn verify_successful_prototype_manifest_join(
    root: &Path,
    builtin: &str,
    dimension: CompatibilityDimension,
    entry: &DivergencePrototypeEntry,
    record: &BTreeMap<String, JsonValue>,
) -> Result<(), String> {
    let patch_relative = entry
        .patch_path
        .strip_prefix(root)
        .map_err(|_| "prototype patch is outside repository".to_owned())?;
    let source_relative = entry
        .source_path
        .strip_prefix(root)
        .map_err(|_| "prototype source is outside repository".to_owned())?;
    if json_member(record, "builtin")?.string()? != builtin
        || json_member(record, "dimension")?.string()? != dimension.as_str()
        || json_member(record, "patchPath")?.string()? != path_text(patch_relative)?
        || json_member(record, "patchSha256")?.string()? != entry.patch_sha256
        || json_member(record, "sourcePath")?.string()? != path_text(source_relative)?
        || json_member(record, "beforeSourceSha256")?.string()? != entry.before_source_sha256
        || json_member(record, "afterSourceSha256")?.string()? != entry.after_source_sha256
        || json_member(record, "planIssueNumber")?.number()? != entry.plan_issue_number
        || json_member(record, "planOwner")?.string()? != entry.plan_owner
        || json_member(record, "planRationale")?.string()? != entry.plan_rationale
    {
        return Err("prototype evidence differs from reviewed manifest".to_owned());
    }
    for field in [
        "baseTreeSha256",
        "buildStderrSha256",
        "buildStdoutSha256",
        "candidateExecutableSha256",
        "patchedTreeSha256",
        "prototypeExecutableSha256",
    ] {
        require_digest(json_member(record, field)?.string()?, "prototype evidence")?;
    }
    Ok(())
}

fn verify_successful_prototype_tree(
    root: &Path,
    entry: &DivergencePrototypeEntry,
    record: &BTreeMap<String, JsonValue>,
) -> Result<(), String> {
    let base_tree = git_output(root, &["rev-parse", "HEAD^{tree}"])?;
    let base_tree = base_tree.trim();
    if json_member(record, "baseTreeId")?.string()? != base_tree
        || json_member(record, "baseTreeSha256")?.string()?
            != sha256_bytes(base_tree.as_bytes()).hex()
    {
        return Err("prototype base tree changed".to_owned());
    }
    let (patched_tree, patched_digest) = replay_divergence_prototype_tree(root, entry)?;
    if json_member(record, "patchedTreeId")?.string()? != patched_tree
        || json_member(record, "patchedTreeSha256")?.string()? != patched_digest
    {
        return Err("prototype patched tree changed under replay".to_owned());
    }
    Ok(())
}

fn replay_divergence_prototype_tree(
    root: &Path,
    entry: &DivergencePrototypeEntry,
) -> Result<(String, String), String> {
    let temporary = create_private_temp_directory("hell-divergence-prototype-replay")?;
    let worktree = temporary.join("subject");
    add_divergence_prototype_worktree(root, &worktree)?;
    let result = (|| {
        apply_divergence_prototype_patch(&worktree, &entry.patch_path)?;
        let source = entry
            .source_path
            .strip_prefix(root)
            .map_err(|_| "prototype source is outside repository".to_owned())?;
        divergence_prototype_tree_identity(&worktree, source)
    })();
    let cleanup = remove_divergence_prototype_worktree(root, &worktree);
    match (result, cleanup) {
        (Ok(value), Ok(())) => Ok(value),
        (Err(error), Ok(())) | (Ok(_), Err(error)) => Err(error),
        (Err(error), Err(cleanup)) => Err(format!(
            "{error}; prototype replay cleanup failed: {cleanup}"
        )),
    }
}

fn verify_retained_prototype_candidate_join(
    native_root: &Path,
    platform: &str,
    case: &DifferentialCase,
    builtin: &str,
    dimension: CompatibilityDimension,
    record: &BTreeMap<String, JsonValue>,
) -> Result<Digest, String> {
    let bundle = native_root
        .join(platform)
        .join("evidence")
        .join("observations")
        .join(case.id.as_ref());
    let classification = hell_testkit::classify_retained_observation_bundle(&bundle, case)
        .map_err(|error| format!("cannot classify prototype retained mismatch: {error}"))?;
    let hell_testkit::RetainedObservationClassification::Mismatch { .. } = classification else {
        return Err("prototype source bundle no longer mismatches".to_owned());
    };
    exact_case_target(case, builtin, dimension)?;
    let candidate_sha256 = retained_candidate_executable_sha256(&bundle)?;
    let assurance_epoch = retained_candidate_assurance_epoch(&bundle)?;
    if json_member(record, "candidateExecutableSha256")?.string()? != candidate_sha256.hex()
        || json_member(record, "assuranceEpochSha256")?.string()? != assurance_epoch.hex()
        || json_member(record, "prototypeExecutableSha256")?
            == json_member(record, "candidateExecutableSha256")?
    {
        return Err(
            "prototype executable does not rejoin the retained candidate boundary".to_owned(),
        );
    }
    Ok(assurance_epoch)
}

#[allow(clippy::too_many_arguments)]
fn verify_retained_prototype_experiments(
    native_root: &Path,
    platform: &str,
    case: &DifferentialCase,
    builtin: &str,
    dimension: CompatibilityDimension,
    directory: &Path,
    prototype: &ExecutableIdentity,
    record: &BTreeMap<String, JsonValue>,
) -> Result<(bool, bool), String> {
    let current_bundle = native_root
        .join(platform)
        .join("evidence")
        .join("observations")
        .join(case.id.as_ref());
    let current = verify_one_retained_prototype_experiment(
        case,
        prototype,
        &current_bundle,
        &directory.join("current"),
        json_member(record, "currentCase")?,
        false,
    )?;
    let mut cases = committed_differential_cases();
    crate::suite::bind_runtime_process_helper(&mut cases)?;
    let expected_neighbors = cases
        .iter()
        .filter(|neighbor| neighbor.id != case.id)
        .filter(|neighbor| {
            exact_case_target(neighbor, builtin, dimension)
                .is_ok_and(|target| !target.boundary_classes.is_empty())
        })
        .collect::<Vec<_>>();
    let retained_neighbors = json_member(record, "neighborCases")?.array()?;
    if retained_neighbors.len() != expected_neighbors.len() || retained_neighbors.is_empty() {
        return Err(
            "prototype experiment lacks the exhaustive same-target neighbor set".to_owned(),
        );
    }
    let mut preserved = true;
    for (neighbor, fact) in expected_neighbors.into_iter().zip(retained_neighbors) {
        let bundle = native_root
            .join(platform)
            .join("evidence")
            .join("observations")
            .join(neighbor.id.as_ref());
        preserved &= verify_one_retained_prototype_experiment(
            neighbor,
            prototype,
            &bundle,
            &directory.join("neighbors").join(neighbor.id.as_ref()),
            fact,
            true,
        )?;
    }
    Ok((current, preserved))
}

fn verify_one_retained_prototype_experiment(
    case: &DifferentialCase,
    prototype: &ExecutableIdentity,
    baseline_bundle: &Path,
    directory: &Path,
    value: &JsonValue,
    preserve_baseline: bool,
) -> Result<bool, String> {
    let fact = value.object()?;
    exact_keys(
        fact,
        &[
            "accepted",
            "baselineClassification",
            "baselineFingerprintSha256",
            "caseId",
            "prototypeClassification",
            "prototypeExecutableSha256",
            "prototypeExecutionInputSha256",
            "prototypeFingerprintSha256",
            "prototypeObservationSha256",
            "prototypePackageSha256",
            "sourceSha256",
        ],
    )?;
    let baseline = hell_testkit::classify_retained_observation_bundle(baseline_bundle, case)
        .map_err(|error| format!("cannot classify retained prototype baseline: {error}"))?;
    let mut profile_case = case.clone();
    profile_case
        .claim_evidence
        .as_mut()
        .ok_or_else(|| "retained prototype case is not reviewed".to_owned())?
        .profile = ExecutionProfile::Upstream;
    let classification = classify_retained_alternate_prototype(
        directory,
        &profile_case,
        baseline_bundle,
        prototype,
    )?;
    let (baseline_state, baseline_fingerprint) = retained_classification_identity(&baseline);
    let (prototype_state, prototype_fingerprint) =
        retained_classification_identity(&classification);
    let retained = hell_testkit::verify_retained_alternate_executable_observation_against_bundle(
        directory,
        &profile_case,
        baseline_bundle,
        ExecutionProfile::Upstream,
        prototype.sha256,
    )
    .map_err(|error| format!("cannot reverify retained prototype package: {error}"))?;
    let accepted = if preserve_baseline {
        retained_classification_identity(&baseline)
            == retained_classification_identity(&classification)
    } else {
        matches!(prototype_state, "exact" | "normalized")
    };
    if json_member(fact, "caseId")?.string()? != case.id.as_ref()
        || json_member(fact, "sourceSha256")?.string()?
            != sha256_bytes(case.source.as_bytes()).hex()
        || json_member(fact, "baselineClassification")?.string()? != baseline_state
        || json_member(fact, "baselineFingerprintSha256")?
            != &baseline_fingerprint.map_or(JsonValue::Null, JsonValue::String)
        || json_member(fact, "prototypeClassification")?.string()? != prototype_state
        || json_member(fact, "prototypeFingerprintSha256")?
            != &prototype_fingerprint.map_or(JsonValue::Null, JsonValue::String)
        || json_member(fact, "prototypeExecutableSha256")?.string()?
            != retained.executable_sha256.hex()
        || json_member(fact, "prototypeExecutionInputSha256")?.string()?
            != retained.execution_input_sha256.hex()
        || json_member(fact, "prototypeObservationSha256")?.string()?
            != retained.observation_sha256.hex()
        || json_member(fact, "prototypePackageSha256")?.string()? != retained.package_sha256.hex()
        || json_member(fact, "accepted")?.boolean()? != accepted
    {
        return Err("retained prototype experiment fact was substituted".to_owned());
    }
    Ok(accepted)
}

fn classify_retained_alternate_prototype(
    directory: &Path,
    case: &DifferentialCase,
    baseline_bundle: &Path,
    prototype: &ExecutableIdentity,
) -> Result<hell_testkit::RetainedObservationClassification, String> {
    hell_testkit::classify_retained_alternate_executable_observation_against_oracle(
        directory,
        case,
        baseline_bundle,
        ExecutionProfile::Upstream,
        prototype.sha256,
    )
    .map_err(|error| format!("cannot classify retained alternate prototype: {error}"))
}

fn divergence_profile_comparison(
    native_root: &Path,
    bundle: &Path,
    case: &DifferentialCase,
) -> Result<(JsonValue, bool), String> {
    let platform = bundle
        .ancestors()
        .nth(3)
        .and_then(Path::file_name)
        .and_then(OsStr::to_str)
        .ok_or_else(|| "divergence profile bundle platform is unavailable".to_owned())?;
    let profile_root = native_root
        .join(platform)
        .join("divergence-objective")
        .join(case.id.as_ref())
        .join("profiles");
    let current = hell_testkit::classify_retained_observation_bundle(bundle, case)
        .map_err(|error| format!("cannot classify divergence profile source bundle: {error}"))?;
    let mut facts = Vec::new();
    let mut classifications = Vec::new();
    for profile in [
        hell_builtins::ExecutionProfile::Upstream,
        hell_builtins::ExecutionProfile::Sandboxed,
    ] {
        let (fact, classification) =
            divergence_profile_fact(native_root, bundle, case, &profile_root, profile)?;
        facts.push(fact);
        classifications.push(classification);
    }
    if retained_classification_identity(&classifications[0])
        != retained_classification_identity(&current)
    {
        return Err(
            "explicit upstream profile observation differs from the retained mismatch".to_owned(),
        );
    }
    let relation = match &classifications[1] {
        hell_testkit::RetainedObservationClassification::Exact
        | hell_testkit::RetainedObservationClassification::Normalized { .. } => {
            "sandboxed-resolves-upstream-mismatch"
        }
        hell_testkit::RetainedObservationClassification::Mismatch {
            fingerprint_sha256, ..
        } if retained_classification_identity(&current).1.as_deref()
            == Some(fingerprint_sha256.hex().as_str()) =>
        {
            "same-mismatch-across-profiles"
        }
        hell_testkit::RetainedObservationClassification::Mismatch { .. } => {
            "changed-mismatch-under-sandboxed-profile"
        }
    };
    Ok((
        JsonValue::Object(BTreeMap::from([
            ("caseId".to_owned(), JsonValue::String(case.id.to_string())),
            (
                "platform".to_owned(),
                JsonValue::String(platform.to_owned()),
            ),
            ("profiles".to_owned(), JsonValue::Array(facts)),
            (
                "relation".to_owned(),
                JsonValue::String(relation.to_owned()),
            ),
            ("schemaVersion".to_owned(), JsonValue::Number(1)),
            (
                "state".to_owned(),
                JsonValue::String("executed-and-replayed".to_owned()),
            ),
        ])),
        relation == "sandboxed-resolves-upstream-mismatch",
    ))
}

fn divergence_profile_fact(
    native_root: &Path,
    bundle: &Path,
    case: &DifferentialCase,
    profile_root: &Path,
    profile: ExecutionProfile,
) -> Result<(JsonValue, hell_testkit::RetainedObservationClassification), String> {
    let mut profile_case = case.clone();
    profile_case
        .claim_evidence
        .as_mut()
        .ok_or_else(|| "divergence profile case is not reviewed".to_owned())?
        .profile = profile;
    let directory = profile_root.join(profile.as_str());
    let retained = hell_testkit::verify_retained_profile_observation_against_bundle(
        &directory,
        &profile_case,
        bundle,
        profile,
    )
    .map_err(|error| format!("cannot verify {} profile: {error}", profile.as_str()))?;
    let classification = hell_testkit::classify_retained_profile_observation_against_oracle(
        &directory,
        &profile_case,
        bundle,
        profile,
    )
    .map_err(|error| format!("cannot classify {} profile: {error}", profile.as_str()))?;
    let (state, fingerprint) = retained_classification_identity(&classification);
    Ok((
        JsonValue::Object(BTreeMap::from([
            (
                "classification".to_owned(),
                JsonValue::String(state.to_owned()),
            ),
            (
                "executableSha256".to_owned(),
                JsonValue::String(retained.executable_sha256.hex()),
            ),
            (
                "executionInputSha256".to_owned(),
                JsonValue::String(retained.execution_input_sha256.hex()),
            ),
            (
                "fingerprintSha256".to_owned(),
                fingerprint.map_or(JsonValue::Null, JsonValue::String),
            ),
            (
                "invocationSha256".to_owned(),
                JsonValue::String(retained.invocation_sha256.hex()),
            ),
            (
                "observationSha256".to_owned(),
                JsonValue::String(retained.observation_sha256.hex()),
            ),
            (
                "packagePath".to_owned(),
                JsonValue::String(retained_relative_path(native_root, &directory)?),
            ),
            (
                "packageSha256".to_owned(),
                JsonValue::String(retained.package_sha256.hex()),
            ),
            (
                "profile".to_owned(),
                JsonValue::String(profile.as_str().to_owned()),
            ),
            (
                "sourceSha256".to_owned(),
                JsonValue::String(retained.source_sha256.hex()),
            ),
        ])),
        classification,
    ))
}

fn divergence_platform_facts(
    native_root: &Path,
    case: &DifferentialCase,
) -> Result<Vec<JsonValue>, String> {
    let platforms = ["linux-amd64", "macos-arm64", "windows-amd64"];
    let mut platform_facts = Vec::new();
    for platform in platforms {
        let retained = native_root
            .join(platform)
            .join("evidence")
            .join("observations")
            .join(case.id.as_ref());
        let classification = hell_testkit::classify_retained_observation_bundle(&retained, case)
            .map_err(|error| format!("cannot classify {platform} divergence evidence: {error}"))?;
        let (state, fingerprint) = retained_classification_identity(&classification);
        platform_facts.push(JsonValue::Object(BTreeMap::from([
            (
                "platform".to_owned(),
                JsonValue::String(platform.to_owned()),
            ),
            (
                "profile".to_owned(),
                JsonValue::String("upstream".to_owned()),
            ),
            (
                "classification".to_owned(),
                JsonValue::String(state.to_owned()),
            ),
            (
                "fingerprintSha256".to_owned(),
                fingerprint.map_or(JsonValue::Null, JsonValue::String),
            ),
            (
                "bundlePath".to_owned(),
                JsonValue::String(retained_relative_path(native_root, &retained)?),
            ),
            (
                "bundleSha256".to_owned(),
                JsonValue::String(record_digest(&retained)?),
            ),
        ])));
    }
    Ok(platform_facts)
}

fn unavailable_objective_fact(reason: &str, inventory_sha256: &str) -> JsonValue {
    JsonValue::Object(BTreeMap::from([
        (
            "state".to_owned(),
            JsonValue::String("unavailable".to_owned()),
        ),
        ("reason".to_owned(), JsonValue::String(reason.to_owned())),
        (
            "evidenceInventorySha256".to_owned(),
            JsonValue::String(inventory_sha256.to_owned()),
        ),
    ]))
}

fn divergence_prior_candidate_evidence(
    native_root: &Path,
    bundle: &Path,
    case: &DifferentialCase,
    builtin: &str,
    dimension: CompatibilityDimension,
) -> Result<(JsonValue, &'static str, &'static str), String> {
    let evidence_root = native_root
        .parent()
        .ok_or_else(|| "native evidence root has no containing evidence directory".to_owned())?;
    let prior_root = evidence_root.join("prior-public");
    let availability_path = prior_root.join("availability.json");
    let availability = parse_json(&read_text(&availability_path)?)?;
    let availability = availability.object()?;
    let state = json_member(availability, "state")?.string()?;
    if state == "no-public-promotion-observed" {
        exact_keys(availability, &["publicBaseUrl", "schemaVersion", "state"])?;
        return Ok((
            unavailable_objective_fact(
                "authenticated-public-endpoint-had-no-prior-promotion",
                &record_digest(&availability_path)?,
            ),
            "unknown",
            "indeterminate",
        ));
    }
    exact_keys(
        availability,
        &[
            "acceptedDivergencesSha256",
            "assuranceEpochSha256",
            "candidateCommit",
            "publicBaseUrl",
            "recordSha256",
            "schemaVersion",
            "state",
        ],
    )?;
    if json_member(availability, "schemaVersion")?.number()? != 1
        || state != "available-signed-public-promotion"
    {
        return Err("prior public promotion availability is invalid".to_owned());
    }
    let base_url = json_member(availability, "publicBaseUrl")?.string()?;
    let record =
        crate::custody_ops::verify_retained_prior_public_transition(&prior_root, base_url)?;
    let record_sha256 = sha256_bytes(record.as_bytes()).hex();
    let divergences_path = prior_root.join("accepted-divergences.json");
    let divergences_sha256 = record_digest(&divergences_path)?;
    if record_sha256 != json_member(availability, "recordSha256")?.string()?
        || divergences_sha256 != json_member(availability, "acceptedDivergencesSha256")?.string()?
        || quoted_json_field(&record, "candidateCommit")?
            != json_member(availability, "candidateCommit")?.string()?
        || quoted_json_field(&record, "assuranceEpochSha256")?
            != json_member(availability, "assuranceEpochSha256")?.string()?
    {
        return Err("prior public promotion availability binding changed".to_owned());
    }
    divergence_prior_behavior(&PriorBehaviorInputs {
        divergences_path: &divergences_path,
        bundle,
        case,
        builtin,
        dimension,
        availability,
        record_sha256: &record_sha256,
        divergences_sha256: &divergences_sha256,
    })
}

fn quoted_json_field(document: &str, field: &str) -> Result<String, String> {
    let parsed = parse_json(document)?;
    Ok(json_member(parsed.object()?, field)?.string()?.to_owned())
}

struct PriorBehaviorInputs<'a> {
    divergences_path: &'a Path,
    bundle: &'a Path,
    case: &'a DifferentialCase,
    builtin: &'a str,
    dimension: CompatibilityDimension,
    availability: &'a BTreeMap<String, JsonValue>,
    record_sha256: &'a str,
    divergences_sha256: &'a str,
}

struct PriorDivergenceMatchInputs<'a> {
    case_id: &'a str,
    builtin: &'a str,
    dimension: &'a str,
    platform: &'a str,
    current_fingerprint: &'a str,
    current_source_sha256: &'a str,
}

struct PriorDivergenceResolution {
    same: bool,
    divergence_id: Option<String>,
}

fn verified_prior_divergence_details(
    path: &Path,
    availability: &BTreeMap<String, JsonValue>,
) -> Result<JsonValue, String> {
    let bytes =
        fs::read(path).map_err(|error| format!("cannot read prior public divergences: {error}"))?;
    let text = std::str::from_utf8(&bytes)
        .map_err(|_| "prior public divergences are not UTF-8".to_owned())?;
    let document = parse_json(text)?;
    if canonical_json_bytes(&document)? != bytes {
        return Err("prior public divergences are not canonical JSON".to_owned());
    }
    let details = document.object()?;
    exact_keys(
        details,
        &[
            "activeDivergences",
            "approvedDivergences",
            "assuranceEpochSha256",
            "candidateSourceCommit",
            "expiredDivergences",
            "fingerprintMismatches",
            "missingImpactApprovals",
            "proposedRecords",
            "records",
            "schemaVersion",
            "wildcardScopes",
        ],
    )?;
    if json_member(details, "candidateSourceCommit")?
        != json_member(availability, "candidateCommit")?
        || json_member(details, "assuranceEpochSha256")?
            != json_member(availability, "assuranceEpochSha256")?
        || !json_member(details, "proposedRecords")?.array()?.is_empty()
        || json_member(details, "schemaVersion")?.number()? != 2
        || json_member(details, "activeDivergences")?.number()?
            != u64::try_from(json_member(details, "records")?.array()?.len())
                .map_err(|_| "prior divergence count exceeds u64".to_owned())?
        || json_member(details, "approvedDivergences")?
            != json_member(details, "activeDivergences")?
        || [
            "expiredDivergences",
            "fingerprintMismatches",
            "missingImpactApprovals",
            "wildcardScopes",
        ]
        .into_iter()
        .any(|field| json_member(details, field).and_then(JsonValue::number) != Ok(0))
    {
        return Err("prior public divergence identity or approval state is invalid".to_owned());
    }
    Ok(document)
}

fn divergence_prior_behavior(
    inputs: &PriorBehaviorInputs<'_>,
) -> Result<(JsonValue, &'static str, &'static str), String> {
    let document = verified_prior_divergence_details(inputs.divergences_path, inputs.availability)?;
    let details = document.object()?;
    let classification =
        hell_testkit::classify_retained_observation_bundle(inputs.bundle, inputs.case)
            .map_err(|error| format!("cannot classify current prior comparison bundle: {error}"))?;
    let hell_testkit::RetainedObservationClassification::Mismatch {
        fingerprint_sha256, ..
    } = classification
    else {
        return Err("prior comparison subject is no longer a mismatch".to_owned());
    };
    let platform = inputs
        .bundle
        .ancestors()
        .nth(3)
        .and_then(Path::file_name)
        .and_then(OsStr::to_str)
        .ok_or_else(|| "prior comparison bundle platform is unavailable".to_owned())?;
    let current_fingerprint = fingerprint_sha256.hex();
    let current_source_sha256 = sha256_bytes(inputs.case.source.as_bytes()).hex();
    let resolution = resolve_prior_divergence(
        details,
        &PriorDivergenceMatchInputs {
            case_id: inputs.case.id.as_ref(),
            builtin: inputs.builtin,
            dimension: inputs.dimension.as_str(),
            platform,
            current_fingerprint: &current_fingerprint,
            current_source_sha256: &current_source_sha256,
        },
    )?;
    let prior_id = resolution
        .divergence_id
        .map_or(JsonValue::Null, JsonValue::String);
    let evidence = JsonValue::Object(BTreeMap::from([
        (
            "state".to_owned(),
            JsonValue::String("available".to_owned()),
        ),
        (
            "priorCandidateCommit".to_owned(),
            json_member(inputs.availability, "candidateCommit")?.clone(),
        ),
        (
            "priorAssuranceEpochSha256".to_owned(),
            json_member(inputs.availability, "assuranceEpochSha256")?.clone(),
        ),
        (
            "transitionSha256".to_owned(),
            JsonValue::String(inputs.record_sha256.to_owned()),
        ),
        (
            "divergenceReportSha256".to_owned(),
            JsonValue::String(inputs.divergences_sha256.to_owned()),
        ),
        (
            "currentMismatchFingerprint".to_owned(),
            JsonValue::String(current_fingerprint),
        ),
        (
            "currentCaseSourceSha256".to_owned(),
            JsonValue::String(current_source_sha256),
        ),
        ("priorDivergenceId".to_owned(), prior_id),
        (
            "behaviorState".to_owned(),
            JsonValue::String(
                if resolution.same {
                    "same-accepted-divergence"
                } else {
                    "prior-behavior-unresolved"
                }
                .to_owned(),
            ),
        ),
    ]));
    Ok(if resolution.same {
        (evidence, "present", "baseline-inherent")
    } else {
        (evidence, "unknown", "indeterminate")
    })
}

fn resolve_prior_divergence(
    details: &BTreeMap<String, JsonValue>,
    inputs: &PriorDivergenceMatchInputs<'_>,
) -> Result<PriorDivergenceResolution, String> {
    let records = json_member(details, "records")?
        .array()?
        .iter()
        .map(JsonValue::object)
        .collect::<Result<Vec<_>, _>>()?;
    let scoped = records
        .into_iter()
        .filter(|record| {
            json_member(record, "caseId").and_then(JsonValue::string) == Ok(inputs.case_id)
                && json_member(record, "builtin").and_then(JsonValue::string) == Ok(inputs.builtin)
                && json_member(record, "dimension").and_then(JsonValue::string)
                    == Ok(inputs.dimension)
                && json_member(record, "platform").and_then(JsonValue::string)
                    == Ok(inputs.platform)
                && json_member(record, "profile").and_then(JsonValue::string) == Ok("upstream")
        })
        .collect::<Vec<_>>();
    if scoped.len() > 1 {
        return Err("prior public divergences repeat one exact claim case".to_owned());
    }
    let Some(prior) = scoped.first().copied() else {
        return Ok(PriorDivergenceResolution {
            same: false,
            divergence_id: None,
        });
    };
    let same = json_member(prior, "mismatchFingerprint")?.string()? == inputs.current_fingerprint
        && json_member(prior, "mismatchEvidence")?
            .object()
            .and_then(|evidence| json_member(evidence, "caseSourceSha256"))?
            .string()?
            == inputs.current_source_sha256;
    let divergence_id = if same {
        let value = json_member(prior, "divergenceId")?.string()?;
        require_digest(value, "prior divergence ID")?;
        Some(value.to_owned())
    } else {
        None
    };
    Ok(PriorDivergenceResolution {
        same,
        divergence_id,
    })
}

fn retained_classification_identity(
    classification: &hell_testkit::RetainedObservationClassification,
) -> (&'static str, Option<String>) {
    match classification {
        hell_testkit::RetainedObservationClassification::Exact => ("exact", None),
        hell_testkit::RetainedObservationClassification::Normalized {
            fingerprint_sha256, ..
        } => ("normalized", Some(fingerprint_sha256.hex())),
        hell_testkit::RetainedObservationClassification::Mismatch {
            fingerprint_sha256, ..
        } => ("mismatch", Some(fingerprint_sha256.hex())),
    }
}

fn divergence_neighbor_facts(
    native_root: &Path,
    bundle: &Path,
    case: &DifferentialCase,
    builtin: &str,
    dimension: CompatibilityDimension,
) -> Result<JsonValue, String> {
    let platform = bundle
        .ancestors()
        .nth(3)
        .and_then(Path::file_name)
        .and_then(OsStr::to_str)
        .ok_or_else(|| "divergence bundle platform is unavailable".to_owned())?;
    let mut cases = committed_differential_cases();
    crate::suite::bind_runtime_process_helper(&mut cases)?;
    let target = exact_case_target(case, builtin, dimension)?;
    let source_boundaries = target
        .boundary_classes
        .iter()
        .map(AsRef::as_ref)
        .collect::<BTreeSet<_>>();
    if source_boundaries.is_empty() {
        return Err("divergence target has no reviewed boundary classes".to_owned());
    }
    let mut facts = Vec::new();
    for neighbor in cases.iter().filter(|neighbor| neighbor.id != case.id) {
        let Ok(neighbor_target) = exact_case_target(neighbor, builtin, dimension) else {
            continue;
        };
        let neighbor_boundaries = neighbor_target
            .boundary_classes
            .iter()
            .map(AsRef::as_ref)
            .collect::<BTreeSet<_>>();
        if neighbor_boundaries.is_empty() {
            continue;
        }
        facts.push(divergence_neighbor_fact(
            native_root,
            platform,
            neighbor,
            builtin,
            dimension,
            neighbor_boundaries,
        )?);
    }
    if facts.is_empty() {
        return Err("divergence objective evidence has no neighboring boundary cases".to_owned());
    }
    Ok(JsonValue::Object(BTreeMap::from([
        ("schemaVersion".to_owned(), JsonValue::Number(1)),
        (
            "sourceCaseId".to_owned(),
            JsonValue::String(case.id.to_string()),
        ),
        ("builtin".to_owned(), JsonValue::String(builtin.to_owned())),
        (
            "dimension".to_owned(),
            JsonValue::String(dimension.as_str().to_owned()),
        ),
        (
            "sourceBoundaryClasses".to_owned(),
            JsonValue::Array(
                source_boundaries
                    .into_iter()
                    .map(|boundary| JsonValue::String(boundary.to_owned()))
                    .collect(),
            ),
        ),
        ("cases".to_owned(), JsonValue::Array(facts)),
    ])))
}

fn divergence_neighbor_fact(
    native_root: &Path,
    platform: &str,
    neighbor: &DifferentialCase,
    builtin: &str,
    dimension: CompatibilityDimension,
    boundaries: BTreeSet<&str>,
) -> Result<JsonValue, String> {
    let retained = native_root
        .join(platform)
        .join("evidence")
        .join("observations")
        .join(neighbor.id.as_ref());
    let classification = hell_testkit::classify_retained_observation_bundle(&retained, neighbor)
        .map_err(|error| {
            format!(
                "cannot classify neighboring case {:?}: {error}",
                neighbor.id
            )
        })?;
    let (state, fingerprint) = retained_classification_identity(&classification);
    Ok(JsonValue::Object(BTreeMap::from([
        ("builtin".to_owned(), JsonValue::String(builtin.to_owned())),
        (
            "caseId".to_owned(),
            JsonValue::String(neighbor.id.to_string()),
        ),
        (
            "dimension".to_owned(),
            JsonValue::String(dimension.as_str().to_owned()),
        ),
        (
            "boundaryClasses".to_owned(),
            JsonValue::Array(
                boundaries
                    .into_iter()
                    .map(|boundary| JsonValue::String(boundary.to_owned()))
                    .collect(),
            ),
        ),
        (
            "sourceSha256".to_owned(),
            JsonValue::String(sha256_bytes(neighbor.source.as_bytes()).hex()),
        ),
        (
            "classification".to_owned(),
            JsonValue::String(state.to_owned()),
        ),
        (
            "fingerprintSha256".to_owned(),
            fingerprint.map_or(JsonValue::Null, JsonValue::String),
        ),
        (
            "bundlePath".to_owned(),
            JsonValue::String(retained_relative_path(native_root, &retained)?),
        ),
        (
            "bundleSha256".to_owned(),
            JsonValue::String(record_digest(&retained)?),
        ),
    ])))
}

fn exact_case_target<'a>(
    case: &'a DifferentialCase,
    builtin: &str,
    dimension: CompatibilityDimension,
) -> Result<&'a hell_testkit::EvidenceTargetV2, String> {
    let descriptor = case
        .claim_evidence
        .as_ref()
        .ok_or_else(|| format!("case {:?} has no reviewed claim evidence", case.id))?;
    let targets = descriptor
        .semantic_targets
        .iter()
        .filter(|target| target.builtin.as_ref() == builtin && target.dimension == dimension)
        .collect::<Vec<_>>();
    match targets.as_slice() {
        [target] => Ok(*target),
        [] => Err(format!(
            "case {:?} has no exact {builtin}/{} target",
            case.id,
            dimension.as_str()
        )),
        _ => Err(format!(
            "case {:?} repeats the {builtin}/{} target",
            case.id,
            dimension.as_str()
        )),
    }
}

fn divergence_differing_paths(
    oracle: &JsonValue,
    candidate: &JsonValue,
    raw: &[hell_testkit::RetainedMismatchFact],
    normalized: &[hell_testkit::RetainedMismatchFact],
) -> Result<Vec<String>, String> {
    let categories = raw
        .iter()
        .chain(normalized)
        .map(|fact| mismatch_kind_name(fact.category))
        .collect::<BTreeSet<_>>();
    let mut paths = BTreeSet::new();
    for (category, field) in [
        (hell_testkit::MismatchKind::Timeout, "timedOut"),
        (hell_testkit::MismatchKind::ExitStatus, "status"),
        (hell_testkit::MismatchKind::Stdout, "stdout"),
        (hell_testkit::MismatchKind::Stderr, "stderr"),
        (hell_testkit::MismatchKind::Diagnostic, "diagnostic"),
        (hell_testkit::MismatchKind::Filesystem, "filesystem"),
    ] {
        if categories.contains(mismatch_kind_name(category)) {
            collect_changed_json_paths(
                json_member(oracle.object()?, field)?,
                json_member(candidate.object()?, field)?,
                &format!("observation.{field}"),
                &mut paths,
            );
        }
    }
    for field in ["semanticTypedResultBuiltinId", "semanticTypedResultSha256"] {
        let oracle_value = json_member(oracle.object()?, field)?;
        let candidate_value = json_member(candidate.object()?, field)?;
        if oracle_value != &JsonValue::Null
            && candidate_value != &JsonValue::Null
            && oracle_value != candidate_value
        {
            collect_changed_json_paths(
                oracle_value,
                candidate_value,
                &format!("observation.{field}"),
                &mut paths,
            );
        }
    }
    if paths.is_empty() {
        return Err("mismatch bundle has no structured differing observation paths".to_owned());
    }
    Ok(paths.into_iter().collect())
}

fn divergence_normalizer_analysis(case: &DifferentialCase) -> Vec<JsonValue> {
    hell_builtins::NormalizerId::ALL
        .iter()
        .map(|normalizer| {
            let (applicable, state, reason) = match normalizer {
                hell_builtins::NormalizerId::DiagnosticSandboxPathV1 => (
                    false,
                    "ineligible",
                    "harness-only normalizer cannot justify a compatibility claim divergence",
                ),
                hell_builtins::NormalizerId::DiagnosticPathSeparatorV1
                    if case.normalization.normalize_path_separators => (
                        true,
                        "replayed-mismatch-remains",
                        "declared claim normalizer was replayed and normalized mismatch facts remain",
                    ),
                hell_builtins::NormalizerId::DiagnosticPathSeparatorV1 => (
                    false,
                    "not-declared",
                    "case descriptor does not authorize path-separator normalization",
                ),
            };
            JsonValue::Object(BTreeMap::from([
                (
                    "normalizerId".to_owned(),
                    JsonValue::String(normalizer.as_str().to_owned()),
                ),
                ("applicable".to_owned(), JsonValue::Bool(applicable)),
                ("resolutionState".to_owned(), JsonValue::String(state.to_owned())),
                ("reason".to_owned(), JsonValue::String(reason.to_owned())),
            ]))
        })
        .collect()
}

fn builtin_implementation_source_facts(builtin: &str) -> Result<(String, String, String), String> {
    let spec = hell_builtins::lookup(builtin)
        .ok_or_else(|| format!("divergence names unknown builtin {builtin:?}"))?;
    let implementation = spec
        .implementation
        .ok_or_else(|| format!("divergence builtin {builtin:?} has no implementation"))?;
    let repository = repository_root()?;
    let (source_root, marker) = implementation_source_authority(builtin, implementation)?;
    let source_root = repository.join(source_root);
    let mut matches = Vec::new();
    for path in rust_source_files(&source_root, "implementation source")? {
        let source = read_text(&path)?;
        for (index, _) in source
            .lines()
            .enumerate()
            .filter(|(_, line)| marker.matches(line))
        {
            matches.push((path.clone(), index.saturating_add(1), source.clone()));
        }
    }
    let [(path, line, source)] = matches.as_slice() else {
        return Err(format!(
            "builtin implementation {implementation:?} does not resolve to one runtime source location"
        ));
    };
    let relative = path
        .strip_prefix(&repository)
        .map_err(|_| "runtime implementation source escaped the repository".to_owned())?;
    Ok((
        implementation.to_owned(),
        format!("{}:{line}", path_text(relative)?),
        sha256_bytes(source.as_bytes()).hex(),
    ))
}

enum ImplementationSourceMarker {
    RuntimeDispatch(String),
    CompilerSpecialization(&'static str),
}

impl ImplementationSourceMarker {
    fn matches(&self, line: &str) -> bool {
        match self {
            Self::RuntimeDispatch(implementation) => {
                let quoted = format!("\"{implementation}\"");
                line.contains(&quoted) && line.contains("=>")
            }
            Self::CompilerSpecialization(marker) => line.contains(marker),
        }
    }
}

fn implementation_source_authority(
    builtin: &str,
    implementation: &str,
) -> Result<(PathBuf, ImplementationSourceMarker), String> {
    let crates = PathBuf::from("crates");
    match implementation {
        "record_get_specialized" => Ok((
            crates.join("hell-compiler").join("src"),
            ImplementationSourceMarker::CompilerSpecialization("\"Record.get\" => ("),
        )),
        "record_set_specialized" => Ok((
            crates.join("hell-compiler").join("src"),
            ImplementationSourceMarker::CompilerSpecialization("\"Record.set\" =>"),
        )),
        "record_modify_specialized" => Ok((
            crates.join("hell-compiler").join("src"),
            ImplementationSourceMarker::CompilerSpecialization("\"Record.modify\" =>"),
        )),
        implementation if implementation.ends_with("_specialized") => Err(format!(
            "builtin {builtin:?} has an unregistered compiler-specialized implementation {implementation:?}"
        )),
        _ => Ok((
            crates.join("hell-runtime").join("src"),
            ImplementationSourceMarker::RuntimeDispatch(implementation.to_owned()),
        )),
    }
}

fn rust_source_files(directory: &Path, label: &str) -> Result<Vec<PathBuf>, String> {
    let mut files = Vec::new();
    let mut entries = fs::read_dir(directory)
        .map_err(|error| format!("cannot inventory {}: {error}", directory.display()))?
        .collect::<Result<Vec<_>, _>>()
        .map_err(|error| format!("cannot inventory {}: {error}", directory.display()))?;
    entries.sort_by_key(std::fs::DirEntry::file_name);
    for entry in entries {
        let file_type = entry
            .file_type()
            .map_err(|error| format!("cannot inspect {}: {error}", entry.path().display()))?;
        if file_type.is_symlink() {
            return Err(format!("{label} inventory contains a symbolic link"));
        }
        if file_type.is_dir() {
            files.extend(rust_source_files(&entry.path(), label)?);
        } else if file_type.is_file() && entry.path().extension() == Some(OsStr::new("rs")) {
            files.push(entry.path());
        }
    }
    Ok(files)
}

fn mismatch_candidate_record(inputs: &MismatchCandidateInputs<'_>) -> Result<JsonValue, String> {
    let mut record = mismatch_candidate_evidence_fields(inputs)?;
    for (field, value) in [
        ("builtin", inputs.builtin),
        ("caseId", inputs.case_id),
        ("caseSourceSha256", inputs.case_source_sha256),
        ("dimension", inputs.dimension.as_str()),
        ("evidencePath", inputs.evidence_path),
        ("evidenceRef", inputs.evidence_ref),
        ("platform", inputs.platform),
        ("profile", "upstream"),
        ("mismatchFingerprint", inputs.mismatch_fingerprint),
    ] {
        record.insert(field.to_owned(), JsonValue::String(value.to_owned()));
    }
    Ok(JsonValue::Object(record))
}

fn mismatch_candidate_evidence_fields(
    inputs: &MismatchCandidateInputs<'_>,
) -> Result<BTreeMap<String, JsonValue>, String> {
    let category_names = inputs
        .raw
        .iter()
        .chain(inputs.normalized)
        .map(|fact| mismatch_kind_name(fact.category).to_owned())
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<BTreeSet<_>>();
    let (recommended_impact_tier, recommended_expiry_days) = divergence_recommendation(
        inputs.builtin,
        inputs.dimension.as_str(),
        &category_names,
        &inputs.bundle_facts.differing_paths,
    )?;
    let mut fields = mismatch_candidate_source_fields(inputs)?;
    fields.extend(mismatch_candidate_comparison_fields(
        inputs,
        &category_names,
    )?);
    fields.extend(mismatch_candidate_review_fields(
        inputs,
        &category_names,
        recommended_impact_tier,
        recommended_expiry_days,
    ));
    Ok(fields)
}

fn mismatch_candidate_source_fields(
    inputs: &MismatchCandidateInputs<'_>,
) -> Result<BTreeMap<String, JsonValue>, String> {
    let observation_path = |role: &str| {
        path_text(
            &PathBuf::from(inputs.evidence_path)
                .join(role)
                .join("observation.json"),
        )
    };
    Ok(BTreeMap::from([
        (
            "affectedCaseIds".to_owned(),
            JsonValue::Array(vec![JsonValue::String(inputs.case_id.to_owned())]),
        ),
        (
            "affectedExamples".to_owned(),
            JsonValue::Array(inputs.bundle_facts.affected_examples.clone()),
        ),
        (
            "baselineImplementationId".to_owned(),
            inputs.bundle_facts.baseline_implementation_id.clone(),
        ),
        (
            "baselineSourceLocation".to_owned(),
            inputs.bundle_facts.baseline_source_location.clone(),
        ),
        (
            "baselineSourceIdentity".to_owned(),
            inputs.bundle_facts.baseline_source_identity.clone(),
        ),
        (
            "baselineExecutableSha256".to_owned(),
            JsonValue::String(inputs.bundle_facts.baseline_executable_sha256.clone()),
        ),
        (
            "baselineObservationPath".to_owned(),
            JsonValue::String(observation_path("oracle")?),
        ),
        (
            "candidateImplementationId".to_owned(),
            JsonValue::String(inputs.bundle_facts.candidate_implementation_id.clone()),
        ),
        (
            "candidateSourceLocation".to_owned(),
            JsonValue::String(inputs.bundle_facts.candidate_source_location.clone()),
        ),
        (
            "candidateSourceSha256".to_owned(),
            JsonValue::String(inputs.bundle_facts.candidate_source_sha256.clone()),
        ),
        (
            "candidateExecutableSha256".to_owned(),
            JsonValue::String(inputs.bundle_facts.candidate_executable_sha256.clone()),
        ),
        (
            "candidateObservationPath".to_owned(),
            JsonValue::String(observation_path("candidate")?),
        ),
        (
            "objectiveEvidence".to_owned(),
            inputs.bundle_facts.objective_evidence.clone(),
        ),
    ]))
}

fn mismatch_candidate_comparison_fields(
    inputs: &MismatchCandidateInputs<'_>,
    category_names: &BTreeSet<String>,
) -> Result<BTreeMap<String, JsonValue>, String> {
    Ok(BTreeMap::from([
        (
            "rawObservationSha256".to_owned(),
            JsonValue::String(mismatch_fact_set_digest(inputs.raw)?),
        ),
        (
            "normalizedObservationSha256".to_owned(),
            JsonValue::String(mismatch_fact_set_digest(inputs.normalized)?),
        ),
        (
            "mismatchCategories".to_owned(),
            JsonValue::Array(
                category_names
                    .iter()
                    .cloned()
                    .map(JsonValue::String)
                    .collect(),
            ),
        ),
        (
            "differingPaths".to_owned(),
            JsonValue::Array(
                inputs
                    .bundle_facts
                    .differing_paths
                    .iter()
                    .cloned()
                    .map(JsonValue::String)
                    .collect(),
            ),
        ),
        (
            "normalizedMismatchFacts".to_owned(),
            JsonValue::Array(mismatch_fact_values(inputs.normalized)),
        ),
        (
            "normalizerSafetyEvidence".to_owned(),
            JsonValue::String("configured-normalizers-do-not-resolve".to_owned()),
        ),
        (
            "normalizerAnalysis".to_owned(),
            JsonValue::Array(inputs.bundle_facts.normalizer_analysis.clone()),
        ),
        (
            "potentialNormalizerIds".to_owned(),
            JsonValue::Array(
                hell_builtins::NormalizerId::ALL
                    .iter()
                    .map(|normalizer| JsonValue::String(normalizer.as_str().to_owned()))
                    .collect(),
            ),
        ),
        (
            "rawMismatchFacts".to_owned(),
            JsonValue::Array(mismatch_fact_values(inputs.raw)),
        ),
    ]))
}

fn mismatch_candidate_review_fields(
    inputs: &MismatchCandidateInputs<'_>,
    category_names: &BTreeSet<String>,
    recommended_impact_tier: &str,
    recommended_expiry_days: u64,
) -> BTreeMap<String, JsonValue> {
    BTreeMap::from([
        (
            "recommendedExpiryDays".to_owned(),
            JsonValue::Number(recommended_expiry_days),
        ),
        (
            "recommendedImpactTier".to_owned(),
            JsonValue::String(recommended_impact_tier.to_owned()),
        ),
        (
            "userImpactTemplate".to_owned(),
            JsonValue::String(format!(
                "{} compatibility for {} on {} differs from the retained baseline in: {}.",
                inputs.dimension.as_str(),
                inputs.builtin,
                inputs.platform,
                category_names
                    .iter()
                    .cloned()
                    .collect::<Vec<_>>()
                    .join(", ")
            )),
        ),
    ])
}

fn divergence_recommendation(
    builtin: &str,
    dimension: &str,
    categories: &BTreeSet<String>,
    differing_paths: &[String],
) -> Result<(&'static str, u64), String> {
    let spec = hell_builtins::lookup(builtin)
        .ok_or_else(|| format!("divergence names unknown builtin {builtin:?}"))?;
    let assurance = spec.assurance_metadata();
    if assurance.capabilities.iter().any(|capability| {
        matches!(
            capability,
            hell_builtins::AssuranceCapability::Network
                | hell_builtins::AssuranceCapability::Filesystem
        )
    }) {
        return Ok(("critical", 14));
    }
    if matches!(dimension, "effects" | "concurrency" | "resource-behavior")
        && categories
            .iter()
            .any(|category| matches!(category.as_str(), "timeout" | "filesystem" | "exit-status"))
    {
        return Ok(("critical", 14));
    }
    let changes_typed_semantics = differing_paths.iter().any(|path| {
        matches!(
            path.as_str(),
            "observation.semanticTypedResultBuiltinId" | "observation.semanticTypedResultSha256"
        )
    });
    let semantic_family_requires_high_review = matches!(
        assurance.semantic_family,
        "Int" | "Word" | "Float" | "List" | "Map" | "Set" | "Vector"
    );
    if changes_typed_semantics
        || (categories.contains("stdout")
            && (dimension == "pure-runtime" || semantic_family_requires_high_review))
    {
        return Ok(("high", 30));
    }
    if categories
        .iter()
        .any(|category| matches!(category.as_str(), "diagnostic" | "filesystem" | "timeout"))
    {
        Ok(("high", 30))
    } else if categories
        .iter()
        .any(|category| matches!(category.as_str(), "exit-status" | "stderr"))
    {
        Ok(("medium", 60))
    } else {
        Ok(("low", 90))
    }
}

fn mismatch_fact_set_digest(
    facts: &[hell_testkit::RetainedMismatchFact],
) -> Result<String, String> {
    canonical_json_digest(&JsonValue::Array(mismatch_fact_values(facts)))
}

fn mismatch_fact_values(facts: &[hell_testkit::RetainedMismatchFact]) -> Vec<JsonValue> {
    facts
        .iter()
        .map(|fact| {
            JsonValue::Object(BTreeMap::from([
                (
                    "category".to_owned(),
                    JsonValue::String(mismatch_kind_name(fact.category).to_owned()),
                ),
                (
                    "oracleSha256".to_owned(),
                    JsonValue::String(fact.oracle_sha256.hex()),
                ),
                (
                    "candidateSha256".to_owned(),
                    JsonValue::String(fact.candidate_sha256.hex()),
                ),
            ]))
        })
        .collect()
}

fn mismatch_kind_name(kind: hell_testkit::MismatchKind) -> &'static str {
    match kind {
        hell_testkit::MismatchKind::Timeout => "timeout",
        hell_testkit::MismatchKind::ExitStatus => "exit-status",
        hell_testkit::MismatchKind::Stdout => "stdout",
        hell_testkit::MismatchKind::Stderr => "stderr",
        hell_testkit::MismatchKind::Diagnostic => "diagnostic",
        hell_testkit::MismatchKind::Filesystem => "filesystem",
    }
}

fn normalizer_application_ref(
    builtin: &str,
    dimension: &str,
    platform: &str,
    bundle_sha256: &str,
    role: &str,
    normalizer: &str,
    application_scope: &str,
) -> Result<String, String> {
    let identity = JsonValue::Object(BTreeMap::from([
        ("schemaVersion".to_owned(), JsonValue::Number(1)),
        ("builtin".to_owned(), JsonValue::String(builtin.to_owned())),
        (
            "dimension".to_owned(),
            JsonValue::String(dimension.to_owned()),
        ),
        (
            "platform".to_owned(),
            JsonValue::String(platform.to_owned()),
        ),
        (
            "bundleSha256".to_owned(),
            JsonValue::String(bundle_sha256.to_owned()),
        ),
        ("role".to_owned(), JsonValue::String(role.to_owned())),
        (
            "applicationScope".to_owned(),
            JsonValue::String(application_scope.to_owned()),
        ),
        (
            "normalizerId".to_owned(),
            JsonValue::String(normalizer.to_owned()),
        ),
    ]));
    Ok(sha256_bytes(&canonical_json_bytes(&identity)?).hex())
}

fn native_observation_bundle(input: &Path, platform: &str, case_id: &str) -> PathBuf {
    input
        .join(platform)
        .join("evidence")
        .join("observations")
        .join(case_id)
}

fn catalog_command(root: &Path, options: &Options, components: &[&str]) -> Result<String, String> {
    let relative_path = components.iter().collect::<PathBuf>();
    let relative = path_text(&relative_path)?;
    let document = read_text(&root.join(&relative_path))?;
    require_assignment(&document, "schema_version", "1")
        .or_else(|_| require_assignment(&document, "schema_version", "2"))?;
    if options.action.as_deref() == Some("report") {
        let output = required_path(&options.output, "report action requires --output")?;
        let digest = sha256_bytes(document.as_bytes()).hex();
        let json = format!(
            "{{\n  \"schemaVersion\": 1,\n  \"catalog\": \"{relative}\",\n  \"catalogSha256\": \"{digest}\",\n  \"state\": \"requires-human-judgment\"\n}}\n"
        );
        write_atomic(output, json.as_bytes())?;
    }
    Ok(format!("validated {relative}"))
}

fn normalizer_audit_command(root: &Path, options: &Options) -> Result<String, String> {
    if options.action.as_deref().unwrap_or("verify") != "report" {
        return catalog_command(root, options, &["compat", "normalizers.toml"]);
    }
    let input = required_path(
        &options.input,
        "normalizer-audit report requires --input claim coverage details",
    )?;
    let output = required_path(&options.output, "normalizer-audit report requires --output")?;
    let coverage = parse_json(&read_text(input)?)?;
    let coverage = coverage.object()?;
    let candidate = json_member(coverage, "candidateSourceCommit")?.string()?;
    let epoch = json_member(coverage, "assuranceEpochSha256")?.string()?;
    let retained_root = retained_evidence_root(input)?;
    let application_directory = prepare_normalizer_application_directory(output)?;
    let (mutation_retained, required_mutants, detected_mutants) =
        verified_normalizer_mutation_suite(root, input, candidate, epoch)?;
    let mut audit = collect_normalizer_audit_records(
        json_member(coverage, "cells")?.array()?,
        &NormalizerAuditInputs {
            repository: root,
            retained_root,
            application_directory: &application_directory,
            mutation_suite: &mutation_retained,
            candidate,
            epoch,
        },
    )?;
    audit.records.sort_by_key(canonical_json_digest);
    let application_count = u64::try_from(audit.records.len())
        .map_err(|_| "normalizer application count exceeds u64".to_owned())?;
    let protected_field_changes = u64::try_from(
        audit
            .records
            .iter()
            .filter(|record| {
                record.object().is_ok_and(|record| {
                    json_member(record, "protectedFieldsUnchanged").and_then(JsonValue::boolean)
                        == Ok(false)
                })
            })
            .count(),
    )
    .map_err(|_| "normalizer protected-field change count exceeds u64".to_owned())?;
    audit.unsafe_normalizers = audit
        .unsafe_normalizers
        .saturating_add(protected_field_changes);
    let document = JsonValue::Object(BTreeMap::from([
        ("schemaVersion".to_owned(), JsonValue::Number(1)),
        (
            "candidateSourceCommit".to_owned(),
            JsonValue::String(candidate.to_owned()),
        ),
        (
            "assuranceEpochSha256".to_owned(),
            JsonValue::String(epoch.to_owned()),
        ),
        (
            "applications".to_owned(),
            JsonValue::Number(application_count),
        ),
        (
            "auditedApplications".to_owned(),
            JsonValue::Number(application_count),
        ),
        (
            "exactClaimsUsingNormalizers".to_owned(),
            JsonValue::Number(audit.exact_with_normalizers),
        ),
        (
            "normalizerMutantsRequired".to_owned(),
            JsonValue::Number(required_mutants),
        ),
        (
            "normalizerMutantsDetected".to_owned(),
            JsonValue::Number(detected_mutants),
        ),
        (
            "failedMutants".to_owned(),
            JsonValue::Number(required_mutants.saturating_sub(detected_mutants)),
        ),
        (
            "protectedFieldChanges".to_owned(),
            JsonValue::Number(protected_field_changes),
        ),
        (
            "unsafeNormalizers".to_owned(),
            JsonValue::Number(audit.unsafe_normalizers),
        ),
        (
            "applicationRecords".to_owned(),
            JsonValue::Array(audit.records),
        ),
    ]));
    write_atomic(output, &canonical_json_bytes(&document)?)?;
    Ok(format!(
        "wrote evidence-derived normalizer audit {}",
        output.display()
    ))
}

fn prepare_normalizer_application_directory(output: &Path) -> Result<PathBuf, String> {
    let directory = output
        .parent()
        .ok_or_else(|| "normalizer audit output has no directory".to_owned())?
        .join("normalizer-applications");
    fs::create_dir_all(&directory)
        .map_err(|error| format!("cannot create normalizer application directory: {error}"))?;
    Ok(directory)
}

struct NormalizerAuditInputs<'a> {
    repository: &'a Path,
    retained_root: &'a Path,
    application_directory: &'a Path,
    mutation_suite: &'a Path,
    candidate: &'a str,
    epoch: &'a str,
}

struct NormalizerAuditCollection {
    records: Vec<JsonValue>,
    exact_with_normalizers: u64,
    unsafe_normalizers: u64,
}

fn collect_normalizer_audit_records(
    cells: &[JsonValue],
    inputs: &NormalizerAuditInputs<'_>,
) -> Result<NormalizerAuditCollection, String> {
    let mut records = Vec::new();
    let mut exact_with_normalizers = 0_u64;
    let mut unsafe_normalizers = 0_u64;
    for cell in cells {
        let cell = cell.object()?;
        let status = json_member(cell, "proposedStatus")?.string()?;
        let normalizers = json_member(cell, "normalizerIds")?.array()?;
        if status == "exact" && !normalizers.is_empty() {
            exact_with_normalizers = exact_with_normalizers.saturating_add(1);
        }
        if matches!(status, "normalized" | "platform-dependent") && normalizers.is_empty() {
            unsafe_normalizers = unsafe_normalizers.saturating_add(1);
        }
        let declared_application_refs = json_member(cell, "normalizerApplicationRefs")?
            .array()?
            .iter()
            .map(JsonValue::string)
            .map(|reference| reference.map(str::to_owned))
            .collect::<Result<BTreeSet<_>, _>>()?;
        let mut emitted_application_refs = BTreeSet::new();
        for reference in json_member(cell, "evidenceRefs")?.array()? {
            for role in ["candidate", "oracle"] {
                records.push(normalizer_application_record(
                    inputs.repository,
                    inputs.retained_root,
                    inputs.application_directory,
                    inputs.mutation_suite,
                    cell,
                    reference.object()?,
                    role,
                    inputs.candidate,
                    inputs.epoch,
                    hell_builtins::NormalizerId::DiagnosticSandboxPathV1,
                    "harness-stderr",
                )?);
                for normalizer in normalizers {
                    let normalizer = normalizer.string()?;
                    let normalizer = hell_builtins::NormalizerId::ALL
                        .iter()
                        .copied()
                        .find(|candidate| candidate.as_str() == normalizer)
                        .ok_or_else(|| "claim cell names an unknown normalizer".to_owned())?;
                    let expected_ref = normalizer_application_ref(
                        json_member(cell, "builtin")?.string()?,
                        json_member(cell, "dimension")?.string()?,
                        json_member(cell, "platform")?.string()?,
                        json_member(reference.object()?, "bundleSha256")?.string()?,
                        role,
                        normalizer.as_str(),
                        "claim-stderr",
                    )?;
                    if !declared_application_refs.contains(&expected_ref) {
                        continue;
                    }
                    emitted_application_refs.insert(expected_ref);
                    records.push(normalizer_application_record(
                        inputs.repository,
                        inputs.retained_root,
                        inputs.application_directory,
                        inputs.mutation_suite,
                        cell,
                        reference.object()?,
                        role,
                        inputs.candidate,
                        inputs.epoch,
                        normalizer,
                        "claim-stderr",
                    )?);
                }
            }
        }
        if emitted_application_refs != declared_application_refs {
            return Err(
                "claim cell normalizer application references do not match replayable evidence"
                    .to_owned(),
            );
        }
    }
    Ok(NormalizerAuditCollection {
        records,
        exact_with_normalizers,
        unsafe_normalizers,
    })
}

#[allow(clippy::too_many_arguments)]
fn normalizer_application_record(
    repository: &Path,
    retained_root: &Path,
    application_directory: &Path,
    mutation_suite: &Path,
    cell: &BTreeMap<String, JsonValue>,
    reference: &BTreeMap<String, JsonValue>,
    role: &str,
    candidate: &str,
    epoch: &str,
    normalizer: hell_builtins::NormalizerId,
    application_scope: &str,
) -> Result<JsonValue, String> {
    let replay = replay_retained_normalizer(
        repository,
        retained_root,
        reference,
        role,
        normalizer,
        application_scope,
    )?;
    let identity = normalizer_application_ref(
        json_member(cell, "builtin")?.string()?,
        json_member(cell, "dimension")?.string()?,
        json_member(cell, "platform")?.string()?,
        json_member(reference, "bundleSha256")?.string()?,
        role,
        normalizer.as_str(),
        application_scope,
    )?;
    let second = application_directory.join(format!("{identity}.second.bin"));
    write_atomic(&second, &replay.second_pass)?;
    let contract = hell_builtins::normalizer_contract(normalizer)
        .ok_or_else(|| "diagnostic normalizer contract is unavailable".to_owned())?;
    let mut record = normalizer_application_identity_fields(&NormalizerApplicationIdentity {
        cell,
        reference,
        role,
        candidate,
        epoch,
        contract,
        replay: &replay,
        application_scope,
        application_ref: &identity,
    })?;
    record.extend(normalizer_application_evidence_fields(
        retained_root,
        mutation_suite,
        &second,
        &replay,
        normalizer,
        application_scope,
    )?);
    Ok(JsonValue::Object(record))
}

struct RetainedNormalizerReplay {
    input: PathBuf,
    normalized: PathBuf,
    context_path: PathBuf,
    sandbox_path: String,
    script_path: String,
    input_bytes: Vec<u8>,
    first_pass: Vec<u8>,
    second_pass: Vec<u8>,
}

fn replay_retained_normalizer(
    repository: &Path,
    retained_root: &Path,
    reference: &BTreeMap<String, JsonValue>,
    role: &str,
    normalizer: hell_builtins::NormalizerId,
    application_scope: &str,
) -> Result<RetainedNormalizerReplay, String> {
    let bundle = confined_record_path(
        repository,
        retained_root,
        Path::new(json_member(reference, "bundlePath")?.string()?),
    )?;
    if record_digest(&bundle)? != json_member(reference, "bundleSha256")?.string()? {
        return Err("normalizer source bundle digest mismatch".to_owned());
    }
    let observation = bundle.join(role);
    let (input, output) = match application_scope {
        "harness-stderr" => (
            observation.join("stderr.raw.bin"),
            observation.join("stderr.claim-input.bin"),
        ),
        "claim-stderr" => (
            observation.join("stderr.claim-input.bin"),
            observation.join("stderr.bin"),
        ),
        _ => return Err("normalizer application scope is unknown".to_owned()),
    };
    let context_path = observation.join("normalizer-context.json");
    let context = parse_json(&read_text(&context_path)?)?;
    let context = context.object()?;
    exact_keys(context, &["sandboxPath", "schemaVersion", "scriptPath"])?;
    if json_member(context, "schemaVersion")?.number()? != 1 {
        return Err("normalizer context schema is unsupported".to_owned());
    }
    let sandbox_path = json_member(context, "sandboxPath")?.string()?.to_owned();
    let script_path = json_member(context, "scriptPath")?.string()?.to_owned();
    let input_bytes = read_regular_file(&input)?;
    let passes =
        hell_testkit::apply_retained_normalizer_twice(hell_testkit::RetainedNormalizerInput {
            normalizer,
            observation: &input_bytes,
            sandbox: Path::new(&sandbox_path),
            script: Path::new(&script_path),
        });
    if passes.first_pass != read_regular_file(&output)? || passes.second_pass != passes.first_pass {
        return Err("retained normalizer output does not match exact production replay".to_owned());
    }
    Ok(RetainedNormalizerReplay {
        input,
        normalized: output,
        context_path,
        sandbox_path,
        script_path,
        input_bytes,
        first_pass: passes.first_pass,
        second_pass: passes.second_pass,
    })
}

struct NormalizerApplicationIdentity<'a> {
    cell: &'a BTreeMap<String, JsonValue>,
    reference: &'a BTreeMap<String, JsonValue>,
    role: &'a str,
    candidate: &'a str,
    epoch: &'a str,
    contract: &'a hell_builtins::NormalizerContract,
    replay: &'a RetainedNormalizerReplay,
    application_scope: &'a str,
    application_ref: &'a str,
}

fn normalizer_application_identity_fields(
    identity: &NormalizerApplicationIdentity<'_>,
) -> Result<BTreeMap<String, JsonValue>, String> {
    Ok(BTreeMap::from([
        (
            "applicationScope".to_owned(),
            JsonValue::String(identity.application_scope.to_owned()),
        ),
        (
            "applicationRef".to_owned(),
            JsonValue::String(identity.application_ref.to_owned()),
        ),
        (
            "observationRole".to_owned(),
            JsonValue::String(identity.role.to_owned()),
        ),
        (
            "candidateSourceCommit".to_owned(),
            JsonValue::String(identity.candidate.to_owned()),
        ),
        (
            "assuranceEpochSha256".to_owned(),
            JsonValue::String(identity.epoch.to_owned()),
        ),
        (
            "builtin".to_owned(),
            json_member(identity.cell, "builtin")?.clone(),
        ),
        (
            "dimension".to_owned(),
            json_member(identity.cell, "dimension")?.clone(),
        ),
        (
            "profile".to_owned(),
            json_member(identity.cell, "profile")?.clone(),
        ),
        (
            "platform".to_owned(),
            json_member(identity.cell, "platform")?.clone(),
        ),
        (
            "evidenceRef".to_owned(),
            json_member(identity.reference, "bundleSha256")?.clone(),
        ),
        (
            "normalizerId".to_owned(),
            JsonValue::String(identity.contract.id.as_str().to_owned()),
        ),
        (
            "implementationSha256".to_owned(),
            JsonValue::String(identity.contract.implementation_sha256.to_owned()),
        ),
        (
            "sandboxPath".to_owned(),
            JsonValue::String(identity.replay.sandbox_path.clone()),
        ),
        (
            "scriptPath".to_owned(),
            JsonValue::String(identity.replay.script_path.clone()),
        ),
    ]))
}

fn normalizer_application_evidence_fields(
    retained_root: &Path,
    mutation_suite: &Path,
    second: &Path,
    replay: &RetainedNormalizerReplay,
    normalizer: hell_builtins::NormalizerId,
    application_scope: &str,
) -> Result<BTreeMap<String, JsonValue>, String> {
    let changed_values = normalizer_changed_values(
        normalizer,
        &replay.input_bytes,
        &replay.first_pass,
        &replay.sandbox_path,
        &replay.script_path,
    )?;
    let changed = changed_values != 0;
    let protected_fields_unchanged = normalizer_protected_fields_unchanged(
        normalizer,
        application_scope,
        &replay.input_bytes,
        &replay.first_pass,
    );
    Ok(BTreeMap::from([
        (
            "contextPath".to_owned(),
            JsonValue::String(retained_relative_path(retained_root, &replay.context_path)?),
        ),
        (
            "contextSha256".to_owned(),
            JsonValue::String(record_digest(&replay.context_path)?),
        ),
        (
            "inputPath".to_owned(),
            JsonValue::String(retained_relative_path(retained_root, &replay.input)?),
        ),
        (
            "inputSha256".to_owned(),
            JsonValue::String(sha256_bytes(&replay.input_bytes).hex()),
        ),
        (
            "outputPath".to_owned(),
            JsonValue::String(retained_relative_path(retained_root, &replay.normalized)?),
        ),
        (
            "outputSha256".to_owned(),
            JsonValue::String(sha256_bytes(&replay.first_pass).hex()),
        ),
        (
            "secondOutputPath".to_owned(),
            JsonValue::String(retained_relative_path(retained_root, second)?),
        ),
        (
            "secondOutputSha256".to_owned(),
            JsonValue::String(sha256_bytes(&replay.second_pass).hex()),
        ),
        (
            "mutationSuitePath".to_owned(),
            JsonValue::String(retained_relative_path(retained_root, mutation_suite)?),
        ),
        (
            "mutationSuiteSha256".to_owned(),
            JsonValue::String(record_digest(mutation_suite)?),
        ),
        (
            "changedPaths".to_owned(),
            JsonValue::Array(
                changed
                    .then(|| JsonValue::String("stderr.path_tokens[*]".to_owned()))
                    .into_iter()
                    .collect(),
            ),
        ),
        (
            "changedValues".to_owned(),
            JsonValue::Number(changed_values),
        ),
        (
            "removedBytes".to_owned(),
            JsonValue::Number(
                u64::try_from(
                    replay
                        .input_bytes
                        .len()
                        .saturating_sub(replay.first_pass.len()),
                )
                .map_err(|_| "normalizer removal size exceeds u64".to_owned())?,
            ),
        ),
        ("idempotent".to_owned(), JsonValue::Bool(true)),
        (
            "protectedFieldsUnchanged".to_owned(),
            JsonValue::Bool(protected_fields_unchanged),
        ),
    ]))
}

fn normalizer_changed_values(
    normalizer: hell_builtins::NormalizerId,
    before: &[u8],
    after: &[u8],
    sandbox_path: &str,
    script_path: &str,
) -> Result<u64, String> {
    let changes = match normalizer {
        hell_builtins::NormalizerId::DiagnosticSandboxPathV1 => [sandbox_path, script_path]
            .into_iter()
            .filter(|needle| !needle.is_empty())
            .map(|needle| {
                before
                    .windows(needle.len())
                    .filter(|window| *window == needle.as_bytes())
                    .count()
            })
            .sum::<usize>(),
        hell_builtins::NormalizerId::DiagnosticPathSeparatorV1 => before
            .iter()
            .zip(after)
            .filter(|(before, after)| before != after)
            .count(),
    };
    u64::try_from(changes).map_err(|_| "normalizer changed-value count exceeds u64".to_owned())
}

fn normalizer_protected_fields_unchanged(
    normalizer: hell_builtins::NormalizerId,
    application_scope: &str,
    before: &[u8],
    after: &[u8],
) -> bool {
    match (normalizer, application_scope) {
        (hell_builtins::NormalizerId::DiagnosticSandboxPathV1, "harness-stderr") => true,
        (hell_builtins::NormalizerId::DiagnosticPathSeparatorV1, "claim-stderr") => {
            before.len() == after.len()
                && before
                    .iter()
                    .zip(after)
                    .all(|(before, after)| before == after || (*before == b'\\' && *after == b'/'))
        }
        _ => false,
    }
}

fn verified_normalizer_mutation_suite(
    root: &Path,
    coverage: &Path,
    candidate: &str,
    epoch: &str,
) -> Result<(PathBuf, u64, u64), String> {
    let directory = coverage
        .parent()
        .ok_or_else(|| "normalizer coverage has no retained directory".to_owned())?;
    let report_path = directory.join("mutation-score.json");
    let signer_policy = directory.join("reviewer.allowed_signers");
    retained_report_command(
        root,
        &Options {
            input: Some(report_path.clone()),
            policy: Some(signer_policy),
            expect_source: Some(candidate.to_owned()),
            expect_epoch: Some(epoch.to_owned()),
            ..Options::default()
        },
        "mutation",
    )?;
    let report = parse_json(&read_text(&report_path)?)?;
    let required_ids = BTreeSet::from([
        "normalizer-order-or-precision-loss",
        "diagnostic-overbroad-normalization",
    ]);
    let mut observed = BTreeSet::new();
    let mut detected = 0_u64;
    for mutant in json_member(report.object()?, "mutants")?.array()? {
        let mutant = mutant.object()?;
        let id = json_member(mutant, "id")?.string()?;
        if required_ids.contains(id) {
            if !observed.insert(id) {
                return Err("normalizer mutation suite repeats a required mutant".to_owned());
            }
            detected =
                detected.saturating_add(u64::from(json_member(mutant, "detected")?.boolean()?));
        }
    }
    if observed != required_ids {
        return Err("normalizer mutation suite omits a required production mutant".to_owned());
    }
    Ok((
        report_path,
        u64::try_from(required_ids.len())
            .map_err(|_| "normalizer mutant count exceeds u64".to_owned())?,
        detected,
    ))
}

fn divergence_command(root: &Path, options: &Options) -> Result<String, String> {
    verify_generated_divergence_policy()?;
    match options.action.as_deref().unwrap_or("verify") {
        "report" => divergence_report(options),
        "accept" => divergence_accept(root, options),
        "apply" => divergence_apply(options),
        "role-plan" => divergence_role_plan(options),
        "approvals" => divergence_approvals(options),
        _ => catalog_command(root, options, &["compat", "divergences.toml"]),
    }
}

fn divergence_role_plan(options: &Options) -> Result<String, String> {
    let input = required_path(&options.input, "divergence role-plan requires --input")?;
    let details = parse_json(&read_text(input)?)?;
    let roles = required_divergence_roles(details.object()?)?;
    let github_output = std::env::var_os("GITHUB_OUTPUT")
        .ok_or_else(|| "divergence role-plan requires GITHUB_OUTPUT".to_owned())?;
    let mut output = fs::OpenOptions::new()
        .append(true)
        .open(&github_output)
        .map_err(|error| format!("cannot open GITHUB_OUTPUT: {error}"))?;
    for (name, role) in [
        ("platform_required", "divergence-platform-reviewer"),
        (
            "implementation_required",
            "divergence-implementation-reviewer",
        ),
        ("product_required", "divergence-product-reviewer"),
        ("security_required", "divergence-security-reviewer"),
    ] {
        writeln!(output, "{name}={}", roles.contains(role))
            .map_err(|error| format!("cannot write GITHUB_OUTPUT: {error}"))?;
    }
    output
        .sync_all()
        .map_err(|error| format!("cannot sync GITHUB_OUTPUT: {error}"))?;
    Ok(format!(
        "derived {} exact divergence approval roles",
        roles.len()
    ))
}

fn divergence_approvals(options: &Options) -> Result<String, String> {
    let input = required_path(&options.input, "divergence approvals requires --input")?;
    let policy = required_path(&options.policy, "divergence approvals requires --policy")?;
    let retained_root = input
        .parent()
        .and_then(Path::parent)
        .ok_or_else(|| "divergence wrapper has no retained evidence root".to_owned())?;
    let wrapper = parse_json(&read_text(input)?)?;
    let wrapper = wrapper.object()?;
    verify_divergence_tier_approvals(
        input,
        retained_root,
        policy,
        json_member(wrapper, "candidateSourceCommit")?.string()?,
        json_member(wrapper, "assuranceEpochSha256")?.string()?,
    )?;
    Ok("verified exact tier-derived divergence approvals".to_owned())
}

fn required_divergence_roles(
    divergence: &BTreeMap<String, JsonValue>,
) -> Result<BTreeSet<String>, String> {
    let mut required = BTreeSet::from(["divergence-reviewer".to_owned()]);
    for record in json_member(divergence, "records")?.array()? {
        let record = record.object()?;
        required.extend(
            json_member(record, "requiredReviewRoles")?
                .array()?
                .iter()
                .map(JsonValue::string)
                .collect::<Result<Vec<_>, _>>()?
                .into_iter()
                .map(str::to_owned),
        );
    }
    Ok(required)
}

fn divergence_report(options: &Options) -> Result<String, String> {
    let input = required_path(
        &options.input,
        "divergence report requires --input claim coverage details",
    )?;
    let output = required_path(&options.output, "divergence report requires --output")?;
    let coverage = parse_json(&read_text(input)?)?;
    let coverage = coverage.object()?;
    let candidate = json_member(coverage, "candidateSourceCommit")?.string()?;
    let epoch = json_member(coverage, "assuranceEpochSha256")?.string()?;
    let deliberate_without_record = json_member(coverage, "cells")?
        .array()?
        .iter()
        .filter(|cell| {
            cell.object().is_ok_and(|cell| {
                json_member(cell, "proposedStatus").and_then(JsonValue::string)
                    == Ok("deliberate-divergence")
            })
        })
        .count();
    let mut proposed_records = json_member(coverage, "mismatchCandidates")?
        .array()?
        .to_vec();
    proposed_records.sort_by_key(canonical_json_digest);
    if proposed_records
        .windows(2)
        .any(|pair| canonical_json_digest(&pair[0]) == canonical_json_digest(&pair[1]))
    {
        return Err("claim coverage repeats a mismatch candidate".to_owned());
    }
    let missing = u64::try_from(
        proposed_records
            .len()
            .saturating_add(deliberate_without_record),
    )
    .map_err(|_| "divergence approval count exceeds u64".to_owned())?;
    let document = JsonValue::Object(BTreeMap::from([
        ("schemaVersion".to_owned(), JsonValue::Number(2)),
        (
            "candidateSourceCommit".to_owned(),
            JsonValue::String(candidate.to_owned()),
        ),
        (
            "assuranceEpochSha256".to_owned(),
            JsonValue::String(epoch.to_owned()),
        ),
        ("activeDivergences".to_owned(), JsonValue::Number(0)),
        ("approvedDivergences".to_owned(), JsonValue::Number(0)),
        ("expiredDivergences".to_owned(), JsonValue::Number(0)),
        ("fingerprintMismatches".to_owned(), JsonValue::Number(0)),
        (
            "missingImpactApprovals".to_owned(),
            JsonValue::Number(missing),
        ),
        ("wildcardScopes".to_owned(), JsonValue::Number(0)),
        (
            "proposedRecords".to_owned(),
            JsonValue::Array(proposed_records),
        ),
        ("records".to_owned(), JsonValue::Array(Vec::new())),
    ]));
    write_atomic(output, &canonical_json_bytes(&document)?)?;
    Ok(format!(
        "wrote evidence-derived divergence report {}",
        output.display()
    ))
}

const DIVERGENCE_APPROVAL_DECISIONS: [&str; 14] = [
    "alternatives",
    "category",
    "documentation-target",
    "expiry",
    "fixability",
    "impact",
    "impact-tier",
    "issue-state",
    "owner",
    "origin-classification",
    "rationale",
    "reproduction",
    "review-level",
    "why-not-fix-candidate",
];

fn divergence_accept(root: &Path, options: &Options) -> Result<String, String> {
    if !options.github_dispatch_inputs {
        return Err("divergence acceptance requires --github-dispatch-inputs".to_owned());
    }
    let input = required_path(&options.input, "divergence accept requires --input")?;
    let output = required_path(&options.output, "divergence accept requires --output")?;
    let mut report = parse_json(&read_text(input)?)?;
    let report_object = report.object_mut()?;
    let candidate = json_member(report_object, "candidateSourceCommit")?
        .string()?
        .to_owned();
    let assurance_epoch = json_member(report_object, "assuranceEpochSha256")?
        .string()?
        .to_owned();
    if git_output(root, &["rev-parse", "HEAD"])?.trim() != candidate
        || epoch(root)?.1.hex() != assurance_epoch
    {
        return Err("divergence acceptance checkout or epoch is stale".to_owned());
    }
    let inputs = github_dispatch_object(REVIEW_ASSEMBLY_INPUTS)?;
    let decisions = parse_json(map_value(&inputs, "divergence_decisions_json")?)?;
    let decisions = decisions.array()?;
    let proposed = json_member(report_object, "proposedRecords")?.array()?;
    let proposed_by_digest = proposed
        .iter()
        .map(|record| Ok((canonical_json_digest(record)?, record)))
        .collect::<Result<BTreeMap<_, _>, String>>()?;
    if proposed_by_digest.len() != proposed.len() || decisions.len() != proposed.len() {
        return Err(
            "divergence decisions are not an exact set over proposed mismatches".to_owned(),
        );
    }
    let retained_root = retained_evidence_root(output)?;
    let issue_directory = output
        .parent()
        .ok_or_else(|| "divergence report has no containing directory".to_owned())?
        .join("divergence-issues");
    fs::create_dir_all(&issue_directory)
        .map_err(|error| format!("cannot create retained divergence issue directory: {error}"))?;
    let mut used = BTreeSet::new();
    let mut records = Vec::new();
    for decision in decisions {
        let decision = decision.object()?;
        let candidate_sha = json_member(decision, "candidateSha256")?.string()?;
        let proposed = proposed_by_digest
            .get(candidate_sha)
            .ok_or_else(|| "divergence decision names an unknown mismatch candidate".to_owned())?;
        if !used.insert(candidate_sha.to_owned()) {
            return Err("divergence decisions repeat a mismatch candidate".to_owned());
        }
        records.push(accepted_divergence_record(
            decision,
            proposed.object()?,
            &issue_directory,
            retained_root,
            output,
        )?);
    }
    records.sort_by_key(canonical_json_digest);
    let count = u64::try_from(records.len())
        .map_err(|_| "accepted divergence count exceeds u64".to_owned())?;
    report_object.insert("activeDivergences".to_owned(), JsonValue::Number(count));
    report_object.insert("approvedDivergences".to_owned(), JsonValue::Number(count));
    report_object.insert("missingImpactApprovals".to_owned(), JsonValue::Number(0));
    report_object.insert("proposedRecords".to_owned(), JsonValue::Array(Vec::new()));
    report_object.insert("records".to_owned(), JsonValue::Array(records));
    write_atomic(output, &canonical_json_bytes(&report)?)?;
    Ok(format!("accepted {count} exact divergence decisions"))
}

fn accepted_divergence_record(
    decision: &BTreeMap<String, JsonValue>,
    proposed: &BTreeMap<String, JsonValue>,
    issue_directory: &Path,
    retained_root: &Path,
    report_path: &Path,
) -> Result<JsonValue, String> {
    let decision_facts = validate_divergence_decision(decision, proposed)?;
    let issue_path = issue_directory.join(format!("issue-{}.json", decision_facts.issue_number));
    let issue = retained_open_divergence_issue(decision_facts.issue_number)?;
    write_atomic(&issue_path, &canonical_json_bytes(&issue)?)?;
    let issue_sha = record_digest(&issue_path)?;
    let record = build_accepted_divergence_record(&AcceptedDivergenceRecordInputs {
        decision,
        proposed,
        facts: &decision_facts,
        issue: &issue,
        issue_path: &issue_path,
        issue_sha: &issue_sha,
        retained_root,
    })?;
    verify_retained_divergence_mismatch(record.object()?, report_path)?;
    Ok(record)
}

struct ValidatedDivergenceDecision {
    alternatives_considered: Vec<String>,
    baseline: String,
    candidate_sha: String,
    category: String,
    documentation_target: String,
    expires_at: String,
    fixability: String,
    impact: String,
    impact_tier: String,
    issue_number: u64,
    origin_classification: String,
    owner: u64,
    prior_release: String,
    rationale: String,
    review_level: String,
    status: String,
    why_not_fix_candidate: String,
}

struct DivergenceAuthoredFields {
    alternatives: Vec<String>,
    category: String,
    documentation_target: String,
    impact: String,
    owner: u64,
    rationale: String,
    why_not_fix_candidate: String,
}

fn validate_divergence_decision(
    decision: &BTreeMap<String, JsonValue>,
    proposed: &BTreeMap<String, JsonValue>,
) -> Result<ValidatedDivergenceDecision, String> {
    exact_keys(
        decision,
        &[
            "alternativesConsidered",
            "baseline",
            "candidateSha256",
            "category",
            "documentationTarget",
            "expiresAt",
            "fixability",
            "impact",
            "impactTier",
            "issueNumber",
            "originClassification",
            "owner",
            "priorReleaseState",
            "rationale",
            "reviewLevel",
            "status",
            "whyNotFixCandidate",
        ],
    )?;
    verify_proposed_divergence_record(proposed)?;
    let candidate_sha = canonical_json_digest(&JsonValue::Object(proposed.clone()))?;
    if json_member(decision, "candidateSha256")?.string()? != candidate_sha {
        return Err("divergence decision candidate digest was substituted".to_owned());
    }
    let expires_at = json_member(decision, "expiresAt")?.string()?;
    validate_utc_timestamp(expires_at)?;
    if utc_timestamp_seconds(expires_at)? <= current_utc_seconds()? {
        return Err("divergence decision is already expired".to_owned());
    }
    let impact_tier = json_member(decision, "impactTier")?.string()?;
    let fixability = json_member(decision, "fixability")?.string()?;
    let prior_release = json_member(decision, "priorReleaseState")?.string()?;
    let baseline = json_member(decision, "baseline")?.string()?;
    let origin_classification = json_member(decision, "originClassification")?.string()?;
    let status = json_member(decision, "status")?.string()?;
    let review_level = json_member(decision, "reviewLevel")?.string()?;
    let objective = json_member(proposed, "objectiveEvidence")?.object()?;
    verify_divergence_objective_decision(
        objective,
        fixability,
        prior_release,
        origin_classification,
    )?;
    if !matches!(impact_tier, "low" | "medium" | "high" | "critical")
        || !matches!(
            fixability,
            "fix-planned" | "upstream-incompatible" | "not-currently-fixable"
        )
        || !matches!(prior_release, "present" | "absent" | "unknown")
        || baseline != hell_builtins::LANGUAGE_VERSION
        || !matches!(
            origin_classification,
            "baseline-inherent" | "platform-inherent" | "newly-introduced" | "policy-driven"
        )
        || status != "accepted"
        || review_level != divergence_review_level(impact_tier)?
    {
        return Err("divergence decision contains an unknown typed disposition".to_owned());
    }
    let recommended_tier = json_member(proposed, "recommendedImpactTier")?.string()?;
    let recommended_days = json_member(proposed, "recommendedExpiryDays")?.number()?;
    let latest_expiry = current_utc_seconds()?.saturating_add(
        recommended_days
            .checked_mul(86_400)
            .ok_or_else(|| "divergence expiry recommendation overflows".to_owned())?,
    );
    if divergence_tier_rank(impact_tier)? < divergence_tier_rank(recommended_tier)?
        || utc_timestamp_seconds(expires_at)? > latest_expiry
    {
        return Err("divergence decision weakens the evidence-derived tier or expiry".to_owned());
    }
    let authored = validate_divergence_authored_fields(decision, impact_tier)?;
    let issue_number = json_member(decision, "issueNumber")?.number()?;
    if issue_number == 0 {
        return Err("divergence issue number must be nonzero".to_owned());
    }
    Ok(ValidatedDivergenceDecision {
        alternatives_considered: authored.alternatives,
        baseline: baseline.to_owned(),
        candidate_sha,
        category: authored.category,
        documentation_target: authored.documentation_target,
        expires_at: expires_at.to_owned(),
        fixability: fixability.to_owned(),
        impact: authored.impact,
        impact_tier: impact_tier.to_owned(),
        issue_number,
        origin_classification: origin_classification.to_owned(),
        owner: authored.owner,
        prior_release: prior_release.to_owned(),
        rationale: authored.rationale,
        review_level: review_level.to_owned(),
        status: status.to_owned(),
        why_not_fix_candidate: authored.why_not_fix_candidate,
    })
}

fn verify_divergence_objective_decision(
    objective: &BTreeMap<String, JsonValue>,
    fixability: &str,
    prior_release: &str,
    origin: &str,
) -> Result<(), String> {
    let derived_fixability = json_member(objective, "derivedFixability")?.string()?;
    let derived_prior = json_member(objective, "derivedPriorReleaseState")?.string()?;
    let automated_origin = json_member(objective, "automatedOriginClassification")?.string()?;
    let profile_state = json_member(
        json_member(objective, "profileComparison")?.object()?,
        "state",
    )?
    .string()?;
    if derived_fixability == "undetermined"
        || automated_origin == "indeterminate"
        || profile_state != "executed-and-replayed"
    {
        return Err(
            "divergence acceptance requires complete objective §11.7 experiments".to_owned(),
        );
    }
    if prior_release != derived_prior
        || fixability != derived_fixability
        || origin != automated_origin
    {
        return Err("divergence decision contradicts objective §11.7 evidence".to_owned());
    }
    Ok(())
}

fn validate_divergence_authored_fields(
    decision: &BTreeMap<String, JsonValue>,
    impact_tier: &str,
) -> Result<DivergenceAuthoredFields, String> {
    let impact = json_member(decision, "impact")?.string()?;
    let rationale = json_member(decision, "rationale")?.string()?;
    let why_not_fix_candidate = json_member(decision, "whyNotFixCandidate")?.string()?;
    let limits = review_text_limits()?;
    for (field, value) in [
        ("impact", impact),
        ("rationale", rationale),
        ("whyNotFixCandidate", why_not_fix_candidate),
    ] {
        if value.len() < limits.rationale_minimum || value.len() > limits.rationale_maximum {
            return Err(format!(
                "divergence {field} is outside the reviewed UTF-8 byte limits"
            ));
        }
        let normalized = value.trim().to_ascii_lowercase();
        if matches!(normalized.as_str(), "tbd" | "none" | "n/a" | "unknown")
            || normalized.contains("placeholder")
        {
            return Err(format!("divergence {field} is generic boilerplate"));
        }
    }
    if [impact, rationale, why_not_fix_candidate]
        .into_iter()
        .collect::<BTreeSet<_>>()
        .len()
        != 3
    {
        return Err("divergence authored explanations must be distinct".to_owned());
    }
    let category = json_member(decision, "category")?.string()?;
    let category_tier = match category {
        "presentation" => "low",
        "diagnostic" | "platform-presentation" => "medium",
        "runtime-semantics" | "ordering-precision" | "resource-semantics" => "high",
        "security-hardening" | "process-semantics" | "network-semantics" | "data-integrity" => {
            "critical"
        }
        _ => return Err("divergence decision category is not a reviewed typed class".to_owned()),
    };
    if divergence_tier_rank(impact_tier)? < divergence_tier_rank(category_tier)? {
        return Err("divergence decision category requires a higher review tier".to_owned());
    }
    let alternatives = json_member(decision, "alternativesConsidered")?.array()?;
    if alternatives.is_empty() || alternatives.len() > 5 {
        return Err("divergence decision must retain one to five alternatives".to_owned());
    }
    let alternatives_considered = alternatives
        .iter()
        .map(JsonValue::string)
        .map(|value| value.map(str::to_owned))
        .collect::<Result<Vec<_>, _>>()?;
    if alternatives_considered
        .iter()
        .collect::<BTreeSet<_>>()
        .len()
        != alternatives_considered.len()
        || alternatives_considered.iter().any(|value| {
            value.len() < limits.rationale_minimum
                || value.len() > limits.rationale_maximum
                || [impact, rationale, why_not_fix_candidate].contains(&value.as_str())
        })
    {
        return Err("divergence alternatives are duplicated or outside policy limits".to_owned());
    }
    let documentation_target = json_member(decision, "documentationTarget")?.string()?;
    if !documentation_target.starts_with("bounded-compatibility-report/")
        || documentation_target.contains("..")
        || documentation_target.chars().any(char::is_control)
    {
        return Err("divergence documentation target is not a bounded report section".to_owned());
    }
    let owner = json_member(decision, "owner")?.number()?;
    if owner == 0 {
        return Err("divergence owner must be a stable nonzero provider account ID".to_owned());
    }
    Ok(DivergenceAuthoredFields {
        alternatives: alternatives_considered,
        category: category.to_owned(),
        documentation_target: documentation_target.to_owned(),
        impact: impact.to_owned(),
        owner,
        rationale: rationale.to_owned(),
        why_not_fix_candidate: why_not_fix_candidate.to_owned(),
    })
}

fn divergence_tier_rank(tier: &str) -> Result<u8, String> {
    match tier {
        "low" => Ok(0),
        "medium" => Ok(1),
        "high" => Ok(2),
        "critical" => Ok(3),
        _ => Err("unknown divergence impact tier".to_owned()),
    }
}

fn divergence_review_level(tier: &str) -> Result<&'static str, String> {
    match tier {
        "low" => Ok("compatibility"),
        "medium" => Ok("compatibility-platform"),
        "high" => Ok("compatibility-implementation-product"),
        "critical" => Ok("compatibility-security-product"),
        _ => Err("unknown divergence review level".to_owned()),
    }
}

struct AcceptedDivergenceRecordInputs<'a> {
    decision: &'a BTreeMap<String, JsonValue>,
    proposed: &'a BTreeMap<String, JsonValue>,
    facts: &'a ValidatedDivergenceDecision,
    issue: &'a JsonValue,
    issue_path: &'a Path,
    issue_sha: &'a str,
    retained_root: &'a Path,
}

fn build_accepted_divergence_record(
    inputs: &AcceptedDivergenceRecordInputs<'_>,
) -> Result<JsonValue, String> {
    let issue = inputs.issue.object()?;
    let mut record = accepted_divergence_decision_fields(inputs, issue)?;
    for field in [
        "builtin",
        "dimension",
        "evidencePath",
        "evidenceRef",
        "normalizedObservationSha256",
        "platform",
        "profile",
        "rawObservationSha256",
    ] {
        record.insert(
            field.to_owned(),
            json_member(inputs.proposed, field)?.clone(),
        );
    }
    let record_fingerprint = divergence_fingerprint(&record)?;
    record.insert(
        "fingerprint".to_owned(),
        JsonValue::String(record_fingerprint),
    );
    let divergence_id = sha256_bytes(
        [
            inputs.facts.candidate_sha.as_bytes(),
            json_member(&record, "reviewRef")?.string()?.as_bytes(),
        ]
        .concat()
        .as_slice(),
    )
    .hex();
    record.insert("divergenceId".to_owned(), JsonValue::String(divergence_id));
    Ok(JsonValue::Object(record))
}

fn accepted_divergence_decision_fields(
    inputs: &AcceptedDivergenceRecordInputs<'_>,
    issue: &BTreeMap<String, JsonValue>,
) -> Result<BTreeMap<String, JsonValue>, String> {
    let mut fields = accepted_divergence_authored_fields(inputs);
    fields.extend(accepted_divergence_governance_fields(inputs)?);
    fields.extend(accepted_divergence_evidence_fields(inputs, issue)?);
    Ok(fields)
}

fn accepted_divergence_authored_fields(
    inputs: &AcceptedDivergenceRecordInputs<'_>,
) -> BTreeMap<String, JsonValue> {
    let facts = inputs.facts;
    BTreeMap::from([
        (
            "alternativesConsidered".to_owned(),
            JsonValue::Array(
                facts
                    .alternatives_considered
                    .iter()
                    .cloned()
                    .map(JsonValue::String)
                    .collect(),
            ),
        ),
        (
            "baseline".to_owned(),
            JsonValue::String(facts.baseline.clone()),
        ),
        (
            "category".to_owned(),
            JsonValue::String(facts.category.clone()),
        ),
        (
            "documentationTarget".to_owned(),
            JsonValue::String(facts.documentation_target.clone()),
        ),
        ("impact".to_owned(), JsonValue::String(facts.impact.clone())),
        ("owner".to_owned(), JsonValue::Number(facts.owner)),
        (
            "rationale".to_owned(),
            JsonValue::String(facts.rationale.clone()),
        ),
        (
            "whyNotFixCandidate".to_owned(),
            JsonValue::String(facts.why_not_fix_candidate.clone()),
        ),
    ])
}

fn accepted_divergence_governance_fields(
    inputs: &AcceptedDivergenceRecordInputs<'_>,
) -> Result<BTreeMap<String, JsonValue>, String> {
    let facts = inputs.facts;
    Ok(BTreeMap::from([
        (
            "approvalDecisions".to_owned(),
            JsonValue::Array(
                DIVERGENCE_APPROVAL_DECISIONS
                    .into_iter()
                    .map(|value| JsonValue::String(value.to_owned()))
                    .collect(),
            ),
        ),
        (
            "candidateSha256".to_owned(),
            JsonValue::String(facts.candidate_sha.clone()),
        ),
        (
            "caseId".to_owned(),
            json_member(inputs.proposed, "caseId")?.clone(),
        ),
        (
            "expiresAt".to_owned(),
            JsonValue::String(facts.expires_at.clone()),
        ),
        (
            "fixability".to_owned(),
            JsonValue::String(facts.fixability.clone()),
        ),
        (
            "impactTier".to_owned(),
            JsonValue::String(facts.impact_tier.clone()),
        ),
        (
            "issueNumber".to_owned(),
            JsonValue::Number(facts.issue_number),
        ),
        (
            "originClassification".to_owned(),
            JsonValue::String(facts.origin_classification.clone()),
        ),
        (
            "priorReleaseState".to_owned(),
            JsonValue::String(facts.prior_release.clone()),
        ),
        (
            "reviewLevel".to_owned(),
            JsonValue::String(facts.review_level.clone()),
        ),
        ("status".to_owned(), JsonValue::String(facts.status.clone())),
    ]))
}

fn accepted_divergence_evidence_fields(
    inputs: &AcceptedDivergenceRecordInputs<'_>,
    issue: &BTreeMap<String, JsonValue>,
) -> Result<BTreeMap<String, JsonValue>, String> {
    Ok(BTreeMap::from([
        (
            "issuePath".to_owned(),
            JsonValue::String(retained_relative_path(
                inputs.retained_root,
                inputs.issue_path,
            )?),
        ),
        (
            "issueRepositoryId".to_owned(),
            json_member(issue, "repositoryId")?.clone(),
        ),
        (
            "issueSha256".to_owned(),
            JsonValue::String(inputs.issue_sha.to_owned()),
        ),
        (
            "issueState".to_owned(),
            JsonValue::String("open".to_owned()),
        ),
        (
            "mismatchCategories".to_owned(),
            json_member(inputs.proposed, "mismatchCategories")?.clone(),
        ),
        (
            "mismatchEvidence".to_owned(),
            JsonValue::Object(inputs.proposed.clone()),
        ),
        (
            "mismatchFingerprint".to_owned(),
            json_member(inputs.proposed, "mismatchFingerprint")?.clone(),
        ),
        (
            "normalizerSafety".to_owned(),
            JsonValue::String("configured-normalizers-do-not-resolve".to_owned()),
        ),
        (
            "reproductionState".to_owned(),
            JsonValue::String("reproduced-retained-bundle".to_owned()),
        ),
        (
            "requiredReviewRoles".to_owned(),
            JsonValue::Array(
                required_divergence_review_roles(&inputs.facts.impact_tier)?
                    .iter()
                    .map(|role| JsonValue::String((*role).to_owned()))
                    .collect(),
            ),
        ),
        (
            "reviewRef".to_owned(),
            JsonValue::String(divergence_decision_digest(inputs.decision)?),
        ),
    ]))
}

fn divergence_decision_digest(decision: &BTreeMap<String, JsonValue>) -> Result<String, String> {
    canonical_json_digest(&JsonValue::Object(decision.clone()))
}

fn required_divergence_review_roles(tier: &str) -> Result<&'static [&'static str], String> {
    match tier {
        "low" => Ok(&["divergence-reviewer"]),
        "medium" => Ok(&["divergence-reviewer", "divergence-platform-reviewer"]),
        "high" => Ok(&[
            "divergence-reviewer",
            "divergence-implementation-reviewer",
            "divergence-product-reviewer",
        ]),
        "critical" => Ok(&[
            "divergence-reviewer",
            "divergence-product-reviewer",
            "divergence-security-reviewer",
        ]),
        _ => Err("unknown divergence tier role policy".to_owned()),
    }
}

fn retained_open_divergence_issue(issue_number: u64) -> Result<JsonValue, String> {
    let repository = std::env::var("GITHUB_REPOSITORY")
        .map_err(|_| "divergence acceptance requires GITHUB_REPOSITORY".to_owned())?;
    if repository != "Portfoligno/hell-rs" {
        return Err("divergence issue repository is not accepted".to_owned());
    }
    let repository_id = environment_u64("GITHUB_REPOSITORY_ID", "divergence repository")?;
    let response = github_public_issue(issue_number)?;
    let response = response.object()?;
    if json_member(response, "number")?.number()? != issue_number
        || json_member(response, "state")?.string()? != "open"
        || json_member(response, "repository_url")?.string()?
            != "https://api.github.com/repos/Portfoligno/hell-rs"
    {
        return Err("divergence issue is closed or belongs to another repository".to_owned());
    }
    validate_utc_timestamp(json_member(response, "updated_at")?.string()?)?;
    Ok(JsonValue::Object(BTreeMap::from([
        ("schemaVersion".to_owned(), JsonValue::Number(1)),
        ("repository".to_owned(), JsonValue::String(repository)),
        ("repositoryId".to_owned(), JsonValue::Number(repository_id)),
        ("number".to_owned(), JsonValue::Number(issue_number)),
        ("issueId".to_owned(), json_member(response, "id")?.clone()),
        (
            "nodeId".to_owned(),
            json_member(response, "node_id")?.clone(),
        ),
        ("state".to_owned(), JsonValue::String("open".to_owned())),
        (
            "htmlUrl".to_owned(),
            json_member(response, "html_url")?.clone(),
        ),
        (
            "updatedAt".to_owned(),
            json_member(response, "updated_at")?.clone(),
        ),
    ])))
}

struct GithubPublicIssueUrl(String);

impl GithubPublicIssueUrl {
    fn new(issue_number: u64) -> Result<Self, String> {
        if issue_number == 0 {
            return Err("public issue URL requires a nonzero issue number".to_owned());
        }
        let issue = issue_number.to_string();
        let value = [
            "https:",
            "",
            "api.github.com",
            "repos",
            "Portfoligno",
            "hell-rs",
            "issues",
            issue.as_str(),
        ]
        .join("/");
        let components = value.split('/').collect::<Vec<_>>();
        if components
            != [
                "https:",
                "",
                "api.github.com",
                "repos",
                "Portfoligno",
                "hell-rs",
                "issues",
                issue.as_str(),
            ]
        {
            return Err("public issue URL did not round-trip exactly".to_owned());
        }
        Ok(Self(value))
    }

    fn as_str(&self) -> &str {
        &self.0
    }
}

fn github_public_issue(issue_number: u64) -> Result<JsonValue, String> {
    let url = GithubPublicIssueUrl::new(issue_number)?;
    let response = Command::new("curl")
        .args([
            "--fail",
            "--silent",
            "--show-error",
            "--proto",
            "=https",
            "--tlsv1.2",
            "--header",
            "Accept: application/vnd.github+json",
            url.as_str(),
        ])
        .output()
        .map_err(|error| format!("cannot query public divergence issue: {error}"))?;
    if !response.status.success() {
        return Err(format!(
            "public divergence issue query failed: {}",
            String::from_utf8_lossy(&response.stderr)
        ));
    }
    parse_json(
        std::str::from_utf8(&response.stdout)
            .map_err(|_| "public divergence issue response is not UTF-8".to_owned())?,
    )
}

fn divergence_apply(options: &Options) -> Result<String, String> {
    let input = required_path(&options.input, "divergence apply requires --input coverage")?;
    let accepted = required_path(&options.from, "divergence apply requires --from report")?;
    let output = required_path(&options.output, "divergence apply requires --output")?;
    let mut coverage = parse_json(&read_text(input)?)?;
    let report = parse_json(&read_text(accepted)?)?;
    let report = report.object()?;
    let coverage_object = coverage.object_mut()?;
    if json_member(report, "candidateSourceCommit")?.string()?
        != json_member(coverage_object, "candidateSourceCommit")?.string()?
        || json_member(report, "assuranceEpochSha256")?.string()?
            != json_member(coverage_object, "assuranceEpochSha256")?.string()?
        || !json_member(report, "proposedRecords")?.array()?.is_empty()
        || json_member(report, "missingImpactApprovals")?.number()? != 0
    {
        return Err("accepted divergence report does not bind the claim coverage".to_owned());
    }
    let records = json_member(report, "records")?.array()?;
    for record in records {
        verify_accepted_divergence_record(record.object()?, accepted)?;
    }
    let by_candidate = records
        .iter()
        .map(|record| {
            let record = record.object()?;
            Ok((
                json_member(record, "candidateSha256")?.string()?.to_owned(),
                record,
            ))
        })
        .collect::<Result<BTreeMap<_, _>, String>>()?;
    if by_candidate.len() != records.len() {
        return Err("accepted divergence report repeats a mismatch candidate".to_owned());
    }
    let candidates = json_member(coverage_object, "mismatchCandidates")?.array()?;
    let mut accepted_digests = BTreeSet::new();
    for candidate in candidates {
        let digest = canonical_json_digest(candidate)?;
        let record = by_candidate
            .get(&digest)
            .ok_or_else(|| "claim mismatch lacks an accepted divergence decision".to_owned())?;
        verify_divergence_candidate_join(candidate.object()?, record)?;
        accepted_digests.insert(digest);
    }
    if accepted_digests.len() != by_candidate.len() {
        return Err("accepted divergence report contains an unused decision".to_owned());
    }
    let cells = json_member_mut(coverage_object, "cells")?.array_mut()?;
    for record in by_candidate.values() {
        let mut matching = cells
            .iter_mut()
            .filter(|cell| {
                cell.object().is_ok_and(|cell| {
                    ["builtin", "dimension", "platform", "profile"]
                        .into_iter()
                        .all(|field| {
                            json_member(cell, field).and_then(JsonValue::string)
                                == json_member(record, field).and_then(JsonValue::string)
                        })
                })
            })
            .collect::<Vec<_>>();
        if matching.len() != 1 {
            return Err("accepted divergence does not select one exact claim cell".to_owned());
        }
        let cell = matching[0].object_mut()?;
        if !evidence_contains(cell, json_member(record, "evidenceRef")?.string()?)? {
            return Err("accepted divergence evidence is absent from its claim cell".to_owned());
        }
        cell.insert(
            "proposedStatus".to_owned(),
            JsonValue::String("deliberate-divergence".to_owned()),
        );
        cell.insert("normalizerIds".to_owned(), JsonValue::Array(Vec::new()));
        cell.insert(
            "normalizerApplicationRefs".to_owned(),
            JsonValue::Array(Vec::new()),
        );
        cell.insert(
            "divergenceRecordRef".to_owned(),
            JsonValue::String(canonical_json_digest(&JsonValue::Object(
                (*record).clone(),
            ))?),
        );
    }
    coverage_object.insert(
        "mismatchCandidates".to_owned(),
        JsonValue::Array(Vec::new()),
    );
    let mut counts = FinalizedClaimCounts::default();
    for cell in json_member(coverage_object, "cells")?.array()? {
        update_finalized_claim_counts(cell.object()?, input, &mut counts)?;
    }
    set_claim_coverage_counts(coverage_object, &counts);
    write_atomic(output, &canonical_json_bytes(&coverage)?)?;
    Ok(format!(
        "applied {} exact accepted divergences",
        records.len()
    ))
}

fn verify_divergence_candidate_join(
    candidate: &BTreeMap<String, JsonValue>,
    record: &BTreeMap<String, JsonValue>,
) -> Result<(), String> {
    for field in [
        "builtin",
        "caseId",
        "dimension",
        "evidencePath",
        "evidenceRef",
        "mismatchCategories",
        "mismatchFingerprint",
        "normalizedObservationSha256",
        "platform",
        "profile",
        "rawObservationSha256",
    ] {
        if json_member(candidate, field)? != json_member(record, field)? {
            return Err(format!("accepted divergence substitutes mismatch {field}"));
        }
    }
    if canonical_json_digest(&JsonValue::Object(candidate.clone()))?
        != json_member(record, "candidateSha256")?.string()?
    {
        return Err("accepted divergence candidate digest is not exact".to_owned());
    }
    Ok(())
}

fn verify_generated_divergence_policy() -> Result<(), String> {
    use hell_builtins::assurance_catalogs as catalog;
    if !catalog::DIVERGENCE_REQUIRE_EXACT_SCOPE
        || !catalog::DIVERGENCE_REQUIRE_MISMATCH_FINGERPRINT
        || !catalog::DIVERGENCE_REQUIRE_EXPIRY
        || !catalog::DIVERGENCE_REQUIRE_IMPACT_APPROVALS
        || catalog::DIVERGENCE_ALLOW_WILDCARDS
    {
        return Err("generated divergence policy is not fail-closed".to_owned());
    }
    Ok(())
}

#[derive(Clone, Copy)]
struct DivergencePrototypePolicy {
    changed_files: u64,
    elapsed_seconds: u64,
    patch_bytes: u64,
}

#[derive(Clone)]
struct DivergencePrototypeEntry {
    after_source_sha256: String,
    before_source_sha256: String,
    builtin: String,
    case_id: String,
    dimension: CompatibilityDimension,
    patch_path: PathBuf,
    patch_sha256: String,
    plan_issue_number: u64,
    plan_owner: String,
    plan_rationale: String,
    source_path: PathBuf,
}

struct DivergencePrototypeManifest {
    entries: BTreeMap<String, DivergencePrototypeEntry>,
    policy: DivergencePrototypePolicy,
    sha256: String,
}

fn divergence_prototype_command(root: &Path, options: &Options) -> Result<String, String> {
    if options.action.as_deref().unwrap_or("run") != "run" {
        return Err("divergence-prototype supports only run".to_owned());
    }
    let input = required_path(
        &options.input,
        "divergence-prototype run requires --input platform artifact root",
    )?;
    let program = required_path(
        &options.program,
        "divergence-prototype run requires --program manifest",
    )?;
    let manifest = parse_divergence_prototype_manifest(root, program)?;
    let mismatch_root = input.join("mismatches");
    if !mismatch_root.is_dir() {
        return Ok(
            "retained no targeted prototypes because the shard has no mismatches".to_owned(),
        );
    }
    let mut entries = fs::read_dir(&mismatch_root)
        .map_err(|error| format!("cannot enumerate divergence mismatches: {error}"))?
        .collect::<Result<Vec<_>, _>>()
        .map_err(|error| format!("cannot enumerate divergence mismatches: {error}"))?;
    entries.sort_by_key(std::fs::DirEntry::file_name);
    let mut retained = 0_u64;
    let cases = committed_differential_cases();
    for directory in entries {
        if !directory
            .file_type()
            .map_err(|error| format!("cannot inspect mismatch entry: {error}"))?
            .is_dir()
        {
            return Err("divergence mismatch root contains a non-directory entry".to_owned());
        }
        let case_id = directory
            .file_name()
            .into_string()
            .map_err(|_| "divergence mismatch case ID is not UTF-8".to_owned())?;
        let Some(case) = cases.iter().find(|case| case.id.as_ref() == case_id) else {
            continue;
        };
        let output = input
            .join("divergence-objective")
            .join(&case_id)
            .join("fix-prototype");
        fs::create_dir_all(&output)
            .map_err(|error| format!("cannot create divergence prototype output: {error}"))?;
        let evidence = if let Some(entry) = manifest.entries.get(&case_id) {
            run_targeted_divergence_prototype(root, input, &output, case, entry, &manifest)?
        } else {
            unavailable_divergence_prototype(root, case, &manifest)?
        };
        let evidence_path = output.join("evidence.json");
        let evidence_bytes = canonical_json_bytes(&evidence)?;
        write_atomic(&evidence_path, &evidence_bytes)?;
        write_digest_sibling(&evidence_path, sha256_bytes(&evidence_bytes))?;
        retained = retained.saturating_add(1);
    }
    Ok(format!(
        "retained {retained} objective targeted-fix prototype attempts"
    ))
}

fn parse_divergence_prototype_manifest(
    root: &Path,
    path: &Path,
) -> Result<DivergencePrototypeManifest, String> {
    let bytes = fs::read(path)
        .map_err(|error| format!("cannot read divergence prototype manifest: {error}"))?;
    let text = std::str::from_utf8(&bytes)
        .map_err(|_| "divergence prototype manifest is not UTF-8".to_owned())?;
    let document = parse_json(text)?;
    if canonical_json_bytes(&document)? != bytes {
        return Err("divergence prototype manifest is not canonical JSON".to_owned());
    }
    let manifest = document.object()?;
    exact_keys(manifest, &["entries", "policy", "schemaVersion"])?;
    if json_member(manifest, "schemaVersion")?.number()? != 1 {
        return Err("divergence prototype manifest schemaVersion must be 1".to_owned());
    }
    let policy = parse_divergence_prototype_policy(json_member(manifest, "policy")?)?;
    let mut entries = BTreeMap::new();
    let mut previous = None;
    for value in json_member(manifest, "entries")?.array()? {
        let entry = parse_divergence_prototype_entry(root, value)?;
        if previous
            .as_deref()
            .is_some_and(|prior| prior >= entry.case_id.as_str())
            || entries.insert(entry.case_id.clone(), entry).is_some()
        {
            return Err("divergence prototype entries are duplicated or unsorted".to_owned());
        }
        previous = entries.last_key_value().map(|(case_id, _)| case_id.clone());
    }
    Ok(DivergencePrototypeManifest {
        entries,
        policy,
        sha256: sha256_bytes(&bytes).hex(),
    })
}

fn parse_divergence_prototype_policy(
    value: &JsonValue,
) -> Result<DivergencePrototypePolicy, String> {
    let policy = value.object()?;
    exact_keys(
        policy,
        &["maxChangedFiles", "maxElapsedSeconds", "maxPatchBytes"],
    )?;
    let parsed = DivergencePrototypePolicy {
        changed_files: json_member(policy, "maxChangedFiles")?.number()?,
        elapsed_seconds: json_member(policy, "maxElapsedSeconds")?.number()?,
        patch_bytes: json_member(policy, "maxPatchBytes")?.number()?,
    };
    if parsed.changed_files == 0
        || parsed.changed_files > 4
        || parsed.elapsed_seconds == 0
        || parsed.elapsed_seconds > 1_800
        || parsed.patch_bytes == 0
        || parsed.patch_bytes > 262_144
    {
        return Err("divergence prototype policy is outside fail-closed limits".to_owned());
    }
    Ok(parsed)
}

fn parse_divergence_prototype_entry(
    root: &Path,
    value: &JsonValue,
) -> Result<DivergencePrototypeEntry, String> {
    let entry = value.object()?;
    exact_keys(
        entry,
        &[
            "afterSourceSha256",
            "beforeSourceSha256",
            "builtin",
            "caseId",
            "dimension",
            "patchPath",
            "patchSha256",
            "planIssueNumber",
            "planOwner",
            "planRationale",
            "sourcePath",
        ],
    )?;
    let digest = |field: &str| -> Result<String, String> {
        let value = json_member(entry, field)?.string()?.to_owned();
        require_digest(&value, field)?;
        Ok(value)
    };
    let relative_path = |field: &str| -> Result<PathBuf, String> {
        let relative = json_member(entry, field)?.string()?;
        let path = repository_relative_path(root, relative)?;
        if path.extension().and_then(OsStr::to_str).is_none() {
            return Err(format!(
                "divergence prototype {field} lacks a file extension"
            ));
        }
        Ok(path)
    };
    let builtin = json_member(entry, "builtin")?.string()?.to_owned();
    if hell_builtins::lookup(&builtin).is_none() {
        return Err("divergence prototype names an unknown builtin".to_owned());
    }
    let case_id = json_member(entry, "caseId")?.string()?.to_owned();
    if !committed_differential_cases()
        .iter()
        .any(|case| case.id.as_ref() == case_id)
    {
        return Err("divergence prototype names an unknown committed case".to_owned());
    }
    let plan_owner = json_member(entry, "planOwner")?.string()?.to_owned();
    validate_prototype_authored_atom(&plan_owner, "plan owner")?;
    let plan_rationale = json_member(entry, "planRationale")?.string()?.to_owned();
    if plan_rationale.len() < 24 || plan_rationale.len() > 2_048 {
        return Err("divergence prototype plan rationale is outside UTF-8 byte limits".to_owned());
    }
    let plan_issue_number = json_member(entry, "planIssueNumber")?.number()?;
    if plan_issue_number == 0 {
        return Err("divergence prototype plan issue must be nonzero".to_owned());
    }
    Ok(DivergencePrototypeEntry {
        after_source_sha256: digest("afterSourceSha256")?,
        before_source_sha256: digest("beforeSourceSha256")?,
        builtin,
        case_id,
        dimension: compatibility_dimension(json_member(entry, "dimension")?.string()?)?,
        patch_path: relative_path("patchPath")?,
        patch_sha256: digest("patchSha256")?,
        plan_issue_number,
        plan_owner,
        plan_rationale,
        source_path: relative_path("sourcePath")?,
    })
}

fn validate_prototype_authored_atom(value: &str, label: &str) -> Result<(), String> {
    if value.is_empty()
        || !value.bytes().all(|byte| {
            byte.is_ascii_alphanumeric() || matches!(byte, b'@' | b':' | b'.' | b'_' | b'-' | b'/')
        })
    {
        return Err(format!("divergence prototype {label} is not normalized"));
    }
    Ok(())
}

fn unavailable_divergence_prototype(
    root: &Path,
    case: &DifferentialCase,
    manifest: &DivergencePrototypeManifest,
) -> Result<JsonValue, String> {
    Ok(JsonValue::Object(BTreeMap::from([
        ("schemaVersion".to_owned(), JsonValue::Number(1)),
        (
            "state".to_owned(),
            JsonValue::String("attempted-unavailable".to_owned()),
        ),
        (
            "reason".to_owned(),
            JsonValue::String("no-reviewed-prototype-entry".to_owned()),
        ),
        ("caseId".to_owned(), JsonValue::String(case.id.to_string())),
        (
            "candidateCommit".to_owned(),
            JsonValue::String(git_output(root, &["rev-parse", "HEAD"])?.trim().to_owned()),
        ),
        (
            "manifestSha256".to_owned(),
            JsonValue::String(manifest.sha256.clone()),
        ),
        (
            "policy".to_owned(),
            divergence_prototype_policy_json(manifest.policy),
        ),
        ("elapsedMilliseconds".to_owned(), JsonValue::Number(0)),
        (
            "derivedFixability".to_owned(),
            JsonValue::String("undetermined".to_owned()),
        ),
    ])))
}

fn divergence_prototype_policy_json(policy: DivergencePrototypePolicy) -> JsonValue {
    JsonValue::Object(BTreeMap::from([
        (
            "maxChangedFiles".to_owned(),
            JsonValue::Number(policy.changed_files),
        ),
        (
            "maxElapsedSeconds".to_owned(),
            JsonValue::Number(policy.elapsed_seconds),
        ),
        (
            "maxPatchBytes".to_owned(),
            JsonValue::Number(policy.patch_bytes),
        ),
    ]))
}

fn divergence_prototype_experiment_budget_milliseconds(
    case: &DifferentialCase,
    entry: &DivergencePrototypeEntry,
) -> Result<u64, String> {
    let mut cases = committed_differential_cases();
    crate::suite::bind_runtime_process_helper(&mut cases)?;
    let mut budget = u64::try_from(case.timeout.as_millis()).unwrap_or(u64::MAX);
    for neighbor in cases.iter().filter(|neighbor| neighbor.id != case.id) {
        if exact_case_target(neighbor, &entry.builtin, entry.dimension)
            .is_ok_and(|target| !target.boundary_classes.is_empty())
        {
            budget = budget
                .saturating_add(u64::try_from(neighbor.timeout.as_millis()).unwrap_or(u64::MAX));
        }
    }
    Ok(budget)
}

fn cost_exceeded_divergence_prototype(
    root: &Path,
    case: &DifferentialCase,
    manifest: &DivergencePrototypeManifest,
    estimated_execution_milliseconds: u64,
) -> Result<JsonValue, String> {
    Ok(JsonValue::Object(BTreeMap::from([
        ("schemaVersion".to_owned(), JsonValue::Number(1)),
        (
            "state".to_owned(),
            JsonValue::String("cost-exceeded".to_owned()),
        ),
        (
            "reason".to_owned(),
            JsonValue::String("experiment-timeout-budget-exceeds-policy".to_owned()),
        ),
        ("caseId".to_owned(), JsonValue::String(case.id.to_string())),
        (
            "candidateCommit".to_owned(),
            JsonValue::String(git_output(root, &["rev-parse", "HEAD"])?.trim().to_owned()),
        ),
        (
            "manifestSha256".to_owned(),
            JsonValue::String(manifest.sha256.clone()),
        ),
        (
            "policy".to_owned(),
            divergence_prototype_policy_json(manifest.policy),
        ),
        (
            "estimatedExecutionMilliseconds".to_owned(),
            JsonValue::Number(estimated_execution_milliseconds),
        ),
        (
            "derivedFixability".to_owned(),
            JsonValue::String("not-currently-fixable".to_owned()),
        ),
    ])))
}

fn run_targeted_divergence_prototype(
    root: &Path,
    artifact_root: &Path,
    output: &Path,
    case: &DifferentialCase,
    entry: &DivergencePrototypeEntry,
    manifest: &DivergencePrototypeManifest,
) -> Result<JsonValue, String> {
    exact_case_target(case, &entry.builtin, entry.dimension)?;
    let (_, implementation_location, _) = builtin_implementation_source_facts(&entry.builtin)?;
    let implementation_path = implementation_location
        .rsplit_once(':')
        .map_or(implementation_location.as_str(), |(path, _)| path);
    if path_text(
        entry
            .source_path
            .strip_prefix(root)
            .map_err(|_| "prototype source is outside repository".to_owned())?,
    )? != implementation_path
    {
        return Err(
            "divergence prototype source is not the exact builtin implementation".to_owned(),
        );
    }
    let patch = fs::read(&entry.patch_path)
        .map_err(|error| format!("cannot read divergence prototype patch: {error}"))?;
    let patch_len = u64::try_from(patch.len())
        .map_err(|_| "divergence prototype patch size exceeds u64".to_owned())?;
    if sha256_bytes(&patch).hex() != entry.patch_sha256 || patch_len > manifest.policy.patch_bytes {
        return Err("divergence prototype patch digest or size changed".to_owned());
    }
    if record_digest(&entry.source_path)? != entry.before_source_sha256 {
        return Err("divergence prototype base source digest changed".to_owned());
    }
    let experiment_budget_milliseconds =
        divergence_prototype_experiment_budget_milliseconds(case, entry)?;
    let maximum_milliseconds = manifest.policy.elapsed_seconds.saturating_mul(1_000);
    if experiment_budget_milliseconds >= maximum_milliseconds {
        return cost_exceeded_divergence_prototype(
            root,
            case,
            manifest,
            experiment_budget_milliseconds,
        );
    }
    let build_timeout_seconds = maximum_milliseconds
        .saturating_sub(experiment_budget_milliseconds)
        .checked_div(1_000)
        .unwrap_or(0)
        .max(1);
    let temporary = create_private_temp_directory("hell-divergence-prototype")?;
    let worktree = temporary.join("subject");
    let started = std::time::Instant::now();
    add_divergence_prototype_worktree(root, &worktree)?;
    let result = run_targeted_divergence_prototype_in_worktree(
        root,
        artifact_root,
        output,
        &worktree,
        case,
        entry,
        manifest,
        started,
        build_timeout_seconds,
    );
    let cleanup = remove_divergence_prototype_worktree(root, &worktree);
    match (result, cleanup) {
        (Ok(value), Ok(())) => Ok(value),
        (Err(error), Ok(())) | (Ok(_), Err(error)) => Err(error),
        (Err(error), Err(cleanup)) => Err(format!("{error}; prototype cleanup failed: {cleanup}")),
    }
}

fn add_divergence_prototype_worktree(root: &Path, worktree: &Path) -> Result<(), String> {
    let result = CommandSpec::new("git", std::time::Duration::from_mins(1))
        .arguments([
            OsString::from("worktree"),
            OsString::from("add"),
            OsString::from("--detach"),
            worktree.as_os_str().to_owned(),
            OsString::from("HEAD"),
        ])
        .current_directory(root)
        .run()
        .map_err(|error| format!("cannot create prototype worktree: {error}"))?;
    if result.timed_out || !result.status.success() {
        return Err("cannot create isolated divergence prototype worktree".to_owned());
    }
    Ok(())
}

fn remove_divergence_prototype_worktree(root: &Path, worktree: &Path) -> Result<(), String> {
    let result = CommandSpec::new("git", std::time::Duration::from_mins(1))
        .arguments([
            OsString::from("worktree"),
            OsString::from("remove"),
            OsString::from("--force"),
            worktree.as_os_str().to_owned(),
        ])
        .current_directory(root)
        .run()
        .map_err(|error| format!("cannot remove prototype worktree: {error}"))?;
    if result.timed_out || !result.status.success() {
        return Err("cannot remove isolated divergence prototype worktree".to_owned());
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn run_targeted_divergence_prototype_in_worktree(
    root: &Path,
    artifact_root: &Path,
    output: &Path,
    worktree: &Path,
    case: &DifferentialCase,
    entry: &DivergencePrototypeEntry,
    manifest: &DivergencePrototypeManifest,
    started: std::time::Instant,
    build_timeout_seconds: u64,
) -> Result<JsonValue, String> {
    let (relative_patch, relative_source) = prototype_relative_paths(root, entry)?;
    apply_divergence_prototype_patch(worktree, &entry.patch_path)?;
    verify_divergence_prototype_changed_surface(worktree, relative_source, entry, manifest.policy)?;
    let base_tree_id = git_output(root, &["rev-parse", "HEAD^{tree}"])?
        .trim()
        .to_owned();
    require_git_sha_text(&base_tree_id, "prototype base tree")?;
    let base_tree_sha256 = sha256_bytes(base_tree_id.as_bytes()).hex();
    let (patched_tree_id, patched_tree_sha256) =
        divergence_prototype_tree_identity(worktree, relative_source)?;
    let trees = DivergencePrototypeTreeFacts {
        base_id: base_tree_id,
        base_sha256: base_tree_sha256,
        patched_id: patched_tree_id,
        patched_sha256: patched_tree_sha256,
    };
    let build = build_divergence_prototype(worktree, build_timeout_seconds)?;
    let elapsed_milliseconds = u64::try_from(started.elapsed().as_millis()).unwrap_or(u64::MAX);
    if build.timed_out || !build.status.success() {
        return failed_divergence_prototype_evidence(
            root,
            case,
            entry,
            manifest,
            &trees,
            elapsed_milliseconds,
            &build,
        );
    }
    let executable_name = if cfg!(windows) { "hell.exe" } else { "hell" };
    let prototype_path = divergence_prototype_target_directory(worktree)
        .join("release")
        .join(executable_name);
    let mut prototype = verify_executable(
        &prototype_path,
        ExecutableRole::Candidate,
        None,
        hell_builtins::LANGUAGE_VERSION,
    )
    .map_err(|error| format!("cannot verify rebuilt divergence prototype: {error}"))?;
    let mut candidate = verify_executable(
        &root.join("target").join("release").join(executable_name),
        ExecutableRole::Candidate,
        None,
        hell_builtins::LANGUAGE_VERSION,
    )
    .map_err(|error| format!("cannot verify base candidate for divergence prototype: {error}"))?;
    let assurance_epoch =
        verify_prototype_base_candidate(artifact_root, case, entry, candidate.sha256)?;
    prototype.assurance_epoch_sha256 = Some(assurance_epoch);
    candidate.assurance_epoch_sha256 = Some(assurance_epoch);
    if prototype.sha256 == candidate.sha256 {
        return Err(
            "divergence prototype executable is identical to the base candidate".to_owned(),
        );
    }
    let retained_executable_path = output.join(executable_name);
    fs::copy(&prototype_path, &retained_executable_path)
        .map_err(|error| format!("cannot retain divergence prototype executable: {error}"))?;
    let mut retained_prototype = verify_executable(
        &retained_executable_path,
        ExecutableRole::Candidate,
        Some(prototype.sha256),
        hell_builtins::LANGUAGE_VERSION,
    )
    .map_err(|error| format!("cannot reverify retained divergence prototype: {error}"))?;
    retained_prototype.assurance_epoch_sha256 = Some(assurance_epoch);
    let experiment = run_divergence_prototype_experiment(
        artifact_root,
        output,
        case,
        entry,
        &retained_prototype,
    )?;
    let elapsed_milliseconds = u64::try_from(started.elapsed().as_millis()).unwrap_or(u64::MAX);
    successful_divergence_prototype_evidence(
        root,
        case,
        entry,
        manifest,
        relative_patch,
        &trees,
        &candidate,
        &retained_prototype,
        &build,
        elapsed_milliseconds,
        experiment,
    )
}

fn prototype_relative_paths<'a>(
    root: &Path,
    entry: &'a DivergencePrototypeEntry,
) -> Result<(&'a Path, &'a Path), String> {
    Ok((
        entry
            .patch_path
            .strip_prefix(root)
            .map_err(|_| "prototype patch is outside repository".to_owned())?,
        entry
            .source_path
            .strip_prefix(root)
            .map_err(|_| "prototype source is outside repository".to_owned())?,
    ))
}

fn verify_divergence_prototype_changed_surface(
    worktree: &Path,
    relative_source: &Path,
    entry: &DivergencePrototypeEntry,
    policy: DivergencePrototypePolicy,
) -> Result<(), String> {
    let changed = git_output(worktree, &["diff", "--name-only", "--"])?
        .lines()
        .map(str::to_owned)
        .collect::<BTreeSet<_>>();
    if changed != BTreeSet::from([path_text(relative_source)?])
        || u64::try_from(changed.len()).unwrap_or(u64::MAX) > policy.changed_files
        || record_digest(&worktree.join(relative_source))? != entry.after_source_sha256
        || entry.after_source_sha256 == entry.before_source_sha256
    {
        return Err("divergence prototype changed an unreviewed source surface".to_owned());
    }
    Ok(())
}

fn apply_divergence_prototype_patch(worktree: &Path, patch: &Path) -> Result<(), String> {
    for check in [true, false] {
        let mut arguments = vec![OsString::from("apply")];
        if check {
            arguments.push(OsString::from("--check"));
        }
        arguments.push(OsString::from("--whitespace=error-all"));
        arguments.push(patch.as_os_str().to_owned());
        let result = CommandSpec::new("git", std::time::Duration::from_mins(1))
            .arguments(arguments)
            .current_directory(worktree)
            .run()
            .map_err(|error| format!("cannot execute prototype patch: {error}"))?;
        if result.timed_out || !result.status.success() {
            return Err("reviewed divergence prototype patch does not apply cleanly".to_owned());
        }
    }
    Ok(())
}

fn divergence_prototype_tree_identity(
    worktree: &Path,
    source: &Path,
) -> Result<(String, String), String> {
    let source_text = path_text(source)?;
    git_output(worktree, &["add", "--", &source_text])?;
    let tree = git_output(worktree, &["write-tree"])?;
    let tree = tree.trim();
    require_git_sha_text(tree, "prototype tree")?;
    Ok((tree.to_owned(), sha256_bytes(tree.as_bytes()).hex()))
}

fn verify_prototype_base_candidate(
    artifact_root: &Path,
    case: &DifferentialCase,
    entry: &DivergencePrototypeEntry,
    candidate_sha256: Digest,
) -> Result<Digest, String> {
    let bundle = artifact_root
        .join("evidence")
        .join("observations")
        .join(case.id.as_ref());
    let classification = hell_testkit::classify_retained_observation_bundle(&bundle, case)
        .map_err(|error| format!("cannot classify prototype source mismatch: {error}"))?;
    let hell_testkit::RetainedObservationClassification::Mismatch { .. } = classification else {
        return Err("divergence prototype source case is not a retained mismatch".to_owned());
    };
    exact_case_target(case, &entry.builtin, entry.dimension)?;
    if retained_candidate_executable_sha256(&bundle)? != candidate_sha256 {
        return Err(
            "divergence prototype base executable differs from retained mismatch".to_owned(),
        );
    }
    retained_candidate_assurance_epoch(&bundle)
}

fn retained_candidate_assurance_epoch(bundle: &Path) -> Result<Digest, String> {
    let observation = parse_json(&read_text(
        &bundle.join("candidate").join("observation.json"),
    )?)?;
    let identity = json_member(observation.object()?, "identity")?.object()?;
    let value = json_member(identity, "assuranceEpochSha256")?.string()?;
    Digest::from_hex(value).map_err(|error| format!("invalid retained candidate epoch: {error}"))
}

fn retained_candidate_executable_sha256(bundle: &Path) -> Result<Digest, String> {
    let observation = parse_json(&read_text(
        &bundle.join("candidate").join("observation.json"),
    )?)?;
    let identity = json_member(observation.object()?, "identity")?.object()?;
    let value = json_member(identity, "sha256")?.string()?;
    Digest::from_hex(value)
        .map_err(|error| format!("invalid retained candidate executable digest: {error}"))
}

fn build_divergence_prototype(
    worktree: &Path,
    timeout_seconds: u64,
) -> Result<crate::command::CommandResult, String> {
    CommandSpec::new("cargo", std::time::Duration::from_secs(timeout_seconds))
        .arguments([
            OsString::from("build"),
            OsString::from("--locked"),
            OsString::from("--release"),
            OsString::from("--package"),
            OsString::from("hell-cli"),
            OsString::from("--bin"),
            OsString::from("hell"),
            OsString::from("--features"),
            OsString::from("compat-tracing"),
            OsString::from("--target-dir"),
            divergence_prototype_target_directory(worktree).into_os_string(),
        ])
        .current_directory(worktree)
        .run()
        .map_err(|error| format!("cannot build divergence prototype: {error}"))
}

fn divergence_prototype_target_directory(worktree: &Path) -> PathBuf {
    worktree.join("target").join("divergence-prototype")
}

struct DivergencePrototypeExperiment {
    current: JsonValue,
    neighbors: Vec<JsonValue>,
    resolves_current: bool,
    preserves_neighbors: bool,
}

struct DivergencePrototypeTreeFacts {
    base_id: String,
    base_sha256: String,
    patched_id: String,
    patched_sha256: String,
}

fn run_divergence_prototype_experiment(
    artifact_root: &Path,
    output: &Path,
    case: &DifferentialCase,
    entry: &DivergencePrototypeEntry,
    prototype: &ExecutableIdentity,
) -> Result<DivergencePrototypeExperiment, String> {
    let current_bundle = artifact_root
        .join("evidence")
        .join("observations")
        .join(case.id.as_ref());
    let (current, resolves_current) = run_one_divergence_prototype_case(
        case,
        prototype,
        &current_bundle,
        &output.join("current"),
        false,
    )?;
    let mut cases = committed_differential_cases();
    crate::suite::bind_runtime_process_helper(&mut cases)?;
    let mut neighbors = Vec::new();
    let mut preserves_neighbors = true;
    for neighbor in cases.iter().filter(|neighbor| neighbor.id != case.id) {
        let Ok(target) = exact_case_target(neighbor, &entry.builtin, entry.dimension) else {
            continue;
        };
        if target.boundary_classes.is_empty() {
            continue;
        }
        let bundle = artifact_root
            .join("evidence")
            .join("observations")
            .join(neighbor.id.as_ref());
        let (fact, preserved) = run_one_divergence_prototype_case(
            neighbor,
            prototype,
            &bundle,
            &output.join("neighbors").join(neighbor.id.as_ref()),
            true,
        )?;
        preserves_neighbors &= preserved;
        neighbors.push(fact);
    }
    if neighbors.is_empty() {
        return Err(
            "divergence prototype experiment has no same-target boundary neighbors".to_owned(),
        );
    }
    Ok(DivergencePrototypeExperiment {
        current,
        neighbors,
        resolves_current,
        preserves_neighbors,
    })
}

fn run_one_divergence_prototype_case(
    case: &DifferentialCase,
    prototype: &ExecutableIdentity,
    baseline_bundle: &Path,
    output: &Path,
    preserve_baseline: bool,
) -> Result<(JsonValue, bool), String> {
    let baseline = hell_testkit::classify_retained_observation_bundle(baseline_bundle, case)
        .map_err(|error| format!("cannot classify prototype baseline {:?}: {error}", case.id))?;
    let mut profile_case = case.clone();
    profile_case
        .claim_evidence
        .as_mut()
        .ok_or_else(|| format!("prototype case {:?} is not reviewed", case.id))?
        .profile = ExecutionProfile::Upstream;
    let verified =
        observe_verified_executable_profile(prototype, &profile_case, ExecutionProfile::Upstream)
            .map_err(|error| format!("cannot execute prototype case {:?}: {error}", case.id))?;
    let retained = retain_verified_profile_observation(output, &profile_case, &verified)
        .map_err(|error| format!("cannot retain prototype case {:?}: {error}", case.id))?;
    let classification =
        hell_testkit::classify_retained_alternate_executable_observation_against_oracle(
            output,
            &profile_case,
            baseline_bundle,
            ExecutionProfile::Upstream,
            prototype.sha256,
        )
        .map_err(|error| format!("cannot classify prototype case {:?}: {error}", case.id))?;
    let (baseline_state, baseline_fingerprint) = retained_classification_identity(&baseline);
    let (prototype_state, prototype_fingerprint) =
        retained_classification_identity(&classification);
    let preserved = retained_classification_identity(&baseline)
        == retained_classification_identity(&classification);
    let resolves = matches!(prototype_state, "exact" | "normalized");
    let accepted = if preserve_baseline {
        preserved
    } else {
        resolves
    };
    Ok((
        JsonValue::Object(BTreeMap::from([
            ("caseId".to_owned(), JsonValue::String(case.id.to_string())),
            (
                "sourceSha256".to_owned(),
                JsonValue::String(sha256_bytes(case.source.as_bytes()).hex()),
            ),
            (
                "baselineClassification".to_owned(),
                JsonValue::String(baseline_state.to_owned()),
            ),
            (
                "baselineFingerprintSha256".to_owned(),
                baseline_fingerprint.map_or(JsonValue::Null, JsonValue::String),
            ),
            (
                "prototypeClassification".to_owned(),
                JsonValue::String(prototype_state.to_owned()),
            ),
            (
                "prototypeFingerprintSha256".to_owned(),
                prototype_fingerprint.map_or(JsonValue::Null, JsonValue::String),
            ),
            (
                "prototypePackageSha256".to_owned(),
                JsonValue::String(retained.package_sha256.hex()),
            ),
            (
                "prototypeExecutableSha256".to_owned(),
                JsonValue::String(retained.executable_sha256.hex()),
            ),
            (
                "prototypeExecutionInputSha256".to_owned(),
                JsonValue::String(retained.execution_input_sha256.hex()),
            ),
            (
                "prototypeObservationSha256".to_owned(),
                JsonValue::String(retained.observation_sha256.hex()),
            ),
            ("accepted".to_owned(), JsonValue::Bool(accepted)),
        ])),
        accepted,
    ))
}

fn failed_divergence_prototype_evidence(
    root: &Path,
    case: &DifferentialCase,
    entry: &DivergencePrototypeEntry,
    manifest: &DivergencePrototypeManifest,
    trees: &DivergencePrototypeTreeFacts,
    elapsed_milliseconds: u64,
    build: &crate::command::CommandResult,
) -> Result<JsonValue, String> {
    Ok(JsonValue::Object(BTreeMap::from([
        ("schemaVersion".to_owned(), JsonValue::Number(1)),
        (
            "state".to_owned(),
            JsonValue::String(
                if build.timed_out {
                    "cost-exceeded"
                } else {
                    "attempted-failed"
                }
                .to_owned(),
            ),
        ),
        (
            "reason".to_owned(),
            JsonValue::String(
                if build.timed_out {
                    "prototype-build-timeout"
                } else {
                    "prototype-build-failed"
                }
                .to_owned(),
            ),
        ),
        ("caseId".to_owned(), JsonValue::String(case.id.to_string())),
        (
            "candidateCommit".to_owned(),
            JsonValue::String(git_output(root, &["rev-parse", "HEAD"])?.trim().to_owned()),
        ),
        (
            "manifestSha256".to_owned(),
            JsonValue::String(manifest.sha256.clone()),
        ),
        (
            "patchSha256".to_owned(),
            JsonValue::String(entry.patch_sha256.clone()),
        ),
        (
            "baseTreeId".to_owned(),
            JsonValue::String(trees.base_id.clone()),
        ),
        (
            "baseTreeSha256".to_owned(),
            JsonValue::String(trees.base_sha256.clone()),
        ),
        (
            "patchedTreeId".to_owned(),
            JsonValue::String(trees.patched_id.clone()),
        ),
        (
            "patchedTreeSha256".to_owned(),
            JsonValue::String(trees.patched_sha256.clone()),
        ),
        (
            "buildStdoutSha256".to_owned(),
            JsonValue::String(build.stdout_sha256.hex()),
        ),
        (
            "buildStderrSha256".to_owned(),
            JsonValue::String(build.stderr_sha256.hex()),
        ),
        (
            "elapsedMilliseconds".to_owned(),
            JsonValue::Number(elapsed_milliseconds),
        ),
        (
            "policy".to_owned(),
            divergence_prototype_policy_json(manifest.policy),
        ),
        (
            "derivedFixability".to_owned(),
            JsonValue::String("undetermined".to_owned()),
        ),
    ])))
}

#[allow(clippy::too_many_arguments)]
fn successful_divergence_prototype_evidence(
    root: &Path,
    case: &DifferentialCase,
    entry: &DivergencePrototypeEntry,
    manifest: &DivergencePrototypeManifest,
    relative_patch: &Path,
    trees: &DivergencePrototypeTreeFacts,
    candidate: &ExecutableIdentity,
    prototype: &ExecutableIdentity,
    build: &crate::command::CommandResult,
    elapsed_milliseconds: u64,
    experiment: DivergencePrototypeExperiment,
) -> Result<JsonValue, String> {
    let within_cost = elapsed_milliseconds <= manifest.policy.elapsed_seconds.saturating_mul(1_000);
    let succeeded = experiment.resolves_current && experiment.preserves_neighbors && within_cost;
    let result = if succeeded {
        "prototype-succeeded"
    } else if !within_cost {
        "cost-exceeded"
    } else if !experiment.resolves_current {
        "prototype-did-not-resolve"
    } else {
        "prototype-regressed-neighbor"
    };
    let mut evidence = successful_prototype_identity_fields(
        root,
        case,
        entry,
        manifest,
        relative_patch,
        trees,
        candidate,
        prototype,
        build,
    )?;
    evidence.extend([
        ("schemaVersion".to_owned(), JsonValue::Number(1)),
        (
            "state".to_owned(),
            JsonValue::String("executed-and-replayed".to_owned()),
        ),
        ("result".to_owned(), JsonValue::String(result.to_owned())),
        ("caseId".to_owned(), JsonValue::String(case.id.to_string())),
        (
            "builtin".to_owned(),
            JsonValue::String(entry.builtin.clone()),
        ),
        (
            "dimension".to_owned(),
            JsonValue::String(entry.dimension.as_str().to_owned()),
        ),
        ("currentCase".to_owned(), experiment.current),
        (
            "neighborCases".to_owned(),
            JsonValue::Array(experiment.neighbors),
        ),
        (
            "currentMismatchResolved".to_owned(),
            JsonValue::Bool(experiment.resolves_current),
        ),
        (
            "neighborsPreserved".to_owned(),
            JsonValue::Bool(experiment.preserves_neighbors),
        ),
        (
            "elapsedMilliseconds".to_owned(),
            JsonValue::Number(elapsed_milliseconds),
        ),
        (
            "policy".to_owned(),
            divergence_prototype_policy_json(manifest.policy),
        ),
        (
            "planIssueNumber".to_owned(),
            JsonValue::Number(entry.plan_issue_number),
        ),
        (
            "planOwner".to_owned(),
            JsonValue::String(entry.plan_owner.clone()),
        ),
        (
            "planRationale".to_owned(),
            JsonValue::String(entry.plan_rationale.clone()),
        ),
        (
            "derivedFixability".to_owned(),
            JsonValue::String(
                if succeeded {
                    "fix-planned"
                } else {
                    "undetermined"
                }
                .to_owned(),
            ),
        ),
    ]);
    Ok(JsonValue::Object(evidence))
}

#[allow(clippy::too_many_arguments)]
fn successful_prototype_identity_fields(
    root: &Path,
    case: &DifferentialCase,
    entry: &DivergencePrototypeEntry,
    manifest: &DivergencePrototypeManifest,
    relative_patch: &Path,
    trees: &DivergencePrototypeTreeFacts,
    candidate: &ExecutableIdentity,
    prototype: &ExecutableIdentity,
    build: &crate::command::CommandResult,
) -> Result<BTreeMap<String, JsonValue>, String> {
    let source = entry
        .source_path
        .strip_prefix(root)
        .map_err(|_| "prototype source is outside repository".to_owned())?;
    let executable = prototype
        .path
        .file_name()
        .and_then(OsStr::to_str)
        .ok_or_else(|| "retained prototype executable name is not UTF-8".to_owned())?;
    Ok(BTreeMap::from([
        (
            "candidateCommit".to_owned(),
            JsonValue::String(git_output(root, &["rev-parse", "HEAD"])?.trim().to_owned()),
        ),
        (
            "assuranceEpochSha256".to_owned(),
            JsonValue::String(
                candidate
                    .assurance_epoch_sha256
                    .ok_or_else(|| "prototype candidate has no assurance epoch".to_owned())?
                    .hex(),
            ),
        ),
        (
            "manifestSha256".to_owned(),
            JsonValue::String(manifest.sha256.clone()),
        ),
        (
            "patchPath".to_owned(),
            JsonValue::String(path_text(relative_patch)?),
        ),
        (
            "patchSha256".to_owned(),
            JsonValue::String(entry.patch_sha256.clone()),
        ),
        (
            "sourcePath".to_owned(),
            JsonValue::String(path_text(source)?),
        ),
        (
            "beforeSourceSha256".to_owned(),
            JsonValue::String(entry.before_source_sha256.clone()),
        ),
        (
            "afterSourceSha256".to_owned(),
            JsonValue::String(entry.after_source_sha256.clone()),
        ),
        (
            "baseTreeId".to_owned(),
            JsonValue::String(trees.base_id.clone()),
        ),
        (
            "baseTreeSha256".to_owned(),
            JsonValue::String(trees.base_sha256.clone()),
        ),
        (
            "patchedTreeId".to_owned(),
            JsonValue::String(trees.patched_id.clone()),
        ),
        (
            "patchedTreeSha256".to_owned(),
            JsonValue::String(trees.patched_sha256.clone()),
        ),
        (
            "candidateExecutableSha256".to_owned(),
            JsonValue::String(candidate.sha256.hex()),
        ),
        (
            "prototypeExecutableSha256".to_owned(),
            JsonValue::String(prototype.sha256.hex()),
        ),
        (
            "prototypeExecutablePath".to_owned(),
            JsonValue::String(executable.to_owned()),
        ),
        (
            "buildStdoutSha256".to_owned(),
            JsonValue::String(build.stdout_sha256.hex()),
        ),
        (
            "buildStderrSha256".to_owned(),
            JsonValue::String(build.stderr_sha256.hex()),
        ),
        (
            "buildDurationMilliseconds".to_owned(),
            JsonValue::Number(u64::try_from(build.duration.as_millis()).unwrap_or(u64::MAX)),
        ),
        ("caseId".to_owned(), JsonValue::String(case.id.to_string())),
    ]))
}

fn residual_risk_command(root: &Path, options: &Options) -> Result<String, String> {
    if options.action.as_deref().unwrap_or("report") != "report" {
        return Err("residual-risk supports only report".to_owned());
    }
    let input = required_path(
        &options.input,
        "residual-risk report requires --input evidence coverage directory",
    )?;
    let output = required_path(&options.output, "residual-risk report requires --output")?;
    let coverage_path = input.join("claim-coverage.finalized.json");
    let coverage = parse_json(&read_text(&coverage_path)?)?;
    let coverage = coverage.object()?;
    let candidate = json_member(coverage, "candidateSourceCommit")?.string()?;
    let assurance_epoch = json_member(coverage, "assuranceEpochSha256")?.string()?;
    if candidate != git_output(root, &["rev-parse", "HEAD"])?.trim()
        || assurance_epoch != epoch(root)?.1.hex()
    {
        return Err("residual-risk input candidate or epoch is stale".to_owned());
    }
    let cells = json_member(coverage, "cells")?.array()?;
    let status_counts = claim_coverage_status_counts(coverage)?;
    let unverified = status_counts["unverified"];
    let out_of_scope = status_counts["not-applicable"];
    let boundary_classes = residual_boundary_classes(cells)?;
    let missing_boundaries = residual_missing_boundary_count(&boundary_classes)?;
    let missing_obligations = residual_missing_obligation_count(cells)?;
    let unacceptable = json_member(coverage, "requiredPlatformGaps")?
        .number()?
        .saturating_add(json_member(coverage, "ambiguousClaimScopes")?.number()?);
    let mutation_path = input.join("mutation-score.json");
    let undetected = mutation_undetected_count(&mutation_path)?;
    let (mutation_families, undetected_mutant_ids) = residual_mutation_facts(&mutation_path)?;
    let native = residual_native_corpus_inputs(input, candidate, assurance_epoch)?;
    let capability_evidence = residual_observed_capability_evidence(cells)?;
    let evidence_age = residual_evidence_age(root, &mutation_path, &native, None)?;
    let known_issues = residual_known_open_issues(input, cells, &undetected_mutant_ids)?;
    let critical_non_exact = residual_critical_non_exact_cells(cells)?;
    let minimum_mutation_score = residual_minimum_mutation_score(&mutation_families)?;
    let factors = ResidualRiskFactors {
        missing_boundaries,
        missing_obligations,
        unacceptable,
        undetected,
        unverified,
        out_of_scope,
        normalized: status_counts["normalized"],
        platform_dependent: status_counts["platform-dependent"],
        divergences: status_counts["deliberate-divergence"],
        critical_non_exact,
        minimum_mutation_score,
        stale_evidence_sources: json_member(evidence_age.object()?, "staleSourceCount")?
            .number()?,
        aging_evidence_sources: json_member(evidence_age.object()?, "warningSourceCount")?
            .number()?,
        observed_platforms: native.platforms.len(),
        custody_current: false,
    };
    let overall = residual_overall_tier(&factors, &load_assurance_policy(root)?.residual);
    let mut fields =
        residual_identity_and_status_fields(candidate, assurance_epoch, &status_counts);
    fields.insert(
        "claimCoverageSha256".to_owned(),
        JsonValue::String(record_digest(&coverage_path)?),
    );
    fields.insert(
        "mutationReportSha256".to_owned(),
        JsonValue::String(record_digest(&mutation_path)?),
    );
    fields.extend(residual_evidence_fields(ResidualEvidenceInputs {
        root,
        cells,
        boundary_classes,
        mutation_families,
        undetected_mutant_ids,
        native: &native,
        capability_evidence,
        evidence_age,
        known_issues,
    })?);
    fields.insert(
        "criticalNonExactClaimCells".to_owned(),
        JsonValue::Number(critical_non_exact),
    );
    fields.insert(
        "minimumMutationFamilyScorePerMille".to_owned(),
        JsonValue::Number(minimum_mutation_score),
    );
    fields.insert(
        "missingClaimObligations".to_owned(),
        JsonValue::Number(missing_obligations),
    );
    fields.extend(residual_gate_fields(
        missing_boundaries,
        out_of_scope,
        overall,
        undetected,
        unacceptable,
        unverified,
    ));
    write_residual_risk_report(output, fields)
}

fn write_residual_risk_report(
    output: &Path,
    fields: BTreeMap<String, JsonValue>,
) -> Result<String, String> {
    write_atomic(output, &canonical_json_bytes(&JsonValue::Object(fields))?)?;
    Ok(format!(
        "wrote evidence-derived residual risk {}",
        output.display()
    ))
}

fn mutation_undetected_count(path: &Path) -> Result<u64, String> {
    if !path.is_file() {
        return Err("residual-risk requires the exact signed mutation report".to_owned());
    }
    let report = parse_json(&read_text(path)?)?;
    json_member(report.object()?, "undetectedCriticalMutants")?.number()
}

fn residual_identity_and_status_fields(
    candidate: &str,
    assurance_epoch: &str,
    status_counts: &BTreeMap<String, u64>,
) -> BTreeMap<String, JsonValue> {
    let promoted = status_counts["exact"]
        .saturating_add(status_counts["normalized"])
        .saturating_add(status_counts["platform-dependent"])
        .saturating_add(status_counts["deliberate-divergence"]);
    BTreeMap::from([
        ("schemaVersion".to_owned(), JsonValue::Number(3)),
        (
            "candidateSourceCommit".to_owned(),
            JsonValue::String(candidate.to_owned()),
        ),
        (
            "assuranceEpochSha256".to_owned(),
            JsonValue::String(assurance_epoch.to_owned()),
        ),
        (
            "claimStatusCounts".to_owned(),
            JsonValue::Object(
                status_counts
                    .iter()
                    .map(|(status, count)| (status.clone(), JsonValue::Number(*count)))
                    .collect(),
            ),
        ),
        ("promotedClaimCells".to_owned(), JsonValue::Number(promoted)),
        (
            "normalizedClaimCells".to_owned(),
            JsonValue::Number(status_counts["normalized"]),
        ),
        (
            "platformDependentClaimCells".to_owned(),
            JsonValue::Number(status_counts["platform-dependent"]),
        ),
        (
            "divergentClaimCells".to_owned(),
            JsonValue::Number(status_counts["deliberate-divergence"]),
        ),
    ])
}

struct ResidualEvidenceInputs<'a> {
    root: &'a Path,
    cells: &'a [JsonValue],
    boundary_classes: Vec<JsonValue>,
    mutation_families: JsonValue,
    undetected_mutant_ids: Vec<JsonValue>,
    native: &'a ResidualNativeEvidence,
    capability_evidence: Vec<JsonValue>,
    evidence_age: JsonValue,
    known_issues: Vec<JsonValue>,
}

fn residual_evidence_fields(
    inputs: ResidualEvidenceInputs<'_>,
) -> Result<BTreeMap<String, JsonValue>, String> {
    let capability_breadth = inputs
        .capability_evidence
        .iter()
        .map(JsonValue::object)
        .map(|record| {
            record.and_then(|record| {
                json_member(record, "capability")
                    .and_then(JsonValue::string)
                    .map(|value| JsonValue::String(value.to_owned()))
            })
        })
        .collect::<Result<Vec<_>, _>>()?;
    Ok(BTreeMap::from([
        (
            "boundedEvidenceStatement".to_owned(),
            JsonValue::String(
                "finite retained corpus evidence is not universal proof of compatibility"
                    .to_owned(),
            ),
        ),
        (
            "obligationCoverage".to_owned(),
            JsonValue::Array(residual_obligation_coverage(inputs.cells)?),
        ),
        (
            "boundaryClasses".to_owned(),
            JsonValue::Array(inputs.boundary_classes),
        ),
        (
            "capabilityBreadth".to_owned(),
            JsonValue::Array(capability_breadth),
        ),
        (
            "observedCapabilityEvidence".to_owned(),
            JsonValue::Array(inputs.capability_evidence),
        ),
        (
            "platforms".to_owned(),
            JsonValue::Array(inputs.native.platforms.clone()),
        ),
        (
            "profiles".to_owned(),
            JsonValue::Array(inputs.native.profiles.clone()),
        ),
        (
            "nativeCorpusInputs".to_owned(),
            JsonValue::Array(inputs.native.corpus_inputs.clone()),
        ),
        (
            "environmentVariables".to_owned(),
            JsonValue::Array(inputs.native.environment_variables.clone()),
        ),
        (
            "mutationFamilyScoresPerMille".to_owned(),
            inputs.mutation_families,
        ),
        (
            "undetectedMutantIds".to_owned(),
            JsonValue::Array(inputs.undetected_mutant_ids),
        ),
        (
            "policyDerivation".to_owned(),
            residual_policy_derivation(inputs.root)?,
        ),
        (
            "custodyEvaluationStage".to_owned(),
            JsonValue::String("pre-custody-proposal-input".to_owned()),
        ),
        (
            "custodyStatus".to_owned(),
            residual_custody_status(inputs.root)?,
        ),
        ("evidenceAge".to_owned(), inputs.evidence_age),
        (
            "knownOpenIssues".to_owned(),
            JsonValue::Array(inputs.known_issues),
        ),
    ]))
}

fn residual_gate_fields(
    missing_boundaries: u64,
    out_of_scope: u64,
    overall: &str,
    undetected: u64,
    unacceptable: u64,
    unverified: u64,
) -> BTreeMap<String, JsonValue> {
    BTreeMap::from([
        (
            "missingBoundaryClasses".to_owned(),
            JsonValue::Number(missing_boundaries),
        ),
        (
            "outOfScopeClaimCells".to_owned(),
            JsonValue::Number(out_of_scope),
        ),
        (
            "overallTier".to_owned(),
            JsonValue::String(overall.to_owned()),
        ),
        (
            "undetectedCriticalMutants".to_owned(),
            JsonValue::Number(undetected),
        ),
        (
            "unacceptableClaimGroups".to_owned(),
            JsonValue::Number(unacceptable),
        ),
        (
            "unverifiedClaimCells".to_owned(),
            JsonValue::Number(unverified),
        ),
    ])
}

fn residual_status_counts(cells: &[JsonValue]) -> Result<BTreeMap<String, u64>, String> {
    let mut counts = [
        "deliberate-divergence",
        "exact",
        "normalized",
        "not-applicable",
        "platform-dependent",
        "unverified",
    ]
    .into_iter()
    .map(|status| (status.to_owned(), 0_u64))
    .collect::<BTreeMap<_, _>>();
    for cell in cells {
        let status = json_member(cell.object()?, "proposedStatus")?.string()?;
        let count = counts
            .get_mut(status)
            .ok_or_else(|| "residual-risk encountered an unknown claim status".to_owned())?;
        *count = count.saturating_add(1);
    }
    Ok(counts)
}

fn claim_coverage_status_counts(
    coverage: &BTreeMap<String, JsonValue>,
) -> Result<BTreeMap<String, u64>, String> {
    let mut counts = residual_status_counts(json_member(coverage, "cells")?.array()?)?;
    if coverage.get("coverageScope").is_some() {
        verify_scoped_collection_coverage_counts(coverage)?;
        counts.insert(
            "not-applicable".to_owned(),
            json_member(coverage, "outOfScopeClaimCells")?.number()?,
        );
    }
    Ok(counts)
}

fn residual_obligation_coverage(cells: &[JsonValue]) -> Result<Vec<JsonValue>, String> {
    let mut coverage = Vec::with_capacity(cells.len());
    for cell in cells {
        let cell = cell.object()?;
        let status = json_member(cell, "proposedStatus")?.string()?;
        let required = json_member(cell, "obligations")?.array()?;
        let mut observed = BTreeSet::new();
        if status != "unverified" && status != "not-applicable" {
            for reference in json_member(cell, "evidenceRefs")?.array()? {
                for obligation in json_member(reference.object()?, "obligations")?.array()? {
                    observed.insert(obligation.string()?.to_owned());
                }
            }
        }
        let required_values = required
            .iter()
            .map(JsonValue::string)
            .map(|value| value.map(str::to_owned))
            .collect::<Result<BTreeSet<_>, _>>()?;
        let missing = required_values.difference(&observed).count();
        coverage.push(JsonValue::Object(BTreeMap::from([
            ("builtin".to_owned(), json_member(cell, "builtin")?.clone()),
            (
                "dimension".to_owned(),
                json_member(cell, "dimension")?.clone(),
            ),
            (
                "platform".to_owned(),
                json_member(cell, "platform")?.clone(),
            ),
            ("profile".to_owned(), json_member(cell, "profile")?.clone()),
            (
                "required".to_owned(),
                JsonValue::Number(
                    u64::try_from(required_values.len())
                        .map_err(|_| "required obligation count exceeds u64")?,
                ),
            ),
            (
                "observed".to_owned(),
                JsonValue::Number(
                    u64::try_from(observed.intersection(&required_values).count())
                        .map_err(|_| "observed obligation count exceeds u64")?,
                ),
            ),
            (
                "missing".to_owned(),
                JsonValue::Number(
                    u64::try_from(missing).map_err(|_| "missing obligation count exceeds u64")?,
                ),
            ),
        ])));
    }
    Ok(coverage)
}

fn residual_missing_obligation_count(cells: &[JsonValue]) -> Result<u64, String> {
    residual_obligation_coverage(cells)?
        .iter()
        .map(JsonValue::object)
        .map(|record| record.and_then(|record| json_member(record, "missing")?.number()))
        .try_fold(0_u64, |total, missing| {
            total
                .checked_add(missing?)
                .ok_or_else(|| "residual missing-obligation count overflows".to_owned())
        })
}

fn residual_boundary_classes(cells: &[JsonValue]) -> Result<Vec<JsonValue>, String> {
    let cases = committed_differential_cases();
    let mut boundaries = BTreeSet::new();
    for cell in cells {
        let cell = cell.object()?;
        if matches!(
            json_member(cell, "proposedStatus")?.string()?,
            "unverified" | "not-applicable"
        ) {
            continue;
        }
        let builtin = json_member(cell, "builtin")?.string()?;
        let dimension = compatibility_dimension(json_member(cell, "dimension")?.string()?)?;
        for reference in json_member(cell, "evidenceRefs")?.array()? {
            let case_id = json_member(reference.object()?, "caseId")?.string()?;
            let case = cases
                .iter()
                .find(|case| case.id.as_ref() == case_id)
                .ok_or_else(|| "residual-risk evidence names an unknown case".to_owned())?;
            let descriptor = case
                .claim_evidence
                .as_ref()
                .ok_or_else(|| "residual-risk evidence case is not claim eligible".to_owned())?;
            for target in descriptor.semantic_targets.iter().filter(|target| {
                target.builtin.as_ref() == builtin && target.dimension == dimension
            }) {
                for boundary in &target.boundary_classes {
                    boundaries.insert(format!("{builtin}:{}", boundary.as_ref()));
                }
            }
        }
    }
    Ok(boundaries.into_iter().map(JsonValue::String).collect())
}

fn residual_missing_boundary_count(observed: &[JsonValue]) -> Result<u64, String> {
    let observed = observed
        .iter()
        .map(JsonValue::string)
        .collect::<Result<BTreeSet<_>, _>>()?;
    let required = hell_testkit::mandatory_runtime_boundaries()
        .into_iter()
        .map(|requirement| format!("{}:{}", requirement.builtin, requirement.class))
        .collect::<BTreeSet<_>>();
    u64::try_from(
        required
            .iter()
            .filter(|requirement| !observed.contains(requirement.as_str()))
            .count(),
    )
    .map_err(|_| "missing boundary count exceeds u64".to_owned())
}

struct ResidualNativeEvidence {
    corpus_inputs: Vec<JsonValue>,
    environment_variables: Vec<JsonValue>,
    platforms: Vec<JsonValue>,
    profiles: Vec<JsonValue>,
}

fn residual_native_corpus_inputs(
    coverage_directory: &Path,
    candidate: &str,
    assurance_epoch: &str,
) -> Result<ResidualNativeEvidence, String> {
    let evidence_root = coverage_directory
        .parent()
        .ok_or_else(|| "residual coverage directory has no evidence root".to_owned())?;
    let native_root = evidence_root.join("native");
    let mut corpus_inputs = Vec::new();
    let mut observed_environment_variables = BTreeSet::new();
    let mut profiles = BTreeSet::new();
    let mut platforms = Vec::new();
    for platform in REQUIRED_CLAIM_PLATFORMS {
        let directory = native_root.join(platform);
        let summary_digest = crate::suite::verify_retained_native_summary(&directory)?;
        let environment = hell_testkit::verify_retained_native_environment(&directory)
            .map_err(|error| format!("cannot verify retained {platform} environment: {error}"))?;
        let summary = parse_json(&read_text(&directory.join("summary.json"))?)?;
        let summary = summary.object()?;
        if json_member(summary, "assuranceEpochSha256")?.string()? != assurance_epoch {
            return Err("native corpus input has a stale assurance epoch".to_owned());
        }
        let expected_summary_platform = match *platform {
            "linux-amd64" => "linux-x86_64",
            "macos-arm64" => "macos-aarch64",
            "windows-amd64" => "windows-x86_64",
            _ => return Err("residual native platform is unsupported".to_owned()),
        };
        if json_member(summary, "platform")?.string()? != expected_summary_platform {
            return Err("native corpus input was collected on the wrong platform".to_owned());
        }
        let claim_index = parse_json(&read_text(
            &directory.join("evidence").join("claim-index.json"),
        )?)?;
        if json_member(claim_index.object()?, "candidateSourceCommit")?.string()? != candidate {
            return Err("native corpus input has a stale candidate".to_owned());
        }
        for profile in json_member(summary, "requiredProfiles")?.array()? {
            profiles.insert(profile.string()?.to_owned());
        }
        if json_member(summary, "runnerOs")?.string()? != environment.runner_os
            || json_member(summary, "runnerArch")?.string()? != environment.runner_arch
            || json_member(summary, "collectedAt")?.string()? != environment.collected_at
            || json_member(summary, "runnerImageIdentitySha256")?.string()?
                != environment.runner_image_identity_sha256.hex()
            || json_member(summary, "rustToolchainSha256")?.string()?
                != environment.rust_toolchain_sha256.hex()
            || json_member(summary, "buildEnvironmentSha256")?.string()?
                != environment.build_environment_sha256.hex()
        {
            return Err("native summary does not bind its exact execution environment".to_owned());
        }
        validate_utc_timestamp(&environment.collected_at)?;
        for variable in &environment.environment_variables {
            if variable.present {
                observed_environment_variables.insert(variable.name.to_owned());
            }
        }
        platforms.push(JsonValue::String((*platform).to_owned()));
        corpus_inputs.push(residual_native_corpus_record(
            evidence_root,
            &directory,
            platform,
            summary,
            summary_digest,
            &environment,
        )?);
    }
    Ok(ResidualNativeEvidence {
        corpus_inputs,
        environment_variables: observed_environment_variables
            .into_iter()
            .map(JsonValue::String)
            .collect(),
        platforms,
        profiles: profiles.into_iter().map(JsonValue::String).collect(),
    })
}

fn residual_native_corpus_record(
    evidence_root: &Path,
    directory: &Path,
    platform: &str,
    summary: &BTreeMap<String, JsonValue>,
    summary_digest: Digest,
    environment: &hell_testkit::RetainedNativeEnvironmentFacts,
) -> Result<JsonValue, String> {
    let environment_path = directory.join("native-environment.json");
    let mut fields = residual_native_environment_fields(environment);
    fields.extend(BTreeMap::from([
        (
            "committedInputCount".to_owned(),
            json_member(summary, "committedDifferentialObservations")?.clone(),
        ),
        (
            "corpusSeed".to_owned(),
            json_member(summary, "corpusSeed")?.clone(),
        ),
        (
            "corpusSha256".to_owned(),
            json_member(summary, "corpusSha256")?.clone(),
        ),
        (
            "generatedInputCount".to_owned(),
            json_member(summary, "generatedDifferentialObservations")?.clone(),
        ),
        (
            "generatedStressCorpusSha256".to_owned(),
            json_member(summary, "generatedStressCorpusSha256")?.clone(),
        ),
        (
            "nativeEnvironmentPath".to_owned(),
            JsonValue::String(retained_relative_path(evidence_root, &environment_path)?),
        ),
        (
            "nativeEnvironmentSha256".to_owned(),
            JsonValue::String(record_digest(&environment_path)?),
        ),
        (
            "platform".to_owned(),
            JsonValue::String(platform.to_owned()),
        ),
        (
            "reviewedCommittedCorpusSha256".to_owned(),
            json_member(summary, "reviewedCommittedCorpusSha256")?.clone(),
        ),
        (
            "summaryPath".to_owned(),
            JsonValue::String(retained_relative_path(
                evidence_root,
                &directory.join("summary.json"),
            )?),
        ),
        (
            "summarySha256".to_owned(),
            JsonValue::String(summary_digest.hex()),
        ),
    ]));
    Ok(JsonValue::Object(fields))
}

fn residual_native_environment_fields(
    environment: &hell_testkit::RetainedNativeEnvironmentFacts,
) -> BTreeMap<String, JsonValue> {
    let variables = environment
        .environment_variables
        .iter()
        .map(|variable| {
            JsonValue::Object(BTreeMap::from([
                (
                    "name".to_owned(),
                    JsonValue::String(variable.name.to_owned()),
                ),
                ("present".to_owned(), JsonValue::Bool(variable.present)),
                (
                    "valueSha256".to_owned(),
                    JsonValue::String(variable.value_sha256.hex()),
                ),
            ]))
        })
        .collect();
    BTreeMap::from([
        (
            "buildEnvironmentSha256".to_owned(),
            JsonValue::String(environment.build_environment_sha256.hex()),
        ),
        (
            "cargoIdentity".to_owned(),
            JsonValue::String(environment.cargo_identity.clone()),
        ),
        (
            "cargoVersionSha256".to_owned(),
            JsonValue::String(environment.cargo_version_sha256.hex()),
        ),
        (
            "collectedAt".to_owned(),
            JsonValue::String(environment.collected_at.clone()),
        ),
        (
            "environmentVariables".to_owned(),
            JsonValue::Array(variables),
        ),
        (
            "imageOs".to_owned(),
            JsonValue::String(environment.image_os.clone()),
        ),
        (
            "imageVersion".to_owned(),
            JsonValue::String(environment.image_version.clone()),
        ),
        (
            "runnerArch".to_owned(),
            JsonValue::String(environment.runner_arch.clone()),
        ),
        (
            "runnerKind".to_owned(),
            JsonValue::String(environment.runner_kind.clone()),
        ),
        (
            "runnerImageIdentitySha256".to_owned(),
            JsonValue::String(environment.runner_image_identity_sha256.hex()),
        ),
        (
            "runnerOs".to_owned(),
            JsonValue::String(environment.runner_os.clone()),
        ),
        (
            "rustToolchainSelectionSha256".to_owned(),
            JsonValue::String(environment.rust_toolchain_selection_sha256.hex()),
        ),
        (
            "rustToolchainSha256".to_owned(),
            JsonValue::String(environment.rust_toolchain_sha256.hex()),
        ),
        (
            "rustcExecutablePathSha256".to_owned(),
            JsonValue::String(environment.rustc_executable_path_sha256.hex()),
        ),
        (
            "rustcExecutableSha256".to_owned(),
            JsonValue::String(environment.rustc_executable_sha256.hex()),
        ),
        (
            "rustcIdentity".to_owned(),
            JsonValue::String(environment.rustc_identity.clone()),
        ),
        (
            "rustcVerboseSha256".to_owned(),
            JsonValue::String(environment.rustc_verbose_sha256.hex()),
        ),
    ])
}

fn residual_observed_capability_evidence(cells: &[JsonValue]) -> Result<Vec<JsonValue>, String> {
    let mut evidence = BTreeMap::<String, BTreeSet<String>>::new();
    for cell in cells {
        let cell = cell.object()?;
        if matches!(
            json_member(cell, "proposedStatus")?.string()?,
            "unverified" | "not-applicable"
        ) {
            continue;
        }
        let spec = hell_builtins::lookup(json_member(cell, "builtin")?.string()?)
            .ok_or_else(|| "residual capability cell names an unknown builtin".to_owned())?;
        for reference in json_member(cell, "evidenceRefs")?.array()? {
            let reference = reference.object()?;
            let observed = format!(
                "{}|{}|{}",
                json_member(cell, "platform")?.string()?,
                json_member(reference, "caseId")?.string()?,
                json_member(reference, "bundleSha256")?.string()?,
            );
            for capability in spec.assurance_metadata().capabilities {
                evidence
                    .entry(format!("{capability:?}").to_ascii_lowercase())
                    .or_default()
                    .insert(observed.clone());
            }
        }
    }
    evidence
        .into_iter()
        .map(|(capability, observations)| {
            Ok(JsonValue::Object(BTreeMap::from([
                ("capability".to_owned(), JsonValue::String(capability)),
                (
                    "observations".to_owned(),
                    JsonValue::Array(observations.into_iter().map(JsonValue::String).collect()),
                ),
            ])))
        })
        .collect()
}

fn residual_evidence_age(
    root: &Path,
    mutation_path: &Path,
    native: &ResidualNativeEvidence,
    observed_at: Option<&str>,
) -> Result<JsonValue, String> {
    let report = parse_json(&read_text(mutation_path)?)?;
    let issued_at = json_member(report.object()?, "issuedAt")?.string()?;
    let generated_observed_at;
    let observed_at = if let Some(observed_at) = observed_at {
        observed_at
    } else {
        generated_observed_at = crate::custody_ops::current_utc_timestamp()?;
        &generated_observed_at
    };
    let now = utc_timestamp_seconds(observed_at)?;
    let mutation_policy_path = root.join("compat").join("mutation-policy.toml");
    let mutation_policy = read_text(&mutation_policy_path)?;
    let mutation_maximum = assignment_u64(&mutation_policy, "maximum_report_age_days")?
        .checked_mul(86_400)
        .ok_or_else(|| "residual evidence maximum age overflows".to_owned())?;
    let surveillance_policy_path = root.join("compat").join("surveillance-policy.toml");
    let surveillance_policy = read_text(&surveillance_policy_path)?;
    let native_maximum = assignment_u64(
        &surveillance_policy,
        "runner_toolchain_drift_check_interval_days",
    )?
    .checked_mul(86_400)
    .ok_or_else(|| "residual native evidence maximum age overflows".to_owned())?;
    let mut sources = vec![residual_age_source(
        now,
        "mutation-report",
        "all",
        issued_at,
        mutation_maximum,
        "mutation-score.json",
        &record_digest(mutation_path)?,
    )?];
    for native_record in &native.corpus_inputs {
        let native_record = native_record.object()?;
        sources.push(residual_age_source(
            now,
            "native-shard",
            json_member(native_record, "platform")?.string()?,
            json_member(native_record, "collectedAt")?.string()?,
            native_maximum,
            json_member(native_record, "nativeEnvironmentPath")?.string()?,
            json_member(native_record, "nativeEnvironmentSha256")?.string()?,
        )?);
    }
    sources.sort_by_key(residual_age_source_sort_key);
    let source_records = sources
        .iter()
        .map(JsonValue::object)
        .collect::<Result<Vec<_>, _>>()?;
    let oldest_age = source_records
        .iter()
        .map(|source| json_member(source, "ageSeconds").and_then(JsonValue::number))
        .collect::<Result<Vec<_>, _>>()?
        .into_iter()
        .max()
        .ok_or_else(|| "residual evidence age has no sources".to_owned())?;
    let mut stale_sources = 0_usize;
    let mut warning_sources = 0_usize;
    for source in source_records {
        let age = json_member(source, "ageSeconds")?.number()?;
        let maximum = json_member(source, "maximumAgeSeconds")?.number()?;
        if age > maximum {
            stale_sources = stale_sources.saturating_add(1);
        } else if age > maximum / 2 {
            warning_sources = warning_sources.saturating_add(1);
        }
    }
    Ok(JsonValue::Object(BTreeMap::from([
        ("oldestAgeSeconds".to_owned(), JsonValue::Number(oldest_age)),
        (
            "mutationPolicySha256".to_owned(),
            JsonValue::String(record_digest(&mutation_policy_path)?),
        ),
        (
            "observedAt".to_owned(),
            JsonValue::String(observed_at.to_owned()),
        ),
        (
            "staleSourceCount".to_owned(),
            JsonValue::Number(
                u64::try_from(stale_sources)
                    .map_err(|_| "residual stale source count exceeds u64")?,
            ),
        ),
        (
            "surveillancePolicySha256".to_owned(),
            JsonValue::String(record_digest(&surveillance_policy_path)?),
        ),
        ("sources".to_owned(), JsonValue::Array(sources)),
        (
            "warningSourceCount".to_owned(),
            JsonValue::Number(
                u64::try_from(warning_sources)
                    .map_err(|_| "residual warning source count exceeds u64")?,
            ),
        ),
    ])))
}

fn residual_age_source(
    now: u64,
    kind: &str,
    platform: &str,
    collected_at: &str,
    maximum_age_seconds: u64,
    source_path: &str,
    source_sha256: &str,
) -> Result<JsonValue, String> {
    let collected = utc_timestamp_seconds(collected_at)?;
    if collected > now {
        return Err("residual evidence is future-dated".to_owned());
    }
    require_digest(source_sha256, "residual evidence age source")?;
    validate_provider_workflow_path(source_path)?;
    Ok(JsonValue::Object(BTreeMap::from([
        (
            "ageSeconds".to_owned(),
            JsonValue::Number(now.saturating_sub(collected)),
        ),
        (
            "collectedAt".to_owned(),
            JsonValue::String(collected_at.to_owned()),
        ),
        ("kind".to_owned(), JsonValue::String(kind.to_owned())),
        (
            "maximumAgeSeconds".to_owned(),
            JsonValue::Number(maximum_age_seconds),
        ),
        (
            "platform".to_owned(),
            JsonValue::String(platform.to_owned()),
        ),
        (
            "sourcePath".to_owned(),
            JsonValue::String(source_path.to_owned()),
        ),
        (
            "sourceSha256".to_owned(),
            JsonValue::String(source_sha256.to_owned()),
        ),
    ])))
}

fn residual_age_source_sort_key(source: &JsonValue) -> String {
    source.object().map_or_else(
        |_| String::new(),
        |source| {
            format!(
                "{}|{}",
                json_member(source, "kind")
                    .and_then(JsonValue::string)
                    .unwrap_or_default(),
                json_member(source, "platform")
                    .and_then(JsonValue::string)
                    .unwrap_or_default(),
            )
        },
    )
}

fn residual_custody_status(root: &Path) -> Result<JsonValue, String> {
    let policy_path = root.join("compat").join("custody-policy.toml");
    let policy = read_text(&policy_path)?;
    let minimum_copies = assignment_u64(&policy, "minimum_copies")?;
    if minimum_copies < 2
        || require_assignment(&policy, "require_independent_retrieval", "true").is_err()
        || require_assignment(&policy, "require_object_lock", "true").is_err()
        || require_assignment(&policy, "require_version_id", "true").is_err()
    {
        return Err("residual custody policy is not independently durable".to_owned());
    }
    Ok(JsonValue::Object(BTreeMap::from([
        (
            "currentStatus".to_owned(),
            JsonValue::String("pending-post-review-custody".to_owned()),
        ),
        (
            "evaluationStage".to_owned(),
            JsonValue::String("pre-custody-proposal-input".to_owned()),
        ),
        (
            "finalAssessmentSource".to_owned(),
            JsonValue::String("proposal-custody-record".to_owned()),
        ),
        (
            "minimumCopies".to_owned(),
            JsonValue::Number(minimum_copies),
        ),
        (
            "policySha256".to_owned(),
            JsonValue::String(record_digest(&policy_path)?),
        ),
    ])))
}

fn residual_known_open_issues(
    coverage_directory: &Path,
    cells: &[JsonValue],
    undetected_mutant_ids: &[JsonValue],
) -> Result<Vec<JsonValue>, String> {
    let evidence_root = coverage_directory
        .parent()
        .ok_or_else(|| "residual coverage directory has no evidence root".to_owned())?;
    let path = evidence_root
        .join("review")
        .join("divergence-report.details.json");
    let report = parse_json(&read_text(&path)?)?;
    let mut issues = json_member(report.object()?, "records")?
        .array()?
        .iter()
        .map(JsonValue::object)
        .map(|record| {
            let record = record?;
            Ok(JsonValue::Object(BTreeMap::from([
                (
                    "kind".to_owned(),
                    JsonValue::String("accepted-divergence".to_owned()),
                ),
                (
                    "reference".to_owned(),
                    json_member(record, "divergenceId")?.clone(),
                ),
                (
                    "trackingIssueNumber".to_owned(),
                    json_member(record, "issueNumber")?.clone(),
                ),
            ])))
        })
        .collect::<Result<Vec<_>, String>>()?;
    for (status, count) in residual_status_counts(cells)? {
        if count != 0 && status != "exact" {
            issues.push(JsonValue::Object(BTreeMap::from([
                (
                    "kind".to_owned(),
                    JsonValue::String("claim-status".to_owned()),
                ),
                (
                    "reference".to_owned(),
                    JsonValue::String(format!("{status}:{count}")),
                ),
                ("trackingIssueNumber".to_owned(), JsonValue::Null),
            ])));
        }
    }
    for mutant in undetected_mutant_ids {
        issues.push(JsonValue::Object(BTreeMap::from([
            (
                "kind".to_owned(),
                JsonValue::String("undetected-mutant".to_owned()),
            ),
            ("reference".to_owned(), mutant.clone()),
            ("trackingIssueNumber".to_owned(), JsonValue::Null),
        ])));
    }
    issues.sort_by_key(residual_issue_sort_key);
    Ok(issues)
}

fn residual_issue_sort_key(issue: &JsonValue) -> String {
    issue.object().map_or_else(
        |_| String::new(),
        |issue| {
            format!(
                "{}|{}",
                json_member(issue, "kind")
                    .and_then(JsonValue::string)
                    .unwrap_or_default(),
                json_member(issue, "reference")
                    .and_then(JsonValue::string)
                    .unwrap_or_default()
            )
        },
    )
}

fn residual_critical_non_exact_cells(cells: &[JsonValue]) -> Result<u64, String> {
    let mut count = 0_u64;
    for cell in cells {
        let cell = cell.object()?;
        let status = json_member(cell, "proposedStatus")?.string()?;
        if matches!(status, "exact" | "not-applicable") {
            continue;
        }
        let spec = hell_builtins::lookup(json_member(cell, "builtin")?.string()?)
            .ok_or_else(|| "residual criticality cell names an unknown builtin".to_owned())?;
        let metadata = spec.assurance_metadata();
        if !metadata.capabilities.is_empty()
            || metadata.host_failure_applicable
            || !metadata.resource_roles.is_empty()
            || metadata.sensitivities.iter().any(|sensitivity| {
                !matches!(
                    sensitivity,
                    hell_builtins::AssuranceSensitivity::Presentation
                )
            })
        {
            count = count.saturating_add(1);
        }
    }
    Ok(count)
}

fn residual_minimum_mutation_score(scores: &JsonValue) -> Result<u64, String> {
    scores
        .object()?
        .values()
        .map(JsonValue::number)
        .collect::<Result<Vec<_>, _>>()?
        .into_iter()
        .min()
        .ok_or_else(|| "residual mutation family scores are empty".to_owned())
}

fn residual_mutation_facts(path: &Path) -> Result<(JsonValue, Vec<JsonValue>), String> {
    if !path.is_file() {
        return Err("residual-risk mutation evidence is missing".to_owned());
    }
    let document = parse_json(&read_text(path)?)?;
    let report = document.object()?;
    let scores = json_member(report, "familyScoresPerMille")?.object()?;
    for score in scores.values() {
        if score.number()? > 1_000 {
            return Err("mutation family score exceeds one thousand per mille".to_owned());
        }
    }
    let mut undetected = Vec::new();
    for mutant in json_member(report, "mutants")?.array()? {
        let mutant = mutant.object()?;
        if !json_member(mutant, "detected")?.boolean()? {
            undetected.push(JsonValue::String(
                json_member(mutant, "id")?.string()?.to_owned(),
            ));
        }
    }
    undetected.sort_by_key(|value| value.string().unwrap_or_default().to_owned());
    Ok((JsonValue::Object(scores.clone()), undetected))
}

struct ResidualRiskFactors {
    missing_boundaries: u64,
    missing_obligations: u64,
    unacceptable: u64,
    undetected: u64,
    unverified: u64,
    out_of_scope: u64,
    normalized: u64,
    platform_dependent: u64,
    divergences: u64,
    critical_non_exact: u64,
    minimum_mutation_score: u64,
    stale_evidence_sources: u64,
    aging_evidence_sources: u64,
    observed_platforms: usize,
    custody_current: bool,
}

fn residual_overall_tier(
    factors: &ResidualRiskFactors,
    policy: &ResidualTierPolicy,
) -> &'static str {
    if factors.missing_boundaries != 0
        || factors.missing_obligations != 0
        || factors.unacceptable != 0
        || factors.undetected != 0
        || factors.unverified != 0
        || factors.stale_evidence_sources != 0
        || factors.observed_platforms != policy.required_platform_count
    {
        "unacceptable"
    } else if factors.critical_non_exact != 0
        || factors.platform_dependent != 0
        || factors.divergences != 0
    {
        "high"
    } else if factors.out_of_scope != 0
        || factors.normalized != 0
        || factors.minimum_mutation_score < policy.minimum_full_mutation_score_per_mille
        || factors.aging_evidence_sources != 0
        || !factors.custody_current
    {
        "moderate"
    } else {
        "low"
    }
}

fn residual_policy_derivation(root: &Path) -> Result<JsonValue, String> {
    let mut policies = BTreeMap::new();
    for (name, path) in [
        (
            "assurancePolicySha256",
            root.join("compat").join("assurance-policy.toml"),
        ),
        (
            "claimRulesSha256",
            root.join("compat").join("claim-rules.toml"),
        ),
        (
            "corpusObligationsSha256",
            root.join("compat").join("corpus-obligations.toml"),
        ),
        (
            "mutationPolicySha256",
            root.join("compat").join("mutation-policy.toml"),
        ),
    ] {
        policies.insert(name.to_owned(), JsonValue::String(record_digest(&path)?));
    }
    Ok(JsonValue::Object(policies))
}

fn review_assemble(root: &Path, options: &Options) -> Result<String, String> {
    if options.action.as_deref() != Some("prepare") || !options.github_dispatch_inputs {
        return Err("review-assemble requires prepare --github-dispatch-inputs".to_owned());
    }
    let inputs = github_dispatch_object(REVIEW_ASSEMBLY_INPUTS)?;
    if inputs.get("require_review").map(String::as_str) != Some("true") {
        return Err("review assembly requires the exact string true".to_owned());
    }
    let candidate = validate_review_assembly_identity(root, &inputs)?;
    verify_review_source_selections(root, &inputs, candidate)?;
    Ok("verified and retained six exact review source artifacts".to_owned())
}

fn validate_review_assembly_identity<'a>(
    root: &Path,
    inputs: &'a BTreeMap<String, String>,
) -> Result<&'a str, String> {
    let candidate = map_value(inputs, "candidate_sha")?;
    require_git_sha_text(candidate, "review assembly candidate")?;
    if git_output(root, &["rev-parse", "HEAD"])?.trim() != candidate {
        return Err("review assembly checkout differs from candidate input".to_owned());
    }
    validate_utc_timestamp(map_value(inputs, "issued_at")?)?;
    let mutation_event = map_value(inputs, "mutation_event")?;
    if !matches!(mutation_event, "workflow_dispatch" | "schedule") {
        return Err("review assembly mutation event is not accepted".to_owned());
    }
    Ok(candidate)
}

