type ReviewProviderSpec<'a> = (
    &'a str,
    PathBuf,
    &'a str,
    PathBuf,
    &'a str,
    &'a str,
    &'a str,
    &'a str,
    &'a str,
    &'a str,
);

fn verify_review_provider_specs(
    root: &Path,
    inputs: &BTreeMap<String, String>,
    archives: &BTreeMap<String, String>,
    candidate: &str,
    selections: Vec<ReviewProviderSpec<'_>>,
) -> Result<(), String> {
    for (label, directory, artifact, workflow, event, run, attempt, id, digest, archive) in
        selections
    {
        let package = map_value(inputs, digest)?;
        let archive = map_value(archives, archive)?;
        require_digest(package, "review source package")?;
        require_digest(archive, "review source provider archive")?;
        let workflow = path_text(&workflow)?;
        let selection = verify_provider_artifact_selection(
            root,
            &directory,
            artifact,
            &workflow,
            event,
            positive_map_integer(inputs, run, "review assembly")?,
            positive_map_integer(inputs, attempt, "review assembly")?,
            positive_map_integer(inputs, id, "review assembly")?,
            candidate,
            package,
            archive,
        )?;
        write_atomic(
            &directory.join(format!("{label}-provider-selection.json")),
            selection.as_bytes(),
        )?;
    }
    Ok(())
}

fn review_provider_archive_digests(
    inputs: &BTreeMap<String, String>,
) -> Result<BTreeMap<String, String>, String> {
    let document = parse_json(map_value(inputs, "provider_archive_sha256_json")?)?;
    let fields = document.object()?;
    exact_keys(
        fields,
        &[
            "acquisition",
            "mutation",
            "native",
            "oracleMacos",
            "oracleWindows",
        ],
    )?;
    fields
        .iter()
        .map(|(key, value)| {
            let digest = value.string()?.to_owned();
            require_digest(&digest, "review source provider archive")?;
            Ok((key.clone(), digest))
        })
        .collect()
}

struct ClaimDecisionSelector {
    run_id: u64,
    run_attempt: u64,
    artifact_id: u64,
    package_sha256: String,
    archive_sha256: String,
    producer_commit: String,
}

fn claim_decision_selector(
    inputs: &BTreeMap<String, String>,
) -> Result<ClaimDecisionSelector, String> {
    let selector = parse_json(map_value(inputs, "claim_decision_selector_json")?)?;
    let selector = selector.object()?;
    exact_keys(
        selector,
        &[
            "archiveSha256",
            "artifactId",
            "packageSha256",
            "producerCommit",
            "runAttempt",
            "runId",
            "schemaVersion",
        ],
    )?;
    if json_member(selector, "schemaVersion")?.number()? != 1 {
        return Err("claim decision selector schema is unsupported".to_owned());
    }
    let package_sha256 = json_member(selector, "packageSha256")?.string()?.to_owned();
    let archive_sha256 = json_member(selector, "archiveSha256")?.string()?.to_owned();
    let producer_commit = json_member(selector, "producerCommit")?
        .string()?
        .to_owned();
    require_digest(&package_sha256, "claim decision package")?;
    require_digest(&archive_sha256, "claim decision provider archive")?;
    require_git_sha_text(&producer_commit, "claim decision producer commit")?;
    Ok(ClaimDecisionSelector {
        run_id: positive_json_integer(selector, "runId", "claim decision selector")?,
        run_attempt: positive_json_integer(selector, "runAttempt", "claim decision selector")?,
        artifact_id: positive_json_integer(selector, "artifactId", "claim decision selector")?,
        package_sha256,
        archive_sha256,
        producer_commit,
    })
}

fn positive_json_integer(
    document: &BTreeMap<String, JsonValue>,
    key: &str,
    label: &str,
) -> Result<u64, String> {
    let value = json_member(document, key)?.number()?;
    if value == 0 {
        return Err(format!("{label} {key} must be nonzero"));
    }
    Ok(value)
}

fn verify_claim_decision_selection(
    root: &Path,
    inputs: &BTreeMap<String, String>,
) -> Result<(), String> {
    let selector = claim_decision_selector(inputs)?;
    let directory = Path::new("ci-out").join("evidence").join("claim-decisions");
    let selection = verify_provider_artifact_selection(
        root,
        &directory,
        "promotion-claim-applicability-decisions",
        ".github/workflows/claim-applicability-decisions.yml",
        "workflow_dispatch",
        selector.run_id,
        selector.run_attempt,
        selector.artifact_id,
        &selector.producer_commit,
        &selector.package_sha256,
        &selector.archive_sha256,
    )?;
    let selection_document = parse_json(&selection)?;
    if json_member(selection_document.object()?, "providerArchiveSha256")?.string()?
        != selector.archive_sha256
    {
        return Err("claim decision provider archive differs from selector".to_owned());
    }
    write_atomic(
        &directory.join("claim-decisions-provider-selection.json"),
        selection.as_bytes(),
    )?;
    Ok(())
}

fn positive_map_integer(
    values: &BTreeMap<String, String>,
    key: &str,
    label: &str,
) -> Result<u64, String> {
    let value = map_value(values, key)?
        .parse::<u64>()
        .map_err(|_| format!("{label} {key} is not an integer"))?;
    if value == 0 {
        return Err(format!("{label} {key} must be nonzero"));
    }
    Ok(value)
}

fn map_value<'a>(values: &'a BTreeMap<String, String>, key: &str) -> Result<&'a str, String> {
    values
        .get(key)
        .map(String::as_str)
        .ok_or_else(|| format!("missing structured input {key}"))
}

fn review_bind(root: &Path, options: &Options) -> Result<String, String> {
    let details_path = required_path(&options.input, "review-bind requires --input details")?;
    let review_path = required_path(&options.from, "review-bind requires --from review envelope")?;
    let output = required_path(&options.output, "review-bind requires --output")?;
    let policy = required_path(
        &options.policy,
        "review-bind requires --policy allowed-signers",
    )?;
    let kind = options
        .category
        .as_deref()
        .ok_or_else(|| "review-bind requires --category report kind".to_owned())?;
    let role = bound_report_role(kind)?;
    let details = parse_json(&read_text(details_path)?)?;
    let details = details.object()?;
    let candidate = json_member(details, "candidateSourceCommit")?.string()?;
    let assurance_epoch = json_member(details, "assuranceEpochSha256")?.string()?;
    if candidate != git_output(root, &["rev-parse", "HEAD"])?.trim()
        || assurance_epoch != epoch(root)?.1.hex()
    {
        return Err("review-bind details candidate or epoch is stale".to_owned());
    }
    verify_bound_details(details_path, kind, candidate, assurance_epoch)?;
    let details_digest = record_digest(details_path)?;
    let review_digest = record_digest(review_path)?;
    let authorization_path = policy
        .parent()
        .ok_or_else(|| "review signer policy has no authorization directory".to_owned())?
        .join("authorization.json");
    verify_review_authorization(&authorization_path, role, candidate, details_path)?;
    let review = verify_review_envelope(review_path, policy)?;
    if review.role != role
        || review.candidate_commit != candidate
        || review.assurance_epoch != assurance_epoch
        || !review.reviewed_artifacts.contains(&details_digest)
    {
        return Err("review-bind envelope does not authorize the exact details".to_owned());
    }
    let retained_root = retained_evidence_root(output)?;
    let details_relative = details_path
        .strip_prefix(retained_root)
        .map_err(|_| "review-bind details are outside the retained evidence root".to_owned())?;
    let review_relative = review_path
        .strip_prefix(retained_root)
        .map_err(|_| "review-bind envelope is outside the retained evidence root".to_owned())?;
    let authorization_relative = authorization_path
        .strip_prefix(retained_root)
        .map_err(|_| {
            "review-bind authorization is outside the retained evidence root".to_owned()
        })?;
    let policy_relative = policy.strip_prefix(retained_root).map_err(|_| {
        "review-bind signer policy is outside the retained evidence root".to_owned()
    })?;
    let blocker_count = bound_report_blockers(kind, details)?;
    let json = format!(
        "{{\n  \"schemaVersion\": 1,\n  \"kind\": {},\n  \"candidateSourceCommit\": {},\n  \"assuranceEpochSha256\": {},\n  \"detailsPath\": {},\n  \"detailsSha256\": {},\n  \"reviewPath\": {},\n  \"reviewSha256\": {},\n  \"authorizationPath\": {},\n  \"authorizationSha256\": {},\n  \"signerPolicyPath\": {},\n  \"signerPolicySha256\": {},\n  \"blockerCount\": {blocker_count}\n}}\n",
        json_string(kind),
        json_string(candidate),
        json_string(assurance_epoch),
        json_string(&path_text(details_relative)?),
        json_string(&details_digest),
        json_string(&path_text(review_relative)?),
        json_string(&review_digest),
        json_string(&path_text(authorization_relative)?),
        json_string(&record_digest(&authorization_path)?),
        json_string(&path_text(policy_relative)?),
        json_string(&record_digest(policy)?),
    );
    write_atomic(output, json.as_bytes())?;
    Ok(format!("bound exact {kind} details to dual-signed review"))
}

fn bound_report_role(kind: &str) -> Result<&'static str, String> {
    match kind {
        "claim-coverage" => Ok("claim-reviewer"),
        "normalizer-audit" => Ok("normalizer-reviewer"),
        "divergence" => Ok("divergence-reviewer"),
        "residual-risk" => Ok("residual-risk-reviewer"),
        "review-role-graph" => Ok("review-graph-reviewer"),
        _ => Err(format!("unknown bound report kind {kind:?}")),
    }
}

fn bound_report_blockers(kind: &str, details: &BTreeMap<String, JsonValue>) -> Result<u64, String> {
    let fields: &[&str] = match kind {
        "claim-coverage" => &[
            "ambiguousClaimScopes",
            "missingObligations",
            "requiredPlatformGaps",
            "semanticCoverageGaps",
            "unreachedTargets",
        ],
        "normalizer-audit" => &[
            "exactClaimsUsingNormalizers",
            "failedMutants",
            "protectedFieldChanges",
            "unsafeNormalizers",
        ],
        "divergence" => &[
            "expiredDivergences",
            "fingerprintMismatches",
            "missingImpactApprovals",
            "wildcardScopes",
        ],
        "residual-risk" => &[
            "missingBoundaryClasses",
            "undetectedCriticalMutants",
            "unacceptableClaimGroups",
        ],
        "review-role-graph" => {
            return Ok(json_member(details, "policyViolations")?.array()?.len() as u64);
        }
        _ => return Err(format!("unknown bound report kind {kind:?}")),
    };
    fields.iter().try_fold(0_u64, |sum, field| {
        Ok(sum.saturating_add(json_member(details, field)?.number()?))
    })
}

fn retained_report_command(root: &Path, options: &Options, name: &str) -> Result<String, String> {
    if options.action.as_deref() == Some("run") {
        return mutation_run(root, options, false);
    }
    if options.action.as_deref() == Some("run-surveillance") {
        return mutation_run(root, options, true);
    }
    if options.action.as_deref() == Some("finalize") {
        return mutation_finalize(root, options);
    }
    let input = required_path(&options.input, &format!("{name} verify requires --input"))?;
    let document = parse_json(&read_text(input)?)?;
    let report = document.object()?;
    exact_keys(
        report,
        &[
            "authorizationPath",
            "authorizationSha256",
            "assuranceEpochSha256",
            "assuranceMutantsDetected",
            "assuranceMutantsRequired",
            "candidateSourceCommit",
            "catalogSha256",
            "criticalMutantsDetected",
            "criticalMutantsRequired",
            "familyScoresPerMille",
            "issuedAt",
            "mutants",
            "policySha256",
            "reportCoreSha256",
            "reviewPath",
            "reviewSha256",
            "schemaVersion",
            "signerPolicyPath",
            "signerPolicySha256",
            "undetectedCriticalMutants",
        ],
    )?;
    if json_member(report, "schemaVersion")?.number()? != 1 {
        return Err(format!("{name} report schemaVersion must be 1"));
    }
    let candidate = json_member(report, "candidateSourceCommit")?.string()?;
    require_git_sha_text(candidate, "mutation candidate")?;
    let epoch = json_member(report, "assuranceEpochSha256")?.string()?;
    require_digest(epoch, "mutation epoch")?;
    if options
        .expect_source
        .as_deref()
        .is_some_and(|value| value != candidate)
        || options
            .expect_epoch
            .as_deref()
            .is_some_and(|value| value != epoch)
    {
        return Err("mutation report candidate or epoch mismatch".to_owned());
    }
    let core_digest = verify_mutation_records(root, input, report)?;
    verify_mutation_review(root, input, options, report, candidate, epoch, &core_digest)?;
    Ok(format!("verified typed, epoch-bound {name} report"))
}

fn mutation_run(
    root: &Path,
    options: &Options,
    surveillance_subject: bool,
) -> Result<String, String> {
    let output = required_path(&options.output, "mutation run requires --output")?;
    if !options.github_dispatch_inputs {
        return Err("mutation run requires structured GitHub dispatch inputs".to_owned());
    }
    let issued_at = mutation_evidence_issued_at(root, surveillance_subject)?;
    let catalog_path = root.join("compat").join("mutants.toml");
    let catalog = read_text(&catalog_path)?;
    require_assignment(&catalog, "schema_version", "2")?;
    require_assignment(&catalog, "state", "\"required\"")?;
    require_assignment(
        &catalog,
        "execution_strategy",
        "\"baseline-pass-mutant-fail\"",
    )?;
    let ids = assignment_string_array(&catalog, "ids")?;
    let families = assignment_string_array(&catalog, "families")?;
    let tests = assignment_string_array(&catalog, "tests")?;
    let packages = assignment_string_array(&catalog, "packages")?;
    let targets = assignment_string_array(&catalog, "targets")?;
    let mutation_sites = assignment_string_array(&catalog, "mutation_sites")?;
    let obligation_ids = assignment_string_array(&catalog, "obligation_ids")?;
    let claim_group_ids = assignment_string_array(&catalog, "claim_group_ids")?;
    let classes = assignment_string_array(&catalog, "classes")?;
    let criticalities = assignment_string_array(&catalog, "criticalities")?;
    if ids.len() != families.len()
        || ids.len() != tests.len()
        || ids.len() != packages.len()
        || ids.len() != targets.len()
        || ids.len() != mutation_sites.len()
        || ids.len() != obligation_ids.len()
        || ids.len() != claim_group_ids.len()
        || ids.len() != classes.len()
        || ids.len() != criticalities.len()
        || ids.iter().collect::<BTreeSet<_>>().len() != ids.len()
        || tests.iter().collect::<BTreeSet<_>>().len() != tests.len()
    {
        return Err("mutation catalog columns disagree".to_owned());
    }
    let results = output
        .parent()
        .ok_or_else(|| "mutation output has no directory".to_owned())?
        .join("mutation-results");
    fs::create_dir_all(&results)
        .map_err(|error| format!("cannot create mutation results: {error}"))?;
    let mut records = Vec::new();
    for index in 0..ids.len() {
        records.push(run_assurance_mutant(
            &results,
            index,
            MutationSpec {
                id: &ids[index],
                family: &families[index],
                package: &packages[index],
                target: &targets[index],
                test: &tests[index],
                mutation_site: &mutation_sites[index],
                obligation_id: &obligation_ids[index],
                claim_group_id: &claim_group_ids[index],
                class: &classes[index],
                criticality: &criticalities[index],
            },
        )?);
    }
    let candidate = git_output(root, &["rev-parse", "HEAD"])?;
    let (_, epoch) = epoch(root)?;
    let policy_path = root.join("compat").join("mutation-policy.toml");
    let report = mutation_report_json(
        candidate.trim(),
        &epoch.hex(),
        &issued_at,
        &record_digest(&catalog_path)?,
        &record_digest(&policy_path)?,
        &records,
    )?;
    write_atomic(output, report.as_bytes())?;
    Ok(format!("executed {} assurance mutants", records.len()))
}

#[derive(Clone, Copy)]
struct MutationSpec<'a> {
    id: &'a str,
    family: &'a str,
    package: &'a str,
    target: &'a str,
    test: &'a str,
    mutation_site: &'a str,
    obligation_id: &'a str,
    claim_group_id: &'a str,
    class: &'a str,
    criticality: &'a str,
}

fn run_assurance_mutant(
    results: &Path,
    index: usize,
    spec: MutationSpec<'_>,
) -> Result<JsonValue, String> {
    let arguments = mutation_cargo_arguments(spec.package, spec.target, spec.test)?;
    let strategy = "baseline-pass-mutant-fail";
    let baseline = Command::new("cargo")
        .args(&arguments)
        .env_remove("HELL_ASSURANCE_MUTANT_ID")
        .output()
        .map_err(|error| format!("cannot execute assurance baseline {}: {error}", spec.id))?;
    let mutant = Command::new("cargo")
        .args(&arguments)
        .env("HELL_ASSURANCE_MUTANT_ID", spec.id)
        .output()
        .map_err(|error| format!("cannot execute assurance mutant {}: {error}", spec.id))?;
    let baseline_stdout_path = results.join(format!("mutant-{index}.baseline.stdout"));
    let baseline_stderr_path = results.join(format!("mutant-{index}.baseline.stderr"));
    let mutant_stdout_path = results.join(format!("mutant-{index}.activated.stdout"));
    let mutant_stderr_path = results.join(format!("mutant-{index}.activated.stderr"));
    write_atomic(&baseline_stdout_path, &baseline.stdout)?;
    write_atomic(&baseline_stderr_path, &baseline.stderr)?;
    write_atomic(&mutant_stdout_path, &mutant.stdout)?;
    write_atomic(&mutant_stderr_path, &mutant.stderr)?;
    let baseline_passed = exact_test_harness_success(&baseline.stdout, spec.test)?;
    let mutant_failed = exact_test_harness_failure(&mutant.stdout, spec.test)?;
    let mutation_identity = mutation_identity_sha256(&spec, &arguments);
    let result = format!(
        "{{\"schemaVersion\":4,\"mutationIdentitySha256\":{},\"baselineActivationEnvironment\":null,\"baselineStatus\":{},\"baselineStdoutPath\":{},\"baselineStdoutSha256\":{},\"baselineStderrPath\":{},\"baselineStderrSha256\":{},\"baselineExactTestPassed\":{baseline_passed},\"mutantActivationEnvironment\":{},\"mutantStatus\":{},\"mutantStdoutPath\":{},\"mutantStdoutSha256\":{},\"mutantStderrPath\":{},\"mutantStderrSha256\":{},\"mutantExactTestFailed\":{mutant_failed}}}\n",
        json_string(&mutation_identity),
        baseline.status.code().unwrap_or(255),
        retained_mutation_path(&baseline_stdout_path)?,
        json_string(&sha256_bytes(&baseline.stdout).hex()),
        retained_mutation_path(&baseline_stderr_path)?,
        json_string(&sha256_bytes(&baseline.stderr).hex()),
        json_string(spec.id),
        mutant.status.code().unwrap_or(255),
        retained_mutation_path(&mutant_stdout_path)?,
        json_string(&sha256_bytes(&mutant.stdout).hex()),
        retained_mutation_path(&mutant_stderr_path)?,
        json_string(&sha256_bytes(&mutant.stderr).hex()),
    );
    let result_path = results.join(format!("mutant-{index}.json"));
    write_atomic(&result_path, result.as_bytes())?;
    parse_json(&format!(
        "{{\"id\":{},\"family\":{},\"class\":{},\"criticality\":{},\"test\":{},\"program\":\"cargo\",\"strategy\":{},\"activationEnvironment\":\"HELL_ASSURANCE_MUTANT_ID\",\"activationValue\":{},\"mutationSite\":{},\"detectionObligationIds\":[{}],\"detectionClaimGroupIds\":[{}],\"arguments\":[{}],\"commandSha256\":{},\"mutationIdentitySha256\":{},\"resultPath\":{},\"resultSha256\":{},\"detected\":{}}}",
        json_string(spec.id),
        json_string(spec.family),
        json_string(spec.class),
        json_string(spec.criticality),
        json_string(spec.test),
        json_string(strategy),
        json_string(spec.id),
        json_string(spec.mutation_site),
        json_string(spec.obligation_id),
        json_string(spec.claim_group_id),
        arguments
            .iter()
            .map(|argument| json_string(argument))
            .collect::<Vec<_>>()
            .join(","),
        json_string(&mutation_command_sha256(&arguments)),
        json_string(&mutation_identity),
        json_string(&path_text(
            &PathBuf::from("mutation-results").join(
                result_path
                    .file_name()
                    .ok_or_else(|| "mutation result path has no name".to_owned())?,
            )
        )?),
        json_string(&sha256_bytes(result.as_bytes()).hex()),
        baseline.status.success() && baseline_passed && !mutant.status.success() && mutant_failed,
    ))
}

fn retained_mutation_path(path: &Path) -> Result<String, String> {
    Ok(json_string(&path_text(
        &PathBuf::from("mutation-results").join(
            path.file_name()
                .ok_or_else(|| "mutation stream path has no name".to_owned())?,
        ),
    )?))
}

fn mutation_identity_sha256(spec: &MutationSpec<'_>, arguments: &[String]) -> String {
    let document = format!(
        "{{\"schemaVersion\":1,\"id\":{},\"site\":{},\"activationEnvironment\":\"HELL_ASSURANCE_MUTANT_ID\",\"activationValue\":{},\"obligationId\":{},\"claimGroupId\":{},\"class\":{},\"criticality\":{},\"commandSha256\":{}}}\n",
        json_string(spec.id),
        json_string(spec.mutation_site),
        json_string(spec.id),
        json_string(spec.obligation_id),
        json_string(spec.claim_group_id),
        json_string(spec.class),
        json_string(spec.criticality),
        json_string(&mutation_command_sha256(arguments)),
    );
    sha256_bytes(document.as_bytes()).hex()
}

fn mutation_command_sha256<T: AsRef<str>>(arguments: &[T]) -> String {
    let arguments = arguments
        .iter()
        .map(|argument| json_string(argument.as_ref()))
        .collect::<Vec<_>>()
        .join(",");
    sha256_bytes(format!("{{\"program\":\"cargo\",\"arguments\":[{arguments}]}}\n").as_bytes())
        .hex()
}

fn mutation_cargo_arguments(
    package: &str,
    target: &str,
    test: &str,
) -> Result<Vec<String>, String> {
    let mut arguments = vec![
        "test".to_owned(),
        "--locked".to_owned(),
        "-p".to_owned(),
        package.to_owned(),
        "--features".to_owned(),
        "mutation-testing".to_owned(),
    ];
    if target == "lib" {
        arguments.push("--lib".to_owned());
    } else if let Some(bin) = target.strip_prefix("bin:") {
        arguments.extend(["--bin".to_owned(), bin.to_owned()]);
    } else if let Some(integration_test) = target.strip_prefix("test:") {
        arguments.extend(["--test".to_owned(), integration_test.to_owned()]);
    } else {
        return Err(format!("mutation catalog target is invalid: {target}"));
    }
    arguments.extend([test.to_owned(), "--".to_owned(), "--exact".to_owned()]);
    Ok(arguments)
}

fn exact_test_harness_success(stdout: &[u8], expected_test: &str) -> Result<bool, String> {
    let text = std::str::from_utf8(stdout)
        .map_err(|_| "mutation test harness output is not UTF-8".to_owned())?;
    let expected_result = format!("test {expected_test} ... ok");
    let matching_tests = text.lines().filter(|line| *line == expected_result).count();
    let summaries = text
        .lines()
        .filter(|line| line.starts_with("test result: "))
        .collect::<Vec<_>>();
    Ok(matching_tests == 1
        && summaries.len() == 1
        && summaries[0].starts_with("test result: ok. 1 passed; 0 failed; 0 ignored; 0 measured;"))
}

fn exact_test_harness_failure(stdout: &[u8], expected_test: &str) -> Result<bool, String> {
    let text = std::str::from_utf8(stdout)
        .map_err(|_| "mutation test harness output is not UTF-8".to_owned())?;
    let expected_result = format!("test {expected_test} ... FAILED");
    let matching_tests = text.lines().filter(|line| *line == expected_result).count();
    let summaries = text
        .lines()
        .filter(|line| line.starts_with("test result: "))
        .collect::<Vec<_>>();
    Ok(matching_tests == 1
        && summaries.len() == 1
        && summaries[0]
            .starts_with("test result: FAILED. 0 passed; 1 failed; 0 ignored; 0 measured;"))
}

fn mutation_report_json(
    candidate: &str,
    epoch: &str,
    issued_at: &str,
    catalog: &str,
    policy: &str,
    mutants: &[JsonValue],
) -> Result<String, String> {
    let mut families = BTreeMap::<String, (u64, u64)>::new();
    let mut controls = (0_u64, 0_u64);
    let mut critical = (0_u64, 0_u64);
    for mutant in mutants {
        let mutant = mutant.object()?;
        let is_detected = json_member(mutant, "detected")?.boolean()?;
        if json_member(mutant, "class")?.string()? == "control" {
            controls.0 = controls.0.saturating_add(1);
            controls.1 = controls.1.saturating_add(u64::from(is_detected));
        } else {
            let family = json_member(mutant, "family")?.string()?.to_owned();
            let counts = families.entry(family).or_default();
            counts.0 = counts.0.saturating_add(1);
            counts.1 = counts.1.saturating_add(u64::from(is_detected));
        }
        if json_member(mutant, "criticality")?.string()? == "critical" {
            critical.0 = critical.0.saturating_add(1);
            critical.1 = critical.1.saturating_add(u64::from(is_detected));
        }
    }
    let mut family_scores = String::from("{");
    for (index, (family, (family_required, family_detected))) in families.iter().enumerate() {
        if index != 0 {
            family_scores.push(',');
        }
        push_json(&mut family_scores, family);
        let score = family_detected.saturating_mul(1_000) / family_required;
        write!(family_scores, ":{score}").expect("writing to String cannot fail");
    }
    family_scores.push('}');
    let mut mutant_json = String::new();
    for (index, mutant) in mutants.iter().enumerate() {
        if index != 0 {
            mutant_json.push(',');
        }
        push_json_value(&mut mutant_json, mutant)?;
    }
    let preliminary = format!(
        "{{\"schemaVersion\":1,\"candidateSourceCommit\":{},\"assuranceEpochSha256\":{},\"catalogSha256\":{},\"policySha256\":{},\"issuedAt\":{},\"assuranceMutantsRequired\":{},\"assuranceMutantsDetected\":{},\"criticalMutantsRequired\":{},\"criticalMutantsDetected\":{},\"undetectedCriticalMutants\":{},\"familyScoresPerMille\":{family_scores},\"mutants\":[{mutant_json}],\"reviewPath\":\"REVIEW_REQUIRED\",\"reviewSha256\":\"REVIEW_REQUIRED\",\"reportCoreSha256\":\"REVIEW_REQUIRED\"}}\n",
        json_string(candidate),
        json_string(epoch),
        json_string(catalog),
        json_string(policy),
        json_string(issued_at),
        controls.0,
        controls.1,
        critical.0,
        critical.1,
        critical.0.saturating_sub(critical.1),
    );
    let parsed = parse_json(&preliminary)?;
    let core = mutation_report_core_digest(parsed.object()?)?;
    Ok(preliminary.replace(
        "\"reportCoreSha256\":\"REVIEW_REQUIRED\"",
        &format!("\"reportCoreSha256\":{}", json_string(&core)),
    ))
}

fn mutation_finalize(root: &Path, options: &Options) -> Result<String, String> {
    let input = required_path(&options.input, "mutation finalize requires --input")?;
    let review = required_path(&options.from, "mutation finalize requires --from review")?;
    let output = required_path(&options.output, "mutation finalize requires --output")?;
    let document = parse_json(&read_text(input)?)?;
    let mut report = document.object()?.clone();
    let core = mutation_report_core_digest(&report)?;
    if json_member(&report, "reportCoreSha256")?.string()? != core {
        return Err("mutation pending report core digest mismatch".to_owned());
    }
    report.insert(
        "reviewPath".to_owned(),
        JsonValue::String(path_text(
            review
                .strip_prefix(
                    output
                        .parent()
                        .ok_or_else(|| "mutation output has no retained directory".to_owned())?,
                )
                .map_err(|_| {
                    "mutation review is outside the retained report directory".to_owned()
                })?,
        )?),
    );
    report.insert(
        "reviewSha256".to_owned(),
        JsonValue::String(record_digest(review)?),
    );
    let mut finalized = String::new();
    push_json_value(&mut finalized, &JsonValue::Object(report))?;
    finalized.push('\n');
    write_atomic(output, finalized.as_bytes())?;
    retained_report_command(
        root,
        &Options {
            input: Some(output.to_path_buf()),
            policy: options.policy.clone(),
            ..Options::default()
        },
        "mutation",
    )
}

fn mutation_evidence_issued_at(root: &Path, surveillance_subject: bool) -> Result<String, String> {
    let surveillance_subject = surveillance_subject
        && trusted_surveillance_subject_identity(
            std::env::var("GITHUB_EVENT_NAME")
                .as_deref()
                .unwrap_or_default(),
            std::env::var("GITHUB_REF").as_deref().unwrap_or_default(),
            std::env::var("GITHUB_WORKFLOW_REF")
                .as_deref()
                .unwrap_or_default(),
        );
    if std::env::var("GITHUB_EVENT_NAME").as_deref() == Ok("schedule") || surveillance_subject {
        let issued_at = crate::custody_ops::current_utc_timestamp()?;
        validate_utc_timestamp(&issued_at)?;
        return Ok(issued_at);
    }
    let event_path = std::env::var_os("GITHUB_EVENT_PATH")
        .ok_or_else(|| "mutation review requires GITHUB_EVENT_PATH".to_owned())?;
    let event = parse_json(&read_text(Path::new(&event_path))?)?;
    let inputs = json_member(event.object()?, "inputs")?.object()?;
    exact_keys(inputs, &["candidate_sha", "issued_at", "require_review"])?;
    if json_member(inputs, "require_review")?.string()? != "true"
        || json_member(inputs, "candidate_sha")?.string()?
            != git_output(root, &["rev-parse", "HEAD"])?.trim()
    {
        return Err("mutation dispatch does not bind the exact candidate".to_owned());
    }
    let issued_at = json_member(inputs, "issued_at")?.string()?.to_owned();
    validate_utc_timestamp(&issued_at)?;
    Ok(issued_at)
}

pub(crate) fn trusted_surveillance_subject_identity(
    event: &str,
    git_ref: &str,
    workflow_ref: &str,
) -> bool {
    matches!(event, "push" | "schedule" | "workflow_dispatch")
        && git_ref == "refs/heads/main"
        && workflow_ref
            == "Portfoligno/hell-rs/.github/workflows/promotion-surveillance.yml@refs/heads/main"
}

fn verify_mutation_records(
    root: &Path,
    input: &Path,
    report: &BTreeMap<String, JsonValue>,
) -> Result<String, String> {
    let catalog_path = root.join("compat").join("mutants.toml");
    let policy_path = root.join("compat").join("mutation-policy.toml");
    let catalog_text = read_text(&catalog_path)?;
    let policy_text = read_text(&policy_path)?;
    require_assignment(&catalog_text, "schema_version", "2")?;
    require_assignment(&catalog_text, "state", "\"required\"")?;
    require_assignment(
        &catalog_text,
        "execution_strategy",
        "\"baseline-pass-mutant-fail\"",
    )?;
    if json_member(report, "catalogSha256")?.string()? != record_digest(&catalog_path)?
        || json_member(report, "policySha256")?.string()? != record_digest(&policy_path)?
    {
        return Err("mutation report does not bind the committed catalog and policy".to_owned());
    }
    let expected_ids = assignment_string_array(&catalog_text, "ids")?;
    let expected_families = assignment_string_array(&catalog_text, "families")?;
    let expected_tests = assignment_string_array(&catalog_text, "tests")?;
    let expected_packages = assignment_string_array(&catalog_text, "packages")?;
    let expected_targets = assignment_string_array(&catalog_text, "targets")?;
    let expected_mutation_sites = assignment_string_array(&catalog_text, "mutation_sites")?;
    let expected_obligation_ids = assignment_string_array(&catalog_text, "obligation_ids")?;
    let expected_claim_group_ids = assignment_string_array(&catalog_text, "claim_group_ids")?;
    let expected_classes = assignment_string_array(&catalog_text, "classes")?;
    let expected_criticalities = assignment_string_array(&catalog_text, "criticalities")?;
    let mutants = json_member(report, "mutants")?.array()?;
    if expected_ids.is_empty()
        || expected_ids.len() != expected_families.len()
        || expected_ids.len() != expected_tests.len()
        || expected_ids.len() != expected_packages.len()
        || expected_ids.len() != expected_targets.len()
        || expected_ids.len() != expected_mutation_sites.len()
        || expected_ids.len() != expected_obligation_ids.len()
        || expected_ids.len() != expected_claim_group_ids.len()
        || expected_ids.len() != expected_classes.len()
        || expected_ids.len() != expected_criticalities.len()
        || expected_ids.iter().collect::<BTreeSet<_>>().len() != expected_ids.len()
        || expected_tests.iter().collect::<BTreeSet<_>>().len() != expected_tests.len()
        || mutants.len() != expected_ids.len()
    {
        return Err("mutation catalog or execution cardinality is incomplete".to_owned());
    }
    let mut families = BTreeSet::new();
    for (index, mutant) in mutants.iter().enumerate() {
        verify_mutation_record(
            root,
            input
                .parent()
                .ok_or_else(|| "mutation report has no retained directory".to_owned())?,
            mutant.object()?,
            MutationSpec {
                id: &expected_ids[index],
                family: &expected_families[index],
                package: &expected_packages[index],
                target: &expected_targets[index],
                test: &expected_tests[index],
                mutation_site: &expected_mutation_sites[index],
                obligation_id: &expected_obligation_ids[index],
                claim_group_id: &expected_claim_group_ids[index],
                class: &expected_classes[index],
                criticality: &expected_criticalities[index],
            },
        )?;
        if expected_classes[index] == "semantic" {
            families.insert(expected_families[index].as_str());
        }
    }
    verify_mutation_totals(report, mutants, &families, &policy_text)?;
    let core_digest = mutation_report_core_digest(report)?;
    if json_member(report, "reportCoreSha256")?.string()? != core_digest {
        return Err("mutation report core digest mismatch".to_owned());
    }
    Ok(core_digest)
}

pub(crate) fn verify_surveillance_mutation_report(
    root: &Path,
    input: &Path,
    candidate: &str,
    epoch: &str,
) -> Result<(), String> {
    require_git_sha_text(candidate, "surveillance mutation candidate")?;
    require_digest(epoch, "surveillance mutation epoch")?;
    let document = parse_json(&read_text(input)?)?;
    let report = document.object()?;
    exact_keys(
        report,
        &[
            "assuranceEpochSha256",
            "assuranceMutantsDetected",
            "assuranceMutantsRequired",
            "candidateSourceCommit",
            "catalogSha256",
            "criticalMutantsDetected",
            "criticalMutantsRequired",
            "familyScoresPerMille",
            "issuedAt",
            "mutants",
            "policySha256",
            "reportCoreSha256",
            "reviewPath",
            "reviewSha256",
            "schemaVersion",
            "undetectedCriticalMutants",
        ],
    )?;
    if json_member(report, "schemaVersion")?.number()? != 1 {
        return Err("surveillance mutation report schemaVersion must be 1".to_owned());
    }
    if json_member(report, "candidateSourceCommit")?.string()? != candidate
        || json_member(report, "assuranceEpochSha256")?.string()? != epoch
    {
        return Err("surveillance mutation report candidate or epoch mismatch".to_owned());
    }
    verify_mutation_records(root, input, report)?;
    Ok(())
}

fn verify_mutation_record(
    root: &Path,
    retained_root: &Path,
    mutant: &BTreeMap<String, JsonValue>,
    spec: MutationSpec<'_>,
) -> Result<(), String> {
    exact_keys(
        mutant,
        &[
            "commandSha256",
            "class",
            "criticality",
            "detected",
            "detectionClaimGroupIds",
            "detectionObligationIds",
            "family",
            "id",
            "activationEnvironment",
            "activationValue",
            "mutationIdentitySha256",
            "mutationSite",
            "strategy",
            "arguments",
            "program",
            "resultPath",
            "resultSha256",
            "test",
        ],
    )?;
    if json_member(mutant, "id")?.string()? != spec.id
        || json_member(mutant, "family")?.string()? != spec.family
        || json_member(mutant, "test")?.string()? != spec.test
        || json_member(mutant, "class")?.string()? != spec.class
        || json_member(mutant, "criticality")?.string()? != spec.criticality
        || json_member(mutant, "program")?.string()? != "cargo"
    {
        return Err("mutation execution record is missing, reordered, or undetected".to_owned());
    }
    if json_member(mutant, "strategy")?.string()? != "baseline-pass-mutant-fail"
        || json_member(mutant, "activationEnvironment")?.string()? != "HELL_ASSURANCE_MUTANT_ID"
        || json_member(mutant, "activationValue")?.string()? != spec.id
        || json_member(mutant, "mutationSite")?.string()? != spec.mutation_site
        || exact_single_string_array(mutant, "detectionObligationIds")? != spec.obligation_id
        || exact_single_string_array(mutant, "detectionClaimGroupIds")? != spec.claim_group_id
    {
        return Err(
            "mutation execution strategy is not the cataloged production-path attack".to_owned(),
        );
    }
    for field in ["commandSha256", "mutationIdentitySha256", "resultSha256"] {
        require_digest(json_member(mutant, field)?.string()?, "mutation execution")?;
    }
    let arguments = json_member(mutant, "arguments")?
        .array()?
        .iter()
        .map(JsonValue::string)
        .collect::<Result<Vec<_>, _>>()?;
    let expected_arguments = mutation_cargo_arguments(spec.package, spec.target, spec.test)?;
    if arguments != expected_arguments {
        return Err("mutation execution arguments do not match the catalog test".to_owned());
    }
    if mutation_command_sha256(&arguments) != json_member(mutant, "commandSha256")?.string()? {
        return Err("mutation command digest is not derived from typed argv".to_owned());
    }
    let expected_identity = mutation_identity_sha256(&spec, &expected_arguments);
    if json_member(mutant, "mutationIdentitySha256")?.string()? != expected_identity {
        return Err(
            "mutation identity is not derived from the committed site and scope".to_owned(),
        );
    }
    let detected =
        verify_retained_mutation_result(root, retained_root, mutant, &spec, &expected_identity)?;
    if json_member(mutant, "detected")?.boolean()? != detected {
        return Err("mutation detection does not match retained test result".to_owned());
    }
    Ok(())
}

fn verify_retained_mutation_result(
    root: &Path,
    retained_root: &Path,
    mutant: &BTreeMap<String, JsonValue>,
    spec: &MutationSpec<'_>,
    expected_identity: &str,
) -> Result<bool, String> {
    let result_path = confined_record_path(
        root,
        retained_root,
        Path::new(json_member(mutant, "resultPath")?.string()?),
    )?;
    verify_file_digest(
        &result_path,
        json_member(mutant, "resultSha256")?.string()?,
        "mutation result",
    )?;
    let result = parse_json(&read_text(&result_path)?)?;
    let result = result.object()?;
    exact_keys(
        result,
        &[
            "baselineExactTestPassed",
            "baselineActivationEnvironment",
            "baselineStatus",
            "baselineStderrPath",
            "baselineStderrSha256",
            "baselineStdoutPath",
            "baselineStdoutSha256",
            "mutantExactTestFailed",
            "mutantActivationEnvironment",
            "mutantStatus",
            "mutantStderrPath",
            "mutantStderrSha256",
            "mutantStdoutPath",
            "mutantStdoutSha256",
            "mutationIdentitySha256",
            "schemaVersion",
        ],
    )?;
    if json_member(result, "mutationIdentitySha256")?.string()? != expected_identity {
        return Err("mutation result identity does not match its execution record".to_owned());
    }
    if !matches!(
        json_member(result, "baselineActivationEnvironment")?,
        JsonValue::Null
    ) || json_member(result, "mutantActivationEnvironment")?.string()? != spec.id
    {
        return Err("mutation execution environment is not exactly retained".to_owned());
    }
    for stream in [
        "baselineStdout",
        "baselineStderr",
        "mutantStdout",
        "mutantStderr",
    ] {
        let path_field = format!("{stream}Path");
        let digest_field = format!("{stream}Sha256");
        let stream_path = confined_record_path(
            root,
            retained_root,
            Path::new(json_member(result, &path_field)?.string()?),
        )?;
        verify_file_digest(
            &stream_path,
            json_member(result, &digest_field)?.string()?,
            "mutation test output",
        )?;
    }
    retained_mutant_detected(root, retained_root, result, spec.test)
}

fn exact_single_string_array<'a>(
    object: &'a BTreeMap<String, JsonValue>,
    field: &str,
) -> Result<&'a str, String> {
    let values = json_member(object, field)?.array()?;
    if values.len() != 1 {
        return Err(format!(
            "{field} must contain exactly one committed binding"
        ));
    }
    values[0].string()
}

fn retained_mutant_detected(
    root: &Path,
    retained_root: &Path,
    result: &BTreeMap<String, JsonValue>,
    expected_test: &str,
) -> Result<bool, String> {
    let baseline_stdout_path = confined_record_path(
        root,
        retained_root,
        Path::new(json_member(result, "baselineStdoutPath")?.string()?),
    )?;
    let mutant_stdout_path = confined_record_path(
        root,
        retained_root,
        Path::new(json_member(result, "mutantStdoutPath")?.string()?),
    )?;
    Ok(json_member(result, "schemaVersion")?.number()? == 4
        && json_member(result, "baselineStatus")?.number()? == 0
        && json_member(result, "mutantStatus")?.number()? != 0
        && json_member(result, "baselineExactTestPassed")?.boolean()?
        && json_member(result, "mutantExactTestFailed")?.boolean()?
        && exact_test_harness_success(&read_regular_file(&baseline_stdout_path)?, expected_test)?
        && exact_test_harness_failure(&read_regular_file(&mutant_stdout_path)?, expected_test)?)
}

fn verify_mutation_totals(
    report: &BTreeMap<String, JsonValue>,
    mutants: &[JsonValue],
    families: &BTreeSet<&str>,
    policy: &str,
) -> Result<(), String> {
    require_assignment(policy, "required_assurance_mutants_detected", "\"all\"")?;
    require_assignment(policy, "critical_mutants_must_all_be_detected", "true")?;
    let mut controls = (0_u64, 0_u64);
    let mut critical = (0_u64, 0_u64);
    let mut semantic_scores = BTreeMap::<&str, (u64, u64)>::new();
    for mutant in mutants {
        let mutant = mutant.object()?;
        let detected = json_member(mutant, "detected")?.boolean()?;
        match json_member(mutant, "class")?.string()? {
            "control" => {
                controls.0 = controls.0.saturating_add(1);
                controls.1 = controls.1.saturating_add(u64::from(detected));
            }
            "semantic" => {
                let counts = semantic_scores
                    .entry(json_member(mutant, "family")?.string()?)
                    .or_default();
                counts.0 = counts.0.saturating_add(1);
                counts.1 = counts.1.saturating_add(u64::from(detected));
            }
            _ => return Err("mutation class is not control or semantic".to_owned()),
        }
        match json_member(mutant, "criticality")?.string()? {
            "critical" => {
                critical.0 = critical.0.saturating_add(1);
                critical.1 = critical.1.saturating_add(u64::from(detected));
            }
            "noncritical" => {}
            _ => return Err("mutation criticality is invalid".to_owned()),
        }
    }
    if json_member(report, "undetectedCriticalMutants")?.number()?
        != critical.0.saturating_sub(critical.1)
        || json_member(report, "assuranceMutantsRequired")?.number()? != controls.0
        || json_member(report, "assuranceMutantsDetected")?.number()? != controls.1
        || controls.0 != controls.1
        || json_member(report, "criticalMutantsRequired")?.number()? != critical.0
        || json_member(report, "criticalMutantsDetected")?.number()? != critical.1
        || critical.0 != critical.1
    {
        return Err("mutation policy thresholds are not satisfied".to_owned());
    }
    let issued = utc_timestamp_seconds(json_member(report, "issuedAt")?.string()?)?;
    let now = current_utc_seconds()?;
    let maximum_age = assignment_u64(policy, "maximum_report_age_days")?
        .checked_mul(86_400)
        .ok_or_else(|| "mutation maximum report age overflows".to_owned())?;
    if issued > now || now.saturating_sub(issued) > maximum_age {
        return Err("mutation report is future-dated or stale".to_owned());
    }
    let scores = json_member(report, "familyScoresPerMille")?.object()?;
    let minimum = assignment_u64(policy, "minimum_semantic_family_score_per_mille")?;
    if minimum > 1_000
        || scores.len() != families.len()
        || families
            .iter()
            .any(|family| match semantic_scores.get(*family) {
                Some((required, detected)) if *required != 0 => {
                    let derived = detected.saturating_mul(1_000) / required;
                    scores.get(*family).and_then(|score| score.number().ok()) != Some(derived)
                        || derived < minimum
                }
                _ => true,
            })
    {
        return Err("semantic family mutation score is below policy".to_owned());
    }
    Ok(())
}

fn verify_mutation_review(
    root: &Path,
    input: &Path,
    options: &Options,
    report: &BTreeMap<String, JsonValue>,
    candidate: &str,
    epoch: &str,
    core_digest: &str,
) -> Result<(), String> {
    let policy = required_path(&options.policy, "mutation verify requires --policy")?;
    let review_path = confined_record_path(
        root,
        retained_evidence_root(input)?,
        Path::new(json_member(report, "reviewPath")?.string()?),
    )?;
    verify_file_digest(
        &review_path,
        json_member(report, "reviewSha256")?.string()?,
        "mutation review",
    )?;
    let review = verify_review_envelope(&review_path, policy)?;
    let report_issued_at = json_member(report, "issuedAt")?.string()?;
    validate_utc_timestamp(report_issued_at)?;
    if utc_timestamp_seconds(&review.issued_at)? < utc_timestamp_seconds(report_issued_at)? {
        return Err("mutation review predates the retained campaign".to_owned());
    }
    if review.role != "mutation-reviewer"
        || review.candidate_commit != candidate
        || review.assurance_epoch != epoch
        || !review.reviewed_artifacts.contains(core_digest)
    {
        return Err("mutation review does not authorize the exact execution records".to_owned());
    }
    Ok(())
}

fn mutation_report_core_digest(report: &BTreeMap<String, JsonValue>) -> Result<String, String> {
    let mut core = report.clone();
    for field in ["reportCoreSha256", "reviewPath", "reviewSha256"] {
        core.remove(field);
    }
    canonical_json_digest(&JsonValue::Object(core))
}

fn divergence_propose(options: &Options) -> Result<String, String> {
    let input = required_path(&options.input, "divergence-propose requires --input")?;
    let output = required_path(&options.output, "divergence-propose requires --output")?;
    let candidate = parse_json(&read_text(input)?)?;
    verify_proposed_divergence_record(candidate.object()?)?;
    let candidate_sha256 = canonical_json_digest(&candidate)?;
    let candidate_object = candidate.object()?;
    let scope = JsonValue::Object(BTreeMap::from([
        (
            "builtin".to_owned(),
            json_member(candidate_object, "builtin")?.clone(),
        ),
        (
            "dimension".to_owned(),
            json_member(candidate_object, "dimension")?.clone(),
        ),
        (
            "platform".to_owned(),
            json_member(candidate_object, "platform")?.clone(),
        ),
        (
            "profile".to_owned(),
            json_member(candidate_object, "profile")?.clone(),
        ),
    ]));
    let proposal = JsonValue::Object(BTreeMap::from([
        (
            "candidateSha256".to_owned(),
            JsonValue::String(candidate_sha256),
        ),
        ("mismatchEvidence".to_owned(), candidate),
        (
            "requiredApprovals".to_owned(),
            JsonValue::Array(
                [
                    "expiry",
                    "fixability",
                    "impact-tier",
                    "issue-state",
                    "reproduction",
                ]
                .into_iter()
                .map(|value| JsonValue::String(value.to_owned()))
                .collect(),
            ),
        ),
        ("reviewStatements".to_owned(), JsonValue::Array(Vec::new())),
        ("schemaVersion".to_owned(), JsonValue::Number(2)),
        ("scope".to_owned(), scope),
        (
            "status".to_owned(),
            JsonValue::String("proposed".to_owned()),
        ),
    ]));
    write_atomic(output, &canonical_json_bytes(&proposal)?)?;
    Ok(format!(
        "wrote exact fail-closed divergence proposal {}",
        output.display()
    ))
}

fn artifact_acquire(root: &Path, options: &Options) -> Result<String, String> {
    if let Some(result) = artifact_acquire_special(root, options) {
        return result;
    }
    artifact_acquire_receipt(root, options)
}

fn artifact_acquire_special(root: &Path, options: &Options) -> Option<Result<String, String>> {
    if options.action.as_deref() == Some("prepare-external-independent") {
        return Some(prepare_external_independent_request(root, options));
    }
    if options.action.as_deref() == Some("verify-external-independent-request") {
        let result = (|| {
            let input = required_path(
                &options.input,
                "verify-external-independent-request requires --input request",
            )?;
            if options.output.is_some()
                || options.artifact.as_deref() != Some("native-oracle-merged")
                || options.github_dispatch_inputs
            {
                return Err(
                    "verify-external-independent-request accepts only exact input and artifact"
                        .to_owned(),
                );
            }
            verify_external_independent_request(root, input, "native-oracle-merged")?;
            Ok(format!(
                "verified sealed external acquisition request {}",
                input.display()
            ))
        })();
        return Some(result);
    }
    if options.action.as_deref() == Some("prepare-provider-attestation") {
        return Some(prepare_provider_attestation_subject(root, options));
    }
    if options.action.as_deref() == Some("finalize") {
        return Some(artifact_finalize(root, options));
    }
    if options.action.as_deref() == Some("assemble-finalize") {
        return Some(artifact_finalize_assemble(root, options));
    }
    if matches!(
        options.action.as_deref(),
        Some("attest-primary" | "attest-independent")
    ) {
        return Some(artifact_receipt_attest(options));
    }
    None
}

fn artifact_acquire_receipt(root: &Path, options: &Options) -> Result<String, String> {
    let output = required_path(&options.output, "artifact-acquire requires --output")?;
    let external_independent = options.action.as_deref() == Some("external-independent");
    let generated_input;
    let requested_input = if external_independent {
        generated_input = acquire_external_independent_artifact(
            root,
            required_path(
                &options.input,
                "external-independent acquisition requires --input sealed request",
            )?,
            output,
        )?;
        generated_input.as_path()
    } else {
        required_path(
            &options.input,
            "artifact-acquire requires a locally acquired --input",
        )?
    };
    let independent = matches!(
        options.action.as_deref(),
        Some("independent" | "external-independent")
    );
    let retained_independent;
    let input = if independent && !external_independent {
        retained_independent = output
            .parent()
            .ok_or_else(|| "independent receipt output has no directory".to_owned())?
            .join("independent");
        copy_record_tree(requested_input, &retained_independent)?;
        retained_independent.as_path()
    } else {
        requested_input
    };
    let artifact = options
        .artifact
        .as_deref()
        .ok_or_else(|| "artifact-acquire requires --artifact".to_owned())?;
    let primary = options.action.as_deref() == Some("primary");
    let dispatch = if external_independent {
        Some(external_independent_dispatch_from_request(
            root,
            required_path(
                &options.input,
                "external-independent acquisition requires --input sealed request",
            )?,
            input,
            artifact,
        )?)
    } else if (primary || independent) && options.github_dispatch_inputs {
        Some(artifact_primary_dispatch(root, input, artifact)?)
    } else {
        None
    };
    let receipt = acquisition_receipt(
        root,
        input,
        output,
        artifact,
        primary,
        independent,
        dispatch.as_ref(),
    )?;
    write_atomic(
        output,
        acquisition_receipt_json(&receipt, "REVIEW_REQUIRED")?.as_bytes(),
    )?;
    if primary {
        let parent = output
            .parent()
            .ok_or_else(|| "primary acquisition output has no directory".to_owned())?;
        acquire_and_verify_provider_attestation(input, parent, &receipt)?;
    }
    Ok(format!("recorded acquisition receipt {}", output.display()))
}

fn external_independent_dispatch_from_request(
    root: &Path,
    request: &Path,
    input: &Path,
    artifact: &str,
) -> Result<AcquisitionDispatch, String> {
    let document = verify_external_independent_request(root, request, artifact)?;
    let fields = document.object()?;
    let candidate = json_member(fields, "candidateCommit")?.string()?;
    let expected = json_member(fields, "expectedArtifactSetSha256")?.string()?;
    if artifact != json_member(fields, "artifact")?.string()?
        || git_output(root, &["rev-parse", "HEAD"])?.trim() != candidate
        || record_digest(input)? != expected
    {
        return Err("external acquisition result differs from sealed request".to_owned());
    }
    let run_id = json_member(fields, "sourceRunId")?.number()?.to_string();
    let run_attempt = json_member(fields, "sourceRunAttempt")?
        .number()?
        .to_string();
    let resolved = resolve_provider_artifact(&run_id, artifact)?;
    if resolved.id != json_member(fields, "sourceArtifactId")?.number()? {
        return Err("external source artifact ID differs from sealed request".to_owned());
    }
    verify_resolved_provider_archive(
        &resolved,
        json_member(fields, "sourceProviderArchiveSha256")?.string()?,
    )?;
    Ok(AcquisitionDispatch {
        candidate: candidate.to_owned(),
        run_id,
        run_attempt,
        acquired_at: crate::custody_ops::current_utc_timestamp()?,
        provider_artifact_id: resolved.id,
        provider_selection_api: resolved.api_bytes,
        provider_event: "push".to_owned(),
        workflow_path: ".github/workflows/nightly.yml".to_owned(),
    })
}

fn verify_external_independent_request(
    root: &Path,
    request: &Path,
    artifact: &str,
) -> Result<JsonValue, String> {
    let metadata = fs::symlink_metadata(request)
        .map_err(|error| format!("cannot inspect external acquisition request: {error}"))?;
    if metadata.file_type().is_symlink() || !metadata.is_file() {
        return Err("external acquisition request is not a regular file".to_owned());
    }
    let bytes = read_regular_file(request)?;
    let document = parse_json(
        std::str::from_utf8(&bytes)
            .map_err(|_| "external acquisition request is not UTF-8".to_owned())?,
    )?;
    if canonical_json_bytes(&document)? != bytes {
        return Err("external acquisition request is not canonical".to_owned());
    }
    let fields = document.object()?;
    exact_keys(
        fields,
        &[
            "archiveSha256",
            "artifact",
            "bucket",
            "candidateCommit",
            "expectedArtifactSetSha256",
            "key",
            "region",
            "schemaVersion",
            "sourceArtifactId",
            "sourceProviderArchiveSha256",
            "sourceRunAttempt",
            "sourceRunId",
            "state",
            "versionId",
        ],
    )?;
    if json_member(fields, "schemaVersion")?.number()? != 1
        || json_member(fields, "state")?.string()? != "sealed-before-external-credentials"
        || json_member(fields, "artifact")?.string()? != artifact
        || json_member(fields, "sourceArtifactId")?.number()? == 0
        || json_member(fields, "sourceRunId")?.number()? == 0
        || json_member(fields, "sourceRunAttempt")?.number()? == 0
    {
        return Err("external acquisition request identity is invalid".to_owned());
    }
    let candidate = json_member(fields, "candidateCommit")?.string()?;
    require_git_sha_text(candidate, "external acquisition request candidate")?;
    if git_output(root, &["rev-parse", "HEAD"])?.trim() != candidate {
        return Err("external acquisition request differs from current HEAD".to_owned());
    }
    require_digest(
        json_member(fields, "expectedArtifactSetSha256")?.string()?,
        "external acquisition request artifact set",
    )?;
    require_digest(
        json_member(fields, "archiveSha256")?.string()?,
        "external acquisition request archive",
    )?;
    external_s3_object_url(
        json_member(fields, "bucket")?.string()?,
        json_member(fields, "key")?.string()?,
        json_member(fields, "versionId")?.string()?,
        json_member(fields, "region")?.string()?,
    )?;
    let sibling = request.with_extension("json.sha256");
    let sibling_metadata = fs::symlink_metadata(&sibling)
        .map_err(|error| format!("cannot inspect external request digest: {error}"))?;
    if sibling_metadata.file_type().is_symlink()
        || !sibling_metadata.is_file()
        || read_text(&sibling)? != format!("{}\n", sha256_bytes(&bytes).hex())
    {
        return Err("external acquisition request digest sibling differs".to_owned());
    }
    Ok(document)
}

fn prepare_external_independent_request(root: &Path, options: &Options) -> Result<String, String> {
    let output = required_path(
        &options.output,
        "prepare-external-independent requires --output request",
    )?;
    if options.input.is_some()
        || options.artifact.as_deref() != Some("native-oracle-merged")
        || !options.github_dispatch_inputs
    {
        return Err(
            "prepare-external-independent requires exact artifact and dispatch inputs".to_owned(),
        );
    }
    let dispatch =
        artifact_primary_dispatch_from_event(root, options.artifact.as_deref().unwrap())?;
    let bucket = required_environment("ARTIFACT_INDEPENDENT_BUCKET")?;
    let key = required_environment("ARTIFACT_INDEPENDENT_KEY")?;
    let version = required_environment("ARTIFACT_INDEPENDENT_VERSION_ID")?;
    let region = required_environment("ARTIFACT_INDEPENDENT_REGION")?;
    let archive = required_environment("ARTIFACT_INDEPENDENT_ARCHIVE_SHA256")?;
    require_digest(&archive, "external provider archive")?;
    external_s3_object_url(&bucket, &key, &version, &region)?;
    let request = JsonValue::Object(BTreeMap::from([
        ("archiveSha256".to_owned(), JsonValue::String(archive)),
        (
            "artifact".to_owned(),
            JsonValue::String("native-oracle-merged".to_owned()),
        ),
        ("bucket".to_owned(), JsonValue::String(bucket)),
        (
            "candidateCommit".to_owned(),
            JsonValue::String(dispatch.candidate),
        ),
        (
            "expectedArtifactSetSha256".to_owned(),
            JsonValue::String(dispatch.expected_set),
        ),
        ("key".to_owned(), JsonValue::String(key)),
        ("region".to_owned(), JsonValue::String(region)),
        ("schemaVersion".to_owned(), JsonValue::Number(1)),
        (
            "sourceRunAttempt".to_owned(),
            JsonValue::Number(dispatch.run_attempt),
        ),
        (
            "sourceArtifactId".to_owned(),
            JsonValue::Number(dispatch.artifact_id),
        ),
        (
            "sourceProviderArchiveSha256".to_owned(),
            JsonValue::String(dispatch.archive_sha256),
        ),
        ("sourceRunId".to_owned(), JsonValue::Number(dispatch.run_id)),
        (
            "state".to_owned(),
            JsonValue::String("sealed-before-external-credentials".to_owned()),
        ),
        ("versionId".to_owned(), JsonValue::String(version)),
    ]));
    let bytes = canonical_json_bytes(&request)?;
    write_atomic(output, &bytes)?;
    write_digest_sibling(output, sha256_bytes(&bytes))?;
    Ok(format!(
        "wrote sealed external acquisition request {}",
        output.display()
    ))
}

struct ExternalIndependentDispatch {
    candidate: String,
    run_id: u64,
    run_attempt: u64,
    artifact_id: u64,
    expected_set: String,
    archive_sha256: String,
}

fn artifact_primary_dispatch_from_event(
    root: &Path,
    artifact: &str,
) -> Result<ExternalIndependentDispatch, String> {
    if artifact != "native-oracle-merged" {
        return Err("external acquisition artifact is not accepted".to_owned());
    }
    let event_path = std::env::var_os("GITHUB_EVENT_PATH")
        .ok_or_else(|| "GITHUB_EVENT_PATH is unavailable for external acquisition".to_owned())?;
    let event = parse_json(&read_text(Path::new(&event_path))?)?;
    let inputs = json_member(event.object()?, "inputs")?.object()?;
    exact_keys(
        inputs,
        &[
            "candidate_sha",
            "expected_artifact_set_sha256",
            "source_artifact_id",
            "source_provider_archive_sha256",
            "source_run_attempt",
            "source_run_id",
        ],
    )?;
    let candidate = json_member(inputs, "candidate_sha")?.string()?.to_owned();
    require_git_sha_text(&candidate, "external acquisition candidate")?;
    if git_output(root, &["rev-parse", "HEAD"])?.trim() != candidate {
        return Err("external acquisition checkout differs from candidate".to_owned());
    }
    let expected_set = json_member(inputs, "expected_artifact_set_sha256")?
        .string()?
        .to_owned();
    require_digest(&expected_set, "external acquisition artifact set")?;
    let archive_sha256 = json_member(inputs, "source_provider_archive_sha256")?
        .string()?
        .to_owned();
    require_digest(
        &archive_sha256,
        "external acquisition source provider archive",
    )?;
    let positive = |key| {
        let number = json_member(inputs, key)?
            .string()?
            .parse::<u64>()
            .map_err(|_| format!("external acquisition {key} is not an integer"))?;
        (number != 0)
            .then_some(number)
            .ok_or_else(|| format!("external acquisition {key} must be nonzero"))
    };
    Ok(ExternalIndependentDispatch {
        candidate,
        run_id: positive("source_run_id")?,
        run_attempt: positive("source_run_attempt")?,
        artifact_id: positive("source_artifact_id")?,
        expected_set,
        archive_sha256,
    })
}

fn prepare_provider_attestation_subject(root: &Path, options: &Options) -> Result<String, String> {
    let input = required_path(
        &options.input,
        "provider attestation subject requires --input artifact directory",
    )?;
    let output = required_path(
        &options.output,
        "provider attestation subject requires --output subject",
    )?;
    let artifact = options
        .artifact
        .as_deref()
        .ok_or_else(|| "provider attestation subject requires --artifact".to_owned())?;
    validate_provider_atom(artifact, "attested provider artifact")?;
    if output.parent() != Some(input)
        || output.file_name() != Some(OsStr::new("provider-attestation-subject.json"))
    {
        return Err(
            "provider attestation subject must use its canonical artifact-local path".to_owned(),
        );
    }
    if output.exists() {
        return Err("provider attestation subject already exists".to_owned());
    }
    let candidate = git_output(root, &["rev-parse", "HEAD"])?.trim().to_owned();
    require_git_sha_text(&candidate, "provider attestation candidate")?;
    let subject = JsonValue::Object(BTreeMap::from([
        (
            "artifact".to_owned(),
            JsonValue::String(artifact.to_owned()),
        ),
        (
            "artifactSetSha256".to_owned(),
            JsonValue::String(record_digest(input)?),
        ),
        ("candidateCommit".to_owned(), JsonValue::String(candidate)),
        ("schemaVersion".to_owned(), JsonValue::Number(1)),
    ]));
    write_atomic(output, &canonical_json_bytes(&subject)?)?;
    Ok(format!(
        "wrote public attestation subject {}",
        output.display()
    ))
}

fn acquire_and_verify_provider_attestation(
    input: &Path,
    output_directory: &Path,
    receipt: &AcquisitionReceipt,
) -> Result<(), String> {
    let subject = input.join("provider-attestation-subject.json");
    let subject_document = parse_json(&read_text(&subject)?)?;
    let subject_object = subject_document.object()?;
    exact_keys(
        subject_object,
        &[
            "artifact",
            "artifactSetSha256",
            "candidateCommit",
            "schemaVersion",
        ],
    )?;
    let artifact_set_sha256 = sha256_bytes(
        directory_manifest_excluding(input, Path::new("provider-attestation-subject.json"))?
            .as_bytes(),
    )
    .hex();
    if json_member(subject_object, "schemaVersion")?.number()? != 1
        || json_member(subject_object, "artifact")?.string()? != receipt.artifact
        || json_member(subject_object, "candidateCommit")?.string()? != receipt.candidate_commit
        || json_member(subject_object, "artifactSetSha256")?.string()? != artifact_set_sha256
    {
        return Err(
            "public attestation subject does not bind the acquired artifact set".to_owned(),
        );
    }
    let subject_sha256 = record_digest(&subject)?;
    let lookup = query_provider_attestations(&subject_sha256)?;
    let lookup_path = output_directory.join("provider-attestation-lookup.json");
    write_atomic(&lookup_path, &canonical_json_bytes(&lookup.document)?)?;
    let lookup_sha256 = record_digest(&lookup_path)?;
    let (state, reason, verification_path, verification_sha256) = if lookup.available {
        let verification = verify_provider_attestation_signature(&subject, receipt)?;
        let path = output_directory.join("provider-attestation-verification.json");
        write_atomic(&path, &verification)?;
        (
            "verified",
            String::new(),
            Some("provider-attestation-verification.json"),
            Some(record_digest(&path)?),
        )
    } else {
        (
            "unavailable-reviewed",
            format!(
                "provider public attestation lookup was {}; explicit external review is required",
                lookup.state
            ),
            None,
            None,
        )
    };
    let report = JsonValue::Object(BTreeMap::from([
        (
            "artifactSetSha256".to_owned(),
            JsonValue::String(artifact_set_sha256),
        ),
        (
            "artifactSha256".to_owned(),
            JsonValue::String(receipt.observed_sha256.clone()),
        ),
        (
            "attestedSubjectPath".to_owned(),
            JsonValue::String("primary/provider-attestation-subject.json".to_owned()),
        ),
        (
            "attestedSubjectSha256".to_owned(),
            JsonValue::String(subject_sha256),
        ),
        (
            "lookupPath".to_owned(),
            JsonValue::String("provider-attestation-lookup.json".to_owned()),
        ),
        ("lookupSha256".to_owned(), JsonValue::String(lookup_sha256)),
        (
            "lookupState".to_owned(),
            JsonValue::String(lookup.state.to_owned()),
        ),
        ("reason".to_owned(), JsonValue::String(reason)),
        ("schemaVersion".to_owned(), JsonValue::Number(2)),
        ("state".to_owned(), JsonValue::String(state.to_owned())),
        (
            "verificationPath".to_owned(),
            verification_path.map_or(JsonValue::Null, |path| JsonValue::String(path.to_owned())),
        ),
        (
            "verificationSha256".to_owned(),
            verification_sha256.map_or(JsonValue::Null, JsonValue::String),
        ),
    ]));
    write_atomic(
        &output_directory.join("attestation-verification.json"),
        &canonical_json_bytes(&report)?,
    )
}

struct ProviderAttestationLookup {
    available: bool,
    state: &'static str,
    document: JsonValue,
}

fn query_provider_attestations(subject_sha256: &str) -> Result<ProviderAttestationLookup, String> {
    let subject_digest = GithubAttestationSubjectDigest::new(subject_sha256)?;
    let endpoint = PathBuf::from("repos")
        .join("Portfoligno")
        .join("hell-rs")
        .join("attestations")
        .join(subject_digest.path_component()?);
    let response = Command::new("gh")
        .args([OsStr::new("api"), endpoint.as_os_str()])
        .output()
        .map_err(|error| format!("cannot query provider attestations: {error}"))?;
    if !response.status.success() {
        let stderr = String::from_utf8(response.stderr)
            .map_err(|_| "provider attestation lookup error is not UTF-8".to_owned())?;
        let state = if stderr.contains("HTTP 404") {
            "absent"
        } else {
            "service-failure"
        };
        return Ok(ProviderAttestationLookup {
            available: false,
            state,
            document: JsonValue::Object(BTreeMap::from([
                (
                    "endpoint".to_owned(),
                    JsonValue::String(path_text(&endpoint)?),
                ),
                ("error".to_owned(), JsonValue::String(stderr.clone())),
                (
                    "errorSha256".to_owned(),
                    JsonValue::String(sha256_bytes(stderr.as_bytes()).hex()),
                ),
                ("schemaVersion".to_owned(), JsonValue::Number(1)),
                ("state".to_owned(), JsonValue::String(state.to_owned())),
                (
                    "subjectSha256".to_owned(),
                    JsonValue::String(subject_sha256.to_owned()),
                ),
            ])),
        });
    }
    let response = parse_json(
        std::str::from_utf8(&response.stdout)
            .map_err(|_| "provider attestation lookup is not UTF-8".to_owned())?,
    )?;
    let attestations = json_member(response.object()?, "attestations")?.array()?;
    let available = !attestations.is_empty();
    Ok(ProviderAttestationLookup {
        available,
        state: if available { "available" } else { "empty" },
        document: JsonValue::Object(BTreeMap::from([
            ("response".to_owned(), response),
            ("schemaVersion".to_owned(), JsonValue::Number(1)),
            (
                "state".to_owned(),
                JsonValue::String(if available { "available" } else { "empty" }.to_owned()),
            ),
            (
                "subjectSha256".to_owned(),
                JsonValue::String(subject_sha256.to_owned()),
            ),
        ])),
    })
}

struct GithubAttestationSubjectDigest(String);

impl GithubAttestationSubjectDigest {
    fn new(digest: &str) -> Result<Self, String> {
        require_digest(digest, "provider attestation subject")?;
        Ok(Self(digest.to_owned()))
    }

    fn path_component(&self) -> Result<OsString, String> {
        let mut component = OsString::from("sha256:");
        component.push(&self.0);
        let text = component
            .to_str()
            .ok_or_else(|| "provider attestation digest token is not UTF-8".to_owned())?;
        if text.strip_prefix("sha256:") != Some(self.0.as_str()) {
            return Err("provider attestation digest token did not round trip".to_owned());
        }
        Ok(component)
    }
}

fn verify_provider_attestation_signature(
    subject: &Path,
    receipt: &AcquisitionReceipt,
) -> Result<Vec<u8>, String> {
    let response = Command::new("gh")
        .args([
            OsStr::new("attestation"),
            OsStr::new("verify"),
            subject.as_os_str(),
            OsStr::new("--repo"),
            OsStr::new("Portfoligno/hell-rs"),
            OsStr::new("--signer-workflow"),
            OsStr::new("Portfoligno/hell-rs/.github/workflows/nightly.yml"),
            OsStr::new("--source-digest"),
            OsStr::new(&receipt.candidate_commit),
            OsStr::new("--deny-self-hosted-runners"),
            OsStr::new("--format"),
            OsStr::new("json"),
        ])
        .output()
        .map_err(|error| format!("cannot execute provider attestation verifier: {error}"))?;
    if !response.status.success() {
        return Err(format!(
            "available provider attestation failed cryptographic verification: {}",
            String::from_utf8_lossy(&response.stderr)
        ));
    }
    let verification = parse_json(
        std::str::from_utf8(&response.stdout)
            .map_err(|_| "provider attestation verification is not UTF-8".to_owned())?,
    )?;
    verify_attestation_output_subject(&verification, &record_digest(subject)?)?;
    canonical_json_bytes(&verification)
}

fn verify_attestation_output_subject(
    verification: &JsonValue,
    subject_sha256: &str,
) -> Result<(), String> {
    require_digest(subject_sha256, "verified attestation subject")?;
    let mut matched = false;
    for entry in verification.array()? {
        let result = json_member(entry.object()?, "verificationResult")?.object()?;
        let statement = json_member(result, "statement")?.object()?;
        if json_member(statement, "predicateType")?.string()? != "https://slsa.dev/provenance/v1" {
            continue;
        }
        for subject in json_member(statement, "subject")?.array()? {
            let digest = json_member(subject.object()?, "digest")?.object()?;
            if json_member(digest, "sha256")?.string()? == subject_sha256 {
                matched = true;
            }
        }
    }
    if !matched {
        return Err("provider attestation verification does not bind its exact subject".to_owned());
    }
    Ok(())
}

struct ExternalAcquisitionIdentity {
    path: PathBuf,
    sha256: String,
    trust_domain: String,
    stable_acquirer: String,
    repository_id: u64,
    run_id: u64,
    run_attempt: u64,
    workflow_ref: String,
    acquired_at: String,
}

fn acquire_external_independent_artifact(
    root: &Path,
    request: &Path,
    output: &Path,
) -> Result<PathBuf, String> {
    let directory = output
        .parent()
        .ok_or_else(|| "external acquisition output has no directory".to_owned())?;
    fs::create_dir_all(directory)
        .map_err(|error| format!("cannot create external acquisition directory: {error}"))?;
    let archive = directory.join("external-provider-object.zip");
    let headers = directory.join("external-provider-headers.txt");
    let tls_path = directory.join("external-provider-tls.json");
    let extracted = directory.join("independent");
    if archive.exists() || headers.exists() || tls_path.exists() || extracted.exists() {
        return Err("external acquisition output paths already exist".to_owned());
    }
    let request_document =
        verify_external_independent_request(root, request, "native-oracle-merged")?;
    let request_fields = request_document.object()?;
    let bucket = json_member(request_fields, "bucket")?.string()?.to_owned();
    let key = json_member(request_fields, "key")?.string()?.to_owned();
    let version = json_member(request_fields, "versionId")?
        .string()?
        .to_owned();
    let region = json_member(request_fields, "region")?.string()?.to_owned();
    let expected_archive = json_member(request_fields, "archiveSha256")?
        .string()?
        .to_owned();
    require_digest(&expected_archive, "external provider archive")?;
    require_git_sha_text(
        json_member(request_fields, "candidateCommit")?.string()?,
        "external acquisition request candidate",
    )?;
    require_digest(
        json_member(request_fields, "expectedArtifactSetSha256")?.string()?,
        "external acquisition request artifact set",
    )?;
    let request_url = external_s3_object_url(&bucket, &key, &version, &region)?;
    let effective_host = format!("{bucket}.s3.{region}.amazonaws.com");
    let tls = crate::release_oracle::external_tls_identity_json(&effective_host)?;
    write_atomic(&tls_path, tls.as_bytes())?;
    let tls_document = parse_json(&tls)?;
    let transport = download_external_s3_object(&request_url, &region, &archive, &headers)?;
    if record_digest(&archive)? != expected_archive {
        return Err(
            "external provider archive digest differs from protected configuration".to_owned(),
        );
    }
    let head = external_aws_json(&[
        "s3api",
        "head-object",
        "--bucket",
        &bucket,
        "--key",
        &key,
        "--version-id",
        &version,
        "--region",
        &region,
    ])?;
    verify_external_s3_head(head.object()?, &version, &archive, &transport)?;
    let caller = external_aws_json(&["sts", "get-caller-identity"])?;
    let caller = caller.object()?;
    let account = json_member(caller, "Account")?.string()?;
    let principal_arn = json_member(caller, "Arn")?.string()?;
    let principal_id = json_member(caller, "UserId")?.string()?;
    validate_external_identity(account, principal_arn, principal_id)?;
    extract_external_zip(&archive, &extracted)?;
    let actor_id = environment_u64("GITHUB_ACTOR_ID", "external acquirer account")?;
    let actor_login = required_environment("GITHUB_ACTOR")?;
    validate_provider_atom(&actor_login, "external acquirer login")?;
    let evidence = external_acquisition_document(&ExternalAcquisitionDocument {
        bucket: &bucket,
        key: &key,
        version: &version,
        region: &region,
        request_url: &request_url,
        archive_sha256: &expected_archive,
        archive_size: record_size(&archive)?,
        extracted_sha256: &record_digest(&extracted)?,
        headers_sha256: &record_digest(&headers)?,
        tls_sha256: &record_digest(&tls_path)?,
        tls: tls_document.object()?,
        transport: &transport,
        account,
        principal_arn,
        principal_id,
        actor_id,
        actor_login: &actor_login,
    })?;
    write_atomic(
        &directory.join("external-acquisition.json"),
        &canonical_json_bytes(&evidence)?,
    )?;
    Ok(extracted)
}

fn required_environment(name: &str) -> Result<String, String> {
    let value = std::env::var(name).map_err(|_| format!("external acquisition requires {name}"))?;
    if value.is_empty() || value.chars().any(char::is_control) {
        return Err(format!(
            "external acquisition {name} is empty or contains controls"
        ));
    }
    Ok(value)
}

fn external_s3_object_url(
    bucket: &str,
    key: &str,
    version: &str,
    region: &str,
) -> Result<String, String> {
    if bucket.is_empty()
        || !bucket.bytes().all(|byte| {
            byte.is_ascii_lowercase() || byte.is_ascii_digit() || matches!(byte, b'-' | b'.')
        })
    {
        return Err("external provider bucket is not canonical".to_owned());
    }
    validate_provider_atom(region, "external provider region")?;
    let encode = |value: &str, preserve_slash: bool| {
        let mut encoded = String::new();
        for byte in value.bytes() {
            if byte.is_ascii_alphanumeric()
                || matches!(byte, b'-' | b'.' | b'_' | b'~')
                || preserve_slash && byte == b'/'
            {
                encoded.push(char::from(byte));
            } else {
                write!(encoded, "%{byte:02X}").expect("writing to String cannot fail");
            }
        }
        encoded
    };
    if key.is_empty()
        || key.starts_with('/')
        || key
            .split('/')
            .any(|component| component.is_empty() || matches!(component, "." | ".."))
    {
        return Err("external provider object key is not canonical".to_owned());
    }
    Ok(format!(
        "https://{bucket}.s3.{region}.amazonaws.com/{}?versionId={}",
        encode(key, true),
        encode(version, false)
    ))
}

struct ExternalTransport {
    effective_url_sha256: String,
    http_status: u64,
    ssl_verify_result: u64,
    etag: String,
    last_modified: String,
    content_length: u64,
    response_version_id: String,
    curl_version: String,
}

fn download_external_s3_object(
    request_url: &str,
    region: &str,
    archive: &Path,
    headers: &Path,
) -> Result<ExternalTransport, String> {
    let access = required_environment("AWS_ACCESS_KEY_ID")?;
    let secret = required_environment("AWS_SECRET_ACCESS_KEY")?;
    let token = required_environment("AWS_SESSION_TOKEN")?;
    let credential_config = CurlAwsCredentialConfig::new(&access, &secret, &token)?;
    let sigv4 = AwsSigV4Argument::new(region)?;
    let mut command = Command::new("curl");
    command.args([
        "--fail",
        "--silent",
        "--show-error",
        "--proto",
        "=https",
        "--tlsv1.2",
        "--max-redirs",
        "0",
        "--aws-sigv4",
        sigv4.as_str(),
        "--config",
        "-",
        "--dump-header",
    ]);
    command.arg(headers).args(["--output"]).arg(archive).args([
        "--write-out",
        "%{http_code}\n%{num_redirects}\n%{url_effective}\n%{ssl_verify_result}\n",
        request_url,
    ]);
    command
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    let mut child = command
        .spawn()
        .map_err(|error| format!("cannot start external provider download: {error}"))?;
    let config = credential_config.encode()?;
    child
        .stdin
        .take()
        .ok_or_else(|| "external provider download has no configuration input".to_owned())?
        .write_all(&config)
        .map_err(|error| format!("cannot configure external provider download: {error}"))?;
    let output = child
        .wait_with_output()
        .map_err(|error| format!("cannot wait for external provider download: {error}"))?;
    if !output.status.success() {
        return Err(format!(
            "external provider download failed: {}",
            String::from_utf8_lossy(&output.stderr)
        ));
    }
    let write_out = std::str::from_utf8(&output.stdout)
        .map_err(|_| "external provider transport facts are not UTF-8".to_owned())?;
    let fields = write_out.lines().collect::<Vec<_>>();
    if fields.len() != 4
        || fields[0] != "200"
        || fields[1] != "0"
        || fields[2] != request_url
        || fields[3] != "0"
    {
        return Err(
            "external provider HTTP, redirect, effective URL, or TLS result is invalid".to_owned(),
        );
    }
    let response = external_response_headers(&read_text(headers)?)?;
    Ok(ExternalTransport {
        effective_url_sha256: sha256_bytes(fields[2].as_bytes()).hex(),
        http_status: 200,
        ssl_verify_result: 0,
        etag: response.0,
        last_modified: response.1,
        content_length: response.2,
        response_version_id: response.3,
        curl_version: external_tool_version("curl", &["--version"])?
            .lines()
            .next()
            .unwrap_or_default()
            .to_owned(),
    })
}

struct AwsSigV4Argument(String);

impl AwsSigV4Argument {
    fn new(region: &str) -> Result<Self, String> {
        validate_provider_atom(region, "external provider signing region")?;
        if region.contains(':') {
            return Err("external provider signing region contains a delimiter".to_owned());
        }
        let value = ["aws", "amz", region, "s3"].join(":");
        let fields = value.split(':').collect::<Vec<_>>();
        if fields != ["aws", "amz", region, "s3"] {
            return Err("external provider SigV4 argument is not canonical".to_owned());
        }
        Ok(Self(value))
    }

    fn as_str(&self) -> &str {
        &self.0
    }
}

struct CurlAwsCredentialConfig<'a> {
    access: &'a str,
    secret: &'a str,
    token: &'a str,
}

impl<'a> CurlAwsCredentialConfig<'a> {
    fn new(access: &'a str, secret: &'a str, token: &'a str) -> Result<Self, String> {
        for value in [access, secret, token] {
            if value.is_empty()
                || !value.is_ascii()
                || value.bytes().any(|byte| byte.is_ascii_control())
            {
                return Err("external provider credential is not a canonical token".to_owned());
            }
        }
        Ok(Self {
            access,
            secret,
            token,
        })
    }

    fn encode(&self) -> Result<Vec<u8>, String> {
        let mut encoded = Vec::new();
        encoded.extend_from_slice(b"user = \"");
        encode_curl_config_token(&mut encoded, self.access);
        encoded.push(b':');
        encode_curl_config_token(&mut encoded, self.secret);
        encoded.extend_from_slice(b"\"\nheader = \"x-amz-security-token: ");
        encode_curl_config_token(&mut encoded, self.token);
        encoded.extend_from_slice(b"\"\n");
        let decoded = decode_curl_aws_config(&encoded)?;
        if decoded
            != (
                self.access.to_owned(),
                self.secret.to_owned(),
                self.token.to_owned(),
            )
        {
            return Err("external provider credential encoding did not round trip".to_owned());
        }
        Ok(encoded)
    }
}

fn encode_curl_config_token(output: &mut Vec<u8>, value: &str) {
    for byte in value.bytes() {
        if matches!(byte, b'\\' | b'"') {
            output.push(b'\\');
        }
        output.push(byte);
    }
}

fn decode_curl_aws_config(encoded: &[u8]) -> Result<(String, String, String), String> {
    let text = std::str::from_utf8(encoded)
        .map_err(|_| "curl credential configuration is not UTF-8".to_owned())?;
    let lines = text.lines().collect::<Vec<_>>();
    if lines.len() != 2 {
        return Err("curl credential configuration has the wrong record count".to_owned());
    }
    let user = decode_curl_config_line(lines[0], "user = \"")?;
    let (access, secret) = user
        .split_once(':')
        .ok_or_else(|| "curl credential user record lacks a separator".to_owned())?;
    let token = decode_curl_config_line(lines[1], "header = \"x-amz-security-token: ")?;
    Ok((access.to_owned(), secret.to_owned(), token))
}

fn decode_curl_config_line(line: &str, prefix: &str) -> Result<String, String> {
    let escaped = line
        .strip_prefix(prefix)
        .and_then(|line| line.strip_suffix('"'))
        .ok_or_else(|| "curl credential configuration is not canonical".to_owned())?;
    let mut decoded = String::new();
    let mut bytes = escaped.bytes();
    while let Some(byte) = bytes.next() {
        if byte == b'\\' {
            let escaped = bytes
                .next()
                .filter(|escaped| matches!(escaped, b'\\' | b'"'))
                .ok_or_else(|| "curl credential configuration has an invalid escape".to_owned())?;
            decoded.push(char::from(escaped));
        } else {
            decoded.push(char::from(byte));
        }
    }
    Ok(decoded)
}

fn external_response_headers(headers: &str) -> Result<(String, String, u64, String), String> {
    let mut values = BTreeMap::new();
    for line in headers.lines() {
        if let Some((name, value)) = line.split_once(':') {
            values.insert(name.trim().to_ascii_lowercase(), value.trim().to_owned());
        }
    }
    let required = |name: &str| {
        values
            .get(name)
            .cloned()
            .ok_or_else(|| format!("external provider response lacks {name}"))
    };
    let length = required("content-length")?
        .parse::<u64>()
        .map_err(|_| "external provider content length is malformed".to_owned())?;
    Ok((
        required("etag")?,
        required("last-modified")?,
        length,
        required("x-amz-version-id")?,
    ))
}

fn external_aws_json(arguments: &[&str]) -> Result<JsonValue, String> {
    let output = Command::new("aws")
        .args(arguments)
        .args(["--output", "json", "--no-cli-pager"])
        .output()
        .map_err(|error| format!("cannot query external provider: {error}"))?;
    if !output.status.success() {
        return Err(format!(
            "external provider query failed: {}",
            String::from_utf8_lossy(&output.stderr)
        ));
    }
    parse_json(
        std::str::from_utf8(&output.stdout)
            .map_err(|_| "external provider response is not UTF-8".to_owned())?,
    )
}

fn verify_external_s3_head(
    head: &BTreeMap<String, JsonValue>,
    version: &str,
    archive: &Path,
    transport: &ExternalTransport,
) -> Result<(), String> {
    let content_length = json_member(head, "ContentLength")?.number()?;
    if json_member(head, "VersionId")?.string()? != version
        || transport.response_version_id != version
        || json_member(head, "ETag")?.string()? != transport.etag
        || json_member(head, "LastModified")?.string()? != transport.last_modified
        || content_length != transport.content_length
        || content_length != record_size(archive)?
    {
        return Err("external provider head, response, and downloaded object disagree".to_owned());
    }
    Ok(())
}

fn validate_external_identity(
    account: &str,
    principal_arn: &str,
    principal_id: &str,
) -> Result<(), String> {
    if account.is_empty()
        || !account.bytes().all(|byte| byte.is_ascii_digit())
        || principal_id.is_empty()
        || principal_id.chars().any(char::is_control)
        || !principal_arn.starts_with("arn:aws:sts::")
        || !principal_arn.contains(account)
        || !principal_arn.contains(":assumed-role/")
    {
        return Err("external provider stable principal identity is invalid".to_owned());
    }
    Ok(())
}

pub(crate) fn extract_external_zip(archive: &Path, destination: &Path) -> Result<(), String> {
    let entries = external_zip_entries(&read_regular_file(archive)?)?;
    fs::create_dir(destination)
        .map_err(|error| format!("cannot create external extraction directory: {error}"))?;
    let extraction = Command::new("unzip")
        .args(["-q"])
        .arg(archive)
        .args(["-d"])
        .arg(destination)
        .output()
        .map_err(|error| format!("cannot extract external provider archive: {error}"))?;
    if !extraction.status.success() {
        return Err(format!(
            "external provider archive extraction failed: {}",
            String::from_utf8_lossy(&extraction.stderr)
        ));
    }
    verify_external_extracted_tree(destination, &entries)
}

pub(crate) fn collection_provider_archive_tree_identity(
    bytes: &[u8],
    extracted: &Path,
) -> Result<(String, u64), String> {
    let entries = external_zip_entries(bytes)?;
    let digest = collection_archive_tree_digest(&entries, extracted)?;
    let count = u64::try_from(entries.len())
        .map_err(|_| "collection provider ZIP inventory is too large".to_owned())?;
    Ok((digest, count))
}

#[derive(Clone)]
struct ExternalZipEntry {
    path: PathBuf,
    directory: bool,
    mode: u32,
    uncompressed_size: u64,
}

fn external_zip_entries(bytes: &[u8]) -> Result<Vec<ExternalZipEntry>, String> {
    let eocd = external_zip_eocd(bytes)?;
    let entries = usize::from(zip_u16(bytes, eocd + 10)?);
    let central_size = usize::try_from(zip_u32(bytes, eocd + 12)?)
        .map_err(|_| "external ZIP central directory is too large".to_owned())?;
    let central_offset = usize::try_from(zip_u32(bytes, eocd + 16)?)
        .map_err(|_| "external ZIP central offset is too large".to_owned())?;
    if entries == 0
        || entries > 250_000
        || zip_u16(bytes, eocd + 4)? != 0
        || zip_u16(bytes, eocd + 6)? != 0
        || zip_u16(bytes, eocd + 8)? != u16::try_from(entries).unwrap_or(u16::MAX)
        || central_offset.checked_add(central_size) != Some(eocd)
    {
        return Err("external ZIP is empty, split, or has an inconsistent directory".to_owned());
    }
    parse_external_zip_central(bytes, central_offset, central_size, entries)
}

fn external_zip_eocd(bytes: &[u8]) -> Result<usize, String> {
    let minimum = 22_usize;
    if bytes.len() < minimum {
        return Err("external ZIP is truncated".to_owned());
    }
    let start = bytes.len().saturating_sub(usize::from(u16::MAX) + minimum);
    let position = (start..=bytes.len() - 4)
        .rev()
        .find(|offset| bytes[*offset..*offset + 4] == [0x50, 0x4b, 0x05, 0x06])
        .ok_or_else(|| "external ZIP lacks its end record".to_owned())?;
    let comment = usize::from(zip_u16(bytes, position + 20)?);
    if position
        .checked_add(minimum)
        .and_then(|end| end.checked_add(comment))
        != Some(bytes.len())
    {
        return Err("external ZIP has trailing or malformed end-record bytes".to_owned());
    }
    Ok(position)
}

fn parse_external_zip_central(
    bytes: &[u8],
    offset: usize,
    size: usize,
    count: usize,
) -> Result<Vec<ExternalZipEntry>, String> {
    let end = offset
        .checked_add(size)
        .ok_or_else(|| "external ZIP central directory overflows".to_owned())?;
    let mut cursor = offset;
    let mut entries = Vec::new();
    let mut paths = BTreeSet::new();
    let mut folded_paths = BTreeSet::new();
    let mut local_offsets = BTreeSet::new();
    let mut uncompressed_bytes = 0_u64;
    for _ in 0..count {
        let (entry, next, local_offset) = external_zip_entry(bytes, cursor)?;
        let folded = entry
            .path
            .to_str()
            .ok_or_else(|| "external ZIP path is not UTF-8".to_owned())?
            .to_ascii_lowercase();
        uncompressed_bytes = uncompressed_bytes
            .checked_add(entry.uncompressed_size)
            .ok_or_else(|| "external ZIP expanded size overflows".to_owned())?;
        if next > end
            || !paths.insert(entry.path.clone())
            || !folded_paths.insert(folded)
            || !local_offsets.insert(local_offset)
            || uncompressed_bytes > 8 * 1024 * 1024 * 1024
        {
            return Err("external ZIP duplicates a path or local entry".to_owned());
        }
        entries.push(entry);
        cursor = next;
    }
    if cursor != end
        || entries
            .iter()
            .any(|entry| external_zip_path_collides(entry, &entries))
    {
        return Err("external ZIP has a path collision or trailing central bytes".to_owned());
    }
    Ok(entries)
}

fn external_zip_entry(
    bytes: &[u8],
    offset: usize,
) -> Result<(ExternalZipEntry, usize, usize), String> {
    if zip_u32(bytes, offset)? != 0x0201_4b50 {
        return Err("external ZIP central entry signature is invalid".to_owned());
    }
    let flags = zip_u16(bytes, offset + 8)?;
    let compression = zip_u16(bytes, offset + 10)?;
    if flags & 1 != 0 || !matches!(compression, 0 | 8) {
        return Err("external ZIP encrypted entries are forbidden".to_owned());
    }
    let name_length = usize::from(zip_u16(bytes, offset + 28)?);
    let extra_length = usize::from(zip_u16(bytes, offset + 30)?);
    let comment_length = usize::from(zip_u16(bytes, offset + 32)?);
    let name_start = offset + 46;
    let name_end = name_start
        .checked_add(name_length)
        .ok_or_else(|| "external ZIP filename overflows".to_owned())?;
    let name = std::str::from_utf8(
        bytes
            .get(name_start..name_end)
            .ok_or_else(|| "external ZIP filename is truncated".to_owned())?,
    )
    .map_err(|_| "external ZIP filename is not UTF-8".to_owned())?;
    let path = safe_external_zip_path(name)?;
    let uncompressed_size = u64::from(zip_u32(bytes, offset + 24)?);
    let (directory, mode) = external_zip_entry_kind(bytes, offset, name)?;
    verify_external_zip_local_entry(bytes, offset, name.as_bytes())?;
    let next = name_end
        .checked_add(extra_length)
        .and_then(|value| value.checked_add(comment_length))
        .ok_or_else(|| "external ZIP central entry overflows".to_owned())?;
    let local_offset = usize::try_from(zip_u32(bytes, offset + 42)?)
        .map_err(|_| "external ZIP local offset is too large".to_owned())?;
    Ok((
        ExternalZipEntry {
            path,
            directory,
            mode,
            uncompressed_size,
        },
        next,
        local_offset,
    ))
}

fn safe_external_zip_path(name: &str) -> Result<PathBuf, String> {
    let path = Path::new(name);
    if name.is_empty()
        || name.contains('\\')
        || !name.is_ascii()
        || name.bytes().any(|byte| {
            !(byte.is_ascii_alphanumeric() || matches!(byte, b'.' | b'_' | b'-' | b'/'))
        })
        || path.is_absolute()
        || path.components().any(|component| {
            !matches!(component, std::path::Component::Normal(_))
                || component.as_os_str().to_str().is_none_or(str::is_empty)
        })
    {
        return Err("external ZIP contains an unsafe path".to_owned());
    }
    Ok(path.to_path_buf())
}

fn external_zip_entry_kind(bytes: &[u8], offset: usize, name: &str) -> Result<(bool, u32), String> {
    let made_by = *bytes
        .get(offset + 5)
        .ok_or_else(|| "external ZIP central entry is truncated".to_owned())?;
    let attributes = zip_u32(bytes, offset + 38)?;
    let directory = name.ends_with('/');
    if made_by == 3 {
        let file_type = (attributes >> 16) & 0o170_000;
        if !matches!(
            (file_type, directory),
            (0o040_000, true) | (0o100_000, false)
        ) {
            return Err("external ZIP contains a symlink or special Unix entry".to_owned());
        }
    } else if (attributes & 0x10 != 0) != directory {
        return Err("external ZIP entry type and path disagree".to_owned());
    }
    Ok((directory, attributes >> 16))
}

pub(crate) fn verify_collection_provider_archive(
    archive: &Path,
    retained_tree: &Path,
    expected_tree_sha256: &str,
    expected_inventory_count: u64,
) -> Result<(), String> {
    let archive_bytes = read_regular_file(archive)?;
    let entries = external_zip_entries(&archive_bytes)?;
    if u64::try_from(entries.len()).ok() != Some(expected_inventory_count) {
        return Err("collection provider ZIP inventory count differs from selection".to_owned());
    }
    let temporary = create_private_temp_directory("hell-collection-provider-archive")?;
    let extracted = temporary.join("extracted");
    extract_external_zip(archive, &extracted)?;
    let result =
        verify_collection_archive_tree(&entries, &extracted, retained_tree, expected_tree_sha256);
    fs::remove_dir_all(&temporary)
        .map_err(|error| format!("cannot clean collection ZIP replay: {error}"))?;
    result
}

fn verify_collection_archive_tree(
    entries: &[ExternalZipEntry],
    extracted: &Path,
    retained_tree: &Path,
    expected_tree_sha256: &str,
) -> Result<(), String> {
    if record_digest(extracted)? != record_digest(retained_tree)? {
        return Err("collection provider ZIP replay differs from retained tree".to_owned());
    }
    if collection_archive_tree_digest(entries, extracted)? != expected_tree_sha256 {
        return Err("collection provider ZIP tree digest differs from selection".to_owned());
    }
    Ok(())
}

fn collection_archive_tree_digest(
    entries: &[ExternalZipEntry],
    extracted: &Path,
) -> Result<String, String> {
    let mut inventory = Vec::with_capacity(entries.len());
    for entry in entries {
        let path = entry
            .path
            .to_str()
            .ok_or_else(|| "collection provider ZIP path is not UTF-8".to_owned())?;
        let canonical_path = if entry.directory {
            format!("{path}/")
        } else {
            path.to_owned()
        };
        let mode = match (entry.directory, entry.mode) {
            (true, 0o040_755) => "040755",
            (false, 0o100_644) => "100644",
            (false, 0o100_755) => "100755",
            _ => return Err("collection provider ZIP entry mode is not reviewed".to_owned()),
        };
        let mut fields = BTreeMap::from([
            ("mode".to_owned(), JsonValue::String(mode.to_owned())),
            ("path".to_owned(), JsonValue::String(canonical_path)),
            (
                "type".to_owned(),
                JsonValue::String(if entry.directory { "directory" } else { "file" }.to_owned()),
            ),
        ]);
        if !entry.directory {
            let bytes = read_regular_file(&extracted.join(&entry.path))?;
            fields.insert(
                "sha256".to_owned(),
                JsonValue::String(sha256_bytes(&bytes).hex()),
            );
            fields.insert("size".to_owned(), JsonValue::Number(bytes.len() as u64));
        }
        inventory.push(JsonValue::Object(fields));
    }
    inventory.sort_by(|left, right| {
        json_member(left.object().expect("inventory entry"), "path")
            .and_then(JsonValue::string)
            .expect("inventory path")
            .as_bytes()
            .cmp(
                json_member(right.object().expect("inventory entry"), "path")
                    .and_then(JsonValue::string)
                    .expect("inventory path")
                    .as_bytes(),
            )
    });
    Ok(sha256_bytes(&canonical_json_bytes(&JsonValue::Array(inventory))?).hex())
}

fn verify_external_zip_local_entry(
    bytes: &[u8],
    central_offset: usize,
    expected_name: &[u8],
) -> Result<(), String> {
    let local_offset = usize::try_from(zip_u32(bytes, central_offset + 42)?)
        .map_err(|_| "external ZIP local offset is too large".to_owned())?;
    if zip_u32(bytes, local_offset)? != 0x0403_4b50 {
        return Err("external ZIP local entry signature is invalid".to_owned());
    }
    let name_length = usize::from(zip_u16(bytes, local_offset + 26)?);
    let name_start = local_offset + 30;
    let local_name = bytes
        .get(name_start..name_start.saturating_add(name_length))
        .ok_or_else(|| "external ZIP local filename is truncated".to_owned())?;
    if local_name != expected_name {
        return Err("external ZIP local and central filenames disagree".to_owned());
    }
    Ok(())
}

fn external_zip_path_collides(entry: &ExternalZipEntry, entries: &[ExternalZipEntry]) -> bool {
    !entry.directory
        && entries
            .iter()
            .any(|other| other.path != entry.path && other.path.starts_with(&entry.path))
}

fn verify_external_extracted_tree(
    directory: &Path,
    entries: &[ExternalZipEntry],
) -> Result<(), String> {
    let expected = entries
        .iter()
        .filter(|entry| !entry.directory)
        .map(|entry| entry.path.clone())
        .collect::<BTreeSet<_>>();
    let mut observed = BTreeSet::new();
    collect_external_extracted_files(directory, directory, &mut observed)?;
    if expected != observed {
        return Err("external ZIP extracted tree differs from its central inventory".to_owned());
    }
    Ok(())
}

fn collect_external_extracted_files(
    root: &Path,
    directory: &Path,
    files: &mut BTreeSet<PathBuf>,
) -> Result<(), String> {
    let mut entries = fs::read_dir(directory)
        .map_err(|error| format!("cannot enumerate external ZIP output: {error}"))?
        .collect::<Result<Vec<_>, _>>()
        .map_err(|error| format!("cannot enumerate external ZIP output: {error}"))?;
    entries.sort_by_key(std::fs::DirEntry::file_name);
    for entry in entries {
        let path = entry.path();
        let metadata = fs::symlink_metadata(&path)
            .map_err(|error| format!("cannot inspect external ZIP output: {error}"))?;
        if metadata.file_type().is_symlink() || !(metadata.is_file() || metadata.is_dir()) {
            return Err("external ZIP extraction produced a link or special file".to_owned());
        }
        if metadata.is_dir() {
            collect_external_extracted_files(root, &path, files)?;
        } else {
            files.insert(
                path.strip_prefix(root)
                    .map_err(|_| "external ZIP output escapes its root".to_owned())?
                    .to_path_buf(),
            );
        }
    }
    Ok(())
}

fn zip_u16(bytes: &[u8], offset: usize) -> Result<u16, String> {
    let raw: [u8; 2] = bytes
        .get(offset..offset.saturating_add(2))
        .ok_or_else(|| "external ZIP integer is truncated".to_owned())?
        .try_into()
        .map_err(|_| "external ZIP integer width is invalid".to_owned())?;
    Ok(u16::from_le_bytes(raw))
}

fn zip_u32(bytes: &[u8], offset: usize) -> Result<u32, String> {
    let raw: [u8; 4] = bytes
        .get(offset..offset.saturating_add(4))
        .ok_or_else(|| "external ZIP integer is truncated".to_owned())?
        .try_into()
        .map_err(|_| "external ZIP integer width is invalid".to_owned())?;
    Ok(u32::from_le_bytes(raw))
}

fn external_tool_version(program: &str, arguments: &[&str]) -> Result<String, String> {
    let output = Command::new(program)
        .args(arguments)
        .output()
        .map_err(|error| format!("cannot inspect external acquisition tool {program}: {error}"))?;
    if !output.status.success() {
        return Err(format!(
            "external acquisition tool {program} is unavailable"
        ));
    }
    String::from_utf8(output.stdout)
        .map(|value| value.trim().to_owned())
        .map_err(|_| format!("external acquisition tool {program} version is not UTF-8"))
}

struct ExternalAcquisitionDocument<'a> {
    bucket: &'a str,
    key: &'a str,
    version: &'a str,
    region: &'a str,
    request_url: &'a str,
    archive_sha256: &'a str,
    archive_size: u64,
    extracted_sha256: &'a str,
    headers_sha256: &'a str,
    tls_sha256: &'a str,
    tls: &'a BTreeMap<String, JsonValue>,
    transport: &'a ExternalTransport,
    account: &'a str,
    principal_arn: &'a str,
    principal_id: &'a str,
    actor_id: u64,
    actor_login: &'a str,
}

fn external_acquisition_document(
    document: &ExternalAcquisitionDocument<'_>,
) -> Result<JsonValue, String> {
    let mut fields = external_acquisition_transport_fields(document)?;
    fields.extend(external_acquisition_identity_fields(document)?);
    Ok(JsonValue::Object(fields))
}

fn external_acquisition_transport_fields(
    document: &ExternalAcquisitionDocument<'_>,
) -> Result<BTreeMap<String, JsonValue>, String> {
    let mut fields = BTreeMap::from([
        ("schemaVersion".to_owned(), JsonValue::Number(1)),
        (
            "provider".to_owned(),
            JsonValue::String("aws-s3".to_owned()),
        ),
        (
            "bucket".to_owned(),
            JsonValue::String(document.bucket.to_owned()),
        ),
        ("key".to_owned(), JsonValue::String(document.key.to_owned())),
        (
            "versionId".to_owned(),
            JsonValue::String(document.version.to_owned()),
        ),
        (
            "region".to_owned(),
            JsonValue::String(document.region.to_owned()),
        ),
        (
            "requestUrl".to_owned(),
            JsonValue::String(document.request_url.to_owned()),
        ),
        (
            "requestUrlSha256".to_owned(),
            JsonValue::String(sha256_bytes(document.request_url.as_bytes()).hex()),
        ),
        (
            "effectiveUrlSha256".to_owned(),
            JsonValue::String(document.transport.effective_url_sha256.clone()),
        ),
        (
            "httpStatus".to_owned(),
            JsonValue::Number(document.transport.http_status),
        ),
        (
            "redirectHosts".to_owned(),
            JsonValue::Array(vec![JsonValue::String(format!(
                "{}.s3.{}.amazonaws.com",
                document.bucket, document.region
            ))]),
        ),
        (
            "sslVerifyResult".to_owned(),
            JsonValue::Number(document.transport.ssl_verify_result),
        ),
        (
            "etag".to_owned(),
            JsonValue::String(document.transport.etag.clone()),
        ),
        (
            "lastModified".to_owned(),
            JsonValue::String(document.transport.last_modified.clone()),
        ),
        (
            "contentLength".to_owned(),
            JsonValue::Number(document.transport.content_length),
        ),
        (
            "responseVersionId".to_owned(),
            JsonValue::String(document.transport.response_version_id.clone()),
        ),
        (
            "archivePath".to_owned(),
            JsonValue::String("external-provider-object.zip".to_owned()),
        ),
        (
            "archiveSha256".to_owned(),
            JsonValue::String(document.archive_sha256.to_owned()),
        ),
        (
            "archiveSize".to_owned(),
            JsonValue::Number(document.archive_size),
        ),
        (
            "extractedPath".to_owned(),
            JsonValue::String("independent".to_owned()),
        ),
        (
            "extractedSha256".to_owned(),
            JsonValue::String(document.extracted_sha256.to_owned()),
        ),
        (
            "responseHeadersPath".to_owned(),
            JsonValue::String("external-provider-headers.txt".to_owned()),
        ),
        (
            "responseHeadersSha256".to_owned(),
            JsonValue::String(document.headers_sha256.to_owned()),
        ),
    ]);
    fields.extend(external_acquisition_tls_fields(document)?);
    Ok(fields)
}

fn external_acquisition_tls_fields(
    document: &ExternalAcquisitionDocument<'_>,
) -> Result<BTreeMap<String, JsonValue>, String> {
    Ok(BTreeMap::from([
        (
            "tlsEvidencePath".to_owned(),
            JsonValue::String("external-provider-tls.json".to_owned()),
        ),
        (
            "tlsEvidenceSha256".to_owned(),
            JsonValue::String(document.tls_sha256.to_owned()),
        ),
        (
            "tlsHost".to_owned(),
            json_member(document.tls, "host")?.clone(),
        ),
        (
            "tlsSubject".to_owned(),
            json_member(document.tls, "subject")?.clone(),
        ),
        (
            "tlsIssuer".to_owned(),
            json_member(document.tls, "issuer")?.clone(),
        ),
        (
            "tlsCertificateSha256".to_owned(),
            json_member(document.tls, "certificateSha256")?.clone(),
        ),
        (
            "tlsSpkiSha256".to_owned(),
            json_member(document.tls, "spkiSha256")?.clone(),
        ),
    ]))
}

fn external_acquisition_identity_fields(
    document: &ExternalAcquisitionDocument<'_>,
) -> Result<BTreeMap<String, JsonValue>, String> {
    Ok(BTreeMap::from([
        (
            "providerAccountId".to_owned(),
            JsonValue::String(document.account.to_owned()),
        ),
        (
            "providerPrincipalArn".to_owned(),
            JsonValue::String(document.principal_arn.to_owned()),
        ),
        (
            "providerPrincipalId".to_owned(),
            JsonValue::String(document.principal_id.to_owned()),
        ),
        (
            "acquirerAccountId".to_owned(),
            JsonValue::Number(document.actor_id),
        ),
        (
            "acquirerLogin".to_owned(),
            JsonValue::String(document.actor_login.to_owned()),
        ),
        (
            "repositoryId".to_owned(),
            JsonValue::Number(environment_u64(
                "GITHUB_REPOSITORY_ID",
                "external acquisition repository",
            )?),
        ),
        (
            "runId".to_owned(),
            JsonValue::Number(environment_u64(
                "GITHUB_RUN_ID",
                "external acquisition run",
            )?),
        ),
        (
            "runAttempt".to_owned(),
            JsonValue::Number(environment_u64(
                "GITHUB_RUN_ATTEMPT",
                "external acquisition attempt",
            )?),
        ),
        (
            "workflowRef".to_owned(),
            JsonValue::String(required_environment("GITHUB_WORKFLOW_REF")?),
        ),
        (
            "acquiredAt".to_owned(),
            JsonValue::String(crate::custody_ops::current_utc_timestamp()?),
        ),
        (
            "curlVersion".to_owned(),
            JsonValue::String(document.transport.curl_version.clone()),
        ),
        (
            "awsCliVersion".to_owned(),
            JsonValue::String(external_tool_version("aws", &["--version"])?),
        ),
    ]))
}

fn external_acquisition_identity(directory: &Path) -> Result<ExternalAcquisitionIdentity, String> {
    let path = directory.join("external-acquisition.json");
    let document = parse_json(&read_text(&path)?)?;
    let document = document.object()?;
    if json_member(document, "schemaVersion")?.number()? != 1
        || json_member(document, "provider")?.string()? != "aws-s3"
    {
        return Err("external acquisition evidence has an unsupported identity".to_owned());
    }
    let account = json_member(document, "providerAccountId")?.string()?;
    let actor_id = json_member(document, "acquirerAccountId")?.number()?;
    if actor_id == 0 || account.is_empty() {
        return Err("external acquisition evidence lacks stable identities".to_owned());
    }
    Ok(ExternalAcquisitionIdentity {
        path: PathBuf::from("external-acquisition.json"),
        sha256: record_digest(&path)?,
        trust_domain: format!("aws-s3-account:{account}"),
        stable_acquirer: format!("github-account:{actor_id}"),
        repository_id: json_member(document, "repositoryId")?.number()?,
        run_id: json_member(document, "runId")?.number()?,
        run_attempt: json_member(document, "runAttempt")?.number()?,
        workflow_ref: json_member(document, "workflowRef")?.string()?.to_owned(),
        acquired_at: json_member(document, "acquiredAt")?.string()?.to_owned(),
    })
}

struct AcquisitionChannel {
    class: &'static str,
    trust_domain: String,
    acquirer: String,
    account_id: u64,
    login: String,
    tool: &'static str,
    external: Option<ExternalAcquisitionIdentity>,
}

fn acquisition_channel(
    output: &Path,
    primary: bool,
    independent: bool,
) -> Result<AcquisitionChannel, String> {
    let login = std::env::var("GITHUB_ACTOR")
        .map_err(|_| "artifact acquisition requires GITHUB_ACTOR".to_owned())?;
    validate_provider_atom(&login, "artifact acquirer login")?;
    let account_id = environment_u64("GITHUB_ACTOR_ID", "artifact acquirer account")?;
    let external = if independent {
        Some(external_acquisition_identity(output.parent().ok_or_else(
            || "independent acquisition output has no directory".to_owned(),
        )?)?)
    } else {
        None
    };
    if primary {
        Ok(AcquisitionChannel {
            class: "github-actions-api",
            trust_domain: "github.com".to_owned(),
            acquirer: format!("github-account:{account_id}"),
            account_id,
            login,
            tool: "actions/download-artifact@70fc10c6e5e1ce46ad2ea6f2b72d43f7d47b13c3",
            external,
        })
    } else if let Some(facts) = external {
        Ok(AcquisitionChannel {
            class: "external-versioned-object",
            trust_domain: facts.trust_domain.clone(),
            acquirer: facts.stable_acquirer.clone(),
            account_id,
            login,
            tool: "curl-aws-sigv4-v1",
            external: Some(facts),
        })
    } else {
        Err("artifact acquisition action must be primary or independent".to_owned())
    }
}

fn acquisition_receipt(
    root: &Path,
    input: &Path,
    output: &Path,
    artifact: &str,
    primary: bool,
    independent: bool,
    dispatch: Option<&AcquisitionDispatch>,
) -> Result<AcquisitionReceipt, String> {
    let dispatch =
        dispatch.ok_or_else(|| "dispatch-bound acquisition lacks dispatch identity".to_owned())?;
    let workflow = repository_relative_path(root, &dispatch.workflow_path)?;
    let workflow_bytes = read_regular_file(&workflow)?;
    let repository_id = std::env::var("GITHUB_REPOSITORY_ID")
        .map_err(|_| "artifact acquisition requires immutable GITHUB_REPOSITORY_ID".to_owned())?;
    let run_id = acquisition_u64(Some(dispatch.run_id.as_str()), "GITHUB_RUN_ID")?;
    let run_attempt = acquisition_u64(Some(dispatch.run_attempt.as_str()), "GITHUB_RUN_ATTEMPT")?;
    let acquisition_run_id = environment_u64("GITHUB_RUN_ID", "artifact acquisition run")?;
    let acquisition_run_attempt =
        environment_u64("GITHUB_RUN_ATTEMPT", "artifact acquisition attempt")?;
    let acquisition_workflow_ref = required_environment("GITHUB_WORKFLOW_REF")?;
    let provider_artifact_id = acquisition_u64(
        Some(dispatch.provider_artifact_id.to_string()).as_deref(),
        "HELL_PROVIDER_ARTIFACT_ID",
    )?;
    let channel = acquisition_channel(output, primary, independent)?;
    let acquired_at = channel.external.as_ref().map_or_else(
        || dispatch.acquired_at.clone(),
        |facts| facts.acquired_at.clone(),
    );
    if let Some(facts) = channel.external.as_ref()
        && (facts.repository_id.to_string() != repository_id
            || facts.run_id != acquisition_run_id
            || facts.run_attempt != acquisition_run_attempt
            || facts.workflow_ref != acquisition_workflow_ref)
    {
        return Err("external acquisition execution identity is inconsistent".to_owned());
    }
    let provider_metadata_sha256 = acquire_provider_metadata(
        output
            .parent()
            .ok_or_else(|| "acquisition receipt output has no directory".to_owned())?,
        dispatch,
        artifact,
        &repository_id,
        primary,
    )?;
    Ok(AcquisitionReceipt {
        artifact: artifact.to_owned(),
        provider_artifact_id,
        provider_metadata_sha256,
        local_path: input
            .strip_prefix(
                output
                    .parent()
                    .ok_or_else(|| "acquisition receipt output has no directory".to_owned())?,
            )
            .map_err(|_| "acquired bytes are outside the receipt package".to_owned())?
            .to_path_buf(),
        observed_sha256: record_digest(input)?,
        observed_size: record_size(input)?,
        repository_id,
        workflow_path: dispatch.workflow_path.clone(),
        workflow_sha256: sha256_bytes(&workflow_bytes).hex(),
        run_id,
        run_attempt,
        acquisition_run_id,
        acquisition_run_attempt,
        acquisition_workflow_ref,
        candidate_commit: git_output(root, &["rev-parse", "HEAD"])?.trim().to_owned(),
        trust_domain: channel.trust_domain,
        channel_class: channel.class.to_owned(),
        acquirer: channel.acquirer,
        acquirer_account_id: channel.account_id,
        acquirer_login: channel.login,
        acquired_at,
        acquisition_event: "workflow_dispatch".to_owned(),
        provider_event: dispatch.provider_event.clone(),
        acquisition_platform: format!(
            "{}-{}",
            std::env::var("RUNNER_OS")
                .map_err(|_| "artifact acquisition requires RUNNER_OS".to_owned())?,
            std::env::var("RUNNER_ARCH")
                .map_err(|_| "artifact acquisition requires RUNNER_ARCH".to_owned())?,
        ),
        acquisition_tool: channel.tool.to_owned(),
        trust_review_ref: "REVIEW_REQUIRED".to_owned(),
        external_acquisition_path: channel
            .external
            .as_ref()
            .map(|external| external.path.clone()),
        external_acquisition_sha256: channel
            .external
            .as_ref()
            .map(|external| external.sha256.clone()),
    })
}

fn acquisition_u64(dispatch: Option<&str>, environment: &str) -> Result<u64, String> {
    let value = match dispatch {
        Some(value) => value.to_owned(),
        None => std::env::var(environment)
            .map_err(|_| format!("artifact acquisition requires {environment}"))?,
    };
    let value = value
        .parse::<u64>()
        .map_err(|_| format!("artifact acquisition {environment} is not an integer"))?;
    if value == 0 {
        return Err(format!(
            "artifact acquisition {environment} must be nonzero"
        ));
    }
    Ok(value)
}

fn copy_record_tree(source: &Path, destination: &Path) -> Result<(), String> {
    let metadata = fs::symlink_metadata(source).map_err(|error| {
        format!(
            "cannot inspect acquisition source {}: {error}",
            source.display()
        )
    })?;
    if metadata.file_type().is_symlink() {
        return Err("independent acquisition source must not be a symlink".to_owned());
    }
    if metadata.is_file() {
        let parent = destination
            .parent()
            .ok_or_else(|| "independent acquisition destination has no directory".to_owned())?;
        fs::create_dir_all(parent)
            .map_err(|error| format!("cannot create independent acquisition directory: {error}"))?;
        let bytes = read_regular_file(source)?;
        let mut file = fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(destination)
            .map_err(|error| format!("cannot create independent acquisition copy: {error}"))?;
        file.write_all(&bytes)
            .map_err(|error| format!("cannot write independent acquisition copy: {error}"))?;
        file.sync_all()
            .map_err(|error| format!("cannot sync independent acquisition copy: {error}"))?;
        return Ok(());
    }
    if !metadata.is_dir() {
        return Err("independent acquisition source is not a regular file or directory".to_owned());
    }
    fs::create_dir(destination)
        .map_err(|error| format!("cannot create independent acquisition root: {error}"))?;
    let mut entries = fs::read_dir(source)
        .map_err(|error| format!("cannot enumerate acquisition source: {error}"))?
        .collect::<Result<Vec<_>, _>>()
        .map_err(|error| format!("cannot enumerate acquisition source: {error}"))?;
    entries.sort_by_key(std::fs::DirEntry::file_name);
    for entry in entries {
        copy_record_tree(&entry.path(), &destination.join(entry.file_name()))?;
    }
    Ok(())
}

fn artifact_receipt_attest(options: &Options) -> Result<String, String> {
    let input = required_path(
        &options.input,
        "artifact receipt attestation requires --input receipt",
    )?;
    let output = required_path(
        &options.output,
        "artifact receipt attestation requires --output envelope",
    )?;
    let role = match options.action.as_deref() {
        Some("attest-primary") => "artifact-primary-producer",
        Some("attest-independent") => "artifact-independent-acquirer",
        _ => return Err("unknown artifact receipt attestation action".to_owned()),
    };
    let receipt = parse_acquisition_receipt_state(input, true)?;
    validate_utc_timestamp(&receipt.acquired_at)?;
    let payload = format!(
        "{{\"schemaVersion\":2,\"role\":{},\"candidateCommit\":{},\"receiptCoreSha256\":{},\"artifactSha256\":{},\"acquiredAt\":{}}}\n",
        json_string(role),
        json_string(&receipt.candidate_commit),
        json_string(&acquisition_receipt_core_digest(&receipt)),
        json_string(&receipt.observed_sha256),
        json_string(&receipt.acquired_at),
    );
    let temporary = create_private_temp_directory("hell-artifact-receipt-attest")?;
    let payload_path = temporary.join("payload.json");
    write_new_file(&payload_path, payload.as_bytes())?;
    let result = sigstore_review_signature(&temporary, &payload_path);
    let cleanup = fs::remove_dir_all(&temporary)
        .map_err(|error| format!("cannot remove receipt attestation directory: {error}"));
    let (bundle, identity, issuer) = match (result, cleanup) {
        (Ok(value), Ok(())) => value,
        (Err(error), _) | (_, Err(error)) => return Err(error),
    };
    let envelope = format!(
        "{{\n  \"payloadType\": \"application/vnd.hell-rs.artifact-receipt+json\",\n  \"payload\": {},\n  \"signatures\": [{{\"scheme\": \"sigstore\", \"bundle\": {}, \"certificateIdentity\": {}, \"certificateIssuer\": {}}}]\n}}\n",
        json_string(&encode_base64(payload.as_bytes())),
        json_string(&encode_base64(&bundle)),
        json_string(&identity),
        json_string(&issuer),
    );
    write_atomic(output, envelope.as_bytes())?;
    Ok(format!(
        "signed {role} receipt attestation {}",
        output.display()
    ))
}

pub(crate) fn sign_linux_release_acquisition(
    artifact: &Path,
    provider_response: &Path,
    receipt: &Path,
    output: &Path,
) -> Result<(), String> {
    let identity = crate::release_oracle::verify_acquisition(artifact, provider_response, receipt)?;
    let receipt_document = parse_json(&read_text(receipt)?)?;
    let receipt_document = receipt_document.object()?;
    let payload = linux_release_acquisition_payload(receipt_document, &identity)?;
    let temporary = create_private_temp_directory("hell-release-oracle-attest")?;
    let payload_path = temporary.join("payload.json");
    write_new_file(&payload_path, payload.as_bytes())?;
    let result = sigstore_review_signature(&temporary, &payload_path);
    let cleanup = fs::remove_dir_all(&temporary)
        .map_err(|error| format!("cannot remove release attestation directory: {error}"));
    let (bundle, certificate_identity, issuer) = match (result, cleanup) {
        (Ok(value), Ok(())) => value,
        (Err(error), _) | (_, Err(error)) => return Err(error),
    };
    let envelope = format!(
        "{{\n  \"payloadType\": \"application/vnd.hell-rs.release-oracle-acquisition+json\",\n  \"payload\": {},\n  \"signatures\": [{{\"scheme\": \"sigstore\", \"bundle\": {}, \"certificateIdentity\": {}, \"certificateIssuer\": {}}}]\n}}\n",
        json_string(&encode_base64(payload.as_bytes())),
        json_string(&encode_base64(&bundle)),
        json_string(&certificate_identity),
        json_string(&issuer),
    );
    write_atomic(output, envelope.as_bytes())
}

pub(crate) fn verify_linux_release_acquisition(
    artifact: &Path,
    provider_response: &Path,
    receipt: &Path,
    envelope_path: &Path,
) -> Result<crate::release_oracle::AcquisitionIdentity, String> {
    let identity = crate::release_oracle::verify_acquisition(artifact, provider_response, receipt)?;
    let receipt_document = parse_json(&read_text(receipt)?)?;
    let expected_payload =
        linux_release_acquisition_payload(receipt_document.object()?, &identity)?;
    let envelope = parse_json(&read_text(envelope_path)?)?;
    let envelope = envelope.object()?;
    exact_keys(envelope, &["payload", "payloadType", "signatures"])?;
    if json_member(envelope, "payloadType")?.string()?
        != "application/vnd.hell-rs.release-oracle-acquisition+json"
    {
        return Err("Linux release acquisition payload type is invalid".to_owned());
    }
    let payload = decode_base64(json_member(envelope, "payload")?.string()?)?;
    if payload != expected_payload.as_bytes() {
        return Err(
            "Linux release acquisition signature does not bind the exact receipt".to_owned(),
        );
    }
    let signatures = json_member(envelope, "signatures")?.array()?;
    if signatures.len() != 1 {
        return Err("Linux release acquisition requires exactly one Sigstore signature".to_owned());
    }
    let signature = signatures[0].object()?;
    exact_keys(
        signature,
        &[
            "bundle",
            "certificateIdentity",
            "certificateIssuer",
            "scheme",
        ],
    )?;
    if json_member(signature, "scheme")?.string()? != "sigstore" {
        return Err("Linux release acquisition signature scheme is invalid".to_owned());
    }
    let policy = Path::new("compat").join("reviews.allowed_signers");
    verify_sigstore_signature(&policy, signature, &payload)?;
    Ok(identity)
}

fn linux_release_acquisition_payload(
    receipt: &BTreeMap<String, JsonValue>,
    identity: &crate::release_oracle::AcquisitionIdentity,
) -> Result<String, String> {
    let string = |field: &str| -> Result<JsonValue, String> {
        Ok(JsonValue::String(
            json_member(receipt, field)?.string()?.to_owned(),
        ))
    };
    let number = |field: &str| -> Result<JsonValue, String> {
        Ok(JsonValue::Number(json_member(receipt, field)?.number()?))
    };
    let workflow_ref = json_member(receipt, "workflowRef")?.string()?;
    let role = linux_release_acquisition_role(workflow_ref)?;
    let document = JsonValue::Object(BTreeMap::from([
        ("schemaVersion".to_owned(), JsonValue::Number(1)),
        ("role".to_owned(), JsonValue::String(role.to_owned())),
        (
            "receiptId".to_owned(),
            JsonValue::String(identity.receipt_id.clone()),
        ),
        (
            "receiptSha256".to_owned(),
            JsonValue::String(identity.receipt_sha256.hex()),
        ),
        ("artifactSha256".to_owned(), string("observedSha256")?),
        ("acquiredAt".to_owned(), string("acquiredAt")?),
        ("acquirerActorId".to_owned(), number("acquirerActorId")?),
        ("repositoryId".to_owned(), number("repositoryId")?),
        ("runId".to_owned(), number("runId")?),
        ("runAttempt".to_owned(), number("runAttempt")?),
        ("workflowRef".to_owned(), string("workflowRef")?),
    ]));
    String::from_utf8(canonical_json_bytes(&document)?)
        .map_err(|_| "release acquisition payload is not UTF-8".to_owned())
}

fn linux_release_acquisition_role(workflow_ref: &str) -> Result<&'static str, String> {
    match workflow_ref {
        "Portfoligno/hell-rs/.github/workflows/nightly.yml@refs/heads/main" => {
            Ok("linux-release-acquirer")
        }
        "Portfoligno/hell-rs/.github/workflows/collection-authority.yml@refs/heads/main" => {
            Ok("collection-linux-release-acquirer")
        }
        _ => Err("Linux release acquisition workflow is not an exact trusted domain".to_owned()),
    }
}

fn write_new_file(path: &Path, bytes: &[u8]) -> Result<(), String> {
    let mut file = fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(path)
        .map_err(|error| format!("cannot create {}: {error}", path.display()))?;
    file.write_all(bytes)
        .map_err(|error| format!("cannot write {}: {error}", path.display()))?;
    file.sync_all()
        .map_err(|error| format!("cannot sync {}: {error}", path.display()))
}

fn verify_artifact_receipt_attestation(
    path: &Path,
    policy: &Path,
    receipt: &AcquisitionReceipt,
    role: &str,
    workflow: &str,
) -> Result<VerifiedArtifactAttestation, String> {
    let document = parse_json(&read_text(path)?)?;
    let envelope = document.object()?;
    exact_keys(envelope, &["payload", "payloadType", "signatures"])?;
    if json_member(envelope, "payloadType")?.string()?
        != "application/vnd.hell-rs.artifact-receipt+json"
    {
        return Err("artifact receipt attestation payload type is invalid".to_owned());
    }
    let payload = decode_base64(json_member(envelope, "payload")?.string()?)?;
    let payload_text = std::str::from_utf8(&payload)
        .map_err(|_| "artifact receipt attestation payload is not UTF-8".to_owned())?;
    let parsed = parse_json(payload_text)?;
    let object = parsed.object()?;
    exact_keys(
        object,
        &[
            "acquiredAt",
            "artifactSha256",
            "candidateCommit",
            "receiptCoreSha256",
            "role",
            "schemaVersion",
        ],
    )?;
    if json_member(object, "schemaVersion")?.number()? != 2
        || json_member(object, "role")?.string()? != role
        || json_member(object, "candidateCommit")?.string()? != receipt.candidate_commit
        || json_member(object, "receiptCoreSha256")?.string()?
            != acquisition_receipt_core_digest(receipt)
        || json_member(object, "artifactSha256")?.string()? != receipt.observed_sha256
        || json_member(object, "acquiredAt")?.string()? != receipt.acquired_at
    {
        return Err("artifact receipt attestation does not bind the receipt core".to_owned());
    }
    validate_utc_timestamp(&receipt.acquired_at)?;
    let signatures = json_member(envelope, "signatures")?.array()?;
    if signatures.len() != 1 {
        return Err("artifact receipt attestation requires exactly one signature".to_owned());
    }
    let signature = signatures[0].object()?;
    exact_keys(
        signature,
        &[
            "bundle",
            "certificateIdentity",
            "certificateIssuer",
            "scheme",
        ],
    )?;
    if json_member(signature, "scheme")?.string()? != "sigstore"
        || !github_workflow_identity_matches(
            json_member(signature, "certificateIdentity")?.string()?,
            "Portfoligno/hell-rs",
            workflow,
            "refs/heads/main",
        )
    {
        return Err("artifact receipt signer workflow identity is invalid".to_owned());
    }
    verify_sigstore_signature(policy, signature, &payload)?;
    let certificate_identity = json_member(signature, "certificateIdentity")?
        .string()?
        .to_owned();
    let certificate_issuer = json_member(signature, "certificateIssuer")?
        .string()?
        .to_owned();
    let signer_fingerprint = canonical_json_digest(&JsonValue::Object(BTreeMap::from([
        (
            "certificateIdentity".to_owned(),
            JsonValue::String(certificate_identity.clone()),
        ),
        (
            "certificateIssuer".to_owned(),
            JsonValue::String(certificate_issuer.clone()),
        ),
    ])))?;
    Ok(VerifiedArtifactAttestation {
        digest: record_digest(path)?,
        certificate_identity,
        certificate_issuer,
        signer_fingerprint,
    })
}

struct VerifiedArtifactAttestation {
    digest: String,
    certificate_identity: String,
    certificate_issuer: String,
    signer_fingerprint: String,
}

fn verify_artifact_receipt_attestations(
    input: &Path,
    policy: &Path,
    primary: &AcquisitionReceipt,
    independent: &AcquisitionReceipt,
) -> Result<[VerifiedArtifactAttestation; 2], String> {
    let primary_attestation = verify_artifact_receipt_attestation(
        &input.join("receipt-primary.producer.dsse.json"),
        policy,
        primary,
        "artifact-primary-producer",
        ".github/workflows/artifact-authenticity-review.yml",
    )?;
    let independent_attestation = verify_artifact_receipt_attestation(
        &input.join("receipt-independent.producer.dsse.json"),
        policy,
        independent,
        "artifact-independent-acquirer",
        ".github/workflows/artifact-independent-acquisition.yml",
    )?;
    if primary_attestation.digest == independent_attestation.digest
        || primary_attestation.certificate_identity == independent_attestation.certificate_identity
        || primary_attestation.signer_fingerprint == independent_attestation.signer_fingerprint
    {
        return Err("artifact receipt producer attestations are not independent".to_owned());
    }
    Ok([primary_attestation, independent_attestation])
}

fn artifact_finalize(root: &Path, options: &Options) -> Result<String, String> {
    let input = required_path(
        &options.input,
        "artifact-acquire finalize requires --input receipt directory",
    )?;
    let output = required_path(
        &options.output,
        "artifact-acquire finalize requires --output report",
    )?;
    let policy = required_path(
        &options.policy,
        "artifact-acquire finalize requires --policy allowed-signers",
    )?;
    let primary_path = input.join("receipt-primary.json");
    let independent_path = input.join("receipt-independent.json");
    let primary = parse_acquisition_receipt_state(&primary_path, true)?;
    let independent = parse_acquisition_receipt_state(&independent_path, true)?;
    let producer_attestations =
        verify_artifact_receipt_attestations(input, policy, &primary, &independent)?;
    verify_provider_metadata(input, &primary, "primary")?;
    verify_provider_metadata(input, &independent, "independent")?;
    verify_external_acquisition_evidence(input, &independent)?;
    let review_path = input.join("trust-review.dsse.json");
    let review_digest = record_digest(&review_path)?;
    let review = verify_review_envelope(&review_path, policy)?;
    let (_, epoch) = epoch(root)?;
    let attestation_path = input.join("attestation-verification.json");
    let attestation_digest = verify_artifact_attestation(
        &attestation_path,
        &primary.observed_sha256,
        &primary.artifact,
        &primary.candidate_commit,
    )?;
    let attestation = parse_json(&read_text(&attestation_path)?)?;
    let attestation_verified = json_member(attestation.object()?, "state")?.string()? == "verified";
    let mut core_digests = vec![
        acquisition_receipt_core_digest(&primary),
        acquisition_receipt_core_digest(&independent),
        primary.observed_sha256.clone(),
        attestation_digest,
        producer_attestations[0].digest.clone(),
        producer_attestations[1].digest.clone(),
    ];
    for label in ["primary", "independent"] {
        let selection = input.join("source-selection").join(label);
        for file in [
            "selection.json",
            "provider-selected-artifact.json",
            "provider-selected-run.json",
        ] {
            core_digests.push(record_digest(&selection.join(file))?);
        }
    }
    if review.role != "artifact-trust-reviewer"
        || review.candidate_commit != git_output(root, &["rev-parse", "HEAD"])?.trim()
        || review.assurance_epoch != epoch.hex()
        || !core_digests
            .iter()
            .all(|digest| review.reviewed_artifacts.contains(digest))
    {
        return Err("artifact trust review does not bind both receipt cores and bytes".to_owned());
    }
    write_atomic(
        &primary_path,
        acquisition_receipt_json(&primary, &review_digest)?.as_bytes(),
    )?;
    write_atomic(
        &independent_path,
        acquisition_receipt_json(&independent, &review_digest)?.as_bytes(),
    )?;
    artifact_verify(
        root,
        &Options {
            input: Some(input.to_path_buf()),
            policy: Some(policy.to_path_buf()),
            ..Options::default()
        },
    )?;
    let report = format!(
        "{{\n  \"schemaVersion\": 1,\n  \"artifactIdentityComplete\": true,\n  \"outerDigestAgreement\": true,\n  \"workflowIdentityVerified\": true,\n  \"releaseIdentityVerified\": false,\n  \"attestationVerified\": {attestation_verified},\n  \"independentTrustDomainCount\": 2,\n  \"requiresHumanTrustDecision\": true,\n  \"humanTrustDecisionRef\": \"{review_digest}\"\n}}\n"
    );
    write_atomic(output, report.as_bytes())?;
    write_digest_sibling(output, sha256_bytes(report.as_bytes()))?;
    Ok(format!(
        "finalized verified artifact authenticity report {}",
        output.display()
    ))
}

fn artifact_finalize_assemble(root: &Path, options: &Options) -> Result<String, String> {
    if !options.github_dispatch_inputs {
        return Err("assemble-finalize requires --github-dispatch-inputs".to_owned());
    }
    let sources = required_path(
        &options.input,
        "assemble-finalize requires --input source directory",
    )?;
    let output = required_path(
        &options.output,
        "assemble-finalize requires --output acquisition directory",
    )?;
    let dispatch = artifact_finalize_dispatch(root)?;
    let primary_root = sources.join("primary");
    let independent_root = sources.join("independent");
    let primary_selection = verify_provider_artifact_selection(
        root,
        &primary_root,
        "ephemeralEvidence-artifact-authenticity",
        ".github/workflows/artifact-authenticity-review.yml",
        "workflow_dispatch",
        dispatch.primary.run_id,
        dispatch.primary.run_attempt,
        dispatch.primary.artifact_id,
        &dispatch.candidate,
        &dispatch.primary.package_sha256,
        &dispatch.primary.archive_sha256,
    )?;
    let independent_selection = verify_provider_artifact_selection(
        root,
        &independent_root,
        "artifact-independent-acquisition",
        ".github/workflows/artifact-independent-acquisition.yml",
        "workflow_dispatch",
        dispatch.independent.run_id,
        dispatch.independent.run_attempt,
        dispatch.independent.artifact_id,
        &dispatch.candidate,
        &dispatch.independent.package_sha256,
        &dispatch.independent.archive_sha256,
    )?;
    verify_selection_archive(&primary_selection, &dispatch.primary.archive_sha256)?;
    verify_selection_archive(&independent_selection, &dispatch.independent.archive_sha256)?;
    copy_record_tree(&primary_root.join("acquisition"), output)?;
    copy_finalize_independent_payload(&independent_root, output)?;
    retain_finalize_selection(output, "primary", &primary_root, &primary_selection)?;
    retain_finalize_selection(
        output,
        "independent",
        &independent_root,
        &independent_selection,
    )?;
    verify_finalize_source_selections(output, &dispatch)?;
    Ok("verified provider objects and assembled exact artifact review sources".to_owned())
}

pub(crate) fn verify_selection_archive(selection: &str, expected: &str) -> Result<(), String> {
    let document = parse_json(selection)?;
    if json_member(document.object()?, "providerArchiveSha256")?.string()? != expected {
        return Err("provider-selected archive digest differs from dispatch".to_owned());
    }
    Ok(())
}

fn copy_finalize_independent_payload(source: &Path, destination: &Path) -> Result<(), String> {
    let mut entries = fs::read_dir(source)
        .map_err(|error| format!("cannot enumerate independent review source: {error}"))?
        .collect::<Result<Vec<_>, _>>()
        .map_err(|error| format!("cannot enumerate independent review source: {error}"))?;
    entries.sort_by_key(std::fs::DirEntry::file_name);
    for entry in entries {
        if matches!(
            entry.file_name().to_str(),
            Some("provider-selected-artifact.json" | "provider-selected-run.json")
        ) {
            continue;
        }
        copy_record_tree(&entry.path(), &destination.join(entry.file_name()))?;
    }
    Ok(())
}

fn retain_finalize_selection(
    output: &Path,
    label: &str,
    source: &Path,
    selection: &str,
) -> Result<(), String> {
    let directory = output.join("source-selection").join(label);
    fs::create_dir_all(&directory)
        .map_err(|error| format!("cannot create finalization selection directory: {error}"))?;
    copy_record_tree(
        &source.join("provider-selected-artifact.json"),
        &directory.join("provider-selected-artifact.json"),
    )?;
    copy_record_tree(
        &source.join("provider-selected-run.json"),
        &directory.join("provider-selected-run.json"),
    )?;
    write_atomic(&directory.join("selection.json"), selection.as_bytes())
}

fn verify_finalize_source_selections(
    acquisition: &Path,
    dispatch: &ArtifactFinalizeDispatch,
) -> Result<(), String> {
    let primary = parse_acquisition_receipt_state(&acquisition.join("receipt-primary.json"), true)?;
    let independent =
        parse_acquisition_receipt_state(&acquisition.join("receipt-independent.json"), true)?;
    verify_finalize_selection(
        &acquisition.join("source-selection").join("primary"),
        &dispatch.primary,
        &dispatch.candidate,
        "ephemeralEvidence-artifact-authenticity",
        ".github/workflows/artifact-authenticity-review.yml",
    )?;
    verify_finalize_selection(
        &acquisition.join("source-selection").join("independent"),
        &dispatch.independent,
        &dispatch.candidate,
        "artifact-independent-acquisition",
        ".github/workflows/artifact-independent-acquisition.yml",
    )?;
    verify_acquisition_selection_identity(
        &primary,
        &dispatch.primary,
        &dispatch.candidate,
        ".github/workflows/artifact-authenticity-review.yml",
    )?;
    verify_acquisition_selection_identity(
        &independent,
        &dispatch.independent,
        &dispatch.candidate,
        ".github/workflows/artifact-independent-acquisition.yml",
    )
}

fn verify_acquisition_selection_identity(
    receipt: &AcquisitionReceipt,
    selection: &ArtifactFinalizeSource,
    candidate: &str,
    workflow: &str,
) -> Result<(), String> {
    if receipt.acquisition_run_id != selection.run_id
        || receipt.acquisition_run_attempt != selection.run_attempt
        || receipt.candidate_commit != candidate
        || acquisition_workflow_reference(&receipt.acquisition_workflow_ref, workflow).is_err()
    {
        return Err("acquisition receipt does not bind its selected provider run".to_owned());
    }
    Ok(())
}

fn verify_finalize_selection(
    directory: &Path,
    expected: &ArtifactFinalizeSource,
    candidate: &str,
    artifact: &str,
    workflow: &str,
) -> Result<(), String> {
    let artifact_api_path = directory.join("provider-selected-artifact.json");
    let run_api_path = directory.join("provider-selected-run.json");
    let selection = parse_json(&read_text(&directory.join("selection.json"))?)?;
    let selection = selection.object()?;
    exact_keys(selection, PROVIDER_SELECTION_KEYS)?;
    if json_member(selection, "schemaVersion")?.number()? != 1
        || json_member(selection, "artifact")?.string()? != artifact
        || json_member(selection, "workflowPath")?.string()? != workflow
        || json_member(selection, "event")?.string()? != "workflow_dispatch"
        || json_member(selection, "providerRunId")?.number()? != expected.run_id
        || json_member(selection, "providerRunAttempt")?.number()? != expected.run_attempt
        || json_member(selection, "providerArtifactId")?.number()? != expected.artifact_id
        || json_member(selection, "providerArchiveSha256")?.string()? != expected.archive_sha256
        || json_member(selection, "candidateCommit")?.string()? != candidate
        || json_member(selection, "directorySha256")?.string()? != expected.package_sha256
        || json_member(selection, "providerArtifactApiPath")?.string()?
            != "provider-selected-artifact.json"
        || json_member(selection, "providerRunApiPath")?.string()? != "provider-selected-run.json"
        || json_member(selection, "selectionState")?.string()? != "exact-provider-object"
    {
        return Err("retained artifact finalization provider selection is substituted".to_owned());
    }
    for (key, label) in [
        ("workflowBlobSha256", "selected workflow blob"),
        ("providerArchiveSha256", "selected provider archive"),
        (
            "providerArtifactApiSha256",
            "selected artifact API response",
        ),
        ("providerRunApiSha256", "selected run API response"),
        ("directorySha256", "selected artifact package"),
    ] {
        require_digest(json_member(selection, key)?.string()?, label)?;
    }
    validate_utc_timestamp(json_member(selection, "providerCreatedAt")?.string()?)?;
    validate_utc_timestamp(json_member(selection, "providerExpiresAt")?.string()?)?;
    if json_member(selection, "providerArchiveSize")?.number()? == 0
        || !json_member(selection, "providerArchiveUrl")?
            .string()?
            .starts_with("https://api.github.com/repos/Portfoligno/hell-rs/actions/artifacts/")
    {
        return Err("retained provider archive metadata is invalid".to_owned());
    }
    verify_file_digest(
        &artifact_api_path,
        json_member(selection, "providerArtifactApiSha256")?.string()?,
        "artifact finalization provider artifact API response",
    )?;
    verify_file_digest(
        &run_api_path,
        json_member(selection, "providerRunApiSha256")?.string()?,
        "artifact finalization provider run API response",
    )?;
    let artifact_api = parse_json(&read_text(&artifact_api_path)?)?;
    let artifact_api = artifact_api.object()?;
    let run_api = parse_json(&read_text(&run_api_path)?)?;
    let run_api = run_api.object()?;
    let archive_digest = json_member(artifact_api, "digest")?
        .string()?
        .strip_prefix("sha256:")
        .ok_or_else(|| "retained provider artifact digest is not SHA-256".to_owned())?;
    let repository_id = std::env::var("GITHUB_REPOSITORY_ID")
        .map_err(|_| "artifact review requires GITHUB_REPOSITORY_ID".to_owned())?;
    if json_member(artifact_api, "id")?.number()? != expected.artifact_id
        || json_member(artifact_api, "name")?.string()? != artifact
        || json_member(artifact_api, "expired")?.boolean()?
        || json_member(json_member(artifact_api, "workflow_run")?.object()?, "id")?.number()?
            != expected.run_id
        || archive_digest != expected.archive_sha256
        || json_member(run_api, "id")?.number()? != expected.run_id
        || json_member(run_api, "run_attempt")?.number()? != expected.run_attempt
        || json_member(run_api, "head_sha")?.string()? != candidate
        || provider_run_workflow_ref(json_member(run_api, "path")?.string()?, workflow).is_err()
        || json_member(run_api, "event")?.string()? != "workflow_dispatch"
        || json_member(json_member(run_api, "repository")?.object()?, "id")?
            .number()?
            .to_string()
            != repository_id
        || json_member(selection, "repositoryId")?.string()? != repository_id
    {
        return Err("retained provider API facts do not match finalization selection".to_owned());
    }
    Ok(())
}

const PROVIDER_SELECTION_KEYS: &[&str] = &[
    "artifact",
    "candidateCommit",
    "directorySha256",
    "event",
    "providerArchiveSha256",
    "providerArchiveSize",
    "providerArchiveUrl",
    "providerArtifactApiPath",
    "providerArtifactApiSha256",
    "providerArtifactId",
    "providerCreatedAt",
    "providerExpiresAt",
    "providerRunApiPath",
    "providerRunApiSha256",
    "providerRunAttempt",
    "providerRunId",
    "repositoryId",
    "schemaVersion",
    "selectionState",
    "workflowBlobSha256",
    "workflowPath",
];

pub(crate) fn verify_retained_collection_activation_selection(
    root: &Path,
    directory: &Path,
    artifact_name: &str,
    candidate: &str,
) -> Result<BTreeMap<String, JsonValue>, String> {
    let selection_path = directory.join("provider-selection.json");
    let document = parse_json(&read_text(&selection_path)?)?;
    let selection = document.object()?;
    exact_keys(selection, PROVIDER_SELECTION_KEYS)?;
    let run_id = json_member(selection, "providerRunId")?.number()?;
    let run_attempt = json_member(selection, "providerRunAttempt")?.number()?;
    let artifact_id = json_member(selection, "providerArtifactId")?.number()?;
    if run_id == 0
        || run_attempt == 0
        || artifact_id == 0
        || json_member(selection, "schemaVersion")?.number()? != 1
        || json_member(selection, "selectionState")?.string()? != "exact-provider-object"
        || json_member(selection, "artifact")?.string()? != artifact_name
        || json_member(selection, "workflowPath")?.string()?
            != ".github/workflows/collection-custody-integration.yml"
        || json_member(selection, "event")?.string()? != "workflow_dispatch"
        || json_member(selection, "candidateCommit")?.string()? != candidate
    {
        return Err(
            "retained collection activation provider selection identity differs".to_owned(),
        );
    }
    verify_retained_workflow_digest(
        json_member(selection, "workflowBlobSha256")?.string()?,
        &record_digest(&root.join(".github/workflows/collection-custody-integration.yml"))?,
    )?;
    verify_retained_proposal_provider_api(directory, selection, artifact_name, candidate)?;
    Ok(selection.clone())
}

pub(crate) fn verify_historical_collection_activation_selection(
    root: &Path,
    directory: &Path,
    artifact_name: &str,
    candidate: &str,
    workflow: &str,
) -> Result<BTreeMap<String, JsonValue>, String> {
    let selection_path = directory.join("provider-selection.json");
    let selection_bytes = read_regular_file(&selection_path)?;
    let document = parse_json(
        std::str::from_utf8(&selection_bytes)
            .map_err(|_| "historical provider selection is not UTF-8".to_owned())?,
    )?;
    if canonical_json_bytes(&document)? != selection_bytes {
        return Err("historical provider selection is not canonical".to_owned());
    }
    let selection = document.object()?;
    exact_keys(selection, PROVIDER_SELECTION_KEYS)?;
    let configured_repository_id = load_acquisition_policy(root)?
        .repository_id
        .ok_or_else(|| "historical provider repository ID is not configured".to_owned())?;
    if configured_repository_id != "1327351238"
        || json_member(selection, "repositoryId")?.string()? != configured_repository_id
        || json_member(selection, "schemaVersion")?.number()? != 1
        || json_member(selection, "selectionState")?.string()? != "exact-provider-object"
        || json_member(selection, "artifact")?.string()? != artifact_name
        || json_member(selection, "workflowPath")?.string()? != workflow
        || json_member(selection, "event")?.string()? != "workflow_dispatch"
        || json_member(selection, "candidateCommit")?.string()? != candidate
    {
        return Err("historical provider selection identity differs".to_owned());
    }
    verify_retained_workflow_digest(
        json_member(selection, "workflowBlobSha256")?.string()?,
        &record_digest(&root.join(workflow))?,
    )?;
    verify_historical_proposal_provider_api(
        directory,
        selection,
        artifact_name,
        candidate,
        &configured_repository_id,
    )?;
    Ok(selection.clone())
}

fn verify_historical_proposal_provider_api(
    directory: &Path,
    selection: &BTreeMap<String, JsonValue>,
    artifact_name: &str,
    candidate: &str,
    repository_id: &str,
) -> Result<(), String> {
    let artifact_path = directory.join("provider-selected-artifact.json");
    let run_path = directory.join("provider-selected-run.json");
    verify_file_digest(
        &artifact_path,
        json_member(selection, "providerArtifactApiSha256")?.string()?,
        "historical artifact API",
    )?;
    verify_file_digest(
        &run_path,
        json_member(selection, "providerRunApiSha256")?.string()?,
        "historical run API",
    )?;
    let artifact_doc = parse_json(&read_text(&artifact_path)?)?;
    let artifact = artifact_doc.object()?;
    let run_doc = parse_json(&read_text(&run_path)?)?;
    let run = run_doc.object()?;
    verify_historical_provider_metadata(
        selection,
        artifact,
        run,
        artifact_name,
        candidate,
        repository_id,
    )
}

fn verify_historical_provider_metadata(
    selection: &BTreeMap<String, JsonValue>,
    artifact: &BTreeMap<String, JsonValue>,
    run: &BTreeMap<String, JsonValue>,
    artifact_name: &str,
    candidate: &str,
    repository_id: &str,
) -> Result<(), String> {
    let run_id = json_member(selection, "providerRunId")?.number()?;
    let run_attempt = json_member(selection, "providerRunAttempt")?.number()?;
    let artifact_id = json_member(selection, "providerArtifactId")?.number()?;
    let archive_size = json_member(selection, "providerArchiveSize")?.number()?;
    let created_at = json_member(selection, "providerCreatedAt")?.string()?;
    let expires_at = json_member(selection, "providerExpiresAt")?.string()?;
    validate_utc_timestamp(created_at)?;
    validate_utc_timestamp(expires_at)?;
    let expected_archive_url = format!(
        "https://api.github.com/repos/Portfoligno/hell-rs/actions/artifacts/{artifact_id}/zip"
    );
    if run_id == 0
        || run_attempt == 0
        || artifact_id == 0
        || archive_size == 0
        || json_member(selection, "providerArtifactApiPath")?.string()?
            != "provider-selected-artifact.json"
        || json_member(selection, "providerRunApiPath")?.string()? != "provider-selected-run.json"
        || utc_timestamp_seconds(created_at)? >= utc_timestamp_seconds(expires_at)?
        || json_member(selection, "providerArchiveUrl")?.string()? != expected_archive_url
        || json_member(artifact, "id")?.number()?
            != json_member(selection, "providerArtifactId")?.number()?
        || json_member(artifact, "name")?.string()? != artifact_name
        || json_member(artifact, "expired")?.boolean()?
        || json_member(json_member(artifact, "workflow_run")?.object()?, "id")?.number()? != run_id
        || json_member(artifact, "digest")?
            .string()?
            .strip_prefix("sha256:")
            != Some(json_member(selection, "providerArchiveSha256")?.string()?)
        || json_member(artifact, "size_in_bytes")?.number()?
            != json_member(selection, "providerArchiveSize")?.number()?
        || json_member(artifact, "created_at")?.string()?
            != json_member(selection, "providerCreatedAt")?.string()?
        || json_member(artifact, "expires_at")?.string()?
            != json_member(selection, "providerExpiresAt")?.string()?
        || json_member(artifact, "archive_download_url")?.string()?
            != json_member(selection, "providerArchiveUrl")?.string()?
        || json_member(run, "id")?.number()? != run_id
        || json_member(run, "run_attempt")?.number()? != run_attempt
        || json_member(run, "head_sha")?.string()? != candidate
        || provider_run_workflow_ref(
            json_member(run, "path")?.string()?,
            json_member(selection, "workflowPath")?.string()?,
        )
        .is_err()
        || json_member(run, "event")?.string()? != "workflow_dispatch"
        || json_member(json_member(run, "repository")?.object()?, "id")?
            .number()?
            .to_string()
            != repository_id
        || json_member(json_member(run, "repository")?.object()?, "full_name")?.string()?
            != "Portfoligno/hell-rs"
    {
        return Err("historical provider API facts differ".to_owned());
    }
    Ok(())
}

