fn acquisition_receipt_json(
    receipt: &AcquisitionReceipt,
    trust_review_ref: &str,
) -> Result<String, String> {
    if trust_review_ref != "REVIEW_REQUIRED" {
        require_digest(trust_review_ref, "artifact trust review")?;
    }
    let external_path = receipt.external_acquisition_path.as_ref().map_or_else(
        || "null".to_owned(),
        |path| json_string(&path_text(path).unwrap_or_else(|_| "INVALID_PATH".to_owned())),
    );
    let external_sha256 = receipt
        .external_acquisition_sha256
        .as_deref()
        .map_or_else(|| "null".to_owned(), json_string);
    Ok(format!(
        "{{\n  \"schemaVersion\": 3,\n  \"artifact\": {},\n  \"providerArtifactId\": {},\n  \"providerMetadataSha256\": {},\n  \"localPath\": {},\n  \"observedSha256\": {},\n  \"observedSize\": {},\n  \"repository\": \"Portfoligno/hell-rs\",\n  \"repositoryId\": {},\n  \"workflowPath\": {},\n  \"workflowBlobSha256\": {},\n  \"runId\": {},\n  \"runAttempt\": {},\n  \"acquisitionRunId\": {},\n  \"acquisitionRunAttempt\": {},\n  \"acquisitionWorkflowRef\": {},\n  \"candidateCommit\": {},\n  \"channelClass\": {},\n  \"trustDomain\": {},\n  \"acquirer\": {},\n  \"acquirerAccountId\": {},\n  \"acquirerLogin\": {},\n  \"acquiredAt\": {},\n  \"acquisitionEvent\": {},\n  \"providerEvent\": {},\n  \"acquisitionPlatform\": {},\n  \"acquisitionTool\": {},\n  \"externalAcquisitionPath\": {external_path},\n  \"externalAcquisitionSha256\": {external_sha256},\n  \"trustReviewRef\": {}\n}}\n",
        json_string(&receipt.artifact),
        receipt.provider_artifact_id,
        json_string(&receipt.provider_metadata_sha256),
        json_string(&path_text(&receipt.local_path)?),
        json_string(&receipt.observed_sha256),
        receipt.observed_size,
        json_string(&receipt.repository_id),
        json_string(&receipt.workflow_path),
        json_string(&receipt.workflow_sha256),
        receipt.run_id,
        receipt.run_attempt,
        receipt.acquisition_run_id,
        receipt.acquisition_run_attempt,
        json_string(&receipt.acquisition_workflow_ref),
        json_string(&receipt.candidate_commit),
        json_string(&receipt.channel_class),
        json_string(&receipt.trust_domain),
        json_string(&receipt.acquirer),
        receipt.acquirer_account_id,
        json_string(&receipt.acquirer_login),
        json_string(&receipt.acquired_at),
        json_string(&receipt.acquisition_event),
        json_string(&receipt.provider_event),
        json_string(&receipt.acquisition_platform),
        json_string(&receipt.acquisition_tool),
        json_string(trust_review_ref),
    ))
}

struct AcquisitionDispatch {
    candidate: String,
    run_id: String,
    run_attempt: String,
    acquired_at: String,
    provider_artifact_id: u64,
    provider_selection_api: Vec<u8>,
    provider_event: String,
    workflow_path: String,
}

fn artifact_primary_dispatch(
    root: &Path,
    input: &Path,
    artifact: &str,
) -> Result<AcquisitionDispatch, String> {
    let event_path = std::env::var_os("GITHUB_EVENT_PATH")
        .ok_or_else(|| "GITHUB_EVENT_PATH is unavailable for primary acquisition".to_owned())?;
    let event = parse_json(&read_text(Path::new(&event_path))?)?;
    let inputs = json_member(event.object()?, "inputs")?.object()?;
    let base_keys = [
        "candidate_sha",
        "expected_artifact_set_sha256",
        "source_artifact_id",
        "source_provider_archive_sha256",
        "source_run_attempt",
        "source_run_id",
    ];
    let custody_keys = [
        "acquisition_time",
        "artifact_class",
        "candidate_sha",
        "expected_artifact_set_sha256",
        "provider_artifact_id",
        "provider_archive_sha256",
        "retention_until",
        "review_issued_at",
        "source_run_attempt",
        "source_run_id",
    ];
    let custody = exact_keys(inputs, &base_keys).is_err();
    if custody {
        exact_keys(inputs, &custody_keys)?;
    }
    let (provider_event, workflow_path) = if custody {
        match json_member(inputs, "artifact_class")?.string()? {
            "pre-review-evidence" if artifact == "promotion-review-ready-evidence" => (
                "workflow_dispatch",
                ".github/workflows/promotion-evidence-review.yml",
            ),
            "final-promotion-record" if artifact == "promotion-record" => {
                ("workflow_dispatch", ".github/workflows/nightly.yml")
            }
            _ => {
                return Err(
                    "artifact class does not match the exact provider artifact identity".to_owned(),
                );
            }
        }
    } else if artifact == "native-oracle-merged" {
        ("push", ".github/workflows/nightly.yml")
    } else {
        return Err("primary artifact lacks an accepted source class".to_owned());
    };
    let candidate = json_member(inputs, "candidate_sha")?.string()?;
    require_git_sha_text(candidate, "primary acquisition candidate")?;
    if git_output(root, &["rev-parse", "HEAD"])?.trim() != candidate {
        return Err("primary acquisition checkout does not match candidate input".to_owned());
    }
    let expected = json_member(inputs, "expected_artifact_set_sha256")?.string()?;
    require_digest(expected, "primary acquisition artifact set")?;
    if record_digest(input)? != expected {
        return Err("primary acquisition artifact set digest mismatch".to_owned());
    }
    let run_id = json_member(inputs, "source_run_id")?.string()?.to_owned();
    let run_attempt = json_member(inputs, "source_run_attempt")?
        .string()?
        .to_owned();
    for (name, value) in [
        ("source_run_id", &run_id),
        ("source_run_attempt", &run_attempt),
    ] {
        if value.parse::<u64>().is_err() || value == "0" {
            return Err(format!("primary acquisition {name} must be nonzero"));
        }
    }
    let resolved = resolve_provider_artifact(&run_id, artifact)?;
    let archive_key = if custody {
        "provider_archive_sha256"
    } else {
        "source_provider_archive_sha256"
    };
    verify_resolved_provider_archive(&resolved, json_member(inputs, archive_key)?.string()?)?;
    let (acquired_at, provider_artifact_id) =
        primary_acquisition_identity(inputs, custody, resolved.id)?;
    Ok(AcquisitionDispatch {
        candidate: candidate.to_owned(),
        run_id,
        run_attempt,
        acquired_at,
        provider_artifact_id,
        provider_selection_api: resolved.api_bytes,
        provider_event: provider_event.to_owned(),
        workflow_path: workflow_path.to_owned(),
    })
}

fn primary_acquisition_identity(
    inputs: &BTreeMap<String, JsonValue>,
    custody: bool,
    resolved_id: u64,
) -> Result<(String, u64), String> {
    let key = if custody {
        "provider_artifact_id"
    } else {
        "source_artifact_id"
    };
    let selected = json_member(inputs, key)?
        .string()?
        .parse::<u64>()
        .map_err(|_| format!("{key} must be an integer"))?;
    if selected == 0 || selected != resolved_id {
        return Err(format!("{key} differs from exact provider selection"));
    }
    let acquired_at = if custody {
        let value = json_member(inputs, "acquisition_time")?
            .string()?
            .to_owned();
        validate_utc_timestamp(&value)?;
        value
    } else {
        crate::custody_ops::current_utc_timestamp()?
    };
    Ok((acquired_at, selected))
}

struct ResolvedProviderArtifact {
    id: u64,
    api_bytes: Vec<u8>,
}

pub(crate) struct ResolvedProviderArtifactForWorkflow {
    pub(crate) artifact_id: u64,
    pub(crate) archive_sha256: String,
}

pub(crate) struct CurrentRunArtifactSelection {
    pub(crate) primary_artifact_id: u64,
    pub(crate) secondary_artifact_id: u64,
    pub(crate) primary_archive_sha256: String,
    pub(crate) secondary_archive_sha256: String,
}

pub(crate) struct VerifiedCurrentRunArtifactSelection {
    pub(crate) primary_artifact_name: String,
    pub(crate) primary_artifact_id: u64,
    pub(crate) primary_archive_sha256: String,
    pub(crate) secondary_artifact_name: String,
    pub(crate) secondary_artifact_id: u64,
    pub(crate) secondary_archive_sha256: String,
    pub(crate) run_id: u64,
    pub(crate) run_attempt: u64,
    pub(crate) workflow_path: String,
    pub(crate) event_name: String,
    pub(crate) candidate: String,
}

pub(crate) struct CurrentRunArtifactSelectionRequest<'a> {
    pub(crate) root: &'a Path,
    pub(crate) output: &'a Path,
    pub(crate) workflow_path: &'a str,
    pub(crate) event_name: &'a str,
    pub(crate) run_id: u64,
    pub(crate) run_attempt: u64,
    pub(crate) candidate: &'a str,
    pub(crate) primary_artifact_name: &'a str,
    pub(crate) secondary_artifact_name: &'a str,
}

pub(crate) fn select_current_run_artifacts(
    request: &CurrentRunArtifactSelectionRequest<'_>,
) -> Result<CurrentRunArtifactSelection, String> {
    let workflow = validate_provider_workflow_path(request.workflow_path)?;
    if !workflow.starts_with(Path::new(".github").join("workflows"))
        || !request.root.join(&workflow).is_file()
        || request.run_id == 0
        || request.run_attempt == 0
    {
        return Err("current-run artifact selection identity is invalid".to_owned());
    }
    require_git_sha_text(request.candidate, "current-run artifact candidate")?;
    validate_provider_atom(request.event_name, "current-run artifact event")?;
    validate_provider_atom(
        request.primary_artifact_name,
        "current-run primary artifact",
    )?;
    validate_provider_atom(
        request.secondary_artifact_name,
        "current-run secondary artifact",
    )?;
    if request.primary_artifact_name == request.secondary_artifact_name {
        return Err("current-run artifact names are not distinct".to_owned());
    }
    let (repository, repository_id) = provider_selection_repository_identity()?;
    if repository != "Portfoligno/hell-rs" || repository_id != "1327351238" {
        return Err("current-run artifact repository identity is invalid".to_owned());
    }
    let (_, run_endpoint) =
        provider_selection_endpoints(&repository, 1, request.run_id, request.run_attempt);
    let run = github_api_json(&run_endpoint)?;
    verify_current_run_artifact_run(request, &run, &repository_id)?;
    let primary =
        resolve_provider_artifact(&request.run_id.to_string(), request.primary_artifact_name)?;
    let secondary =
        resolve_provider_artifact(&request.run_id.to_string(), request.secondary_artifact_name)?;
    let primary_digest =
        verify_current_run_artifact(&primary, request.run_id, request.primary_artifact_name)?;
    let secondary_digest =
        verify_current_run_artifact(&secondary, request.run_id, request.secondary_artifact_name)?;
    if primary.id == secondary.id {
        return Err("current-run artifacts resolve to the same provider object".to_owned());
    }
    retain_current_run_artifact_selection(
        request,
        &run,
        &primary,
        &secondary,
        &primary_digest,
        &secondary_digest,
    )?;
    Ok(CurrentRunArtifactSelection {
        primary_artifact_id: primary.id,
        secondary_artifact_id: secondary.id,
        primary_archive_sha256: primary_digest,
        secondary_archive_sha256: secondary_digest,
    })
}

pub(crate) fn verify_current_run_artifact_selection(
    directory: &Path,
) -> Result<VerifiedCurrentRunArtifactSelection, String> {
    let expected = BTreeSet::from([
        OsString::from("primary-artifact.json"),
        OsString::from("provider-run.json"),
        OsString::from("secondary-artifact.json"),
        OsString::from("selection.json"),
        OsString::from("selection.json.sha256"),
    ]);
    require_exact_real_file_inventory(directory, &expected, "current-run artifact selection")?;
    let bytes = fs::read(directory.join("selection.json"))
        .map_err(|error| format!("cannot read current-run artifact selection: {error}"))?;
    if fs::read_to_string(directory.join("selection.json.sha256"))
        .map_err(|error| format!("cannot read current-run artifact selection digest: {error}"))?
        != format!("{}\n", sha256_bytes(&bytes).hex())
    {
        return Err("current-run artifact selection digest differs".to_owned());
    }
    let document = parse_json(
        std::str::from_utf8(&bytes)
            .map_err(|_| "current-run artifact selection is not UTF-8".to_owned())?,
    )?;
    if canonical_json_bytes(&document)? != bytes {
        return Err("current-run artifact selection is not canonical".to_owned());
    }
    let fields = document.object()?;
    verify_current_run_selection_keys(fields)?;
    if json_member(fields, "schemaVersion")?.number()? != 1
        || json_member(fields, "selectionState")?.string()?
            != "exact-current-run-provider-artifacts"
    {
        return Err("current-run artifact selection schema is invalid".to_owned());
    }
    require_git_sha_text(
        json_member(fields, "candidateCommit")?.string()?,
        "current-run artifact candidate",
    )?;
    validate_provider_atom(
        json_member(fields, "event")?.string()?,
        "current-run artifact event",
    )?;
    validate_provider_workflow_path(json_member(fields, "workflowPath")?.string()?)?;
    let run_id = json_member(fields, "providerRunId")?.number()?;
    if run_id == 0 || json_member(fields, "providerRunAttempt")?.number()? == 0 {
        return Err("current-run artifact run identity is invalid".to_owned());
    }
    let run =
        read_exact_selection_json(directory, fields, "providerRunSha256", "provider-run.json")?;
    let run_fields = run.object()?;
    if json_member(run_fields, "id")?.number()? != run_id
        || json_member(run_fields, "run_attempt")?.number()?
            != json_member(fields, "providerRunAttempt")?.number()?
        || json_member(run_fields, "head_sha")?.string()?
            != json_member(fields, "candidateCommit")?.string()?
        || json_member(run_fields, "event")?.string()? != json_member(fields, "event")?.string()?
        || provider_run_workflow_ref(
            json_member(run_fields, "path")?.string()?,
            json_member(fields, "workflowPath")?.string()?,
        )
        .is_err()
        || json_member(json_member(run_fields, "repository")?.object()?, "id")?.number()?
            != 1_327_351_238
        || json_member(
            json_member(run_fields, "repository")?.object()?,
            "full_name",
        )?
        .string()?
            != "Portfoligno/hell-rs"
    {
        return Err("current-run artifact retained run differs".to_owned());
    }
    let primary = verify_retained_current_run_artifact(directory, fields, "primary", run_id)?;
    let secondary = verify_retained_current_run_artifact(directory, fields, "secondary", run_id)?;
    if primary.0 == secondary.0 || primary.1 == secondary.1 || primary.2 == secondary.2 {
        return Err("current-run artifact selection is not distinct".to_owned());
    }
    Ok(VerifiedCurrentRunArtifactSelection {
        primary_artifact_name: primary.1,
        primary_artifact_id: primary.0,
        primary_archive_sha256: primary.2,
        secondary_artifact_name: secondary.1,
        secondary_artifact_id: secondary.0,
        secondary_archive_sha256: secondary.2,
        run_id,
        run_attempt: json_member(fields, "providerRunAttempt")?.number()?,
        workflow_path: json_member(fields, "workflowPath")?.string()?.to_owned(),
        event_name: json_member(fields, "event")?.string()?.to_owned(),
        candidate: json_member(fields, "candidateCommit")?.string()?.to_owned(),
    })
}

fn verify_current_run_selection_keys(fields: &BTreeMap<String, JsonValue>) -> Result<(), String> {
    exact_keys(
        fields,
        &[
            "candidateCommit",
            "event",
            "primaryArchiveSha256",
            "primaryArtifactId",
            "primaryArtifactName",
            "primaryProviderApiSha256",
            "providerRunAttempt",
            "providerRunId",
            "providerRunSha256",
            "schemaVersion",
            "secondaryArchiveSha256",
            "secondaryArtifactId",
            "secondaryArtifactName",
            "secondaryProviderApiSha256",
            "selectionState",
            "workflowPath",
        ],
    )
}

fn verify_retained_current_run_artifact(
    directory: &Path,
    fields: &BTreeMap<String, JsonValue>,
    channel: &str,
    run_id: u64,
) -> Result<(u64, String, String), String> {
    let title = if channel == "primary" {
        "primary"
    } else {
        "secondary"
    };
    let id_key = format!("{title}ArtifactId");
    let name_key = format!("{title}ArtifactName");
    let archive_key = format!("{title}ArchiveSha256");
    let api_key = format!("{title}ProviderApiSha256");
    let path = format!("{title}-artifact.json");
    let response = read_exact_selection_json(directory, fields, &api_key, &path)?;
    let response = response.object()?;
    let artifacts = json_member(response, "artifacts")?.array()?;
    if json_member(response, "total_count")?.number()? != 1 || artifacts.len() != 1 {
        return Err("retained current-run artifact response cardinality differs".to_owned());
    }
    let artifact = artifacts
        .first()
        .ok_or_else(|| "retained current-run artifact response is empty".to_owned())?
        .object()?;
    let id = json_member(fields, &id_key)?.number()?;
    let name = json_member(fields, &name_key)?.string()?;
    let archive = json_member(fields, &archive_key)?.string()?;
    require_digest(archive, "retained current-run provider archive")?;
    validate_provider_atom(name, "retained current-run artifact name")?;
    if id == 0
        || json_member(artifact, "id")?.number()? != id
        || json_member(artifact, "name")?.string()? != name
        || json_member(artifact, "digest")?.string()? != format!("sha256:{archive}")
        || json_member(artifact, "expired")?.boolean()?
        || json_member(json_member(artifact, "workflow_run")?.object()?, "id")?.number()? != run_id
    {
        return Err("retained current-run artifact identity differs".to_owned());
    }
    Ok((id, name.to_owned(), archive.to_owned()))
}

fn read_exact_selection_json(
    directory: &Path,
    fields: &BTreeMap<String, JsonValue>,
    digest_key: &str,
    name: &str,
) -> Result<JsonValue, String> {
    let bytes = fs::read(directory.join(name))
        .map_err(|error| format!("cannot read retained current-run provider facts: {error}"))?;
    if json_member(fields, digest_key)?.string()? != sha256_bytes(&bytes).hex() {
        return Err("retained current-run provider facts digest differs".to_owned());
    }
    let document = parse_json(
        std::str::from_utf8(&bytes)
            .map_err(|_| "retained current-run provider facts are not UTF-8".to_owned())?,
    )?;
    if canonical_json_bytes(&document)? != bytes {
        return Err("retained current-run provider facts are not canonical".to_owned());
    }
    Ok(document)
}

fn require_exact_real_file_inventory(
    directory: &Path,
    expected: &BTreeSet<OsString>,
    label: &str,
) -> Result<(), String> {
    let metadata = fs::symlink_metadata(directory)
        .map_err(|error| format!("cannot inspect {label}: {error}"))?;
    if metadata.file_type().is_symlink() || !metadata.is_dir() {
        return Err(format!("{label} is not a real directory"));
    }
    let mut actual = BTreeSet::new();
    for entry in
        fs::read_dir(directory).map_err(|error| format!("cannot enumerate {label}: {error}"))?
    {
        let entry = entry.map_err(|error| format!("cannot enumerate {label}: {error}"))?;
        let metadata = fs::symlink_metadata(entry.path())
            .map_err(|error| format!("cannot inspect {label} member: {error}"))?;
        if metadata.file_type().is_symlink() || !metadata.is_file() {
            return Err(format!("{label} contains a non-regular file"));
        }
        actual.insert(entry.file_name());
    }
    if &actual != expected {
        return Err(format!("{label} inventory differs"));
    }
    Ok(())
}

fn verify_current_run_artifact_run(
    request: &CurrentRunArtifactSelectionRequest<'_>,
    run: &JsonValue,
    repository_id: &str,
) -> Result<(), String> {
    let run = run.object()?;
    let repository = json_member(run, "repository")?.object()?;
    if json_member(run, "id")?.number()? != request.run_id
        || json_member(run, "run_attempt")?.number()? != request.run_attempt
        || json_member(run, "head_sha")?.string()? != request.candidate
        || json_member(run, "event")?.string()? != request.event_name
        || provider_run_workflow_ref(json_member(run, "path")?.string()?, request.workflow_path)
            .is_err()
        || json_member(repository, "id")?.number()?.to_string() != repository_id
        || json_member(repository, "full_name")?.string()? != "Portfoligno/hell-rs"
    {
        return Err("current-run artifact provider run identity differs".to_owned());
    }
    Ok(())
}

fn verify_current_run_artifact(
    resolved: &ResolvedProviderArtifact,
    run_id: u64,
    artifact_name: &str,
) -> Result<String, String> {
    let response = parse_json(
        std::str::from_utf8(&resolved.api_bytes)
            .map_err(|_| "current-run artifact response is not UTF-8".to_owned())?,
    )?;
    let response = response.object()?;
    let artifact = json_member(response, "artifacts")?
        .array()?
        .first()
        .ok_or_else(|| "current-run artifact response is empty".to_owned())?
        .object()?;
    let digest = json_member(artifact, "digest")?
        .string()?
        .strip_prefix("sha256:")
        .ok_or_else(|| "current-run artifact digest is not SHA-256".to_owned())?;
    require_digest(digest, "current-run artifact archive")?;
    let created = json_member(artifact, "created_at")?.string()?;
    let expires = json_member(artifact, "expires_at")?.string()?;
    validate_utc_timestamp(created)?;
    validate_utc_timestamp(expires)?;
    let url = json_member(artifact, "archive_download_url")?.string()?;
    if json_member(artifact, "id")?.number()? != resolved.id
        || json_member(artifact, "name")?.string()? != artifact_name
        || json_member(artifact, "expired")?.boolean()?
        || json_member(artifact, "size_in_bytes")?.number()? == 0
        || utc_timestamp_seconds(created)? >= utc_timestamp_seconds(expires)?
        || json_member(json_member(artifact, "workflow_run")?.object()?, "id")?.number()? != run_id
        || url
            != format!(
                "https://api.github.com/repos/Portfoligno/hell-rs/actions/artifacts/{}/zip",
                resolved.id
            )
    {
        return Err("current-run artifact provider identity differs".to_owned());
    }
    Ok(digest.to_owned())
}

fn retain_current_run_artifact_selection(
    request: &CurrentRunArtifactSelectionRequest<'_>,
    run: &JsonValue,
    primary: &ResolvedProviderArtifact,
    secondary: &ResolvedProviderArtifact,
    primary_digest: &str,
    secondary_digest: &str,
) -> Result<(), String> {
    fs::create_dir_all(request.output)
        .map_err(|error| format!("cannot create current-run artifact selection: {error}"))?;
    let run_bytes = canonical_json_bytes(run)?;
    write_atomic(&request.output.join("provider-run.json"), &run_bytes)?;
    write_atomic(
        &request.output.join("primary-artifact.json"),
        &primary.api_bytes,
    )?;
    write_atomic(
        &request.output.join("secondary-artifact.json"),
        &secondary.api_bytes,
    )?;
    let string = |value: &str| JsonValue::String(value.to_owned());
    let selection = JsonValue::Object(BTreeMap::from([
        ("candidateCommit".to_owned(), string(request.candidate)),
        ("event".to_owned(), string(request.event_name)),
        ("primaryArchiveSha256".to_owned(), string(primary_digest)),
        (
            "primaryArtifactId".to_owned(),
            JsonValue::Number(primary.id),
        ),
        (
            "primaryArtifactName".to_owned(),
            string(request.primary_artifact_name),
        ),
        (
            "primaryProviderApiSha256".to_owned(),
            string(&sha256_bytes(&primary.api_bytes).hex()),
        ),
        (
            "providerRunAttempt".to_owned(),
            JsonValue::Number(request.run_attempt),
        ),
        (
            "providerRunId".to_owned(),
            JsonValue::Number(request.run_id),
        ),
        (
            "providerRunSha256".to_owned(),
            string(&sha256_bytes(&run_bytes).hex()),
        ),
        ("schemaVersion".to_owned(), JsonValue::Number(1)),
        (
            "secondaryArchiveSha256".to_owned(),
            string(secondary_digest),
        ),
        (
            "secondaryArtifactId".to_owned(),
            JsonValue::Number(secondary.id),
        ),
        (
            "secondaryArtifactName".to_owned(),
            string(request.secondary_artifact_name),
        ),
        (
            "secondaryProviderApiSha256".to_owned(),
            string(&sha256_bytes(&secondary.api_bytes).hex()),
        ),
        (
            "selectionState".to_owned(),
            string("exact-current-run-provider-artifacts"),
        ),
        ("workflowPath".to_owned(), string(request.workflow_path)),
    ]));
    let bytes = canonical_json_bytes(&selection)?;
    write_atomic(&request.output.join("selection.json"), &bytes)?;
    write_atomic(
        &request.output.join("selection.json.sha256"),
        format!("{}\n", sha256_bytes(&bytes).hex()).as_bytes(),
    )
}

pub(crate) fn resolve_provider_artifact_for_workflow(
    run_id: &str,
    artifact_name: &str,
    retained_response: &Path,
) -> Result<ResolvedProviderArtifactForWorkflow, String> {
    if run_id
        .parse::<u64>()
        .ok()
        .as_ref()
        .is_none_or(|value| *value == 0)
    {
        return Err("provider artifact resolution run ID must be nonzero".to_owned());
    }
    let resolved = resolve_provider_artifact(run_id, artifact_name)?;
    write_atomic(retained_response, &resolved.api_bytes)?;
    Ok(ResolvedProviderArtifactForWorkflow {
        artifact_id: resolved.id,
        archive_sha256: resolved_provider_archive_sha256(&resolved)?,
    })
}

fn resolve_provider_artifact(
    run_id: &str,
    artifact_name: &str,
) -> Result<ResolvedProviderArtifact, String> {
    let (repository, repository_id) = provider_selection_repository_identity()?;
    if repository != "Portfoligno/hell-rs" || repository_id != "1327351238" {
        return Err("artifact resolution repository identity is not accepted".to_owned());
    }
    let repository_path = repository
        .split('/')
        .fold(PathBuf::new(), |path, component| path.join(component));
    let endpoint = PathBuf::from("repos")
        .join(repository_path)
        .join("actions")
        .join("runs")
        .join(run_id)
        .join("artifacts");
    let response = github_api_json_named_artifact(&endpoint, artifact_name)?;
    resolve_provider_artifact_response(&response, run_id, artifact_name)
}

fn resolve_provider_artifact_response(
    response: &JsonValue,
    run_id: &str,
    artifact_name: &str,
) -> Result<ResolvedProviderArtifact, String> {
    let response = response.object()?;
    let artifacts = json_member(response, "artifacts")?.array()?;
    if json_member(response, "total_count")?.number()? != 1 || artifacts.len() != 1 {
        return Err("source run does not expose exactly one named artifact".to_owned());
    }
    let artifact = artifacts[0].object()?;
    let id = json_member(artifact, "id")?.number()?;
    if id == 0
        || json_member(artifact, "name")?.string()? != artifact_name
        || json_member(artifact, "expired")?.boolean()?
        || json_member(json_member(artifact, "workflow_run")?.object()?, "id")?
            .number()?
            .to_string()
            != run_id
    {
        return Err("resolved provider artifact identity is invalid".to_owned());
    }
    Ok(ResolvedProviderArtifact {
        id,
        api_bytes: canonical_json_bytes(&JsonValue::Object(response.clone()))?,
    })
}

fn verify_resolved_provider_archive(
    resolved: &ResolvedProviderArtifact,
    expected: &str,
) -> Result<(), String> {
    require_digest(expected, "resolved provider archive")?;
    if resolved_provider_archive_sha256(resolved)? != expected {
        return Err("resolved provider archive differs from dispatch".to_owned());
    }
    Ok(())
}

fn resolved_provider_archive_sha256(resolved: &ResolvedProviderArtifact) -> Result<String, String> {
    let response = parse_json(
        std::str::from_utf8(&resolved.api_bytes)
            .map_err(|_| "resolved provider response is not UTF-8".to_owned())?,
    )?;
    let artifact = json_member(response.object()?, "artifacts")?
        .array()?
        .first()
        .ok_or_else(|| "resolved provider response is empty".to_owned())?
        .object()?;
    let observed = json_member(artifact, "digest")?
        .string()?
        .strip_prefix("sha256:")
        .ok_or_else(|| "resolved provider archive is not SHA-256".to_owned())?;
    require_digest(observed, "resolved provider archive")?;
    Ok(observed.to_owned())
}

fn acquire_provider_metadata(
    output_directory: &Path,
    dispatch: &AcquisitionDispatch,
    artifact_name: &str,
    repository_id: &str,
    primary: bool,
) -> Result<String, String> {
    let repository = std::env::var("GITHUB_REPOSITORY")
        .map_err(|_| "provider metadata requires GITHUB_REPOSITORY".to_owned())?;
    if repository != "Portfoligno/hell-rs" {
        return Err("provider metadata repository name is not accepted".to_owned());
    }
    let (artifact_response, run_response, commit_response) =
        provider_metadata_responses(dispatch, &repository)?;
    let artifact = artifact_response.object()?;
    let run = run_response.object()?;
    verify_provider_commit_identity(commit_response.object()?, &dispatch.candidate)?;
    let provider_digest = json_member(artifact, "digest")?
        .string()?
        .strip_prefix("sha256:")
        .ok_or_else(|| "provider artifact digest is not SHA-256".to_owned())?;
    require_digest(provider_digest, "provider artifact archive")?;
    let provider_size = json_member(artifact, "size_in_bytes")?.number()?;
    let created_at = json_member(artifact, "created_at")?.string()?;
    let expires_at = json_member(artifact, "expires_at")?.string()?;
    validate_utc_timestamp(created_at)?;
    validate_utc_timestamp(expires_at)?;
    let archive_url = json_member(artifact, "archive_download_url")?.string()?;
    if json_member(artifact, "id")?.number()? != dispatch.provider_artifact_id
        || json_member(artifact, "name")?.string()? != artifact_name
        || json_member(artifact, "expired")?.boolean()?
        || provider_size == 0
        || utc_timestamp_seconds(expires_at)? <= current_utc_seconds()?
        || utc_timestamp_seconds(created_at)? > utc_timestamp_seconds(&dispatch.acquired_at)?
        || !archive_url
            .starts_with("https://api.github.com/repos/Portfoligno/hell-rs/actions/artifacts/")
        || json_member(json_member(artifact, "workflow_run")?.object()?, "id")?.number()?
            != dispatch
                .run_id
                .parse::<u64>()
                .map_err(|_| "provider run ID is invalid".to_owned())?
        || json_member(run, "id")?.number()?
            != dispatch
                .run_id
                .parse::<u64>()
                .map_err(|_| "provider run ID is invalid".to_owned())?
        || json_member(run, "run_attempt")?.number()?
            != dispatch
                .run_attempt
                .parse::<u64>()
                .map_err(|_| "provider run attempt is invalid".to_owned())?
        || json_member(run, "head_sha")?.string()? != dispatch.candidate
        || provider_run_workflow_ref(json_member(run, "path")?.string()?, &dispatch.workflow_path)
            .is_err()
        || json_member(run, "event")?.string()? != dispatch.provider_event
        || json_member(json_member(run, "repository")?.object()?, "id")?
            .number()?
            .to_string()
            != repository_id
    {
        return Err(
            "provider API metadata does not bind artifact, run, workflow, and candidate".to_owned(),
        );
    }
    let artifact_bytes = canonical_json_bytes(&artifact_response)?;
    let run_bytes = canonical_json_bytes(&run_response)?;
    let commit_bytes = canonical_json_bytes(&commit_response)?;
    fs::create_dir_all(output_directory)
        .map_err(|error| format!("cannot create provider metadata directory: {error}"))?;
    let channel = if primary { "primary" } else { "independent" };
    let artifact_path = output_directory.join(format!("provider-artifact-{channel}.json"));
    let run_path = output_directory.join(format!("provider-run-{channel}.json"));
    let commit_path = output_directory.join(format!("provider-commit-{channel}.json"));
    let selection_path =
        output_directory.join(format!("provider-artifact-selection-{channel}.json"));
    write_atomic(&artifact_path, &artifact_bytes)?;
    write_atomic(&run_path, &run_bytes)?;
    write_atomic(&commit_path, &commit_bytes)?;
    write_atomic(&selection_path, &dispatch.provider_selection_api)?;
    let summary = format!(
        "{{\"schemaVersion\":3,\"artifactId\":{},\"artifactName\":{},\"artifactSelectionApiSha256\":{},\"artifactApiSha256\":{},\"providerArchiveSha256\":{},\"providerArchiveSize\":{},\"createdAt\":{},\"expiresAt\":{},\"archiveDownloadUrl\":{},\"runId\":{},\"runAttempt\":{},\"runApiSha256\":{},\"commitApiSha256\":{},\"candidateCommit\":{},\"workflowPath\":{},\"event\":{},\"repositoryId\":{}}}\n",
        dispatch.provider_artifact_id,
        json_string(artifact_name),
        json_string(&sha256_bytes(&dispatch.provider_selection_api).hex()),
        json_string(&sha256_bytes(&artifact_bytes).hex()),
        json_string(provider_digest),
        provider_size,
        json_string(created_at),
        json_string(expires_at),
        json_string(archive_url),
        dispatch.run_id,
        dispatch.run_attempt,
        json_string(&sha256_bytes(&run_bytes).hex()),
        json_string(&sha256_bytes(&commit_bytes).hex()),
        json_string(&dispatch.candidate),
        json_string(&dispatch.workflow_path),
        json_string(&dispatch.provider_event),
        json_string(repository_id),
    );
    let summary_path = output_directory.join(format!("provider-metadata-{channel}.json"));
    write_atomic(&summary_path, summary.as_bytes())?;
    record_digest(&summary_path)
}

fn provider_metadata_responses(
    dispatch: &AcquisitionDispatch,
    repository: &str,
) -> Result<(JsonValue, JsonValue, JsonValue), String> {
    let (artifact_endpoint, run_endpoint, commit_endpoint) =
        provider_metadata_endpoints(dispatch, repository);
    Ok((
        github_api_json(&artifact_endpoint)?,
        github_api_json(&run_endpoint)?,
        github_api_json(&commit_endpoint)?,
    ))
}

fn provider_metadata_endpoints(
    dispatch: &AcquisitionDispatch,
    repository: &str,
) -> (PathBuf, PathBuf, PathBuf) {
    let repository_path = repository
        .split('/')
        .fold(PathBuf::new(), |path, segment| path.join(segment));
    let artifact_endpoint = PathBuf::from("repos")
        .join(&repository_path)
        .join("actions")
        .join("artifacts")
        .join(dispatch.provider_artifact_id.to_string());
    let run_endpoint = PathBuf::from("repos")
        .join(&repository_path)
        .join("actions")
        .join("runs")
        .join(&dispatch.run_id)
        .join("attempts")
        .join(&dispatch.run_attempt);
    let commit_endpoint = PathBuf::from("repos")
        .join(&repository_path)
        .join("commits")
        .join(&dispatch.candidate);
    (artifact_endpoint, run_endpoint, commit_endpoint)
}

fn verify_provider_commit_identity(
    commit: &BTreeMap<String, JsonValue>,
    candidate: &str,
) -> Result<(), String> {
    if json_member(commit, "sha")?.string()? != candidate
        || !json_member(commit, "html_url")?
            .string()?
            .starts_with("https://github.com/Portfoligno/hell-rs/commit/")
    {
        return Err("provider commit response does not bind the candidate".to_owned());
    }
    for role in ["author", "committer"] {
        let identity = json_member(commit, role)?.object()?;
        let account_id = json_member(identity, "id")?.number()?;
        let login = json_member(identity, "login")?.string()?;
        validate_provider_atom(login, "provider commit identity login")?;
        if account_id == 0 {
            return Err(format!("provider commit {role} has no stable account ID"));
        }
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn verify_provider_artifact_selection(
    root: &Path,
    input_directory: &Path,
    artifact_name: &str,
    workflow_path: &str,
    event_name: &str,
    run_id: u64,
    run_attempt: u64,
    artifact_id: u64,
    candidate: &str,
    expected_directory_sha256: &str,
    expected_archive_sha256: &str,
) -> Result<String, String> {
    verify_provider_artifact_selection_to(
        root,
        input_directory,
        input_directory,
        artifact_name,
        workflow_path,
        event_name,
        run_id,
        run_attempt,
        artifact_id,
        candidate,
        expected_directory_sha256,
        expected_archive_sha256,
    )
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn verify_provider_artifact_selection_to(
    root: &Path,
    input_directory: &Path,
    output_directory: &Path,
    artifact_name: &str,
    workflow_path: &str,
    event_name: &str,
    run_id: u64,
    run_attempt: u64,
    artifact_id: u64,
    candidate: &str,
    expected_directory_sha256: &str,
    expected_archive_sha256: &str,
) -> Result<String, String> {
    verify_provider_artifact_selection_subject_to(&ProviderArtifactSelectionSubject {
        root,
        input_directory,
        output_directory,
        artifact_name,
        workflow_path,
        event_name,
        run_id,
        run_attempt,
        artifact_id,
        provider_head: candidate,
        candidate,
        expected_directory_sha256,
        expected_archive_sha256,
    })
}

pub(crate) struct ProviderArtifactSelectionSubject<'a> {
    pub(crate) root: &'a Path,
    pub(crate) input_directory: &'a Path,
    pub(crate) output_directory: &'a Path,
    pub(crate) artifact_name: &'a str,
    pub(crate) workflow_path: &'a str,
    pub(crate) event_name: &'a str,
    pub(crate) run_id: u64,
    pub(crate) run_attempt: u64,
    pub(crate) artifact_id: u64,
    pub(crate) provider_head: &'a str,
    pub(crate) candidate: &'a str,
    pub(crate) expected_directory_sha256: &'a str,
    pub(crate) expected_archive_sha256: &'a str,
}

pub(crate) fn verify_provider_artifact_selection_subject_to(
    request: &ProviderArtifactSelectionSubject<'_>,
) -> Result<String, String> {
    let ProviderArtifactSelectionSubject {
        root,
        input_directory,
        output_directory,
        artifact_name,
        workflow_path,
        event_name,
        run_id,
        run_attempt,
        artifact_id,
        provider_head,
        candidate,
        expected_directory_sha256,
        expected_archive_sha256,
    } = *request;
    let workflow_relative = validate_provider_selection_subject(request)?;
    let observed_directory_sha256 = record_digest(input_directory)?;
    if observed_directory_sha256 != expected_directory_sha256 {
        return Err("provider-selected directory digest differs from dispatch".to_owned());
    }
    require_digest(
        expected_archive_sha256,
        "provider selection expected archive",
    )?;
    let (repository, repository_id) = provider_selection_repository_identity()?;
    if repository != "Portfoligno/hell-rs" {
        return Err("provider selection repository is not accepted".to_owned());
    }
    let (artifact_endpoint, run_endpoint) =
        provider_selection_endpoints(&repository, artifact_id, run_id, run_attempt);
    let artifact_response = github_api_json(&artifact_endpoint)?;
    let run_response = github_api_json(&run_endpoint)?;
    let artifact = artifact_response.object()?;
    let run = run_response.object()?;
    let provider_archive_sha256 = json_member(artifact, "digest")?
        .string()?
        .strip_prefix("sha256:")
        .ok_or_else(|| "provider-selected artifact digest is not SHA-256".to_owned())?;
    require_digest(provider_archive_sha256, "provider-selected archive")?;
    if provider_archive_sha256 != expected_archive_sha256 {
        return Err("provider-selected archive digest differs from dispatch".to_owned());
    }
    let provider_archive_size = json_member(artifact, "size_in_bytes")?.number()?;
    let created_at = json_member(artifact, "created_at")?.string()?;
    let expires_at = json_member(artifact, "expires_at")?.string()?;
    validate_utc_timestamp(created_at)?;
    validate_utc_timestamp(expires_at)?;
    if json_member(artifact, "id")?.number()? != artifact_id
        || json_member(artifact, "name")?.string()? != artifact_name
        || json_member(artifact, "expired")?.boolean()?
        || provider_archive_size == 0
        || utc_timestamp_seconds(expires_at)? <= current_utc_seconds()?
        || json_member(json_member(artifact, "workflow_run")?.object()?, "id")?.number()? != run_id
        || json_member(run, "id")?.number()? != run_id
        || json_member(run, "run_attempt")?.number()? != run_attempt
        || json_member(run, "head_sha")?.string()? != provider_head
        || provider_run_workflow_ref(json_member(run, "path")?.string()?, workflow_path).is_err()
        || json_member(run, "event")?.string()? != event_name
        || json_member(json_member(run, "repository")?.object()?, "id")?
            .number()?
            .to_string()
            != repository_id
    {
        return Err(
            "provider API metadata does not bind the selected artifact and producing run"
                .to_owned(),
        );
    }
    let archive_download_url = json_member(artifact, "archive_download_url")?.string()?;
    if !archive_download_url
        .starts_with("https://api.github.com/repos/Portfoligno/hell-rs/actions/artifacts/")
    {
        return Err("provider-selected archive URL is outside the repository API".to_owned());
    }
    let artifact_bytes = canonical_json_bytes(&artifact_response)?;
    let run_bytes = canonical_json_bytes(&run_response)?;
    retain_provider_selection_responses(output_directory, &artifact_bytes, &run_bytes)?;
    let workflow_sha256 = record_digest(&root.join(&workflow_relative))?;
    Ok(render_provider_selection(&ProviderSelection {
        artifact_name,
        workflow_path,
        event_name,
        run_id,
        run_attempt,
        artifact_id,
        candidate,
        directory_sha256: &observed_directory_sha256,
        workflow_sha256: &workflow_sha256,
        repository_id: &repository_id,
        artifact_bytes: &artifact_bytes,
        run_bytes: &run_bytes,
        provider_archive_sha256,
        provider_archive_size,
        created_at,
        expires_at,
        archive_download_url,
    }))
}

fn provider_selection_repository_identity() -> Result<(String, String), String> {
    #[cfg(test)]
    if TEST_GITHUB_API.with(|api| api.borrow().is_some()) {
        return Ok(("Portfoligno/hell-rs".to_owned(), "1327351238".to_owned()));
    }
    Ok((
        std::env::var("GITHUB_REPOSITORY")
            .map_err(|_| "provider selection requires GITHUB_REPOSITORY".to_owned())?,
        std::env::var("GITHUB_REPOSITORY_ID")
            .map_err(|_| "provider selection requires GITHUB_REPOSITORY_ID".to_owned())?,
    ))
}

fn validate_provider_selection_subject(
    request: &ProviderArtifactSelectionSubject<'_>,
) -> Result<PathBuf, String> {
    require_git_sha_text(request.provider_head, "provider selection workflow head")?;
    require_git_sha_text(request.candidate, "provider selection candidate")?;
    require_digest(
        request.expected_directory_sha256,
        "provider selection directory digest",
    )?;
    require_digest(
        request.expected_archive_sha256,
        "provider selection archive digest",
    )?;
    if request.run_id == 0 || request.run_attempt == 0 || request.artifact_id == 0 {
        return Err("provider selection identifiers must be nonzero".to_owned());
    }
    validate_provider_atom(request.artifact_name, "provider artifact name")?;
    validate_provider_atom(request.event_name, "provider run event")?;
    let relative = validate_provider_workflow_path(request.workflow_path)?;
    if !relative.starts_with(Path::new(".github").join("workflows")) {
        return Err("provider workflow is outside .github/workflows".to_owned());
    }
    Ok(relative)
}

fn retain_provider_selection_responses(
    output_directory: &Path,
    artifact_bytes: &[u8],
    run_bytes: &[u8],
) -> Result<(), String> {
    fs::create_dir_all(output_directory)
        .map_err(|error| format!("cannot create provider selection output: {error}"))?;
    write_atomic(
        &output_directory.join("provider-selected-artifact.json"),
        artifact_bytes,
    )?;
    write_atomic(
        &output_directory.join("provider-selected-run.json"),
        run_bytes,
    )
}

fn provider_selection_endpoints(
    repository: &str,
    artifact_id: u64,
    run_id: u64,
    run_attempt: u64,
) -> (PathBuf, PathBuf) {
    let repository_path = repository
        .split('/')
        .fold(PathBuf::new(), |path, segment| path.join(segment));
    let base = PathBuf::from("repos").join(repository_path);
    let artifact = base
        .join("actions")
        .join("artifacts")
        .join(artifact_id.to_string());
    let run = base
        .join("actions")
        .join("runs")
        .join(run_id.to_string())
        .join("attempts")
        .join(run_attempt.to_string());
    (artifact, run)
}

struct ProviderSelection<'a> {
    artifact_name: &'a str,
    workflow_path: &'a str,
    event_name: &'a str,
    run_id: u64,
    run_attempt: u64,
    artifact_id: u64,
    candidate: &'a str,
    directory_sha256: &'a str,
    workflow_sha256: &'a str,
    repository_id: &'a str,
    artifact_bytes: &'a [u8],
    run_bytes: &'a [u8],
    provider_archive_sha256: &'a str,
    provider_archive_size: u64,
    created_at: &'a str,
    expires_at: &'a str,
    archive_download_url: &'a str,
}

fn render_provider_selection(selection: &ProviderSelection<'_>) -> String {
    let string = |value: &str| JsonValue::String(value.to_owned());
    let document = JsonValue::Object(BTreeMap::from([
        ("artifact".to_owned(), string(selection.artifact_name)),
        ("candidateCommit".to_owned(), string(selection.candidate)),
        (
            "directorySha256".to_owned(),
            string(selection.directory_sha256),
        ),
        ("event".to_owned(), string(selection.event_name)),
        (
            "providerArchiveSha256".to_owned(),
            string(selection.provider_archive_sha256),
        ),
        (
            "providerArchiveSize".to_owned(),
            JsonValue::Number(selection.provider_archive_size),
        ),
        (
            "providerArchiveUrl".to_owned(),
            string(selection.archive_download_url),
        ),
        (
            "providerArtifactApiPath".to_owned(),
            string("provider-selected-artifact.json"),
        ),
        (
            "providerArtifactApiSha256".to_owned(),
            string(&sha256_bytes(selection.artifact_bytes).hex()),
        ),
        (
            "providerArtifactId".to_owned(),
            JsonValue::Number(selection.artifact_id),
        ),
        ("providerCreatedAt".to_owned(), string(selection.created_at)),
        ("providerExpiresAt".to_owned(), string(selection.expires_at)),
        (
            "providerRunApiPath".to_owned(),
            string("provider-selected-run.json"),
        ),
        (
            "providerRunApiSha256".to_owned(),
            string(&sha256_bytes(selection.run_bytes).hex()),
        ),
        (
            "providerRunAttempt".to_owned(),
            JsonValue::Number(selection.run_attempt),
        ),
        (
            "providerRunId".to_owned(),
            JsonValue::Number(selection.run_id),
        ),
        ("repositoryId".to_owned(), string(selection.repository_id)),
        ("schemaVersion".to_owned(), JsonValue::Number(1)),
        ("selectionState".to_owned(), string("exact-provider-object")),
        (
            "workflowBlobSha256".to_owned(),
            string(selection.workflow_sha256),
        ),
        ("workflowPath".to_owned(), string(selection.workflow_path)),
    ]));
    String::from_utf8(canonical_json_bytes(&document).expect("provider selection JSON is valid"))
        .expect("provider selection JSON is UTF-8")
}

fn validate_provider_atom(value: &str, label: &str) -> Result<(), String> {
    if value.is_empty()
        || !value
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'.' | b'_' | b'-'))
    {
        return Err(format!("{label} is not a normalized provider atom"));
    }
    Ok(())
}

fn validate_provider_workflow_path(value: &str) -> Result<PathBuf, String> {
    let path = Path::new(value);
    if path.is_absolute()
        || path.components().any(|component| {
            !matches!(component, std::path::Component::Normal(_))
                || component.as_os_str().to_str().is_none_or(str::is_empty)
        })
    {
        return Err("provider workflow path is not normalized and relative".to_owned());
    }
    Ok(path.to_path_buf())
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ExternalServiceOperation {
    EvidenceCollection,
    ProtectedAdmission,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ExternalServiceFailureDisposition {
    RetryCollection,
    RejectAdmission,
}

fn external_service_failure_disposition(
    operation: ExternalServiceOperation,
    diagnostic: &str,
) -> ExternalServiceFailureDisposition {
    let transient = [
        "HTTP 429",
        "HTTP 502",
        "HTTP 503",
        "HTTP 504",
        "rate limit",
        "connection reset",
        "timed out",
    ]
    .iter()
    .any(|marker| {
        diagnostic
            .to_ascii_lowercase()
            .contains(&marker.to_ascii_lowercase())
    });
    if operation == ExternalServiceOperation::EvidenceCollection && transient {
        ExternalServiceFailureDisposition::RetryCollection
    } else {
        ExternalServiceFailureDisposition::RejectAdmission
    }
}

fn external_service_error(
    context: &str,
    operation: ExternalServiceOperation,
    diagnostic: &str,
) -> String {
    let disposition = match external_service_failure_disposition(operation, diagnostic) {
        ExternalServiceFailureDisposition::RetryCollection => "retryable-collection-failure",
        ExternalServiceFailureDisposition::RejectAdmission => "admission-rejected",
    };
    format!("{context} [{disposition}]: {diagnostic}")
}

fn github_api_json(endpoint: &Path) -> Result<JsonValue, String> {
    github_api_json_for(endpoint, ExternalServiceOperation::EvidenceCollection)
}

fn github_api_json_for(
    endpoint: &Path,
    operation: ExternalServiceOperation,
) -> Result<JsonValue, String> {
    #[cfg(test)]
    if let Some(result) = invoke_test_github_api(endpoint, operation) {
        return result;
    }
    let mut command = Command::new("gh");
    command.args([OsStr::new("api"), endpoint.as_os_str()]);
    command
        .env_remove("AWS_ACCESS_KEY_ID")
        .env_remove("AWS_SECRET_ACCESS_KEY")
        .env_remove("AWS_SESSION_TOKEN");
    if let Ok(token) = std::env::var("GITHUB_TOKEN") {
        command.env("GH_TOKEN", token).env_remove("GITHUB_TOKEN");
    }
    let response = command
        .output()
        .map_err(|error| format!("cannot query GitHub artifact metadata: {error}"))?;
    if !response.status.success() {
        return Err(external_service_error(
            "GitHub API query failed",
            operation,
            &String::from_utf8_lossy(&response.stderr),
        ));
    }
    parse_json(
        std::str::from_utf8(&response.stdout)
            .map_err(|_| "GitHub artifact metadata is not UTF-8".to_owned())?,
    )
}

#[cfg(test)]
type TestGithubApi = Box<dyn Fn(&Path, ExternalServiceOperation) -> Result<JsonValue, String>>;

#[cfg(test)]
std::thread_local! {
    static TEST_GITHUB_API: std::cell::RefCell<Option<TestGithubApi>> =
        std::cell::RefCell::new(None);
}

#[cfg(test)]
fn invoke_test_github_api(
    endpoint: &Path,
    operation: ExternalServiceOperation,
) -> Option<Result<JsonValue, String>> {
    TEST_GITHUB_API.with(|api| api.borrow().as_ref().map(|api| api(endpoint, operation)))
}

#[cfg(test)]
struct TestGithubApiGuard;

#[cfg(test)]
impl TestGithubApiGuard {
    fn install(api: TestGithubApi) -> Result<Self, String> {
        TEST_GITHUB_API.with(|slot| {
            let mut slot = slot.borrow_mut();
            if slot.is_some() {
                return Err("test GitHub API is already installed".to_owned());
            }
            *slot = Some(api);
            Ok(Self)
        })
    }
}

#[cfg(test)]
impl Drop for TestGithubApiGuard {
    fn drop(&mut self) {
        TEST_GITHUB_API.with(|slot| {
            slot.borrow_mut().take();
        });
    }
}

pub(crate) fn github_raw_source_at(
    repository: &str,
    relative: &str,
    commit: &str,
) -> Result<Vec<u8>, String> {
    require_git_sha_text(commit, "provider source commit")?;
    let repository_path = repository
        .split('/')
        .fold(PathBuf::new(), |path, component| path.join(component));
    let relative_path = validate_provider_workflow_path(relative)?;
    let endpoint = PathBuf::from("repos")
        .join(repository_path)
        .join("contents")
        .join(relative_path);
    let mut reference = String::with_capacity("ref=".len().saturating_add(commit.len()));
    reference.push_str("ref=");
    reference.push_str(commit);
    if reference.strip_prefix("ref=") != Some(commit) {
        return Err("provider source ref encoding failed to round trip".to_owned());
    }
    let token = std::env::var("GITHUB_TOKEN")
        .map_err(|_| "provider source query requires GITHUB_TOKEN".to_owned())?;
    let response = Command::new("gh")
        .args([
            OsStr::new("api"),
            OsStr::new("--method"),
            OsStr::new("GET"),
            endpoint.as_os_str(),
            OsStr::new("-f"),
            OsStr::new(&reference),
            OsStr::new("--header"),
            OsStr::new("Accept: application/vnd.github.raw+json"),
        ])
        .env("GH_TOKEN", token)
        .env_remove("GITHUB_TOKEN")
        .output()
        .map_err(|error| format!("cannot query provider source: {error}"))?;
    if !response.status.success() || response.stdout.is_empty() {
        return Err("provider source query failed or returned empty bytes".to_owned());
    }
    Ok(response.stdout)
}

fn github_api_json_named_artifact(
    endpoint: &Path,
    artifact_name: &str,
) -> Result<JsonValue, String> {
    let query = GithubArtifactNameQuery::new(endpoint, artifact_name)?.argument()?;
    #[cfg(test)]
    if let Some(result) = invoke_test_github_api(
        Path::new(&query),
        ExternalServiceOperation::EvidenceCollection,
    ) {
        return result;
    }
    let response = Command::new("gh")
        .args([OsStr::new("api"), query.as_os_str()])
        .output()
        .map_err(|error| format!("cannot query named GitHub artifact metadata: {error}"))?;
    if !response.status.success() {
        return Err(format!(
            "named GitHub artifact metadata query failed: {}",
            String::from_utf8_lossy(&response.stderr)
        ));
    }
    parse_json(
        std::str::from_utf8(&response.stdout)
            .map_err(|_| "named GitHub artifact metadata is not UTF-8".to_owned())?,
    )
}

struct GithubArtifactNameQuery {
    endpoint: PathBuf,
    artifact_name: String,
}

impl GithubArtifactNameQuery {
    fn new(endpoint: &Path, artifact_name: &str) -> Result<Self, String> {
        validate_provider_atom(artifact_name, "provider artifact name")?;
        if endpoint.as_os_str().is_empty()
            || endpoint.is_absolute()
            || endpoint.components().any(|component| {
                !matches!(component, std::path::Component::Normal(_))
                    || component.as_os_str().to_str().is_none_or(str::is_empty)
            })
        {
            return Err("GitHub API endpoint is not a normalized relative path".to_owned());
        }
        Ok(Self {
            endpoint: endpoint.to_path_buf(),
            artifact_name: artifact_name.to_owned(),
        })
    }

    fn argument(&self) -> Result<OsString, String> {
        let endpoint = self
            .endpoint
            .to_str()
            .ok_or_else(|| "GitHub API endpoint is not UTF-8".to_owned())?;
        let mut argument = String::with_capacity(
            endpoint
                .len()
                .saturating_add(self.artifact_name.len())
                .saturating_add("?name=".len()),
        );
        argument.push_str(endpoint);
        argument.push_str("?name=");
        for byte in self.artifact_name.bytes() {
            if byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'.' | b'_' | b'~') {
                argument.push(char::from(byte));
            } else {
                write!(argument, "%{byte:02X}").expect("writing to String cannot fail");
            }
        }
        Ok(OsString::from(argument))
    }
}

pub(crate) fn canonical_json_bytes(value: &JsonValue) -> Result<Vec<u8>, String> {
    let mut output = String::new();
    push_json_value(&mut output, value)?;
    output.push('\n');
    Ok(output.into_bytes())
}

#[allow(clippy::too_many_lines)]
fn artifact_verify(root: &Path, options: &Options) -> Result<String, String> {
    let acquisition_policy = load_acquisition_policy(root)?;
    let input = required_path(
        &options.input,
        "artifact-verify requires --input receipt directory",
    )?;
    let policy = required_path(
        &options.policy,
        "artifact-verify requires --policy allowed-signers",
    )?;
    let primary = parse_acquisition_receipt(&input.join("receipt-primary.json"))?;
    let independent = parse_acquisition_receipt(&input.join("receipt-independent.json"))?;
    let producer_attestations =
        verify_artifact_receipt_attestations(input, policy, &primary, &independent)?;
    verify_provider_metadata(input, &primary, "primary")?;
    verify_provider_metadata(input, &independent, "independent")?;
    if primary.artifact != independent.artifact
        || primary.observed_sha256 != independent.observed_sha256
        || primary.observed_size != independent.observed_size
        || primary.provider_artifact_id != independent.provider_artifact_id
        || primary.repository_id != independent.repository_id
        || primary.workflow_path != independent.workflow_path
        || primary.workflow_sha256 != independent.workflow_sha256
        || primary.run_id != independent.run_id
        || primary.run_attempt != independent.run_attempt
        || primary.candidate_commit != independent.candidate_commit
        || primary.provider_event != independent.provider_event
    {
        return Err("independent acquisition receipt identities disagree".to_owned());
    }
    verify_independent_trust_domains(&primary.trust_domain, &independent.trust_domain)?;
    if u64::try_from(BTreeSet::from([&primary.trust_domain, &independent.trust_domain]).len())
        .map_err(|_| "acquisition trust-domain count exceeds u64".to_owned())?
        < acquisition_policy.minimum_trust_domains
    {
        return Err("acquisition evidence has too few authoritative trust domains".to_owned());
    }
    if u64::try_from([&primary, &independent].len())
        .map_err(|_| "acquisition count exceeds u64".to_owned())?
        < acquisition_policy.minimum_acquisitions
        || primary.channel_class != acquisition_policy.required_channel_classes[0]
        || primary.trust_domain != "github.com"
        || independent.channel_class != acquisition_policy.required_channel_classes[1]
        || !independent.trust_domain.starts_with("aws-s3-account:")
    {
        return Err(
            "acquisition receipts do not use the declared independent channel classes".to_owned(),
        );
    }
    if primary.acquisition_event != "workflow_dispatch"
        || independent.acquisition_event != "workflow_dispatch"
        || primary.acquisition_tool
            != "actions/download-artifact@70fc10c6e5e1ce46ad2ea6f2b72d43f7d47b13c3"
        || independent.acquisition_tool != "curl-aws-sigv4-v1"
    {
        return Err("acquisition event or tool identity is not accepted".to_owned());
    }
    if primary.channel_class == independent.channel_class
        || primary.acquirer_account_id == independent.acquirer_account_id
    {
        return Err("acquisitions are not independently produced".to_owned());
    }
    let primary_path = confined_record_path(root, input, &primary.local_path)?;
    let independent_path = confined_record_path(root, input, &independent.local_path)?;
    if primary_path == independent_path {
        return Err("acquisitions do not retain independent artifact copies".to_owned());
    }
    if primary.repository_id == "REVIEW_REQUIRED" || primary.run_id == 0 || primary.run_attempt == 0
    {
        return Err("acquisition receipt lacks immutable repository/run identity".to_owned());
    }
    let expected_repository_id = acquisition_policy.repository_id.ok_or_else(|| {
        "acquisition repository ID remains REVIEW_REQUIRED in authoritative policy".to_owned()
    })?;
    if primary.repository_id != expected_repository_id {
        return Err("acquisition repository ID is not an accepted immutable identity".to_owned());
    }
    if acquisition_policy.repository != "Portfoligno/hell-rs"
        || primary.workflow_path != acquisition_policy.workflow
    {
        return Err(
            "acquisition receipt differs from authoritative repository/workflow".to_owned(),
        );
    }
    let current_candidate = git_output(root, &["rev-parse", "HEAD"])?;
    if primary.candidate_commit != current_candidate.trim() {
        return Err("acquisition receipts do not bind the current candidate".to_owned());
    }
    let workflow = fs::read(root.join(&primary.workflow_path))
        .map_err(|error| format!("cannot read acquisition workflow: {error}"))?;
    if sha256_bytes(&workflow).hex() != primary.workflow_sha256 {
        return Err("acquisition workflow blob digest does not match candidate source".to_owned());
    }
    for (receipt, path) in [(&primary, &primary_path), (&independent, &independent_path)] {
        if record_digest(path)? != receipt.observed_sha256
            || record_size(path)? != receipt.observed_size
        {
            return Err("acquired artifact bytes no longer match receipt".to_owned());
        }
    }
    if primary.trust_review_ref != independent.trust_review_ref {
        return Err("acquisition receipts bind different trust reviews".to_owned());
    }
    let review_path = input.join("trust-review.dsse.json");
    let review_bytes = read_regular_file(&review_path)?;
    if sha256_bytes(&review_bytes).hex() != primary.trust_review_ref {
        return Err("artifact trust review digest mismatch".to_owned());
    }
    let review = verify_review_envelope(&review_path, policy)?;
    let (_, current_epoch) = epoch(root)?;
    let attestation_digest = verify_artifact_attestation(
        &input.join("attestation-verification.json"),
        &primary.observed_sha256,
        &primary.artifact,
        &primary.candidate_commit,
    )?;
    let primary_digest = acquisition_receipt_core_digest(&primary);
    let independent_digest = acquisition_receipt_core_digest(&independent);
    if review.role != "artifact-trust-reviewer"
        || review.candidate_commit != primary.candidate_commit
        || review.assurance_epoch != current_epoch.hex()
        || ![
            &primary_digest,
            &independent_digest,
            &primary.observed_sha256,
            &attestation_digest,
            &producer_attestations[0].digest,
            &producer_attestations[1].digest,
        ]
        .into_iter()
        .all(|digest| review.reviewed_artifacts.contains(digest))
    {
        return Err(
            "artifact trust review does not bind receipts, bytes, candidate, and epoch".to_owned(),
        );
    }
    Ok(format!(
        "verified two-domain acquisition and signed trust review for {}",
        primary.artifact
    ))
}

fn verify_external_acquisition_evidence(
    input: &Path,
    receipt: &AcquisitionReceipt,
) -> Result<(), String> {
    let relative = receipt
        .external_acquisition_path
        .as_deref()
        .ok_or_else(|| "independent receipt lacks external acquisition evidence".to_owned())?;
    if relative != Path::new("external-acquisition.json") {
        return Err("external acquisition evidence path is not canonical".to_owned());
    }
    let path = input.join(relative);
    let expected = receipt
        .external_acquisition_sha256
        .as_deref()
        .ok_or_else(|| "independent receipt lacks external acquisition digest".to_owned())?;
    verify_file_digest(&path, expected, "external acquisition evidence")?;
    let evidence = parse_json(&read_text(&path)?)?;
    let evidence = evidence.object()?;
    verify_external_acquisition_keys(evidence)?;
    let request_url = external_s3_object_url(
        json_member(evidence, "bucket")?.string()?,
        json_member(evidence, "key")?.string()?,
        json_member(evidence, "versionId")?.string()?,
        json_member(evidence, "region")?.string()?,
    )?;
    let expected_paths = [
        ("archivePath", "external-provider-object.zip"),
        ("extractedPath", "independent"),
        ("responseHeadersPath", "external-provider-headers.txt"),
        ("tlsEvidencePath", "external-provider-tls.json"),
    ];
    if expected_paths.iter().any(|(field, expected)| {
        json_member(evidence, field).and_then(JsonValue::string) != Ok(*expected)
    }) {
        return Err("external acquisition retained paths are not canonical".to_owned());
    }
    let archive = input.join("external-provider-object.zip");
    let extracted = input.join("independent");
    let headers = input.join("external-provider-headers.txt");
    let tls = input.join("external-provider-tls.json");
    for (path, digest) in [
        (&archive, "archiveSha256"),
        (&extracted, "extractedSha256"),
        (&headers, "responseHeadersSha256"),
        (&tls, "tlsEvidenceSha256"),
    ] {
        let expected = json_member(evidence, digest)?.string()?;
        require_digest(expected, digest)?;
        if record_digest(path)? != expected {
            return Err(format!("external acquisition {digest} is substituted"));
        }
    }
    let tls_document = parse_json(&read_text(&tls)?)?;
    let tls_document = tls_document.object()?;
    let response = external_response_headers(&read_text(&headers)?)?;
    verify_external_acquisition_identity(evidence, receipt, &request_url)?;
    if json_member(evidence, "schemaVersion")?.number()? != 1
        || json_member(evidence, "provider")?.string()? != "aws-s3"
        || json_member(evidence, "requestUrl")?.string()? != request_url
        || json_member(evidence, "requestUrlSha256")?.string()?
            != sha256_bytes(request_url.as_bytes()).hex()
        || json_member(evidence, "effectiveUrlSha256")?.string()?
            != sha256_bytes(request_url.as_bytes()).hex()
        || json_member(evidence, "httpStatus")?.number()? != 200
        || json_member(evidence, "sslVerifyResult")?.number()? != 0
        || json_member(evidence, "contentLength")?.number()? != record_size(&archive)?
        || json_member(evidence, "archiveSize")?.number()? != record_size(&archive)?
        || json_member(evidence, "etag")?.string()? != response.0
        || json_member(evidence, "lastModified")?.string()? != response.1
        || json_member(evidence, "responseVersionId")?.string()? != response.3
        || json_member(evidence, "acquirerAccountId")?.number()? != receipt.acquirer_account_id
        || json_member(evidence, "acquirerLogin")?.string()? != receipt.acquirer_login
        || json_member(evidence, "extractedSha256")?.string()? != receipt.observed_sha256
        || json_member(evidence, "providerAccountId")?.string()?
            != receipt
                .trust_domain
                .strip_prefix("aws-s3-account:")
                .unwrap_or_default()
        || [
            ("tlsHost", "host"),
            ("tlsSubject", "subject"),
            ("tlsIssuer", "issuer"),
            ("tlsCertificateSha256", "certificateSha256"),
            ("tlsSpkiSha256", "spkiSha256"),
        ]
        .into_iter()
        .any(|(outer, inner)| {
            json_member(evidence, outer).and_then(JsonValue::string)
                != json_member(tls_document, inner).and_then(JsonValue::string)
        })
    {
        return Err("external acquisition evidence does not reproduce retained facts".to_owned());
    }
    Ok(())
}

fn verify_external_acquisition_identity(
    evidence: &BTreeMap<String, JsonValue>,
    receipt: &AcquisitionReceipt,
    request_url: &str,
) -> Result<(), String> {
    let host = format!(
        "{}.s3.{}.amazonaws.com",
        json_member(evidence, "bucket")?.string()?,
        json_member(evidence, "region")?.string()?
    );
    let redirects = json_member(evidence, "redirectHosts")?.array()?;
    let provider_account = json_member(evidence, "providerAccountId")?.string()?;
    let provider_arn = json_member(evidence, "providerPrincipalArn")?.string()?;
    let provider_principal = json_member(evidence, "providerPrincipalId")?.string()?;
    validate_external_identity(provider_account, provider_arn, provider_principal)?;
    validate_utc_timestamp(json_member(evidence, "acquiredAt")?.string()?)?;
    let expected_repository = receipt
        .repository_id
        .parse::<u64>()
        .map_err(|_| "artifact acquisition repository ID is not numeric".to_owned())?;
    if redirects.len() != 1
        || redirects[0].string()? != host
        || json_member(evidence, "tlsHost")?.string()? != host
        || json_member(evidence, "requestUrl")?.string()? != request_url
        || json_member(evidence, "repositoryId")?.number()? != expected_repository
        || json_member(evidence, "runId")?.number()? != receipt.acquisition_run_id
        || json_member(evidence, "runAttempt")?.number()? != receipt.acquisition_run_attempt
        || json_member(evidence, "workflowRef")?.string()? != receipt.acquisition_workflow_ref
        || json_member(evidence, "acquiredAt")?.string()? != receipt.acquired_at
        || json_member(evidence, "curlVersion")?.string()?.is_empty()
        || json_member(evidence, "awsCliVersion")?.string()?.is_empty()
    {
        return Err("external acquisition execution identity is not exact".to_owned());
    }
    Ok(())
}

fn verify_external_acquisition_keys(evidence: &BTreeMap<String, JsonValue>) -> Result<(), String> {
    exact_keys(
        evidence,
        &[
            "acquiredAt",
            "acquirerAccountId",
            "acquirerLogin",
            "archivePath",
            "archiveSha256",
            "archiveSize",
            "awsCliVersion",
            "bucket",
            "contentLength",
            "curlVersion",
            "effectiveUrlSha256",
            "etag",
            "extractedPath",
            "extractedSha256",
            "httpStatus",
            "key",
            "lastModified",
            "provider",
            "providerAccountId",
            "providerPrincipalArn",
            "providerPrincipalId",
            "redirectHosts",
            "region",
            "repositoryId",
            "requestUrl",
            "requestUrlSha256",
            "responseHeadersPath",
            "responseHeadersSha256",
            "responseVersionId",
            "runAttempt",
            "runId",
            "schemaVersion",
            "sslVerifyResult",
            "tlsCertificateSha256",
            "tlsEvidencePath",
            "tlsEvidenceSha256",
            "tlsHost",
            "tlsIssuer",
            "tlsSpkiSha256",
            "tlsSubject",
            "versionId",
            "workflowRef",
        ],
    )
}

fn verify_provider_metadata(
    input: &Path,
    receipt: &AcquisitionReceipt,
    channel: &str,
) -> Result<(), String> {
    let summary_path = input.join(format!("provider-metadata-{channel}.json"));
    if record_digest(&summary_path)? != receipt.provider_metadata_sha256 {
        return Err("provider metadata summary digest does not match receipt".to_owned());
    }
    let summary = parse_json(&read_text(&summary_path)?)?;
    let summary = summary.object()?;
    exact_keys(
        summary,
        &[
            "artifactApiSha256",
            "artifactId",
            "artifactName",
            "artifactSelectionApiSha256",
            "archiveDownloadUrl",
            "candidateCommit",
            "commitApiSha256",
            "createdAt",
            "event",
            "expiresAt",
            "providerArchiveSha256",
            "providerArchiveSize",
            "repositoryId",
            "runApiSha256",
            "runAttempt",
            "runId",
            "schemaVersion",
            "workflowPath",
        ],
    )?;
    if json_member(summary, "schemaVersion")?.number()? != 3
        || json_member(summary, "artifactId")?.number()? != receipt.provider_artifact_id
        || json_member(summary, "artifactName")?.string()? != receipt.artifact
        || json_member(summary, "runId")?.number()? != receipt.run_id
        || json_member(summary, "runAttempt")?.number()? != receipt.run_attempt
        || json_member(summary, "candidateCommit")?.string()? != receipt.candidate_commit
        || json_member(summary, "workflowPath")?.string()? != receipt.workflow_path
        || json_member(summary, "event")?.string()? != receipt.provider_event
        || json_member(summary, "repositoryId")?.string()? != receipt.repository_id
        || json_member(summary, "providerArchiveSize")?.number()? == 0
        || utc_timestamp_seconds(json_member(summary, "expiresAt")?.string()?)?
            <= current_utc_seconds()?
        || !json_member(summary, "archiveDownloadUrl")?
            .string()?
            .starts_with("https://api.github.com/repos/Portfoligno/hell-rs/actions/artifacts/")
    {
        return Err("provider metadata does not bind acquisition identity".to_owned());
    }
    for (file, field) in [
        (
            format!("provider-artifact-selection-{channel}.json"),
            "artifactSelectionApiSha256",
        ),
        (
            format!("provider-artifact-{channel}.json"),
            "artifactApiSha256",
        ),
        (format!("provider-run-{channel}.json"), "runApiSha256"),
        (format!("provider-commit-{channel}.json"), "commitApiSha256"),
    ] {
        verify_file_digest(
            &input.join(file),
            json_member(summary, field)?.string()?,
            field,
        )?;
    }
    require_digest(
        json_member(summary, "providerArchiveSha256")?.string()?,
        "provider archive digest",
    )?;
    verify_provider_selection_record(input, receipt, channel)?;
    verify_provider_metadata_time(summary, receipt)?;
    verify_raw_provider_artifact(input, summary, channel)?;
    verify_raw_provider_commit(input, summary, channel)?;
    Ok(())
}

fn verify_raw_provider_commit(
    input: &Path,
    summary: &BTreeMap<String, JsonValue>,
    channel: &str,
) -> Result<(), String> {
    let path = input.join(format!("provider-commit-{channel}.json"));
    verify_file_digest(
        &path,
        json_member(summary, "commitApiSha256")?.string()?,
        "provider commit API response",
    )?;
    let commit = parse_json(&read_text(&path)?)?;
    verify_provider_commit_identity(
        commit.object()?,
        json_member(summary, "candidateCommit")?.string()?,
    )
}

fn verify_provider_selection_record(
    input: &Path,
    receipt: &AcquisitionReceipt,
    channel: &str,
) -> Result<(), String> {
    let selection = parse_json(&read_text(
        &input.join(format!("provider-artifact-selection-{channel}.json")),
    )?)?;
    let selection = selection.object()?;
    let selected = json_member(selection, "artifacts")?.array()?;
    if json_member(selection, "total_count")?.number()? != 1 || selected.len() != 1 {
        return Err("retained provider selection is not unique".to_owned());
    }
    let selected = selected[0].object()?;
    if json_member(selected, "id")?.number()? != receipt.provider_artifact_id
        || json_member(selected, "name")?.string()? != receipt.artifact
        || json_member(selected, "expired")?.boolean()?
        || json_member(json_member(selected, "workflow_run")?.object()?, "id")?.number()?
            != receipt.run_id
    {
        return Err("retained provider selection does not bind the receipt".to_owned());
    }
    Ok(())
}

fn verify_provider_metadata_time(
    summary: &BTreeMap<String, JsonValue>,
    receipt: &AcquisitionReceipt,
) -> Result<(), String> {
    validate_utc_timestamp(json_member(summary, "createdAt")?.string()?)?;
    validate_utc_timestamp(json_member(summary, "expiresAt")?.string()?)?;
    let acquired = utc_timestamp_seconds(&receipt.acquired_at)?;
    if utc_timestamp_seconds(json_member(summary, "createdAt")?.string()?)? > acquired
        || acquired > current_utc_seconds()?
    {
        return Err(
            "artifact acquisition time is future-dated or predates provider creation".to_owned(),
        );
    }
    Ok(())
}

fn verify_raw_provider_artifact(
    input: &Path,
    summary: &BTreeMap<String, JsonValue>,
    channel: &str,
) -> Result<(), String> {
    let artifact_api = parse_json(&read_text(
        &input.join(format!("provider-artifact-{channel}.json")),
    )?)?;
    let artifact_api = artifact_api.object()?;
    let raw_digest = json_member(artifact_api, "digest")?
        .string()?
        .strip_prefix("sha256:")
        .ok_or_else(|| "provider raw artifact digest is not SHA-256".to_owned())?;
    if raw_digest != json_member(summary, "providerArchiveSha256")?.string()?
        || json_member(artifact_api, "size_in_bytes")?.number()?
            != json_member(summary, "providerArchiveSize")?.number()?
        || json_member(artifact_api, "created_at")?.string()?
            != json_member(summary, "createdAt")?.string()?
        || json_member(artifact_api, "expires_at")?.string()?
            != json_member(summary, "expiresAt")?.string()?
        || json_member(artifact_api, "archive_download_url")?.string()?
            != json_member(summary, "archiveDownloadUrl")?.string()?
    {
        return Err("provider raw artifact metadata differs from its signed summary".to_owned());
    }
    Ok(())
}

fn verify_artifact_attestation(
    path: &Path,
    artifact_digest: &str,
    artifact: &str,
    candidate: &str,
) -> Result<String, String> {
    let document = parse_json(&read_text(path)?)?;
    let report = document.object()?;
    exact_keys(
        report,
        &[
            "artifactSetSha256",
            "artifactSha256",
            "attestedSubjectPath",
            "attestedSubjectSha256",
            "lookupPath",
            "lookupSha256",
            "lookupState",
            "reason",
            "schemaVersion",
            "state",
            "verificationPath",
            "verificationSha256",
        ],
    )?;
    if json_member(report, "schemaVersion")?.number()? != 2
        || json_member(report, "artifactSha256")?.string()? != artifact_digest
    {
        return Err("artifact attestation report does not bind acquired bytes".to_owned());
    }
    let retained_root =
        verify_artifact_attestation_subject(path, report, artifact_digest, artifact, candidate)?;
    verify_artifact_attestation_lookup(&retained_root, report)?;
    record_digest(path)
}

fn verify_artifact_attestation_subject(
    path: &Path,
    report: &BTreeMap<String, JsonValue>,
    artifact_digest: &str,
    artifact: &str,
    candidate: &str,
) -> Result<PathBuf, String> {
    let retained_root = path
        .parent()
        .ok_or_else(|| "artifact attestation report has no retained root".to_owned())?;
    let subject_relative = Path::new(json_member(report, "attestedSubjectPath")?.string()?);
    let subject = confined_record_path(retained_root, Path::new("."), subject_relative)?;
    verify_file_digest(
        &subject,
        json_member(report, "attestedSubjectSha256")?.string()?,
        "provider attestation subject",
    )?;
    let subject_directory = subject
        .parent()
        .ok_or_else(|| "provider attestation subject has no artifact directory".to_owned())?;
    if record_digest(subject_directory)? != artifact_digest {
        return Err(
            "provider attestation subject is outside the acquired artifact bytes".to_owned(),
        );
    }
    let subject_document = parse_json(&read_text(&subject)?)?;
    let subject_object = subject_document.object()?;
    exact_keys(
        subject_object,
        &[
            "artifact",
            "artifactSetSha256",
            "candidateCommit",
            "schemaVersion",
        ],
    )?;
    let subject_file_name = subject
        .file_name()
        .ok_or_else(|| "provider attestation subject has no file name".to_owned())?;
    let artifact_set_sha256 = sha256_bytes(
        directory_manifest_excluding(subject_directory, Path::new(subject_file_name))?.as_bytes(),
    )
    .hex();
    if json_member(subject_object, "schemaVersion")?.number()? != 1
        || json_member(subject_object, "artifact")?.string()? != artifact
        || json_member(subject_object, "candidateCommit")?.string()? != candidate
        || json_member(subject_object, "artifactSetSha256")?.string()? != artifact_set_sha256
        || json_member(report, "artifactSetSha256")?.string()? != artifact_set_sha256
    {
        return Err("provider attestation subject does not bind the exact artifact set".to_owned());
    }
    Ok(retained_root.to_path_buf())
}

fn verify_artifact_attestation_lookup(
    retained_root: &Path,
    report: &BTreeMap<String, JsonValue>,
) -> Result<(), String> {
    let lookup = confined_record_path(
        retained_root,
        Path::new("."),
        Path::new(json_member(report, "lookupPath")?.string()?),
    )?;
    verify_file_digest(
        &lookup,
        json_member(report, "lookupSha256")?.string()?,
        "provider attestation lookup",
    )?;
    let lookup_document = parse_json(&read_text(&lookup)?)?;
    let lookup_object = lookup_document.object()?;
    let lookup_state = json_member(report, "lookupState")?.string()?;
    if json_member(lookup_object, "schemaVersion")?.number()? != 1
        || json_member(lookup_object, "state")?.string()? != lookup_state
        || json_member(lookup_object, "subjectSha256")?.string()?
            != json_member(report, "attestedSubjectSha256")?.string()?
    {
        return Err("provider attestation lookup identity is inconsistent".to_owned());
    }
    verify_provider_attestation_lookup_document(lookup_object, lookup_state)?;
    let reason = json_member(report, "reason")?.string()?;
    match (json_member(report, "state")?.string()?, lookup_state) {
        ("verified", "available") if reason.is_empty() => {
            let verification = confined_record_path(
                retained_root,
                Path::new("."),
                Path::new(json_member(report, "verificationPath")?.string()?),
            )?;
            verify_file_digest(
                &verification,
                json_member(report, "verificationSha256")?.string()?,
                "provider attestation verification",
            )?;
            verify_attestation_output_subject(
                &parse_json(&read_text(&verification)?)?,
                json_member(report, "attestedSubjectSha256")?.string()?,
            )?;
        }
        ("unavailable-reviewed", "absent" | "empty" | "service-failure") if !reason.is_empty() => {
            if !matches!(json_member(report, "verificationPath")?, JsonValue::Null)
                || !matches!(json_member(report, "verificationSha256")?, JsonValue::Null)
            {
                return Err(
                    "unavailable provider attestation invents verification output".to_owned(),
                );
            }
        }
        _ => return Err("artifact attestation state or reason is invalid".to_owned()),
    }
    Ok(())
}

fn verify_provider_attestation_lookup_document(
    lookup: &BTreeMap<String, JsonValue>,
    state: &str,
) -> Result<(), String> {
    if matches!(state, "absent" | "service-failure") {
        exact_keys(
            lookup,
            &[
                "endpoint",
                "error",
                "errorSha256",
                "schemaVersion",
                "state",
                "subjectSha256",
            ],
        )?;
        let error = json_member(lookup, "error")?.string()?;
        if json_member(lookup, "errorSha256")?.string()? != sha256_bytes(error.as_bytes()).hex() {
            return Err("provider attestation lookup failure digest is invalid".to_owned());
        }
        return Ok(());
    }
    if !matches!(state, "available" | "empty") {
        return Err("provider attestation lookup state is invalid".to_owned());
    }
    exact_keys(
        lookup,
        &["response", "schemaVersion", "state", "subjectSha256"],
    )?;
    let attestations = json_member(json_member(lookup, "response")?.object()?, "attestations")?
        .array()?
        .is_empty();
    if (state == "available" && attestations) || (state == "empty" && !attestations) {
        return Err("available provider attestation lookup has no records".to_owned());
    }
    Ok(())
}

struct AcquisitionReceipt {
    artifact: String,
    provider_artifact_id: u64,
    provider_metadata_sha256: String,
    local_path: PathBuf,
    observed_sha256: String,
    observed_size: u64,
    repository_id: String,
    workflow_path: String,
    workflow_sha256: String,
    run_id: u64,
    run_attempt: u64,
    acquisition_run_id: u64,
    acquisition_run_attempt: u64,
    acquisition_workflow_ref: String,
    candidate_commit: String,
    trust_domain: String,
    channel_class: String,
    acquirer: String,
    acquirer_account_id: u64,
    acquirer_login: String,
    acquired_at: String,
    acquisition_event: String,
    provider_event: String,
    acquisition_platform: String,
    acquisition_tool: String,
    trust_review_ref: String,
    external_acquisition_path: Option<PathBuf>,
    external_acquisition_sha256: Option<String>,
}

fn acquisition_receipt_core_digest(receipt: &AcquisitionReceipt) -> String {
    let external_path = receipt.external_acquisition_path.as_ref().map_or_else(
        || "null".to_owned(),
        |path| json_string(&path_text(path).unwrap_or_else(|_| "INVALID_PATH".to_owned())),
    );
    let external_sha256 = receipt
        .external_acquisition_sha256
        .as_deref()
        .map_or_else(|| "null".to_owned(), json_string);
    let core = format!(
        "{{\"schemaVersion\":3,\"artifact\":{},\"providerArtifactId\":{},\"providerMetadataSha256\":{},\"localPath\":{},\"observedSha256\":{},\"observedSize\":{},\"repository\":\"Portfoligno/hell-rs\",\"repositoryId\":{},\"workflowPath\":{},\"workflowBlobSha256\":{},\"runId\":{},\"runAttempt\":{},\"acquisitionRunId\":{},\"acquisitionRunAttempt\":{},\"acquisitionWorkflowRef\":{},\"candidateCommit\":{},\"channelClass\":{},\"trustDomain\":{},\"acquirer\":{},\"acquirerAccountId\":{},\"acquirerLogin\":{},\"acquiredAt\":{},\"acquisitionEvent\":{},\"providerEvent\":{},\"acquisitionPlatform\":{},\"acquisitionTool\":{},\"externalAcquisitionPath\":{external_path},\"externalAcquisitionSha256\":{external_sha256}}}\n",
        json_string(&receipt.artifact),
        receipt.provider_artifact_id,
        json_string(&receipt.provider_metadata_sha256),
        json_string(&path_text(&receipt.local_path).unwrap_or_else(|_| "INVALID_PATH".to_owned())),
        json_string(&receipt.observed_sha256),
        receipt.observed_size,
        json_string(&receipt.repository_id),
        json_string(&receipt.workflow_path),
        json_string(&receipt.workflow_sha256),
        receipt.run_id,
        receipt.run_attempt,
        receipt.acquisition_run_id,
        receipt.acquisition_run_attempt,
        json_string(&receipt.acquisition_workflow_ref),
        json_string(&receipt.candidate_commit),
        json_string(&receipt.channel_class),
        json_string(&receipt.trust_domain),
        json_string(&receipt.acquirer),
        receipt.acquirer_account_id,
        json_string(&receipt.acquirer_login),
        json_string(&receipt.acquired_at),
        json_string(&receipt.acquisition_event),
        json_string(&receipt.provider_event),
        json_string(&receipt.acquisition_platform),
        json_string(&receipt.acquisition_tool),
    );
    sha256_bytes(core.as_bytes()).hex()
}

fn parse_acquisition_receipt(path: &Path) -> Result<AcquisitionReceipt, String> {
    parse_acquisition_receipt_state(path, false)
}

fn parse_acquisition_receipt_state(
    path: &Path,
    allow_pending_review: bool,
) -> Result<AcquisitionReceipt, String> {
    parse_acquisition_receipt_document(&read_text(path)?, allow_pending_review)
}

fn parse_acquisition_receipt_document(
    bytes: &str,
    allow_pending_review: bool,
) -> Result<AcquisitionReceipt, String> {
    let document = parse_json(bytes)?;
    let object = document.object()?;
    verify_acquisition_receipt_keys(object)?;
    if json_member(object, "schemaVersion")?.number()? != 3
        || json_member(object, "repository")?.string()? != "Portfoligno/hell-rs"
    {
        return Err("acquisition receipt source identity is invalid".to_owned());
    }
    let observed_sha256 = json_member(object, "observedSha256")?.string()?.to_owned();
    require_digest(&observed_sha256, "acquisition digest")?;
    let workflow_sha256 = json_member(object, "workflowBlobSha256")?
        .string()?
        .to_owned();
    require_digest(&workflow_sha256, "workflow blob digest")?;
    let candidate_commit = json_member(object, "candidateCommit")?.string()?.to_owned();
    require_git_sha_text(&candidate_commit, "acquisition candidate")?;
    let trust_review_ref = json_member(object, "trustReviewRef")?.string()?.to_owned();
    if trust_review_ref != "REVIEW_REQUIRED" || !allow_pending_review {
        require_digest(&trust_review_ref, "artifact trust review")?;
    }
    let provider_artifact_id = json_member(object, "providerArtifactId")?.number()?;
    if provider_artifact_id == 0 {
        return Err("artifact provider identity must be nonzero".to_owned());
    }
    let provider_metadata_sha256 = json_member(object, "providerMetadataSha256")?
        .string()?
        .to_owned();
    require_digest(&provider_metadata_sha256, "provider metadata")?;
    let acquired_at = json_member(object, "acquiredAt")?.string()?.to_owned();
    validate_utc_timestamp(&acquired_at)?;
    let acquisition_event = json_member(object, "acquisitionEvent")?
        .string()?
        .to_owned();
    let provider_event = json_member(object, "providerEvent")?.string()?.to_owned();
    let artifact = json_member(object, "artifact")?.string()?.to_owned();
    let workflow_path = json_member(object, "workflowPath")?.string()?.to_owned();
    let acquisition_platform = json_member(object, "acquisitionPlatform")?
        .string()?
        .to_owned();
    let acquisition_tool = json_member(object, "acquisitionTool")?.string()?.to_owned();
    let acquisition_run_id = json_member(object, "acquisitionRunId")?.number()?;
    let acquisition_run_attempt = json_member(object, "acquisitionRunAttempt")?.number()?;
    let acquisition_workflow_ref = json_member(object, "acquisitionWorkflowRef")?
        .string()?
        .to_owned();
    let acquirer_account_id = json_member(object, "acquirerAccountId")?.number()?;
    let acquirer_login = json_member(object, "acquirerLogin")?.string()?.to_owned();
    validate_provider_atom(&acquirer_login, "artifact acquirer login")?;
    if acquirer_account_id == 0
        || json_member(object, "acquirer")?.string()?
            != format!("github-account:{acquirer_account_id}")
    {
        return Err("artifact acquirer stable provider identity is invalid".to_owned());
    }
    let (external_acquisition_path, external_acquisition_sha256) =
        parsed_external_acquisition_binding(object)?;
    let receipt = AcquisitionReceipt {
        artifact,
        provider_artifact_id,
        provider_metadata_sha256,
        local_path: PathBuf::from(json_member(object, "localPath")?.string()?),
        observed_sha256,
        observed_size: json_member(object, "observedSize")?.number()?,
        repository_id: json_member(object, "repositoryId")?.string()?.to_owned(),
        workflow_path,
        workflow_sha256,
        run_id: json_member(object, "runId")?.number()?,
        run_attempt: json_member(object, "runAttempt")?.number()?,
        acquisition_run_id,
        acquisition_run_attempt,
        acquisition_workflow_ref,
        candidate_commit,
        trust_domain: json_member(object, "trustDomain")?.string()?.to_owned(),
        channel_class: json_member(object, "channelClass")?.string()?.to_owned(),
        acquirer: json_member(object, "acquirer")?.string()?.to_owned(),
        acquired_at,
        acquisition_event,
        provider_event,
        acquisition_platform,
        acquisition_tool,
        trust_review_ref,
        acquirer_account_id,
        acquirer_login,
        external_acquisition_path,
        external_acquisition_sha256,
    };
    validate_acquisition_receipt_identity(&receipt)?;
    Ok(receipt)
}

pub fn fuzz_admit_acquisition_receipt(bytes: &[u8]) -> Result<(), String> {
    let document = std::str::from_utf8(bytes)
        .map_err(|_| "acquisition receipt is not canonical UTF-8".to_owned())?;
    let final_result = parse_acquisition_receipt_document(document, false).map(|_| ());
    let pending_result = parse_acquisition_receipt_document(document, true).map(|_| ());
    final_result.or(pending_result)
}

fn validate_acquisition_receipt_identity(receipt: &AcquisitionReceipt) -> Result<(), String> {
    let (expected_provider_event, expected_workflow) = match receipt.artifact.as_str() {
        "native-oracle-merged" => ("push", ".github/workflows/nightly.yml"),
        "promotion-review-ready-evidence" => (
            "workflow_dispatch",
            ".github/workflows/promotion-evidence-review.yml",
        ),
        "promotion-final-reviewed-evidence" => (
            "workflow_dispatch",
            ".github/workflows/evidence-custody.yml",
        ),
        "promotion-record" => ("workflow_dispatch", ".github/workflows/nightly.yml"),
        _ => return Err("acquisition receipt has an unknown artifact class".to_owned()),
    };
    let acquisition_workflow = if receipt.external_acquisition_path.is_some() {
        ".github/workflows/artifact-independent-acquisition.yml"
    } else {
        ".github/workflows/artifact-authenticity-review.yml"
    };
    if receipt.acquisition_event != "workflow_dispatch"
        || receipt.provider_event != expected_provider_event
        || receipt.workflow_path != expected_workflow
        || receipt.acquisition_platform.is_empty()
        || receipt.acquisition_tool.is_empty()
        || receipt.acquisition_run_id == 0
        || receipt.acquisition_run_attempt == 0
        || acquisition_workflow_reference(&receipt.acquisition_workflow_ref, acquisition_workflow)
            .is_err()
    {
        return Err("artifact acquisition event/platform/tool identity is invalid".to_owned());
    }
    Ok(())
}

fn acquisition_workflow_reference<'a>(
    value: &'a str,
    expected_path: &str,
) -> Result<&'a str, String> {
    let relative = value
        .strip_prefix("Portfoligno/hell-rs/")
        .ok_or_else(|| "acquisition workflow ref lacks the exact repository".to_owned())?;
    let (path, reference) = relative
        .split_once('@')
        .ok_or_else(|| "acquisition workflow ref does not bind a ref".to_owned())?;
    if path != expected_path
        || reference.is_empty()
        || reference.contains('@')
        || reference.contains('\\')
        || reference.chars().any(char::is_whitespace)
    {
        return Err("acquisition workflow repository/path/ref is invalid".to_owned());
    }
    Ok(reference)
}

fn parsed_external_acquisition_binding(
    object: &BTreeMap<String, JsonValue>,
) -> Result<(Option<PathBuf>, Option<String>), String> {
    let path = match json_member(object, "externalAcquisitionPath")? {
        JsonValue::Null => None,
        value => Some(PathBuf::from(value.string()?)),
    };
    let sha256 = match json_member(object, "externalAcquisitionSha256")? {
        JsonValue::Null => None,
        value => {
            require_digest(value.string()?, "external acquisition evidence")?;
            Some(value.string()?.to_owned())
        }
    };
    if path.is_some() != sha256.is_some() {
        return Err("external acquisition path and digest are incomplete".to_owned());
    }
    Ok((path, sha256))
}

fn verify_acquisition_receipt_keys(object: &BTreeMap<String, JsonValue>) -> Result<(), String> {
    exact_keys(
        object,
        &[
            "acquiredAt",
            "acquisitionEvent",
            "acquisitionPlatform",
            "acquisitionRunAttempt",
            "acquisitionRunId",
            "acquisitionTool",
            "acquisitionWorkflowRef",
            "acquirer",
            "acquirerAccountId",
            "acquirerLogin",
            "artifact",
            "candidateCommit",
            "channelClass",
            "localPath",
            "observedSha256",
            "observedSize",
            "providerArtifactId",
            "providerEvent",
            "providerMetadataSha256",
            "repository",
            "repositoryId",
            "runAttempt",
            "runId",
            "schemaVersion",
            "trustDomain",
            "trustReviewRef",
            "externalAcquisitionPath",
            "externalAcquisitionSha256",
            "workflowBlobSha256",
            "workflowPath",
        ],
    )
}

#[allow(clippy::too_many_lines)]
fn oracle_provenance(root: &Path, options: &Options) -> Result<String, String> {
    match options.action.as_deref().unwrap_or("verify") {
        "collect" => {
            let source = required_path(
                &options.input,
                "oracle-provenance collect requires --input source",
            )?;
            let output = required_path(
                &options.output,
                "oracle-provenance collect requires --output",
            )?;
            let platform = options
                .platform
                .as_deref()
                .ok_or_else(|| "oracle-provenance collect requires --platform".to_owned())?;
            let head = git_output(source, &["rev-parse", "HEAD"])?;
            let tree = git_output(source, &["rev-parse", "HEAD^{tree}"])?;
            let status = git_output(source, &["status", "--porcelain=v2"])?;
            let json = format!(
                "{{\n  \"schemaVersion\": 1,\n  \"platform\": {},\n  \"sourceCommit\": {},\n  \"sourceTree\": {},\n  \"sourceTreeClean\": {},\n  \"sbomState\": \"not-collected\",\n  \"networkInventoryState\": \"not-collected\",\n  \"reproducibilityState\": \"not-collected\",\n  \"exercisedBinaryBindingState\": \"not-collected\",\n  \"policyState\": \"requires-human-judgment\"\n}}\n",
                json_string(platform),
                json_string(head.trim()),
                json_string(tree.trim()),
                status.trim().is_empty()
            );
            write_atomic(output, json.as_bytes())?;
            Ok(format!(
                "collected fail-closed oracle provenance at {}",
                output.display()
            ))
        }
        "verify" | "compare" => {
            let input = required_path(
                &options.input,
                "oracle-provenance verification requires --input",
            )?;
            let record_root = input
                .parent()
                .ok_or_else(|| "oracle provenance record has no retained root".to_owned())?;
            let policy = required_path(
                &options.policy,
                "oracle-provenance verify requires --policy allowed-signers",
            )?;
            let document = parse_json(&read_text(input)?)?;
            let record = document.object()?;
            exact_keys(
                record,
                &[
                    "assuranceEpochSha256",
                    "buildPlanPath",
                    "buildPlanSha256",
                    "candidateCommit",
                    "exercisedBinaryPath",
                    "exercisedBinarySha256",
                    "comparisonPath",
                    "comparisonSha256",
                    "firstAcquisitionReceiptPath",
                    "firstAcquisitionReceiptSha256",
                    "firstBinaryPath",
                    "firstBinarySha256",
                    "firstBuildReceiptPath",
                    "firstBuildReceiptSha256",
                    "firstBuilderTrustDomain",
                    "firstEnvironmentPath",
                    "firstEnvironmentSha256",
                    "firstProvenancePolicyPath",
                    "firstProvenancePolicySha256",
                    "firstRunIdentity",
                    "networkInventoryPath",
                    "networkInventorySha256",
                    "platform",
                    "platformReviewPath",
                    "platformReviewSha256",
                    "policyFindings",
                    "reproducibility",
                    "sbomPath",
                    "sbomSha256",
                    "schemaVersion",
                    "secondBinaryPath",
                    "secondBinarySha256",
                    "secondAcquisitionReceiptPath",
                    "secondAcquisitionReceiptSha256",
                    "secondBuildReceiptPath",
                    "secondBuildReceiptSha256",
                    "secondBuilderTrustDomain",
                    "secondEnvironmentPath",
                    "secondEnvironmentSha256",
                    "secondProvenancePolicyPath",
                    "secondProvenancePolicySha256",
                    "secondRunIdentity",
                    "sourceCommit",
                    "sourceArchivePath",
                    "sourceArchiveSha256",
                    "sourceFilesPath",
                    "sourceFilesSha256",
                    "sourcePath",
                    "sourceTree",
                    "sourceTreeClean",
                    "semanticFingerprintSha256",
                ],
            )?;
            if json_member(record, "schemaVersion")?.number()? != 1
                || !json_member(record, "sourceTreeClean")?.boolean()?
                || !json_member(record, "policyFindings")?.array()?.is_empty()
            {
                return Err("oracle provenance structural policy failed".to_owned());
            }
            let assurance_epoch = json_member(record, "assuranceEpochSha256")?.string()?;
            require_digest(assurance_epoch, "oracle assurance epoch")?;
            let current_candidate = git_output(root, &["rev-parse", "HEAD"])?;
            let (_, current_epoch) = epoch(root)?;
            if json_member(record, "candidateCommit")?.string()? != current_candidate.trim()
                || assurance_epoch != current_epoch.hex()
                || !matches!(
                    json_member(record, "platform")?.string()?,
                    "macos-arm64" | "windows-amd64" | "linux-amd64"
                )
            {
                return Err("oracle provenance candidate, epoch, or platform mismatch".to_owned());
            }
            let source = confined_record_path(
                root,
                record_root,
                Path::new(json_member(record, "sourcePath")?.string()?),
            )?;
            let source_commit = json_member(record, "sourceCommit")?.string()?;
            let source_tree = json_member(record, "sourceTree")?.string()?;
            if git_output(&source, &["rev-parse", "HEAD"])?.trim() != source_commit
                || git_output(&source, &["rev-parse", "HEAD^{tree}"])?.trim() != source_tree
                || !git_output(&source, &["status", "--porcelain=v2"])?
                    .trim()
                    .is_empty()
            {
                return Err("oracle source tree identity or cleanliness changed".to_owned());
            }
            for (path_field, digest_field) in [
                (
                    "firstAcquisitionReceiptPath",
                    "firstAcquisitionReceiptSha256",
                ),
                (
                    "secondAcquisitionReceiptPath",
                    "secondAcquisitionReceiptSha256",
                ),
                ("buildPlanPath", "buildPlanSha256"),
                ("sbomPath", "sbomSha256"),
                ("networkInventoryPath", "networkInventorySha256"),
                ("sourceFilesPath", "sourceFilesSha256"),
                ("sourceArchivePath", "sourceArchiveSha256"),
                ("firstEnvironmentPath", "firstEnvironmentSha256"),
                ("secondEnvironmentPath", "secondEnvironmentSha256"),
                ("firstProvenancePolicyPath", "firstProvenancePolicySha256"),
                ("secondProvenancePolicyPath", "secondProvenancePolicySha256"),
                ("firstBinaryPath", "firstBinarySha256"),
                ("firstBuildReceiptPath", "firstBuildReceiptSha256"),
                ("secondBinaryPath", "secondBinarySha256"),
                ("secondBuildReceiptPath", "secondBuildReceiptSha256"),
                ("exercisedBinaryPath", "exercisedBinarySha256"),
                ("comparisonPath", "comparisonSha256"),
                ("platformReviewPath", "platformReviewSha256"),
            ] {
                verify_confined_path_digest(root, record_root, record, path_field, digest_field)?;
            }
            let build_plan = confined_record_path(
                root,
                record_root,
                Path::new(json_member(record, "buildPlanPath")?.string()?),
            )?;
            let sbom = confined_record_path(
                root,
                record_root,
                Path::new(json_member(record, "sbomPath")?.string()?),
            )?;
            let network = confined_record_path(
                root,
                record_root,
                Path::new(json_member(record, "networkInventoryPath")?.string()?),
            )?;
            let source_files = confined_record_path(
                root,
                record_root,
                Path::new(json_member(record, "sourceFilesPath")?.string()?),
            )?;
            let first_environment = confined_record_path(
                root,
                record_root,
                Path::new(json_member(record, "firstEnvironmentPath")?.string()?),
            )?;
            let second_environment = confined_record_path(
                root,
                record_root,
                Path::new(json_member(record, "secondEnvironmentPath")?.string()?),
            )?;
            let first_provenance_policy = confined_record_path(
                root,
                record_root,
                Path::new(json_member(record, "firstProvenancePolicyPath")?.string()?),
            )?;
            let second_provenance_policy = confined_record_path(
                root,
                record_root,
                Path::new(json_member(record, "secondProvenancePolicyPath")?.string()?),
            )?;
            let comparison = confined_record_path(
                root,
                record_root,
                Path::new(json_member(record, "comparisonPath")?.string()?),
            )?;
            let first_acquisition = confined_record_path(
                root,
                record_root,
                Path::new(json_member(record, "firstAcquisitionReceiptPath")?.string()?),
            )?;
            let second_acquisition = confined_record_path(
                root,
                record_root,
                Path::new(json_member(record, "secondAcquisitionReceiptPath")?.string()?),
            )?;
            verify_oracle_evidence_documents(&build_plan, &sbom, &network)?;
            verify_source_files(&source_files, source_tree)?;
            verify_oracle_environment(
                &first_environment,
                json_member(record, "platform")?.string()?,
            )?;
            verify_oracle_environment(
                &second_environment,
                json_member(record, "platform")?.string()?,
            )?;
            verify_provenance_policy(
                &first_provenance_policy,
                record,
                "firstEnvironmentSha256",
                "firstBinarySha256",
            )?;
            verify_provenance_policy(
                &second_provenance_policy,
                record,
                "secondEnvironmentSha256",
                "secondBinarySha256",
            )?;
            verify_oracle_comparison(&comparison, record)?;
            let plan_document = parse_json(&read_text(&build_plan)?)?;
            let plan = plan_document.object()?;
            for field in ["sourceArchiveSha256", "sourceFilesSha256"] {
                if json_member(plan, field)?.string()? != json_member(record, field)?.string()? {
                    return Err(format!("oracle build plan field {field} was substituted"));
                }
            }
            let expected_packages = oracle_plan_packages(plan)?;
            let first_acquisition = verify_oracle_acquisition_receipt(
                &first_acquisition,
                record,
                "firstBuilderTrustDomain",
                "firstRunIdentity",
                &expected_packages,
            )?;
            let second_acquisition = verify_oracle_acquisition_receipt(
                &second_acquisition,
                record,
                "secondBuilderTrustDomain",
                "secondRunIdentity",
                &expected_packages,
            )?;
            if first_acquisition.builder == second_acquisition.builder
                || first_acquisition.observed_urls != second_acquisition.observed_urls
            {
                return Err(
                    "oracle acquisitions lack independent builders or common observed sources"
                        .to_owned(),
                );
            }
            let first = json_member(record, "firstBinarySha256")?.string()?;
            let second = json_member(record, "secondBinarySha256")?.string()?;
            let exercised = json_member(record, "exercisedBinarySha256")?.string()?;
            match json_member(record, "reproducibility")?.string()? {
                "exact" if first == second => {}
                "normalized" => {
                    return Err(
                        "normalized reproducibility needs a typed nondeterminism inventory"
                            .to_owned(),
                    );
                }
                _ => {
                    return Err("oracle independent rebuild is not exactly reproducible".to_owned());
                }
            }
            verify_exercised_oracle_binary(first, exercised)?;
            let first_binary_path = confined_record_path(
                root,
                record_root,
                Path::new(json_member(record, "firstBinaryPath")?.string()?),
            )?;
            let second_binary_path = confined_record_path(
                root,
                record_root,
                Path::new(json_member(record, "secondBinaryPath")?.string()?),
            )?;
            let first_receipt_path = confined_record_path(
                root,
                record_root,
                Path::new(json_member(record, "firstBuildReceiptPath")?.string()?),
            )?;
            let second_receipt_path = confined_record_path(
                root,
                record_root,
                Path::new(json_member(record, "secondBuildReceiptPath")?.string()?),
            )?;
            let first_domain = json_member(record, "firstBuilderTrustDomain")?.string()?;
            let second_domain = json_member(record, "secondBuilderTrustDomain")?.string()?;
            let first_run = json_member(record, "firstRunIdentity")?.string()?;
            let second_run = json_member(record, "secondRunIdentity")?.string()?;
            if first_binary_path == second_binary_path
                || first_receipt_path == second_receipt_path
                || first_domain.is_empty()
                || first_domain == second_domain
                || first_run.is_empty()
                || first_run == second_run
            {
                return Err(
                    "oracle rebuilds are not independently retained and identified".to_owned(),
                );
            }
            let first_receipt = verify_review_envelope(&first_receipt_path, policy)?;
            let second_receipt = verify_review_envelope(&second_receipt_path, policy)?;
            let common_subjects = [
                json_member(record, "buildPlanSha256")?.string()?,
                json_member(record, "sbomSha256")?.string()?,
                json_member(record, "networkInventorySha256")?.string()?,
            ];
            let first_subject = oracle_build_subject_digest(record, "first")?;
            let second_subject = oracle_build_subject_digest(record, "second")?;
            if first_receipt.role != "oracle-builder"
                || second_receipt.role != "oracle-builder"
                || first_receipt.subject == second_receipt.subject
                || first_receipt.signer_fingerprint == second_receipt.signer_fingerprint
                || first_receipt.candidate_commit != current_candidate.trim()
                || second_receipt.candidate_commit != current_candidate.trim()
                || first_receipt.assurance_epoch != assurance_epoch
                || second_receipt.assurance_epoch != assurance_epoch
                || !common_subjects.into_iter().all(|digest| {
                    first_receipt.reviewed_artifacts.contains(digest)
                        && second_receipt.reviewed_artifacts.contains(digest)
                })
                || !first_receipt
                    .reviewed_artifacts
                    .contains(json_member(record, "firstEnvironmentSha256")?.string()?)
                || !second_receipt
                    .reviewed_artifacts
                    .contains(json_member(record, "secondEnvironmentSha256")?.string()?)
                || !first_receipt
                    .reviewed_artifacts
                    .contains(json_member(record, "firstProvenancePolicySha256")?.string()?)
                || !second_receipt
                    .reviewed_artifacts
                    .contains(json_member(record, "secondProvenancePolicySha256")?.string()?)
                || !first_receipt.reviewed_artifacts.contains(&first_subject)
                || !second_receipt.reviewed_artifacts.contains(&second_subject)
            {
                return Err("oracle build receipts do not prove two independent builds".to_owned());
            }
            let review_path = confined_record_path(
                root,
                record_root,
                Path::new(json_member(record, "platformReviewPath")?.string()?),
            )?;
            let review = verify_authorized_human_review(
                &review_path,
                policy,
                "platform-reviewer",
                json_member(record, "candidateCommit")?.string()?,
                "platform-review-packet.json",
            )?;
            let required_digests = [
                "buildPlanSha256",
                "sbomSha256",
                "networkInventorySha256",
                "sourceFilesSha256",
                "firstEnvironmentSha256",
                "secondEnvironmentSha256",
                "firstProvenancePolicySha256",
                "secondProvenancePolicySha256",
                "firstBinarySha256",
                "secondBinarySha256",
                "exercisedBinarySha256",
                "firstBuildReceiptSha256",
                "secondBuildReceiptSha256",
                "comparisonSha256",
                "semanticFingerprintSha256",
            ];
            if review.role != "platform-reviewer"
                || review.candidate_commit != json_member(record, "candidateCommit")?.string()?
                || review.assurance_epoch != assurance_epoch
                || !required_digests.into_iter().all(|field| {
                    json_member(record, field)
                        .and_then(JsonValue::string)
                        .is_ok_and(|digest| review.reviewed_artifacts.contains(digest))
                })
            {
                return Err("platform review role or candidate binding mismatch".to_owned());
            }
            Ok(format!(
                "verified exact native oracle provenance for {}",
                json_member(record, "platform")?.string()?
            ))
        }
        action => Err(format!("unknown oracle-provenance action {action:?}")),
    }
}

pub(crate) fn verify_surveillance_oracle_provenance(
    root: &Path,
    input: &Path,
    signer_policy: &Path,
    maximum_age_days: u64,
) -> Result<String, String> {
    oracle_provenance(
        root,
        &Options {
            action: Some("verify".to_owned()),
            input: Some(input.to_path_buf()),
            policy: Some(signer_policy.to_path_buf()),
            ..Options::default()
        },
    )?;
    let document = parse_json(&read_text(input)?)?;
    let record = document.object()?;
    let retained_root = input
        .parent()
        .ok_or_else(|| "surveillance provenance has no retained root".to_owned())?;
    let review_path = confined_record_path(
        root,
        retained_root,
        Path::new(json_member(record, "platformReviewPath")?.string()?),
    )?;
    let review = verify_authorized_human_review(
        &review_path,
        signer_policy,
        "platform-reviewer",
        json_member(record, "candidateCommit")?.string()?,
        "platform-review-packet.json",
    )?;
    if crate::custody_ops::utc_age_days(&review.issued_at)? > maximum_age_days {
        return Err("reviewed native oracle provenance exceeded surveillance cadence".to_owned());
    }
    Ok(json_member(record, "platform")?.string()?.to_owned())
}

fn verify_exercised_oracle_binary(reviewed: &str, exercised: &str) -> Result<(), String> {
    require_digest(reviewed, "reviewed oracle binary")?;
    require_digest(exercised, "exercised oracle binary")?;
    if crate::assurance_control_mutant_active("oracle-binary-substitution") || reviewed == exercised
    {
        Ok(())
    } else {
        Err("exercised oracle binary differs from reviewed build".to_owned())
    }
}

fn verify_confined_path_digest(
    root: &Path,
    retained_root: &Path,
    object: &BTreeMap<String, JsonValue>,
    path_field: &str,
    digest_field: &str,
) -> Result<PathBuf, String> {
    let path = confined_record_path(
        root,
        retained_root,
        Path::new(json_member(object, path_field)?.string()?),
    )?;
    let expected = json_member(object, digest_field)?.string()?;
    require_digest(expected, digest_field)?;
    let bytes = read_regular_file(&path)?;
    let observed = sha256_bytes(&bytes).hex();
    if observed != expected {
        return Err(format!(
            "{digest_field} mismatch: expected {expected}, observed {observed}"
        ));
    }
    Ok(path)
}

fn oracle_build_subject_digest(
    record: &BTreeMap<String, JsonValue>,
    ordinal: &str,
) -> Result<String, String> {
    let (binary, environment, provenance_policy, domain, run) = match ordinal {
        "first" => (
            "firstBinarySha256",
            "firstEnvironmentSha256",
            "firstProvenancePolicySha256",
            "firstBuilderTrustDomain",
            "firstRunIdentity",
        ),
        "second" => (
            "secondBinarySha256",
            "secondEnvironmentSha256",
            "secondProvenancePolicySha256",
            "secondBuilderTrustDomain",
            "secondRunIdentity",
        ),
        _ => return Err("unknown oracle build ordinal".to_owned()),
    };
    let mut subject = String::from("{\"schemaVersion\":1");
    for field in [
        "candidateCommit",
        "assuranceEpochSha256",
        "platform",
        "sourceCommit",
        "sourceTree",
        "buildPlanSha256",
        "sbomSha256",
        "networkInventorySha256",
        environment,
        provenance_policy,
        binary,
        domain,
        run,
    ] {
        subject.push(',');
        push_json(&mut subject, field);
        subject.push(':');
        push_json_value(&mut subject, json_member(record, field)?)?;
    }
    subject.push_str("}\n");
    Ok(sha256_bytes(subject.as_bytes()).hex())
}

const BOUND_REPORT_KEYS: &[&str] = &[
    "authorizationPath",
    "authorizationSha256",
    "assuranceEpochSha256",
    "blockerCount",
    "candidateSourceCommit",
    "detailsPath",
    "detailsSha256",
    "kind",
    "reviewPath",
    "reviewSha256",
    "schemaVersion",
    "signerPolicyPath",
    "signerPolicySha256",
];

fn verify_bound_report(
    path: &Path,
    allowed_signers: &Path,
    expected_kind: &str,
    expected_role: &str,
    expected_candidate: &str,
    expected_epoch: &str,
    retained_root: &Path,
) -> Result<(), String> {
    let blocker_count = verify_bound_report_with_count(
        path,
        allowed_signers,
        expected_kind,
        expected_role,
        expected_candidate,
        expected_epoch,
        retained_root,
    )?;
    if blocker_count != 0 {
        return Err(format!("{expected_kind} report has blockers"));
    }
    Ok(())
}

fn verify_bound_report_with_count(
    path: &Path,
    allowed_signers: &Path,
    expected_kind: &str,
    expected_role: &str,
    expected_candidate: &str,
    expected_epoch: &str,
    retained_root: &Path,
) -> Result<u64, String> {
    let document = parse_json(&read_text(path)?)?;
    let report = document.object()?;
    exact_keys(report, BOUND_REPORT_KEYS)?;
    if json_member(report, "schemaVersion")?.number()? != 1
        || json_member(report, "kind")?.string()? != expected_kind
        || json_member(report, "candidateSourceCommit")?.string()? != expected_candidate
        || json_member(report, "assuranceEpochSha256")?.string()? != expected_epoch
    {
        return Err(format!("{expected_kind} report identity is invalid"));
    }
    let declared_blockers = json_member(report, "blockerCount")?.number()?;
    let repository = repository_root()?;
    let details_path = confined_record_path(
        &repository,
        retained_root,
        Path::new(json_member(report, "detailsPath")?.string()?),
    )?;
    let review_path = confined_record_path(
        &repository,
        retained_root,
        Path::new(json_member(report, "reviewPath")?.string()?),
    )?;
    let authorization_path = confined_record_path(
        &repository,
        retained_root,
        Path::new(json_member(report, "authorizationPath")?.string()?),
    )?;
    let signer_policy_path = confined_record_path(
        &repository,
        retained_root,
        Path::new(json_member(report, "signerPolicyPath")?.string()?),
    )?;
    verify_file_digest(
        &details_path,
        json_member(report, "detailsSha256")?.string()?,
        "detailsSha256",
    )?;
    verify_file_digest(
        &review_path,
        json_member(report, "reviewSha256")?.string()?,
        "reviewSha256",
    )?;
    verify_file_digest(
        &authorization_path,
        json_member(report, "authorizationSha256")?.string()?,
        "authorizationSha256",
    )?;
    verify_file_digest(
        &signer_policy_path,
        json_member(report, "signerPolicySha256")?.string()?,
        "signerPolicySha256",
    )?;
    verify_bound_details(
        &details_path,
        expected_kind,
        expected_candidate,
        expected_epoch,
    )?;
    let details = parse_json(&read_text(&details_path)?)?;
    if bound_report_blockers(expected_kind, details.object()?)? != declared_blockers {
        return Err(format!(
            "{expected_kind} wrapper blocker count does not match signed details"
        ));
    }
    let _ = allowed_signers;
    verify_review_authorization(
        &authorization_path,
        expected_role,
        expected_candidate,
        &details_path,
    )?;
    let review = verify_review_envelope(&review_path, &signer_policy_path)?;
    let details_digest = json_member(report, "detailsSha256")?.string()?;
    if review.role != expected_role
        || review.candidate_commit != expected_candidate
        || review.assurance_epoch != expected_epoch
        || !review.reviewed_artifacts.contains(details_digest)
    {
        return Err(format!("{expected_kind} signed review binding is invalid"));
    }
    verify_bound_claim_groups_if_required(
        expected_kind,
        &details_path,
        expected_candidate,
        expected_epoch,
        &review,
    )?;
    Ok(declared_blockers)
}

fn verified_claim_report_counter(
    path: &Path,
    allowed_signers: &Path,
    expected_candidate: &str,
    expected_epoch: &str,
    retained_root: &Path,
    field: &str,
) -> Result<u64, String> {
    verify_bound_report_with_count(
        path,
        allowed_signers,
        "claim-coverage",
        "claim-reviewer",
        expected_candidate,
        expected_epoch,
        retained_root,
    )?;
    let details = bound_details_document(path, retained_root)?;
    json_member(details.object()?, field)?.number()
}

fn verify_bound_claim_groups_if_required(
    kind: &str,
    details: &Path,
    candidate: &str,
    epoch: &str,
    review: &VerifiedReview,
) -> Result<(), String> {
    if kind != "claim-coverage" {
        return Ok(());
    }
    let (_, expected) = reviewed_finalized_claim_groups_json(details, candidate, epoch)?;
    if review.reviewed_claim_groups != expected {
        return Err("claim review does not bind every exact finalized claim group".to_owned());
    }
    Ok(())
}

fn verify_finalized_claim_inputs(
    path: &Path,
    details: &BTreeMap<String, JsonValue>,
    candidate: &str,
    epoch: &str,
) -> Result<BTreeSet<String>, String> {
    let repository = repository_root()?;
    let retained_root = retained_evidence_root(path)?;
    let source = confined_record_path(
        &repository,
        retained_root,
        Path::new(json_member(details, "sourceCoveragePath")?.string()?),
    )?;
    let decisions = confined_record_path(
        &repository,
        retained_root,
        Path::new(json_member(details, "applicabilityDecisionsPath")?.string()?),
    )?;
    verify_file_digest(
        &source,
        json_member(details, "sourceCoverageSha256")?.string()?,
        "sourceCoverageSha256",
    )?;
    verify_file_digest(
        &decisions,
        json_member(details, "applicabilityDecisionsSha256")?.string()?,
        "applicabilityDecisionsSha256",
    )?;
    let source_document = parse_json(&read_text(&source)?)?;
    let source_document = source_document.object()?;
    if json_member(source_document, "schemaVersion")?.number()? != 1
        || json_member(source_document, "candidateSourceCommit")?.string()? != candidate
        || json_member(source_document, "assuranceEpochSha256")?.string()? != epoch
    {
        return Err("finalized claims do not bind the immutable source coverage".to_owned());
    }
    let decisions_document = parse_json(&read_text(&decisions)?)?;
    claim_applicability_decisions(
        decisions_document.object()?,
        candidate,
        epoch,
        json_member(details, "sourceCoverageSha256")?.string()?,
        retained_root,
    )?
    .into_values()
    .map(|decision| canonical_json_digest(&decision))
    .collect()
}

#[allow(clippy::too_many_lines)]
fn verify_bound_details(
    path: &Path,
    kind: &str,
    candidate: &str,
    epoch: &str,
) -> Result<(), String> {
    let document = parse_json(&read_text(path)?)?;
    let details = document.object()?;
    let schema_version = json_member(details, "schemaVersion")?.number()?;
    let expected_schema_version = match kind {
        "residual-risk" => 3,
        "claim-coverage" | "divergence" => 2,
        _ => 1,
    };
    if schema_version != expected_schema_version
        || json_member(details, "candidateSourceCommit")?.string()? != candidate
    {
        return Err(format!("{kind} details do not bind candidate and epoch"));
    }
    verify_review_epoch(
        epoch,
        json_member(details, "assuranceEpochSha256")?.string()?,
    )?;
    match kind {
        "claim-coverage" => {
            let scoped = details.get("coverageScope").is_some();
            let mut expected_keys = vec![
                "ambiguousClaimScopes",
                "applicabilityDecisionsPath",
                "applicabilityDecisionsSha256",
                "assuranceEpochSha256",
                "candidateSourceCommit",
                "cells",
                "explicitDispositionCells",
                "missingObligations",
                "mismatchCandidates",
                "requiredPlatformGaps",
                "schemaVersion",
                "semanticCoverageGaps",
                "totalClaimCells",
                "unreachedTargets",
                "sourceCoveragePath",
                "sourceCoverageSha256",
            ];
            if scoped {
                expected_keys.extend([
                    "activatedScopeCells",
                    "activeEvidenceCells",
                    "coverageScope",
                    "outOfScopeClaimCells",
                    "residualRuntimeCells",
                ]);
                expected_keys.sort_unstable();
            }
            exact_keys(details, &expected_keys)?;
            let mut retained_decisions =
                verify_finalized_claim_inputs(path, details, candidate, epoch)?;
            let total = json_member(details, "totalClaimCells")?.number()?;
            let expected_rows = if scoped {
                active_collection_applicability_rows()?
            } else {
                applicability_rows()
            };
            let expected_total = u64::try_from(
                expected_rows
                    .len()
                    .saturating_mul(REQUIRED_CLAIM_PLATFORMS.len()),
            )
            .map_err(|_| "claim coverage cell count exceeds u64".to_owned())?;
            let cells = json_member(details, "cells")?.array()?;
            if total != expected_total
                || json_member(details, "explicitDispositionCells")?.number()? != total
                || cells.len()
                    != expected_rows
                        .len()
                        .saturating_mul(REQUIRED_CLAIM_PLATFORMS.len())
                || verify_zero_coverage_gaps(details).is_err()
                || (scoped && verify_scoped_collection_coverage_counts(details).is_err())
            {
                return Err("claim coverage graph is incomplete".to_owned());
            }
            if scoped {
                verify_scoped_collection_claim_cell_scope(cells)?;
            } else {
                verify_canonical_claim_cell_scope(cells)?;
            }
            let mut reviewed_ambiguous = 0_u64;
            let mut scoped_evidence_edges = BTreeSet::new();
            let expected_cells = expected_rows.into_iter().flat_map(|row| {
                REQUIRED_CLAIM_PLATFORMS
                    .iter()
                    .copied()
                    .map(move |platform| (row, platform))
            });
            for (cell, ((builtin, dimension, derived, _), platform)) in
                cells.iter().zip(expected_cells)
            {
                let cell = cell.object()?;
                exact_keys(
                    cell,
                    &[
                        "applicability",
                        "applicabilityDecisionSha256",
                        "builtin",
                        "assuranceEpochSha256",
                        "candidateSourceCommit",
                        "dimension",
                        "evidenceRefs",
                        "divergenceRecordRef",
                        "obligations",
                        "normalizerApplicationRefs",
                        "normalizerIds",
                        "platform",
                        "profile",
                        "proposedStatus",
                    ],
                )?;
                let applicability = json_member(cell, "applicability")?.string()?;
                let decision_digest = json_member(cell, "applicabilityDecisionSha256")?;
                if derived == "ambiguous-needs-review" {
                    if !matches!(
                        applicability,
                        "applicable-reviewed" | "not-applicable-reviewed"
                    ) {
                        reviewed_ambiguous = reviewed_ambiguous.saturating_add(1);
                    }
                    require_digest(
                        decision_digest.string()?,
                        "reviewed claim applicability decision",
                    )?;
                    if !retained_decisions.remove(decision_digest.string()?) {
                        return Err(
                            "claim cell decision is absent from retained reviewed decisions"
                                .to_owned(),
                        );
                    }
                } else if applicability != derived {
                    return Err("mechanical claim applicability was overridden".to_owned());
                } else if !matches!(decision_digest, JsonValue::Null) {
                    return Err("mechanical claim cell has a human decision override".to_owned());
                }
                let status = json_member(cell, "proposedStatus")?.string()?;
                let evidence = json_member(cell, "evidenceRefs")?.array()?;
                let obligations = json_member(cell, "obligations")?.array()?;
                let normalizer_ids = json_member(cell, "normalizerIds")?.array()?;
                let normalizer_refs = json_member(cell, "normalizerApplicationRefs")?.array()?;
                let divergence_ref = json_member(cell, "divergenceRecordRef")?;
                if applicability == "not-applicable-reviewed" {
                    if status != "not-applicable"
                        || !evidence.is_empty()
                        || !obligations.is_empty()
                        || !normalizer_ids.is_empty()
                        || !normalizer_refs.is_empty()
                        || !matches!(divergence_ref, JsonValue::Null)
                    {
                        return Err("reviewed not-applicable cell has the wrong status".to_owned());
                    }
                } else {
                    if !matches!(
                        status,
                        "exact" | "normalized" | "platform-dependent" | "deliberate-divergence"
                    ) || evidence.is_empty()
                        || obligations.is_empty()
                    {
                        return Err(
                            "applicable claim cell lacks status, evidence, or obligations"
                                .to_owned(),
                        );
                    }
                    validate_claim_status_shape(
                        status,
                        normalizer_ids,
                        normalizer_refs,
                        divergence_ref,
                    )?;
                    let required_obligations = claim_obligations(builtin, dimension, platform)?;
                    let declared_obligations = obligations
                        .iter()
                        .map(JsonValue::string)
                        .map(|obligation| obligation.map(str::to_owned))
                        .collect::<Result<Vec<_>, _>>()?;
                    if declared_obligations.len()
                        != declared_obligations.iter().collect::<BTreeSet<_>>().len()
                        || declared_obligations.into_iter().collect::<BTreeSet<_>>()
                            != required_obligations
                    {
                        return Err(
                            "claim cell obligations do not match the canonical family".to_owned()
                        );
                    }
                    require_unique_claim_evidence_edges(evidence)?;
                    let mut evidenced_obligations = BTreeSet::new();
                    for reference in evidence {
                        evidenced_obligations.extend(verify_claim_evidence_reference(
                            reference, path, builtin, dimension, platform, candidate, epoch,
                        )?);
                        if scoped {
                            let reference = reference.object()?;
                            if !scoped_evidence_edges.insert((
                                json_member(reference, "caseId")?.string()?.to_owned(),
                                json_member(reference, "platform")?.string()?.to_owned(),
                            )) {
                                return Err(
                                    "active collection coverage duplicates a case/platform edge"
                                        .to_owned(),
                                );
                            }
                        }
                    }
                    if evidenced_obligations
                        != required_obligations
                            .iter()
                            .map(|obligation| (*obligation).clone())
                            .collect()
                    {
                        return Err(
                            "claim evidence edges do not cover every canonical obligation"
                                .to_owned(),
                        );
                    }
                }
            }
            if scoped {
                verify_scoped_collection_evidence_edges(&scoped_evidence_edges)?;
            }
            verify_platform_dependent_cells(cells, path)?;
            if json_member(details, "ambiguousClaimScopes")?.number()? != reviewed_ambiguous
                || reviewed_ambiguous != 0
                || !retained_decisions.is_empty()
            {
                return Err("claim applicability still needs explicit review".to_owned());
            }
        }
        "normalizer-audit" => {
            exact_keys(
                details,
                &[
                    "applications",
                    "applicationRecords",
                    "assuranceEpochSha256",
                    "auditedApplications",
                    "candidateSourceCommit",
                    "exactClaimsUsingNormalizers",
                    "failedMutants",
                    "normalizerMutantsDetected",
                    "normalizerMutantsRequired",
                    "protectedFieldChanges",
                    "schemaVersion",
                    "unsafeNormalizers",
                ],
            )?;
            let applications = json_member(details, "applicationRecords")?.array()?;
            let application_count = u64::try_from(applications.len())
                .map_err(|_| "normalizer application count exceeds u64".to_owned())?;
            if verify_summary_counter(
                json_member(details, "applications")?.number()?,
                application_count,
            )
            .is_err()
                || application_count == 0
                || json_member(details, "applications")?.number()?
                    != json_member(details, "auditedApplications")?.number()?
                || json_member(details, "normalizerMutantsRequired")?.number()? == 0
                || json_member(details, "normalizerMutantsRequired")?.number()?
                    != json_member(details, "normalizerMutantsDetected")?.number()?
                || [
                    "exactClaimsUsingNormalizers",
                    "failedMutants",
                    "protectedFieldChanges",
                    "unsafeNormalizers",
                ]
                .into_iter()
                .any(|field| json_member(details, field).and_then(JsonValue::number) != Ok(0))
            {
                return Err(
                    "normalizer certification has unsafe or unaudited transformations".to_owned(),
                );
            }
            for application in applications {
                let application = application.object()?;
                exact_keys(
                    application,
                    &[
                        "applicationRef",
                        "applicationScope",
                        "assuranceEpochSha256",
                        "builtin",
                        "candidateSourceCommit",
                        "changedPaths",
                        "changedValues",
                        "contextPath",
                        "contextSha256",
                        "dimension",
                        "evidenceRef",
                        "idempotent",
                        "implementationSha256",
                        "inputPath",
                        "inputSha256",
                        "mutationSuitePath",
                        "mutationSuiteSha256",
                        "normalizerId",
                        "observationRole",
                        "outputPath",
                        "outputSha256",
                        "platform",
                        "profile",
                        "protectedFieldsUnchanged",
                        "removedBytes",
                        "sandboxPath",
                        "secondOutputPath",
                        "secondOutputSha256",
                        "scriptPath",
                    ],
                )?;
                for field in [
                    "applicationRef",
                    "contextSha256",
                    "evidenceRef",
                    "inputSha256",
                    "mutationSuiteSha256",
                    "outputSha256",
                    "secondOutputSha256",
                ] {
                    require_digest(
                        json_member(application, field)?.string()?,
                        "normalizer application field",
                    )?;
                }
                if !matches!(
                    json_member(application, "applicationScope")?.string()?,
                    "harness-stderr" | "claim-stderr"
                ) || !matches!(
                    json_member(application, "observationRole")?.string()?,
                    "candidate" | "oracle"
                ) {
                    return Err("normalizer application scope or role is invalid".to_owned());
                }
                let expected_application_ref = normalizer_application_ref(
                    json_member(application, "builtin")?.string()?,
                    json_member(application, "dimension")?.string()?,
                    json_member(application, "platform")?.string()?,
                    json_member(application, "evidenceRef")?.string()?,
                    json_member(application, "observationRole")?.string()?,
                    json_member(application, "normalizerId")?.string()?,
                    json_member(application, "applicationScope")?.string()?,
                )?;
                if json_member(application, "applicationRef")?.string()? != expected_application_ref
                {
                    return Err(
                        "normalizer application reference identity was substituted".to_owned()
                    );
                }
                let repository = repository_root()?;
                let retained_root = retained_evidence_root(path)?;
                let mut retained_input = None;
                let mut retained_output = None;
                let mut retained_second_output = None;
                let mut retained_context = None;
                for (path_field, digest_field) in [
                    ("contextPath", "contextSha256"),
                    ("inputPath", "inputSha256"),
                    ("outputPath", "outputSha256"),
                    ("secondOutputPath", "secondOutputSha256"),
                    ("mutationSuitePath", "mutationSuiteSha256"),
                ] {
                    let retained = confined_record_path(
                        &repository,
                        retained_root,
                        Path::new(json_member(application, path_field)?.string()?),
                    )?;
                    verify_file_digest(
                        &retained,
                        json_member(application, digest_field)?.string()?,
                        digest_field,
                    )?;
                    match path_field {
                        "contextPath" => retained_context = Some(retained),
                        "inputPath" => retained_input = Some(retained),
                        "outputPath" => retained_output = Some(retained),
                        "secondOutputPath" => retained_second_output = Some(retained),
                        _ => {}
                    }
                }
                verify_normalizer_application_files(
                    application,
                    retained_input
                        .as_deref()
                        .ok_or_else(|| "normalizer application lacks retained input".to_owned())?,
                    retained_output
                        .as_deref()
                        .ok_or_else(|| "normalizer application lacks retained output".to_owned())?,
                    retained_second_output.as_deref().ok_or_else(|| {
                        "normalizer application lacks retained second output".to_owned()
                    })?,
                    retained_context.as_deref().ok_or_else(|| {
                        "normalizer application lacks retained context".to_owned()
                    })?,
                )?;
                if json_member(application, "candidateSourceCommit")?.string()? != candidate
                    || json_member(application, "assuranceEpochSha256")?.string()? != epoch
                    || !json_member(application, "idempotent")?.boolean()?
                    || !json_member(application, "protectedFieldsUnchanged")?.boolean()?
                    || !hell_builtins::NormalizerId::ALL.iter().any(|normalizer| {
                        normalizer.as_str()
                            == json_member(application, "normalizerId")
                                .and_then(JsonValue::string)
                                .unwrap_or("")
                    })
                {
                    return Err("normalizer application is unsafe or unknown".to_owned());
                }
            }
        }
        "divergence" => {
            verify_generated_divergence_policy()?;
            exact_keys(
                details,
                &[
                    "activeDivergences",
                    "approvedDivergences",
                    "assuranceEpochSha256",
                    "candidateSourceCommit",
                    "expiredDivergences",
                    "fingerprintMismatches",
                    "missingImpactApprovals",
                    "proposedRecords",
                    "records",
                    "schemaVersion",
                    "wildcardScopes",
                ],
            )?;
            let records = json_member(details, "records")?.array()?;
            let proposed_records = json_member(details, "proposedRecords")?.array()?;
            if json_member(details, "activeDivergences")?.number()?
                != u64::try_from(records.len())
                    .map_err(|_| "divergence record count exceeds u64".to_owned())?
                || json_member(details, "activeDivergences")?.number()?
                    != json_member(details, "approvedDivergences")?.number()?
                || json_member(details, "missingImpactApprovals")?.number()?
                    != u64::try_from(proposed_records.len())
                        .map_err(|_| "proposed divergence count exceeds u64".to_owned())?
                || [
                    "expiredDivergences",
                    "fingerprintMismatches",
                    "wildcardScopes",
                ]
                .into_iter()
                .any(|field| json_member(details, field).and_then(JsonValue::number) != Ok(0))
            {
                return Err(
                    "divergence records are expired, broad, changed, or unapproved".to_owned(),
                );
            }
            for proposed in proposed_records {
                verify_proposed_divergence_record(proposed.object()?)?;
            }
            for record in records {
                verify_accepted_divergence_record(record.object()?, path)?;
            }
        }
        "residual-risk" => {
            exact_keys(
                details,
                &[
                    "assuranceEpochSha256",
                    "boundaryClasses",
                    "boundedEvidenceStatement",
                    "capabilityBreadth",
                    "candidateSourceCommit",
                    "claimCoverageSha256",
                    "claimStatusCounts",
                    "criticalNonExactClaimCells",
                    "custodyEvaluationStage",
                    "custodyStatus",
                    "divergentClaimCells",
                    "environmentVariables",
                    "missingBoundaryClasses",
                    "missingClaimObligations",
                    "minimumMutationFamilyScorePerMille",
                    "mutationFamilyScoresPerMille",
                    "mutationReportSha256",
                    "nativeCorpusInputs",
                    "normalizedClaimCells",
                    "obligationCoverage",
                    "observedCapabilityEvidence",
                    "outOfScopeClaimCells",
                    "overallTier",
                    "platformDependentClaimCells",
                    "platforms",
                    "policyDerivation",
                    "profiles",
                    "promotedClaimCells",
                    "schemaVersion",
                    "evidenceAge",
                    "knownOpenIssues",
                    "undetectedCriticalMutants",
                    "undetectedMutantIds",
                    "unacceptableClaimGroups",
                    "unverifiedClaimCells",
                ],
            )?;
            verify_residual_risk_facts(details)?;
            verify_residual_source_bindings(path, details, candidate, epoch)?;
            let policy = load_assurance_policy(&repository_root()?)?.residual;
            if !policy
                .acceptable_tiers
                .contains(json_member(details, "overallTier")?.string()?)
                || [
                    "missingBoundaryClasses",
                    "missingClaimObligations",
                    "undetectedCriticalMutants",
                    "unacceptableClaimGroups",
                    "unverifiedClaimCells",
                ]
                .into_iter()
                .any(|field| json_member(details, field).and_then(JsonValue::number) != Ok(0))
            {
                return Err("residual compatibility risk is unacceptable".to_owned());
            }
            json_member(details, "outOfScopeClaimCells")?.number()?;
            json_member(details, "unverifiedClaimCells")?.number()?;
        }
        "review-role-graph" => {
            exact_keys(
                details,
                &[
                    "actions",
                    "assuranceEpochSha256",
                    "candidateSourceCommit",
                    "distinctSubjects",
                    "policyViolations",
                    "requiredRoles",
                    "schemaVersion",
                    "verifiedRoles",
                ],
            )?;
            let required = json_member(details, "requiredRoles")?.array()?;
            let verified = json_member(details, "verifiedRoles")?.array()?;
            let repository = repository_root()?;
            let minimum_distinct_people = load_review_policy(&repository)?.minimum_distinct_people;
            if declared_human_reviewer_subject_count(details)? < minimum_distinct_people
                || !json_member(details, "policyViolations")?
                    .array()?
                    .is_empty()
                || json_member(details, "actions")?.array()?.is_empty()
                || required.is_empty()
                || required != verified
            {
                return Err(
                    "review role graph violates authorization or independence policy".to_owned(),
                );
            }
        }
        _ => return Err(format!("unknown bound report kind {kind:?}")),
    }
    Ok(())
}

pub(crate) fn verify_divergence_report_for_publication(path: &Path) -> Result<(), String> {
    let document = parse_json(&read_text(path)?)?;
    let details = document.object()?;
    let candidate = json_member(details, "candidateSourceCommit")?.string()?;
    let epoch = json_member(details, "assuranceEpochSha256")?.string()?;
    verify_bound_details(path, "divergence", candidate, epoch)
}

pub(crate) fn public_divergence_details_bytes(path: &Path) -> Result<Vec<u8>, String> {
    verify_divergence_report_for_publication(path)?;
    let retained_root = retained_evidence_root(path)?;
    let details = bound_details_document(path, retained_root)?;
    canonical_json_bytes(&details)
}

pub(crate) fn verify_active_accepted_divergence(
    active_root: &Path,
    candidate: &str,
    epoch: &str,
    case_id: &str,
    raw_mismatches: &[hell_testkit::RetainedMismatchFact],
    normalized_mismatches: &[hell_testkit::RetainedMismatchFact],
    fingerprint_sha256: &Digest,
) -> Result<String, String> {
    let report = active_divergence_report_path(active_root)?;
    verify_divergence_report_for_publication(&report)?;
    let document = parse_json(&read_text(&report)?)?;
    let details = document.object()?;
    if json_member(details, "candidateSourceCommit")?.string()? != candidate
        || json_member(details, "assuranceEpochSha256")?.string()? != epoch
    {
        return Err("active divergence report identity is stale".to_owned());
    }
    let raw_sha256 = mismatch_fact_set_digest(raw_mismatches)?;
    let normalized_sha256 = mismatch_fact_set_digest(normalized_mismatches)?;
    let matching = json_member(details, "records")?
        .array()?
        .iter()
        .map(JsonValue::object)
        .collect::<Result<Vec<_>, _>>()?
        .into_iter()
        .filter(|record| {
            json_member(record, "caseId").and_then(JsonValue::string) == Ok(case_id)
                && json_member(record, "platform").and_then(JsonValue::string) == Ok("linux-amd64")
                && json_member(record, "profile").and_then(JsonValue::string) == Ok("upstream")
                && json_member(record, "rawObservationSha256").and_then(JsonValue::string)
                    == Ok(raw_sha256.as_str())
                && json_member(record, "normalizedObservationSha256").and_then(JsonValue::string)
                    == Ok(normalized_sha256.as_str())
                && json_member(record, "mismatchFingerprint").and_then(JsonValue::string)
                    == Ok(fingerprint_sha256.hex().as_str())
        })
        .map(|record| {
            json_member(record, "divergenceId")?
                .string()
                .map(str::to_owned)
        })
        .collect::<Result<Vec<_>, String>>()?;
    let [divergence_id] = matching.as_slice() else {
        return Err(format!(
            "retained mismatch for {case_id:?} does not match exactly one immutable accepted divergence"
        ));
    };
    Ok(divergence_id.clone())
}

pub(crate) fn active_accepted_divergence_ids(
    active_root: &Path,
    candidate: &str,
    epoch: &str,
) -> Result<BTreeSet<String>, String> {
    let report = active_divergence_report_path(active_root)?;
    verify_divergence_report_for_publication(&report)?;
    let document = parse_json(&read_text(&report)?)?;
    let details = document.object()?;
    if json_member(details, "candidateSourceCommit")?.string()? != candidate
        || json_member(details, "assuranceEpochSha256")?.string()? != epoch
    {
        return Err("active divergence report identity is stale".to_owned());
    }
    json_member(details, "records")?
        .array()?
        .iter()
        .map(JsonValue::object)
        .collect::<Result<Vec<_>, _>>()?
        .into_iter()
        .filter(|record| {
            json_member(record, "platform").and_then(JsonValue::string) == Ok("linux-amd64")
                && json_member(record, "profile").and_then(JsonValue::string) == Ok("upstream")
        })
        .map(|record| {
            json_member(record, "divergenceId")?
                .string()
                .map(str::to_owned)
        })
        .collect()
}

fn active_divergence_report_path(active_root: &Path) -> Result<PathBuf, String> {
    let mut files = Vec::new();
    collect_manifest_files(active_root, active_root, &mut files)?;
    let reports = files
        .into_iter()
        .filter_map(|(relative, _, _)| {
            let relative = PathBuf::from(relative);
            relative
                .file_name()
                .is_some_and(|name| name == "divergence-report.details.json")
                .then(|| active_root.join(relative))
        })
        .collect::<Vec<_>>();
    if reports.len() != 1 {
        return Err(
            "active promotion must retain exactly one canonical divergence details report"
                .to_owned(),
        );
    }
    Ok(reports[0].clone())
}

fn verify_summary_counter(summary: u64, derived: u64) -> Result<(), String> {
    if summary == derived || crate::assurance_control_mutant_active("summary-zero-counter-forgery")
    {
        Ok(())
    } else {
        Err("summary counter does not match retained inner evidence".to_owned())
    }
}

fn verify_residual_risk_facts(details: &BTreeMap<String, JsonValue>) -> Result<(), String> {
    if json_member(details, "boundedEvidenceStatement")?.string()?
        != "finite retained corpus evidence is not universal proof of compatibility"
    {
        return Err("residual-risk omits its finite-evidence limitation".to_owned());
    }
    require_digest(
        json_member(details, "claimCoverageSha256")?.string()?,
        "residual-risk claim coverage",
    )?;
    require_digest(
        json_member(details, "mutationReportSha256")?.string()?,
        "residual-risk mutation report",
    )?;
    verify_residual_status_partition(details)?;
    let evidence_age = json_member(details, "evidenceAge")?.object()?;
    let policy = load_assurance_policy(&repository_root()?)?.residual;
    let expected_tier = residual_overall_tier(
        &ResidualRiskFactors {
            missing_boundaries: json_member(details, "missingBoundaryClasses")?.number()?,
            missing_obligations: json_member(details, "missingClaimObligations")?.number()?,
            unacceptable: json_member(details, "unacceptableClaimGroups")?.number()?,
            undetected: json_member(details, "undetectedCriticalMutants")?.number()?,
            unverified: json_member(details, "unverifiedClaimCells")?.number()?,
            out_of_scope: json_member(details, "outOfScopeClaimCells")?.number()?,
            normalized: json_member(details, "normalizedClaimCells")?.number()?,
            platform_dependent: json_member(details, "platformDependentClaimCells")?.number()?,
            divergences: json_member(details, "divergentClaimCells")?.number()?,
            critical_non_exact: json_member(details, "criticalNonExactClaimCells")?.number()?,
            minimum_mutation_score: json_member(details, "minimumMutationFamilyScorePerMille")?
                .number()?,
            stale_evidence_sources: json_member(evidence_age, "staleSourceCount")?.number()?,
            aging_evidence_sources: json_member(evidence_age, "warningSourceCount")?.number()?,
            observed_platforms: json_member(details, "platforms")?.array()?.len(),
            custody_current: json_member(
                json_member(details, "custodyStatus")?.object()?,
                "currentStatus",
            )?
            .string()?
                == "current-verified",
        },
        &policy,
    );
    if json_member(details, "overallTier")?.string()? != expected_tier {
        return Err("residual-risk tier is not derived from all unresolved scope".to_owned());
    }
    verify_residual_obligation_records(json_member(details, "obligationCoverage")?.array()?)?;
    for field in [
        "boundaryClasses",
        "capabilityBreadth",
        "undetectedMutantIds",
    ] {
        verify_sorted_unique_string_array(json_member(details, field)?.array()?, field)?;
    }
    if json_member(details, "missingBoundaryClasses")?.number()?
        != residual_missing_boundary_count(json_member(details, "boundaryClasses")?.array()?)?
    {
        return Err("residual-risk boundary count does not match retained classes".to_owned());
    }
    verify_residual_native_records(
        json_member(details, "nativeCorpusInputs")?.array()?,
        json_member(details, "environmentVariables")?.array()?,
        json_member(details, "platforms")?.array()?,
        json_member(details, "profiles")?.array()?,
    )?;
    verify_residual_capability_records(
        json_member(details, "observedCapabilityEvidence")?.array()?,
        json_member(details, "capabilityBreadth")?.array()?,
    )?;
    verify_residual_age_record(evidence_age)?;
    verify_residual_issue_records(json_member(details, "knownOpenIssues")?.array()?)?;
    verify_residual_custody_status(json_member(details, "custodyStatus")?.object()?)?;
    if json_member(details, "custodyEvaluationStage")?.string()? != "pre-custody-proposal-input" {
        return Err("residual-risk execution breadth or stage is invalid".to_owned());
    }
    for score in json_member(details, "mutationFamilyScoresPerMille")?
        .object()?
        .values()
    {
        if score.number()? > 1_000 {
            return Err("residual-risk mutation score exceeds one thousand per mille".to_owned());
        }
    }
    let policy = json_member(details, "policyDerivation")?.object()?;
    exact_keys(
        policy,
        &[
            "assurancePolicySha256",
            "claimRulesSha256",
            "corpusObligationsSha256",
            "mutationPolicySha256",
        ],
    )?;
    for digest in policy.values() {
        require_digest(digest.string()?, "residual-risk policy source")?;
    }
    Ok(())
}

fn verify_residual_native_records(
    records: &[JsonValue],
    environment_variables: &[JsonValue],
    platforms: &[JsonValue],
    profiles: &[JsonValue],
) -> Result<(), String> {
    if records.len() != REQUIRED_CLAIM_PLATFORMS.len() {
        return Err("residual-risk lacks one exact native corpus record per platform".to_owned());
    }
    let mut observed_platforms = Vec::new();
    let mut observed_environment_variables = BTreeSet::new();
    for record in records {
        let record = record.object()?;
        exact_keys(
            record,
            &[
                "buildEnvironmentSha256",
                "cargoIdentity",
                "cargoVersionSha256",
                "collectedAt",
                "committedInputCount",
                "corpusSeed",
                "corpusSha256",
                "environmentVariables",
                "generatedInputCount",
                "generatedStressCorpusSha256",
                "imageOs",
                "imageVersion",
                "nativeEnvironmentPath",
                "nativeEnvironmentSha256",
                "platform",
                "reviewedCommittedCorpusSha256",
                "runnerArch",
                "runnerImageIdentitySha256",
                "runnerKind",
                "runnerOs",
                "rustToolchainSha256",
                "rustToolchainSelectionSha256",
                "rustcExecutablePathSha256",
                "rustcExecutableSha256",
                "rustcIdentity",
                "rustcVerboseSha256",
                "summaryPath",
                "summarySha256",
            ],
        )?;
        for field in [
            "buildEnvironmentSha256",
            "cargoVersionSha256",
            "corpusSha256",
            "generatedStressCorpusSha256",
            "nativeEnvironmentSha256",
            "reviewedCommittedCorpusSha256",
            "runnerImageIdentitySha256",
            "rustToolchainSha256",
            "rustToolchainSelectionSha256",
            "rustcExecutablePathSha256",
            "rustcExecutableSha256",
            "rustcVerboseSha256",
            "summarySha256",
        ] {
            require_digest(
                json_member(record, field)?.string()?,
                "residual native corpus",
            )?;
        }
        validate_utc_timestamp(json_member(record, "collectedAt")?.string()?)?;
        verify_residual_native_environment_record(record, &mut observed_environment_variables)?;
        validate_provider_workflow_path(json_member(record, "nativeEnvironmentPath")?.string()?)?;
        if json_member(record, "committedInputCount")?.number()? == 0
            || json_member(record, "generatedInputCount")?.number()? == 0
            || json_member(record, "corpusSeed")?.number()? == 0
        {
            return Err("residual native corpus counts or seed are empty".to_owned());
        }
        validate_provider_workflow_path(json_member(record, "summaryPath")?.string()?)?;
        observed_platforms.push(json_member(record, "platform")?.clone());
    }
    if platforms != observed_platforms
        || platforms
            != REQUIRED_CLAIM_PLATFORMS
                .iter()
                .map(|value| JsonValue::String((*value).to_owned()))
                .collect::<Vec<_>>()
        || profiles != [JsonValue::String("upstream".to_owned())]
    {
        return Err("residual native execution breadth is incomplete".to_owned());
    }
    let expected_environment_variables = observed_environment_variables
        .into_iter()
        .map(JsonValue::String)
        .collect::<Vec<_>>();
    if environment_variables != expected_environment_variables {
        return Err("residual environment-variable breadth is incomplete".to_owned());
    }
    Ok(())
}

fn verify_residual_native_environment_record(
    record: &BTreeMap<String, JsonValue>,
    observed_environment_variables: &mut BTreeSet<String>,
) -> Result<(), String> {
    let retained_variables = json_member(record, "environmentVariables")?.array()?;
    if retained_variables.len() != hell_testkit::NATIVE_BUILD_ENVIRONMENT_NAMES.len()
        || json_member(record, "runnerKind")?.string()? != "github-actions"
        || json_member(record, "runnerOs")?.string()?.is_empty()
        || json_member(record, "runnerArch")?.string()?.is_empty()
        || matches!(
            json_member(record, "imageOs")?.string()?,
            "" | "not-reported"
        )
        || matches!(
            json_member(record, "imageVersion")?.string()?,
            "" | "not-reported"
        )
        || json_member(record, "rustcIdentity")?.string()?.is_empty()
        || json_member(record, "cargoIdentity")?.string()?.is_empty()
    {
        return Err("residual native environment breadth is incomplete".to_owned());
    }
    for (retained, expected_name) in retained_variables
        .iter()
        .zip(hell_testkit::NATIVE_BUILD_ENVIRONMENT_NAMES)
    {
        let retained = retained.object()?;
        exact_keys(retained, &["name", "present", "valueSha256"])?;
        if json_member(retained, "name")?.string()? != expected_name {
            return Err("residual native environment variable order is stale".to_owned());
        }
        if json_member(retained, "present")?.boolean()? {
            observed_environment_variables.insert(expected_name.to_owned());
        }
        require_digest(
            json_member(retained, "valueSha256")?.string()?,
            "residual native environment variable",
        )?;
    }
    Ok(())
}

fn verify_residual_capability_records(
    records: &[JsonValue],
    breadth: &[JsonValue],
) -> Result<(), String> {
    let mut observed = Vec::new();
    for record in records {
        let record = record.object()?;
        exact_keys(record, &["capability", "observations"])?;
        let capability = json_member(record, "capability")?.string()?;
        if capability.is_empty() {
            return Err("residual observed capability is empty".to_owned());
        }
        verify_sorted_unique_string_array(
            json_member(record, "observations")?.array()?,
            "residual capability observations",
        )?;
        if json_member(record, "observations")?.array()?.is_empty() {
            return Err("residual capability has no retained observation".to_owned());
        }
        observed.push(JsonValue::String(capability.to_owned()));
    }
    if breadth != observed {
        return Err("residual capability breadth is not observation-derived".to_owned());
    }
    verify_sorted_unique_string_array(breadth, "residual capability breadth")
}

fn verify_residual_age_record(record: &BTreeMap<String, JsonValue>) -> Result<(), String> {
    exact_keys(
        record,
        &[
            "mutationPolicySha256",
            "observedAt",
            "oldestAgeSeconds",
            "sources",
            "staleSourceCount",
            "surveillancePolicySha256",
            "warningSourceCount",
        ],
    )?;
    for field in ["mutationPolicySha256", "surveillancePolicySha256"] {
        require_digest(
            json_member(record, field)?.string()?,
            "residual evidence age policy",
        )?;
    }
    let observed_at = utc_timestamp_seconds(json_member(record, "observedAt")?.string()?)?;
    let current = current_utc_seconds()?;
    if observed_at > current {
        return Err("residual evidence age observation is future-dated".to_owned());
    }
    let sources = json_member(record, "sources")?.array()?;
    if sources.len() != REQUIRED_CLAIM_PLATFORMS.len() + 1 {
        return Err("residual evidence age lacks mutation or native sources".to_owned());
    }
    let mut previous = None::<String>;
    let mut oldest = 0_u64;
    let mut stale = 0_u64;
    let mut warning = 0_u64;
    for source in sources {
        let source = source.object()?;
        exact_keys(
            source,
            &[
                "ageSeconds",
                "collectedAt",
                "kind",
                "maximumAgeSeconds",
                "platform",
                "sourcePath",
                "sourceSha256",
            ],
        )?;
        validate_utc_timestamp(json_member(source, "collectedAt")?.string()?)?;
        require_digest(
            json_member(source, "sourceSha256")?.string()?,
            "residual evidence age source",
        )?;
        validate_provider_workflow_path(json_member(source, "sourcePath")?.string()?)?;
        let kind = json_member(source, "kind")?.string()?;
        let platform = json_member(source, "platform")?.string()?;
        if !matches!(kind, "mutation-report" | "native-shard")
            || (kind == "mutation-report" && platform != "all")
            || (kind == "native-shard" && !REQUIRED_CLAIM_PLATFORMS.contains(&platform))
        {
            return Err("residual evidence age has an unknown source".to_owned());
        }
        let key = format!("{kind}|{platform}");
        if previous
            .as_deref()
            .is_some_and(|value| value >= key.as_str())
        {
            return Err("residual evidence age sources are duplicated or unsorted".to_owned());
        }
        previous = Some(key);
        let age = json_member(source, "ageSeconds")?.number()?;
        let maximum = json_member(source, "maximumAgeSeconds")?.number()?;
        if maximum == 0 {
            return Err("residual evidence age source has no policy window".to_owned());
        }
        oldest = oldest.max(age);
        if age > maximum {
            stale = stale.saturating_add(1);
        } else if age > maximum / 2 {
            warning = warning.saturating_add(1);
        }
        let collected = utc_timestamp_seconds(json_member(source, "collectedAt")?.string()?)?;
        let current_age = current.saturating_sub(collected);
        if collected > current
            || (current_age > maximum && age <= maximum)
            || (current_age > maximum / 2 && age <= maximum / 2)
        {
            return Err("residual evidence source aged beyond its reviewed tier".to_owned());
        }
    }
    if json_member(record, "oldestAgeSeconds")?.number()? != oldest
        || json_member(record, "staleSourceCount")?.number()? != stale
        || json_member(record, "warningSourceCount")?.number()? != warning
    {
        return Err("residual evidence age does not identify the oldest source".to_owned());
    }
    Ok(())
}

fn verify_residual_custody_status(record: &BTreeMap<String, JsonValue>) -> Result<(), String> {
    exact_keys(
        record,
        &[
            "currentStatus",
            "evaluationStage",
            "finalAssessmentSource",
            "minimumCopies",
            "policySha256",
        ],
    )?;
    require_digest(
        json_member(record, "policySha256")?.string()?,
        "residual custody policy",
    )?;
    if json_member(record, "currentStatus")?.string()? != "pending-post-review-custody"
        || json_member(record, "evaluationStage")?.string()? != "pre-custody-proposal-input"
        || json_member(record, "finalAssessmentSource")?.string()? != "proposal-custody-record"
        || json_member(record, "minimumCopies")?.number()? < 2
    {
        return Err("residual custody status overstates current evidence".to_owned());
    }
    Ok(())
}

fn verify_residual_issue_records(records: &[JsonValue]) -> Result<(), String> {
    let mut previous = None::<String>;
    for record in records {
        let record = record.object()?;
        exact_keys(record, &["kind", "reference", "trackingIssueNumber"])?;
        let kind = json_member(record, "kind")?.string()?;
        let reference = json_member(record, "reference")?.string()?;
        if reference.is_empty()
            || !matches!(
                kind,
                "accepted-divergence" | "claim-status" | "undetected-mutant"
            )
        {
            return Err("residual known issues are invalid or unsorted".to_owned());
        }
        if kind == "accepted-divergence" {
            require_digest(reference, "residual divergence issue")?;
            if json_member(record, "trackingIssueNumber")?.number()? == 0 {
                return Err("residual accepted divergence has no tracking issue".to_owned());
            }
        } else if json_member(record, "trackingIssueNumber")? != &JsonValue::Null {
            return Err("untracked residual finding overstates a tracking issue".to_owned());
        }
        let key = format!("{kind}|{reference}");
        if previous
            .as_deref()
            .is_some_and(|value| value >= key.as_str())
        {
            return Err("residual known issues are invalid or unsorted".to_owned());
        }
        previous = Some(key);
    }
    Ok(())
}

fn verify_residual_source_bindings(
    path: &Path,
    details: &BTreeMap<String, JsonValue>,
    candidate: &str,
    epoch: &str,
) -> Result<(), String> {
    let directory = path
        .parent()
        .ok_or_else(|| "residual-risk report has no retained directory".to_owned())?;
    let coverage_path = directory.join("claim-coverage.finalized.json");
    let mutation_path = directory.join("mutation-score.json");
    verify_file_digest(
        &coverage_path,
        json_member(details, "claimCoverageSha256")?.string()?,
        "claimCoverageSha256",
    )?;
    verify_file_digest(
        &mutation_path,
        json_member(details, "mutationReportSha256")?.string()?,
        "mutationReportSha256",
    )?;
    verify_bound_details(&coverage_path, "claim-coverage", candidate, epoch)?;
    let coverage = parse_json(&read_text(&coverage_path)?)?;
    let coverage = coverage.object()?;
    let cells = json_member(coverage, "cells")?.array()?;
    verify_residual_claim_source_facts(
        details,
        coverage,
        json_member(coverage, "requiredPlatformGaps")?.number()?,
        json_member(coverage, "ambiguousClaimScopes")?.number()?,
    )?;
    let repository = repository_root()?;
    retained_report_command(
        &repository,
        &Options {
            input: Some(mutation_path.clone()),
            policy: Some(directory.join("reviewer.allowed_signers")),
            expect_source: Some(candidate.to_owned()),
            expect_epoch: Some(epoch.to_owned()),
            ..Options::default()
        },
        "mutation",
    )?;
    let (expected_scores, expected_undetected) = residual_mutation_facts(&mutation_path)?;
    let expected_native = residual_native_corpus_inputs(directory, candidate, epoch)?;
    let expected_capability_evidence = residual_observed_capability_evidence(cells)?;
    let expected_age = residual_evidence_age(
        &repository,
        &mutation_path,
        &expected_native,
        Some(json_member(json_member(details, "evidenceAge")?.object()?, "observedAt")?.string()?),
    )?;
    let expected_issues = residual_known_open_issues(directory, cells, &expected_undetected)?;
    if json_member(details, "mutationFamilyScoresPerMille")? != &expected_scores
        || json_member(details, "undetectedMutantIds")?
            != &JsonValue::Array(expected_undetected.clone())
        || json_member(details, "undetectedCriticalMutants")?.number()?
            != mutation_undetected_count(&mutation_path)?
        || json_member(details, "policyDerivation")? != &residual_policy_derivation(&repository)?
        || json_member(details, "nativeCorpusInputs")?
            != &JsonValue::Array(expected_native.corpus_inputs)
        || json_member(details, "environmentVariables")?
            != &JsonValue::Array(expected_native.environment_variables)
        || json_member(details, "platforms")? != &JsonValue::Array(expected_native.platforms)
        || json_member(details, "profiles")? != &JsonValue::Array(expected_native.profiles)
        || json_member(details, "observedCapabilityEvidence")?
            != &JsonValue::Array(expected_capability_evidence)
        || json_member(details, "evidenceAge")? != &expected_age
        || json_member(details, "knownOpenIssues")? != &JsonValue::Array(expected_issues)
        || json_member(details, "custodyStatus")? != &residual_custody_status(&repository)?
        || json_member(details, "criticalNonExactClaimCells")?.number()?
            != residual_critical_non_exact_cells(cells)?
        || json_member(details, "minimumMutationFamilyScorePerMille")?.number()?
            != residual_minimum_mutation_score(&expected_scores)?
        || json_member(details, "missingClaimObligations")?.number()?
            != residual_missing_obligation_count(cells)?
    {
        return Err("residual-risk facts do not match mutation or policy sources".to_owned());
    }
    Ok(())
}

fn verify_residual_claim_source_facts(
    details: &BTreeMap<String, JsonValue>,
    coverage: &BTreeMap<String, JsonValue>,
    required_platform_gaps: u64,
    ambiguous_claim_scopes: u64,
) -> Result<(), String> {
    let cells = json_member(coverage, "cells")?.array()?;
    let expected_statuses = JsonValue::Object(
        claim_coverage_status_counts(coverage)?
            .into_iter()
            .map(|(status, count)| (status, JsonValue::Number(count)))
            .collect(),
    );
    let expected_obligations = JsonValue::Array(residual_obligation_coverage(cells)?);
    let expected_boundaries = JsonValue::Array(residual_boundary_classes(cells)?);
    let expected_capabilities = JsonValue::Array(
        residual_observed_capability_evidence(cells)?
            .into_iter()
            .map(|record| {
                let record = record.object()?;
                json_member(record, "capability").cloned()
            })
            .collect::<Result<Vec<_>, String>>()?,
    );
    if json_member(details, "claimStatusCounts")? != &expected_statuses
        || json_member(details, "obligationCoverage")? != &expected_obligations
        || json_member(details, "boundaryClasses")? != &expected_boundaries
        || json_member(details, "capabilityBreadth")? != &expected_capabilities
        || json_member(details, "missingBoundaryClasses")?.number()?
            != residual_missing_boundary_count(expected_boundaries.array()?)?
        || json_member(details, "unacceptableClaimGroups")?.number()?
            != required_platform_gaps.saturating_add(ambiguous_claim_scopes)
    {
        return Err("residual-risk facts do not match finalized claim coverage".to_owned());
    }
    Ok(())
}

fn verify_residual_status_partition(details: &BTreeMap<String, JsonValue>) -> Result<(), String> {
    let statuses = json_member(details, "claimStatusCounts")?.object()?;
    exact_keys(
        statuses,
        &[
            "deliberate-divergence",
            "exact",
            "normalized",
            "not-applicable",
            "platform-dependent",
            "unverified",
        ],
    )?;
    let promoted = json_member(statuses, "exact")?
        .number()?
        .saturating_add(json_member(statuses, "normalized")?.number()?)
        .saturating_add(json_member(statuses, "platform-dependent")?.number()?)
        .saturating_add(json_member(statuses, "deliberate-divergence")?.number()?);
    if json_member(details, "promotedClaimCells")?.number()? != promoted
        || json_member(details, "normalizedClaimCells")?.number()?
            != json_member(statuses, "normalized")?.number()?
        || json_member(details, "platformDependentClaimCells")?.number()?
            != json_member(statuses, "platform-dependent")?.number()?
        || json_member(details, "divergentClaimCells")?.number()?
            != json_member(statuses, "deliberate-divergence")?.number()?
        || json_member(details, "outOfScopeClaimCells")?.number()?
            != json_member(statuses, "not-applicable")?.number()?
        || json_member(details, "unverifiedClaimCells")?.number()?
            != json_member(statuses, "unverified")?.number()?
    {
        return Err("residual-risk status counters do not match their exact partition".to_owned());
    }
    Ok(())
}

fn verify_residual_obligation_records(records: &[JsonValue]) -> Result<(), String> {
    for record in records {
        let record = record.object()?;
        exact_keys(
            record,
            &[
                "builtin",
                "dimension",
                "missing",
                "observed",
                "platform",
                "profile",
                "required",
            ],
        )?;
        let required = json_member(record, "required")?.number()?;
        let observed = json_member(record, "observed")?.number()?;
        let missing = json_member(record, "missing")?.number()?;
        if observed.saturating_add(missing) != required
            || hell_builtins::lookup(json_member(record, "builtin")?.string()?).is_none()
            || compatibility_dimension(json_member(record, "dimension")?.string()?).is_err()
            || json_member(record, "profile")?.string()? != "upstream"
            || !REQUIRED_CLAIM_PLATFORMS.contains(&json_member(record, "platform")?.string()?)
        {
            return Err("residual-risk obligation coverage is invalid".to_owned());
        }
    }
    Ok(())
}

fn verify_sorted_unique_string_array(values: &[JsonValue], label: &str) -> Result<(), String> {
    let values = values
        .iter()
        .map(JsonValue::string)
        .collect::<Result<Vec<_>, _>>()?;
    if values.windows(2).any(|pair| pair[0] >= pair[1]) {
        return Err(format!("{label} is not sorted and unique"));
    }
    Ok(())
}

fn declared_human_reviewer_subject_count(
    details: &BTreeMap<String, JsonValue>,
) -> Result<u64, String> {
    let subjects = json_member(details, "actions")?
        .array()?
        .iter()
        .map(JsonValue::object)
        .map(|action| {
            let action = action?;
            Ok((
                json_member(action, "role")?.string()?,
                json_member(action, "stableAccountId")?.string()?,
            ))
        })
        .collect::<Result<Vec<_>, String>>()?
        .into_iter()
        .filter(|(role, _)| human_review_role(role))
        .map(|(_, stable_account_id)| stable_account_id)
        .collect::<BTreeSet<_>>();
    u64::try_from(subjects.len()).map_err(|_| "review identity count exceeds u64".to_owned())
}

fn verify_review_epoch(expected: &str, observed: &str) -> Result<(), String> {
    require_digest(expected, "expected review epoch")?;
    require_digest(observed, "observed review epoch")?;
    if expected == observed || crate::assurance_control_mutant_active("old-epoch-review-reuse") {
        Ok(())
    } else {
        Err("review from an old assurance epoch was reused".to_owned())
    }
}

fn verify_zero_coverage_gaps(details: &BTreeMap<String, JsonValue>) -> Result<(), String> {
    for field in [
        "missingObligations",
        "requiredPlatformGaps",
        "semanticCoverageGaps",
        "unreachedTargets",
    ] {
        if crate::assurance_control_mutant_active("required-platform-cell-omission")
            && field == "requiredPlatformGaps"
        {
            continue;
        }
        if json_member(details, field)?.number()? != 0 {
            return Err(format!("claim coverage retains nonzero {field}"));
        }
    }
    Ok(())
}

pub(crate) struct FinalizedClaimEvidenceRef {
    pub(crate) canonical_json: String,
    pub(crate) sha256: String,
    pub(crate) bundle_path: String,
    pub(crate) bundle_sha256: String,
    pub(crate) case_id: String,
    pub(crate) obligations: Vec<String>,
}

pub(crate) struct FinalizedClaimCell {
    pub(crate) builtin: String,
    pub(crate) dimension: String,
    pub(crate) profile: String,
    pub(crate) platform: String,
    pub(crate) applicability: String,
    pub(crate) applicability_decision_sha256: Option<String>,
    pub(crate) proposed_status: String,
    pub(crate) canonical_json: String,
    pub(crate) evidence_refs: Vec<FinalizedClaimEvidenceRef>,
    pub(crate) normalizer_ids: Vec<String>,
    pub(crate) normalizer_application_refs: Vec<String>,
    pub(crate) obligations: Vec<String>,
    pub(crate) divergence_record_ref: Option<String>,
}

pub(crate) fn finalized_claim_cells(path: &Path) -> Result<Vec<FinalizedClaimCell>, String> {
    let document = parse_json(&read_text(path)?)?;
    let details = document.object()?;
    let candidate = json_member(details, "candidateSourceCommit")?.string()?;
    let epoch = json_member(details, "assuranceEpochSha256")?.string()?;
    verify_bound_details(path, "claim-coverage", candidate, epoch)?;
    json_member(details, "cells")?
        .array()?
        .iter()
        .map(finalized_claim_cell)
        .collect()
}

pub(crate) fn verify_offline_packet_sources(
    input: &Path,
    signer_policy: &Path,
) -> Result<(), String> {
    let root = repository_root()?;
    let evidence = input.join("evidence");
    let coverage_details = evidence
        .join("coverage")
        .join("claim-coverage.finalized.json");
    finalized_claim_cells(&coverage_details)?;
    let coverage = parse_json(&read_text(&coverage_details)?)?;
    let candidate = json_member(coverage.object()?, "candidateSourceCommit")?.string()?;
    let epoch = json_member(coverage.object()?, "assuranceEpochSha256")?.string()?;
    require_git_sha_text(candidate, "offline packet candidate")?;
    require_digest(epoch, "offline packet epoch")?;

    retained_report_command(
        &root,
        &Options {
            input: Some(evidence.join("coverage").join("mutation-score.json")),
            policy: Some(signer_policy.to_path_buf()),
            expect_source: Some(candidate.to_owned()),
            expect_epoch: Some(epoch.to_owned()),
            ..Options::default()
        },
        "mutation",
    )?;
    for path in [
        evidence
            .join("provenance")
            .join("macos-arm64")
            .join("oracle-provenance.json"),
        evidence
            .join("provenance")
            .join("windows-amd64")
            .join("oracle-provenance.json"),
    ] {
        oracle_provenance(
            &root,
            &Options {
                action: Some("verify".to_owned()),
                input: Some(path),
                policy: Some(signer_policy.to_path_buf()),
                ..Options::default()
            },
        )?;
    }
    custody_command(&Options {
        action: Some("verify".to_owned()),
        input: Some(evidence.join("custody").join("custody-receipt.json")),
        policy: Some(signer_policy.to_path_buf()),
        ..Options::default()
    })?;
    for (path, kind, role) in [
        (
            evidence.join("coverage").join("claim-coverage.json"),
            "claim-coverage",
            "claim-reviewer",
        ),
        (
            evidence.join("coverage").join("normalizer-audit.json"),
            "normalizer-audit",
            "normalizer-reviewer",
        ),
        (
            evidence.join("review").join("divergence-report.json"),
            "divergence",
            "divergence-reviewer",
        ),
        (
            evidence.join("coverage").join("residual-risk.json"),
            "residual-risk",
            "residual-risk-reviewer",
        ),
    ] {
        verify_bound_report(
            &path,
            signer_policy,
            kind,
            role,
            candidate,
            epoch,
            &evidence,
        )?;
    }
    verify_divergence_tier_approvals(
        &evidence.join("review").join("divergence-report.json"),
        &evidence,
        signer_policy,
        candidate,
        epoch,
    )?;
    verify_claim_status_consistency(
        &evidence.join("coverage").join("claim-coverage.json"),
        &evidence.join("coverage").join("normalizer-audit.json"),
        &evidence.join("review").join("divergence-report.json"),
        &evidence,
    )
}

fn finalized_claim_cell(value: &JsonValue) -> Result<FinalizedClaimCell, String> {
    let cell = value.object()?;
    let applicability_decision_sha256 = match json_member(cell, "applicabilityDecisionSha256")? {
        JsonValue::Null => None,
        value => Some(value.string()?.to_owned()),
    };
    let divergence_record_ref = match json_member(cell, "divergenceRecordRef")? {
        JsonValue::Null => None,
        value => Some(value.string()?.to_owned()),
    };
    Ok(FinalizedClaimCell {
        builtin: json_member(cell, "builtin")?.string()?.to_owned(),
        dimension: json_member(cell, "dimension")?.string()?.to_owned(),
        profile: json_member(cell, "profile")?.string()?.to_owned(),
        platform: json_member(cell, "platform")?.string()?.to_owned(),
        applicability: json_member(cell, "applicability")?.string()?.to_owned(),
        applicability_decision_sha256,
        proposed_status: json_member(cell, "proposedStatus")?.string()?.to_owned(),
        canonical_json: canonical_json_string(value)?,
        evidence_refs: json_member(cell, "evidenceRefs")?
            .array()?
            .iter()
            .map(finalized_claim_evidence_ref)
            .collect::<Result<Vec<_>, _>>()?,
        normalizer_ids: finalized_claim_string_array(cell, "normalizerIds")?,
        normalizer_application_refs: finalized_claim_string_array(
            cell,
            "normalizerApplicationRefs",
        )?,
        obligations: finalized_claim_string_array(cell, "obligations")?,
        divergence_record_ref,
    })
}

fn finalized_claim_evidence_ref(value: &JsonValue) -> Result<FinalizedClaimEvidenceRef, String> {
    let reference = value.object()?;
    Ok(FinalizedClaimEvidenceRef {
        canonical_json: canonical_json_string(value)?,
        sha256: canonical_json_digest(value)?,
        bundle_path: json_member(reference, "bundlePath")?.string()?.to_owned(),
        bundle_sha256: json_member(reference, "bundleSha256")?.string()?.to_owned(),
        case_id: json_member(reference, "caseId")?.string()?.to_owned(),
        obligations: finalized_claim_string_array(reference, "obligations")?,
    })
}

fn finalized_claim_string_array(
    object: &BTreeMap<String, JsonValue>,
    field: &str,
) -> Result<Vec<String>, String> {
    json_member(object, field)?
        .array()?
        .iter()
        .map(|value| value.string().map(str::to_owned))
        .collect()
}

fn canonical_json_string(value: &JsonValue) -> Result<String, String> {
    String::from_utf8(canonical_json_bytes(value)?)
        .map_err(|_| "canonical JSON is not UTF-8".to_owned())
}

fn validate_claim_status_shape(
    status: &str,
    normalizer_ids: &[JsonValue],
    normalizer_refs: &[JsonValue],
    divergence_ref: &JsonValue,
) -> Result<(), String> {
    let ids = normalizer_ids
        .iter()
        .map(JsonValue::string)
        .collect::<Result<Vec<_>, _>>()?;
    let refs = normalizer_refs
        .iter()
        .map(JsonValue::string)
        .collect::<Result<Vec<_>, _>>()?;
    if ids.iter().collect::<BTreeSet<_>>().len() != ids.len()
        || refs.iter().collect::<BTreeSet<_>>().len() != refs.len()
    {
        return Err("claim status repeats a normalizer ID or application reference".to_owned());
    }
    for id in &ids {
        if !hell_builtins::NormalizerId::ALL
            .iter()
            .any(|normalizer| normalizer.as_str() == *id)
        {
            return Err("claim cell names an unknown normalizer".to_owned());
        }
    }
    for reference in &refs {
        require_digest(reference, "normalizer application")?;
    }
    match status {
        "exact"
            if ids.is_empty() && refs.is_empty() && matches!(divergence_ref, JsonValue::Null) =>
        {
            Ok(())
        }
        "normalized" | "platform-dependent"
            if !ids.is_empty() && !refs.is_empty() && matches!(divergence_ref, JsonValue::Null) =>
        {
            Ok(())
        }
        "deliberate-divergence" if ids.is_empty() && refs.is_empty() => {
            require_digest(divergence_ref.string()?, "claim divergence record")
        }
        _ => Err("claim status is not bound to status-specific evidence".to_owned()),
    }
}

struct PlatformStatusFact {
    declared: String,
    normalized_fingerprints: BTreeSet<String>,
    has_exact: bool,
}

fn verify_platform_dependent_cells(cells: &[JsonValue], details_path: &Path) -> Result<(), String> {
    let repository = repository_root()?;
    let retained_root = retained_evidence_root(details_path)?;
    let cases = committed_differential_cases();
    let mut groups =
        BTreeMap::<(String, String, String), BTreeMap<String, PlatformStatusFact>>::new();
    for cell in cells {
        let cell = cell.object()?;
        let declared = json_member(cell, "proposedStatus")?.string()?;
        if !matches!(declared, "exact" | "normalized" | "platform-dependent") {
            continue;
        }
        let mut fact = PlatformStatusFact {
            declared: declared.to_owned(),
            normalized_fingerprints: BTreeSet::new(),
            has_exact: false,
        };
        for reference in json_member(cell, "evidenceRefs")?.array()? {
            let reference = reference.object()?;
            let case_id = json_member(reference, "caseId")?.string()?;
            let case = cases
                .iter()
                .find(|case| case.id.as_ref() == case_id)
                .ok_or_else(|| "platform claim evidence names an unknown case".to_owned())?;
            let bundle = confined_record_path(
                &repository,
                retained_root,
                Path::new(json_member(reference, "bundlePath")?.string()?),
            )?;
            match hell_testkit::classify_retained_observation_bundle(&bundle, case)
                .map_err(|error| format!("cannot classify platform claim bundle: {error}"))?
            {
                hell_testkit::RetainedObservationClassification::Exact => fact.has_exact = true,
                hell_testkit::RetainedObservationClassification::Normalized {
                    fingerprint_sha256,
                    ..
                } => {
                    fact.normalized_fingerprints
                        .insert(fingerprint_sha256.hex());
                }
                hell_testkit::RetainedObservationClassification::Mismatch { .. } => {
                    return Err(
                        "exact/normalized platform claim retains an unapproved mismatch".to_owned(),
                    );
                }
            }
        }
        let key = (
            json_member(cell, "builtin")?.string()?.to_owned(),
            json_member(cell, "dimension")?.string()?.to_owned(),
            json_member(cell, "profile")?.string()?.to_owned(),
        );
        let platform = json_member(cell, "platform")?.string()?.to_owned();
        if groups
            .entry(key)
            .or_default()
            .insert(platform, fact)
            .is_some()
        {
            return Err("claim coverage repeats a platform status cell".to_owned());
        }
    }
    for platforms in groups.values() {
        let fingerprint_sets = platforms
            .values()
            .map(|fact| fact.normalized_fingerprints.clone())
            .collect::<BTreeSet<_>>();
        let platform_dependent = platforms.len() == REQUIRED_CLAIM_PLATFORMS.len()
            && fingerprint_sets.len() > 1
            && platforms
                .values()
                .all(|fact| !fact.has_exact && !fact.normalized_fingerprints.is_empty());
        for fact in platforms.values() {
            let expected = if platform_dependent {
                "platform-dependent"
            } else if fact.normalized_fingerprints.is_empty() {
                "exact"
            } else {
                "normalized"
            };
            if fact.declared != expected {
                return Err(
                    "claim platform status is not derived from exact bundle facts".to_owned(),
                );
            }
        }
    }
    Ok(())
}

fn canonical_json_digest(value: &JsonValue) -> Result<String, String> {
    let mut canonical = String::new();
    push_json_value(&mut canonical, value)?;
    canonical.push('\n');
    Ok(sha256_bytes(canonical.as_bytes()).hex())
}

fn divergence_fingerprint(record: &BTreeMap<String, JsonValue>) -> Result<String, String> {
    let mut subject = String::new();
    for field in [
        "builtin",
        "dimension",
        "profile",
        "platform",
        "evidenceRef",
        "rawObservationSha256",
        "normalizedObservationSha256",
    ] {
        subject.push_str(json_member(record, field)?.string()?);
        subject.push('\n');
    }
    Ok(sha256_bytes(subject.as_bytes()).hex())
}

fn bound_details_document(record: &Path, retained_root: &Path) -> Result<JsonValue, String> {
    let wrapper = parse_json(&read_text(record)?)?;
    let wrapper = wrapper.object()?;
    let repository = repository_root()?;
    let path = confined_record_path(
        &repository,
        retained_root,
        Path::new(json_member(wrapper, "detailsPath")?.string()?),
    )?;
    let bytes = read_regular_file(&path)?;
    if sha256_bytes(&bytes).hex() != json_member(wrapper, "detailsSha256")?.string()? {
        return Err("bound details digest changed during status consistency check".to_owned());
    }
    parse_json(std::str::from_utf8(&bytes).map_err(|_| "bound details are not UTF-8".to_owned())?)
}

fn verify_residual_gate_source_records(
    pointers: &BTreeMap<&str, PathBuf>,
    retained_root: &Path,
) -> Result<(), String> {
    let residual_path = pointers
        .get("residualRisk")
        .ok_or_else(|| "missing residual-risk proposal record".to_owned())?;
    let residual = bound_details_document(residual_path, retained_root)?;
    let residual = residual.object()?;
    let claim_path = pointers
        .get("claimCoverage")
        .ok_or_else(|| "missing claim-coverage proposal record".to_owned())?;
    let claim_wrapper = parse_json(&read_text(claim_path)?)?;
    let mutation_path = pointers
        .get("mutation")
        .ok_or_else(|| "missing mutation proposal record".to_owned())?;
    if json_member(residual, "claimCoverageSha256")?.string()?
        != json_member(claim_wrapper.object()?, "detailsSha256")?.string()?
        || json_member(residual, "mutationReportSha256")?.string()? != record_digest(mutation_path)?
    {
        return Err(
            "residual-risk sources differ from the proposal's reviewed source records".to_owned(),
        );
    }
    Ok(())
}

fn verify_claim_status_consistency(
    claim_record: &Path,
    normalizer_record: &Path,
    divergence_record: &Path,
    retained_root: &Path,
) -> Result<(), String> {
    let claims = bound_details_document(claim_record, retained_root)?;
    let normalizers = bound_details_document(normalizer_record, retained_root)?;
    let divergences = bound_details_document(divergence_record, retained_root)?;
    let normalizer_by_digest = indexed_normalizer_application_records(
        json_member(normalizers.object()?, "applicationRecords")?.array()?,
    )?;
    let divergence_by_digest = indexed_detail_records(
        json_member(divergences.object()?, "records")?.array()?,
        "divergence report",
    )?;
    let mut used_normalizers = BTreeSet::new();
    let mut used_divergences = BTreeSet::new();
    let cells = json_member(claims.object()?, "cells")?.array()?;
    for cell in cells {
        let cell = cell.object()?;
        verify_cell_normalizers(cell, &normalizer_by_digest, &mut used_normalizers)?;
        verify_cell_divergence(cell, &divergence_by_digest, &mut used_divergences)?;
    }
    let claim_normalizers = normalizer_by_digest
        .values()
        .filter(|record| {
            json_member(record, "applicationScope").and_then(JsonValue::string)
                != Ok("harness-stderr")
        })
        .count();
    let harness_bound = normalizer_by_digest.values().all(|application| {
        json_member(application, "applicationScope").and_then(JsonValue::string)
            != Ok("harness-stderr")
            || cells.iter().any(|cell| {
                cell.object().is_ok_and(|cell| {
                    ["builtin", "dimension", "profile", "platform"]
                        .into_iter()
                        .all(|field| {
                            json_member(application, field).and_then(JsonValue::string)
                                == json_member(cell, field).and_then(JsonValue::string)
                        })
                        && evidence_contains(
                            cell,
                            json_member(application, "evidenceRef")
                                .and_then(JsonValue::string)
                                .unwrap_or(""),
                        ) == Ok(true)
                })
            })
    });
    if used_normalizers.len() != claim_normalizers
        || !harness_bound
        || used_divergences.len() != divergence_by_digest.len()
    {
        return Err("status reports contain unreferenced or multiply claimed records".to_owned());
    }
    Ok(())
}

#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
struct ReviewGraphAction {
    action_kind: String,
    stable_account_id: String,
    subject: String,
    signer_fingerprint: String,
    role: String,
    review_sha256: String,
    environment: String,
    team: String,
    provider_run_id: u64,
    provider_run_attempt: u64,
}

struct ActualReviewGraph {
    actions: BTreeSet<ReviewGraphAction>,
    roles: BTreeSet<String>,
    identities: BTreeMap<String, (String, String)>,
    minimum_distinct_people: u64,
}

struct VerifiedReviewGraph {
    actions: BTreeSet<ReviewGraphAction>,
    distinct_identities: BTreeSet<(String, String)>,
}

fn review_graph_command(root: &Path, options: &Options) -> Result<String, String> {
    let input = required_path(
        &options.input,
        "review-graph requires --input proposal package",
    )?;
    let policy = required_path(&options.policy, "review-graph requires --policy")?;
    let records = promotion_record_paths(input);
    let candidate = git_output(root, &["rev-parse", "HEAD"])?;
    let (_, epoch) = epoch(root)?;
    if options.action.as_deref() == Some("verify") {
        let identities = verify_actual_review_graph(
            &records,
            &input.join("evidence"),
            policy,
            candidate.trim(),
            &epoch.hex(),
        )?;
        return Ok(format!(
            "verified canonical review graph with {} distinct identities",
            identities.distinct_identities.len()
        ));
    }
    if options.action.is_some() {
        return Err("review-graph action must be verify when supplied".to_owned());
    }
    let output = required_path(&options.output, "review-graph requires --output details")?;
    let graph = collect_actual_review_actions(
        &records,
        &input.join("evidence"),
        policy,
        candidate.trim(),
        &epoch.hex(),
    )?;
    require_complete_review_roles(
        &graph.actions,
        &graph.roles,
        &graph.identities,
        graph.minimum_distinct_people,
    )?;
    let document =
        render_review_graph(candidate.trim(), &epoch.hex(), &graph.actions, &graph.roles);
    write_atomic(output, document.as_bytes())?;
    Ok(format!(
        "wrote canonical {}-action review graph",
        graph.actions.len()
    ))
}

fn collect_actual_review_actions(
    records: &BTreeMap<&str, PathBuf>,
    retained_root: &Path,
    policy: &Path,
    candidate: &str,
    epoch: &str,
) -> Result<ActualReviewGraph, String> {
    let mut actions = BTreeSet::new();
    let mut identities = BTreeMap::<String, (String, String)>::new();
    let mut roles = BTreeSet::new();
    let repository = repository_root()?;
    let review_policy = load_review_policy(&repository)?;
    for path in proposal_review_paths(records, retained_root)? {
        let signer_policy = review_policy_for_envelope(&path, policy)?;
        let review = verify_review_envelope(&path, &signer_policy)?;
        if review.candidate_commit != candidate || review.assurance_epoch != epoch {
            return Err("actual review graph contains a foreign candidate or epoch".to_owned());
        }
        if review.role == "custody-provider" {
            continue;
        }
        let digest = record_digest(&path)?;
        let action = review_graph_action(&path, &review, &digest)?;
        if action.provider_run_id != 0 {
            if let Some((prior_role, prior_key)) = identities.get(&action.stable_account_id) {
                verify_reviewer_identity_compatibility(
                    prior_role,
                    prior_key,
                    &review.role,
                    &review.signer_fingerprint,
                )?;
            }
            identities.insert(
                action.stable_account_id.clone(),
                (review.role.clone(), review.signer_fingerprint.clone()),
            );
        }
        roles.insert(review.role.clone());
        if !actions.insert(action) {
            return Err("actual review graph duplicates an action".to_owned());
        }
    }
    append_acquisition_and_custody_actions(
        records,
        policy,
        candidate,
        epoch,
        review_policy
            .require_external_or_separate_team_for_artifact_authenticity
            .required(),
        &mut actions,
        &mut roles,
    )?;
    append_authorship_actions(records, candidate, &mut actions, &mut roles)?;
    let evidence_run_trigger = evidence_run_trigger_action(records, candidate)?;
    if review_policy
        .claim_reviewer_may_not_be_evidence_run_actor
        .required()
    {
        for action in &actions {
            if action.role != "claim-reviewer" {
                continue;
            }
            verify_cross_action_independence(
                &evidence_run_trigger,
                action,
                "claim reviewer may not be the evidence run actor",
            )?;
        }
    }
    if !actions.insert(evidence_run_trigger) {
        return Err("actual review graph duplicates the evidence-run trigger action".to_owned());
    }
    roles.insert("evidence-run-trigger".to_owned());
    let claim_proposer = claim_proposer_action(retained_root, candidate, epoch)?;
    if !actions.insert(claim_proposer) {
        return Err("actual review graph duplicates the claim proposer action".to_owned());
    }
    roles.insert("claim-proposer".to_owned());
    for trigger in oracle_trigger_actions(records, retained_root, candidate, epoch)? {
        if review_policy
            .platform_reviewer_may_not_be_oracle_build_trigger
            .required()
        {
            for action in &actions {
                if action.role != "platform-reviewer" {
                    continue;
                }
                verify_cross_action_independence(
                    &trigger,
                    action,
                    "platform reviewer may not be an oracle build trigger",
                )?;
            }
        }
        if !actions.insert(trigger) {
            return Err("actual review graph duplicates an oracle trigger action".to_owned());
        }
        roles.insert("oracle-trigger".to_owned());
    }
    Ok(ActualReviewGraph {
        actions,
        roles,
        identities,
        minimum_distinct_people: review_policy.minimum_distinct_people,
    })
}

fn append_authorship_actions(
    records: &BTreeMap<&str, PathBuf>,
    candidate: &str,
    actions: &mut BTreeSet<ReviewGraphAction>,
    roles: &mut BTreeSet<String>,
) -> Result<(), String> {
    let mut authored = candidate_author_actions(records, candidate)?.to_vec();
    authored.extend(normalizer_author_action(records, candidate)?);
    authored.extend(claim_author_action(records, candidate)?);
    for action in authored {
        roles.insert(action.role.clone());
        if !actions.insert(action) {
            return Err("actual review graph duplicates an authorship action".to_owned());
        }
    }
    Ok(())
}

fn candidate_author_actions(
    records: &BTreeMap<&str, PathBuf>,
    candidate: &str,
) -> Result<[ReviewGraphAction; 2], String> {
    let directory = records
        .get("artifactAuthenticity")
        .ok_or_else(|| "proposal lacks artifact authenticity evidence".to_owned())?;
    let receipt = parse_acquisition_receipt(&directory.join("receipt-primary.json"))?;
    let commit_path = directory.join("provider-commit-primary.json");
    let commit = parse_json(&read_text(&commit_path)?)?;
    let commit = commit.object()?;
    verify_provider_commit_identity(commit, candidate)?;
    let digest = record_digest(&commit_path)?;
    let action = |provider_role: &str, graph_role: &str| -> Result<ReviewGraphAction, String> {
        let identity = json_member(commit, provider_role)?.object()?;
        let account_id = json_member(identity, "id")?.number()?;
        let login = json_member(identity, "login")?.string()?;
        Ok(ReviewGraphAction {
            action_kind: "authored-candidate-commit".to_owned(),
            stable_account_id: account_id.to_string(),
            subject: login.to_owned(),
            signer_fingerprint: sha256_bytes(format!("provider-account:{account_id}").as_bytes())
                .hex(),
            role: graph_role.to_owned(),
            review_sha256: digest.clone(),
            environment: "github-commit-api".to_owned(),
            team: "Portfoligno/hell-rs".to_owned(),
            provider_run_id: receipt.run_id,
            provider_run_attempt: receipt.run_attempt,
        })
    };
    Ok([
        action("author", "candidate-author")?,
        action("committer", "candidate-committer")?,
    ])
}

fn normalizer_author_action(
    records: &BTreeMap<&str, PathBuf>,
    candidate: &str,
) -> Result<Option<ReviewGraphAction>, String> {
    let directory = records
        .get("artifactAuthenticity")
        .ok_or_else(|| "proposal lacks artifact authenticity evidence".to_owned())?;
    let receipt = parse_acquisition_receipt(&directory.join("receipt-primary.json"))?;
    let commit_path = directory.join("provider-commit-primary.json");
    let commit_document = parse_json(&read_text(&commit_path)?)?;
    let commit = commit_document.object()?;
    verify_provider_commit_identity(commit, candidate)?;
    let repository = repository_root()?;
    let Some(binding) = normalizer_authoring_binding(&repository, &commit_path, commit, candidate)?
    else {
        return Ok(None);
    };
    let identity = json_member(commit, "author")?.object()?;
    let account_id = json_member(identity, "id")?.number()?;
    let login = json_member(identity, "login")?.string()?;
    Ok(Some(ReviewGraphAction {
        action_kind: "authored-normalizer".to_owned(),
        stable_account_id: account_id.to_string(),
        subject: login.to_owned(),
        signer_fingerprint: sha256_bytes(format!("provider-account:{account_id}").as_bytes()).hex(),
        role: "normalizer-author".to_owned(),
        review_sha256: binding,
        environment: "github-commit-api".to_owned(),
        team: "Portfoligno/hell-rs".to_owned(),
        provider_run_id: receipt.run_id,
        provider_run_attempt: receipt.run_attempt,
    }))
}

fn normalizer_authoring_binding(
    repository: &Path,
    commit_path: &Path,
    commit: &BTreeMap<String, JsonValue>,
    candidate: &str,
) -> Result<Option<String>, String> {
    let paths = [
        PathBuf::from("compat").join("normalizers.toml"),
        PathBuf::from("crates")
            .join("hell-testkit")
            .join("src")
            .join("lib.rs"),
    ];
    let changed_paths = changed_governed_paths(repository, candidate, &paths)?;
    if changed_paths.is_empty() {
        return Ok(None);
    }
    let files = authored_governed_files(repository, commit, &changed_paths)?;
    let contracts = hell_builtins::assurance_catalogs::NORMALIZER_CONTRACTS;
    if contracts.is_empty() {
        return Err("normalizer authoring binding has no generated contracts".to_owned());
    }
    let implementation_digests = contracts
        .iter()
        .map(|contract| JsonValue::String(contract.implementation_sha256.to_owned()))
        .collect();
    let document = JsonValue::Object(BTreeMap::from([
        ("schemaVersion".to_owned(), JsonValue::Number(1)),
        (
            "providerCommitSha256".to_owned(),
            JsonValue::String(record_digest(commit_path)?),
        ),
        ("governedFiles".to_owned(), JsonValue::Array(files)),
        (
            "normalizerImplementationSha256".to_owned(),
            JsonValue::Array(implementation_digests),
        ),
    ]));
    Ok(Some(sha256_bytes(&canonical_json_bytes(&document)?).hex()))
}

fn authored_governed_files(
    repository: &Path,
    commit: &BTreeMap<String, JsonValue>,
    paths: &[PathBuf],
) -> Result<Vec<JsonValue>, String> {
    let mut files = Vec::new();
    for relative in paths {
        let relative_text = path_text(relative)?;
        let provider_blob = verify_authored_provider_file(repository, commit, relative)?;
        files.push(JsonValue::Object(BTreeMap::from([
            ("path".to_owned(), JsonValue::String(relative_text)),
            (
                "providerBlobSha".to_owned(),
                JsonValue::String(provider_blob),
            ),
            (
                "sha256".to_owned(),
                JsonValue::String(record_digest(&repository.join(relative))?),
            ),
        ])));
    }
    Ok(files)
}

fn changed_governed_paths(
    repository: &Path,
    candidate: &str,
    governed: &[PathBuf],
) -> Result<Vec<PathBuf>, String> {
    require_git_sha_text(candidate, "authorship candidate")?;
    let changed = git_output(
        repository,
        &[
            "diff-tree",
            "--root",
            "-m",
            "--no-commit-id",
            "--name-only",
            "-z",
            "-r",
            candidate,
            "--",
        ],
    )?;
    let changed = changed.split('\0').collect::<BTreeSet<_>>();
    let mut selected = Vec::new();
    for path in governed {
        if changed.contains(path_text(path)?.as_str()) {
            selected.push(path.clone());
        }
    }
    Ok(selected)
}

fn verify_authored_provider_file(
    repository: &Path,
    commit: &BTreeMap<String, JsonValue>,
    expected_relative: &Path,
) -> Result<String, String> {
    let expected = path_text(expected_relative)?;
    let blob = provider_authored_file_blob(commit, &expected)?;
    let local = git_output(repository, &["hash-object", "--", &expected])?;
    if local.trim() != blob {
        return Err(format!(
            "authored source file {expected} differs from its retained provider blob"
        ));
    }
    Ok(blob)
}

fn claim_author_action(
    records: &BTreeMap<&str, PathBuf>,
    candidate: &str,
) -> Result<Option<ReviewGraphAction>, String> {
    let directory = records
        .get("artifactAuthenticity")
        .ok_or_else(|| "proposal lacks artifact authenticity evidence".to_owned())?;
    let receipt = parse_acquisition_receipt(&directory.join("receipt-primary.json"))?;
    let commit_path = directory.join("provider-commit-primary.json");
    let commit_document = parse_json(&read_text(&commit_path)?)?;
    let commit = commit_document.object()?;
    verify_provider_commit_identity(commit, candidate)?;
    let Some(binding) =
        claim_authoring_binding(&repository_root()?, &commit_path, commit, candidate)?
    else {
        return Ok(None);
    };
    let identity = json_member(commit, "author")?.object()?;
    let account_id = json_member(identity, "id")?.number()?;
    let login = json_member(identity, "login")?.string()?;
    Ok(Some(ReviewGraphAction {
        action_kind: "authored-claim-change".to_owned(),
        stable_account_id: account_id.to_string(),
        subject: login.to_owned(),
        signer_fingerprint: sha256_bytes(format!("provider-account:{account_id}").as_bytes()).hex(),
        role: "claim-author".to_owned(),
        review_sha256: binding,
        environment: "github-commit-api".to_owned(),
        team: "Portfoligno/hell-rs".to_owned(),
        provider_run_id: receipt.run_id,
        provider_run_attempt: receipt.run_attempt,
    }))
}

fn claim_authoring_binding(
    repository: &Path,
    commit_path: &Path,
    commit: &BTreeMap<String, JsonValue>,
    candidate: &str,
) -> Result<Option<String>, String> {
    let paths = [
        PathBuf::from("compat")
            .join("claims")
            .join("2026-05-29.toml"),
        PathBuf::from("compat").join("claim-rules.toml"),
        PathBuf::from("compat").join("corpus-obligations.toml"),
        PathBuf::from("compat").join("collection-activation.toml"),
        PathBuf::from("compat").join("collection-activation-claims.json"),
        PathBuf::from("compat").join("collection-activation-provenance.json"),
        PathBuf::from("compat").join("collection-activation-review-subject"),
        PathBuf::from("compat").join("collection-activation-reviews"),
        PathBuf::from("crates")
            .join("hell-testkit")
            .join("src")
            .join("corpus.rs"),
    ];
    let changed_paths = changed_governed_paths(repository, candidate, &paths)?;
    if changed_paths.is_empty() {
        return Ok(None);
    }
    let files = authored_governed_files(repository, commit, &changed_paths)?;
    let document = JsonValue::Object(BTreeMap::from([
        ("schemaVersion".to_owned(), JsonValue::Number(1)),
        (
            "providerCommitSha256".to_owned(),
            JsonValue::String(record_digest(commit_path)?),
        ),
        ("claimFiles".to_owned(), JsonValue::Array(files)),
    ]));
    Ok(Some(sha256_bytes(&canonical_json_bytes(&document)?).hex()))
}

fn provider_authored_file_blob(
    commit: &BTreeMap<String, JsonValue>,
    expected: &str,
) -> Result<String, String> {
    let mut matching = json_member(commit, "files")?
        .array()?
        .iter()
        .filter_map(|file| {
            let file = file.object().ok()?;
            (json_member(file, "filename").and_then(JsonValue::string) == Ok(expected))
                .then_some(file)
        });
    let file = matching
        .next()
        .ok_or_else(|| format!("provider commit did not author required source file {expected}"))?;
    if matching.next().is_some() {
        return Err(format!(
            "provider commit duplicates required source file {expected}"
        ));
    }
    if !matches!(
        json_member(file, "status")?.string()?,
        "added" | "modified" | "renamed"
    ) {
        return Err(format!(
            "provider commit does not mark source file {expected} as authored"
        ));
    }
    let blob = json_member(file, "sha")?.string()?;
    require_git_sha_text(blob, "authored source provider blob")?;
    Ok(blob.to_owned())
}

fn append_acquisition_and_custody_actions(
    records: &BTreeMap<&str, PathBuf>,
    policy: &Path,
    candidate: &str,
    epoch: &str,
    require_external_acquisition: bool,
    actions: &mut BTreeSet<ReviewGraphAction>,
    roles: &mut BTreeSet<String>,
) -> Result<(), String> {
    let acquisitions = acquired_artifact_actions(records, policy, candidate)?;
    verify_artifact_acquisition_policy(&acquisitions, require_external_acquisition)?;
    for acquisition in acquisitions {
        for reviewer in actions
            .iter()
            .filter(|action| action.role == "artifact-trust-reviewer")
        {
            verify_cross_action_independence(
                &acquisition,
                reviewer,
                "artifact trust reviewer may not be an acquisition actor",
            )?;
        }
        roles.insert(acquisition.role.clone());
        if !actions.insert(acquisition) {
            return Err("actual review graph duplicates an acquisition action".to_owned());
        }
    }
    for custody in custody_provider_actions(records, policy, candidate, epoch)? {
        for reviewer in actions
            .iter()
            .filter(|action| action.role == "custody-reviewer")
        {
            verify_cross_action_independence(
                &custody,
                reviewer,
                "custody reviewer may not upload or retrieve the reviewed custody copy",
            )?;
        }
        roles.insert(custody.role.clone());
        if !actions.insert(custody) {
            return Err("actual review graph duplicates a custody provider action".to_owned());
        }
    }
    Ok(())
}

fn custody_provider_actions(
    records: &BTreeMap<&str, PathBuf>,
    policy: &Path,
    candidate: &str,
    epoch: &str,
) -> Result<Vec<ReviewGraphAction>, String> {
    let receipt_path = records
        .get("custody")
        .ok_or_else(|| "proposal lacks custody evidence".to_owned())?;
    custody_command(&Options {
        input: Some(receipt_path.clone()),
        policy: Some(policy.to_path_buf()),
        ..Options::default()
    })?;
    let document = parse_json(&read_text(receipt_path)?)?;
    let receipt = document.object()?;
    if json_member(receipt, "candidateCommit")?.string()? != candidate
        || json_member(receipt, "assuranceEpochSha256")?.string()? != epoch
    {
        return Err("custody graph source is stale".to_owned());
    }
    let repository = repository_root()?;
    let retained_root = retained_evidence_root(receipt_path)?;
    let mut actions = Vec::new();
    for copy in json_member(receipt, "copies")?.array()? {
        let copy = copy.object()?;
        actions.push(custody_provider_action(
            &repository,
            retained_root,
            policy,
            copy,
            true,
        )?);
        actions.push(custody_provider_action(
            &repository,
            retained_root,
            policy,
            copy,
            false,
        )?);
    }
    let stable_ids = actions
        .iter()
        .map(|action| &action.stable_account_id)
        .collect::<BTreeSet<_>>();
    if stable_ids.len() != actions.len() {
        return Err("custody upload/retrieval actions reuse a stable provider identity".to_owned());
    }
    Ok(actions)
}

fn custody_provider_action(
    repository: &Path,
    retained_root: &Path,
    policy: &Path,
    copy: &BTreeMap<String, JsonValue>,
    upload: bool,
) -> Result<ReviewGraphAction, String> {
    let (path_field, stable_field, subject_field, action_kind) = if upload {
        (
            "uploadProviderReceiptPath",
            "uploaderStableId",
            "uploadedBy",
            "uploaded-custody-copy",
        )
    } else {
        (
            "providerReceiptPath",
            "retrieverStableId",
            "retrievedBy",
            "retrieved-custody-copy",
        )
    };
    let path = confined_record_path(
        repository,
        retained_root,
        Path::new(json_member(copy, path_field)?.string()?),
    )?;
    let review = verify_review_envelope(&path, policy)?;
    if review.role != "custody-provider" {
        return Err("custody provider action has the wrong signed role".to_owned());
    }
    let stable_id = json_member(copy, stable_field)?.string()?;
    let provider_subject = json_member(copy, subject_field)?.string()?;
    validate_external_stable_id(stable_id, stable_field)?;
    let signed_subject = format!("custody-provider:{provider_subject}");
    if review.subject != signed_subject {
        return Err(
            "custody provider signature subject does not match the retained AWS principal"
                .to_owned(),
        );
    }
    Ok(ReviewGraphAction {
        action_kind: action_kind.to_owned(),
        stable_account_id: stable_id.to_owned(),
        subject: review.subject,
        signer_fingerprint: review.signer_fingerprint,
        role: "custody-provider".to_owned(),
        review_sha256: record_digest(&path)?,
        environment: json_member(copy, "trustDomain")?.string()?.to_owned(),
        team: format!(
            "{}:{}",
            json_member(copy, "provider")?.string()?,
            json_member(copy, "accountOrTenant")?.string()?
        ),
        provider_run_id: 0,
        provider_run_attempt: 0,
    })
}

fn validate_external_stable_id(value: &str, label: &str) -> Result<(), String> {
    if value.is_empty()
        || value.chars().any(char::is_control)
        || value.bytes().any(|byte| byte.is_ascii_whitespace())
    {
        return Err(format!("{label} is not a stable provider identity"));
    }
    Ok(())
}

fn verify_artifact_acquisition_policy(
    acquisitions: &[ReviewGraphAction; 2],
    require_external_or_separate_team: bool,
) -> Result<(), String> {
    let primary = acquisitions
        .iter()
        .find(|action| action.role == "artifact-primary-acquirer")
        .ok_or_else(|| "artifact authenticity lacks its primary acquisition action".to_owned())?;
    let independent = acquisitions
        .iter()
        .find(|action| action.role == "artifact-independent-acquirer")
        .ok_or_else(|| {
            "artifact authenticity lacks its independent acquisition action".to_owned()
        })?;
    if primary.stable_account_id == independent.stable_account_id
        || primary.team == independent.team
        || (require_external_or_separate_team && !independent.team.starts_with("aws-s3-account:"))
    {
        return Err(
            "artifact authenticity lacks stable actor, team, or external-domain independence"
                .to_owned(),
        );
    }
    Ok(())
}

fn acquired_artifact_actions(
    records: &BTreeMap<&str, PathBuf>,
    policy: &Path,
    candidate: &str,
) -> Result<[ReviewGraphAction; 2], String> {
    let directory = records
        .get("artifactAuthenticity")
        .ok_or_else(|| "proposal lacks artifact authenticity evidence".to_owned())?;
    let primary = parse_acquisition_receipt(&directory.join("receipt-primary.json"))?;
    let independent = parse_acquisition_receipt(&directory.join("receipt-independent.json"))?;
    verify_provider_metadata(directory, &primary, "primary")?;
    verify_provider_metadata(directory, &independent, "independent")?;
    verify_external_acquisition_evidence(directory, &independent)?;
    let attestations =
        verify_artifact_receipt_attestations(directory, policy, &primary, &independent)?;
    verify_graph_acquisition_selection(directory, "primary", &primary, candidate)?;
    verify_graph_acquisition_selection(directory, "independent", &independent, candidate)?;
    if primary.observed_sha256 != independent.observed_sha256
        || primary.stable_identity() == independent.stable_identity()
        || primary.trust_domain == independent.trust_domain
    {
        return Err(
            "artifact acquisitions lack stable actor or trust-domain independence".to_owned(),
        );
    }
    Ok([
        acquisition_graph_action(&primary, &attestations[0], "artifact-primary-acquirer"),
        acquisition_graph_action(
            &independent,
            &attestations[1],
            "artifact-independent-acquirer",
        ),
    ])
}

impl AcquisitionReceipt {
    fn stable_identity(&self) -> String {
        self.acquirer_account_id.to_string()
    }
}

fn acquisition_graph_action(
    receipt: &AcquisitionReceipt,
    attestation: &VerifiedArtifactAttestation,
    role: &str,
) -> ReviewGraphAction {
    ReviewGraphAction {
        action_kind: "acquired-artifact".to_owned(),
        stable_account_id: attestation.certificate_identity.clone(),
        subject: attestation.certificate_identity.clone(),
        signer_fingerprint: attestation.signer_fingerprint.clone(),
        role: role.to_owned(),
        review_sha256: attestation.digest.clone(),
        environment: receipt.acquisition_workflow_ref.clone(),
        team: format!(
            "{}:{}",
            receipt.trust_domain, attestation.certificate_issuer
        ),
        provider_run_id: receipt.acquisition_run_id,
        provider_run_attempt: receipt.acquisition_run_attempt,
    }
}

fn verify_graph_acquisition_selection(
    directory: &Path,
    label: &str,
    receipt: &AcquisitionReceipt,
    candidate: &str,
) -> Result<(), String> {
    let selection_directory = directory.join("source-selection").join(label);
    let selection = parse_json(&read_text(&selection_directory.join("selection.json"))?)?;
    let selection = selection.object()?;
    exact_keys(selection, PROVIDER_SELECTION_KEYS)?;
    let run_path = selection_directory.join("provider-selected-run.json");
    verify_file_digest(
        &run_path,
        json_member(selection, "providerRunApiSha256")?.string()?,
        "acquisition selection run API",
    )?;
    let run = parse_json(&read_text(&run_path)?)?;
    let run = run.object()?;
    let repository_id = receipt
        .repository_id
        .parse::<u64>()
        .map_err(|_| "acquisition repository ID is not numeric".to_owned())?;
    let workflow = if receipt.external_acquisition_path.is_some() {
        ".github/workflows/artifact-independent-acquisition.yml"
    } else {
        ".github/workflows/artifact-authenticity-review.yml"
    };
    let acquisition_ref =
        acquisition_workflow_reference(&receipt.acquisition_workflow_ref, workflow)?;
    let provider_ref = provider_run_workflow_ref(json_member(run, "path")?.string()?, workflow)?;
    if json_member(selection, "candidateCommit")?.string()? != candidate
        || json_member(selection, "providerRunId")?.number()? != receipt.acquisition_run_id
        || json_member(selection, "providerRunAttempt")?.number()?
            != receipt.acquisition_run_attempt
        || json_member(run, "id")?.number()? != receipt.acquisition_run_id
        || json_member(run, "run_attempt")?.number()? != receipt.acquisition_run_attempt
        || json_member(run, "head_sha")?.string()? != candidate
        || !provider_workflow_ref_matches(acquisition_ref, &provider_ref)
        || json_member(json_member(run, "repository")?.object()?, "id")?.number()? != repository_id
    {
        return Err(
            "acquisition action does not match the selected signed provider run".to_owned(),
        );
    }
    Ok(())
}

fn provider_workflow_ref_matches(acquisition_ref: &str, provider_ref: &str) -> bool {
    acquisition_ref == provider_ref
        || acquisition_ref.strip_prefix("refs/heads/") == Some(provider_ref)
        || acquisition_ref.strip_prefix("refs/tags/") == Some(provider_ref)
}

fn claim_proposer_action(
    retained_root: &Path,
    candidate: &str,
    epoch: &str,
) -> Result<ReviewGraphAction, String> {
    let coverage_path = retained_root
        .join("coverage")
        .join("claim-coverage.finalized.json");
    let coverage = parse_json(&read_text(&coverage_path)?)?;
    let coverage = coverage.object()?;
    if json_member(coverage, "schemaVersion")?.number()? != 2
        || json_member(coverage, "candidateSourceCommit")?.string()? != candidate
        || json_member(coverage, "assuranceEpochSha256")?.string()? != epoch
    {
        return Err("claim proposer coverage identity is stale".to_owned());
    }
    let repository = repository_root()?;
    let decisions_path = confined_record_path(
        &repository,
        retained_root,
        Path::new(json_member(coverage, "applicabilityDecisionsPath")?.string()?),
    )?;
    verify_file_digest(
        &decisions_path,
        json_member(coverage, "applicabilityDecisionsSha256")?.string()?,
        "claim proposer decision artifact",
    )?;
    let decisions = parse_json(&read_text(&decisions_path)?)?;
    let decisions = decisions.object()?;
    let source_digest = json_member(coverage, "sourceCoverageSha256")?.string()?;
    claim_applicability_decisions(decisions, candidate, epoch, source_digest, retained_root)?;
    let account_id = json_member(decisions, "claimProposerAccountId")?.number()?;
    let login = json_member(decisions, "claimProposerLogin")?.string()?;
    let run_id = json_member(decisions, "providerRunId")?.number()?;
    let run_attempt = json_member(decisions, "providerRunAttempt")?.number()?;
    if account_id == 0 || run_id == 0 || run_attempt == 0 {
        return Err("claim proposer provider identity is incomplete".to_owned());
    }
    Ok(ReviewGraphAction {
        action_kind: "proposed-claims".to_owned(),
        stable_account_id: account_id.to_string(),
        subject: login.to_owned(),
        signer_fingerprint: sha256_bytes(format!("provider-account:{account_id}").as_bytes()).hex(),
        role: "claim-proposer".to_owned(),
        review_sha256: record_digest(&decisions_path)?,
        environment: "github-actions".to_owned(),
        team: "provider-dispatch".to_owned(),
        provider_run_id: run_id,
        provider_run_attempt: run_attempt,
    })
}

fn oracle_trigger_actions(
    records: &BTreeMap<&str, PathBuf>,
    retained_root: &Path,
    candidate: &str,
    epoch: &str,
) -> Result<Vec<ReviewGraphAction>, String> {
    let repository = repository_root()?;
    let mut actions = Vec::new();
    for name in ["oracleProvenanceMacos", "oracleProvenanceWindows"] {
        let provenance_path = records
            .get(name)
            .ok_or_else(|| format!("proposal lacks {name}"))?;
        let provenance = parse_json(&read_text(provenance_path)?)?;
        let provenance = provenance.object()?;
        if json_member(provenance, "candidateCommit")?.string()? != candidate
            || json_member(provenance, "assuranceEpochSha256")?.string()? != epoch
        {
            return Err("oracle trigger provenance identity is stale".to_owned());
        }
        let platform = json_member(provenance, "platform")?.string()?;
        for ordinal in ["first", "second"] {
            let field = |suffix: &str| format!("{ordinal}{suffix}");
            let subject_path = confined_record_path(
                &repository,
                retained_root,
                Path::new(json_member(provenance, &field("BuilderSubjectPath"))?.string()?),
            )?;
            verify_file_digest(
                &subject_path,
                json_member(provenance, &field("BuilderSubjectSha256"))?.string()?,
                "oracle trigger builder subject",
            )?;
            let subject = parse_json(&read_text(&subject_path)?)?;
            let subject = subject.object()?;
            let actor_id = json_member(provenance, &field("TriggerActorId"))?.string()?;
            let actor_login = json_member(provenance, &field("TriggerActorLogin"))?.string()?;
            let run_id = json_member(provenance, &field("TriggerRunId"))?
                .string()?
                .parse::<u64>()
                .map_err(|_| "oracle trigger run ID is not an integer".to_owned())?;
            let run_attempt = json_member(provenance, &field("TriggerRunAttempt"))?
                .string()?
                .parse::<u64>()
                .map_err(|_| "oracle trigger run attempt is not an integer".to_owned())?;
            if actor_id
                .parse::<u64>()
                .ok()
                .as_ref()
                .is_none_or(|value| *value == 0)
                || run_id == 0
                || run_attempt == 0
                || json_member(subject, "triggerActorId")?.string()? != actor_id
                || json_member(subject, "triggerActorLogin")?.string()? != actor_login
                || json_member(subject, "triggerRunId")?.string()? != run_id.to_string()
                || json_member(subject, "triggerRunAttempt")?.string()? != run_attempt.to_string()
            {
                return Err(
                    "oracle trigger facts disagree with the signed builder subject".to_owned(),
                );
            }
            actions.push(ReviewGraphAction {
                action_kind: "triggered-oracle-build".to_owned(),
                stable_account_id: actor_id.to_owned(),
                subject: actor_login.to_owned(),
                signer_fingerprint: sha256_bytes(format!("provider-account:{actor_id}").as_bytes())
                    .hex(),
                role: "oracle-trigger".to_owned(),
                review_sha256: record_digest(&subject_path)?,
                environment: json_member(provenance, &field("TriggerWorkflowRef"))?
                    .string()?
                    .to_owned(),
                team: format!("oracle-{platform}-{ordinal}"),
                provider_run_id: run_id,
                provider_run_attempt: run_attempt,
            });
        }
    }
    Ok(actions)
}

fn evidence_run_trigger_action(
    records: &BTreeMap<&str, PathBuf>,
    candidate: &str,
) -> Result<ReviewGraphAction, String> {
    let acquisition = records
        .get("artifactAuthenticity")
        .ok_or_else(|| "proposal lacks artifact authenticity evidence".to_owned())?;
    let selection_path = acquisition
        .join("source-selection")
        .join("primary")
        .join("selection.json");
    let run_path = acquisition
        .join("source-selection")
        .join("primary")
        .join("provider-selected-run.json");
    let selection = parse_json(&read_text(&selection_path)?)?;
    let selection = selection.object()?;
    let run = parse_json(&read_text(&run_path)?)?;
    let run = run.object()?;
    let actor = json_member(run, "actor")?.object()?;
    let account_id = json_member(actor, "id")?.number()?;
    let login = json_member(actor, "login")?.string()?;
    validate_provider_atom(login, "evidence run actor login")?;
    if account_id == 0
        || json_member(run, "id")?.number()? != json_member(selection, "providerRunId")?.number()?
        || json_member(run, "run_attempt")?.number()?
            != json_member(selection, "providerRunAttempt")?.number()?
        || json_member(run, "head_sha")?.string()? != candidate
    {
        return Err("evidence-run trigger provider facts are stale".to_owned());
    }
    Ok(ReviewGraphAction {
        action_kind: "triggered-evidence-run".to_owned(),
        stable_account_id: account_id.to_string(),
        subject: login.to_owned(),
        signer_fingerprint: sha256_bytes(format!("provider-account:{account_id}").as_bytes()).hex(),
        role: "evidence-run-trigger".to_owned(),
        review_sha256: record_digest(&run_path)?,
        environment: "github-actions".to_owned(),
        team: "Portfoligno/hell-rs".to_owned(),
        provider_run_id: json_member(run, "id")?.number()?,
        provider_run_attempt: json_member(run, "run_attempt")?.number()?,
    })
}

fn verify_cross_action_independence(
    producer: &ReviewGraphAction,
    reviewer: &ReviewGraphAction,
    rule: &str,
) -> Result<(), String> {
    if producer.stable_account_id != reviewer.stable_account_id
        || crate::assurance_control_mutant_active("producer-independent-review-alias")
    {
        Ok(())
    } else {
        Err(format!(
            "review independence policy violated: {rule} (stable account {})",
            producer.stable_account_id
        ))
    }
}

fn verify_reviewer_identity_compatibility(
    prior_role: &str,
    prior_key: &str,
    current_role: &str,
    current_key: &str,
) -> Result<(), String> {
    if (prior_role == current_role && prior_key == current_key)
        || crate::assurance_control_mutant_active("producer-independent-review-alias")
    {
        Ok(())
    } else {
        Err("one stable account aliases producer and independent reviewer roles".to_owned())
    }
}

fn review_policy_for_envelope(path: &Path, fallback: &Path) -> Result<PathBuf, String> {
    let directory = path
        .parent()
        .ok_or_else(|| "review envelope has no retained directory".to_owned())?;
    let authorization = directory.join("authorization.json");
    if !authorization.is_file() {
        return Ok(fallback.to_path_buf());
    }
    let policy = directory.join("reviewer.allowed_signers");
    if !policy.is_file() {
        return Err("authorized review lacks its retained signer policy".to_owned());
    }
    Ok(policy)
}

fn verify_authorized_human_review(
    envelope_path: &Path,
    fallback_policy: &Path,
    role: &str,
    candidate: &str,
    reviewed_subject_name: &str,
) -> Result<VerifiedReview, String> {
    let directory = envelope_path
        .parent()
        .ok_or_else(|| "authorized review envelope has no retained directory".to_owned())?;
    let authorization_path = directory.join("authorization.json");
    let reviewed_subject = directory
        .join("reviewed-provider-extracted-subject")
        .join(reviewed_subject_name);
    if !authorization_path.is_file() || !reviewed_subject.is_file() {
        return Err(format!(
            "human review role {role:?} lacks its retained authorization or exact subject"
        ));
    }
    verify_review_authorization(&authorization_path, role, candidate, &reviewed_subject)?;
    let signer_policy = review_policy_for_envelope(envelope_path, fallback_policy)?;
    let review = verify_review_envelope(envelope_path, &signer_policy)?;
    if review.role != role
        || review.candidate_commit != candidate
        || !review
            .reviewed_artifacts
            .contains(&record_digest(&authorization_path)?)
        || !review
            .reviewed_artifacts
            .contains(&record_digest(&reviewed_subject)?)
    {
        return Err(
            "authorized human review does not bind its authorization and subject".to_owned(),
        );
    }
    Ok(review)
}

fn review_graph_action(
    path: &Path,
    review: &VerifiedReview,
    review_sha256: &str,
) -> Result<ReviewGraphAction, String> {
    let authorization_path = path
        .parent()
        .ok_or_else(|| "review action has no parent directory".to_owned())?
        .join("authorization.json");
    let authorization = if authorization_path.is_file() {
        Some(parse_json(&read_text(&authorization_path)?)?)
    } else {
        None
    };
    let facts = authorization.as_ref().map(JsonValue::object).transpose()?;
    if facts.is_none() && !matches!(review.role.as_str(), "oracle-builder" | "custody-provider") {
        return Err(format!(
            "human review role {:?} lacks retained protected authorization",
            review.role
        ));
    }
    let stable_account_id = facts
        .map(|record| json_member(record, "accountId").and_then(JsonValue::number))
        .transpose()?
        .map_or_else(|| review.subject.clone(), |id| id.to_string());
    let text_fact = |field: &str, fallback: &str| -> Result<String, String> {
        facts.map_or_else(
            || Ok(fallback.to_owned()),
            |record| Ok(json_member(record, field)?.string()?.to_owned()),
        )
    };
    let number_fact = |field: &str| -> Result<u64, String> {
        facts.map_or(Ok(0), |record| json_member(record, field)?.number())
    };
    Ok(ReviewGraphAction {
        action_kind: review_action_kind(&review.role).to_owned(),
        stable_account_id,
        subject: review.subject.clone(),
        signer_fingerprint: review.signer_fingerprint.clone(),
        role: review.role.clone(),
        review_sha256: review_sha256.to_owned(),
        environment: text_fact("environment", "provider-workload")?,
        team: text_fact("team", &review.role)?,
        provider_run_id: number_fact("runId")?,
        provider_run_attempt: number_fact("runAttempt")?,
    })
}

fn review_action_kind(role: &str) -> &'static str {
    match role {
        "artifact-primary-acquirer" | "artifact-independent-acquirer" => "acquired-artifact",
        "candidate-author" | "candidate-committer" => "authored-candidate-commit",
        "claim-author" => "authored-claim-change",
        "normalizer-author" => "authored-normalizer",
        "claim-proposer" => "proposed-claims",
        "evidence-run-trigger" => "triggered-evidence-run",
        "oracle-trigger" => "triggered-oracle-build",
        "oracle-builder" => "built-oracle",
        "custody-provider" => "retrieved-custody-copy",
        _ => "signed-review",
    }
}

fn review_action_kind_is_valid(role: &str, action_kind: &str) -> bool {
    if role == "custody-provider" {
        matches!(
            action_kind,
            "uploaded-custody-copy" | "retrieved-custody-copy"
        )
    } else {
        action_kind == review_action_kind(role)
    }
}

fn render_review_graph(
    candidate: &str,
    epoch: &str,
    actions: &BTreeSet<ReviewGraphAction>,
    roles: &BTreeSet<String>,
) -> String {
    let mut output = format!(
        "{{\n  \"schemaVersion\": 1,\n  \"candidateSourceCommit\": {},\n  \"assuranceEpochSha256\": {},\n  \"requiredRoles\": [",
        json_string(candidate),
        json_string(epoch)
    );
    push_json_strings(&mut output, roles.iter().map(String::as_str));
    output.push_str("],\n  \"verifiedRoles\": [");
    push_json_strings(&mut output, roles.iter().map(String::as_str));
    write!(
        output,
        "],\n  \"distinctSubjects\": {},\n  \"actions\": [",
        actions
            .iter()
            .map(|action| &action.stable_account_id)
            .collect::<BTreeSet<_>>()
            .len()
    )
    .expect("writing to String cannot fail");
    for (index, action) in actions.iter().enumerate() {
        if index != 0 {
            output.push(',');
        }
        write!(
            output,
            "\n    {{\"actionKind\":{},\"stableAccountId\":{},\"subject\":{},\"signerFingerprint\":{},\"role\":{},\"reviewSha256\":{},\"environment\":{},\"team\":{},\"providerRunId\":{},\"providerRunAttempt\":{}}}",
            json_string(&action.action_kind), json_string(&action.stable_account_id),
            json_string(&action.subject), json_string(&action.signer_fingerprint),
            json_string(&action.role), json_string(&action.review_sha256),
            json_string(&action.environment), json_string(&action.team),
            action.provider_run_id, action.provider_run_attempt,
        ).expect("writing to String cannot fail");
    }
    output.push_str("\n  ],\n  \"policyViolations\": []\n}\n");
    output
}

fn push_json_strings<'a>(output: &mut String, values: impl Iterator<Item = &'a str>) {
    for (index, value) in values.enumerate() {
        if index != 0 {
            output.push(',');
        }
        push_json(output, value);
    }
}

fn verify_actual_review_graph(
    records: &BTreeMap<&str, PathBuf>,
    retained_root: &Path,
    policy: &Path,
    candidate: &str,
    epoch: &str,
) -> Result<VerifiedReviewGraph, String> {
    let actual = collect_actual_review_actions(records, retained_root, policy, candidate, epoch)?;
    require_complete_review_roles(
        &actual.actions,
        &actual.roles,
        &actual.identities,
        actual.minimum_distinct_people,
    )?;
    let graph_record = records
        .get("reviewRoleGraph")
        .ok_or_else(|| "proposal lacks review role graph".to_owned())?;
    let graph = bound_details_document(graph_record, retained_root)?;
    let all_subject_count = actual
        .actions
        .iter()
        .map(|action| &action.stable_account_id)
        .collect::<BTreeSet<_>>()
        .len();
    let human_subject_count = human_reviewer_subject_count(&actual.actions);
    verify_declared_review_graph(
        graph.object()?,
        &actual.actions,
        &actual.roles,
        all_subject_count,
        human_subject_count,
        actual.minimum_distinct_people,
    )?;
    let repository = repository_root()?;
    let wrapper = parse_json(&read_text(graph_record)?)?;
    let graph_review_path = confined_record_path(
        &repository,
        retained_root,
        Path::new(json_member(wrapper.object()?, "reviewPath")?.string()?),
    )?;
    let graph_policy = review_policy_for_envelope(&graph_review_path, policy)?;
    let graph_review = verify_review_envelope(&graph_review_path, &graph_policy)?;
    if graph_review.role != "review-graph-reviewer"
        || graph_review.candidate_commit != candidate
        || graph_review.assurance_epoch != epoch
    {
        return Err("review graph approval does not bind the candidate and epoch".to_owned());
    }
    let graph_review_digest = record_digest(&graph_review_path)?;
    let graph_review_action =
        review_graph_action(&graph_review_path, &graph_review, &graph_review_digest)?;
    if actual
        .identities
        .contains_key(&graph_review_action.stable_account_id)
    {
        return Err("review graph approver is not independent of evidence reviewers".to_owned());
    }
    let supporting_identities = actual
        .actions
        .iter()
        .filter(|action| !actual.identities.contains_key(&action.stable_account_id))
        .map(|action| {
            (
                action.stable_account_id.clone(),
                action.signer_fingerprint.clone(),
            )
        })
        .collect::<BTreeSet<_>>();
    let mut distinct = actual
        .identities
        .into_iter()
        .map(|(stable_account_id, (_, fingerprint))| (stable_account_id, fingerprint))
        .collect::<BTreeSet<_>>();
    distinct.extend(supporting_identities);
    if distinct
        .iter()
        .any(|(_, fingerprint)| fingerprint == &graph_review.signer_fingerprint)
    {
        return Err("review graph approver reuses an evidence reviewer signing key".to_owned());
    }
    distinct.insert((
        graph_review_action.stable_account_id,
        graph_review.signer_fingerprint,
    ));
    Ok(VerifiedReviewGraph {
        actions: actual.actions,
        distinct_identities: distinct,
    })
}

fn require_complete_review_roles(
    actions: &BTreeSet<ReviewGraphAction>,
    roles: &BTreeSet<String>,
    identities: &BTreeMap<String, (String, String)>,
    minimum_distinct_people: u64,
) -> Result<(), String> {
    let required = BTreeSet::from([
        "artifact-trust-reviewer",
        "artifact-primary-acquirer",
        "artifact-independent-acquirer",
        "claim-reviewer",
        "candidate-author",
        "candidate-committer",
        "custody-provider",
        "custody-reviewer",
        "divergence-reviewer",
        "evidence-run-trigger",
        "mutation-reviewer",
        "normalizer-reviewer",
        "oracle-builder",
        "platform-reviewer",
        "residual-risk-reviewer",
    ]);
    let mut role_subjects = BTreeMap::<String, BTreeSet<String>>::new();
    let mut fingerprints = BTreeMap::<String, String>::new();
    for action in actions {
        role_subjects
            .entry(action.role.clone())
            .or_default()
            .insert(action.stable_account_id.clone());
        if let Some(prior) = fingerprints.insert(
            action.signer_fingerprint.clone(),
            action.stable_account_id.clone(),
        ) && prior != action.stable_account_id
        {
            return Err("one signing key is aliased to multiple stable identities".to_owned());
        }
    }
    let distinct_people = human_reviewer_subject_count(actions);
    require_minimum_distinct_people(distinct_people, minimum_distinct_people)?;
    if !required.iter().all(|role| roles.contains(*role))
        || ["oracle-builder", "custody-provider"]
            .into_iter()
            .any(|role| role_subjects.get(role).map_or(0, BTreeSet::len) < 2)
        || identities.is_empty()
    {
        return Err("actual reviews do not satisfy required roles and independence".to_owned());
    }
    Ok(())
}

fn verify_declared_review_graph(
    graph: &BTreeMap<String, JsonValue>,
    actual_actions: &BTreeSet<ReviewGraphAction>,
    actual_roles: &BTreeSet<String>,
    distinct_subjects: usize,
    distinct_people: usize,
    minimum_distinct_people: u64,
) -> Result<(), String> {
    let declared_roles = json_member(graph, "verifiedRoles")?
        .array()?
        .iter()
        .map(JsonValue::string)
        .map(|value| value.map(str::to_owned))
        .collect::<Result<BTreeSet<_>, _>>()?;
    let mut declared_actions = BTreeSet::new();
    for action in json_member(graph, "actions")?.array()? {
        let action = action.object()?;
        exact_keys(
            action,
            &[
                "actionKind",
                "environment",
                "providerRunAttempt",
                "providerRunId",
                "reviewSha256",
                "role",
                "signerFingerprint",
                "stableAccountId",
                "subject",
                "team",
            ],
        )?;
        for field in ["reviewSha256", "signerFingerprint"] {
            require_digest(json_member(action, field)?.string()?, "review graph action")?;
        }
        let declared = ReviewGraphAction {
            action_kind: json_member(action, "actionKind")?.string()?.to_owned(),
            stable_account_id: json_member(action, "stableAccountId")?.string()?.to_owned(),
            subject: json_member(action, "subject")?.string()?.to_owned(),
            signer_fingerprint: json_member(action, "signerFingerprint")?
                .string()?
                .to_owned(),
            role: json_member(action, "role")?.string()?.to_owned(),
            review_sha256: json_member(action, "reviewSha256")?.string()?.to_owned(),
            environment: json_member(action, "environment")?.string()?.to_owned(),
            team: json_member(action, "team")?.string()?.to_owned(),
            provider_run_id: json_member(action, "providerRunId")?.number()?,
            provider_run_attempt: json_member(action, "providerRunAttempt")?.number()?,
        };
        if declared.stable_account_id.is_empty()
            || declared.environment.is_empty()
            || declared.team.is_empty()
            || !review_action_kind_is_valid(&declared.role, &declared.action_kind)
        {
            return Err("review role graph action identity is incomplete".to_owned());
        }
        if !declared_actions.insert(declared) {
            return Err("review role graph duplicates an action".to_owned());
        }
    }
    require_minimum_distinct_people(distinct_people, minimum_distinct_people)?;
    let distinct_subjects = u64::try_from(distinct_subjects)
        .map_err(|_| "review identity count exceeds u64".to_owned())?;
    if declared_actions != *actual_actions
        || declared_roles != *actual_roles
        || json_member(graph, "requiredRoles")?.array()?
            != json_member(graph, "verifiedRoles")?.array()?
        || json_member(graph, "distinctSubjects")?.number()? != distinct_subjects
    {
        return Err("signed role graph does not match mechanically verified reviews".to_owned());
    }
    Ok(())
}

pub fn fuzz_admit_review_graph(bytes: &[u8]) -> Result<(), String> {
    let document =
        std::str::from_utf8(bytes).map_err(|_| "review graph is not canonical UTF-8".to_owned())?;
    let action = ReviewGraphAction {
        action_kind: "signed-review".to_owned(),
        stable_account_id: "101".to_owned(),
        subject: "subject-101".to_owned(),
        signer_fingerprint: sha256_bytes(b"fuzz-review-graph-key").hex(),
        role: "claim-reviewer".to_owned(),
        review_sha256: sha256_bytes(b"fuzz-review-graph-review").hex(),
        environment: "compatibility-review".to_owned(),
        team: "claim-reviewers".to_owned(),
        provider_run_id: 41,
        provider_run_attempt: 2,
    };
    let actions = BTreeSet::from([action]);
    let roles = BTreeSet::from(["claim-reviewer".to_owned()]);
    let graph = parse_json(document)?;
    let graph = graph.object()?;
    exact_keys(
        graph,
        &[
            "actions",
            "assuranceEpochSha256",
            "candidateSourceCommit",
            "distinctSubjects",
            "policyViolations",
            "requiredRoles",
            "schemaVersion",
            "verifiedRoles",
        ],
    )?;
    require_git_sha_text(
        json_member(graph, "candidateSourceCommit")?.string()?,
        "review graph candidate",
    )?;
    require_digest(
        json_member(graph, "assuranceEpochSha256")?.string()?,
        "review graph epoch",
    )?;
    if json_member(graph, "schemaVersion")?.number()? != 1
        || !json_member(graph, "policyViolations")?.array()?.is_empty()
    {
        return Err("review graph schema or policy state is invalid".to_owned());
    }
    verify_declared_review_graph(graph, &actions, &roles, 1, 1, 1)
}

fn human_reviewer_subject_count(actions: &BTreeSet<ReviewGraphAction>) -> usize {
    actions
        .iter()
        .filter(|action| human_review_role(&action.role))
        .map(|action| &action.stable_account_id)
        .collect::<BTreeSet<_>>()
        .len()
}

fn verify_promotion_approver_independence(
    actions: &BTreeSet<ReviewGraphAction>,
    approval_account_id: &str,
    policy: &ReviewPolicy,
) -> Result<(), String> {
    if actions.iter().any(|action| {
        action.stable_account_id == approval_account_id
            && ((policy
                .promotion_approver_may_not_be_claim_proposer
                .required()
                && action.role == "claim-proposer")
                || (policy
                    .promotion_approver_may_not_be_candidate_commit_author
                    .required()
                    && action.role == "candidate-author"))
    }) {
        return Err("final promotion approver violates a configured role separation".to_owned());
    }
    Ok(())
}

fn require_minimum_distinct_people(
    distinct_people: usize,
    minimum_distinct_people: u64,
) -> Result<(), String> {
    let distinct_people = u64::try_from(distinct_people)
        .map_err(|_| "review identity count exceeds u64".to_owned())?;
    if distinct_people < minimum_distinct_people {
        return Err("review graph does not meet the configured distinct-person minimum".to_owned());
    }
    Ok(())
}

fn proposal_review_paths(
    records: &BTreeMap<&str, PathBuf>,
    retained_root: &Path,
) -> Result<Vec<PathBuf>, String> {
    let repository = repository_root()?;
    let mut paths = vec![
        records
            .get("artifactAuthenticity")
            .ok_or_else(|| "proposal lacks artifact authenticity".to_owned())?
            .join("trust-review.dsse.json"),
    ];
    for name in [
        "claimCoverage",
        "normalizerAudit",
        "divergence",
        "residualRisk",
    ] {
        let wrapper = parse_json(&read_text(
            records
                .get(name)
                .ok_or_else(|| format!("proposal lacks {name}"))?,
        )?)?;
        paths.push(confined_record_path(
            &repository,
            retained_root,
            Path::new(json_member(wrapper.object()?, "reviewPath")?.string()?),
        )?);
    }
    let divergence_record = records
        .get("divergence")
        .ok_or_else(|| "proposal lacks divergence report".to_owned())?;
    for role in divergence_approval_roles(divergence_record, retained_root)? {
        if role == "divergence-reviewer" {
            continue;
        }
        let (_, review_path) = divergence_approval_paths(divergence_record, retained_root, &role)?;
        paths.push(review_path);
    }
    append_mutation_review_path(records, retained_root, &repository, &mut paths)?;
    append_oracle_review_paths(records, retained_root, &repository, &mut paths)?;
    append_custody_review_paths(records, retained_root, &repository, &mut paths)?;
    Ok(paths)
}

fn human_review_statement_mapping_gaps(
    records: &BTreeMap<&str, PathBuf>,
    retained_root: &Path,
    policy: &Path,
) -> Result<u64, String> {
    let repository = repository_root()?;
    let mut expected_paths = proposal_review_paths(records, retained_root)?;
    let graph_record = records
        .get("reviewRoleGraph")
        .ok_or_else(|| "proposal lacks review role graph".to_owned())?;
    let graph_wrapper = parse_json(&read_text(graph_record)?)?;
    expected_paths.push(confined_record_path(
        &repository,
        retained_root,
        Path::new(json_member(graph_wrapper.object()?, "reviewPath")?.string()?),
    )?);

    let mut expected = BTreeSet::new();
    for path in expected_paths {
        let signer_policy = review_policy_for_envelope(&path, policy)?;
        let review = verify_review_envelope(&path, &signer_policy)?;
        if human_review_role(&review.role) {
            expected.insert(retained_review_relative_path(retained_root, &path)?);
        }
    }
    let mut observed = BTreeSet::new();
    collect_retained_human_review_statements(retained_root, retained_root, policy, &mut observed)?;
    u64::try_from(expected.symmetric_difference(&observed).count())
        .map_err(|_| "unmapped review statement count exceeds u64".to_owned())
}

fn human_review_role(role: &str) -> bool {
    matches!(
        role,
        "artifact-trust-reviewer"
            | "claim-author"
            | "claim-reviewer"
            | "custody-reviewer"
            | "divergence-reviewer"
            | "divergence-platform-reviewer"
            | "divergence-implementation-reviewer"
            | "divergence-product-reviewer"
            | "divergence-security-reviewer"
            | "mutation-reviewer"
            | "normalizer-reviewer"
            | "platform-reviewer"
            | "regression-reviewer"
            | "residual-risk-reviewer"
            | "review-graph-reviewer"
    )
}

fn retained_review_relative_path(retained_root: &Path, path: &Path) -> Result<String, String> {
    let relative = path.strip_prefix(retained_root).map_err(|_| {
        format!(
            "review statement {} is outside retained evidence",
            path.display()
        )
    })?;
    path_text(relative)
}

fn collect_retained_human_review_statements(
    retained_root: &Path,
    directory: &Path,
    fallback_policy: &Path,
    observed: &mut BTreeSet<String>,
) -> Result<(), String> {
    let mut entries = fs::read_dir(directory)
        .map_err(|error| format!("cannot inventory {}: {error}", directory.display()))?
        .collect::<Result<Vec<_>, _>>()
        .map_err(|error| format!("cannot inventory {}: {error}", directory.display()))?;
    entries.sort_by_key(std::fs::DirEntry::file_name);
    for entry in entries {
        let path = entry.path();
        let file_type = entry
            .file_type()
            .map_err(|error| format!("cannot inspect {}: {error}", path.display()))?;
        if file_type.is_symlink() {
            return Err(format!(
                "retained review inventory contains symlink {}",
                path.display()
            ));
        }
        if file_type.is_dir() {
            collect_retained_human_review_statements(
                retained_root,
                &path,
                fallback_policy,
                observed,
            )?;
            continue;
        }
        if !file_type.is_file()
            || !entry
                .file_name()
                .to_str()
                .is_some_and(|name| name.ends_with(".dsse.json"))
        {
            continue;
        }
        let envelope = parse_json(&read_text(&path)?)?;
        let envelope = envelope.object()?;
        if json_member(envelope, "payloadType")?.string()?
            != "application/vnd.hell-rs.assurance+json"
        {
            continue;
        }
        let signer_policy = review_policy_for_envelope(&path, fallback_policy)?;
        let review = verify_review_envelope(&path, &signer_policy)?;
        if human_review_role(&review.role)
            && !observed.insert(retained_review_relative_path(retained_root, &path)?)
        {
            return Err("retained human review inventory duplicates a path".to_owned());
        }
    }
    Ok(())
}

fn append_mutation_review_path(
    records: &BTreeMap<&str, PathBuf>,
    retained_root: &Path,
    repository: &Path,
    paths: &mut Vec<PathBuf>,
) -> Result<(), String> {
    let mutation = parse_json(&read_text(
        records
            .get("mutation")
            .ok_or_else(|| "proposal lacks mutation report".to_owned())?,
    )?)?;
    paths.push(confined_record_path(
        repository,
        retained_root,
        Path::new(json_member(mutation.object()?, "reviewPath")?.string()?),
    )?);
    Ok(())
}

fn append_oracle_review_paths(
    records: &BTreeMap<&str, PathBuf>,
    retained_root: &Path,
    repository: &Path,
    paths: &mut Vec<PathBuf>,
) -> Result<(), String> {
    for name in ["oracleProvenanceMacos", "oracleProvenanceWindows"] {
        let record = parse_json(&read_text(
            records
                .get(name)
                .ok_or_else(|| format!("proposal lacks {name}"))?,
        )?)?;
        let record = record.object()?;
        for field in [
            "firstBuildReceiptPath",
            "secondBuildReceiptPath",
            "platformReviewPath",
        ] {
            paths.push(confined_record_path(
                repository,
                retained_root,
                Path::new(json_member(record, field)?.string()?),
            )?);
        }
    }
    Ok(())
}

fn append_custody_review_paths(
    records: &BTreeMap<&str, PathBuf>,
    retained_root: &Path,
    repository: &Path,
    paths: &mut Vec<PathBuf>,
) -> Result<(), String> {
    let receipt_path = records
        .get("custody")
        .ok_or_else(|| "proposal lacks custody receipt".to_owned())?;
    let receipt_directory = receipt_path
        .parent()
        .ok_or_else(|| "custody receipt has no retained directory".to_owned())?;
    let relative_directory = receipt_directory
        .strip_prefix(retained_root)
        .map_err(|_| "custody receipt directory is outside retained evidence".to_owned())?;
    let receipt = parse_json(&read_text(receipt_path)?)?;
    let receipt = receipt.object()?;
    paths.push(confined_record_path(
        repository,
        retained_root,
        &relative_directory.join(json_member(receipt, "reviewPath")?.string()?),
    )?);
    for copy in json_member(receipt, "copies")?.array()? {
        let copy = copy.object()?;
        for field in ["uploadProviderReceiptPath", "providerReceiptPath"] {
            paths.push(confined_record_path(
                repository,
                retained_root,
                &relative_directory.join(json_member(copy, field)?.string()?),
            )?);
        }
    }
    Ok(())
}

fn indexed_detail_records<'a>(
    records: &'a [JsonValue],
    label: &str,
) -> Result<BTreeMap<String, &'a BTreeMap<String, JsonValue>>, String> {
    let mut indexed = BTreeMap::new();
    for record in records {
        if indexed
            .insert(canonical_json_digest(record)?, record.object()?)
            .is_some()
        {
            return Err(format!("{label} contains duplicate records"));
        }
    }
    Ok(indexed)
}

fn indexed_normalizer_application_records(
    records: &[JsonValue],
) -> Result<BTreeMap<String, &BTreeMap<String, JsonValue>>, String> {
    let mut indexed = BTreeMap::new();
    for record in records {
        let record = record.object()?;
        let reference = json_member(record, "applicationRef")?.string()?;
        require_digest(reference, "normalizer application reference")?;
        if indexed.insert(reference.to_owned(), record).is_some() {
            return Err("normalizer audit contains duplicate application references".to_owned());
        }
    }
    Ok(indexed)
}

fn evidence_contains(cell: &BTreeMap<String, JsonValue>, digest: &str) -> Result<bool, String> {
    Ok(json_member(cell, "evidenceRefs")?
        .array()?
        .iter()
        .any(|evidence| {
            evidence.object().ok().and_then(|object| {
                json_member(object, "bundleSha256")
                    .and_then(JsonValue::string)
                    .ok()
            }) == Some(digest)
        }))
}

fn verify_cell_normalizers(
    cell: &BTreeMap<String, JsonValue>,
    records: &BTreeMap<String, &BTreeMap<String, JsonValue>>,
    used: &mut BTreeSet<String>,
) -> Result<(), String> {
    let ids = json_member(cell, "normalizerIds")?.array()?;
    let references = json_member(cell, "normalizerApplicationRefs")?.array()?;
    let ids = ids
        .iter()
        .map(JsonValue::string)
        .collect::<Result<BTreeSet<_>, _>>()?;
    let mut observed_ids = BTreeSet::new();
    for reference in references {
        let reference = reference.string()?;
        let application = records.get(reference).ok_or_else(|| {
            "claim normalizer reference is absent from the signed audit".to_owned()
        })?;
        for field in ["builtin", "dimension", "profile", "platform"] {
            if json_member(application, field)?.string()? != json_member(cell, field)?.string()? {
                return Err("normalizer application is bound to a different claim cell".to_owned());
            }
        }
        let normalizer_id = json_member(application, "normalizerId")?.string()?;
        if !ids.contains(normalizer_id)
            || json_member(application, "applicationScope")?.string()? != "claim-stderr"
            || !evidence_contains(cell, json_member(application, "evidenceRef")?.string()?)?
        {
            return Err("normalizer application does not bind its ID and raw evidence".to_owned());
        }
        verify_normalizer_protected_facts(application)?;
        observed_ids.insert(normalizer_id);
        if !used.insert(reference.to_owned()) {
            return Err("one normalizer audit record is reused by multiple claim cells".to_owned());
        }
    }
    if observed_ids != ids {
        return Err("claim normalizer applications do not cover every declared ID".to_owned());
    }
    Ok(())
}

fn verify_normalizer_protected_facts(
    application: &BTreeMap<String, JsonValue>,
) -> Result<(), String> {
    let safe = json_member(application, "idempotent")?.boolean()?
        && json_member(application, "protectedFieldsUnchanged")?.boolean()?;
    if safe || crate::assurance_control_mutant_active("normalizer-order-or-precision-loss") {
        Ok(())
    } else {
        Err("normalizer changes ordering, numeric precision, or another protected field".to_owned())
    }
}

fn verify_normalizer_application_files(
    application: &BTreeMap<String, JsonValue>,
    input: &Path,
    output: &Path,
    second_output: &Path,
    context_path: &Path,
) -> Result<(), String> {
    let normalizer_id = json_member(application, "normalizerId")?.string()?;
    let normalizer = hell_builtins::NormalizerId::ALL
        .iter()
        .copied()
        .find(|normalizer| normalizer.as_str() == normalizer_id)
        .ok_or_else(|| "normalizer application names an unknown contract".to_owned())?;
    let contract = hell_builtins::normalizer_contract(normalizer)
        .ok_or_else(|| "normalizer application contract is unavailable".to_owned())?;
    let input_bytes = read_regular_file(input)?;
    let output_bytes = read_regular_file(output)?;
    let second_output_bytes = read_regular_file(second_output)?;
    let context = parse_json(&read_text(context_path)?)?;
    let context = context.object()?;
    exact_keys(context, &["sandboxPath", "schemaVersion", "scriptPath"])?;
    if json_member(context, "schemaVersion")?.number()? != 1
        || json_member(context, "sandboxPath")?.string()?
            != json_member(application, "sandboxPath")?.string()?
        || json_member(context, "scriptPath")?.string()?
            != json_member(application, "scriptPath")?.string()?
    {
        return Err("normalizer replay context does not match retained evidence".to_owned());
    }
    let replay =
        hell_testkit::apply_retained_normalizer_twice(hell_testkit::RetainedNormalizerInput {
            normalizer,
            observation: &input_bytes,
            sandbox: Path::new(json_member(application, "sandboxPath")?.string()?),
            script: Path::new(json_member(application, "scriptPath")?.string()?),
        });
    let facts = derive_normalizer_application_facts(
        application,
        contract,
        normalizer,
        &input_bytes,
        &output_bytes,
    )?;
    let declared_paths = json_member(application, "changedPaths")?
        .array()?
        .iter()
        .map(JsonValue::string)
        .map(|path| path.map(str::to_owned))
        .collect::<Result<Vec<_>, _>>()?;
    if json_member(application, "implementationSha256")?.string()? != contract.implementation_sha256
        || declared_paths != facts.changed_paths
        || json_member(application, "changedValues")?.number()? != facts.changed_values
        || json_member(application, "removedBytes")?.number()? != facts.removed_bytes
        || !json_member(application, "idempotent")?.boolean()?
        || replay.first_pass != output_bytes
        || replay.second_pass != second_output_bytes
        || output_bytes != second_output_bytes
        || json_member(application, "protectedFieldsUnchanged")?.boolean()?
            != facts.protected_fields_unchanged
        || !facts.protected_fields_unchanged
    {
        if crate::assurance_control_mutant_active("normalizer-order-or-precision-loss") {
            return Ok(());
        }
        return Err(
            "normalizer retained before/after evidence changes order, precision, or another protected field"
                .to_owned(),
        );
    }
    Ok(())
}

struct NormalizerApplicationFacts {
    changed_paths: Vec<String>,
    changed_values: u64,
    removed_bytes: u64,
    protected_fields_unchanged: bool,
}

fn derive_normalizer_application_facts(
    application: &BTreeMap<String, JsonValue>,
    contract: &hell_builtins::NormalizerContract,
    normalizer: hell_builtins::NormalizerId,
    input_bytes: &[u8],
    output_bytes: &[u8],
) -> Result<NormalizerApplicationFacts, String> {
    let mut changed = BTreeSet::new();
    let application_scope = json_member(application, "applicationScope")?.string()?;
    let stderr_scope = matches!(application_scope, "harness-stderr" | "claim-stderr");
    let removed_bytes = if stderr_scope {
        if input_bytes != output_bytes {
            changed.insert("stderr.path_tokens[*]".to_owned());
        }
        u64::try_from(input_bytes.len().saturating_sub(output_bytes.len()))
            .map_err(|_| "normalizer removed byte count exceeds u64".to_owned())?
    } else {
        let before = parse_json(
            std::str::from_utf8(input_bytes)
                .map_err(|_| "normalizer input is not canonical UTF-8 JSON".to_owned())?,
        )?;
        let after = parse_json(
            std::str::from_utf8(output_bytes)
                .map_err(|_| "normalizer output is not canonical UTF-8 JSON".to_owned())?,
        )?;
        collect_changed_json_paths(&before, &after, "", &mut changed);
        changed_json_removed_bytes(&before, &after)?
    };
    let allowed = contract
        .allowed_fields
        .iter()
        .map(|field| field.as_str())
        .collect::<Vec<_>>();
    let forbidden = contract
        .forbidden_fields
        .iter()
        .map(|field| field.as_str())
        .collect::<Vec<_>>();
    let changed_values = if stderr_scope {
        normalizer_changed_values(
            normalizer,
            input_bytes,
            output_bytes,
            json_member(application, "sandboxPath")?.string()?,
            json_member(application, "scriptPath")?.string()?,
        )?
    } else {
        u64::try_from(changed.len())
            .map_err(|_| "normalizer changed-value count exceeds u64".to_owned())?
    };
    let within_budget = changed_values <= contract.max_changed_values
        && removed_bytes <= contract.max_removed_bytes;
    let protected_fields_unchanged = within_budget
        && changed.iter().all(|path| {
            allowed
                .iter()
                .any(|allowed| json_path_is_within(path, allowed))
                && !forbidden
                    .iter()
                    .any(|forbidden| json_path_is_within(path, forbidden))
        })
        && (!stderr_scope
            || normalizer_protected_fields_unchanged(
                normalizer,
                application_scope,
                input_bytes,
                output_bytes,
            ));
    Ok(NormalizerApplicationFacts {
        changed_paths: changed.into_iter().collect(),
        changed_values,
        removed_bytes,
        protected_fields_unchanged,
    })
}

fn changed_json_removed_bytes(before: &JsonValue, after: &JsonValue) -> Result<u64, String> {
    match (before, after) {
        (JsonValue::Object(before), JsonValue::Object(after)) => {
            let mut removed = 0_u64;
            for (key, value) in before {
                removed = removed.saturating_add(match after.get(key) {
                    Some(after) => changed_json_removed_bytes(value, after)?,
                    None => u64::try_from(canonical_json_bytes(value)?.len())
                        .map_err(|_| "normalizer removed value exceeds u64".to_owned())?,
                });
            }
            Ok(removed)
        }
        (JsonValue::Array(before), JsonValue::Array(after)) => {
            let mut removed = 0_u64;
            for (before, after) in before.iter().zip(after) {
                removed = removed.saturating_add(changed_json_removed_bytes(before, after)?);
            }
            for value in before.iter().skip(after.len()) {
                removed = removed.saturating_add(
                    u64::try_from(canonical_json_bytes(value)?.len())
                        .map_err(|_| "normalizer removed array value exceeds u64".to_owned())?,
                );
            }
            Ok(removed)
        }
        (JsonValue::String(before), JsonValue::String(after)) if before != after => {
            let before = before.as_bytes();
            let after = after.as_bytes();
            let prefix = before
                .iter()
                .zip(after)
                .take_while(|(left, right)| left == right)
                .count();
            let maximum_suffix = before.len().min(after.len()).saturating_sub(prefix);
            let suffix = before
                .iter()
                .rev()
                .zip(after.iter().rev())
                .take(maximum_suffix)
                .take_while(|(left, right)| left == right)
                .count();
            u64::try_from(before.len().saturating_sub(prefix).saturating_sub(suffix))
                .map_err(|_| "normalizer removed string bytes exceed u64".to_owned())
        }
        _ if before != after => u64::try_from(canonical_json_bytes(before)?.len())
            .map_err(|_| "normalizer removed scalar exceeds u64".to_owned()),
        _ => Ok(0),
    }
}

fn json_path_is_within(path: &str, scope: &str) -> bool {
    path == scope
        || path
            .strip_prefix(scope)
            .is_some_and(|suffix| suffix.starts_with('.') || suffix.starts_with("[*]"))
}

fn collect_changed_json_paths(
    before: &JsonValue,
    after: &JsonValue,
    path: &str,
    changed: &mut BTreeSet<String>,
) {
    match (before, after) {
        (JsonValue::Object(before), JsonValue::Object(after)) => {
            for key in before.keys().chain(after.keys()).collect::<BTreeSet<_>>() {
                let child = if path.is_empty() {
                    (*key).clone()
                } else {
                    format!("{path}.{key}")
                };
                match (before.get(key), after.get(key)) {
                    (Some(before), Some(after)) => {
                        collect_changed_json_paths(before, after, &child, changed);
                    }
                    _ => {
                        changed.insert(child);
                    }
                }
            }
        }
        (JsonValue::Array(before), JsonValue::Array(after)) => {
            let child = format!("{path}[*]");
            if before.len() != after.len() {
                changed.insert(child.clone());
            }
            for (before, after) in before.iter().zip(after) {
                collect_changed_json_paths(before, after, &child, changed);
            }
        }
        _ if before != after => {
            changed.insert(path.to_owned());
        }
        _ => {}
    }
}

fn verify_proposed_divergence_record(record: &BTreeMap<String, JsonValue>) -> Result<(), String> {
    verify_proposed_divergence_schema(record)?;
    verify_proposed_divergence_identity(record)?;
    verify_proposed_divergence_context(record)?;
    verify_proposed_mismatch_fact_arrays(record)?;
    verify_proposed_divergence_categories(record)?;
    verify_divergence_objective_evidence(json_member(record, "objectiveEvidence")?)
}

fn verify_proposed_divergence_schema(record: &BTreeMap<String, JsonValue>) -> Result<(), String> {
    exact_keys(
        record,
        &[
            "affectedCaseIds",
            "affectedExamples",
            "baselineExecutableSha256",
            "baselineImplementationId",
            "baselineObservationPath",
            "baselineSourceIdentity",
            "baselineSourceLocation",
            "builtin",
            "caseId",
            "caseSourceSha256",
            "candidateImplementationId",
            "candidateExecutableSha256",
            "candidateObservationPath",
            "candidateSourceLocation",
            "candidateSourceSha256",
            "differingPaths",
            "dimension",
            "evidencePath",
            "evidenceRef",
            "mismatchCategories",
            "mismatchFingerprint",
            "normalizedMismatchFacts",
            "normalizedObservationSha256",
            "normalizerAnalysis",
            "normalizerSafetyEvidence",
            "objectiveEvidence",
            "platform",
            "potentialNormalizerIds",
            "profile",
            "rawMismatchFacts",
            "rawObservationSha256",
            "recommendedExpiryDays",
            "recommendedImpactTier",
            "userImpactTemplate",
        ],
    )
}

fn verify_divergence_objective_evidence(value: &JsonValue) -> Result<(), String> {
    let evidence = value.object()?;
    exact_keys(
        evidence,
        &[
            "automatedOriginClassification",
            "derivedFixability",
            "derivedPriorReleaseState",
            "fixPrototypeEvidence",
            "neighboringBoundaryFacts",
            "priorCandidateEvidence",
            "profileComparison",
            "schemaVersion",
            "upstreamPlatformFacts",
        ],
    )?;
    if json_member(evidence, "schemaVersion")?.number()? != 1 {
        return Err("divergence objective derivation is invalid".to_owned());
    }
    let platforms = json_member(evidence, "upstreamPlatformFacts")?.array()?;
    if platforms.len() != REQUIRED_CLAIM_PLATFORMS.len() {
        return Err("divergence objective evidence lacks all supported platforms".to_owned());
    }
    for (fact, expected_platform) in platforms.iter().zip(REQUIRED_CLAIM_PLATFORMS) {
        let fact = fact.object()?;
        exact_keys(
            fact,
            &[
                "bundlePath",
                "bundleSha256",
                "classification",
                "fingerprintSha256",
                "platform",
                "profile",
            ],
        )?;
        let classification = json_member(fact, "classification")?.string()?;
        if json_member(fact, "platform")?.string()? != *expected_platform
            || json_member(fact, "profile")?.string()? != "upstream"
            || !matches!(classification, "exact" | "normalized" | "mismatch")
        {
            return Err("divergence upstream platform fact is not exact".to_owned());
        }
        require_digest(
            json_member(fact, "bundleSha256")?.string()?,
            "platform bundle",
        )?;
        validate_provider_workflow_path(json_member(fact, "bundlePath")?.string()?)?;
        verify_classification_fingerprint(classification, json_member(fact, "fingerprintSha256")?)?;
    }
    let prior_origin = verify_divergence_prior_candidate_evidence(
        json_member(evidence, "priorCandidateEvidence")?,
        json_member(evidence, "derivedPriorReleaseState")?.string()?,
    )?;
    let expected_fixability =
        verify_embedded_divergence_prototype(json_member(evidence, "fixPrototypeEvidence")?)?;
    if json_member(evidence, "derivedFixability")?.string()? != expected_fixability {
        return Err("divergence fixability is not derived from prototype evidence".to_owned());
    }
    verify_divergence_neighbor_facts(json_member(evidence, "neighboringBoundaryFacts")?)?;
    let profile = json_member(evidence, "profileComparison")?;
    verify_divergence_profile_comparison(profile)?;
    let expected_origin = if prior_origin == "baseline-inherent" {
        prior_origin
    } else if divergence_platform_facts_vary(platforms)? {
        "platform-inherent"
    } else if json_member(profile.object()?, "relation")?.string()?
        == "sandboxed-resolves-upstream-mismatch"
    {
        "policy-driven"
    } else {
        prior_origin
    };
    if json_member(evidence, "automatedOriginClassification")?.string()? != expected_origin {
        return Err("divergence apparent origin is not derived from objective evidence".to_owned());
    }
    Ok(())
}

fn verify_embedded_divergence_prototype(value: &JsonValue) -> Result<&str, String> {
    let record = value.object()?;
    let state = json_member(record, "state")?.string()?;
    if state == "attempted-unavailable" {
        exact_keys(
            record,
            &[
                "candidateCommit",
                "caseId",
                "derivedFixability",
                "elapsedMilliseconds",
                "manifestSha256",
                "policy",
                "reason",
                "schemaVersion",
                "state",
            ],
        )?;
        if json_member(record, "reason")?.string()? != "no-reviewed-prototype-entry"
            || json_member(record, "elapsedMilliseconds")?.number()? != 0
        {
            return Err("embedded unavailable prototype fact is invalid".to_owned());
        }
    } else if state == "cost-exceeded"
        && json_member(record, "reason")?.string()? == "experiment-timeout-budget-exceeds-policy"
    {
        exact_keys(
            record,
            &[
                "candidateCommit",
                "caseId",
                "derivedFixability",
                "estimatedExecutionMilliseconds",
                "manifestSha256",
                "policy",
                "reason",
                "schemaVersion",
                "state",
            ],
        )?;
        if json_member(record, "estimatedExecutionMilliseconds")?.number()? == 0 {
            return Err("embedded prototype cost estimate is empty".to_owned());
        }
    } else if matches!(state, "attempted-failed" | "cost-exceeded") {
        exact_keys(
            record,
            &[
                "baseTreeId",
                "baseTreeSha256",
                "buildStderrSha256",
                "buildStdoutSha256",
                "candidateCommit",
                "caseId",
                "derivedFixability",
                "elapsedMilliseconds",
                "manifestSha256",
                "patchSha256",
                "patchedTreeId",
                "patchedTreeSha256",
                "policy",
                "reason",
                "schemaVersion",
                "state",
            ],
        )?;
    } else if state == "executed-and-replayed" {
        verify_embedded_successful_prototype(record)?;
    } else {
        return Err("embedded prototype state is unknown".to_owned());
    }
    if json_member(record, "schemaVersion")?.number()? != 1
        || json_member(record, "caseId")?.string()?.is_empty()
    {
        return Err("embedded prototype identity is invalid".to_owned());
    }
    require_git_sha_text(
        json_member(record, "candidateCommit")?.string()?,
        "prototype candidate",
    )?;
    require_digest(
        json_member(record, "manifestSha256")?.string()?,
        "prototype manifest",
    )?;
    parse_divergence_prototype_policy(json_member(record, "policy")?)?;
    let fixability = json_member(record, "derivedFixability")?.string()?;
    if !matches!(
        fixability,
        "fix-planned" | "not-currently-fixable" | "undetermined"
    ) {
        return Err("embedded prototype fixability is unknown".to_owned());
    }
    Ok(fixability)
}

fn verify_embedded_successful_prototype(
    record: &BTreeMap<String, JsonValue>,
) -> Result<(), String> {
    exact_keys(
        record,
        &[
            "afterSourceSha256",
            "baseTreeId",
            "baseTreeSha256",
            "beforeSourceSha256",
            "buildDurationMilliseconds",
            "buildStderrSha256",
            "buildStdoutSha256",
            "builtin",
            "candidateCommit",
            "candidateExecutableSha256",
            "caseId",
            "currentCase",
            "currentMismatchResolved",
            "derivedFixability",
            "dimension",
            "elapsedMilliseconds",
            "manifestSha256",
            "neighborCases",
            "neighborsPreserved",
            "patchPath",
            "patchSha256",
            "patchedTreeId",
            "patchedTreeSha256",
            "planIssueNumber",
            "planOwner",
            "planRationale",
            "policy",
            "prototypeExecutablePath",
            "prototypeExecutableSha256",
            "result",
            "schemaVersion",
            "sourcePath",
            "state",
        ],
    )?;
    if json_member(record, "neighborCases")?.array()?.is_empty()
        || json_member(record, "planIssueNumber")?.number()? == 0
        || hell_builtins::lookup(json_member(record, "builtin")?.string()?).is_none()
        || compatibility_dimension(json_member(record, "dimension")?.string()?).is_err()
    {
        return Err("embedded successful prototype lacks reviewed scope".to_owned());
    }
    for field in [
        "afterSourceSha256",
        "baseTreeSha256",
        "beforeSourceSha256",
        "buildStderrSha256",
        "buildStdoutSha256",
        "candidateExecutableSha256",
        "patchSha256",
        "patchedTreeSha256",
        "prototypeExecutableSha256",
    ] {
        require_digest(json_member(record, field)?.string()?, "embedded prototype")?;
    }
    Ok(())
}

fn divergence_platform_facts_vary(platforms: &[JsonValue]) -> Result<bool, String> {
    let identities = platforms
        .iter()
        .map(|fact| {
            let fact = fact.object()?;
            Ok((
                json_member(fact, "classification")?.string()?,
                json_member(fact, "fingerprintSha256")?,
            ))
        })
        .collect::<Result<Vec<_>, String>>()?;
    Ok(identities
        .first()
        .is_some_and(|first| identities.iter().skip(1).any(|identity| identity != first)))
}

fn verify_divergence_profile_comparison(value: &JsonValue) -> Result<(), String> {
    let profile = value.object()?;
    exact_keys(
        profile,
        &[
            "caseId",
            "platform",
            "profiles",
            "relation",
            "schemaVersion",
            "state",
        ],
    )?;
    let platform = json_member(profile, "platform")?.string()?;
    if json_member(profile, "schemaVersion")?.number()? != 1
        || json_member(profile, "state")?.string()? != "executed-and-replayed"
        || json_member(profile, "caseId")?.string()?.is_empty()
        || !REQUIRED_CLAIM_PLATFORMS.contains(&platform)
    {
        return Err("divergence profile comparison is not evidence-derived".to_owned());
    }
    let profiles = json_member(profile, "profiles")?.array()?;
    if profiles.len() != 2 {
        return Err("divergence profile comparison lacks the exact profile set".to_owned());
    }
    let mut states = Vec::new();
    let mut fingerprints = Vec::new();
    let mut shared = None;
    for (fact, expected_profile) in profiles.iter().zip(["upstream", "sandboxed"]) {
        let fact = fact.object()?;
        exact_keys(
            fact,
            &[
                "classification",
                "executableSha256",
                "executionInputSha256",
                "fingerprintSha256",
                "invocationSha256",
                "observationSha256",
                "packagePath",
                "packageSha256",
                "profile",
                "sourceSha256",
            ],
        )?;
        let state = json_member(fact, "classification")?.string()?;
        if json_member(fact, "profile")?.string()? != expected_profile
            || !matches!(state, "exact" | "normalized" | "mismatch")
        {
            return Err("divergence profile fact has the wrong profile or state".to_owned());
        }
        for field in [
            "executableSha256",
            "executionInputSha256",
            "invocationSha256",
            "observationSha256",
            "packageSha256",
            "sourceSha256",
        ] {
            require_digest(
                json_member(fact, field)?.string()?,
                "divergence profile fact",
            )?;
        }
        validate_provider_workflow_path(json_member(fact, "packagePath")?.string()?)?;
        verify_classification_fingerprint(state, json_member(fact, "fingerprintSha256")?)?;
        let identity = (
            json_member(fact, "executableSha256")?.string()?,
            json_member(fact, "sourceSha256")?.string()?,
            json_member(fact, "executionInputSha256")?.string()?,
        );
        if shared.is_some_and(|expected| expected != identity) {
            return Err("divergence profile facts do not share one exact subject".to_owned());
        }
        shared = Some(identity);
        states.push(state);
        fingerprints.push(json_member(fact, "fingerprintSha256")?);
    }
    if states[0] != "mismatch" {
        return Err("divergence upstream profile no longer reproduces the mismatch".to_owned());
    }
    let expected_relation = if matches!(states[1], "exact" | "normalized") {
        "sandboxed-resolves-upstream-mismatch"
    } else if fingerprints[0] == fingerprints[1] {
        "same-mismatch-across-profiles"
    } else {
        "changed-mismatch-under-sandboxed-profile"
    };
    if json_member(profile, "relation")?.string()? != expected_relation {
        return Err("divergence profile relation is not derived from replay".to_owned());
    }
    Ok(())
}

fn verify_classification_fingerprint(
    classification: &str,
    fingerprint: &JsonValue,
) -> Result<(), String> {
    match (classification, fingerprint) {
        ("exact", JsonValue::Null) => Ok(()),
        ("normalized" | "mismatch", JsonValue::String(digest)) => {
            require_digest(digest, "divergence classification fingerprint")
        }
        _ => Err("divergence classification fingerprint is inconsistent".to_owned()),
    }
}

fn verify_divergence_neighbor_facts(value: &JsonValue) -> Result<(), String> {
    let packet = value.object()?;
    exact_keys(
        packet,
        &[
            "builtin",
            "cases",
            "dimension",
            "schemaVersion",
            "sourceBoundaryClasses",
            "sourceCaseId",
        ],
    )?;
    if json_member(packet, "schemaVersion")?.number()? != 1
        || json_member(packet, "sourceCaseId")?.string()?.is_empty()
        || hell_builtins::lookup(json_member(packet, "builtin")?.string()?).is_none()
        || compatibility_dimension(json_member(packet, "dimension")?.string()?).is_err()
        || json_member(packet, "sourceBoundaryClasses")?
            .array()?
            .is_empty()
    {
        return Err("divergence neighboring boundary packet is invalid".to_owned());
    }
    let facts = json_member(packet, "cases")?.array()?;
    if facts.is_empty() {
        return Err("divergence objective evidence lacks neighboring boundaries".to_owned());
    }
    let mut case_ids = BTreeSet::new();
    for fact in facts {
        let fact = fact.object()?;
        exact_keys(
            fact,
            &[
                "boundaryClasses",
                "builtin",
                "bundlePath",
                "bundleSha256",
                "caseId",
                "classification",
                "dimension",
                "fingerprintSha256",
                "sourceSha256",
            ],
        )?;
        let case_id = json_member(fact, "caseId")?.string()?;
        let classification = json_member(fact, "classification")?.string()?;
        if case_id.is_empty()
            || !case_ids.insert(case_id)
            || hell_builtins::lookup(json_member(fact, "builtin")?.string()?).is_none()
            || compatibility_dimension(json_member(fact, "dimension")?.string()?).is_err()
            || !matches!(classification, "exact" | "normalized" | "mismatch")
            || json_member(fact, "boundaryClasses")?.array()?.is_empty()
            || json_member(fact, "builtin")? != json_member(packet, "builtin")?
            || json_member(fact, "dimension")? != json_member(packet, "dimension")?
        {
            return Err("divergence neighboring boundary fact is invalid".to_owned());
        }
        require_digest(
            json_member(fact, "sourceSha256")?.string()?,
            "neighbor source",
        )?;
        require_digest(
            json_member(fact, "bundleSha256")?.string()?,
            "neighbor bundle",
        )?;
        validate_provider_workflow_path(json_member(fact, "bundlePath")?.string()?)?;
        verify_classification_fingerprint(classification, json_member(fact, "fingerprintSha256")?)?;
    }
    Ok(())
}

fn verify_divergence_prior_candidate_evidence(
    value: &JsonValue,
    prior_state: &str,
) -> Result<&'static str, String> {
    let fact = value.object()?;
    if json_member(fact, "state")?.string()? == "unavailable" {
        verify_divergence_unavailable_fact(
            value,
            "authenticated-public-endpoint-had-no-prior-promotion",
        )?;
        if prior_state != "unknown" {
            return Err("unavailable prior evidence derived a concrete origin".to_owned());
        }
        return Ok("indeterminate");
    }
    exact_keys(
        fact,
        &[
            "behaviorState",
            "currentCaseSourceSha256",
            "currentMismatchFingerprint",
            "divergenceReportSha256",
            "priorAssuranceEpochSha256",
            "priorCandidateCommit",
            "priorDivergenceId",
            "state",
            "transitionSha256",
        ],
    )?;
    for field in [
        "currentMismatchFingerprint",
        "currentCaseSourceSha256",
        "divergenceReportSha256",
        "priorAssuranceEpochSha256",
        "transitionSha256",
    ] {
        require_digest(
            json_member(fact, field)?.string()?,
            "prior promotion evidence",
        )?;
    }
    require_git_sha_text(
        json_member(fact, "priorCandidateCommit")?.string()?,
        "prior candidate commit",
    )?;
    let behavior = json_member(fact, "behaviorState")?.string()?;
    let expected = match behavior {
        "same-accepted-divergence" => ("present", "baseline-inherent", true),
        "prior-behavior-unresolved" => ("unknown", "indeterminate", false),
        _ => return Err("prior candidate behavior state is unknown".to_owned()),
    };
    if json_member(fact, "state")?.string()? != "available"
        || prior_state != expected.0
        || (json_member(fact, "priorDivergenceId")? != &JsonValue::Null) != expected.2
    {
        return Err("prior candidate behavior derivation is inconsistent".to_owned());
    }
    if expected.2 {
        require_digest(
            json_member(fact, "priorDivergenceId")?.string()?,
            "prior divergence identity",
        )?;
    }
    Ok(expected.1)
}

fn verify_divergence_unavailable_fact(value: &JsonValue, reason: &str) -> Result<(), String> {
    let fact = value.object()?;
    exact_keys(fact, &["evidenceInventorySha256", "reason", "state"])?;
    require_digest(
        json_member(fact, "evidenceInventorySha256")?.string()?,
        "divergence evidence inventory",
    )?;
    if json_member(fact, "state")?.string()? != "unavailable"
        || json_member(fact, "reason")?.string()? != reason
    {
        return Err("divergence unavailable evidence reason was substituted".to_owned());
    }
    Ok(())
}

fn verify_proposed_divergence_identity(record: &BTreeMap<String, JsonValue>) -> Result<(), String> {
    if hell_builtins::lookup(json_member(record, "builtin")?.string()?).is_none()
        || json_member(record, "caseId")?.string()?.is_empty()
        || compatibility_dimension(json_member(record, "dimension")?.string()?).is_err()
        || json_member(record, "profile")?.string()? != "upstream"
        || !REQUIRED_CLAIM_PLATFORMS.contains(&json_member(record, "platform")?.string()?)
    {
        return Err("proposed divergence scope is not one exact claim cell".to_owned());
    }
    for field in [
        "caseSourceSha256",
        "baselineExecutableSha256",
        "candidateExecutableSha256",
        "candidateSourceSha256",
        "evidenceRef",
        "mismatchFingerprint",
        "normalizedObservationSha256",
        "rawObservationSha256",
    ] {
        require_digest(
            json_member(record, field)?.string()?,
            "proposed divergence evidence",
        )?;
    }
    validate_provider_workflow_path(json_member(record, "evidencePath")?.string()?)?;
    validate_provider_workflow_path(json_member(record, "baselineObservationPath")?.string()?)?;
    validate_provider_workflow_path(json_member(record, "candidateObservationPath")?.string()?)?;
    let candidate_location = json_member(record, "candidateSourceLocation")?.string()?;
    if candidate_location.is_empty() || candidate_location.chars().any(char::is_control) {
        return Err("proposed divergence implementation location is invalid".to_owned());
    }
    if json_member(record, "baselineSourceLocation")? != &JsonValue::Null {
        return Err("unretained baseline source location must remain explicitly null".to_owned());
    }
    let baseline = json_member(record, "baselineSourceIdentity")?.object()?;
    exact_keys(
        baseline,
        &[
            "acquisitionAttestationSha256",
            "acquisitionReceiptId",
            "acquisitionReceiptSha256",
        ],
    )?;
    if json_member(record, "baselineImplementationId")? != &JsonValue::Null
        || json_member(baseline, "acquisitionReceiptId")?
            .string()?
            .is_empty()
    {
        return Err("proposed divergence baseline source identity is invalid".to_owned());
    }
    for field in ["acquisitionReceiptSha256", "acquisitionAttestationSha256"] {
        require_digest(
            json_member(baseline, field)?.string()?,
            "baseline acquisition identity",
        )?;
    }
    if json_member(record, "affectedCaseIds")?.array()?
        != [JsonValue::String(
            json_member(record, "caseId")?.string()?.to_owned(),
        )]
        || json_member(record, "normalizerSafetyEvidence")?.string()?
            != "configured-normalizers-do-not-resolve"
        || !matches!(
            json_member(record, "recommendedImpactTier")?.string()?,
            "low" | "medium" | "high" | "critical"
        )
        || json_member(record, "recommendedExpiryDays")?.number()? == 0
    {
        return Err("proposed divergence derived review facts are invalid".to_owned());
    }
    Ok(())
}

fn verify_proposed_divergence_categories(
    record: &BTreeMap<String, JsonValue>,
) -> Result<(), String> {
    let categories = json_member(record, "mismatchCategories")?
        .array()?
        .iter()
        .map(JsonValue::string)
        .collect::<Result<Vec<_>, _>>()?;
    if categories.is_empty()
        || categories.iter().collect::<BTreeSet<_>>().len() != categories.len()
        || categories.iter().any(|category| {
            !matches!(
                *category,
                "timeout" | "exit-status" | "stdout" | "stderr" | "diagnostic" | "filesystem"
            )
        })
    {
        return Err("proposed divergence mismatch categories are invalid".to_owned());
    }
    Ok(())
}

fn verify_proposed_divergence_context(record: &BTreeMap<String, JsonValue>) -> Result<(), String> {
    let (implementation, source_location, source_sha256) =
        builtin_implementation_source_facts(json_member(record, "builtin")?.string()?)?;
    if json_member(record, "candidateImplementationId")?.string()? != implementation
        || json_member(record, "candidateSourceLocation")?.string()? != source_location
        || json_member(record, "candidateSourceSha256")?.string()? != source_sha256
    {
        return Err(
            "proposed divergence candidate implementation source was substituted".to_owned(),
        );
    }
    let paths = json_member(record, "differingPaths")?
        .array()?
        .iter()
        .map(JsonValue::string)
        .map(|value| value.map(str::to_owned))
        .collect::<Result<Vec<_>, _>>()?;
    if paths.is_empty()
        || paths.windows(2).any(|pair| pair[0] >= pair[1])
        || paths.iter().any(|path| !path.starts_with("observation."))
    {
        return Err("proposed divergence differing paths are not exact and canonical".to_owned());
    }
    let categories = json_member(record, "mismatchCategories")?
        .array()?
        .iter()
        .map(JsonValue::string)
        .map(|value| value.map(str::to_owned))
        .collect::<Result<BTreeSet<_>, _>>()?;
    let (recommended_tier, recommended_days) = divergence_recommendation(
        json_member(record, "builtin")?.string()?,
        json_member(record, "dimension")?.string()?,
        &categories,
        &paths,
    )?;
    if json_member(record, "recommendedImpactTier")?.string()? != recommended_tier
        || json_member(record, "recommendedExpiryDays")?.number()? != recommended_days
    {
        return Err("proposed divergence recommendation is not evidence-derived".to_owned());
    }
    let [example] = json_member(record, "affectedExamples")?.array()? else {
        return Err("proposed divergence must bind one exact retained example".to_owned());
    };
    let example = example.object()?;
    exact_keys(example, &["caseId", "sourcePath", "sourceSha256"])?;
    if json_member(example, "caseId")?.string()? != json_member(record, "caseId")?.string()?
        || json_member(example, "sourcePath")?.string()? != "main.hell"
        || json_member(example, "sourceSha256")?.string()?
            != json_member(record, "caseSourceSha256")?.string()?
    {
        return Err("proposed divergence affected example was substituted".to_owned());
    }
    let analysis = json_member(record, "normalizerAnalysis")?.array()?;
    if analysis.len() != hell_builtins::NormalizerId::ALL.len() {
        return Err("proposed divergence normalizer analysis is incomplete".to_owned());
    }
    let mut ids = Vec::new();
    for item in analysis {
        let item = item.object()?;
        exact_keys(
            item,
            &["applicable", "normalizerId", "reason", "resolutionState"],
        )?;
        ids.push(json_member(item, "normalizerId")?.string()?);
        if json_member(item, "reason")?.string()?.is_empty()
            || !matches!(
                (
                    json_member(item, "applicable")?.boolean()?,
                    json_member(item, "resolutionState")?.string()?
                ),
                (true, "replayed-mismatch-remains") | (false, "ineligible" | "not-declared")
            )
        {
            return Err("proposed divergence normalizer analysis is unsupported".to_owned());
        }
    }
    if ids
        != hell_builtins::NormalizerId::ALL
            .iter()
            .map(|normalizer| normalizer.as_str())
            .collect::<Vec<_>>()
    {
        return Err("proposed divergence normalizer analysis IDs are not exhaustive".to_owned());
    }
    let categories = json_member(record, "mismatchCategories")?
        .array()?
        .iter()
        .map(JsonValue::string)
        .collect::<Result<Vec<_>, _>>()?;
    let expected_impact = format!(
        "{} compatibility for {} on {} differs from the retained baseline in: {}.",
        json_member(record, "dimension")?.string()?,
        json_member(record, "builtin")?.string()?,
        json_member(record, "platform")?.string()?,
        categories.join(", ")
    );
    if json_member(record, "userImpactTemplate")?.string()? != expected_impact {
        return Err("proposed divergence user-impact template was substituted".to_owned());
    }
    Ok(())
}

fn verify_proposed_mismatch_fact_arrays(
    record: &BTreeMap<String, JsonValue>,
) -> Result<(), String> {
    let raw = json_member(record, "rawMismatchFacts")?.array()?;
    let normalized = json_member(record, "normalizedMismatchFacts")?.array()?;
    for fact in raw.iter().chain(normalized) {
        let fact = fact.object()?;
        exact_keys(fact, &["candidateSha256", "category", "oracleSha256"])?;
        require_digest(
            json_member(fact, "candidateSha256")?.string()?,
            "candidate mismatch",
        )?;
        require_digest(
            json_member(fact, "oracleSha256")?.string()?,
            "oracle mismatch",
        )?;
        if !matches!(
            json_member(fact, "category")?.string()?,
            "timeout" | "exit-status" | "stdout" | "stderr" | "diagnostic" | "filesystem"
        ) {
            return Err("proposed divergence contains an unknown mismatch fact".to_owned());
        }
    }
    if canonical_json_digest(&JsonValue::Array(raw.to_vec()))?
        != json_member(record, "rawObservationSha256")?.string()?
        || canonical_json_digest(&JsonValue::Array(normalized.to_vec()))?
            != json_member(record, "normalizedObservationSha256")?.string()?
    {
        return Err("proposed divergence mismatch arrays do not match their digests".to_owned());
    }
    let expected_normalizers = hell_builtins::NormalizerId::ALL
        .iter()
        .map(|normalizer| normalizer.as_str())
        .collect::<Vec<_>>();
    let observed_normalizers = json_member(record, "potentialNormalizerIds")?
        .array()?
        .iter()
        .map(JsonValue::string)
        .collect::<Result<Vec<_>, _>>()?;
    if observed_normalizers != expected_normalizers {
        return Err("proposed divergence potential normalizers are incomplete".to_owned());
    }
    Ok(())
}

fn verify_accepted_divergence_record(
    record: &BTreeMap<String, JsonValue>,
    report_path: &Path,
) -> Result<(), String> {
    const ACCEPTED_DIVERGENCE_KEYS: &[&str] = &[
        "alternativesConsidered",
        "approvalDecisions",
        "baseline",
        "builtin",
        "candidateSha256",
        "caseId",
        "category",
        "documentationTarget",
        "dimension",
        "divergenceId",
        "evidencePath",
        "evidenceRef",
        "expiresAt",
        "fingerprint",
        "fixability",
        "impact",
        "impactTier",
        "issueNumber",
        "issuePath",
        "issueRepositoryId",
        "issueSha256",
        "issueState",
        "mismatchCategories",
        "mismatchEvidence",
        "mismatchFingerprint",
        "normalizedObservationSha256",
        "normalizerSafety",
        "originClassification",
        "owner",
        "platform",
        "priorReleaseState",
        "profile",
        "rawObservationSha256",
        "rationale",
        "reproductionState",
        "requiredReviewRoles",
        "reviewRef",
        "reviewLevel",
        "status",
        "whyNotFixCandidate",
    ];
    exact_keys(record, ACCEPTED_DIVERGENCE_KEYS)?;
    let mismatch_evidence = json_member(record, "mismatchEvidence")?.object()?;
    verify_proposed_divergence_record(mismatch_evidence)?;
    verify_divergence_candidate_join(mismatch_evidence, record)?;
    for field in [
        "candidateSha256",
        "evidenceRef",
        "fingerprint",
        "issueSha256",
        "mismatchFingerprint",
        "normalizedObservationSha256",
        "rawObservationSha256",
        "reviewRef",
    ] {
        require_digest(json_member(record, field)?.string()?, field)?;
    }
    if divergence_fingerprint(record)? != json_member(record, "fingerprint")?.string()? {
        return Err("divergence mismatch fingerprint is not derived from evidence".to_owned());
    }
    validate_utc_timestamp(json_member(record, "expiresAt")?.string()?)?;
    if utc_timestamp_seconds(json_member(record, "expiresAt")?.string()?)? <= current_utc_seconds()?
    {
        return Err("divergence record is expired".to_owned());
    }
    verify_divergence_decision_binding(record)?;
    verify_divergence_record_identity(record)?;
    verify_retained_divergence_issue(record, report_path)?;
    verify_retained_divergence_mismatch(record, report_path)?;
    Ok(())
}

fn verify_divergence_decision_binding(record: &BTreeMap<String, JsonValue>) -> Result<(), String> {
    let approvals = json_member(record, "approvalDecisions")?
        .array()?
        .iter()
        .map(JsonValue::string)
        .collect::<Result<Vec<_>, _>>()?;
    if approvals != DIVERGENCE_APPROVAL_DECISIONS {
        return Err("divergence record lacks the exact typed approval set".to_owned());
    }
    let required_roles = json_member(record, "requiredReviewRoles")?
        .array()?
        .iter()
        .map(JsonValue::string)
        .collect::<Result<Vec<_>, _>>()?;
    if required_roles
        != required_divergence_review_roles(json_member(record, "impactTier")?.string()?)?
    {
        return Err("divergence tier reviewer roles were weakened or substituted".to_owned());
    }
    let decision = BTreeMap::from([
        (
            "alternativesConsidered".to_owned(),
            json_member(record, "alternativesConsidered")?.clone(),
        ),
        (
            "baseline".to_owned(),
            json_member(record, "baseline")?.clone(),
        ),
        (
            "candidateSha256".to_owned(),
            json_member(record, "candidateSha256")?.clone(),
        ),
        (
            "category".to_owned(),
            json_member(record, "category")?.clone(),
        ),
        (
            "documentationTarget".to_owned(),
            json_member(record, "documentationTarget")?.clone(),
        ),
        (
            "expiresAt".to_owned(),
            json_member(record, "expiresAt")?.clone(),
        ),
        (
            "fixability".to_owned(),
            json_member(record, "fixability")?.clone(),
        ),
        ("impact".to_owned(), json_member(record, "impact")?.clone()),
        (
            "impactTier".to_owned(),
            json_member(record, "impactTier")?.clone(),
        ),
        (
            "issueNumber".to_owned(),
            json_member(record, "issueNumber")?.clone(),
        ),
        (
            "originClassification".to_owned(),
            json_member(record, "originClassification")?.clone(),
        ),
        ("owner".to_owned(), json_member(record, "owner")?.clone()),
        (
            "priorReleaseState".to_owned(),
            json_member(record, "priorReleaseState")?.clone(),
        ),
        (
            "rationale".to_owned(),
            json_member(record, "rationale")?.clone(),
        ),
        (
            "reviewLevel".to_owned(),
            json_member(record, "reviewLevel")?.clone(),
        ),
        ("status".to_owned(), json_member(record, "status")?.clone()),
        (
            "whyNotFixCandidate".to_owned(),
            json_member(record, "whyNotFixCandidate")?.clone(),
        ),
    ]);
    if divergence_decision_digest(&decision)? != json_member(record, "reviewRef")?.string()? {
        return Err("divergence review reference does not bind the complete decision".to_owned());
    }
    validate_divergence_decision(
        &decision,
        json_member(record, "mismatchEvidence")?.object()?,
    )?;
    Ok(())
}

fn verify_divergence_record_identity(record: &BTreeMap<String, JsonValue>) -> Result<(), String> {
    let expected_id = sha256_bytes(
        [
            json_member(record, "candidateSha256")?.string()?.as_bytes(),
            json_member(record, "reviewRef")?.string()?.as_bytes(),
        ]
        .concat()
        .as_slice(),
    )
    .hex();
    if json_member(record, "divergenceId")?.string()? != expected_id {
        return Err("divergence identity is not content-addressed".to_owned());
    }
    Ok(())
}

fn verify_retained_divergence_issue(
    record: &BTreeMap<String, JsonValue>,
    report_path: &Path,
) -> Result<(), String> {
    let retained_root = retained_evidence_root(report_path)?;
    let issue_path = confined_record_path(
        &repository_root()?,
        retained_root,
        Path::new(json_member(record, "issuePath")?.string()?),
    )?;
    verify_file_digest(
        &issue_path,
        json_member(record, "issueSha256")?.string()?,
        "divergence issue API facts",
    )?;
    let issue = parse_json(&read_text(&issue_path)?)?;
    let issue = issue.object()?;
    exact_keys(
        issue,
        &[
            "htmlUrl",
            "issueId",
            "nodeId",
            "number",
            "repository",
            "repositoryId",
            "schemaVersion",
            "state",
            "updatedAt",
        ],
    )?;
    if json_member(issue, "schemaVersion")?.number()? != 1
        || json_member(issue, "repository")?.string()? != "Portfoligno/hell-rs"
        || json_member(issue, "repositoryId")?.number()? == 0
        || json_member(issue, "repositoryId")? != json_member(record, "issueRepositoryId")?
        || json_member(issue, "number")? != json_member(record, "issueNumber")?
        || json_member(issue, "issueId")?.number()? == 0
        || json_member(issue, "nodeId")?.string()?.is_empty()
        || json_member(issue, "htmlUrl")?.string()?.is_empty()
        || json_member(issue, "state")?.string()? != "open"
        || json_member(record, "issueState")?.string()? != "open"
    {
        return Err("divergence issue facts are not exact, live, or repository-bound".to_owned());
    }
    validate_utc_timestamp(json_member(issue, "updatedAt")?.string()?)
}

fn verify_retained_divergence_mismatch(
    record: &BTreeMap<String, JsonValue>,
    report_path: &Path,
) -> Result<(), String> {
    let case_id = json_member(record, "caseId")?.string()?;
    let cases = committed_differential_cases();
    let case = cases
        .iter()
        .find(|case| case.id.as_ref() == case_id)
        .ok_or_else(|| "accepted divergence names an unknown retained case".to_owned())?;
    let mismatch_evidence = json_member(record, "mismatchEvidence")?.object()?;
    let descriptor = case
        .claim_evidence
        .as_ref()
        .ok_or_else(|| "accepted divergence case is not claim-eligible".to_owned())?;
    if json_member(mismatch_evidence, "caseSourceSha256")?.string()?
        != descriptor.source_sha256.hex()
    {
        return Err("accepted divergence case source digest was substituted".to_owned());
    }
    let retained_root = retained_evidence_root(report_path)?;
    let bundle = confined_record_path(
        &repository_root()?,
        retained_root,
        Path::new(json_member(record, "evidencePath")?.string()?),
    )?;
    if record_digest(&bundle)? != json_member(record, "evidenceRef")?.string()? {
        return Err("accepted divergence bundle digest was substituted".to_owned());
    }
    let classification = hell_testkit::classify_retained_observation_bundle(&bundle, case)
        .map_err(|error| format!("cannot reclassify accepted divergence bundle: {error}"))?;
    let hell_testkit::RetainedObservationClassification::Mismatch {
        raw_mismatches,
        normalized_mismatches,
        fingerprint_sha256,
    } = classification
    else {
        return Err("accepted divergence no longer classifies as a mismatch".to_owned());
    };
    let categories = raw_mismatches
        .iter()
        .chain(&normalized_mismatches)
        .map(|fact| mismatch_kind_name(fact.category).to_owned())
        .collect::<BTreeSet<_>>();
    let bundle_facts = divergence_bundle_facts(
        &bundle,
        case,
        json_member(record, "builtin")?.string()?,
        compatibility_dimension(json_member(record, "dimension")?.string()?)?,
        &raw_mismatches,
        &normalized_mismatches,
    )?;
    let (recommended_tier, recommended_days) = divergence_recommendation(
        json_member(record, "builtin")?.string()?,
        json_member(record, "dimension")?.string()?,
        &categories,
        &bundle_facts.differing_paths,
    )?;
    verify_retained_divergence_fact_join(
        record,
        mismatch_evidence,
        &RetainedDivergenceFacts {
            raw_mismatches,
            normalized_mismatches,
            fingerprint_sha256: fingerprint_sha256.hex(),
            categories,
            bundle: bundle_facts,
            recommended_tier,
            recommended_days,
        },
    )
}

struct RetainedDivergenceFacts {
    raw_mismatches: Vec<hell_testkit::RetainedMismatchFact>,
    normalized_mismatches: Vec<hell_testkit::RetainedMismatchFact>,
    fingerprint_sha256: String,
    categories: BTreeSet<String>,
    bundle: DivergenceBundleFacts,
    recommended_tier: &'static str,
    recommended_days: u64,
}

fn verify_retained_divergence_fact_join(
    record: &BTreeMap<String, JsonValue>,
    mismatch_evidence: &BTreeMap<String, JsonValue>,
    facts: &RetainedDivergenceFacts,
) -> Result<(), String> {
    let recorded_categories = json_member(record, "mismatchCategories")?
        .array()?
        .iter()
        .map(JsonValue::string)
        .map(|value| value.map(str::to_owned))
        .collect::<Result<BTreeSet<_>, _>>()?;
    let differing_paths = JsonValue::Array(
        facts
            .bundle
            .differing_paths
            .iter()
            .cloned()
            .map(JsonValue::String)
            .collect(),
    );
    let expected_observation_path = |role: &str| {
        path_text(
            &PathBuf::from(json_member(record, "evidencePath")?.string()?)
                .join(role)
                .join("observation.json"),
        )
    };
    if mismatch_fact_set_digest(&facts.raw_mismatches)?
        != json_member(record, "rawObservationSha256")?.string()?
        || mismatch_fact_set_digest(&facts.normalized_mismatches)?
            != json_member(record, "normalizedObservationSha256")?.string()?
        || facts.fingerprint_sha256 != json_member(record, "mismatchFingerprint")?.string()?
        || facts.categories != recorded_categories
        || json_member(mismatch_evidence, "rawMismatchFacts")?.array()?
            != mismatch_fact_values(&facts.raw_mismatches)
        || json_member(mismatch_evidence, "normalizedMismatchFacts")?.array()?
            != mismatch_fact_values(&facts.normalized_mismatches)
        || json_member(mismatch_evidence, "recommendedImpactTier")?.string()?
            != facts.recommended_tier
        || json_member(mismatch_evidence, "recommendedExpiryDays")?.number()?
            != facts.recommended_days
        || json_member(mismatch_evidence, "baselineObservationPath")?.string()?
            != expected_observation_path("oracle")?
        || json_member(mismatch_evidence, "candidateObservationPath")?.string()?
            != expected_observation_path("candidate")?
        || json_member(mismatch_evidence, "differingPaths")? != &differing_paths
        || json_member(mismatch_evidence, "candidateImplementationId")?.string()?
            != facts.bundle.candidate_implementation_id
        || json_member(mismatch_evidence, "candidateSourceLocation")?.string()?
            != facts.bundle.candidate_source_location
        || json_member(mismatch_evidence, "candidateSourceSha256")?.string()?
            != facts.bundle.candidate_source_sha256
        || json_member(mismatch_evidence, "candidateExecutableSha256")?.string()?
            != facts.bundle.candidate_executable_sha256
        || json_member(mismatch_evidence, "baselineImplementationId")?
            != &facts.bundle.baseline_implementation_id
        || json_member(mismatch_evidence, "baselineSourceLocation")?
            != &facts.bundle.baseline_source_location
        || json_member(mismatch_evidence, "baselineSourceIdentity")?
            != &facts.bundle.baseline_source_identity
        || json_member(mismatch_evidence, "baselineExecutableSha256")?.string()?
            != facts.bundle.baseline_executable_sha256
        || json_member(mismatch_evidence, "affectedExamples")?
            != &JsonValue::Array(facts.bundle.affected_examples.clone())
        || json_member(mismatch_evidence, "normalizerAnalysis")?
            != &JsonValue::Array(facts.bundle.normalizer_analysis.clone())
        || json_member(mismatch_evidence, "objectiveEvidence")? != &facts.bundle.objective_evidence
        || json_member(record, "normalizerSafety")?.string()?
            != "configured-normalizers-do-not-resolve"
        || json_member(record, "reproductionState")?.string()? != "reproduced-retained-bundle"
    {
        return Err(
            "accepted divergence mismatch facts differ from retained observations".to_owned(),
        );
    }
    Ok(())
}

fn verify_cell_divergence(
    cell: &BTreeMap<String, JsonValue>,
    records: &BTreeMap<String, &BTreeMap<String, JsonValue>>,
    used: &mut BTreeSet<String>,
) -> Result<(), String> {
    if json_member(cell, "proposedStatus")?.string()? != "deliberate-divergence" {
        return Ok(());
    }
    let reference = json_member(cell, "divergenceRecordRef")?.string()?;
    let divergence = records
        .get(reference)
        .ok_or_else(|| "claim divergence reference is absent from the signed report".to_owned())?;
    for field in ["builtin", "dimension", "profile", "platform"] {
        verify_divergence_scope_field(
            field,
            json_member(cell, field)?.string()?,
            json_member(divergence, field)?.string()?,
        )?;
    }
    if !evidence_contains(cell, json_member(divergence, "evidenceRef")?.string()?)?
        || divergence_fingerprint(divergence)?
            != json_member(divergence, "fingerprint")?.string()?
    {
        return Err("divergence record does not bind the claim evidence mismatch".to_owned());
    }
    if !used.insert(reference.to_owned()) {
        return Err("one divergence record is reused by multiple claim cells".to_owned());
    }
    Ok(())
}

fn verify_divergence_scope_field(
    field: &str,
    expected: &str,
    observed: &str,
) -> Result<(), String> {
    if expected != observed && !crate::assurance_control_mutant_active("divergence-scope-widening")
    {
        return Err(format!("divergence record widens claim {field} scope"));
    }
    Ok(())
}

fn claim_obligations(
    builtin: &str,
    dimension: CompatibilityDimension,
    platform: &str,
) -> Result<BTreeSet<String>, String> {
    let required = hell_testkit::required_obligations_for_target(builtin, dimension)
        .unwrap_or_default()
        .into_iter()
        .map(|obligation| obligation.to_string())
        .collect::<BTreeSet<_>>();
    let declared = declared_claim_obligations(builtin, dimension, platform)?;
    if !declared.is_empty() && declared != required {
        return Err(format!(
            "claim catalog obligations disagree with registry-derived target {builtin}/{}/{platform}",
            dimension.as_str()
        ));
    }
    Ok(required)
}

fn canonical_claim_cell_scope() -> Vec<(String, String, String, String)> {
    applicability_rows()
        .into_iter()
        .flat_map(|(builtin, dimension, _, _)| {
            REQUIRED_CLAIM_PLATFORMS.iter().map(move |platform| {
                (
                    builtin.to_owned(),
                    dimension.as_str().to_owned(),
                    "upstream".to_owned(),
                    (*platform).to_owned(),
                )
            })
        })
        .collect()
}

fn verify_canonical_claim_cell_scope(cells: &[JsonValue]) -> Result<(), String> {
    let expected = canonical_claim_cell_scope();
    if cells.len() != expected.len() {
        return Err("claim coverage changes the canonical cell scope".to_owned());
    }
    for (cell, (builtin, dimension, profile, platform)) in cells.iter().zip(expected) {
        let cell = cell.object()?;
        if json_member(cell, "builtin")?.string()? != builtin
            || json_member(cell, "dimension")?.string()? != dimension
            || json_member(cell, "profile")?.string()? != profile
            || json_member(cell, "platform")?.string()? != platform
        {
            return Err(
                "claim coverage omits, duplicates, or reorders a canonical cell".to_owned(),
            );
        }
    }
    Ok(())
}

fn active_collection_applicability_rows() -> Result<
    Vec<(
        &'static str,
        CompatibilityDimension,
        &'static str,
        &'static str,
    )>,
    String,
> {
    let scopes = hell_testkit::activated_collection_claim_scopes()?
        .into_iter()
        .map(|scope| scope.builtin)
        .collect::<BTreeSet<_>>();
    let rows = applicability_rows()
        .into_iter()
        .filter(|(builtin, dimension, _, _)| {
            *dimension == CompatibilityDimension::PureRuntime && scopes.contains(*builtin)
        })
        .collect::<Vec<_>>();
    if rows.len() != 14 {
        return Err("active collection applicability scope is not exact14".to_owned());
    }
    Ok(rows)
}

fn verify_scoped_collection_coverage_counts(
    details: &BTreeMap<String, JsonValue>,
) -> Result<(), String> {
    if json_member(details, "coverageScope")?.string()? != "activated-collection-exact14"
        || json_member(details, "activatedScopeCells")?.number()? != 14
        || json_member(details, "activeEvidenceCells")?.number()? != 42
        || json_member(details, "totalClaimCells")?.number()? != 42
        || json_member(details, "explicitDispositionCells")?.number()? != 42
        || json_member(details, "residualRuntimeCells")?.number()?
            != scoped_collection_residual_runtime_cells()?
        || json_member(details, "outOfScopeClaimCells")?.number()?
            != scoped_collection_out_of_scope_claim_cells()?
    {
        return Err("active collection scoped coverage counts differ".to_owned());
    }
    Ok(())
}

fn verify_scoped_collection_claim_cell_scope(cells: &[JsonValue]) -> Result<(), String> {
    let expected = active_collection_applicability_rows()?
        .into_iter()
        .flat_map(|(builtin, dimension, _, _)| {
            REQUIRED_CLAIM_PLATFORMS.iter().map(move |platform| {
                (
                    builtin.to_owned(),
                    dimension.as_str().to_owned(),
                    "upstream".to_owned(),
                    (*platform).to_owned(),
                )
            })
        })
        .collect::<Vec<_>>();
    if cells.len() != expected.len() {
        return Err("active collection coverage is not exact14 x three platforms".to_owned());
    }
    for (cell, (builtin, dimension, profile, platform)) in cells.iter().zip(expected) {
        let cell = cell.object()?;
        if json_member(cell, "builtin")?.string()? != builtin
            || json_member(cell, "dimension")?.string()? != dimension
            || json_member(cell, "profile")?.string()? != profile
            || json_member(cell, "platform")?.string()? != platform
        {
            return Err("active collection coverage substitutes a scoped cell".to_owned());
        }
    }
    Ok(())
}

fn verify_scoped_collection_evidence_edges(
    observed: &BTreeSet<(String, String)>,
) -> Result<(), String> {
    let expected = hell_testkit::activated_collection_claim_scopes()?
        .into_iter()
        .flat_map(|scope| {
            scope.case_refs.into_iter().flat_map(|case_id| {
                REQUIRED_CLAIM_PLATFORMS
                    .iter()
                    .map(move |platform| (case_id.clone(), (*platform).to_owned()))
            })
        })
        .collect::<BTreeSet<_>>();
    if observed != &expected {
        return Err(
            "active collection coverage is not the exact 1,191-case x three-platform set"
                .to_owned(),
        );
    }
    Ok(())
}

fn require_unique_claim_evidence_edges(evidence: &[JsonValue]) -> Result<(), String> {
    let mut edges = BTreeSet::new();
    for reference in evidence {
        if !edges.insert(canonical_json_digest(reference)?) {
            return Err("claim coverage contains a duplicate evidence edge".to_owned());
        }
    }
    Ok(())
}

fn declared_claim_obligations(
    builtin: &str,
    dimension: CompatibilityDimension,
    platform: &str,
) -> Result<BTreeSet<String>, String> {
    let spec = hell_builtins::lookup(builtin)
        .ok_or_else(|| format!("claim obligations name unknown builtin {builtin:?}"))?;
    let claim = hell_builtins::compatibility_claims()
        .iter()
        .find(|claim| claim.builtin == spec.id)
        .ok_or_else(|| format!("claim catalog omits builtin {builtin:?}"))?;
    let dimension_claim = claim
        .dimensions
        .iter()
        .find(|claim| claim.dimension == dimension)
        .ok_or_else(|| format!("claim catalog omits dimension {dimension:?}"))?;
    let expected_platform = match platform {
        "linux-amd64" => hell_builtins::ClaimPlatform::Linux,
        "macos-arm64" => hell_builtins::ClaimPlatform::MacOs,
        "windows-amd64" => hell_builtins::ClaimPlatform::Windows,
        _ => {
            return Err(format!(
                "claim obligations name unknown platform {platform:?}"
            ));
        }
    };
    let scopes = dimension_claim
        .scopes
        .iter()
        .filter(|scope| {
            scope
                .profiles
                .contains(&hell_builtins::ExecutionProfile::Upstream)
                && (scope.platforms.contains(&hell_builtins::ClaimPlatform::All)
                    || scope.platforms.contains(&expected_platform))
        })
        .collect::<Vec<_>>();
    let [scope] = scopes.as_slice() else {
        return Err(format!(
            "claim catalog does not select exactly one upstream scope for {builtin}/{}/{platform}",
            dimension.as_str()
        ));
    };
    Ok(scope
        .obligations
        .iter()
        .map(|obligation| (*obligation).to_owned())
        .collect())
}

fn verify_claim_evidence_reference(
    reference: &JsonValue,
    details_path: &Path,
    builtin: &str,
    dimension: CompatibilityDimension,
    platform: &str,
    candidate: &str,
    epoch: &str,
) -> Result<BTreeSet<String>, String> {
    let reference = reference.object()?;
    exact_keys(
        reference,
        &[
            "assuranceEpochSha256",
            "bundlePath",
            "bundleSha256",
            "candidateSourceCommit",
            "caseId",
            "obligations",
            "platform",
            "profile",
        ],
    )?;
    if json_member(reference, "candidateSourceCommit")?.string()? != candidate
        || json_member(reference, "assuranceEpochSha256")?.string()? != epoch
        || json_member(reference, "platform")?.string()? != platform
        || json_member(reference, "profile")?.string()? != "upstream"
    {
        return Err("claim evidence reference identity does not match its cell".to_owned());
    }
    let case_id = json_member(reference, "caseId")?.string()?;
    let case = committed_differential_cases()
        .into_iter()
        .find(|case| case.id.as_ref() == case_id)
        .ok_or_else(|| format!("claim evidence references unknown case {case_id:?}"))?;
    let descriptor = case
        .claim_evidence
        .as_ref()
        .ok_or_else(|| format!("case {case_id:?} is not eligible for claim evidence"))?;
    let target = descriptor
        .semantic_targets
        .iter()
        .find(|target| verify_case_target_binding(target, builtin, dimension, platform).is_ok())
        .ok_or_else(|| format!("case {case_id:?} does not target this claim cell"))?;
    let declared_obligations = json_member(reference, "obligations")?
        .array()?
        .iter()
        .map(JsonValue::string)
        .collect::<Result<BTreeSet<_>, _>>()?;
    let target_obligations = target
        .obligations
        .iter()
        .map(|obligation| obligation.0.as_ref())
        .collect::<BTreeSet<_>>();
    if declared_obligations != target_obligations {
        return Err("claim evidence edge obligations disagree with the case descriptor".to_owned());
    }
    let repository = repository_root()?;
    let retained_root = retained_evidence_root(details_path)?;
    let bundle = confined_record_path(
        &repository,
        retained_root,
        Path::new(json_member(reference, "bundlePath")?.string()?),
    )?;
    let expected = json_member(reference, "bundleSha256")?.string()?;
    require_digest(expected, "claim evidence bundle")?;
    if record_digest(&bundle)? != expected {
        return Err("claim evidence bundle digest mismatch".to_owned());
    }
    hell_testkit::verify_observation_bundle_for_case(&bundle, &case)
        .map_err(|error| format!("claim evidence bundle is causally invalid: {error}"))?;
    Ok(declared_obligations
        .into_iter()
        .map(str::to_owned)
        .collect())
}

fn verify_case_target_binding(
    target: &hell_testkit::EvidenceTargetV2,
    builtin: &str,
    dimension: CompatibilityDimension,
    platform: &str,
) -> Result<(), String> {
    let exact = target.builtin.as_ref() == builtin
        && target.dimension == dimension
        && target.platforms.iter().any(|target_platform| {
            matches!(target_platform, hell_builtins::ClaimPlatform::All)
                || claim_platform_matches(*target_platform, platform)
        });
    if exact || crate::assurance_control_mutant_active("ordinary-case-universal-target") {
        Ok(())
    } else {
        Err("ordinary case evidence was mapped to a claim target it does not exercise".to_owned())
    }
}

fn claim_platform_matches(platform: hell_builtins::ClaimPlatform, name: &str) -> bool {
    matches!(
        (platform, name),
        (hell_builtins::ClaimPlatform::Linux, "linux-amd64")
            | (hell_builtins::ClaimPlatform::MacOs, "macos-arm64")
            | (hell_builtins::ClaimPlatform::Windows, "windows-amd64")
    )
}

fn verify_build_plan(path: &Path) -> Result<(), String> {
    verify_build_plan_document(&read_text(path)?)
}

fn verify_build_plan_document(bytes: &str) -> Result<(), String> {
    let document = parse_json(bytes)?;
    let plan = document.object()?;
    verify_build_plan_keys(plan)?;
    verify_build_plan_contents(plan)
}

pub fn fuzz_admit_provenance_record(bytes: &[u8]) -> Result<(), String> {
    let document = std::str::from_utf8(bytes)
        .map_err(|_| "provenance record is not canonical UTF-8".to_owned())?;
    verify_build_plan_document(document)
}

fn verify_build_plan_keys(plan: &BTreeMap<String, JsonValue>) -> Result<(), String> {
    exact_keys(
        plan,
        &[
            "buildOffline",
            "commands",
            "compilerInfoSha256",
            "declaredCompilerOptions",
            "declaredResolver",
            "executableTarget",
            "localDependencies",
            "localDependencyEscapes",
            "mutableVcsDependencies",
            "packageDigestsComplete",
            "packageFlags",
            "packages",
            "resolverSha256",
            "reviewRequired",
            "schemaVersion",
            "sourceAcquisitionComplete",
            "sourceArchiveSha256",
            "sourceCommit",
            "sourceFilesSha256",
            "sourceTree",
            "sourceTreeClean",
            "stackExecutableSha256",
            "stackVersion",
            "stackYamlSha256",
            "toolchainSha256",
        ],
    )
}

fn verify_build_plan_contents(plan: &BTreeMap<String, JsonValue>) -> Result<(), String> {
    for field in [
        "compilerInfoSha256",
        "resolverSha256",
        "sourceArchiveSha256",
        "sourceFilesSha256",
        "sourceTree",
        "stackExecutableSha256",
        "stackYamlSha256",
        "toolchainSha256",
    ] {
        require_digest(json_member(plan, field)?.string()?, "oracle build plan")?;
    }
    require_git_sha_text(
        json_member(plan, "sourceCommit")?.string()?,
        "oracle source commit",
    )?;
    if json_member(plan, "schemaVersion")?.number()? != 2
        || !json_member(plan, "sourceTreeClean")?.boolean()?
        || !json_member(plan, "packageDigestsComplete")?.boolean()?
        || !json_member(plan, "sourceAcquisitionComplete")?.boolean()?
        || !json_member(plan, "buildOffline")?.boolean()?
        || !json_member(plan, "mutableVcsDependencies")?
            .array()?
            .is_empty()
        || !json_member(plan, "localDependencyEscapes")?
            .array()?
            .is_empty()
        || !json_member(plan, "reviewRequired")?.array()?.is_empty()
        || json_member(plan, "stackVersion")?.string()?.is_empty()
        || json_member(plan, "declaredResolver")?.string()?.is_empty()
        || json_member(plan, "executableTarget")?.string()? != "hell"
        || json_member(plan, "localDependencies")?.array()?.len() != 1
    {
        return Err("oracle build plan violates provenance policy".to_owned());
    }
    let packages = json_member(plan, "packages")?.array()?;
    if packages.is_empty() {
        return Err("oracle build plan contains no dependency packages".to_owned());
    }
    for package in packages {
        let package = package.object()?;
        exact_keys(
            package,
            &[
                "name",
                "providerUrls",
                "retainedPath",
                "sourceChecksumSha256",
                "sourceKind",
                "version",
            ],
        )?;
        if json_member(package, "name")?.string()?.is_empty()
            || json_member(package, "version")?.string()?.is_empty()
            || json_member(package, "sourceKind")?.string()?.is_empty()
        {
            return Err("oracle package identity is incomplete".to_owned());
        }
        require_digest(
            json_member(package, "sourceChecksumSha256")?.string()?,
            "oracle package source checksum",
        )?;
        validate_oracle_retained_path(json_member(package, "retainedPath")?.string()?)?;
        validate_oracle_provider_urls(json_member(package, "providerUrls")?.array()?)?;
    }
    let commands = json_member(plan, "commands")?.array()?;
    if commands.len() < 2 {
        return Err("oracle build plan lacks prefetch and offline build commands".to_owned());
    }
    for command in commands {
        let command = command.object()?;
        exact_keys(command, &["name", "status", "stderrSha256", "stdoutSha256"])?;
        if json_member(command, "name")?.string()?.is_empty()
            || json_member(command, "status")?.number()? != 0
        {
            return Err("oracle build command did not succeed".to_owned());
        }
        for field in ["stderrSha256", "stdoutSha256"] {
            require_digest(
                json_member(command, field)?.string()?,
                "oracle command output",
            )?;
        }
    }
    Ok(())
}

fn verify_source_files(path: &Path, source_tree: &str) -> Result<(), String> {
    let document = parse_json(&read_text(path)?)?;
    let inventory = document.object()?;
    exact_keys(
        inventory,
        &["fileCount", "files", "schemaVersion", "sourceTree"],
    )?;
    let files = json_member(inventory, "files")?.array()?;
    if json_member(inventory, "schemaVersion")?.number()? != 1
        || json_member(inventory, "sourceTree")?.string()? != source_tree
        || json_member(inventory, "fileCount")?.number()?
            != u64::try_from(files.len())
                .map_err(|_| "oracle source inventory is too large".to_owned())?
        || files.is_empty()
    {
        return Err("oracle source inventory identity or count is invalid".to_owned());
    }
    let mut previous = None;
    for file in files {
        let file = file.object()?;
        exact_keys(file, &["path", "sha256"])?;
        let declared = json_member(file, "path")?.string()?;
        let declared_path = Path::new(declared);
        if declared_path.is_absolute()
            || declared_path
                .components()
                .any(|component| !matches!(component, std::path::Component::Normal(_)))
            || declared.contains('\\')
        {
            return Err("oracle source inventory path is not canonical".to_owned());
        }
        require_digest(json_member(file, "sha256")?.string()?, "oracle source file")?;
        if previous.is_some_and(|value: &str| value >= declared) {
            return Err("oracle source inventory is not strictly sorted".to_owned());
        }
        previous = Some(declared);
    }
    Ok(())
}

fn verify_oracle_environment(path: &Path, platform: &str) -> Result<(), String> {
    let document = parse_json(&read_text(path)?)?;
    let environment = document.object()?;
    exact_keys(
        environment,
        &[
            "buildEnvironment",
            "compilerInfoSha256",
            "osBuildSha256",
            "platform",
            "runnerArch",
            "runnerImageIdentitySha256",
            "runnerName",
            "runnerOs",
            "schemaVersion",
            "stackExecutableSha256",
            "stackVersion",
        ],
    )?;
    if json_member(environment, "schemaVersion")?.number()? != 1
        || json_member(environment, "platform")?.string()? != platform
        || json_member(environment, "runnerName")?.string()?.is_empty()
        || json_member(environment, "runnerOs")?.string()?.is_empty()
        || json_member(environment, "runnerArch")?.string()?.is_empty()
        || json_member(environment, "stackVersion")?
            .string()?
            .is_empty()
    {
        return Err("oracle builder environment identity is incomplete".to_owned());
    }
    for field in [
        "compilerInfoSha256",
        "osBuildSha256",
        "runnerImageIdentitySha256",
        "stackExecutableSha256",
    ] {
        require_digest(
            json_member(environment, field)?.string()?,
            "oracle builder environment",
        )?;
    }
    let expected_names = ["GHC_PACKAGE_PATH", "LANG", "LC_ALL", "PATH", "STACK_ROOT"];
    let values = json_member(environment, "buildEnvironment")?.array()?;
    if values.len() != expected_names.len() {
        return Err("oracle builder environment allowlist is incomplete".to_owned());
    }
    for (value, expected_name) in values.iter().zip(expected_names) {
        let value = value.object()?;
        exact_keys(value, &["name", "valueSha256"])?;
        if json_member(value, "name")?.string()? != expected_name {
            return Err("oracle builder environment is not canonically ordered".to_owned());
        }
        require_digest(
            json_member(value, "valueSha256")?.string()?,
            "oracle builder environment value",
        )?;
    }
    Ok(())
}

fn verify_provenance_policy(
    path: &Path,
    record: &BTreeMap<String, JsonValue>,
    environment_field: &str,
    binary_field: &str,
) -> Result<(), String> {
    let document = parse_json(&read_text(path)?)?;
    let policy = document.object()?;
    exact_keys(
        policy,
        &[
            "binarySha256",
            "buildPlanSha256",
            "checks",
            "environmentSha256",
            "failures",
            "networkInventorySha256",
            "reviewFindings",
            "sbomSha256",
            "schemaVersion",
            "sourceCommit",
            "sourceFilesSha256",
            "sourceTree",
            "verdict",
        ],
    )?;
    if json_member(policy, "schemaVersion")?.number()? != 1
        || json_member(policy, "sourceCommit")?.string()?
            != json_member(record, "sourceCommit")?.string()?
        || json_member(policy, "sourceTree")?.string()?
            != json_member(record, "sourceTree")?.string()?
        || json_member(policy, "verdict")?.string()? != "pass"
        || !json_member(policy, "failures")?.array()?.is_empty()
        || !json_member(policy, "reviewFindings")?.array()?.is_empty()
    {
        return Err("oracle provenance policy did not pass exact source evidence".to_owned());
    }
    for field in [
        "buildPlanSha256",
        "networkInventorySha256",
        "sbomSha256",
        "sourceFilesSha256",
    ] {
        require_digest(
            json_member(policy, field)?.string()?,
            "oracle provenance policy",
        )?;
        if json_member(policy, field)?.string()? != json_member(record, field)?.string()? {
            return Err(format!(
                "oracle provenance policy field {field} was substituted"
            ));
        }
    }
    for (policy_field, record_field) in [
        ("environmentSha256", environment_field),
        ("binarySha256", binary_field),
    ] {
        require_digest(
            json_member(policy, policy_field)?.string()?,
            "oracle provenance policy",
        )?;
        if json_member(policy, policy_field)?.string()?
            != json_member(record, record_field)?.string()?
        {
            return Err(format!(
                "oracle provenance policy field {policy_field} was substituted"
            ));
        }
    }
    let checks = json_member(policy, "checks")?.object()?;
    let names = [
        "cleanTree",
        "dependencySourcesContentAddressed",
        "networkInventoryComplete",
        "offlineBuild",
        "sbomComplete",
        "sourceInventoryComplete",
    ];
    exact_keys(checks, &names)?;
    if names
        .into_iter()
        .any(|name| json_member(checks, name).and_then(JsonValue::string) != Ok("pass"))
    {
        return Err("oracle provenance policy contains a non-passing check".to_owned());
    }
    Ok(())
}

fn verify_oracle_cross_digests(
    build_plan_path: &Path,
    sbom_path: &Path,
    network_path: &Path,
) -> Result<(), String> {
    let plan_document = parse_json(&read_text(build_plan_path)?)?;
    let plan = plan_document.object()?;
    let network_document = parse_json(&read_text(network_path)?)?;
    let network = network_document.object()?;
    if json_member(network, "resolverLockSha256")?.string()?
        != json_member(plan, "resolverSha256")?.string()?
    {
        return Err("oracle network inventory resolver was substituted".to_owned());
    }
    let plan_packages = oracle_plan_packages(plan)?;
    let network_packages = oracle_network_packages(network)?;
    let sbom_document = parse_json(&read_text(sbom_path)?)?;
    let sbom_packages = oracle_sbom_packages(sbom_document.object()?)?;
    if plan_packages != network_packages {
        return Err("oracle plan, SBOM, and network package evidence disagree".to_owned());
    }
    verify_oracle_sbom_join(&plan_packages, &sbom_packages)?;
    verify_retained_oracle_packages(build_plan_path, &plan_packages)?;
    verify_oracle_download_join(network, &plan_packages)?;
    Ok(())
}

pub(crate) fn verify_oracle_evidence_documents(
    build_plan_path: &Path,
    sbom_path: &Path,
    network_path: &Path,
) -> Result<(), String> {
    verify_build_plan(build_plan_path)?;
    verify_sbom(sbom_path)?;
    verify_network_inventory(network_path)?;
    verify_oracle_cross_digests(build_plan_path, sbom_path, network_path)
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct OraclePackageEvidence {
    checksum: String,
    retained_path: String,
    provider_urls: Vec<String>,
}

struct OracleAcquisitionEvidence {
    builder: String,
    observed_urls: BTreeSet<String>,
}

fn verify_oracle_acquisition_receipt(
    path: &Path,
    gate: &BTreeMap<String, JsonValue>,
    trust_domain_field: &str,
    run_identity_field: &str,
    expected_packages: &BTreeMap<(String, String), OraclePackageEvidence>,
) -> Result<OracleAcquisitionEvidence, String> {
    let document = parse_json(&read_text(path)?)?;
    let receipt = document.object()?;
    exact_keys(
        receipt,
        &[
            "acquisitionStderrSha256",
            "acquisitionStdoutSha256",
            "assuranceEpochSha256",
            "builder",
            "candidateCommit",
            "observedHttpsAccesses",
            "packageSources",
            "runIdentity",
            "schemaVersion",
            "sourceAcquisitionComplete",
            "trustDomain",
            "unexpectedAccesses",
            "unrecordedAccesses",
        ],
    )?;
    if json_member(receipt, "schemaVersion")?.number()? != 1
        || !json_member(receipt, "sourceAcquisitionComplete")?.boolean()?
        || !json_member(receipt, "unexpectedAccesses")?
            .array()?
            .is_empty()
        || !json_member(receipt, "unrecordedAccesses")?
            .array()?
            .is_empty()
        || json_member(receipt, "candidateCommit")?.string()?
            != json_member(gate, "candidateCommit")?.string()?
        || json_member(receipt, "assuranceEpochSha256")?.string()?
            != json_member(gate, "assuranceEpochSha256")?.string()?
        || json_member(receipt, "trustDomain")?.string()?
            != json_member(gate, trust_domain_field)?.string()?
        || json_member(receipt, "runIdentity")?.string()?
            != json_member(gate, run_identity_field)?.string()?
    {
        return Err("oracle acquisition receipt identity or completeness is invalid".to_owned());
    }
    for field in ["acquisitionStdoutSha256", "acquisitionStderrSha256"] {
        require_digest(
            json_member(receipt, field)?.string()?,
            "oracle acquisition output",
        )?;
    }
    let builder = json_member(receipt, "builder")?.string()?.to_owned();
    if builder.is_empty() {
        return Err("oracle acquisition builder identity is empty".to_owned());
    }
    let observed_urls = strict_oracle_url_set(
        json_member(receipt, "observedHttpsAccesses")?.array()?,
        "oracle acquisition observations",
    )?;
    let packages = oracle_acquisition_packages(receipt)?;
    if &packages != expected_packages {
        return Err("oracle acquisition package sources disagree with the build plan".to_owned());
    }
    verify_retained_oracle_packages(path, &packages)?;
    for url in packages
        .values()
        .flat_map(|package| package.provider_urls.iter())
    {
        if !observed_urls.contains(url) {
            return Err("oracle acquired package lacks an observed provider access".to_owned());
        }
    }
    Ok(OracleAcquisitionEvidence {
        builder,
        observed_urls,
    })
}

fn oracle_acquisition_packages(
    receipt: &BTreeMap<String, JsonValue>,
) -> Result<BTreeMap<(String, String), OraclePackageEvidence>, String> {
    let mut packages = BTreeMap::new();
    for package in json_member(receipt, "packageSources")?.array()? {
        let package = package.object()?;
        exact_keys(
            package,
            &["name", "providerUrls", "retainedPath", "sha256", "version"],
        )?;
        let key = (
            json_member(package, "name")?.string()?.to_owned(),
            json_member(package, "version")?.string()?.to_owned(),
        );
        if key.0.is_empty() || key.1.is_empty() {
            return Err("oracle acquisition package identity is incomplete".to_owned());
        }
        let checksum = json_member(package, "sha256")?.string()?.to_owned();
        require_digest(&checksum, "oracle acquisition package")?;
        let retained_path = json_member(package, "retainedPath")?.string()?.to_owned();
        validate_oracle_retained_path(&retained_path)?;
        let provider_urls =
            validate_oracle_provider_urls(json_member(package, "providerUrls")?.array()?)?;
        let evidence = OraclePackageEvidence {
            checksum,
            retained_path,
            provider_urls,
        };
        if packages.insert(key, evidence).is_some() {
            return Err("oracle acquisition duplicates a package source".to_owned());
        }
    }
    if packages.is_empty() {
        return Err("oracle acquisition retains no package sources".to_owned());
    }
    Ok(packages)
}

fn strict_oracle_url_set(values: &[JsonValue], label: &str) -> Result<BTreeSet<String>, String> {
    if values.is_empty() {
        return Err(format!("{label} is empty"));
    }
    let mut urls = BTreeSet::new();
    let mut previous = None;
    for value in values {
        let url = value.string()?;
        validate_oracle_provider_url(url)?;
        if previous.is_some_and(|prior: &str| prior >= url) || !urls.insert(url.to_owned()) {
            return Err(format!("{label} is not strictly sorted and unique"));
        }
        previous = Some(url);
    }
    Ok(urls)
}

fn oracle_plan_packages(
    plan: &BTreeMap<String, JsonValue>,
) -> Result<BTreeMap<(String, String), OraclePackageEvidence>, String> {
    let mut packages = BTreeMap::new();
    for package in json_member(plan, "packages")?.array()? {
        let package = package.object()?;
        let key = (
            json_member(package, "name")?.string()?.to_owned(),
            json_member(package, "version")?.string()?.to_owned(),
        );
        let evidence = oracle_package_evidence(package, true)?;
        if packages.insert(key, evidence).is_some() {
            return Err("oracle build plan duplicates a package".to_owned());
        }
    }
    Ok(packages)
}

fn oracle_network_packages(
    network: &BTreeMap<String, JsonValue>,
) -> Result<BTreeMap<(String, String), OraclePackageEvidence>, String> {
    let mut packages = BTreeMap::new();
    for package in json_member(network, "retainedPackageSources")?.array()? {
        let package = package.object()?;
        let key = (
            json_member(package, "name")?.string()?.to_owned(),
            json_member(package, "version")?.string()?.to_owned(),
        );
        let evidence = oracle_package_evidence(package, false)?;
        if packages.insert(key, evidence).is_some() {
            return Err("oracle network inventory duplicates a package".to_owned());
        }
    }
    Ok(packages)
}

fn oracle_sbom_packages(
    sbom: &BTreeMap<String, JsonValue>,
) -> Result<BTreeMap<(String, String), OracleSbomPackage>, String> {
    let mut packages = BTreeMap::new();
    for package in json_member(sbom, "packages")?.array()? {
        let package = package.object()?;
        exact_keys(
            package,
            &[
                "checksums",
                "checksumState",
                "downloadLocation",
                "externalRefs",
                "name",
                "retainedPath",
                "versionInfo",
            ],
        )?;
        let checksums = json_member(package, "checksums")?.array()?;
        if checksums.len() != 1 {
            return Err("oracle SBOM package needs exactly one source checksum".to_owned());
        }
        let checksum = checksums[0].object()?;
        exact_keys(checksum, &["algorithm", "checksumValue"])?;
        if json_member(checksum, "algorithm")?.string()? != "SHA256" {
            return Err("oracle SBOM package checksum is not SHA-256".to_owned());
        }
        let key = (
            json_member(package, "name")?.string()?.to_owned(),
            json_member(package, "versionInfo")?.string()?.to_owned(),
        );
        let checksum = json_member(checksum, "checksumValue")?.string()?.to_owned();
        require_digest(&checksum, "oracle SBOM package checksum")?;
        let retained_path = json_member(package, "retainedPath")?.string()?.to_owned();
        validate_oracle_retained_path(&retained_path)?;
        let external_refs = json_member(package, "externalRefs")?.array()?;
        if external_refs.len() != 1
            || json_member(package, "checksumState")?.string()?
                != "collected-from-retained-acquired-source"
        {
            return Err("oracle SBOM package provenance is incomplete".to_owned());
        }
        let external_ref = external_refs[0].object()?;
        exact_keys(external_ref, &["referenceLocator", "referenceType"])?;
        if json_member(external_ref, "referenceType")?.string()? != "hell-rs-stack-resolution"
            || json_member(external_ref, "referenceLocator")?
                .string()?
                .is_empty()
        {
            return Err("oracle SBOM resolution reference is invalid".to_owned());
        }
        let download_location = json_member(package, "downloadLocation")?
            .string()?
            .to_owned();
        validate_oracle_provider_url(&download_location)?;
        let evidence = OracleSbomPackage {
            checksum,
            retained_path,
            download_location,
        };
        if packages.insert(key, evidence).is_some() {
            return Err("oracle SBOM duplicates a package".to_owned());
        }
    }
    Ok(packages)
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct OracleSbomPackage {
    checksum: String,
    retained_path: String,
    download_location: String,
}

fn oracle_package_evidence(
    package: &BTreeMap<String, JsonValue>,
    require_source_kind: bool,
) -> Result<OraclePackageEvidence, String> {
    let common_keys = [
        "name",
        "providerUrls",
        "retainedPath",
        "sourceChecksumSha256",
        "version",
    ];
    if require_source_kind {
        exact_keys(
            package,
            &[
                "name",
                "providerUrls",
                "retainedPath",
                "sourceChecksumSha256",
                "sourceKind",
                "version",
            ],
        )?;
        if json_member(package, "sourceKind")?.string()? != "stack-offline-unpack" {
            return Err("oracle package source kind is not an isolated retained unpack".to_owned());
        }
    } else {
        exact_keys(package, &common_keys)?;
    }
    if json_member(package, "name")?.string()?.is_empty()
        || json_member(package, "version")?.string()?.is_empty()
    {
        return Err("oracle retained package identity is incomplete".to_owned());
    }
    let checksum = json_member(package, "sourceChecksumSha256")?
        .string()?
        .to_owned();
    require_digest(&checksum, "oracle retained package checksum")?;
    let retained_path = json_member(package, "retainedPath")?.string()?.to_owned();
    validate_oracle_retained_path(&retained_path)?;
    let provider_urls =
        validate_oracle_provider_urls(json_member(package, "providerUrls")?.array()?)?;
    Ok(OraclePackageEvidence {
        checksum,
        retained_path,
        provider_urls,
    })
}

fn validate_oracle_retained_path(value: &str) -> Result<(), String> {
    let path = Path::new(value);
    if path.is_absolute()
        || value.contains('\\')
        || path
            .components()
            .any(|component| !matches!(component, std::path::Component::Normal(_)))
        || !path.starts_with("package-sources")
    {
        return Err("oracle retained package path is not canonical".to_owned());
    }
    Ok(())
}

fn validate_oracle_provider_urls(values: &[JsonValue]) -> Result<Vec<String>, String> {
    if values.is_empty() {
        return Err("oracle retained package has no observed provider URL".to_owned());
    }
    let mut urls = Vec::with_capacity(values.len());
    for value in values {
        let url = value.string()?;
        validate_oracle_provider_url(url)?;
        if urls
            .last()
            .is_some_and(|previous: &String| previous.as_str() >= url)
        {
            return Err("oracle provider URLs are not strictly sorted".to_owned());
        }
        urls.push(url.to_owned());
    }
    Ok(urls)
}

fn validate_oracle_provider_url(value: &str) -> Result<(), String> {
    let authority_and_path = value
        .strip_prefix("https://")
        .ok_or_else(|| "oracle provider URL is not HTTPS".to_owned())?;
    let (authority, path) = authority_and_path
        .split_once('/')
        .ok_or_else(|| "oracle provider URL has no absolute path".to_owned())?;
    if authority.is_empty()
        || authority.contains('@')
        || path.is_empty()
        || value.contains('?')
        || value.contains('#')
        || value.chars().any(char::is_whitespace)
    {
        return Err("oracle provider URL is not canonical public HTTPS".to_owned());
    }
    Ok(())
}

fn verify_oracle_sbom_join(
    plan: &BTreeMap<(String, String), OraclePackageEvidence>,
    sbom: &BTreeMap<(String, String), OracleSbomPackage>,
) -> Result<(), String> {
    if plan.len() != sbom.len() {
        return Err("oracle plan and SBOM package sets disagree".to_owned());
    }
    for (key, expected) in plan {
        let observed = sbom
            .get(key)
            .ok_or_else(|| "oracle SBOM omits a retained package".to_owned())?;
        if observed.checksum != expected.checksum
            || observed.retained_path != expected.retained_path
            || expected.provider_urls.first() != Some(&observed.download_location)
        {
            return Err("oracle SBOM package provenance was substituted".to_owned());
        }
    }
    Ok(())
}

fn verify_retained_oracle_packages(
    build_plan_path: &Path,
    packages: &BTreeMap<(String, String), OraclePackageEvidence>,
) -> Result<(), String> {
    let retained_root = build_plan_path
        .parent()
        .ok_or_else(|| "oracle build plan has no retained root".to_owned())?;
    let repository = repository_root()?;
    for package in packages.values() {
        let path = confined_record_path(
            &repository,
            retained_root,
            Path::new(&package.retained_path),
        )?;
        if oracle_retained_directory_digest(&path)? != package.checksum {
            return Err("oracle retained package source digest mismatch".to_owned());
        }
    }
    Ok(())
}

fn oracle_retained_directory_digest(root: &Path) -> Result<String, String> {
    let mut files = Vec::new();
    collect_manifest_files(root, root, &mut files)?;
    if files.is_empty() {
        return Err("oracle retained package source is empty".to_owned());
    }
    files.sort_by(|left, right| left.0.cmp(&right.0));
    let mut manifest = String::new();
    for (path, digest, _) in files {
        writeln!(manifest, "{} {path}", digest.hex()).expect("writing to String cannot fail");
    }
    Ok(sha256_bytes(manifest.as_bytes()).hex())
}

fn verify_oracle_download_join(
    network: &BTreeMap<String, JsonValue>,
    packages: &BTreeMap<(String, String), OraclePackageEvidence>,
) -> Result<(), String> {
    let observed = json_member(network, "recordedDownloads")?
        .array()?
        .iter()
        .map(|download| {
            let download = download.object()?;
            Ok(json_member(download, "url")?.string()?.to_owned())
        })
        .collect::<Result<BTreeSet<_>, String>>()?;
    for url in packages
        .values()
        .flat_map(|package| package.provider_urls.iter())
    {
        if !observed.contains(url) {
            return Err("oracle package provider URL lacks a download observation".to_owned());
        }
    }
    Ok(())
}

fn verify_oracle_comparison(
    path: &Path,
    record: &BTreeMap<String, JsonValue>,
) -> Result<(), String> {
    let document = parse_json(&read_text(path)?)?;
    let comparison = document.object()?;
    exact_keys(
        comparison,
        &[
            "assuranceEpochSha256",
            "binarySha256",
            "buildPlanSha256",
            "candidateCommit",
            "exercisedBinaryBinding",
            "exercisedBinarySha256",
            "firstAcquisitionReceiptSha256",
            "firstBinarySha256",
            "firstBuildReceiptSha256",
            "firstBuilder",
            "firstBuilderTrustDomain",
            "firstEnvironmentSha256",
            "firstProvenancePolicySha256",
            "firstRunIdentity",
            "networkInventorySha256",
            "platform",
            "policyFindings",
            "reproducibility",
            "sbomSha256",
            "schemaVersion",
            "secondBinarySha256",
            "secondAcquisitionReceiptSha256",
            "secondBuildReceiptSha256",
            "secondBuilder",
            "secondBuilderTrustDomain",
            "secondEnvironmentSha256",
            "secondProvenancePolicySha256",
            "secondRunIdentity",
            "semanticFingerprintSha256",
            "sourceCommit",
            "sourceTree",
        ],
    )?;
    if json_member(comparison, "schemaVersion")?.number()? != 1
        || json_member(comparison, "reproducibility")?.string()? != "exact"
        || !json_member(comparison, "exercisedBinaryBinding")?.boolean()?
        || !json_member(comparison, "policyFindings")?
            .array()?
            .is_empty()
    {
        return Err("oracle comparison did not retain an exact clean result".to_owned());
    }
    for field in [
        "assuranceEpochSha256",
        "buildPlanSha256",
        "candidateCommit",
        "exercisedBinarySha256",
        "firstAcquisitionReceiptSha256",
        "firstBinarySha256",
        "firstBuildReceiptSha256",
        "firstEnvironmentSha256",
        "firstProvenancePolicySha256",
        "networkInventorySha256",
        "platform",
        "sbomSha256",
        "secondBinarySha256",
        "secondAcquisitionReceiptSha256",
        "secondBuildReceiptSha256",
        "secondEnvironmentSha256",
        "secondProvenancePolicySha256",
        "semanticFingerprintSha256",
        "sourceCommit",
        "sourceTree",
    ] {
        if json_member(comparison, field)?.string()? != json_member(record, field)?.string()? {
            return Err(format!("oracle comparison field {field} was substituted"));
        }
    }
    Ok(())
}

fn verify_sbom(path: &Path) -> Result<(), String> {
    let document = parse_json(&read_text(path)?)?;
    let sbom = document.object()?;
    let version = json_member(sbom, "spdxVersion")?.string()?;
    let packages = json_member(sbom, "packages")?.array()?;
    if !version.starts_with("SPDX-") || packages.is_empty() {
        return Err("oracle SBOM is empty or is not SPDX".to_owned());
    }
    for package in packages {
        let package = package.object()?;
        for field in ["name", "versionInfo", "downloadLocation", "checksums"] {
            json_member(package, field)?;
        }
        if json_member(package, "checksums")?.array()?.is_empty() {
            return Err("oracle SBOM package lacks checksums".to_owned());
        }
    }
    Ok(())
}

fn verify_network_inventory(path: &Path) -> Result<(), String> {
    let document = parse_json(&read_text(path)?)?;
    let inventory = document.object()?;
    exact_keys(
        inventory,
        &[
            "buildOffline",
            "acquisitionStderrSha256",
            "acquisitionStdoutSha256",
            "networkMode",
            "resolverLockSha256",
            "offlineDependencyStdoutSha256",
            "offlineDependencyStderrSha256",
            "offlineBuildStdoutSha256",
            "offlineBuildStderrSha256",
            "recordedDownloads",
            "retainedPackageSources",
            "schemaVersion",
            "unexpectedEndpoints",
            "unrecordedDownloads",
        ],
    )?;
    if json_member(inventory, "schemaVersion")?.number()? != 2
        || !json_member(inventory, "buildOffline")?.boolean()?
        || json_member(inventory, "networkMode")?.string()?
            != "observed-acquisition-then-isolated-offline-build"
        || json_member(inventory, "recordedDownloads")?
            .array()?
            .is_empty()
        || !json_member(inventory, "unexpectedEndpoints")?
            .array()?
            .is_empty()
        || !json_member(inventory, "unrecordedDownloads")?
            .array()?
            .is_empty()
    {
        return Err("oracle network inventory violates offline-build policy".to_owned());
    }
    for field in [
        "resolverLockSha256",
        "acquisitionStdoutSha256",
        "acquisitionStderrSha256",
        "offlineDependencyStdoutSha256",
        "offlineDependencyStderrSha256",
        "offlineBuildStdoutSha256",
        "offlineBuildStderrSha256",
    ] {
        require_digest(
            json_member(inventory, field)?.string()?,
            "oracle network inventory",
        )?;
    }
    let mut accesses = BTreeSet::new();
    let mut previous_access = None;
    for download in json_member(inventory, "recordedDownloads")?.array()? {
        let download = download.object()?;
        exact_keys(download, &["kind", "url"])?;
        let url = json_member(download, "url")?.string()?;
        if json_member(download, "kind")?.string()? != "observed-https-access" {
            return Err("oracle recorded download has the wrong observation kind".to_owned());
        }
        validate_oracle_provider_url(url)?;
        if previous_access.is_some_and(|previous: &str| previous >= url) {
            return Err("oracle download observations are not strictly sorted".to_owned());
        }
        previous_access = Some(url);
        if !accesses.insert(url) {
            return Err("oracle network inventory duplicates a download observation".to_owned());
        }
    }
    let packages = oracle_network_packages(inventory)?;
    if packages.is_empty() {
        return Err("oracle network inventory retains no package sources".to_owned());
    }
    verify_oracle_download_join(inventory, &packages)?;
    Ok(())
}

#[allow(clippy::too_many_lines)]
fn custody_command(options: &Options) -> Result<String, String> {
    match options.action.as_deref().unwrap_or("verify") {
        "package" => {
            let input = required_path(&options.input, "custody package requires --input")?;
            let output = required_path(&options.output, "custody package requires --output")?;
            let manifest = directory_manifest(input)?;
            write_atomic(output, manifest.as_bytes())?;
            write_digest_sibling(output, sha256_bytes(manifest.as_bytes()))?;
            Ok(format!("wrote deterministic custody manifest {}", output.display()))
        }
        "verify" => {
            let input = required_path(&options.input, "custody verify requires --input")?;
            let policy = required_path(&options.policy, "custody verify requires --policy allowed-signers")?;
            let repository = repository_root()?;
            let custody_policy =
                read_text(&repository.join("compat").join("custody-policy.toml"))?;
            let minimum_copies = assignment_u64(&custody_policy, "minimum_copies")?;
            let minimum_years = assignment_u64(&custody_policy, "minimum_years")?;
            let scrub_interval_days = assignment_u64(&custody_policy, "scrub_interval_days")?;
            for key in [
                "require_encryption_at_rest",
                "require_independent_retrieval",
                "require_object_lock",
                "require_version_id",
            ] {
                require_assignment(&custody_policy, key, "true")?;
            }
            let retained_root = retained_evidence_root(input)?;
            let document = parse_json(&read_text(input)?)?;
            let receipt = document.object()?;
            exact_keys(
                receipt,
                &[
                    "assuranceEpochSha256", "candidateCommit", "copies", "manifestPath",
                    "manifestSha256", "packageRoot", "reviewPath", "reviewSha256",
                    "schemaVersion",
                ],
            )?;
            if json_member(receipt, "schemaVersion")?.number()? != 1 {
                return Err("custody receipt schemaVersion must be 1".to_owned());
            }
            let candidate = json_member(receipt, "candidateCommit")?.string()?;
            require_git_sha_text(candidate, "custody candidate")?;
            let epoch = json_member(receipt, "assuranceEpochSha256")?.string()?;
            require_digest(epoch, "custody epoch")?;
            let manifest_path = confined_record_path(
                &repository,
                retained_root,
                Path::new(json_member(receipt, "manifestPath")?.string()?),
            )?;
            let package_root = confined_record_path(
                &repository,
                retained_root,
                Path::new(json_member(receipt, "packageRoot")?.string()?),
            )?;
            let manifest = read_text(&manifest_path)?;
            let expected_manifest = directory_manifest(&package_root)?;
            if manifest != expected_manifest {
                return Err("custody manifest does not match package contents".to_owned());
            }
            let manifest_digest = sha256_bytes(manifest.as_bytes()).hex();
            if manifest_digest != json_member(receipt, "manifestSha256")?.string()? {
                return Err("custody manifest digest mismatch".to_owned());
            }
            let copies = json_member(receipt, "copies")?.array()?;
            if u64::try_from(copies.len())
                .map_err(|_| "custody copy count exceeds u64".to_owned())?
                < minimum_copies
            {
                return Err("custody policy requires at least two copies".to_owned());
            }
            let mut domains = BTreeSet::new();
            let mut providers = BTreeSet::new();
            let mut retrieval_paths = BTreeSet::new();
            let mut provider_reviewers = BTreeSet::new();
            let mut provider_signer_fingerprints = BTreeSet::new();
            let mut accounts = BTreeSet::new();
            let mut uploader_stable_ids = BTreeSet::new();
            let mut retriever_stable_ids = BTreeSet::new();
            let mut provider_receipt_digests = Vec::new();
            for copy in copies {
                let copy = copy.object()?;
                exact_keys(
                    copy,
                    &[
                        "accountOrTenant", "candidateEpochMatch", "contentSha256", "encryptionAtRest",
                        "innerManifestValid", "objectLock", "objectVersion", "provider",
                        "providerReceiptPath", "providerReceiptSha256", "retentionYears",
                        "retrievedBy", "retrievedPath", "retrievedSha256", "retrieverStableId",
                        "scrubAgeDays", "trustDomain", "uploadProviderReceiptPath",
                        "uploadProviderReceiptSha256", "uploadReceiptPath", "uploadReceiptSha256",
                        "uploadedBy", "uploaderStableId",
                    ],
                )?;
                domains.insert(json_member(copy, "trustDomain")?.string()?.to_owned());
                providers.insert(json_member(copy, "provider")?.string()?.to_owned());
                accounts.insert(json_member(copy, "accountOrTenant")?.string()?.to_owned());
                uploader_stable_ids
                    .insert(json_member(copy, "uploaderStableId")?.string()?.to_owned());
                retriever_stable_ids
                    .insert(json_member(copy, "retrieverStableId")?.string()?.to_owned());
                let retrieved_path = confined_record_path(
                    &repository,
                    retained_root,
                    Path::new(json_member(copy, "retrievedPath")?.string()?),
                )?;
                retrieval_paths.insert(retrieved_path.clone());
                if json_member(copy, "contentSha256")?.string()? != manifest_digest
                    || json_member(copy, "retrievedSha256")?.string()? != manifest_digest
                    || json_member(copy, "retentionYears")?.number()? < minimum_years
                    || !json_member(copy, "objectLock")?.boolean()?
                    || !json_member(copy, "encryptionAtRest")?.boolean()?
                    || !json_member(copy, "innerManifestValid")?.boolean()?
                    || !json_member(copy, "candidateEpochMatch")?.boolean()?
                    || json_member(copy, "scrubAgeDays")?.number()? > scrub_interval_days
                    || json_member(copy, "objectVersion")?.string()?.is_empty()
                    || json_member(copy, "uploadedBy")?.string()?
                        == json_member(copy, "retrievedBy")?.string()?
                    || json_member(copy, "uploaderStableId")?.string()?
                        == json_member(copy, "retrieverStableId")?.string()?
                {
                    return Err("custody copy violates retention, retrieval, or independence policy".to_owned());
                }
                let retrieved = directory_manifest(&retrieved_path)?;
                if retrieved != manifest {
                    return Err("independently retrieved custody content differs".to_owned());
                }
                let provider_path = confined_record_path(
                    &repository,
                    retained_root,
                    Path::new(json_member(copy, "providerReceiptPath")?.string()?),
                )?;
                let provider_bytes = read_regular_file(&provider_path)?;
                let provider_digest = sha256_bytes(&provider_bytes).hex();
                if provider_digest != json_member(copy, "providerReceiptSha256")?.string()? {
                    return Err("provider custody receipt digest mismatch".to_owned());
                }
                let provider_review = verify_review_envelope(&provider_path, policy)?;
                let upload_receipt_path = confined_record_path(
                    &repository,
                    retained_root,
                    Path::new(json_member(copy, "uploadReceiptPath")?.string()?),
                )?;
                let upload_receipt_digest = record_digest(&upload_receipt_path)?;
                if upload_receipt_digest != json_member(copy, "uploadReceiptSha256")?.string()? {
                    return Err("raw custody upload receipt digest mismatch".to_owned());
                }
                verify_custody_upload_receipt(
                    &upload_receipt_path,
                    copy,
                    candidate,
                    epoch,
                    &manifest_digest,
                )?;
                let upload_provider_path = confined_record_path(
                    &repository,
                    retained_root,
                    Path::new(json_member(copy, "uploadProviderReceiptPath")?.string()?),
                )?;
                let upload_provider_digest = record_digest(&upload_provider_path)?;
                if upload_provider_digest
                    != json_member(copy, "uploadProviderReceiptSha256")?.string()?
                {
                    return Err("signed custody upload receipt digest mismatch".to_owned());
                }
                let upload_review = verify_review_envelope(&upload_provider_path, policy)?;
                let copy_digest = custody_copy_core_digest(copy)?;
                if provider_review.role != "custody-provider"
                    || provider_review.candidate_commit != candidate
                    || provider_review.assurance_epoch != epoch
                    || !provider_review.reviewed_artifacts.contains(&manifest_digest)
                    || !provider_review.reviewed_artifacts.contains(&copy_digest)
                    || upload_review.role != "custody-provider"
                    || upload_review.candidate_commit != candidate
                    || upload_review.assurance_epoch != epoch
                    || !upload_review.reviewed_artifacts.contains(&manifest_digest)
                    || !upload_review
                        .reviewed_artifacts
                        .contains(&upload_receipt_digest)
                    || upload_review.subject == provider_review.subject
                    || upload_review.signer_fingerprint == provider_review.signer_fingerprint
                {
                    return Err("provider custody upload/retrieval receipts do not authenticate independent stored evidence".to_owned());
                }
                provider_reviewers.insert((
                    upload_review.subject,
                    upload_review.signer_fingerprint.clone(),
                ));
                provider_signer_fingerprints.insert(upload_review.signer_fingerprint);
                provider_reviewers.insert((
                    provider_review.subject,
                    provider_review.signer_fingerprint.clone(),
                ));
                provider_signer_fingerprints.insert(provider_review.signer_fingerprint);
                provider_receipt_digests.push(upload_provider_digest);
                provider_receipt_digests.push(provider_digest);
            }
            if domains.len() < 2
                || providers.len() < 2
                || accounts.len() < 2
                || retrieval_paths.len() < 2
                || provider_reviewers.len() < 2
                || provider_signer_fingerprints.len() < 2
                || uploader_stable_ids.len() < 2
                || retriever_stable_ids.len() < 2
            {
                return Err("custody copies do not span independent providers, domains, identities, and retrievals".to_owned());
            }
            let review_path = confined_record_path(
                &repository,
                retained_root,
                Path::new(json_member(receipt, "reviewPath")?.string()?),
            )?;
            let review_bytes = read_regular_file(&review_path)?;
            if sha256_bytes(&review_bytes).hex() != json_member(receipt, "reviewSha256")?.string()? {
                return Err("custody review digest mismatch".to_owned());
            }
            let review = verify_authorized_human_review(
                &review_path,
                policy,
                "custody-reviewer",
                candidate,
                "review-packet.json",
            )?;
            if review.role != "custody-reviewer"
                || review.candidate_commit != candidate
                || review.assurance_epoch != epoch
                || !review.reviewed_artifacts.contains(&manifest_digest)
                || !provider_receipt_digests
                    .iter()
                    .all(|digest| review.reviewed_artifacts.contains(digest))
            {
                return Err("custody review binding mismatch".to_owned());
            }
            Ok("verified two-provider immutable custody and independent retrieval".to_owned())
        }
        "upload" | "retrieve" | "scrub" => Err(
            "custody network operation requires an externally configured OIDC provider adapter; no durable-copy state was manufactured"
                .to_owned(),
        ),
        action => Err(format!("unknown custody action {action:?}")),
    }
}

pub(crate) fn verify_retained_custody_receipt(
    input: &Path,
    signer_policy: &Path,
) -> Result<(), String> {
    custody_command(&Options {
        action: Some("verify".to_owned()),
        input: Some(input.to_path_buf()),
        policy: Some(signer_policy.to_path_buf()),
        ..Options::default()
    })
    .map(|_| ())
}

fn retained_evidence_root(path: &Path) -> Result<&Path, String> {
    path.ancestors()
        .find(|ancestor| ancestor.file_name().is_some_and(|name| name == "evidence"))
        .or_else(|| path.parent())
        .ok_or_else(|| {
            format!(
                "retained record {} has no containing directory",
                path.display()
            )
        })
}

fn custody_copy_core_digest(copy: &BTreeMap<String, JsonValue>) -> Result<String, String> {
    let mut core = String::from("{\"schemaVersion\":1");
    for field in [
        "accountOrTenant",
        "candidateEpochMatch",
        "contentSha256",
        "encryptionAtRest",
        "innerManifestValid",
        "objectLock",
        "objectVersion",
        "provider",
        "retentionYears",
        "retrievedBy",
        "retrievedPath",
        "retrieverStableId",
        "retrievedSha256",
        "scrubAgeDays",
        "trustDomain",
        "uploadReceiptSha256",
        "uploadedBy",
        "uploaderStableId",
    ] {
        if crate::assurance_control_mutant_active("custody-retention-omission")
            && matches!(field, "retentionYears" | "uploaderStableId")
        {
            continue;
        }
        core.push(',');
        push_json(&mut core, field);
        core.push(':');
        push_json_value(&mut core, json_member(copy, field)?)?;
    }
    core.push_str("}\n");
    Ok(sha256_bytes(core.as_bytes()).hex())
}

fn verify_custody_upload_receipt(
    path: &Path,
    copy: &BTreeMap<String, JsonValue>,
    candidate: &str,
    epoch: &str,
    manifest_digest: &str,
) -> Result<(), String> {
    let document = parse_json(&read_text(path)?)?;
    let receipt = document.object()?;
    exact_keys(
        receipt,
        &[
            "accountOrTenant",
            "assuranceEpochSha256",
            "bucket",
            "candidateCommit",
            "encryption",
            "manifestSha256",
            "objectLockMode",
            "objects",
            "packageRootSha256",
            "provider",
            "retentionUntil",
            "schemaVersion",
            "trustDomain",
            "uploadedBy",
            "uploaderStableId",
        ],
    )?;
    if json_member(receipt, "schemaVersion")?.number()? != 1
        || json_member(receipt, "candidateCommit")?.string()? != candidate
        || json_member(receipt, "assuranceEpochSha256")?.string()? != epoch
        || json_member(receipt, "manifestSha256")?.string()? != manifest_digest
        || json_member(receipt, "provider")?.string()? != json_member(copy, "provider")?.string()?
        || json_member(receipt, "trustDomain")?.string()?
            != json_member(copy, "trustDomain")?.string()?
        || json_member(receipt, "accountOrTenant")?.string()?
            != json_member(copy, "accountOrTenant")?.string()?
        || json_member(receipt, "uploadedBy")?.string()?
            != json_member(copy, "uploadedBy")?.string()?
        || json_member(receipt, "uploaderStableId")?.string()?
            != json_member(copy, "uploaderStableId")?.string()?
        || json_member(receipt, "objectLockMode")?.string()? != "COMPLIANCE"
        || json_member(receipt, "encryption")?.string()? != "aws:kms"
        || json_member(receipt, "bucket")?.string()?.is_empty()
        || json_member(receipt, "objects")?.array()?.is_empty()
    {
        return Err("custody upload receipt identity or immutable metadata mismatch".to_owned());
    }
    for field in [
        "assuranceEpochSha256",
        "manifestSha256",
        "packageRootSha256",
    ] {
        require_digest(
            json_member(receipt, field)?.string()?,
            "custody upload receipt",
        )?;
    }
    validate_utc_timestamp(json_member(receipt, "retentionUntil")?.string()?)?;
    let mut object_digests = BTreeSet::new();
    for object in json_member(receipt, "objects")?.array()? {
        let object = object.object()?;
        exact_keys(
            object,
            &["checksumSha256Base64", "key", "sha256", "version"],
        )?;
        let digest = json_member(object, "sha256")?.string()?;
        require_digest(digest, "custody upload object")?;
        if json_member(object, "key")?.string()? != digest
            || json_member(object, "checksumSha256Base64")?
                .string()?
                .is_empty()
            || json_member(object, "version")?.string()?.is_empty()
            || !object_digests.insert(digest)
        {
            return Err("custody upload object identity is invalid or duplicated".to_owned());
        }
    }
    Ok(())
}

fn review_packet(root: &Path, options: &Options) -> Result<String, String> {
    let output = required_path(&options.output, "review-packet requires --output")?;
    let (_, epoch) = epoch(root)?;
    if let (Some(input), Some(role), Some(decision)) = (
        options.input.as_deref(),
        options.role.as_deref(),
        options.decision.as_deref(),
    ) {
        return signable_review_packet(root, options, input, role, decision, output, &epoch);
    }
    let applicability = sha256_bytes(applicability_json(true).as_bytes()).hex();
    let json = format!(
        "{{\n  \"schemaVersion\": 1,\n  \"candidateCommit\": {},\n  \"assuranceEpochSha256\": \"{}\",\n  \"applicabilityCatalogSha256\": \"{}\",\n  \"decisionQuestions\": [\"artifact authenticity\", \"native provenance\", \"claim applicability\", \"semantic sufficiency\", \"normalizer safety\", \"divergence acceptability\", \"durable custody\", \"reviewer independence\", \"residual risk\"],\n  \"state\": \"requires-human-judgment\"\n}}\n",
        json_string(git_output(root, &["rev-parse", "HEAD"])?.trim()),
        epoch.hex(),
        applicability
    );
    write_atomic(output, json.as_bytes())?;
    write_digest_sibling(output, sha256_bytes(json.as_bytes()))?;
    Ok(format!(
        "wrote content-addressed review packet {}",
        output.display()
    ))
}

fn signable_review_packet(
    root: &Path,
    options: &Options,
    input: &Path,
    role: &str,
    decision: &str,
    output: &Path,
    epoch: &Digest,
) -> Result<String, String> {
    let (reviewer, issued_at, authorization) =
        signable_review_identity(root, options, input, role)?;
    if !reviewer.starts_with(&format!("{role}:")) {
        return Err("reviewer identity does not match packet role".to_owned());
    }
    validate_utc_timestamp(&issued_at)?;
    if role == "artifact-trust-reviewer" {
        let policy = required_path(
            &options.policy,
            "artifact trust review packet requires --policy",
        )?;
        let primary = parse_acquisition_receipt_state(&input.join("receipt-primary.json"), true)?;
        let independent =
            parse_acquisition_receipt_state(&input.join("receipt-independent.json"), true)?;
        verify_artifact_receipt_attestations(input, policy, &primary, &independent)?;
    }
    let source = git_output(root, &["rev-parse", "HEAD"])?;
    let loaded_findings = load_review_packet_findings(
        root,
        options,
        input,
        role,
        source.trim(),
        epoch,
        authorization,
    )?;
    let mut findings = loaded_findings.findings;
    if role == "artifact-trust-reviewer" {
        add_required_artifact_exception_finding(input, &mut findings)?;
    }
    let mut findings_json = String::new();
    push_json_value(&mut findings_json, &findings)?;
    let mut artifacts = if matches!(
        options.category.as_deref(),
        Some("collection-activation-author" | "collection-activation-final")
    ) {
        collection_activation_review_artifacts(input, role)?
    } else {
        review_packet_artifacts(input, role)?
    };
    if let Some(authorization) = authorization
        && !artifacts.insert(record_digest(authorization)?)
    {
        return Err("review authorization duplicates a reviewed artifact".to_owned());
    }
    if let Some(path) = options.findings.as_deref()
        && !artifacts.insert(record_digest(path)?)
    {
        return Err("review findings duplicate a reviewed artifact".to_owned());
    }
    artifacts.extend(loaded_findings.bindings);
    let findings_sha256 = validate_review_findings(&findings, false, &artifacts)?;
    let reviewed_artifacts = artifacts
        .iter()
        .map(|artifact| json_string(artifact))
        .collect::<Vec<_>>()
        .join(",");
    let (claim_groups, claim_group_bindings) =
        if options.category.as_deref() == Some("claim-groups") {
            if !matches!(role, "claim-reviewer" | "review-graph-reviewer") {
                return Err("claim-group packet requires a claim or graph reviewer role".to_owned());
            }
            reviewed_claim_groups_json(input, source.trim(), &epoch.hex())?
        } else if role == "claim-reviewer"
            && options.category.as_deref() != Some("collection-activation-final")
        {
            reviewed_finalized_claim_groups_json(input, source.trim(), &epoch.hex())?
        } else {
            (String::new(), BTreeMap::new())
        };
    let review_id = review_statement_id(&ReviewStatementIdentity {
        candidate: source.trim(),
        epoch: &epoch.hex(),
        role,
        reviewer: &reviewer,
        decision,
        issued_at: &issued_at,
        artifacts: &artifacts,
        claim_groups: &claim_group_bindings,
        findings_sha256: &findings_sha256,
    });
    let group_field = if claim_groups.is_empty() {
        String::new()
    } else {
        format!(",\"reviewedClaimGroups\":[{claim_groups}]")
    };
    let schema_version = if group_field.is_empty() { 1 } else { 2 };
    let json = format!(
        "{{\"schemaVersion\":{schema_version},\"reviewId\":{},\"role\":{},\"reviewer\":{},\"decision\":{},\"candidateCommit\":{},\"assuranceEpochSha256\":{},\"reviewedArtifacts\":[{reviewed_artifacts}]{group_field},\"distinctSubjects\":1,\"independenceViolations\":[],\"findings\":{findings_json},\"issuedAt\":{}}}\n",
        json_string(&review_id),
        json_string(role),
        json_string(&reviewer),
        json_string(decision),
        json_string(source.trim()),
        json_string(&epoch.hex()),
        json_string(&issued_at)
    );
    write_atomic(output, json.as_bytes())?;
    write_digest_sibling(output, sha256_bytes(json.as_bytes()))?;
    Ok(format!("wrote signable review packet {}", output.display()))
}

struct LoadedReviewFindings {
    findings: JsonValue,
    bindings: BTreeSet<String>,
}

fn load_review_packet_findings(
    root: &Path,
    options: &Options,
    input: &Path,
    role: &str,
    source: &str,
    epoch: &Digest,
    authorization: Option<&Path>,
) -> Result<LoadedReviewFindings, String> {
    let Some(path) = options.findings.as_deref() else {
        return Ok(LoadedReviewFindings {
            findings: JsonValue::Array(Vec::new()),
            bindings: BTreeSet::new(),
        });
    };
    let document = parse_json(&read_text(path)?)?;
    let document = document.object()?;
    let schema_version = json_member(document, "schemaVersion")?.number()?;
    exact_keys(
        document,
        if schema_version == 3 {
            &[
                "acquisitionPackageSha256",
                "assuranceEpochSha256",
                "authorizationSha256",
                "candidateCommit",
                "findings",
                "reviewedArtifacts",
                "reviewSubjectSha256",
                "role",
                "schemaVersion",
                "workflowBlobSha256",
                "workflowPath",
            ]
        } else {
            &[
                "assuranceEpochSha256",
                "candidateCommit",
                "findings",
                "role",
                "schemaVersion",
            ]
        },
    )?;
    if !matches!(schema_version, 1 | 3)
        || json_member(document, "candidateCommit")?.string()? != source
        || json_member(document, "assuranceEpochSha256")?.string()? != epoch.hex()
        || json_member(document, "role")?.string()? != role
    {
        return Err("review findings do not bind the candidate, epoch, and role".to_owned());
    }
    let mut bindings = BTreeSet::new();
    if schema_version == 3 {
        bindings = verify_authorized_review_findings(
            document,
            root,
            input,
            role,
            source,
            epoch,
            authorization,
        )?;
    }
    Ok(LoadedReviewFindings {
        findings: json_member(document, "findings")?.clone(),
        bindings,
    })
}

fn verify_authorized_review_findings(
    document: &BTreeMap<String, JsonValue>,
    root: &Path,
    input: &Path,
    role: &str,
    source: &str,
    epoch: &Digest,
    authorization: Option<&Path>,
) -> Result<BTreeSet<String>, String> {
    let mut bindings = BTreeSet::new();
    for field in ["authorizationSha256", "reviewSubjectSha256"] {
        let digest = json_member(document, field)?.string()?.to_owned();
        require_digest(&digest, "authorized findings binding")?;
        bindings.insert(digest);
    }
    let authorization = authorization
        .ok_or_else(|| "authorized findings require retained review authorization".to_owned())?;
    let subject_path = input.join("artifact-findings.subject.json");
    if json_member(document, "authorizationSha256")?.string()? != record_digest(authorization)?
        || json_member(document, "reviewSubjectSha256")?.string()? != record_digest(&subject_path)?
    {
        return Err("authorized findings do not bind their exact subject and approval".to_owned());
    }
    let subject = parse_json(&read_text(&subject_path)?)?;
    let subject = subject.object()?;
    verify_review_findings_document(subject, root, input, source, &epoch.hex(), role)?;
    if json_member(document, "acquisitionPackageSha256")?.string()?
        != json_member(subject, "acquisitionPackageSha256")?.string()?
        || json_member(document, "workflowPath")?.string()?
            != json_member(subject, "workflowPath")?.string()?
        || json_member(document, "workflowBlobSha256")?.string()?
            != json_member(subject, "workflowBlobSha256")?.string()?
        || exact_reviewed_artifact_set(document)? != exact_reviewed_artifact_set(subject)?
    {
        return Err("authorized findings broaden the reviewed acquisition subject".to_owned());
    }
    Ok(bindings)
}

fn signable_review_identity<'a>(
    root: &Path,
    options: &'a Options,
    input: &Path,
    role: &str,
) -> Result<(String, String, Option<&'a Path>), String> {
    let evidence_role = matches!(
        role,
        "artifact-trust-reviewer"
            | "claim-author"
            | "claim-reviewer"
            | "custody-reviewer"
            | "normalizer-reviewer"
            | "platform-reviewer"
            | "promotion-approver"
            | "divergence-reviewer"
            | "divergence-platform-reviewer"
            | "divergence-implementation-reviewer"
            | "divergence-product-reviewer"
            | "divergence-security-reviewer"
            | "mutation-reviewer"
            | "regression-reviewer"
            | "residual-risk-reviewer"
            | "review-graph-reviewer"
    );
    let authorization = evidence_role
        .then(|| {
            required_path(
                &options.from,
                "evidence review packet requires --from authorization record",
            )
        })
        .transpose()?;
    let identity = if options.github_dispatch_inputs {
        match role {
            "artifact-trust-reviewer"
            | "claim-author"
            | "claim-reviewer"
            | "custody-reviewer"
            | "normalizer-reviewer"
            | "platform-reviewer"
            | "divergence-reviewer"
            | "divergence-platform-reviewer"
            | "divergence-implementation-reviewer"
            | "divergence-product-reviewer"
            | "divergence-security-reviewer"
            | "mutation-reviewer"
            | "regression-reviewer"
            | "residual-risk-reviewer"
            | "review-graph-reviewer" => evidence_review_identity(
                root,
                role,
                input,
                authorization.ok_or_else(|| "evidence authorization is absent".to_owned())?,
            )?,
            "promotion-approver" => promotion_review_identity(
                root,
                input,
                authorization.ok_or_else(|| "promotion authorization is absent".to_owned())?,
            )?,
            _ => return Err("structured dispatch does not support this review role".to_owned()),
        }
    } else {
        (
            std::env::var("HELL_REVIEWER_ID").map_err(|_| {
                "HELL_REVIEWER_ID is required for a signable review packet".to_owned()
            })?,
            std::env::var("HELL_REVIEW_ISSUED_AT").map_err(|_| {
                "HELL_REVIEW_ISSUED_AT is required for a signable review packet".to_owned()
            })?,
        )
    };
    Ok((identity.0, identity.1, authorization))
}

fn promotion_review_identity(
    root: &Path,
    proposal: &Path,
    authorization: &Path,
) -> Result<(String, String), String> {
    let candidate = git_output(root, &["rev-parse", "HEAD"])?;
    let candidate = candidate.trim();
    let (_, epoch) = epoch(root)?;
    let subject = proposal
        .parent()
        .ok_or_else(|| "promotion proposal has no directory".to_owned())?
        .join("promotion-approval-subject.json");
    verify_promotion_approval_subject(&subject, proposal, candidate, &epoch.hex())?;
    let (account_id, _, reviewed_at, _, _) =
        verify_review_authorization(authorization, "promotion-approver", candidate, &subject)?;
    Ok((
        format!("promotion-approver:github-account-{account_id}"),
        reviewed_at,
    ))
}

type ClaimGroupBinding = (String, String, String);
type ReviewedClaimGroups = BTreeMap<String, ClaimGroupBinding>;

fn reviewed_finalized_claim_groups_json(
    input: &Path,
    candidate: &str,
    epoch: &str,
) -> Result<(String, ReviewedClaimGroups), String> {
    let cells = finalized_claim_cells(input)?;
    let document = parse_json(&read_text(input)?)?;
    let details = document.object()?;
    if json_member(details, "candidateSourceCommit")?.string()? != candidate
        || json_member(details, "assuranceEpochSha256")?.string()? != epoch
    {
        return Err("finalized claim review identity is stale".to_owned());
    }
    let review_set_sha256 = finalized_claim_review_set_sha256(input, details)?;
    let mut grouped = BTreeMap::<String, Vec<&FinalizedClaimCell>>::new();
    for cell in &cells {
        grouped
            .entry(claim_decision_group_id_fields(
                &cell.builtin,
                &cell.dimension,
                &cell.profile,
                &cell.platform,
            )?)
            .or_default()
            .push(cell);
    }
    render_finalized_reviewed_claim_groups(&grouped, &review_set_sha256)
}

fn finalized_claim_review_set_sha256(
    input: &Path,
    details: &BTreeMap<String, JsonValue>,
) -> Result<String, String> {
    let repository = repository_root()?;
    let retained_root = retained_evidence_root(input)?;
    let decisions_path = confined_record_path(
        &repository,
        retained_root,
        Path::new(json_member(details, "applicabilityDecisionsPath")?.string()?),
    )?;
    let decisions = parse_json(&read_text(&decisions_path)?)?;
    let decisions = decisions.object()?;
    let mut digests = [
        record_digest(input)?,
        json_member(details, "sourceCoverageSha256")?
            .string()?
            .to_owned(),
        json_member(details, "applicabilityDecisionsSha256")?
            .string()?
            .to_owned(),
        json_member(decisions, "authoredDecisionsSha256")?
            .string()?
            .to_owned(),
    ];
    digests.sort();
    canonical_json_digest(&JsonValue::Array(
        digests.into_iter().map(JsonValue::String).collect(),
    ))
}

fn render_finalized_reviewed_claim_groups(
    groups: &BTreeMap<String, Vec<&FinalizedClaimCell>>,
    review_set_sha256: &str,
) -> Result<(String, ReviewedClaimGroups), String> {
    let mut output = String::new();
    let mut bindings = BTreeMap::new();
    for (index, (group_id, cells)) in groups.iter().enumerate() {
        let mut keys = cells
            .iter()
            .map(|cell| {
                (
                    cell.builtin.clone(),
                    cell.dimension.clone(),
                    cell.platform.clone(),
                )
            })
            .collect::<Vec<_>>();
        keys.sort();
        let cell_set_sha256 = claim_decision_cell_set_sha256(&keys)?;
        let evidence_set_sha256 = finalized_claim_evidence_set_sha256(cells)?;
        if index != 0 {
            output.push(',');
        }
        let group = JsonValue::Object(BTreeMap::from([
            ("groupId".to_owned(), JsonValue::String(group_id.clone())),
            (
                "cellSetSha256".to_owned(),
                JsonValue::String(cell_set_sha256.clone()),
            ),
            (
                "evidenceSetSha256".to_owned(),
                JsonValue::String(evidence_set_sha256.clone()),
            ),
            (
                "reviewSetSha256".to_owned(),
                JsonValue::String(review_set_sha256.to_owned()),
            ),
        ]));
        push_json_value(&mut output, &group)?;
        bindings.insert(
            group_id.clone(),
            (
                cell_set_sha256,
                evidence_set_sha256,
                review_set_sha256.to_owned(),
            ),
        );
    }
    if bindings.is_empty() {
        return Err("finalized claim review has no exact claim groups".to_owned());
    }
    Ok((output, bindings))
}

fn finalized_claim_evidence_set_sha256(cells: &[&FinalizedClaimCell]) -> Result<String, String> {
    let mut records = Vec::with_capacity(cells.len());
    for cell in cells {
        records.push(JsonValue::Object(BTreeMap::from([
            (
                "builtin".to_owned(),
                JsonValue::String(cell.builtin.clone()),
            ),
            (
                "dimension".to_owned(),
                JsonValue::String(cell.dimension.clone()),
            ),
            (
                "platform".to_owned(),
                JsonValue::String(cell.platform.clone()),
            ),
            (
                "applicability".to_owned(),
                JsonValue::String(cell.applicability.clone()),
            ),
            (
                "proposedStatus".to_owned(),
                JsonValue::String(cell.proposed_status.clone()),
            ),
            (
                "applicabilityDecisionSha256".to_owned(),
                cell.applicability_decision_sha256
                    .clone()
                    .map_or(JsonValue::Null, JsonValue::String),
            ),
            (
                "evidenceRefSha256".to_owned(),
                JsonValue::Array(
                    cell.evidence_refs
                        .iter()
                        .map(|reference| JsonValue::String(reference.sha256.clone()))
                        .collect(),
                ),
            ),
            (
                "normalizerIds".to_owned(),
                JsonValue::Array(
                    cell.normalizer_ids
                        .iter()
                        .cloned()
                        .map(JsonValue::String)
                        .collect(),
                ),
            ),
            (
                "normalizerApplicationRefs".to_owned(),
                JsonValue::Array(
                    cell.normalizer_application_refs
                        .iter()
                        .cloned()
                        .map(JsonValue::String)
                        .collect(),
                ),
            ),
            (
                "obligations".to_owned(),
                JsonValue::Array(
                    cell.obligations
                        .iter()
                        .cloned()
                        .map(JsonValue::String)
                        .collect(),
                ),
            ),
            (
                "divergenceRecordRef".to_owned(),
                cell.divergence_record_ref
                    .clone()
                    .map_or(JsonValue::Null, JsonValue::String),
            ),
        ])));
    }
    canonical_json_digest(&JsonValue::Array(records))
}

fn reviewed_claim_groups_json(
    input: &Path,
    candidate: &str,
    epoch: &str,
) -> Result<(String, ReviewedClaimGroups), String> {
    let document = parse_json(&read_text(input)?)?;
    let manifest = document.object()?;
    exact_keys(
        manifest,
        &[
            "assuranceEpochSha256",
            "candidateSourceCommit",
            "claimGroups",
            "schemaVersion",
        ],
    )?;
    if json_member(manifest, "schemaVersion")?.number()? != 1
        || json_member(manifest, "candidateSourceCommit")?.string()? != candidate
        || json_member(manifest, "assuranceEpochSha256")?.string()? != epoch
    {
        return Err("claim-group manifest identity is stale".to_owned());
    }
    let claim_groups = json_member(manifest, "claimGroups")?;
    let groups = parse_reviewed_claim_groups(claim_groups)?;
    let bindings = reviewed_claim_group_bindings(claim_groups)?;
    let mut output = String::new();
    for (index, group) in groups.iter().enumerate() {
        if index != 0 {
            output.push(',');
        }
        push_json_value(&mut output, group)?;
    }
    Ok((output, bindings))
}

fn parse_reviewed_claim_groups(value: &JsonValue) -> Result<Vec<JsonValue>, String> {
    let values = value.array()?;
    if values.is_empty() {
        return Err("reviewed claim groups must not be empty".to_owned());
    }
    let mut groups = Vec::with_capacity(values.len());
    let mut prior = None;
    for value in values {
        let group = value.object()?;
        exact_keys(
            group,
            &[
                "cellSetSha256",
                "evidenceSetSha256",
                "groupId",
                "reviewSetSha256",
            ],
        )?;
        let group_id = json_member(group, "groupId")?.string()?;
        if group_id.is_empty()
            || group_id.chars().any(|character| {
                !(character.is_ascii_alphanumeric() || matches!(character, '-' | '.' | '_' | '/'))
            })
            || prior.is_some_and(|previous: &str| previous >= group_id)
        {
            return Err(
                "reviewed claim groups are not canonically identified and sorted".to_owned(),
            );
        }
        for field in ["cellSetSha256", "evidenceSetSha256", "reviewSetSha256"] {
            require_digest(json_member(group, field)?.string()?, "reviewed claim group")?;
        }
        prior = Some(group_id);
        groups.push(value.clone());
    }
    Ok(groups)
}

fn reviewed_claim_group_bindings(value: &JsonValue) -> Result<ReviewedClaimGroups, String> {
    let groups = parse_reviewed_claim_groups(value)?;
    let mut bindings = BTreeMap::new();
    for group in groups {
        let group = group.object()?;
        let identity = json_member(group, "groupId")?.string()?.to_owned();
        let binding = (
            json_member(group, "cellSetSha256")?.string()?.to_owned(),
            json_member(group, "evidenceSetSha256")?
                .string()?
                .to_owned(),
            json_member(group, "reviewSetSha256")?.string()?.to_owned(),
        );
        if bindings.insert(identity, binding).is_some() {
            return Err("reviewed claim groups repeat a group ID".to_owned());
        }
    }
    Ok(bindings)
}

struct ReviewStatementIdentity<'a> {
    candidate: &'a str,
    epoch: &'a str,
    role: &'a str,
    reviewer: &'a str,
    decision: &'a str,
    issued_at: &'a str,
    artifacts: &'a BTreeSet<String>,
    claim_groups: &'a ReviewedClaimGroups,
    findings_sha256: &'a str,
}

fn review_statement_id(review: &ReviewStatementIdentity<'_>) -> String {
    let mut identity = String::new();
    for field in [
        review.candidate,
        review.epoch,
        review.role,
        review.reviewer,
        review.decision,
        review.issued_at,
        review.findings_sha256,
    ] {
        identity.push_str(field);
        identity.push('\n');
    }
    for artifact in review.artifacts {
        identity.push_str(artifact);
        identity.push('\n');
    }
    for (group, (cells, evidence, reviews)) in review.claim_groups {
        for field in [group, cells, evidence, reviews] {
            identity.push_str(field);
            identity.push('\n');
        }
    }
    sha256_bytes(identity.as_bytes()).hex()
}

#[cfg(test)]
pub(crate) fn clean_review_statement_id(
    candidate: &str,
    epoch: &str,
    role: &str,
    reviewer: &str,
    issued_at: &str,
    artifacts: &BTreeSet<String>,
) -> String {
    review_statement_id(&ReviewStatementIdentity {
        candidate,
        epoch,
        role,
        reviewer,
        decision: "accept",
        issued_at,
        artifacts,
        claim_groups: &BTreeMap::new(),
        findings_sha256: &sha256_bytes(b"[]\n").hex(),
    })
}

fn add_required_artifact_exception_finding(
    input: &Path,
    findings: &mut JsonValue,
) -> Result<(), String> {
    let attestation_path = input.join("attestation-verification.json");
    let attestation = parse_json(&read_text(&attestation_path)?)?;
    if json_member(attestation.object()?, "state")?.string()? == "verified" {
        return Ok(());
    }
    let evidence_sha256 = record_digest(&attestation_path)?;
    let JsonValue::Array(values) = findings else {
        return Err("review findings must be an array".to_owned());
    };
    let already_present = values.iter().any(|finding| {
        finding.object().is_ok_and(|finding| {
            json_member(finding, "category").and_then(JsonValue::string)
                == Ok("ArtifactAuthenticity")
                && json_member(finding, "disposition").and_then(JsonValue::string) == Ok("Accepted")
                && json_member(finding, "evidenceSha256")
                    .and_then(JsonValue::array)
                    .is_ok_and(|evidence| {
                        evidence
                            .iter()
                            .any(|digest| digest.string() == Ok(&evidence_sha256))
                    })
        })
    });
    if !already_present {
        let mut finding = BTreeMap::from([
            (
                "category".to_owned(),
                JsonValue::String("ArtifactAuthenticity".to_owned()),
            ),
            (
                "disposition".to_owned(),
                JsonValue::String("FollowUpRequired".to_owned()),
            ),
            (
                "evidenceSha256".to_owned(),
                JsonValue::Array(vec![JsonValue::String(evidence_sha256)]),
            ),
            (
                "issue".to_owned(),
                JsonValue::String("review-required:unavailable-attestation".to_owned()),
            ),
            (
                "statement".to_owned(),
                JsonValue::String(
                    "the unavailable upstream attestation requires an external authorized decision"
                        .to_owned(),
                ),
            ),
        ]);
        let finding_id = canonical_json_digest(&JsonValue::Object(finding.clone()))?;
        finding.insert("findingId".to_owned(), JsonValue::String(finding_id));
        values.push(JsonValue::Object(finding));
        values.sort_by(|left, right| {
            let left = left
                .object()
                .and_then(|value| json_member(value, "findingId"))
                .and_then(JsonValue::string)
                .unwrap_or("");
            let right = right
                .object()
                .and_then(|value| json_member(value, "findingId"))
                .and_then(JsonValue::string)
                .unwrap_or("");
            left.cmp(right)
        });
    }
    Ok(())
}

fn artifact_review_exception_required(path: &Path, role: &str) -> Result<bool, String> {
    if role != "artifact-trust-reviewer" {
        return Ok(false);
    }
    let directory = path
        .parent()
        .ok_or_else(|| "artifact trust subject has no acquisition directory".to_owned())?;
    let document = parse_json(&read_text(path)?)?;
    verify_artifact_exception_findings(
        directory,
        json_member(document.object()?, "findings")?.array()?,
    )
}

fn verify_artifact_exception_findings(
    directory: &Path,
    findings: &[JsonValue],
) -> Result<bool, String> {
    let attestation_path = directory.join("attestation-verification.json");
    let attestation = parse_json(&read_text(&attestation_path)?)?;
    let state = json_member(attestation.object()?, "state")?.string()?;
    let exception_required = match state {
        "verified" => false,
        "unavailable-reviewed" => true,
        _ => return Err("artifact attestation has an unsupported review state".to_owned()),
    };
    if findings.is_empty() {
        return if exception_required {
            Err("unavailable artifact attestation lacks its required finding".to_owned())
        } else {
            Ok(false)
        };
    }
    if !exception_required {
        return Err("verified artifact attestation has an invented exception finding".to_owned());
    }
    if findings.len() != 1 {
        return Err("artifact trust subject has an invalid exception finding set".to_owned());
    }
    let finding = findings[0].object()?;
    if json_member(finding, "category")?.string()? != "ArtifactAuthenticity"
        || json_member(finding, "disposition")?.string()? != "FollowUpRequired"
        || json_member(finding, "issue")?.string()? != "review-required:unavailable-attestation"
    {
        return Err(
            "artifact trust subject exception is not the unavailable attestation".to_owned(),
        );
    }
    let evidence_sha256 = record_digest(&attestation_path)?;
    if !json_member(finding, "evidenceSha256")?
        .array()?
        .iter()
        .any(|digest| digest.string() == Ok(&evidence_sha256))
    {
        return Err("artifact exception does not bind the retained attestation".to_owned());
    }
    Ok(true)
}

fn review_findings_command(root: &Path, options: &Options) -> Result<String, String> {
    let action = options.action.as_deref().unwrap_or("prepare");
    let input = required_path(&options.input, "review-findings requires --input")?;
    let output = required_path(&options.output, "review-findings requires --output")?;
    let candidate = git_output(root, &["rev-parse", "HEAD"])?;
    let (_, epoch) = epoch(root)?;
    match action {
        "prepare" => {
            let mut findings = JsonValue::Array(Vec::new());
            add_required_artifact_exception_finding(input, &mut findings)?;
            write_artifact_review_findings_document(
                output,
                root,
                input,
                candidate.trim(),
                &epoch.hex(),
                "artifact-trust-reviewer",
                &findings,
            )?;
            Ok(format!(
                "wrote deterministic artifact findings subject {}",
                output.display()
            ))
        }
        "accept" => {
            accept_review_findings(root, options, input, output, candidate.trim(), &epoch.hex())
        }
        _ => Err("review-findings action must be prepare or accept".to_owned()),
    }
}

fn accept_review_findings(
    root: &Path,
    options: &Options,
    input: &Path,
    output: &Path,
    candidate: &str,
    epoch: &str,
) -> Result<String, String> {
    let authorization = required_path(
        &options.from,
        "review-findings accept requires --from authorization",
    )?;
    let document = parse_json(&read_text(input)?)?;
    let document = document.object()?;
    verify_review_findings_document(
        document,
        root,
        input
            .parent()
            .ok_or_else(|| "artifact findings subject has no acquisition directory".to_owned())?,
        candidate,
        epoch,
        "artifact-trust-reviewer",
    )?;
    let (account_id, _, _, rationale, exception_issue) =
        verify_review_authorization(authorization, "artifact-trust-reviewer", candidate, input)?;
    let mut findings = json_member(document, "findings")?.clone();
    authorize_artifact_findings(
        &mut findings,
        account_id,
        &rationale,
        exception_issue.as_deref(),
    )?;
    write_authorized_review_findings_document(&AuthorizedFindingsDocument {
        output,
        candidate,
        epoch,
        role: "artifact-trust-reviewer",
        findings: &findings,
        acquisition_package_sha256: json_member(document, "acquisitionPackageSha256")?.string()?,
        reviewed_artifacts: json_member(document, "reviewedArtifacts")?,
        workflow_path: json_member(document, "workflowPath")?.string()?,
        workflow_blob_sha256: json_member(document, "workflowBlobSha256")?.string()?,
        review_subject_sha256: &record_digest(input)?,
        authorization_sha256: &record_digest(authorization)?,
    })?;
    Ok(format!(
        "wrote authorized artifact findings decision {}",
        output.display()
    ))
}

fn authorize_artifact_findings(
    findings: &mut JsonValue,
    account_id: u64,
    rationale: &str,
    exception_issue: Option<&str>,
) -> Result<(), String> {
    let JsonValue::Array(values) = findings else {
        return Err("artifact findings subject is not an array".to_owned());
    };
    for finding in values.iter_mut() {
        let JsonValue::Object(finding) = finding else {
            return Err("artifact finding is not an object".to_owned());
        };
        if json_member(finding, "category")?.string()? != "ArtifactAuthenticity"
            || json_member(finding, "disposition")?.string()? != "FollowUpRequired"
        {
            return Err("artifact findings subject contains a non-waivable item".to_owned());
        }
        finding.insert(
            "disposition".to_owned(),
            JsonValue::String("Accepted".to_owned()),
        );
        finding.insert(
            "issue".to_owned(),
            exception_issue.map_or(JsonValue::Null, |issue| JsonValue::String(issue.to_owned())),
        );
        finding.insert(
            "statement".to_owned(),
            JsonValue::String(format!(
                "authorized stable account {account_id}: {rationale}"
            )),
        );
        finding.remove("findingId");
        let finding_id = canonical_json_digest(&JsonValue::Object(finding.clone()))?;
        finding.insert("findingId".to_owned(), JsonValue::String(finding_id));
    }
    values.sort_by_key(|value| {
        value
            .object()
            .and_then(|value| json_member(value, "findingId"))
            .and_then(JsonValue::string)
            .unwrap_or("")
            .to_owned()
    });
    Ok(())
}

fn write_artifact_review_findings_document(
    output: &Path,
    root: &Path,
    input: &Path,
    candidate: &str,
    epoch: &str,
    role: &str,
    findings: &JsonValue,
) -> Result<(), String> {
    let (reviewed_files, acquisition_package_sha256) =
        artifact_review_file_manifest(input, output)?;
    let reviewed_artifacts = review_packet_artifacts(input, role)?;
    let workflow_path = ".github/workflows/artifact-authenticity-finalize.yml";
    let workflow_blob_sha256 = record_digest(&repository_relative_path(root, workflow_path)?)?;
    let mut reviewed_files_json = String::new();
    push_json_value(&mut reviewed_files_json, &reviewed_files)?;
    let mut findings_json = String::new();
    push_json_value(&mut findings_json, findings)?;
    let reviewed_artifacts = reviewed_artifacts
        .iter()
        .map(|digest| json_string(digest))
        .collect::<Vec<_>>()
        .join(",");
    let document = format!(
        "{{\"schemaVersion\":2,\"candidateCommit\":{},\"assuranceEpochSha256\":{},\"role\":{},\"workflowPath\":{},\"workflowBlobSha256\":{},\"acquisitionPackageSha256\":{},\"reviewedFiles\":{reviewed_files_json},\"reviewedArtifacts\":[{reviewed_artifacts}],\"findings\":{findings_json}}}\n",
        json_string(candidate),
        json_string(epoch),
        json_string(role),
        json_string(workflow_path),
        json_string(&workflow_blob_sha256),
        json_string(&acquisition_package_sha256),
    );
    write_atomic(output, document.as_bytes())
}

struct AuthorizedFindingsDocument<'a> {
    output: &'a Path,
    candidate: &'a str,
    epoch: &'a str,
    role: &'a str,
    findings: &'a JsonValue,
    acquisition_package_sha256: &'a str,
    reviewed_artifacts: &'a JsonValue,
    workflow_path: &'a str,
    workflow_blob_sha256: &'a str,
    review_subject_sha256: &'a str,
    authorization_sha256: &'a str,
}

fn write_authorized_review_findings_document(
    facts: &AuthorizedFindingsDocument<'_>,
) -> Result<(), String> {
    require_digest(
        facts.acquisition_package_sha256,
        "authorized findings acquisition package",
    )?;
    require_digest(
        facts.workflow_blob_sha256,
        "authorized findings workflow blob",
    )?;
    require_digest(facts.review_subject_sha256, "authorized findings subject")?;
    require_digest(
        facts.authorization_sha256,
        "authorized findings authorization",
    )?;
    let mut findings_json = String::new();
    push_json_value(&mut findings_json, facts.findings)?;
    let mut reviewed_artifacts_json = String::new();
    push_json_value(&mut reviewed_artifacts_json, facts.reviewed_artifacts)?;
    let document = format!(
        "{{\"schemaVersion\":3,\"candidateCommit\":{},\"assuranceEpochSha256\":{},\"role\":{},\"workflowPath\":{},\"workflowBlobSha256\":{},\"acquisitionPackageSha256\":{},\"reviewedArtifacts\":{reviewed_artifacts_json},\"reviewSubjectSha256\":{},\"authorizationSha256\":{},\"findings\":{findings_json}}}\n",
        json_string(facts.candidate),
        json_string(facts.epoch),
        json_string(facts.role),
        json_string(facts.workflow_path),
        json_string(facts.workflow_blob_sha256),
        json_string(facts.acquisition_package_sha256),
        json_string(facts.review_subject_sha256),
        json_string(facts.authorization_sha256),
    );
    write_atomic(facts.output, document.as_bytes())
}

fn verify_review_findings_document(
    document: &BTreeMap<String, JsonValue>,
    root: &Path,
    input: &Path,
    candidate: &str,
    epoch: &str,
    role: &str,
) -> Result<(), String> {
    exact_keys(
        document,
        &[
            "acquisitionPackageSha256",
            "assuranceEpochSha256",
            "candidateCommit",
            "findings",
            "reviewedArtifacts",
            "reviewedFiles",
            "role",
            "schemaVersion",
            "workflowBlobSha256",
            "workflowPath",
        ],
    )?;
    if json_member(document, "schemaVersion")?.number()? != 2
        || json_member(document, "candidateCommit")?.string()? != candidate
        || json_member(document, "assuranceEpochSha256")?.string()? != epoch
        || json_member(document, "role")?.string()? != role
    {
        return Err("review findings document identity is stale".to_owned());
    }
    let workflow_path = ".github/workflows/artifact-authenticity-finalize.yml";
    if json_member(document, "workflowPath")?.string()? != workflow_path
        || json_member(document, "workflowBlobSha256")?.string()?
            != record_digest(&repository_relative_path(root, workflow_path)?)?
    {
        return Err("artifact review subject workflow identity is stale".to_owned());
    }
    verify_artifact_review_file_manifest(
        input,
        json_member(document, "reviewedFiles")?,
        json_member(document, "acquisitionPackageSha256")?.string()?,
    )?;
    let reviewed_artifacts = exact_reviewed_artifact_set(document)?;
    if reviewed_artifacts != review_packet_artifacts(input, role)? {
        return Err("review findings subject artifact set is stale".to_owned());
    }
    verify_artifact_exception_findings(input, json_member(document, "findings")?.array()?)?;
    Ok(())
}

fn artifact_review_file_manifest(
    input: &Path,
    output: &Path,
) -> Result<(JsonValue, String), String> {
    let excluded = output
        .strip_prefix(input)
        .ok()
        .and_then(|path| path.to_str());
    let files = artifact_review_manifest_value(input, excluded)?;
    let digest = canonical_json_digest(&files)?;
    Ok((files, digest))
}

fn artifact_review_manifest_value(
    input: &Path,
    excluded: Option<&str>,
) -> Result<JsonValue, String> {
    let mut files = Vec::new();
    collect_manifest_files(input, input, &mut files)?;
    files.retain(|(path, _, _)| Some(path.as_str()) != excluded);
    files.sort_by(|left, right| left.0.cmp(&right.0));
    if files.is_empty() {
        return Err("artifact review subject has no acquisition files".to_owned());
    }
    Ok(JsonValue::Array(
        files
            .into_iter()
            .map(|(path, digest, size)| {
                JsonValue::Object(BTreeMap::from([
                    ("path".to_owned(), JsonValue::String(path)),
                    ("sha256".to_owned(), JsonValue::String(digest.hex())),
                    ("size".to_owned(), JsonValue::Number(size)),
                ]))
            })
            .collect(),
    ))
}

fn verify_artifact_review_file_manifest(
    input: &Path,
    value: &JsonValue,
    expected_digest: &str,
) -> Result<(), String> {
    require_digest(expected_digest, "artifact review acquisition package")?;
    if canonical_json_digest(value)? != expected_digest {
        return Err("artifact review acquisition package digest mismatch".to_owned());
    }
    let files = value.array()?;
    if files.is_empty() {
        return Err("artifact review acquisition package is empty".to_owned());
    }
    let mut previous = None;
    for file in files {
        let file = file.object()?;
        exact_keys(file, &["path", "sha256", "size"])?;
        let declared = json_member(file, "path")?.string()?;
        let declared_path = Path::new(declared);
        if declared_path.is_absolute()
            || declared.contains('\\')
            || declared_path
                .components()
                .any(|component| !matches!(component, std::path::Component::Normal(_)))
            || previous.is_some_and(|prior: &str| prior >= declared)
        {
            return Err("artifact review package paths are not confined and sorted".to_owned());
        }
        let retained = input.join(declared_path);
        verify_file_digest(
            &retained,
            json_member(file, "sha256")?.string()?,
            "artifact review package file",
        )?;
        if record_size(&retained)? != json_member(file, "size")?.number()? {
            return Err("artifact review package file size mismatch".to_owned());
        }
        previous = Some(declared);
    }
    Ok(())
}

fn verify_artifact_review_file_manifest_exact(
    input: &Path,
    value: &JsonValue,
    expected_digest: &str,
) -> Result<(), String> {
    verify_artifact_review_file_manifest(input, value, expected_digest)?;
    if artifact_review_manifest_value(input, None)? != *value {
        return Err("reviewed provider extraction has missing or extra files".to_owned());
    }
    Ok(())
}

fn exact_reviewed_artifact_set(
    document: &BTreeMap<String, JsonValue>,
) -> Result<BTreeSet<String>, String> {
    let mut artifacts = BTreeSet::new();
    let mut previous = None;
    for artifact in json_member(document, "reviewedArtifacts")?.array()? {
        let artifact = artifact.string()?.to_owned();
        require_digest(&artifact, "artifact review subject artifact")?;
        if previous.as_ref().is_some_and(|prior| prior >= &artifact)
            || !artifacts.insert(artifact.clone())
        {
            return Err("artifact review subject artifacts are not unique and sorted".to_owned());
        }
        previous = Some(artifact);
    }
    if artifacts.is_empty() {
        return Err("artifact review subject has no reviewed artifacts".to_owned());
    }
    Ok(artifacts)
}

fn validate_review_findings(
    value: &JsonValue,
    enforce_resolution: bool,
    reviewed_artifacts: &BTreeSet<String>,
) -> Result<String, String> {
    let limits = review_text_limits()?;
    let findings = value.array()?;
    let mut prior_id = None;
    for finding in findings {
        let finding = finding.object()?;
        let finding_id =
            validate_review_finding(finding, enforce_resolution, reviewed_artifacts, &limits)?;
        if prior_id.as_ref().is_some_and(|prior| prior >= &finding_id) {
            return Err("review findings are not content-addressed and sorted".to_owned());
        }
        prior_id = Some(finding_id);
    }
    canonical_json_digest(value)
}

fn validate_review_finding(
    finding: &BTreeMap<String, JsonValue>,
    enforce_resolution: bool,
    reviewed_artifacts: &BTreeSet<String>,
    limits: &ReviewTextLimits,
) -> Result<String, String> {
    exact_keys(
        finding,
        &[
            "category",
            "disposition",
            "evidenceSha256",
            "findingId",
            "issue",
            "statement",
        ],
    )?;
    let category = json_member(finding, "category")?.string()?;
    if !matches!(
        category,
        "ArtifactAuthenticity"
            | "OracleProvenance"
            | "ClaimApplicability"
            | "SemanticSufficiency"
            | "NormalizerSafety"
            | "DivergenceAcceptability"
            | "DurableCustody"
            | "ReviewerIndependence"
            | "ResidualRisk"
            | "MutationSensitivity"
    ) {
        return Err("review finding category is not typed".to_owned());
    }
    let disposition = json_member(finding, "disposition")?.string()?;
    if !matches!(
        disposition,
        "Accepted" | "Rejected" | "FollowUpRequired" | "Informational"
    ) || enforce_resolution && matches!(disposition, "Rejected" | "FollowUpRequired")
    {
        return Err("review finding disposition is invalid or unresolved".to_owned());
    }
    let statement = json_member(finding, "statement")?.string()?;
    if statement.is_empty()
        || statement.len() > limits.finding_statement_maximum
        || statement.chars().any(char::is_control)
    {
        return Err("review finding statement is empty or unsafe".to_owned());
    }
    let mut evidence_digests = BTreeSet::new();
    for digest in json_member(finding, "evidenceSha256")?.array()? {
        let digest = digest.string()?.to_owned();
        require_digest(&digest, "review finding evidence")?;
        if !reviewed_artifacts.contains(&digest) || !evidence_digests.insert(digest) {
            return Err("review finding evidence is absent or repeated".to_owned());
        }
    }
    let issue = match json_member(finding, "issue")? {
        JsonValue::Null => None,
        JsonValue::String(issue)
            if !issue.is_empty()
                && issue.len() <= limits.issue_reference_maximum
                && !issue.chars().any(char::is_whitespace) =>
        {
            Some(issue.as_str())
        }
        _ => return Err("review finding issue reference is invalid".to_owned()),
    };
    if matches!(disposition, "Accepted" | "Rejected") && evidence_digests.is_empty()
        || matches!(disposition, "Rejected" | "FollowUpRequired") && issue.is_none()
        || disposition == "Informational" && evidence_digests.is_empty() && issue.is_none()
    {
        return Err("review finding lacks required evidence or issue binding".to_owned());
    }
    let core = JsonValue::Object(BTreeMap::from([
        (
            "category".to_owned(),
            JsonValue::String(category.to_owned()),
        ),
        (
            "disposition".to_owned(),
            JsonValue::String(disposition.to_owned()),
        ),
        (
            "evidenceSha256".to_owned(),
            JsonValue::Array(
                evidence_digests
                    .into_iter()
                    .map(JsonValue::String)
                    .collect(),
            ),
        ),
        (
            "issue".to_owned(),
            issue.map_or(JsonValue::Null, |value| JsonValue::String(value.to_owned())),
        ),
        (
            "statement".to_owned(),
            JsonValue::String(statement.to_owned()),
        ),
    ]));
    let expected_id = canonical_json_digest(&core)?;
    let finding_id = json_member(finding, "findingId")?.string()?;
    if finding_id != expected_id {
        return Err("review finding identity is not content-addressed".to_owned());
    }
    Ok(finding_id.to_owned())
}

fn evidence_review_identity(
    root: &Path,
    role: &str,
    reviewed_artifact: &Path,
    authorization: &Path,
) -> Result<(String, String), String> {
    let authorization_document = parse_json(&read_text(authorization)?)?;
    let candidate = json_member(authorization_document.object()?, "candidateCommit")?.string()?;
    require_git_sha_text(candidate, "evidence review candidate")?;
    if git_output(root, &["rev-parse", "HEAD"])?.trim() != candidate {
        return Err("evidence review checkout differs from dispatch candidate".to_owned());
    }
    let (account_id, _, reviewed_at, _, _) =
        verify_review_authorization(authorization, role, candidate, reviewed_artifact)?;
    Ok((format!("{role}:github-account-{account_id}"), reviewed_at))
}

fn review_authorization(root: &Path, options: &Options) -> Result<String, String> {
    let input = required_path(
        &options.input,
        "review-authorization requires --input reviewed details",
    )?;
    let output = required_path(&options.output, "review-authorization requires --output")?;
    let role = options
        .role
        .as_deref()
        .ok_or_else(|| "review-authorization requires --role".to_owned())?;
    if !options.github_dispatch_inputs {
        return Err("review-authorization requires --github-dispatch-inputs".to_owned());
    }
    let candidate = review_authorization_candidate(root, options)?;
    let (team, environment, organization, team_slug) = review_team_authority(root, role)?;
    let repository = std::env::var("GITHUB_REPOSITORY")
        .map_err(|_| "review authorization requires GITHUB_REPOSITORY".to_owned())?;
    if repository != "Portfoligno/hell-rs" {
        return Err("review authorization repository is not accepted".to_owned());
    }
    let run_id = environment_u64("GITHUB_RUN_ID", "review authorization run")?;
    let run_attempt = environment_u64("GITHUB_RUN_ATTEMPT", "review authorization attempt")?;
    let reviewed_artifact_sha256 = record_digest(input)?;
    let repository_path = repository
        .split('/')
        .fold(PathBuf::new(), |path, component| path.join(component));
    let approvals_endpoint = PathBuf::from("repos")
        .join(repository_path)
        .join("actions")
        .join("runs")
        .join(run_id.to_string())
        .join("approvals");
    let approvals = github_api_json_for(
        &approvals_endpoint,
        ExternalServiceOperation::ProtectedAdmission,
    )?;
    let scope = ReviewApprovalScope {
        environment,
        role,
        candidate: &candidate,
        reviewed_artifact_sha256: &reviewed_artifact_sha256,
        artifact_exception_required: artifact_review_exception_required(input, role)?,
    };
    let (account_id, login, decision) = approved_environment_actor(&approvals, &scope)?;
    verify_regression_reviewer_independence(input, options.category.as_deref(), account_id)?;
    let membership_endpoint = PathBuf::from("orgs")
        .join(&organization)
        .join("teams")
        .join(&team_slug)
        .join("memberships")
        .join(&login);
    let membership = github_active_team_membership(&membership_endpoint)?;
    let approvals_bytes = canonical_json_bytes(&approvals)?;
    let membership_bytes = canonical_json_bytes(&membership)?;
    let signing_keys_endpoint = PathBuf::from("users").join(&login).join("ssh_signing_keys");
    let signing_keys = github_api_json_for(
        &signing_keys_endpoint,
        ExternalServiceOperation::ProtectedAdmission,
    )?;
    let signing_key = select_github_signing_key(&signing_keys, decision.signing_key_id)?;
    let signing_keys_bytes = canonical_json_bytes(&signing_keys)?;
    let provider_request = FinalReviewProviderRequest {
        root,
        reviewed_artifact: input,
        output,
        category: options.category.as_deref(),
        candidate: &candidate,
        reviewed_artifact_sha256: &reviewed_artifact_sha256,
        run_id,
        run_attempt,
        platform: options.platform.as_deref(),
    };
    let provider = final_review_provider_facts_if_required(&provider_request)?;
    retain_review_authorization(
        root,
        output,
        &ReviewAuthorizationRetention {
            role,
            candidate: &candidate,
            reviewed_artifact_sha256: &reviewed_artifact_sha256,
            run_id,
            run_attempt,
            environment,
            reviewed_at: &decision.reviewed_at,
            review_rationale: &decision.rationale,
            exception_issue: decision.exception_issue.as_deref(),
            account_id,
            login: &login,
            team: &team,
            signing_key_id: decision.signing_key_id,
            signing_key: &signing_key,
            approvals_bytes: &approvals_bytes,
            membership_bytes: &membership_bytes,
            signing_keys_bytes: &signing_keys_bytes,
            provider: provider.as_ref(),
        },
    )?;
    Ok(format!("retained authorized {role} account {account_id}"))
}

fn verify_active_team_membership(membership: &BTreeMap<String, JsonValue>) -> Result<(), String> {
    if json_member(membership, "state")?.string()? != "active"
        || !matches!(
            json_member(membership, "role")?.string()?,
            "member" | "maintainer"
        )
    {
        return Err("reviewer does not have active membership in the required team".to_owned());
    }
    Ok(())
}

fn github_active_team_membership(endpoint: &Path) -> Result<JsonValue, String> {
    let membership = github_api_json_for(endpoint, ExternalServiceOperation::ProtectedAdmission)?;
    verify_active_team_membership(membership.object()?)?;
    Ok(membership)
}

fn verify_regression_reviewer_independence(
    input: &Path,
    category: Option<&str>,
    reviewer_account_id: u64,
) -> Result<(), String> {
    if category != Some("regression-final") {
        return Ok(());
    }
    let subject = parse_json(&read_text(input)?)?;
    if json_member(subject.object()?, "proposerAccountId")?.number()? == reviewer_account_id {
        return Err("regression reviewer is not independent from the proposal actor".to_owned());
    }
    Ok(())
}

fn review_team_authority(
    root: &Path,
    role: &str,
) -> Result<(String, &'static str, String, String), String> {
    let (team_key, environment) = evidence_review_authority(role)?;
    let review_policy = read_text(&root.join("compat").join("review-policy.toml"))?;
    let team = assignment_string(&review_policy, team_key)?;
    let (organization, team_slug) = team
        .split_once('/')
        .ok_or_else(|| "review policy team is not an organization/team identity".to_owned())?;
    validate_provider_atom(organization, "review organization")?;
    validate_provider_atom(team_slug, "review team")?;
    Ok((
        team.clone(),
        environment,
        organization.to_owned(),
        team_slug.to_owned(),
    ))
}

const FINAL_REVIEW_GRAPH_INPUTS: &[&str] = &[
    "acquisition_time",
    "artifact_class",
    "candidate_sha",
    "expected_artifact_set_sha256",
    "provider_artifact_id",
    "retention_until",
    "review_issued_at",
    "source_run_attempt",
    "source_run_id",
];

fn review_authorization_candidate(root: &Path, options: &Options) -> Result<String, String> {
    if options.category.as_deref() == Some("regression-final") {
        return regression_authorization_candidate(root, options);
    }
    if options.category.as_deref() == Some("artifact-trust-final") {
        return artifact_finalize_dispatch(root).map(|dispatch| dispatch.candidate);
    }
    if options.category.as_deref() == Some("mutation-final") {
        return mutation_review_candidate(root);
    }
    if options.category.as_deref() == Some("promotion-final") {
        let subject = required_path(
            &options.input,
            "promotion authorization requires --input subject",
        )?;
        let (_, epoch) = epoch(root)?;
        let candidate = git_output(root, &["rev-parse", "HEAD"])?;
        let candidate = candidate.trim();
        let proposal = subject
            .parent()
            .ok_or_else(|| "promotion authorization subject has no directory".to_owned())?
            .join("promotion-proposal.json");
        verify_promotion_approval_subject(subject, &proposal, candidate, &epoch.hex())?;
        return Ok(candidate.to_owned());
    }
    if let Some((role, allowed_events)) = match options.category.as_deref() {
        Some("oracle-platform-final") => Some(("platform-reviewer", &["workflow_dispatch"][..])),
        Some("custody-final") => Some(("custody-reviewer", &["workflow_dispatch"][..])),
        Some("collection-activation-author") => Some(("claim-author", &["workflow_dispatch"][..])),
        Some("collection-activation-final") => Some(("claim-reviewer", &["workflow_dispatch"][..])),
        _ => None,
    } {
        let subject = required_path(
            &options.input,
            "protected human review authorization requires --input subject",
        )?;
        if matches!(role, "claim-author" | "claim-reviewer") {
            return collection_activation_authorization_candidate(
                root,
                subject,
                role,
                allowed_events,
            );
        }
        return protected_review_subject_candidate(root, subject, role, allowed_events);
    }
    if options.category.as_deref() != Some("final-review-graph") {
        let inputs = github_dispatch_object(REVIEW_ASSEMBLY_INPUTS)?;
        return validate_review_assembly_identity(root, &inputs).map(str::to_owned);
    }
    final_review_graph_authorization_candidate(root)
}

fn final_review_graph_authorization_candidate(root: &Path) -> Result<String, String> {
    let inputs = github_dispatch_object(FINAL_REVIEW_GRAPH_INPUTS)?;
    if map_value(&inputs, "artifact_class")? != "pre-review-evidence" {
        return Err("final review graph requires pre-review evidence custody".to_owned());
    }
    for key in [
        "source_run_id",
        "source_run_attempt",
        "provider_artifact_id",
    ] {
        positive_map_integer(&inputs, key, "final review graph authorization")?;
    }
    require_digest(
        map_value(&inputs, "expected_artifact_set_sha256")?,
        "final review graph artifact set",
    )?;
    validate_utc_timestamp(map_value(&inputs, "review_issued_at")?)?;
    let candidate = map_value(&inputs, "candidate_sha")?;
    require_git_sha_text(candidate, "final review graph candidate")?;
    if git_output(root, &["rev-parse", "HEAD"])?.trim() != candidate {
        return Err("final review graph checkout differs from candidate".to_owned());
    }
    Ok(candidate.to_owned())
}

fn regression_authorization_candidate(root: &Path, options: &Options) -> Result<String, String> {
    let subject = required_path(
        &options.input,
        "regression authorization requires --input provider-bound subject",
    )?;
    let document = parse_json(&read_text(subject)?)?;
    let document = document.object()?;
    exact_keys(
        document,
        &[
            "assuranceEpochSha256",
            "candidateCommit",
            "packageSha256",
            "providerSelectionSha256",
            "proposerAccountId",
            "schemaVersion",
            "state",
        ],
    )?;
    let candidate = json_member(document, "candidateCommit")?.string()?;
    if json_member(document, "schemaVersion")?.number()? != 1
        || json_member(document, "state")?.string()? != "requires-regression-review"
        || git_output(root, &["rev-parse", "HEAD"])?.trim() != candidate
    {
        return Err("regression authorization subject is not trusted current state".to_owned());
    }
    for (field, label) in [
        ("assuranceEpochSha256", "regression authorization epoch"),
        ("packageSha256", "regression authorization package"),
        (
            "providerSelectionSha256",
            "regression authorization provider selection",
        ),
    ] {
        require_digest(json_member(document, field)?.string()?, label)?;
    }
    if json_member(document, "proposerAccountId")?.number()? == 0 {
        return Err("regression authorization proposer identity is invalid".to_owned());
    }
    verify_regression_authorization_subject(root, subject, document)?;
    Ok(candidate.to_owned())
}

fn collection_activation_authorization_candidate(
    root: &Path,
    subject: &Path,
    role: &str,
    allowed_events: &[&str],
) -> Result<String, String> {
    if !matches!(role, "claim-author" | "claim-reviewer")
        || subject.file_name() != Some(OsStr::new("review-subject.json"))
    {
        return Err("collection activation authorization subject is invalid".to_owned());
    }
    let subject_root = subject
        .parent()
        .ok_or_else(|| "collection activation review subject has no directory".to_owned())?;
    let proposal_root =
        crate::collection_custody::verify_activation_review_subject(root, subject_root)?;
    let document = parse_json(&read_text(&proposal_root.join("activation-proposal.json"))?)?;
    let candidate = json_member(document.object()?, "baseCandidateCommit")?.string()?;
    let event = std::env::var("GITHUB_EVENT_NAME")
        .map_err(|_| "collection activation authorization requires GITHUB_EVENT_NAME".to_owned())?;
    if git_output(root, &["rev-parse", "HEAD"])?.trim() != candidate
        || !allowed_events.contains(&event.as_str())
    {
        return Err(
            "collection activation authorization is stale or has an unsupported event".to_owned(),
        );
    }
    Ok(candidate.to_owned())
}

fn verify_regression_authorization_subject(
    root: &Path,
    subject: &Path,
    record: &BTreeMap<String, JsonValue>,
) -> Result<(), String> {
    let sealed = subject
        .parent()
        .ok_or_else(|| "regression authorization subject has no sealed root".to_owned())?;
    let package = sealed.join("package");
    let selection = sealed.join("proposal-selection");
    if record_digest(&package)? != json_member(record, "packageSha256")?.string()?
        || record_digest(&selection)? != json_member(record, "providerSelectionSha256")?.string()?
    {
        return Err(
            "regression authorization sibling roots differ from the sealed subject".to_owned(),
        );
    }
    let proposal = parse_json(&read_text(&package.join("proposal.json"))?)?;
    let proposal = proposal.object()?;
    verify_regression_proposal_shape(proposal)?;
    let candidate = json_member(record, "candidateCommit")?.string()?;
    if json_member(proposal, "candidateCommit")?.string()? != candidate
        || json_member(proposal, "assuranceEpochSha256")?.string()?
            != json_member(record, "assuranceEpochSha256")?.string()?
    {
        return Err("regression authorization proposal identity differs".to_owned());
    }
    reverify_regression_provider_selection(
        root,
        &package,
        &selection,
        candidate,
        ".github/workflows/regression-corpus.yml",
    )?;
    require_regression_artifact_class(&selection, "regression-review-subject-")?;
    let provider_run = parse_json(&read_text(&selection.join("provider-selected-run.json"))?)?;
    let actor = json_member(provider_run.object()?, "actor")?.object()?;
    if json_member(actor, "id")?.number()? != json_member(record, "proposerAccountId")?.number()? {
        return Err("regression authorization proposer differs from the provider run".to_owned());
    }
    Ok(())
}

fn protected_review_subject_candidate(
    root: &Path,
    subject: &Path,
    role: &str,
    allowed_events: &[&str],
) -> Result<String, String> {
    let (candidate, subject_epoch, _) = protected_review_subject(subject, role)?;
    let checkout = git_output(root, &["rev-parse", "HEAD"])?;
    let (_, current_epoch) = epoch(root)?;
    let event = std::env::var("GITHUB_EVENT_NAME")
        .map_err(|_| "protected review authorization requires GITHUB_EVENT_NAME".to_owned())?;
    if checkout.trim() != candidate
        || current_epoch.hex() != subject_epoch
        || !allowed_events.contains(&event.as_str())
    {
        return Err(
            "protected review subject is stale or has an unsupported provider event".to_owned(),
        );
    }
    if role == "custody-reviewer" {
        let inputs = github_dispatch_object(&[
            "acquisition_time",
            "artifact_class",
            "candidate_sha",
            "expected_artifact_set_sha256",
            "provider_artifact_id",
            "retention_until",
            "review_issued_at",
            "source_run_attempt",
            "source_run_id",
        ])?;
        if map_value(&inputs, "candidate_sha")? != candidate {
            return Err("custody review subject differs from the dispatch candidate".to_owned());
        }
    }
    Ok(candidate)
}

fn protected_review_subject(
    path: &Path,
    role: &str,
) -> Result<(String, String, BTreeSet<String>), String> {
    let document = parse_json(&read_text(path)?)?;
    let packet = document.object()?;
    exact_keys(
        packet,
        &[
            "assuranceEpochSha256",
            "candidateCommit",
            "decision",
            "distinctSubjects",
            "findings",
            "independenceViolations",
            "issuedAt",
            "reviewId",
            "reviewedArtifacts",
            "reviewer",
            "role",
            "schemaVersion",
        ],
    )?;
    let candidate = json_member(packet, "candidateCommit")?.string()?.to_owned();
    let subject_epoch = json_member(packet, "assuranceEpochSha256")?
        .string()?
        .to_owned();
    require_git_sha_text(&candidate, "protected review subject candidate")?;
    require_digest(&subject_epoch, "protected review subject epoch")?;
    let reviewer = json_member(packet, "reviewer")?.string()?;
    let issued_at = json_member(packet, "issuedAt")?.string()?;
    validate_utc_timestamp(issued_at)?;
    if json_member(packet, "schemaVersion")?.number()? != 1
        || json_member(packet, "role")?.string()? != role
        || json_member(packet, "decision")?.string()? != "accept"
        || !reviewer.starts_with(&format!("{role}:"))
        || json_member(packet, "distinctSubjects")?.number()? != 1
        || !json_member(packet, "findings")?.array()?.is_empty()
        || !json_member(packet, "independenceViolations")?
            .array()?
            .is_empty()
    {
        return Err("protected review subject packet is not a clean exact review".to_owned());
    }
    let mut artifacts = BTreeSet::new();
    let mut ordered = Vec::new();
    for artifact in json_member(packet, "reviewedArtifacts")?.array()? {
        let artifact = artifact.string()?.to_owned();
        require_digest(&artifact, "protected reviewed artifact")?;
        if !artifacts.insert(artifact.clone()) {
            return Err("protected review subject repeats a reviewed artifact".to_owned());
        }
        ordered.push(artifact);
    }
    if artifacts.is_empty() {
        return Err("protected review subject has no reviewed artifacts".to_owned());
    }
    let empty_claim_groups = BTreeMap::new();
    let expected_id = review_statement_id(&ReviewStatementIdentity {
        candidate: &candidate,
        epoch: &subject_epoch,
        role,
        reviewer,
        decision: "accept",
        issued_at,
        artifacts: &artifacts,
        claim_groups: &empty_claim_groups,
        findings_sha256: &sha256_bytes(b"[]\n").hex(),
    });
    if json_member(packet, "reviewId")?.string()? != expected_id {
        return Err(
            "protected review subject ID is not derived from its exact artifacts".to_owned(),
        );
    }
    Ok((candidate, subject_epoch, artifacts))
}

pub(crate) fn verify_review_packet_first_artifact(
    path: &Path,
    role: &str,
    expected_candidate: &str,
    expected_epoch: &str,
    expected_artifact_sha256: &str,
) -> Result<(), String> {
    require_digest(
        expected_artifact_sha256,
        "protected review packet first artifact",
    )?;
    let (candidate, epoch, _) = protected_review_subject(path, role)?;
    let document = parse_json(&read_text(path)?)?;
    let reviewed = json_member(document.object()?, "reviewedArtifacts")?.array()?;
    if candidate != expected_candidate
        || epoch != expected_epoch
        || reviewed
            .first()
            .ok_or_else(|| "protected review packet has no first artifact".to_owned())?
            .string()?
            != expected_artifact_sha256
    {
        return Err(
            "protected review packet does not bind the exact first reviewed artifact".to_owned(),
        );
    }
    Ok(())
}

pub(crate) fn verify_review_packet_artifacts(
    path: &Path,
    role: &str,
    expected: &[String],
) -> Result<(), String> {
    protected_review_subject(path, role)?;
    let document = parse_json(&read_text(path)?)?;
    let observed = json_member(document.object()?, "reviewedArtifacts")?
        .array()?
        .iter()
        .map(JsonValue::string)
        .collect::<Result<Vec<_>, _>>()?;
    if observed != expected.iter().map(String::as_str).collect::<Vec<_>>() {
        return Err("protected review packet artifact sequence changed".to_owned());
    }
    Ok(())
}

pub(crate) struct PublicationReceiptExpectation<'a> {
    pub(crate) public_base_url: &'a str,
    pub(crate) candidate: &'a str,
    pub(crate) epoch: &'a str,
    pub(crate) state: &'a str,
    pub(crate) record_sha256: &'a str,
    pub(crate) packet_sha256: &'a str,
    pub(crate) dsse_sha256: &'a str,
    pub(crate) report_sha256: &'a str,
    pub(crate) divergences_sha256: &'a str,
    pub(crate) release_statement_sha256: &'a str,
}

pub(crate) fn verify_publication_receipt(
    path: &Path,
    expected: &PublicationReceiptExpectation<'_>,
) -> Result<(), String> {
    verify_publication_receipt_schema(path)?;
    let document = parse_json(&read_text(path)?)?;
    let receipt = document.object()?;
    if json_member(receipt, "schemaVersion")?.number()? != 2
        || json_member(receipt, "candidateCommit")?.string()? != expected.candidate
        || json_member(receipt, "assuranceEpochSha256")?.string()? != expected.epoch
        || json_member(receipt, "derivedState")?.string()? != expected.state
        || json_member(receipt, "recordSha256")?.string()? != expected.record_sha256
        || json_member(receipt, "packetSha256")?.string()? != expected.packet_sha256
        || json_member(receipt, "dsseSha256")?.string()? != expected.dsse_sha256
        || json_member(receipt, "compatibilityReportSha256")?.string()? != expected.report_sha256
        || json_member(receipt, "acceptedDivergencesSha256")?.string()?
            != expected.divergences_sha256
        || json_member(receipt, "releaseStatementSha256")?.string()?
            != expected.release_statement_sha256
        || json_member(receipt, "state")?.string()? != "published-and-anonymously-reverified"
        || json_member(receipt, "publicBaseUrl")?.string()? != expected.public_base_url
        || !matches!(
            json_member(receipt, "publisherEvent")?.string()?,
            "push" | "schedule" | "workflow_dispatch"
        )
        || json_member(receipt, "sourceArtifactName")?
            .string()?
            .is_empty()
        || json_member(receipt, "publisherAccount")?
            .string()?
            .is_empty()
        || json_member(receipt, "publisherArn")?.string()?.is_empty()
        || json_member(receipt, "publisherStableId")?
            .string()?
            .is_empty()
    {
        return Err("public publication receipt does not bind exact current state".to_owned());
    }
    Ok(())
}

fn verify_publication_receipt_schema(path: &Path) -> Result<(), String> {
    let document = parse_json(&read_text(path)?)?;
    let receipt = document.object()?;
    exact_keys(
        receipt,
        &[
            "assuranceEpochSha256",
            "candidateCommit",
            "compatibilityReportSha256",
            "derivedState",
            "dsseSha256",
            "observedAt",
            "packetSha256",
            "publicBaseUrl",
            "publisherAccount",
            "publisherArn",
            "publisherEvent",
            "publisherRepositoryId",
            "publisherRunAttempt",
            "publisherRunId",
            "publisherSourceCommit",
            "publisherStableId",
            "publisherWorkflowRef",
            "recordSha256",
            "releaseStatementSha256",
            "schemaVersion",
            "sourceArtifactApiSha256",
            "sourceArtifactId",
            "sourceArtifactName",
            "sourceExtractedSha256",
            "sourceProviderArchiveSha256",
            "sourceProviderArchiveSize",
            "sourceRunApiSha256",
            "sourceSelectionSha256",
            "sourceWorkflowSha256",
            "state",
            "acceptedDivergencesSha256",
        ],
    )?;
    for field in [
        "assuranceEpochSha256",
        "recordSha256",
        "packetSha256",
        "dsseSha256",
        "publisherSourceCommit",
        "sourceSelectionSha256",
        "sourceProviderArchiveSha256",
        "sourceExtractedSha256",
        "sourceArtifactApiSha256",
        "sourceRunApiSha256",
        "sourceWorkflowSha256",
        "compatibilityReportSha256",
        "acceptedDivergencesSha256",
        "releaseStatementSha256",
    ] {
        let value = json_member(receipt, field)?.string()?;
        if field == "publisherSourceCommit" {
            require_git_sha_text(value, "public publisher source commit")?;
        } else {
            require_digest(value, field)?;
        }
    }
    validate_utc_timestamp(json_member(receipt, "observedAt")?.string()?)?;
    for field in [
        "sourceArtifactId",
        "sourceProviderArchiveSize",
        "publisherRunId",
        "publisherRunAttempt",
        "publisherRepositoryId",
    ] {
        if json_member(receipt, field)?.number()? == 0 {
            return Err(format!("public publication receipt {field} is zero"));
        }
    }
    Ok(())
}

pub(crate) struct PublicReleaseExpectation<'a> {
    pub(crate) candidate: &'a str,
    pub(crate) epoch: &'a str,
    pub(crate) state: &'a str,
    pub(crate) report_sha256: &'a str,
    pub(crate) divergences_sha256: &'a str,
    pub(crate) transition_sha256: &'a str,
    pub(crate) issued_at: &'a str,
}

pub(crate) fn verify_public_release_statement(
    path: &Path,
    expected: &PublicReleaseExpectation<'_>,
) -> Result<(), String> {
    let document = parse_json(&read_text(path)?)?;
    let statement = document.object()?;
    exact_keys(
        statement,
        &[
            "acceptedDivergencesSha256",
            "assuranceEpochSha256",
            "candidateCommit",
            "claim",
            "compatibilityReportSha256",
            "issuedAt",
            "promotionState",
            "schemaVersion",
            "transitionSha256",
        ],
    )?;
    validate_utc_timestamp(json_member(statement, "issuedAt")?.string()?)?;
    if json_member(statement, "schemaVersion")?.number()? != 1
        || json_member(statement, "candidateCommit")?.string()? != expected.candidate
        || json_member(statement, "assuranceEpochSha256")?.string()? != expected.epoch
        || json_member(statement, "promotionState")?.string()? != expected.state
        || json_member(statement, "compatibilityReportSha256")?.string()? != expected.report_sha256
        || json_member(statement, "acceptedDivergencesSha256")?.string()?
            != expected.divergences_sha256
        || json_member(statement, "transitionSha256")?.string()? != expected.transition_sha256
        || json_member(statement, "issuedAt")?.string()? != expected.issued_at
        || json_member(statement, "claim")?.string()?
            != "compatibility is bounded to the retained claim-cell, platform, profile, normalizer, divergence, and custody evidence in this report"
    {
        return Err("public release statement does not bind exact bounded evidence".to_owned());
    }
    Ok(())
}

fn mutation_review_candidate(root: &Path) -> Result<String, String> {
    let candidate = git_output(root, &["rev-parse", "HEAD"])?;
    let candidate = candidate.trim();
    require_git_sha_text(candidate, "mutation review candidate")?;
    match std::env::var("GITHUB_EVENT_NAME").as_deref() {
        Ok("schedule") => Ok(candidate.to_owned()),
        Ok("workflow_dispatch") => {
            let inputs = github_dispatch_object(&["candidate_sha", "issued_at", "require_review"])?;
            if map_value(&inputs, "candidate_sha")? != candidate
                || map_value(&inputs, "require_review")? != "true"
            {
                return Err("mutation review dispatch does not bind the candidate".to_owned());
            }
            validate_utc_timestamp(map_value(&inputs, "issued_at")?)?;
            Ok(candidate.to_owned())
        }
        _ => Err("mutation review requires schedule or workflow_dispatch".to_owned()),
    }
}

struct ReviewAuthorizationRetention<'a> {
    role: &'a str,
    candidate: &'a str,
    reviewed_artifact_sha256: &'a str,
    run_id: u64,
    run_attempt: u64,
    environment: &'a str,
    reviewed_at: &'a str,
    review_rationale: &'a str,
    exception_issue: Option<&'a str>,
    account_id: u64,
    login: &'a str,
    team: &'a str,
    signing_key_id: u64,
    signing_key: &'a str,
    approvals_bytes: &'a [u8],
    membership_bytes: &'a [u8],
    signing_keys_bytes: &'a [u8],
    provider: Option<&'a FinalReviewProviderFacts>,
}

struct FinalReviewProviderFacts {
    artifact_id: u64,
    repository_id: u64,
    archive_sha256: String,
    artifact_api_sha256: String,
    run_api_sha256: String,
    workflow_path: String,
    workflow_ref: String,
    workflow_blob_sha256: String,
    provider_event: String,
    extracted_manifest_sha256: String,
    extracted_root_sha256: String,
}

struct FinalReviewProviderRequest<'a> {
    root: &'a Path,
    reviewed_artifact: &'a Path,
    output: &'a Path,
    category: Option<&'a str>,
    candidate: &'a str,
    reviewed_artifact_sha256: &'a str,
    run_id: u64,
    run_attempt: u64,
    platform: Option<&'a str>,
}

fn final_review_provider_facts_if_required(
    request: &FinalReviewProviderRequest<'_>,
) -> Result<Option<FinalReviewProviderFacts>, String> {
    let (artifact_name, workflow) = match request.category {
        Some("final-review-graph") => (
            final_review_subject_name(request.run_id, request.run_attempt),
            ".github/workflows/evidence-custody.yml",
        ),
        Some("artifact-trust-final") => (
            artifact_review_subject_name(request.run_id, request.run_attempt),
            ".github/workflows/artifact-authenticity-finalize.yml",
        ),
        Some("mutation-final") => (
            mutation_review_subject_name(request.run_id, request.run_attempt),
            ".github/workflows/mutation.yml",
        ),
        Some("oracle-platform-final") => (
            oracle_platform_review_subject_name(
                request.run_id,
                request.run_attempt,
                request.platform.ok_or_else(|| {
                    "oracle platform authorization requires --platform".to_owned()
                })?,
            )?,
            ".github/workflows/oracle-reproduce.yml",
        ),
        Some("custody-final") => (
            custody_review_subject_name(request.run_id, request.run_attempt),
            ".github/workflows/evidence-custody.yml",
        ),
        Some("collection-activation-author" | "collection-activation-final") => (
            collection_activation_subject_name(request.run_id, request.run_attempt),
            ".github/workflows/collection-activation.yml",
        ),
        _ => return Ok(None),
    };
    retain_final_review_provider_facts(request, &artifact_name, workflow).map(Some)
}

fn final_review_subject_name(run_id: u64, run_attempt: u64) -> String {
    let mut name = String::from("ephemeralEvidence-final-review-graph-subject-");
    name.push_str(&run_id.to_string());
    name.push('-');
    name.push_str(&run_attempt.to_string());
    name
}

fn collection_activation_subject_name(run_id: u64, run_attempt: u64) -> String {
    format!("collection-activation-proposal-{run_id}-{run_attempt}")
}

fn artifact_review_subject_name(run_id: u64, run_attempt: u64) -> String {
    let mut name = String::from("ephemeralEvidence-artifact-trust-subject-");
    name.push_str(&run_id.to_string());
    name.push('-');
    name.push_str(&run_attempt.to_string());
    name
}

fn mutation_review_subject_name(run_id: u64, run_attempt: u64) -> String {
    let mut name = String::from("ephemeralEvidence-mutation-subject-");
    name.push_str(&run_id.to_string());
    name.push('-');
    name.push_str(&run_attempt.to_string());
    name
}

fn oracle_platform_review_subject_name(
    run_id: u64,
    run_attempt: u64,
    platform: &str,
) -> Result<String, String> {
    if !matches!(platform, "macos-arm64" | "windows-amd64") {
        return Err("oracle platform review subject has an unsupported platform".to_owned());
    }
    Ok(format!(
        "ephemeralEvidence-oracle-platform-review-sealed-{platform}-{run_id}-{run_attempt}"
    ))
}

fn custody_review_subject_name(run_id: u64, run_attempt: u64) -> String {
    format!("ephemeralEvidence-custody-review-subject-{run_id}-{run_attempt}")
}

fn retain_final_review_provider_facts(
    request: &FinalReviewProviderRequest<'_>,
    artifact_name: &str,
    workflow: &str,
) -> Result<FinalReviewProviderFacts, String> {
    let (extracted_manifest_bytes, extracted_root_sha256, extracted_manifest_path) =
        retain_reviewed_provider_snapshot(request, workflow)?;
    let (repository, repository_id) = provider_selection_repository_identity()?;
    let repository_id = repository_id
        .parse::<u64>()
        .map_err(|_| "final graph repository ID is not an integer".to_owned())?;
    if repository_id == 0 {
        return Err("final graph repository ID must be nonzero".to_owned());
    }
    let repository_path = repository
        .split('/')
        .fold(PathBuf::new(), |path, component| path.join(component));
    let endpoint = PathBuf::from("repos")
        .join(repository_path)
        .join("actions")
        .join("runs")
        .join(request.run_id.to_string())
        .join("artifacts");
    let response = github_api_json_named_artifact(&endpoint, artifact_name)?;
    let response = response.object()?;
    let artifacts = json_member(response, "artifacts")?.array()?;
    if json_member(response, "total_count")?.number()? != 1 || artifacts.len() != 1 {
        return Err("final graph subject does not select exactly one provider artifact".to_owned());
    }
    let artifact = artifacts[0].object()?;
    let artifact_id = verify_final_review_artifact(artifact, artifact_name, request.run_id)?;
    let archive_sha256 = json_member(artifact, "digest")?
        .string()?
        .strip_prefix("sha256:")
        .ok_or_else(|| "final graph provider artifact digest is not SHA-256".to_owned())?
        .to_owned();
    require_digest(&archive_sha256, "final graph provider archive")?;
    let (_, run_endpoint) = provider_selection_endpoints(
        &repository,
        artifact_id,
        request.run_id,
        request.run_attempt,
    );
    let run = github_api_json(&run_endpoint)?;
    let (workflow_ref, provider_event, provider_head) = verify_final_review_run(
        request.root,
        run.object()?,
        request.candidate,
        repository_id,
        request.run_id,
        request.run_attempt,
        workflow,
    )?;
    let artifact_bytes = canonical_json_bytes(&artifacts[0])?;
    let run_bytes = canonical_json_bytes(&run)?;
    let directory = request
        .output
        .parent()
        .ok_or_else(|| "final graph authorization output has no directory".to_owned())?;
    let workflow_blob_sha256 = retain_reviewed_provider_workflow(
        request,
        &repository,
        workflow,
        &provider_head,
        directory,
    )?;
    write_atomic(
        &directory.join("reviewed-provider-artifact.json"),
        &artifact_bytes,
    )?;
    write_atomic(&directory.join("reviewed-provider-run.json"), &run_bytes)?;
    write_atomic(&extracted_manifest_path, &extracted_manifest_bytes)?;
    require_digest(
        request.reviewed_artifact_sha256,
        "final graph reviewed subject",
    )?;
    Ok(FinalReviewProviderFacts {
        artifact_id,
        repository_id,
        archive_sha256,
        artifact_api_sha256: sha256_bytes(&artifact_bytes).hex(),
        run_api_sha256: sha256_bytes(&run_bytes).hex(),
        workflow_path: workflow.to_owned(),
        workflow_ref,
        workflow_blob_sha256,
        provider_event,
        extracted_manifest_sha256: sha256_bytes(&extracted_manifest_bytes).hex(),
        extracted_root_sha256,
    })
}

fn retain_reviewed_provider_snapshot(
    request: &FinalReviewProviderRequest<'_>,
    workflow: &str,
) -> Result<(Vec<u8>, String, PathBuf), String> {
    let extracted_root = provider_review_subject_root(request.reviewed_artifact, workflow)?;
    let directory = request
        .output
        .parent()
        .ok_or_else(|| "final graph authorization output has no directory".to_owned())?;
    let manifest_path = directory.join("reviewed-provider-extracted-manifest.json");
    let (manifest, root_sha256) =
        provider_extracted_file_manifest(&extracted_root, &manifest_path)?;
    let bytes = canonical_json_bytes(&manifest)?;
    snapshot_reviewed_files(
        &extracted_root,
        &directory.join("reviewed-provider-extracted-subject"),
        &manifest,
    )?;
    Ok((bytes, root_sha256, manifest_path))
}

fn retain_reviewed_provider_workflow(
    request: &FinalReviewProviderRequest<'_>,
    repository: &str,
    workflow: &str,
    provider_head: &str,
    directory: &Path,
) -> Result<String, String> {
    let bytes = if provider_head == request.candidate {
        read_regular_file(&repository_relative_path(request.root, workflow)?)?
    } else {
        github_raw_source_at(repository, workflow, provider_head)?
    };
    write_atomic(&directory.join("reviewed-provider-workflow.yml"), &bytes)?;
    Ok(sha256_bytes(&bytes).hex())
}

fn provider_review_subject_root(
    reviewed_artifact: &Path,
    workflow: &str,
) -> Result<PathBuf, String> {
    let parent = reviewed_artifact
        .parent()
        .ok_or_else(|| "reviewed provider artifact has no extracted directory".to_owned())?;
    if workflow == ".github/workflows/evidence-custody.yml"
        && reviewed_artifact.file_name().and_then(|name| name.to_str())
            == Some("graph-review-subject.json")
    {
        return parent
            .parent()
            .map(Path::to_path_buf)
            .ok_or_else(|| "final graph subject has no extracted evidence root".to_owned());
    }
    Ok(parent.to_path_buf())
}

fn provider_extracted_file_manifest(
    root: &Path,
    output: &Path,
) -> Result<(JsonValue, String), String> {
    let (manifest, _) = artifact_review_file_manifest(root, output)?;
    let digest = canonical_json_digest(&manifest)?;
    Ok((manifest, digest))
}

fn snapshot_reviewed_files(
    source_root: &Path,
    snapshot_root: &Path,
    manifest: &JsonValue,
) -> Result<(), String> {
    fs::create_dir(snapshot_root).map_err(|error| {
        format!(
            "cannot create sealed reviewed subject {}: {error}",
            snapshot_root.display()
        )
    })?;
    for entry in manifest.array()? {
        let entry = entry.object()?;
        let relative = normalized_manifest_path(json_member(entry, "path")?.string()?)?;
        let source = source_root.join(&relative);
        let destination = snapshot_root.join(&relative);
        let parent = destination
            .parent()
            .ok_or_else(|| "reviewed subject destination has no directory".to_owned())?;
        fs::create_dir_all(parent).map_err(|error| {
            format!(
                "cannot create reviewed subject directory {}: {error}",
                parent.display()
            )
        })?;
        write_atomic(&destination, &read_regular_file(&source)?)?;
    }
    verify_artifact_review_file_manifest_exact(
        snapshot_root,
        manifest,
        &canonical_json_digest(manifest)?,
    )
}

fn normalized_manifest_path(value: &str) -> Result<PathBuf, String> {
    let path = Path::new(value);
    if path.is_absolute()
        || value.contains('\\')
        || path
            .components()
            .any(|component| !matches!(component, std::path::Component::Normal(_)))
    {
        return Err("reviewed subject manifest path is not confined".to_owned());
    }
    Ok(path.to_path_buf())
}

fn verify_final_review_artifact(
    artifact: &BTreeMap<String, JsonValue>,
    expected_name: &str,
    run_id: u64,
) -> Result<u64, String> {
    let artifact_id = json_member(artifact, "id")?.number()?;
    let created_at = json_member(artifact, "created_at")?.string()?;
    let expires_at = json_member(artifact, "expires_at")?.string()?;
    validate_utc_timestamp(created_at)?;
    validate_utc_timestamp(expires_at)?;
    if artifact_id == 0
        || json_member(artifact, "name")?.string()? != expected_name
        || json_member(artifact, "expired")?.boolean()?
        || json_member(artifact, "size_in_bytes")?.number()? == 0
        || utc_timestamp_seconds(expires_at)? <= current_utc_seconds()?
        || json_member(json_member(artifact, "workflow_run")?.object()?, "id")?.number()? != run_id
    {
        return Err("final graph provider artifact identity is invalid".to_owned());
    }
    Ok(artifact_id)
}

fn verify_final_review_run(
    root: &Path,
    run: &BTreeMap<String, JsonValue>,
    candidate: &str,
    repository_id: u64,
    run_id: u64,
    run_attempt: u64,
    workflow: &str,
) -> Result<(String, String, String), String> {
    let workflow_ref = provider_run_workflow_ref(json_member(run, "path")?.string()?, workflow)?;
    let provider_event = json_member(run, "event")?.string()?.to_owned();
    let event_is_valid = match workflow {
        ".github/workflows/mutation.yml" => {
            matches!(provider_event.as_str(), "schedule" | "workflow_dispatch")
        }
        _ => provider_event == "workflow_dispatch",
    };
    let provider_head = json_member(run, "head_sha")?.string()?.to_owned();
    let subject_head_matches = if workflow == ".github/workflows/oracle-reproduce.yml" {
        true
    } else {
        provider_head == candidate
    };
    if json_member(run, "id")?.number()? != run_id
        || json_member(run, "run_attempt")?.number()? != run_attempt
        || !subject_head_matches
        || !event_is_valid
        || json_member(json_member(run, "repository")?.object()?, "id")?.number()? != repository_id
        || (provider_head == candidate && !repository_relative_path(root, workflow)?.is_file())
    {
        return Err("final graph provider run identity is invalid".to_owned());
    }
    require_git_sha_text(&provider_head, "final review provider workflow head")?;
    Ok((workflow_ref, provider_event, provider_head))
}

fn provider_run_workflow_ref(value: &str, expected_path: &str) -> Result<String, String> {
    let (path, reference) = value
        .split_once('@')
        .ok_or_else(|| "provider workflow path does not bind its exact ref".to_owned())?;
    if path != expected_path
        || reference != "main"
        || reference.contains('@')
        || reference.contains('\\')
        || reference.chars().any(char::is_whitespace)
    {
        return Err("provider workflow path/ref identity is invalid".to_owned());
    }
    Ok("refs/heads/main".to_owned())
}

fn retain_review_authorization(
    root: &Path,
    output: &Path,
    facts: &ReviewAuthorizationRetention<'_>,
) -> Result<(), String> {
    let directory = output
        .parent()
        .ok_or_else(|| "review authorization output has no directory".to_owned())?;
    write_atomic(
        &directory.join("environment-approvals.json"),
        facts.approvals_bytes,
    )?;
    write_atomic(
        &directory.join("team-membership.json"),
        facts.membership_bytes,
    )?;
    write_atomic(
        &directory.join("ssh-signing-keys.json"),
        facts.signing_keys_bytes,
    )?;
    let signer_policy = format!(
        "{}:github-account-{} {}\n",
        facts.role, facts.account_id, facts.signing_key
    );
    write_atomic(
        &directory.join("reviewer.allowed_signers"),
        signer_policy.as_bytes(),
    )?;
    let trust_roots = read_regular_file(&root.join("compat").join("trust-roots.toml"))?;
    write_atomic(&directory.join("trust-roots.toml"), &trust_roots)?;
    let surveillance_policy =
        read_regular_file(&root.join("compat").join("surveillance-policy.toml"))?;
    write_atomic(
        &directory.join("surveillance-policy.toml"),
        &surveillance_policy,
    )?;
    let review_revocations =
        read_regular_file(&root.join("compat").join("review-revocations.toml"))?;
    write_atomic(
        &directory.join("review-revocations.toml"),
        &review_revocations,
    )?;
    let exception_issue = facts
        .exception_issue
        .map_or_else(|| "null".to_owned(), json_string);
    let mut record = format!(
        "{{\"schemaVersion\":{schema_version},\"role\":{role},\"candidateCommit\":{candidate},\"decision\":\"accept\",\"reviewedArtifactSha256\":{reviewed_artifact_sha256},\"reviewRationale\":{review_rationale},\"exceptionIssue\":{exception_issue},\"runId\":{run_id},\"runAttempt\":{run_attempt},\"environment\":{environment},\"approvalState\":\"approved\",\"reviewedAt\":{reviewed_at},\"accountId\":{account_id},\"login\":{login},\"team\":{team},\"membershipState\":\"active\",\"authorizationCredentialKind\":\"protected-environment-secret\",\"authorizationCredentialName\":\"REVIEW_AUTHORIZATION_GITHUB_TOKEN\",\"approvalApiPath\":\"environment-approvals.json\",\"approvalApiSha256\":{approval_api_sha256},\"membershipApiPath\":\"team-membership.json\",\"membershipApiSha256\":{membership_api_sha256},\"signingKeyId\":{signing_key_id},\"signingKeysApiPath\":\"ssh-signing-keys.json\",\"signingKeysApiSha256\":{signing_keys_api_sha256},\"signerPolicyPath\":\"reviewer.allowed_signers\",\"signerPolicySha256\":{signer_policy_sha256},\"trustRootsPath\":\"trust-roots.toml\",\"trustRootsSha256\":{trust_roots_sha256},\"surveillancePolicyPath\":\"surveillance-policy.toml\",\"surveillancePolicySha256\":{surveillance_policy_sha256},\"reviewRevocationsPath\":\"review-revocations.toml\",\"reviewRevocationsSha256\":{review_revocations_sha256}",
        schema_version = if facts.provider.is_some() { 2 } else { 1 },
        role = json_string(facts.role),
        candidate = json_string(facts.candidate),
        reviewed_artifact_sha256 = json_string(facts.reviewed_artifact_sha256),
        review_rationale = json_string(facts.review_rationale),
        exception_issue = exception_issue,
        run_id = facts.run_id,
        run_attempt = facts.run_attempt,
        environment = json_string(facts.environment),
        reviewed_at = json_string(facts.reviewed_at),
        account_id = facts.account_id,
        login = json_string(facts.login),
        team = json_string(facts.team),
        signing_key_id = facts.signing_key_id,
        approval_api_sha256 = json_string(&sha256_bytes(facts.approvals_bytes).hex()),
        membership_api_sha256 = json_string(&sha256_bytes(facts.membership_bytes).hex()),
        signing_keys_api_sha256 = json_string(&sha256_bytes(facts.signing_keys_bytes).hex()),
        signer_policy_sha256 = json_string(&sha256_bytes(signer_policy.as_bytes()).hex()),
        trust_roots_sha256 = json_string(&sha256_bytes(&trust_roots).hex()),
        surveillance_policy_sha256 = json_string(&sha256_bytes(&surveillance_policy).hex()),
        review_revocations_sha256 = json_string(&sha256_bytes(&review_revocations).hex()),
    );
    if let Some(provider) = facts.provider {
        write!(
            record,
            ",\"reviewedProviderArtifactId\":{},\"reviewedProviderRepositoryId\":{},\"reviewedProviderArchiveSha256\":{},\"reviewedProviderArtifactApiPath\":\"reviewed-provider-artifact.json\",\"reviewedProviderArtifactApiSha256\":{},\"reviewedProviderRunApiPath\":\"reviewed-provider-run.json\",\"reviewedProviderRunApiSha256\":{},\"reviewedProviderWorkflowPath\":{},\"reviewedProviderWorkflowRef\":{},\"reviewedProviderWorkflowBlobSha256\":{},\"reviewedProviderEvent\":{}",
            provider.artifact_id,
            provider.repository_id,
            json_string(&provider.archive_sha256),
            json_string(&provider.artifact_api_sha256),
            json_string(&provider.run_api_sha256),
            json_string(&provider.workflow_path),
            json_string(&provider.workflow_ref),
            json_string(&provider.workflow_blob_sha256),
            json_string(&provider.provider_event),
        )
        .expect("writing to String cannot fail");
        write!(
            record,
            ",\"reviewedProviderExtractedManifestPath\":\"reviewed-provider-extracted-manifest.json\",\"reviewedProviderExtractedManifestSha256\":{},\"reviewedProviderExtractedRootSha256\":{},\"reviewedProviderExtractedSubjectPath\":\"reviewed-provider-extracted-subject\"",
            json_string(&provider.extracted_manifest_sha256),
            json_string(&provider.extracted_root_sha256),
        )
        .expect("writing to String cannot fail");
    }
    record.push_str("}\n");
    write_atomic(output, record.as_bytes())?;
    Ok(())
}

fn evidence_review_authority(role: &str) -> Result<(&'static str, &'static str), String> {
    match role {
        "artifact-trust-reviewer" => Ok(("security_reviewer_team", "artifact-authenticity-review")),
        "mutation-reviewer" => Ok(("security_reviewer_team", "assurance-mutation-review")),
        "claim-author" => Ok(("claim_author_team", "compatibility-claim-author")),
        "claim-reviewer" | "regression-reviewer" => {
            Ok(("claim_reviewer_team", "compatibility-claim-review"))
        }
        "custody-reviewer" => Ok(("security_reviewer_team", "custody-review")),
        "normalizer-reviewer" => Ok(("claim_reviewer_team", "compatibility-normalizer-review")),
        "platform-reviewer" => Ok(("platform_reviewer_team", "oracle-platform-review")),
        "divergence-reviewer" => Ok(("claim_reviewer_team", "compatibility-divergence-review")),
        "divergence-platform-reviewer" => Ok((
            "platform_reviewer_team",
            "compatibility-divergence-platform-review",
        )),
        "divergence-implementation-reviewer" => Ok((
            "implementation_reviewer_team",
            "compatibility-divergence-implementation-review",
        )),
        "divergence-product-reviewer" => Ok((
            "product_reviewer_team",
            "compatibility-divergence-product-review",
        )),
        "divergence-security-reviewer" => Ok((
            "security_reviewer_team",
            "compatibility-divergence-security-review",
        )),
        "residual-risk-reviewer" => Ok((
            "security_reviewer_team",
            "compatibility-residual-risk-review",
        )),
        "review-graph-reviewer" => {
            Ok(("promotion_approver_team", "compatibility-role-graph-review"))
        }
        "promotion-approver" => Ok(("promotion_approver_team", "compatibility-promotion-review")),
        _ => Err("role has no evidence-review authorization policy".to_owned()),
    }
}

fn select_github_signing_key(keys: &JsonValue, expected_id: u64) -> Result<String, String> {
    let mut selected = None;
    for key in keys.array()? {
        let key = key.object()?;
        exact_keys(key, &["created_at", "id", "key", "title"])?;
        if json_member(key, "id")?.number()? != expected_id {
            continue;
        }
        validate_utc_timestamp(json_member(key, "created_at")?.string()?)?;
        if json_member(key, "title")?.string()?.is_empty() {
            return Err("GitHub SSH signing key has no title".to_owned());
        }
        let value = json_member(key, "key")?.string()?;
        let fields = value.split_ascii_whitespace().collect::<Vec<_>>();
        if fields.len() != 2
            || !matches!(fields[0], "ssh-ed25519" | "ecdsa-sha2-nistp256")
            || fields[1].is_empty()
            || !fields[1]
                .bytes()
                .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'+' | b'/' | b'='))
        {
            return Err(
                "GitHub SSH signing key is not a supported canonical public key".to_owned(),
            );
        }
        if selected.replace(value.to_owned()).is_some() {
            return Err("GitHub repeats the selected SSH signing key ID".to_owned());
        }
    }
    selected.ok_or_else(|| "approved SSH signing key ID is not active on the account".to_owned())
}

fn approved_environment_actor(
    approvals: &JsonValue,
    scope: &ReviewApprovalScope<'_>,
) -> Result<(u64, String, ReviewApprovalDecision), String> {
    let mut matches = Vec::new();
    for approval in approvals.array()? {
        let approval = approval.object()?;
        if json_member(approval, "state")?.string()? != "approved"
            || !json_member(approval, "environments")?
                .array()?
                .iter()
                .any(|environment| {
                    environment
                        .object()
                        .and_then(|object| json_member(object, "name"))
                        .and_then(JsonValue::string)
                        == Ok(scope.environment)
                })
        {
            continue;
        }
        let decision =
            verify_review_approval_comment(json_member(approval, "comment")?.string()?, scope)?;
        let user = json_member(approval, "user")?.object()?;
        let account_id = json_member(user, "id")?.number()?;
        let login = json_member(user, "login")?.string()?.to_owned();
        validate_provider_atom(&login, "environment approver login")?;
        if account_id == 0 {
            return Err("environment approver lacks a stable account ID".to_owned());
        }
        matches.push((account_id, login, decision));
    }
    if matches.len() != 1 {
        return Err(
            "review role requires exactly one retained protected-environment approval".to_owned(),
        );
    }
    matches
        .pop()
        .ok_or_else(|| "review approval selection is empty".to_owned())
}

struct ReviewApprovalScope<'a> {
    environment: &'a str,
    role: &'a str,
    candidate: &'a str,
    reviewed_artifact_sha256: &'a str,
    artifact_exception_required: bool,
}

struct ReviewApprovalDecision {
    reviewed_at: String,
    signing_key_id: u64,
    rationale: String,
    exception_issue: Option<String>,
}

fn verify_review_approval_comment(
    comment: &str,
    scope: &ReviewApprovalScope<'_>,
) -> Result<ReviewApprovalDecision, String> {
    let limits = review_text_limits()?;
    let comment = parse_json(comment)?;
    let comment = comment.object()?;
    exact_keys(
        comment,
        &[
            "candidateCommit",
            "decision",
            "exceptionIssue",
            "reviewRationale",
            "reviewedArtifactSha256",
            "reviewedAt",
            "role",
            "schemaVersion",
            "sshSigningKeyId",
        ],
    )?;
    let reviewed_at = json_member(comment, "reviewedAt")?.string()?.to_owned();
    validate_utc_timestamp(&reviewed_at)?;
    let rationale = json_member(comment, "reviewRationale")?
        .string()?
        .to_owned();
    if rationale.len() < limits.rationale_minimum
        || rationale.len() > limits.rationale_maximum
        || rationale.chars().any(char::is_control)
    {
        return Err("environment approval rationale is missing or unsafe".to_owned());
    }
    let exception_issue = match json_member(comment, "exceptionIssue")? {
        JsonValue::Null => None,
        JsonValue::String(issue)
            if !issue.is_empty()
                && issue.len() <= limits.issue_reference_maximum
                && !issue.chars().any(char::is_whitespace) =>
        {
            Some(issue.clone())
        }
        _ => return Err("environment approval exception issue is invalid".to_owned()),
    };
    if scope.role == "artifact-trust-reviewer" {
        let expected = scope
            .artifact_exception_required
            .then_some("review-required:unavailable-attestation");
        if exception_issue.as_deref() != expected {
            return Err(
                "artifact trust approval exception does not match the reviewed attestation state"
                    .to_owned(),
            );
        }
    }
    let signing_key_id = json_member(comment, "sshSigningKeyId")?.number()?;
    if json_member(comment, "schemaVersion")?.number()? != 2
        || json_member(comment, "candidateCommit")?.string()? != scope.candidate
        || json_member(comment, "decision")?.string()? != "accept"
        || json_member(comment, "role")?.string()? != scope.role
        || json_member(comment, "reviewedArtifactSha256")?.string()?
            != scope.reviewed_artifact_sha256
        || signing_key_id == 0
    {
        return Err(
            "environment approval comment does not exactly scope the review decision".to_owned(),
        );
    }
    Ok(ReviewApprovalDecision {
        reviewed_at,
        signing_key_id,
        rationale,
        exception_issue,
    })
}

fn environment_u64(name: &str, label: &str) -> Result<u64, String> {
    let value = std::env::var(name)
        .map_err(|_| format!("{label} requires {name}"))?
        .parse::<u64>()
        .map_err(|_| format!("{label} {name} is not an integer"))?;
    if value == 0 {
        return Err(format!("{label} {name} must be nonzero"));
    }
    Ok(value)
}

fn verify_review_authorization(
    path: &Path,
    role: &str,
    candidate: &str,
    reviewed_artifact: &Path,
) -> Result<(u64, String, String, String, Option<String>), String> {
    verify_review_authorization_at(
        &repository_root()?,
        path,
        role,
        candidate,
        reviewed_artifact,
    )
}

fn verify_review_authorization_at(
    repository: &Path,
    path: &Path,
    role: &str,
    candidate: &str,
    reviewed_artifact: &Path,
) -> Result<(u64, String, String, String, Option<String>), String> {
    let document = parse_json(&read_text(path)?)?;
    let record = document.object()?;
    let context = review_authorization_context(record, role, candidate, repository)?;
    let retained = RetainedReviewAuthorization::verify(path, record)?;
    let approvals = parse_json(&read_text(&retained.approvals)?)?;
    let reviewed_artifact_sha256 = json_member(record, "reviewedArtifactSha256")?.string()?;
    require_digest(reviewed_artifact_sha256, "authorized reviewed artifact")?;
    if record_digest(reviewed_artifact)? != reviewed_artifact_sha256 {
        return Err("review authorization does not bind the reviewed detail bytes".to_owned());
    }
    if matches!(
        role,
        "review-graph-reviewer"
            | "artifact-trust-reviewer"
            | "claim-author"
            | "claim-reviewer"
            | "custody-reviewer"
            | "mutation-reviewer"
            | "platform-reviewer"
    ) {
        verify_final_review_provider_retention(
            repository,
            path,
            record,
            role,
            candidate,
            reviewed_artifact_sha256,
        )?;
    }
    let scope = ReviewApprovalScope {
        environment: &context.environment,
        role,
        candidate,
        reviewed_artifact_sha256,
        artifact_exception_required: artifact_review_exception_required(reviewed_artifact, role)?,
    };
    let (account_id, login, decision) = approved_environment_actor(&approvals, &scope)?;
    let membership = parse_json(&read_text(&retained.membership)?)?;
    let membership = membership.object()?;
    let membership_user = json_member(membership, "user")?.object()?;
    if json_member(membership, "state")?.string()? != "active"
        || !matches!(
            json_member(membership, "role")?.string()?,
            "member" | "maintainer"
        )
        || json_member(record, "accountId")?.number()? != account_id
        || json_member(record, "login")?.string()? != login
        || json_member(record, "reviewedAt")?.string()? != decision.reviewed_at
        || json_member(record, "reviewRationale")?.string()? != decision.rationale
        || json_member(record, "exceptionIssue")?
            != &decision
                .exception_issue
                .clone()
                .map_or(JsonValue::Null, JsonValue::String)
        || json_member(record, "signingKeyId")?.number()? != decision.signing_key_id
        || json_member(membership_user, "id")?.number()? != account_id
        || json_member(membership_user, "login")?.string()? != login
    {
        return Err("review authorization does not match retained provider facts".to_owned());
    }
    let signing_keys = parse_json(&read_text(&retained.signing_keys)?)?;
    let signing_key = select_github_signing_key(&signing_keys, decision.signing_key_id)?;
    let expected_policy = format!("{role}:github-account-{account_id} {signing_key}\n");
    if read_text(&retained.signer_policy)? != expected_policy
        || read_regular_file(&retained.trust_roots)?
            != read_regular_file(&repository.join("compat").join("trust-roots.toml"))?
        || read_regular_file(&retained.surveillance_policy)?
            != read_regular_file(&repository.join("compat").join("surveillance-policy.toml"))?
        || read_regular_file(&retained.review_revocations)?
            != read_regular_file(&repository.join("compat").join("review-revocations.toml"))?
    {
        return Err("review signer policy is not derived from current provider facts".to_owned());
    }
    Ok((
        account_id,
        login,
        decision.reviewed_at,
        decision.rationale,
        decision.exception_issue,
    ))
}

pub(crate) fn verify_historical_activation_authorization(
    repository: &Path,
    path: &Path,
    role: &str,
    candidate: &str,
    reviewed_artifact: &Path,
) -> Result<String, String> {
    if !matches!(role, "claim-author" | "claim-reviewer") {
        return Err("historical activation authorization role is unsupported".to_owned());
    }
    let document = parse_json(&read_text(path)?)?;
    let record = document.object()?;
    let context = review_authorization_context(record, role, candidate, repository)?;
    let retained = RetainedReviewAuthorization::verify(path, record)?;
    let reviewed_digest = json_member(record, "reviewedArtifactSha256")?.string()?;
    if record_digest(reviewed_artifact)? != reviewed_digest {
        return Err("historical activation authorization subject differs".to_owned());
    }
    let reviewed_at = json_member(record, "reviewedAt")?.string()?.to_owned();
    verify_historical_activation_provider_retention(
        repository,
        path,
        record,
        role,
        candidate,
        &reviewed_at,
    )?;
    let approvals = parse_json(&read_text(&retained.approvals)?)?;
    let scope = ReviewApprovalScope {
        environment: &context.environment,
        role,
        candidate,
        reviewed_artifact_sha256: reviewed_digest,
        artifact_exception_required: false,
    };
    let (account_id, login, decision) = approved_environment_actor(&approvals, &scope)?;
    let membership = parse_json(&read_text(&retained.membership)?)?;
    let membership = membership.object()?;
    let member = json_member(membership, "user")?.object()?;
    let signing_keys = parse_json(&read_text(&retained.signing_keys)?)?;
    let signing_key = select_github_signing_key(
        &signing_keys,
        json_member(record, "signingKeyId")?.number()?,
    )?;
    if json_member(record, "accountId")?.number()? != account_id
        || json_member(record, "login")?.string()? != login
        || decision.reviewed_at != reviewed_at
        || json_member(membership, "state")?.string()? != "active"
        || json_member(member, "id")?.number()? != account_id
        || json_member(member, "login")?.string()? != login
        || read_text(&retained.signer_policy)?
            != format!("{role}:github-account-{account_id} {signing_key}\n")
        || read_regular_file(&retained.trust_roots)?
            != read_regular_file(&repository.join("compat/trust-roots.toml"))?
        || read_regular_file(&retained.surveillance_policy)?
            != read_regular_file(&repository.join("compat/surveillance-policy.toml"))?
        || read_regular_file(&retained.review_revocations)?
            != read_regular_file(&repository.join("compat/review-revocations.toml"))?
    {
        return Err("historical activation authorization provider facts differ".to_owned());
    }
    Ok(reviewed_at)
}

fn verify_historical_activation_provider_retention(
    repository: &Path,
    path: &Path,
    record: &BTreeMap<String, JsonValue>,
    role: &str,
    candidate: &str,
    reviewed_at: &str,
) -> Result<(), String> {
    let parent = path
        .parent()
        .ok_or_else(|| "historical activation authorization has no directory".to_owned())?;
    let artifact_path = parent.join("reviewed-provider-artifact.json");
    let run_path = parent.join("reviewed-provider-run.json");
    let extracted_manifest_path = parent.join("reviewed-provider-extracted-manifest.json");
    let extracted_subject_path = parent.join("reviewed-provider-extracted-subject");
    let artifact_document = parse_json(&read_text(&artifact_path)?)?;
    let artifact = artifact_document.object()?;
    let run_id = json_member(record, "runId")?.number()?;
    let run_attempt = json_member(record, "runAttempt")?.number()?;
    let (artifact_name, workflow) = retained_review_subject_identity(
        role,
        run_id,
        run_attempt,
        json_member(artifact, "name")?.string()?,
    )?;
    let created = utc_timestamp_seconds(json_member(artifact, "created_at")?.string()?)?;
    let expires = utc_timestamp_seconds(json_member(artifact, "expires_at")?.string()?)?;
    let reviewed = utc_timestamp_seconds(reviewed_at)?;
    let artifact_id = json_member(artifact, "id")?.number()?;
    let archive_url = json_member(artifact, "archive_download_url")?.string()?;
    let expected_archive_url = format!(
        "https://api.github.com/repos/Portfoligno/hell-rs/actions/artifacts/{artifact_id}/zip"
    );
    let archive = json_member(artifact, "digest")?
        .string()?
        .strip_prefix("sha256:")
        .ok_or_else(|| "historical activation archive is not SHA-256".to_owned())?;
    require_digest(archive, "historical activation provider archive")?;
    if artifact_id == 0
        || json_member(artifact, "name")?.string()? != artifact_name
        || json_member(artifact, "expired")?.boolean()?
        || json_member(artifact, "size_in_bytes")?.number()? == 0
        || archive_url != expected_archive_url
        || json_member(json_member(artifact, "workflow_run")?.object()?, "id")?.number()? != run_id
        || !(created <= reviewed && reviewed < expires)
        || json_member(record, "reviewedProviderArtifactId")?.number()? != artifact_id
        || json_member(record, "reviewedProviderArchiveSha256")?.string()? != archive
    {
        return Err("historical activation artifact was not live at review time".to_owned());
    }
    verify_named_retained_file(
        record,
        &artifact_path,
        "reviewedProviderArtifactApiPath",
        "reviewedProviderArtifactApiSha256",
        "reviewed-provider-artifact.json",
    )?;
    verify_named_retained_file(
        record,
        &run_path,
        "reviewedProviderRunApiPath",
        "reviewedProviderRunApiSha256",
        "reviewed-provider-run.json",
    )?;
    verify_named_retained_file(
        record,
        &extracted_manifest_path,
        "reviewedProviderExtractedManifestPath",
        "reviewedProviderExtractedManifestSha256",
        "reviewed-provider-extracted-manifest.json",
    )?;
    if json_member(record, "reviewedProviderExtractedSubjectPath")?.string()?
        != "reviewed-provider-extracted-subject"
    {
        return Err("historical activation extracted subject path is invalid".to_owned());
    }
    let extracted_manifest = parse_json(&read_text(&extracted_manifest_path)?)?;
    verify_artifact_review_file_manifest_exact(
        &extracted_subject_path,
        &extracted_manifest,
        json_member(record, "reviewedProviderExtractedRootSha256")?.string()?,
    )?;
    if record_digest(&extracted_subject_path.join("review-subject.json"))?
        != json_member(record, "reviewedArtifactSha256")?.string()?
    {
        return Err("historical provider snapshot reviewed a different subject".to_owned());
    }
    verify_retained_provider_run(
        repository,
        record,
        &run_path,
        candidate,
        run_id,
        run_attempt,
        workflow,
    )
}

struct ReviewAuthorizationContext {
    environment: String,
}

fn review_authorization_context(
    record: &BTreeMap<String, JsonValue>,
    role: &str,
    candidate: &str,
    repository: &Path,
) -> Result<ReviewAuthorizationContext, String> {
    let provider_bound = matches!(
        role,
        "review-graph-reviewer"
            | "artifact-trust-reviewer"
            | "claim-author"
            | "claim-reviewer"
            | "custody-reviewer"
            | "mutation-reviewer"
            | "platform-reviewer"
    );
    exact_keys(
        record,
        if provider_bound {
            FINAL_REVIEW_AUTHORIZATION_KEYS
        } else {
            REVIEW_AUTHORIZATION_KEYS
        },
    )?;
    let (team_key, environment) = evidence_review_authority(role)?;
    let policy = read_text(&repository.join("compat").join("review-policy.toml"))?;
    let team = assignment_string(&policy, team_key)?;
    if json_member(record, "schemaVersion")?.number()? != if provider_bound { 2 } else { 1 }
        || json_member(record, "role")?.string()? != role
        || json_member(record, "candidateCommit")?.string()? != candidate
        || json_member(record, "decision")?.string()? != "accept"
        || json_member(record, "environment")?.string()? != environment
        || json_member(record, "team")?.string()? != team
        || json_member(record, "approvalState")?.string()? != "approved"
        || json_member(record, "membershipState")?.string()? != "active"
        || json_member(record, "authorizationCredentialKind")?.string()?
            != "protected-environment-secret"
        || json_member(record, "authorizationCredentialName")?.string()?
            != "REVIEW_AUTHORIZATION_GITHUB_TOKEN"
        || json_member(record, "runId")?.number()? == 0
        || json_member(record, "runAttempt")?.number()? == 0
    {
        return Err("review authorization identity or state is invalid".to_owned());
    }
    Ok(ReviewAuthorizationContext {
        environment: environment.to_owned(),
    })
}

