fn verify_final_review_provider_retention(
    repository: &Path,
    path: &Path,
    record: &BTreeMap<String, JsonValue>,
    role: &str,
    candidate: &str,
    reviewed_artifact_sha256: &str,
) -> Result<(), String> {
    let parent = path
        .parent()
        .ok_or_else(|| "final graph authorization has no retained directory".to_owned())?;
    let artifact_path = parent.join("reviewed-provider-artifact.json");
    let run_path = parent.join("reviewed-provider-run.json");
    let extracted_manifest_path = parent.join("reviewed-provider-extracted-manifest.json");
    let extracted_subject_path = parent.join("reviewed-provider-extracted-subject");
    verify_named_retained_file(
        record,
        &artifact_path,
        "reviewedProviderArtifactApiPath",
        "reviewedProviderArtifactApiSha256",
        "reviewed-provider-artifact.json",
    )?;
    verify_named_retained_file(
        record,
        &extracted_manifest_path,
        "reviewedProviderExtractedManifestPath",
        "reviewedProviderExtractedManifestSha256",
        "reviewed-provider-extracted-manifest.json",
    )?;
    verify_named_retained_file(
        record,
        &run_path,
        "reviewedProviderRunApiPath",
        "reviewedProviderRunApiSha256",
        "reviewed-provider-run.json",
    )?;
    let artifact_document = parse_json(&read_text(&artifact_path)?)?;
    let artifact = artifact_document.object()?;
    let run_id = json_member(record, "runId")?.number()?;
    let run_attempt = json_member(record, "runAttempt")?.number()?;
    let retained_artifact_name = json_member(artifact, "name")?.string()?;
    let (artifact_name, workflow) =
        retained_review_subject_identity(role, run_id, run_attempt, retained_artifact_name)?;
    let extracted_manifest = parse_json(&read_text(&extracted_manifest_path)?)?;
    if json_member(record, "reviewedProviderExtractedSubjectPath")?.string()?
        != "reviewed-provider-extracted-subject"
    {
        return Err("reviewed provider extracted subject path is invalid".to_owned());
    }
    verify_artifact_review_file_manifest_exact(
        &extracted_subject_path,
        &extracted_manifest,
        json_member(record, "reviewedProviderExtractedRootSha256")?.string()?,
    )?;
    let artifact_id = verify_final_review_artifact(artifact, &artifact_name, run_id)?;
    let archive_sha256 = json_member(artifact, "digest")?
        .string()?
        .strip_prefix("sha256:")
        .ok_or_else(|| "retained final graph artifact digest is not SHA-256".to_owned())?;
    if json_member(record, "reviewedProviderArtifactId")?.number()? != artifact_id
        || json_member(record, "reviewedProviderArchiveSha256")?.string()? != archive_sha256
    {
        return Err("final graph authorization changes retained provider identity".to_owned());
    }
    verify_retained_provider_run(
        repository,
        record,
        &run_path,
        candidate,
        run_id,
        run_attempt,
        workflow,
    )?;
    require_digest(
        reviewed_artifact_sha256,
        "retained final graph reviewed subject",
    )
}

fn retained_review_subject_identity(
    role: &str,
    run_id: u64,
    run_attempt: u64,
    retained_artifact_name: &str,
) -> Result<(String, &'static str), String> {
    match role {
        "review-graph-reviewer" => Ok((
            final_review_subject_name(run_id, run_attempt),
            ".github/workflows/evidence-custody.yml",
        )),
        "artifact-trust-reviewer" => Ok((
            artifact_review_subject_name(run_id, run_attempt),
            ".github/workflows/artifact-authenticity-finalize.yml",
        )),
        "mutation-reviewer" => Ok((
            mutation_review_subject_name(run_id, run_attempt),
            ".github/workflows/mutation.yml",
        )),
        "platform-reviewer" => {
            let accepted = ["macos-arm64", "windows-amd64"]
                .into_iter()
                .map(|platform| oracle_platform_review_subject_name(run_id, run_attempt, platform))
                .collect::<Result<Vec<_>, _>>()?;
            if !accepted.iter().any(|name| name == retained_artifact_name) {
                return Err("retained oracle platform subject artifact name is invalid".to_owned());
            }
            Ok((
                retained_artifact_name.to_owned(),
                ".github/workflows/oracle-reproduce.yml",
            ))
        }
        "custody-reviewer" => Ok((
            custody_review_subject_name(run_id, run_attempt),
            ".github/workflows/evidence-custody.yml",
        )),
        "claim-author" | "claim-reviewer" => Ok((
            collection_activation_subject_name(run_id, run_attempt),
            ".github/workflows/collection-activation.yml",
        )),
        _ => Err("provider-bound authorization role is unsupported".to_owned()),
    }
}

fn verify_retained_provider_run(
    repository: &Path,
    record: &BTreeMap<String, JsonValue>,
    run_path: &Path,
    candidate: &str,
    run_id: u64,
    run_attempt: u64,
    workflow: &str,
) -> Result<(), String> {
    let repository_id = json_member(record, "reviewedProviderRepositoryId")?.number()?;
    let configured_repository_id = load_acquisition_policy(repository)?
        .repository_id
        .ok_or_else(|| "retained final graph repository ID is not configured".to_owned())?
        .parse::<u64>()
        .map_err(|_| "configured repository ID is invalid".to_owned())?;
    if repository_id != configured_repository_id {
        return Err("retained final graph repository ID differs from policy".to_owned());
    }
    let run_document = parse_json(&read_text(run_path)?)?;
    let run = run_document.object()?;
    if json_member(json_member(run, "repository")?.object()?, "full_name")?.string()?
        != "Portfoligno/hell-rs"
    {
        return Err("retained final graph repository name differs".to_owned());
    }
    let (workflow_ref, provider_event, _) = verify_final_review_run(
        repository,
        run,
        candidate,
        repository_id,
        run_id,
        run_attempt,
        workflow,
    )?;
    if json_member(record, "reviewedProviderWorkflowPath")?.string()? != workflow
        || json_member(record, "reviewedProviderWorkflowRef")?.string()? != workflow_ref
        || json_member(record, "reviewedProviderEvent")?.string()? != provider_event
        || json_member(record, "reviewedProviderWorkflowBlobSha256")?.string()?
            != record_digest(
                &run_path
                    .parent()
                    .ok_or_else(|| "retained provider run lacks a directory".to_owned())?
                    .join("reviewed-provider-workflow.yml"),
            )?
        || record_digest(
            &run_path
                .parent()
                .ok_or_else(|| "retained provider run lacks a directory".to_owned())?
                .join("reviewed-provider-workflow.yml"),
        )? != record_digest(&repository.join(workflow))?
    {
        return Err("final review provider workflow binding is stale".to_owned());
    }
    Ok(())
}

fn verify_named_retained_file(
    record: &BTreeMap<String, JsonValue>,
    path: &Path,
    path_key: &str,
    digest_key: &str,
    expected_name: &str,
) -> Result<(), String> {
    if json_member(record, path_key)?.string()? != expected_name {
        return Err("final graph provider retention path is invalid".to_owned());
    }
    verify_file_digest(path, json_member(record, digest_key)?.string()?, path_key)
}

struct RetainedReviewAuthorization {
    approvals: PathBuf,
    membership: PathBuf,
    signing_keys: PathBuf,
    signer_policy: PathBuf,
    trust_roots: PathBuf,
    surveillance_policy: PathBuf,
    review_revocations: PathBuf,
}

impl RetainedReviewAuthorization {
    fn verify(path: &Path, record: &BTreeMap<String, JsonValue>) -> Result<Self, String> {
        let parent = path
            .parent()
            .ok_or_else(|| "review authorization has no retained directory".to_owned())?;
        let retained = Self {
            approvals: parent.join("environment-approvals.json"),
            membership: parent.join("team-membership.json"),
            signing_keys: parent.join("ssh-signing-keys.json"),
            signer_policy: parent.join("reviewer.allowed_signers"),
            trust_roots: parent.join("trust-roots.toml"),
            surveillance_policy: parent.join("surveillance-policy.toml"),
            review_revocations: parent.join("review-revocations.toml"),
        };
        retained.verify_paths(record)?;
        Ok(retained)
    }

    fn verify_paths(&self, record: &BTreeMap<String, JsonValue>) -> Result<(), String> {
        let files = [
            (
                &self.approvals,
                "approvalApiPath",
                "approvalApiSha256",
                "environment-approvals.json",
            ),
            (
                &self.membership,
                "membershipApiPath",
                "membershipApiSha256",
                "team-membership.json",
            ),
            (
                &self.signing_keys,
                "signingKeysApiPath",
                "signingKeysApiSha256",
                "ssh-signing-keys.json",
            ),
            (
                &self.signer_policy,
                "signerPolicyPath",
                "signerPolicySha256",
                "reviewer.allowed_signers",
            ),
            (
                &self.trust_roots,
                "trustRootsPath",
                "trustRootsSha256",
                "trust-roots.toml",
            ),
            (
                &self.surveillance_policy,
                "surveillancePolicyPath",
                "surveillancePolicySha256",
                "surveillance-policy.toml",
            ),
            (
                &self.review_revocations,
                "reviewRevocationsPath",
                "reviewRevocationsSha256",
                "review-revocations.toml",
            ),
        ];
        for (path, path_key, digest_key, expected_path) in files {
            if json_member(record, path_key)?.string()? != expected_path {
                return Err("review authorization retained path is invalid".to_owned());
            }
            verify_file_digest(path, json_member(record, digest_key)?.string()?, path_key)?;
        }
        Ok(())
    }
}

fn review_packet_artifacts(input: &Path, role: &str) -> Result<BTreeSet<String>, String> {
    let digest = record_digest(input)?;
    if matches!(role, "platform-reviewer" | "custody-reviewer") {
        let (_, _, mut artifacts) = protected_review_subject(input, role)?;
        if !artifacts.insert(digest) {
            return Err(
                "protected review subject digest duplicates a reviewed artifact".to_owned(),
            );
        }
        return Ok(artifacts);
    }
    if role == "artifact-trust-reviewer" {
        let primary = parse_acquisition_receipt_state(&input.join("receipt-primary.json"), true)?;
        let independent =
            parse_acquisition_receipt_state(&input.join("receipt-independent.json"), true)?;
        if primary.artifact != independent.artifact
            || primary.observed_sha256 != independent.observed_sha256
            || primary.observed_size != independent.observed_size
            || primary.provider_artifact_id != independent.provider_artifact_id
            || primary.repository_id != independent.repository_id
            || primary.run_id != independent.run_id
            || primary.run_attempt != independent.run_attempt
            || primary.candidate_commit != independent.candidate_commit
            || primary.acquirer_account_id == independent.acquirer_account_id
            || primary.acquisition_tool
                != "actions/download-artifact@70fc10c6e5e1ce46ad2ea6f2b72d43f7d47b13c3"
            || independent.acquisition_tool != "curl-aws-sigv4-v1"
        {
            return Err(
                "artifact review packet receipts are not matching and independent".to_owned(),
            );
        }
        verify_independent_trust_domains(&primary.trust_domain, &independent.trust_domain)?;
        let attestation = verify_artifact_attestation(
            &input.join("attestation-verification.json"),
            &primary.observed_sha256,
            &primary.artifact,
            &primary.candidate_commit,
        )?;
        let mut artifacts = BTreeSet::from([
            acquisition_receipt_core_digest(&primary),
            acquisition_receipt_core_digest(&independent),
            primary.observed_sha256.clone(),
            attestation,
            record_digest(&input.join("receipt-primary.producer.dsse.json"))?,
            record_digest(&input.join("receipt-independent.producer.dsse.json"))?,
        ]);
        for label in ["primary", "independent"] {
            let directory = input.join("source-selection").join(label);
            for file in [
                "selection.json",
                "provider-selected-artifact.json",
                "provider-selected-run.json",
            ] {
                if !artifacts.insert(record_digest(&directory.join(file))?) {
                    return Err("artifact source selection repeats a reviewed digest".to_owned());
                }
            }
        }
        return Ok(artifacts);
    }
    if role == "mutation-reviewer" {
        let report = parse_json(&read_text(input)?)?;
        let report = report.object()?;
        return Ok(BTreeSet::from([mutation_report_core_digest(report)?]));
    }
    if role == "claim-reviewer" {
        let report = parse_json(&read_text(input)?)?;
        let report = report.object()?;
        if json_member(report, "schemaVersion")?.number()? != 2 {
            return Err("claim reviewer requires finalized applicability schema v2".to_owned());
        }
        return Ok(BTreeSet::from([
            digest,
            json_member(report, "sourceCoverageSha256")?
                .string()?
                .to_owned(),
            json_member(report, "applicabilityDecisionsSha256")?
                .string()?
                .to_owned(),
        ]));
    }
    if role != "promotion-approver" {
        return Ok(BTreeSet::from([digest]));
    }
    promotion_approval_artifacts(input, &digest)
}

fn collection_activation_review_artifacts(
    input: &Path,
    role: &str,
) -> Result<BTreeSet<String>, String> {
    collection_activation_review_artifacts_at(&repository_root()?, input, role)
}

fn collection_activation_review_artifacts_at(
    root: &Path,
    input: &Path,
    role: &str,
) -> Result<BTreeSet<String>, String> {
    if !matches!(role, "claim-author" | "claim-reviewer")
        || input.file_name().and_then(|name| name.to_str()) != Some("review-subject.json")
    {
        return Err("collection activation review subject or role is invalid".to_owned());
    }
    let directory = input
        .parent()
        .ok_or_else(|| "collection activation review subject has no directory".to_owned())?;
    crate::collection_custody::activation_review_subject_artifacts(root, directory)
}

fn promotion_approval_artifacts(input: &Path, digest: &str) -> Result<BTreeSet<String>, String> {
    let proposal = parse_json(&read_text(input)?)?;
    let proposal = proposal.object()?;
    if json_member(proposal, "blockerCount")?.number()? != 0
        || !json_member(proposal, "readyForExplicitGate")?.boolean()?
    {
        return Err("promotion approver packet requires a mechanically ready proposal".to_owned());
    }
    let retained = input
        .parent()
        .ok_or_else(|| "promotion proposal has no retained package directory".to_owned())?;
    verify_final_merged_readiness(
        proposal,
        &read_regular_file(&retained.join("merged-native-shards.json"))?,
        &read_regular_file(&retained.join("merged-native-shards.final.json"))?,
    )?;
    let mut artifacts = proposal_review_artifacts(proposal, digest)?;
    let selection = retained.join("proposal-provider-selection.json");
    if !artifacts.insert(record_digest(&selection)?) {
        return Err("proposal provider selection duplicates another reviewed artifact".to_owned());
    }
    Ok(artifacts)
}

fn review_sign(options: &Options) -> Result<String, String> {
    let input = required_path(&options.input, "review-sign requires --packet")?;
    let output = required_path(&options.output, "review-sign requires --output")?;
    let role = options
        .role
        .as_deref()
        .ok_or_else(|| "review-sign requires --role".to_owned())?;
    let decision = options
        .decision
        .as_deref()
        .ok_or_else(|| "review-sign requires --decision".to_owned())?;
    let payload = read_regular_file(input)?;
    let payload_text =
        std::str::from_utf8(&payload).map_err(|_| "review-sign packet is not UTF-8".to_owned())?;
    let payload_json = parse_json(payload_text)?;
    let payload_object = payload_json.object()?;
    let reviewer = json_member(payload_object, "reviewer")?
        .string()?
        .to_owned();
    if let Ok(expected_reviewer) = std::env::var("HELL_REVIEWER_ID")
        && expected_reviewer != reviewer
    {
        return Err("HELL_REVIEWER_ID does not match the content-bound packet".to_owned());
    }
    if json_member(payload_object, "role")?.string()? != role
        || json_member(payload_object, "decision")?.string()? != decision
        || json_member(payload_object, "reviewer")?.string()? != reviewer
    {
        return Err("review-sign options do not match the content-bound packet".to_owned());
    }
    let key = std::env::var_os("HELL_REVIEW_SIGNING_KEY").map(PathBuf::from);
    let signatures = sign_review_payload(
        &payload,
        key.as_deref(),
        options.policy.as_deref(),
        &reviewer,
    )?;
    let envelope = format!(
        "{{\n  \"payloadType\": \"application/vnd.hell-rs.assurance+json\",\n  \"payload\": {},\n  \"signatures\": [{{\"scheme\": \"ssh\", \"keyid\": {}, \"sig\": {}}}, {{\"scheme\": \"sigstore\", \"bundle\": {}, \"certificateIdentity\": {}, \"certificateIssuer\": {}}}]\n}}\n",
        json_string(&encode_base64(&payload)),
        json_string(&reviewer),
        json_string(&encode_base64(&signatures.ssh)),
        json_string(&encode_base64(&signatures.sigstore_bundle)),
        json_string(&signatures.sigstore_identity),
        json_string(&signatures.sigstore_issuer),
    );
    write_atomic(output, envelope.as_bytes())?;
    write_digest_sibling(output, sha256_bytes(envelope.as_bytes()))?;
    Ok(format!("wrote signed review envelope {}", output.display()))
}

const TRANSPORT_PROBE_MEDIA_TYPE: &str =
    "application/vnd.hell-rs.assurance-transport-readiness+json";
const TRANSPORT_PROBE_DOMAIN: &str = "hell-rs-assurance-transport-readiness-v1";
const TRANSPORT_PROBE_ROLES: &[&str] =
    &["assurance-transport-probe-a", "assurance-transport-probe-b"];

fn auth_transport_probe(root: &Path, options: &Options) -> Result<String, String> {
    match options.action.as_deref() {
        Some("subject") => auth_transport_probe_subject(options),
        Some("context") => auth_transport_probe_context(root, options),
        Some("context-verify") => auth_transport_probe_context_verify(root, options),
        Some("packet") => auth_transport_probe_packet(options),
        Some("sign") => auth_transport_probe_sign(options),
        Some("verify") => auth_transport_probe_verify(options),
        Some("aggregate") => auth_transport_probe_aggregate(root, options),
        action => Err(format!(
            "unsupported auth-transport-probe action {:?}",
            action.unwrap_or_default()
        )),
    }
}

fn auth_transport_probe_context_verify(root: &Path, options: &Options) -> Result<String, String> {
    let context = required_path(
        &options.input,
        "auth-transport-probe context-verify requires --input context",
    )?;
    let subject = required_path(
        &options.program,
        "auth-transport-probe context-verify requires --program subject",
    )?;
    let selection = required_path(
        &options.from,
        "auth-transport-probe context-verify requires --from selection",
    )?;
    let context = parse_json(&read_text(context)?)?;
    verify_transport_probe_context_provider(root, context.object()?, subject, selection)?;
    Ok("reverified transport probe context against exact subject provider".to_owned())
}

fn verify_transport_probe_context_provider(
    root: &Path,
    context: &BTreeMap<String, JsonValue>,
    subject: &Path,
    selection_root: &Path,
) -> Result<(), String> {
    verify_transport_probe_context(context)?;
    let selection = parse_json(&read_text(&selection_root.join("selection.json"))?)?;
    let selection = selection.object()?;
    let candidate = json_member(context, "candidateCommit")?.string()?;
    reverify_regression_provider_selection(
        root,
        subject,
        selection_root,
        candidate,
        ".github/workflows/assurance-transport-readiness.yml",
    )?;
    let retained_run = parse_json(&read_text(
        &selection_root.join("provider-selected-run.json"),
    )?)?;
    let retained_run = retained_run.object()?;
    let selection_sha256 = record_digest(&selection_root.join("selection.json"))?;
    let subject_sha256 = record_digest(subject)?;
    let nonce = sha256_bytes(
        format!("{TRANSPORT_PROBE_DOMAIN}\0{selection_sha256}\0{subject_sha256}").as_bytes(),
    )
    .hex();
    let repository_id = json_member(selection, "repositoryId")?
        .string()?
        .parse::<u64>()
        .map_err(|_| "transport probe repository ID is malformed".to_owned())?;
    if json_member(context, "candidateCommit")?.string()?
        != json_member(selection, "candidateCommit")?.string()?
        || json_member(context, "event")?.string()? != json_member(selection, "event")?.string()?
        || json_member(context, "repositoryId")?.number()? != repository_id
        || json_member(context, "runId")?.number()?
            != json_member(selection, "providerRunId")?.number()?
        || json_member(context, "runAttempt")?.number()?
            != json_member(selection, "providerRunAttempt")?.number()?
        || json_member(context, "subjectArtifactId")?.number()?
            != json_member(selection, "providerArtifactId")?.number()?
        || json_member(context, "subjectArtifactName")?.string()?
            != json_member(selection, "artifact")?.string()?
        || json_member(context, "subjectProviderSelectionSha256")?.string()? != selection_sha256
        || json_member(context, "subjectSha256")?.string()? != subject_sha256
        || json_member(context, "nonceSha256")?.string()? != nonce
        || json_member(context, "workflowHeadSha")?.string()?
            != json_member(retained_run, "head_sha")?.string()?
    {
        return Err("transport probe context differs from exact subject provider facts".to_owned());
    }
    Ok(())
}

fn auth_transport_probe_subject(options: &Options) -> Result<String, String> {
    let output = required_path(
        &options.output,
        "auth-transport-probe subject requires --output directory",
    )?;
    let repository = std::env::var("GITHUB_REPOSITORY")
        .map_err(|_| "transport probe subject requires GITHUB_REPOSITORY".to_owned())?;
    let workflow_ref = std::env::var("GITHUB_WORKFLOW_REF")
        .map_err(|_| "transport probe subject requires GITHUB_WORKFLOW_REF".to_owned())?;
    let head = std::env::var("GITHUB_SHA")
        .map_err(|_| "transport probe subject requires GITHUB_SHA".to_owned())?;
    let event = std::env::var("GITHUB_EVENT_NAME")
        .map_err(|_| "transport probe subject requires GITHUB_EVENT_NAME".to_owned())?;
    let run_id = environment_u64("GITHUB_RUN_ID", "transport probe subject run")?;
    let run_attempt = environment_u64("GITHUB_RUN_ATTEMPT", "transport probe subject attempt")?;
    require_git_sha_text(&head, "transport probe subject head")?;
    if repository != "Portfoligno/hell-rs"
        || workflow_ref
            != "Portfoligno/hell-rs/.github/workflows/assurance-transport-readiness.yml@refs/heads/main"
        || event != "workflow_dispatch"
    {
        return Err("transport probe subject is not trusted current-main dispatch".to_owned());
    }
    let nonce = sha256_bytes(
        format!(
            "{TRANSPORT_PROBE_DOMAIN}\0{repository}\0{workflow_ref}\0{head}\0{run_id}\0{run_attempt}"
        )
        .as_bytes(),
    )
    .hex();
    let subject = JsonValue::Object(BTreeMap::from([
        (
            "authorityDomain".to_owned(),
            JsonValue::String(TRANSPORT_PROBE_DOMAIN.to_owned()),
        ),
        (
            "event".to_owned(),
            JsonValue::String("workflow_dispatch".to_owned()),
        ),
        ("nonceSha256".to_owned(), JsonValue::String(nonce)),
        ("repository".to_owned(), JsonValue::String(repository)),
        ("runAttempt".to_owned(), JsonValue::Number(run_attempt)),
        ("runId".to_owned(), JsonValue::Number(run_id)),
        ("schemaVersion".to_owned(), JsonValue::Number(1)),
        ("workflowHeadSha".to_owned(), JsonValue::String(head)),
        ("workflowRef".to_owned(), JsonValue::String(workflow_ref)),
    ]));
    fs::create_dir_all(output)
        .map_err(|error| format!("cannot create transport probe subject: {error}"))?;
    let subject = canonical_json_bytes(&subject)?;
    write_atomic(&output.join("probe-subject.json"), &subject)?;
    Ok("wrote isolated unprivileged transport probe subject".to_owned())
}

fn auth_transport_probe_packet(options: &Options) -> Result<String, String> {
    let input = required_path(
        &options.input,
        "auth-transport-probe packet requires --input context",
    )?;
    let output = required_path(
        &options.output,
        "auth-transport-probe packet requires --output",
    )?;
    let policy = required_path(
        &options.policy,
        "auth-transport-probe packet requires --policy",
    )?;
    let role = transport_probe_role(options)?;
    let reviewer = options
        .expected
        .as_deref()
        .ok_or_else(|| "auth-transport-probe packet requires --expected reviewer".to_owned())?;
    if !reviewer.starts_with(&format!("{role}:")) {
        return Err("transport probe reviewer is not role-qualified".to_owned());
    }
    let context = parse_json(&read_text(input)?)?;
    let context = context.object()?;
    verify_transport_probe_context(context)?;
    verify_transport_probe_repository_id(context, policy)?;
    let mut packet = context.clone();
    packet.insert(
        "reviewer".to_owned(),
        JsonValue::String(reviewer.to_owned()),
    );
    packet.insert("role".to_owned(), JsonValue::String(role.to_owned()));
    let identity = transport_probe_statement_id(&packet)?;
    packet.insert("statementId".to_owned(), JsonValue::String(identity));
    let packet = canonical_json_bytes(&JsonValue::Object(packet))?;
    write_atomic(output, &packet)?;
    write_digest_sibling(output, sha256_bytes(&packet))?;
    Ok(format!("wrote isolated {role} transport probe packet"))
}

fn auth_transport_probe_sign(options: &Options) -> Result<String, String> {
    let input = required_path(
        &options.input,
        "auth-transport-probe sign requires --input packet",
    )?;
    let output = required_path(
        &options.output,
        "auth-transport-probe sign requires --output",
    )?;
    let policy = required_path(
        &options.policy,
        "auth-transport-probe sign requires --policy",
    )?;
    let role = transport_probe_role(options)?;
    let payload = read_regular_file(input)?;
    let packet = parse_json(
        std::str::from_utf8(&payload)
            .map_err(|_| "transport probe packet is not UTF-8".to_owned())?,
    )?;
    let packet = packet.object()?;
    verify_transport_probe_packet(packet, role)?;
    verify_transport_probe_repository_id(packet, policy)?;
    let reviewer = json_member(packet, "reviewer")?.string()?;
    if std::env::var("HELL_REVIEWER_ID").as_deref() != Ok(reviewer) {
        return Err("HELL_REVIEWER_ID does not match the transport probe packet".to_owned());
    }
    let signatures = sign_review_payload(&payload, None, Some(policy), reviewer)?;
    let envelope = format!(
        "{{\n  \"payloadType\": {},\n  \"payload\": {},\n  \"signatures\": [{{\"scheme\": \"ssh\", \"keyid\": {}, \"sig\": {}}}, {{\"scheme\": \"sigstore\", \"bundle\": {}, \"certificateIdentity\": {}, \"certificateIssuer\": {}}}]\n}}\n",
        json_string(TRANSPORT_PROBE_MEDIA_TYPE),
        json_string(&encode_base64(&payload)),
        json_string(reviewer),
        json_string(&encode_base64(&signatures.ssh)),
        json_string(&encode_base64(&signatures.sigstore_bundle)),
        json_string(&signatures.sigstore_identity),
        json_string(&signatures.sigstore_issuer),
    );
    write_atomic(output, envelope.as_bytes())?;
    write_digest_sibling(output, sha256_bytes(envelope.as_bytes()))?;
    Ok(format!("wrote isolated {role} transport probe envelope"))
}

fn auth_transport_probe_verify(options: &Options) -> Result<String, String> {
    let input = required_path(
        &options.input,
        "auth-transport-probe verify requires --input envelope",
    )?;
    let policy = required_path(
        &options.policy,
        "auth-transport-probe verify requires --policy",
    )?;
    let role = transport_probe_role(options)?;
    verified_transport_probe_envelope(input, policy, role)?;
    Ok(format!(
        "verified isolated {role} SSH, OIDC, and transparency transport"
    ))
}

struct VerifiedTransportProbe {
    context: BTreeMap<String, JsonValue>,
    envelope_sha256: String,
    packet_artifact_id: u64,
    packet_provider_selection_sha256: String,
    payload_sha256: String,
    reviewer: String,
    role: String,
    sigstore_identity: String,
    ssh_fingerprint: String,
    statement_id: String,
    provider_selection_sha256: String,
}

fn verified_transport_probe_envelope(
    input: &Path,
    policy: &Path,
    role: &str,
) -> Result<VerifiedTransportProbe, String> {
    let document = read_text(input)?;
    if admit_review_envelope_bytes(document.as_bytes()).is_ok() {
        return Err(
            "transport probe envelope is admissible as production review evidence".to_owned(),
        );
    }
    let envelope = parse_json(&document)?;
    let envelope = envelope.object()?;
    exact_keys(envelope, &["payload", "payloadType", "signatures"])?;
    if json_member(envelope, "payloadType")?.string()? != TRANSPORT_PROBE_MEDIA_TYPE {
        return Err("transport probe envelope has the wrong isolated media type".to_owned());
    }
    let payload = decode_base64(json_member(envelope, "payload")?.string()?)?;
    let packet = parse_json(
        std::str::from_utf8(&payload)
            .map_err(|_| "transport probe payload is not UTF-8".to_owned())?,
    )?;
    let packet = packet.object()?;
    verify_transport_probe_packet(packet, role)?;
    verify_transport_probe_repository_id(packet, policy)?;
    verify_transport_probe_freshness_and_revocation(packet, policy)?;
    verify_transport_probe_signatures(
        json_member(envelope, "signatures")?.array()?,
        packet,
        &payload,
        policy,
    )?;
    let reviewer = json_member(packet, "reviewer")?.string()?.to_owned();
    let sigstore_identity = json_member(envelope, "signatures")?
        .array()?
        .iter()
        .find_map(|signature| {
            let signature = signature.object().ok()?;
            (json_member(signature, "scheme")
                .and_then(JsonValue::string)
                .ok()?
                == "sigstore")
                .then(|| {
                    json_member(signature, "certificateIdentity")
                        .and_then(JsonValue::string)
                        .map(str::to_owned)
                })?
                .ok()
        })
        .ok_or_else(|| "transport probe lacks a Sigstore identity".to_owned())?;
    let mut context = packet.clone();
    let statement_id = context
        .remove("statementId")
        .and_then(|value| value.string().ok().map(str::to_owned))
        .ok_or_else(|| "transport probe lacks a statement ID".to_owned())?;
    context.remove("reviewer");
    context.remove("role");
    Ok(VerifiedTransportProbe {
        context,
        envelope_sha256: sha256_bytes(document.as_bytes()).hex(),
        packet_artifact_id: 0,
        packet_provider_selection_sha256: String::new(),
        payload_sha256: sha256_bytes(&payload).hex(),
        reviewer: reviewer.clone(),
        role: role.to_owned(),
        sigstore_identity,
        ssh_fingerprint: allowed_signer_key_fingerprint(policy, &reviewer)?,
        statement_id,
        provider_selection_sha256: String::new(),
    })
}

fn auth_transport_probe_aggregate(root: &Path, options: &Options) -> Result<String, String> {
    let first = required_path(
        &options.input,
        "auth-transport-probe aggregate requires --input A envelope",
    )?;
    let second = required_path(
        &options.from,
        "auth-transport-probe aggregate requires --from B envelope",
    )?;
    let first_policy = required_path(
        &options.policy,
        "auth-transport-probe aggregate requires --policy A roots",
    )?;
    let second_policy = required_path(
        &options.to,
        "auth-transport-probe aggregate requires --to B roots",
    )?;
    let output = required_path(
        &options.output,
        "auth-transport-probe aggregate requires --output receipt",
    )?;
    let mut first =
        verified_transport_probe_envelope(first, first_policy, TRANSPORT_PROBE_ROLES[0])?;
    let mut second =
        verified_transport_probe_envelope(second, second_policy, TRANSPORT_PROBE_ROLES[1])?;
    verify_transport_probe_provider_chain(root, &mut first, &mut second)?;
    let receipt = aggregate_transport_probe_facts(&first, &second)?;
    let receipt = canonical_json_bytes(&JsonValue::Object(receipt))?;
    write_atomic(output, &receipt)?;
    write_digest_sibling(output, sha256_bytes(&receipt))?;
    Ok("verified independent dual authentication over one transported probe subject".to_owned())
}

fn verify_transport_probe_provider_chain(
    root: &Path,
    first: &mut VerifiedTransportProbe,
    second: &mut VerifiedTransportProbe,
) -> Result<(), String> {
    let path = |name: &str| {
        std::env::var_os(name)
            .map(PathBuf::from)
            .ok_or_else(|| format!("transport probe aggregate requires {name}"))
    };
    let subject = path("TRANSPORT_PROBE_SUBJECT_DIRECTORY")?;
    let subject_selection = path("TRANSPORT_PROBE_SUBJECT_SELECTION")?;
    let first_directory = path("TRANSPORT_PROBE_A_DIRECTORY")?;
    let first_selection = path("TRANSPORT_PROBE_A_SELECTION")?;
    let second_directory = path("TRANSPORT_PROBE_B_DIRECTORY")?;
    let second_selection = path("TRANSPORT_PROBE_B_SELECTION")?;
    let candidate = json_member(&first.context, "candidateCommit")?
        .string()?
        .to_owned();
    let sealed_subject_selection = first_directory
        .join("packet-artifact")
        .join("subject-selection");
    verify_transport_probe_context_provider(
        root,
        &first.context,
        &subject,
        &sealed_subject_selection,
    )?;
    reverify_regression_provider_selection(
        root,
        &subject,
        &subject_selection,
        &candidate,
        ".github/workflows/assurance-transport-readiness.yml",
    )?;
    let sealed_subject_identity = transport_probe_provider_identity(&sealed_subject_selection)?;
    if transport_probe_provider_identity(&subject_selection)? != sealed_subject_identity {
        return Err("transport probe live subject retrieval differs from sealed facts".to_owned());
    }
    let run_id = json_member(&first.context, "runId")?.number()?;
    let run_attempt = json_member(&first.context, "runAttempt")?.number()?;
    let mut artifact_ids = BTreeSet::new();
    let mut packet_identities = Vec::new();
    for (verified, directory, selection, suffix) in [
        (&mut *first, first_directory, first_selection, "a"),
        (&mut *second, second_directory, second_selection, "b"),
    ] {
        reverify_regression_provider_selection(
            root,
            &directory,
            &selection,
            &candidate,
            ".github/workflows/assurance-transport-readiness.yml",
        )?;
        if record_digest(&directory.join("envelope.json"))? != verified.envelope_sha256 {
            return Err("transport probe envelope differs from provider-selected bytes".to_owned());
        }
        let retained = parse_json(&read_text(&selection.join("selection.json"))?)?;
        let retained = retained.object()?;
        verify_transport_probe_envelope_provider_identity(
            retained,
            suffix,
            run_id,
            run_attempt,
            &mut artifact_ids,
        )?;
        verified.provider_selection_sha256 = record_digest(&selection.join("selection.json"))?;
        packet_identities.push(verify_transport_probe_signer_input(
            root,
            verified,
            &TransportProbeSignerInput {
                directory: &directory,
                subject: &subject,
                candidate: &candidate,
                suffix,
                run_id,
                run_attempt,
                sealed_subject_identity: &sealed_subject_identity,
            },
        )?);
    }
    if first.packet_artifact_id != second.packet_artifact_id
        || packet_identities[0] != packet_identities[1]
    {
        return Err("transport probe signers did not consume one exact packet artifact".to_owned());
    }
    Ok(())
}

struct TransportProbeSignerInput<'a> {
    directory: &'a Path,
    subject: &'a Path,
    candidate: &'a str,
    suffix: &'a str,
    run_id: u64,
    run_attempt: u64,
    sealed_subject_identity: &'a TransportProbeProviderIdentity,
}

#[derive(Debug, PartialEq, Eq)]
struct TransportProbeProviderIdentity {
    artifact: String,
    artifact_id: u64,
    archive_sha256: String,
    archive_size: u64,
    candidate: String,
    directory_sha256: String,
    event: String,
    provider_head: String,
    repository_id: String,
    run_attempt: u64,
    run_id: u64,
    workflow_blob_sha256: String,
    workflow_path: String,
}

fn transport_probe_provider_identity(
    selection_root: &Path,
) -> Result<TransportProbeProviderIdentity, String> {
    let selection = parse_json(&read_text(&selection_root.join("selection.json"))?)?;
    let selection = selection.object()?;
    let run = parse_json(&read_text(
        &selection_root.join("provider-selected-run.json"),
    )?)?;
    Ok(TransportProbeProviderIdentity {
        artifact: json_member(selection, "artifact")?.string()?.to_owned(),
        artifact_id: json_member(selection, "providerArtifactId")?.number()?,
        archive_sha256: json_member(selection, "providerArchiveSha256")?
            .string()?
            .to_owned(),
        archive_size: json_member(selection, "providerArchiveSize")?.number()?,
        candidate: json_member(selection, "candidateCommit")?
            .string()?
            .to_owned(),
        directory_sha256: json_member(selection, "directorySha256")?
            .string()?
            .to_owned(),
        event: json_member(selection, "event")?.string()?.to_owned(),
        provider_head: json_member(run.object()?, "head_sha")?.string()?.to_owned(),
        repository_id: json_member(selection, "repositoryId")?.string()?.to_owned(),
        run_attempt: json_member(selection, "providerRunAttempt")?.number()?,
        run_id: json_member(selection, "providerRunId")?.number()?,
        workflow_blob_sha256: json_member(selection, "workflowBlobSha256")?
            .string()?
            .to_owned(),
        workflow_path: json_member(selection, "workflowPath")?.string()?.to_owned(),
    })
}

fn verify_transport_probe_signer_input(
    root: &Path,
    verified: &mut VerifiedTransportProbe,
    input: &TransportProbeSignerInput<'_>,
) -> Result<TransportProbeProviderIdentity, String> {
    let packet_artifact = input.directory.join("packet-artifact");
    let packet_selection = input.directory.join("packet-selection");
    let signer_subject_selection = input.directory.join("subject-selection");
    reverify_regression_provider_selection(
        root,
        &packet_artifact,
        &packet_selection,
        input.candidate,
        ".github/workflows/assurance-transport-readiness.yml",
    )?;
    reverify_regression_provider_selection(
        root,
        input.subject,
        &signer_subject_selection,
        input.candidate,
        ".github/workflows/assurance-transport-readiness.yml",
    )?;
    if transport_probe_provider_identity(&signer_subject_selection)?
        != *input.sealed_subject_identity
        || record_digest(&packet_artifact.join(format!("packet-{}.json", input.suffix)))?
            != verified.payload_sha256
    {
        return Err("transport probe signer input differs from retained provider bytes".to_owned());
    }
    let selection = parse_json(&read_text(&packet_selection.join("selection.json"))?)?;
    let selection = selection.object()?;
    let expected_name = format!(
        "assurance-transport-readiness-packets-{}-{}",
        input.run_id, input.run_attempt
    );
    if json_member(selection, "providerRunId")?.number()? != input.run_id
        || json_member(selection, "providerRunAttempt")?.number()? != input.run_attempt
        || json_member(selection, "artifact")?.string()? != expected_name
    {
        return Err("transport probe packet provider identity is not exact".to_owned());
    }
    verified.packet_artifact_id = json_member(selection, "providerArtifactId")?.number()?;
    verified.packet_provider_selection_sha256 = record_digest(&packet_selection)?;
    transport_probe_provider_identity(&packet_selection)
}

fn verify_transport_probe_envelope_provider_identity(
    selection: &BTreeMap<String, JsonValue>,
    suffix: &str,
    run_id: u64,
    run_attempt: u64,
    artifact_ids: &mut BTreeSet<u64>,
) -> Result<(), String> {
    let expected_name =
        format!("assurance-transport-readiness-envelope-{suffix}-{run_id}-{run_attempt}");
    let artifact_id = json_member(selection, "providerArtifactId")?.number()?;
    if !matches!(suffix, "a" | "b")
        || json_member(selection, "providerRunId")?.number()? != run_id
        || json_member(selection, "providerRunAttempt")?.number()? != run_attempt
        || json_member(selection, "artifact")?.string()? != expected_name
        || !artifact_ids.insert(artifact_id)
    {
        return Err(
            "transport probe envelope provider identity is not exact or distinct".to_owned(),
        );
    }
    Ok(())
}

fn aggregate_transport_probe_facts(
    first: &VerifiedTransportProbe,
    second: &VerifiedTransportProbe,
) -> Result<BTreeMap<String, JsonValue>, String> {
    if first.role != TRANSPORT_PROBE_ROLES[0]
        || second.role != TRANSPORT_PROBE_ROLES[1]
        || first.context != second.context
        || first.reviewer == second.reviewer
        || first.ssh_fingerprint == second.ssh_fingerprint
        || first.sigstore_identity == second.sigstore_identity
        || first.packet_artifact_id == 0
        || first.packet_artifact_id != second.packet_artifact_id
        || first.packet_provider_selection_sha256.is_empty()
        || second.packet_provider_selection_sha256.is_empty()
    {
        return Err(
            "transport probe signers are not independent over one exact context".to_owned(),
        );
    }
    let context_sha256 = sha256_bytes(&canonical_json_bytes(&JsonValue::Object(
        first.context.clone(),
    ))?)
    .hex();
    Ok(BTreeMap::from([
        (
            "authorityDomain".to_owned(),
            JsonValue::String(TRANSPORT_PROBE_DOMAIN.to_owned()),
        ),
        ("schemaVersion".to_owned(), JsonValue::Number(1)),
        (
            "contextSha256".to_owned(),
            JsonValue::String(context_sha256),
        ),
        (
            "candidateCommit".to_owned(),
            json_member(&first.context, "candidateCommit")?.clone(),
        ),
        (
            "runId".to_owned(),
            json_member(&first.context, "runId")?.clone(),
        ),
        (
            "runAttempt".to_owned(),
            json_member(&first.context, "runAttempt")?.clone(),
        ),
        (
            "subjectArtifactId".to_owned(),
            json_member(&first.context, "subjectArtifactId")?.clone(),
        ),
        (
            "subjectSha256".to_owned(),
            json_member(&first.context, "subjectSha256")?.clone(),
        ),
        (
            "packetArtifactId".to_owned(),
            JsonValue::Number(first.packet_artifact_id),
        ),
        (
            "authentications".to_owned(),
            JsonValue::Array(
                [first, second]
                    .into_iter()
                    .map(|verified| {
                        JsonValue::Object(BTreeMap::from([
                            (
                                "envelopeSha256".to_owned(),
                                JsonValue::String(verified.envelope_sha256.clone()),
                            ),
                            (
                                "reviewer".to_owned(),
                                JsonValue::String(verified.reviewer.clone()),
                            ),
                            (
                                "packetProviderSelectionSha256".to_owned(),
                                JsonValue::String(
                                    verified.packet_provider_selection_sha256.clone(),
                                ),
                            ),
                            (
                                "providerSelectionSha256".to_owned(),
                                JsonValue::String(verified.provider_selection_sha256.clone()),
                            ),
                            ("role".to_owned(), JsonValue::String(verified.role.clone())),
                            (
                                "sigstoreIdentity".to_owned(),
                                JsonValue::String(verified.sigstore_identity.clone()),
                            ),
                            (
                                "sshKeyFingerprint".to_owned(),
                                JsonValue::String(verified.ssh_fingerprint.clone()),
                            ),
                            (
                                "statementId".to_owned(),
                                JsonValue::String(verified.statement_id.clone()),
                            ),
                        ]))
                    })
                    .collect(),
            ),
        ),
    ]))
}

fn transport_probe_role(options: &Options) -> Result<&str, String> {
    options
        .role
        .as_deref()
        .filter(|role| TRANSPORT_PROBE_ROLES.contains(role))
        .ok_or_else(|| "auth-transport-probe requires one exact isolated --role".to_owned())
}

fn verify_transport_probe_context(context: &BTreeMap<String, JsonValue>) -> Result<(), String> {
    exact_keys(
        context,
        &[
            "authorityDomain",
            "candidateCommit",
            "issuedAt",
            "event",
            "nonceSha256",
            "repository",
            "repositoryId",
            "runAttempt",
            "runId",
            "subjectArtifactId",
            "subjectArtifactName",
            "subjectProviderSelectionSha256",
            "subjectSha256",
            "workflowHeadSha",
            "workflowRef",
        ],
    )?;
    let candidate = json_member(context, "candidateCommit")?.string()?;
    require_git_sha_text(candidate, "transport probe candidate")?;
    require_git_sha_text(
        json_member(context, "workflowHeadSha")?.string()?,
        "transport probe workflow head",
    )?;
    for field in [
        "nonceSha256",
        "subjectProviderSelectionSha256",
        "subjectSha256",
    ] {
        require_digest(
            json_member(context, field)?.string()?,
            "transport probe digest",
        )?;
    }
    validate_utc_timestamp(json_member(context, "issuedAt")?.string()?)?;
    let run_id = json_member(context, "runId")?.number()?;
    let run_attempt = json_member(context, "runAttempt")?.number()?;
    let expected_artifact = format!("assurance-transport-readiness-subject-{run_id}-{run_attempt}");
    if json_member(context, "authorityDomain")?.string()? != TRANSPORT_PROBE_DOMAIN
        || json_member(context, "repository")?.string()? != "Portfoligno/hell-rs"
        || json_member(context, "repositoryId")?.number()? == 0
        || json_member(context, "event")?.string()? != "workflow_dispatch"
        || run_id == 0
        || run_attempt == 0
        || json_member(context, "subjectArtifactId")?.number()? == 0
        || json_member(context, "subjectArtifactName")?.string()? != expected_artifact
        || json_member(context, "workflowRef")?.string()?
            != "Portfoligno/hell-rs/.github/workflows/assurance-transport-readiness.yml@refs/heads/main"
    {
        return Err("transport probe context is not exact current-main authority".to_owned());
    }
    Ok(())
}

fn verify_transport_probe_repository_id(
    context: &BTreeMap<String, JsonValue>,
    policy: &Path,
) -> Result<(), String> {
    let directory = policy
        .parent()
        .ok_or_else(|| "transport probe policy has no directory".to_owned())?;
    let configured = assignment_u64(
        &read_text(&directory.join("transport-probe-policy.toml"))?,
        "repository_id",
    )?;
    if configured == 0 || json_member(context, "repositoryId")?.number()? != configured {
        return Err("transport probe repository ID differs from committed policy".to_owned());
    }
    Ok(())
}

fn verify_transport_probe_packet(
    packet: &BTreeMap<String, JsonValue>,
    role: &str,
) -> Result<(), String> {
    let mut context = packet.clone();
    let statement = context
        .remove("statementId")
        .ok_or_else(|| "transport probe packet omits statementId".to_owned())?;
    let reviewer = context
        .remove("reviewer")
        .ok_or_else(|| "transport probe packet omits reviewer".to_owned())?;
    let retained_role = context
        .remove("role")
        .ok_or_else(|| "transport probe packet omits role".to_owned())?;
    if retained_role.string()? != role || !reviewer.string()?.starts_with(&format!("{role}:")) {
        return Err("transport probe packet role identity was substituted".to_owned());
    }
    verify_transport_probe_context(&context)?;
    let mut unsigned = context;
    unsigned.insert("reviewer".to_owned(), reviewer);
    unsigned.insert("role".to_owned(), retained_role);
    if statement.string()? != transport_probe_statement_id(&unsigned)? {
        return Err("transport probe statement ID is not content-derived".to_owned());
    }
    Ok(())
}

fn transport_probe_statement_id(packet: &BTreeMap<String, JsonValue>) -> Result<String, String> {
    let bytes = canonical_json_bytes(&JsonValue::Object(packet.clone()))?;
    let mut bound = TRANSPORT_PROBE_DOMAIN.as_bytes().to_vec();
    bound.push(0);
    bound.extend_from_slice(&bytes);
    Ok(sha256_bytes(&bound).hex())
}

fn verify_transport_probe_freshness_and_revocation(
    packet: &BTreeMap<String, JsonValue>,
    policy: &Path,
) -> Result<(), String> {
    let directory = policy
        .parent()
        .ok_or_else(|| "transport probe policy has no directory".to_owned())?;
    let issued = utc_timestamp_seconds(json_member(packet, "issuedAt")?.string()?)?;
    let now = current_utc_seconds()?;
    let maximum_age = assignment_u64(
        &read_text(&directory.join("surveillance-policy.toml"))?,
        "mutation_report_maximum_age_days",
    )?
    .checked_mul(86_400)
    .ok_or_else(|| "transport probe maximum age overflows".to_owned())?;
    if issued > now || now.saturating_sub(issued) > maximum_age {
        return Err("transport probe statement is future-dated or stale".to_owned());
    }
    let revocations = assignment_string_array(
        &read_text(&directory.join("review-revocations.toml"))?,
        "revoked_review_ids",
    )?;
    if revocations.iter().any(|value| {
        value
            == json_member(packet, "statementId")
                .and_then(JsonValue::string)
                .unwrap_or_default()
    }) {
        return Err("transport probe statement is revoked".to_owned());
    }
    Ok(())
}

fn verify_transport_probe_signatures(
    signatures: &[JsonValue],
    packet: &BTreeMap<String, JsonValue>,
    payload: &[u8],
    policy: &Path,
) -> Result<(), String> {
    let required = required_signature_schemes(policy)?;
    if signatures.len() != required.len() {
        return Err("transport probe signature count differs from policy".to_owned());
    }
    let reviewer = json_member(packet, "reviewer")?.string()?;
    let mut observed = BTreeSet::new();
    for signature in signatures {
        let signature = signature.object()?;
        let scheme = json_member(signature, "scheme")?.string()?;
        if !observed.insert(scheme.to_owned()) || !required.contains(scheme) {
            return Err("transport probe signature scheme is duplicate or unauthorized".to_owned());
        }
        match scheme {
            "ssh" => {
                exact_keys(signature, &["keyid", "scheme", "sig"])?;
                if json_member(signature, "keyid")?.string()? != reviewer {
                    return Err("transport probe SSH key identity differs from reviewer".to_owned());
                }
                verify_ssh_signature(
                    policy,
                    reviewer,
                    payload,
                    &decode_base64(json_member(signature, "sig")?.string()?)?,
                )?;
            }
            "sigstore" => {
                exact_keys(
                    signature,
                    &[
                        "bundle",
                        "certificateIdentity",
                        "certificateIssuer",
                        "scheme",
                    ],
                )?;
                verify_sigstore_signature(policy, signature, payload)?;
            }
            _ => return Err("transport probe signature scheme is unsupported".to_owned()),
        }
    }
    if observed != required {
        return Err("transport probe omits a required signature scheme".to_owned());
    }
    Ok(())
}

struct ReviewSignatures {
    ssh: Vec<u8>,
    sigstore_bundle: Vec<u8>,
    sigstore_identity: String,
    sigstore_issuer: String,
}

fn sign_review_payload(
    payload: &[u8],
    key: Option<&Path>,
    allowed_signers: Option<&Path>,
    reviewer: &str,
) -> Result<ReviewSignatures, String> {
    let temporary_directory = create_private_temp_directory("hell-review-sign")?;
    let result = sign_review_payload_in(
        &temporary_directory,
        payload,
        key,
        allowed_signers,
        reviewer,
    );
    let cleanup = fs::remove_dir_all(&temporary_directory)
        .map_err(|error| format!("cannot remove private signing directory: {error}"));
    match (result, cleanup) {
        (Ok(signatures), Ok(())) => Ok(signatures),
        (Err(error), _) | (Ok(_), Err(error)) => Err(error),
    }
}

fn sign_review_payload_in(
    temporary_directory: &Path,
    payload: &[u8],
    key: Option<&Path>,
    allowed_signers: Option<&Path>,
    reviewer: &str,
) -> Result<ReviewSignatures, String> {
    let temporary_payload = temporary_directory.join("payload.json");
    let mut staged_payload = fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(&temporary_payload)
        .map_err(|error| format!("cannot stage review packet: {error}"))?;
    staged_payload
        .write_all(payload)
        .map_err(|error| format!("cannot write staged review packet: {error}"))?;
    staged_payload
        .sync_all()
        .map_err(|error| format!("cannot sync staged review packet: {error}"))?;
    drop(staged_payload);
    let staged_key;
    let signing_key = if let Some(key) = key {
        key
    } else {
        staged_key = temporary_directory.join("reviewer.pub");
        stage_allowed_signer_public_key(
            allowed_signers.ok_or_else(|| {
                "review-sign requires --policy when using an SSH agent".to_owned()
            })?,
            reviewer,
            &staged_key,
        )?;
        &staged_key
    };
    let ssh = ssh_review_signature(&temporary_payload, signing_key)?;
    let (sigstore_bundle, sigstore_identity, sigstore_issuer) =
        sigstore_review_signature(temporary_directory, &temporary_payload)?;
    Ok(ReviewSignatures {
        ssh,
        sigstore_bundle,
        sigstore_identity,
        sigstore_issuer,
    })
}

fn ssh_review_signature(payload: &Path, key: &Path) -> Result<Vec<u8>, String> {
    let signed = Command::new("ssh-keygen")
        .args([
            OsStr::new("-Y"),
            OsStr::new("sign"),
            OsStr::new("-f"),
            key.as_os_str(),
            OsStr::new("-n"),
            OsStr::new("hell-rs-promotion-review"),
            payload.as_os_str(),
        ])
        .stdout(Stdio::null())
        .stderr(Stdio::piped())
        .output()
        .map_err(|error| format!("cannot run SSH review signer: {error}"))?;
    if !signed.status.success() {
        return Err(format!(
            "SSH review signing failed: {}",
            String::from_utf8_lossy(&signed.stderr)
        ));
    }
    read_regular_file(&payload.with_extension("json.sig"))
        .map_err(|error| format!("cannot read SSH review signature: {error}"))
}

fn sigstore_review_signature(
    temporary_directory: &Path,
    payload: &Path,
) -> Result<(Vec<u8>, String, String), String> {
    let sigstore_bundle_path = temporary_directory.join("sigstore-bundle.json");
    let sigstore_identity = match std::env::var("HELL_SIGSTORE_IDENTITY") {
        Ok(identity) => identity,
        Err(_) => github_workflow_certificate_identity(
            &std::env::var("GITHUB_WORKFLOW_REF")
                .map_err(|_| "review-sign requires a Sigstore workflow identity".to_owned())?,
        )?,
    };
    let sigstore_issuer = std::env::var("HELL_SIGSTORE_ISSUER")
        .unwrap_or_else(|_| "https://token.actions.githubusercontent.com".to_owned());
    let sigstore = Command::new("cosign")
        .args([
            OsStr::new("sign-blob"),
            OsStr::new("--yes"),
            OsStr::new("--bundle"),
            sigstore_bundle_path.as_os_str(),
            payload.as_os_str(),
        ])
        .stdout(Stdio::null())
        .stderr(Stdio::piped())
        .output()
        .map_err(|error| format!("cannot run Sigstore review signer: {error}"))?;
    if !sigstore.status.success() {
        return Err(format!(
            "Sigstore review signing failed: {}",
            String::from_utf8_lossy(&sigstore.stderr)
        ));
    }
    let sigstore_bundle = read_regular_file(&sigstore_bundle_path)?;
    parse_json(
        std::str::from_utf8(&sigstore_bundle)
            .map_err(|_| "Sigstore bundle is not UTF-8".to_owned())?,
    )?;
    Ok((sigstore_bundle, sigstore_identity, sigstore_issuer))
}

fn github_workflow_certificate_identity(reference: &str) -> Result<String, String> {
    let (path, revision) = reference
        .split_once('@')
        .ok_or_else(|| "GITHUB_WORKFLOW_REF lacks an exact revision".to_owned())?;
    if !revision.starts_with("refs/")
        || revision
            .bytes()
            .any(|byte| byte.is_ascii_control() || byte.is_ascii_whitespace())
    {
        return Err("GITHUB_WORKFLOW_REF revision is not a normalized Git ref".to_owned());
    }
    let components = path.split('/').collect::<Vec<_>>();
    if components.len() < 4
        || components.iter().any(|component| component.is_empty())
        || components[2] != ".github"
        || components[3] != "workflows"
    {
        return Err("GITHUB_WORKFLOW_REF is not a repository workflow identity".to_owned());
    }
    let mut identity = String::from("https://github.com/");
    identity.push_str(path);
    identity.push('@');
    identity.push_str(revision);
    Ok(identity)
}

fn github_workflow_identity_matches(
    identity: &str,
    repository: &str,
    workflow: &str,
    trusted_ref: &str,
) -> bool {
    let Some(remainder) = identity.strip_prefix("https://github.com/") else {
        return false;
    };
    let Some((path, revision)) = remainder.split_once('@') else {
        return false;
    };
    if revision != trusted_ref
        || revision
            .bytes()
            .any(|byte| byte.is_ascii_control() || byte.is_ascii_whitespace())
    {
        return false;
    }
    let repository_components = repository.split('/').collect::<Vec<_>>();
    let workflow_components = workflow.split('/').collect::<Vec<_>>();
    let identity_components = path.split('/').collect::<Vec<_>>();
    identity_components.len() == repository_components.len() + workflow_components.len()
        && identity_components
            .iter()
            .zip(repository_components.iter().chain(&workflow_components))
            .all(|(observed, expected)| observed == expected)
}

fn review_verify(options: &Options) -> Result<String, String> {
    let input = required_path(&options.input, "review-verify requires --input")?;
    let policy = required_path(
        &options.policy,
        "review-verify requires --policy allowed-signers",
    )?;
    let verified = verify_review_envelope(input, policy)?;
    if let Some(role) = &options.role
        && verified.role != *role
    {
        return Err(format!(
            "review role mismatch: expected {role:?}, observed {:?}",
            verified.role
        ));
    }
    if let Some(source) = &options.expect_source
        && verified.candidate_commit != *source
    {
        return Err(format!(
            "review candidate mismatch: expected {source}, observed {}",
            verified.candidate_commit
        ));
    }
    if let Some(epoch) = &options.expect_epoch
        && verified.assurance_epoch != *epoch
    {
        return Err(format!(
            "review epoch mismatch: expected {epoch}, observed {}",
            verified.assurance_epoch
        ));
    }
    Ok(format!(
        "verified signed {:?} review by {} over {} artifacts",
        verified.role, verified.reviewer, verified.artifact_count
    ))
}

struct VerifiedReview {
    role: String,
    reviewer: String,
    subject: String,
    signer_fingerprint: String,
    candidate_commit: String,
    assurance_epoch: String,
    issued_at: String,
    artifact_count: usize,
    reviewed_artifacts: BTreeSet<String>,
    reviewed_claim_groups: BTreeMap<String, (String, String, String)>,
}

pub(crate) fn verify_review_binding(
    input: &Path,
    policy: &Path,
    role: &str,
    candidate: &str,
    epoch: &str,
    required_artifacts: &BTreeSet<String>,
) -> Result<(String, String), String> {
    let review = verify_review_envelope(input, policy)?;
    if review.role != role
        || review.candidate_commit != candidate
        || review.assurance_epoch != epoch
        || review.reviewed_artifacts != *required_artifacts
    {
        return Err(
            "review envelope does not exactly bind the required subject artifacts".to_owned(),
        );
    }
    Ok((review.subject, review.signer_fingerprint))
}

pub(crate) fn verify_review_binding_payload(
    input: &Path,
    payload_path: &Path,
    policy: &Path,
    role: &str,
    candidate: &str,
    epoch: &str,
    required_artifacts: &BTreeSet<String>,
) -> Result<(String, String), String> {
    let binding = verify_review_binding(input, policy, role, candidate, epoch, required_artifacts)?;
    let envelope = parse_json(&read_text(input)?)?;
    let payload = decode_base64(json_member(envelope.object()?, "payload")?.string()?)?;
    if payload != read_text(payload_path)?.as_bytes() {
        return Err("review envelope payload differs from the retained review packet".to_owned());
    }
    Ok(binding)
}

pub(crate) struct VerifiedActivationReviewPackage {
    pub(crate) subject: String,
    pub(crate) signer_fingerprint: String,
    pub(crate) envelope: Vec<u8>,
    pub(crate) authorization_sha256: String,
    pub(crate) packet_sha256: String,
}

pub(crate) fn verify_activation_review_package(
    root: &Path,
    directory: &Path,
    subject: &Path,
    role: &str,
) -> Result<VerifiedActivationReviewPackage, String> {
    if !matches!(role, "claim-author" | "claim-reviewer") {
        return Err("activation review package role is unsupported".to_owned());
    }
    require_activation_review_package_inventory(directory)?;
    let authorization = directory.join("authorization.json");
    let packet = directory.join("review-packet.json");
    let packet_digest = directory.join("review-packet.json.sha256");
    let envelope = directory.join("review.dsse.json");
    let envelope_digest = directory.join("review.dsse.json.sha256");
    for path in [
        &authorization,
        &packet,
        &packet_digest,
        &envelope,
        &envelope_digest,
    ] {
        let metadata = fs::symlink_metadata(path)
            .map_err(|error| format!("activation review package input is absent: {error}"))?;
        if metadata.file_type().is_symlink() || !metadata.is_file() {
            return Err("activation review package input is not a regular file".to_owned());
        }
    }
    verify_activation_review_package_binding(root, directory, subject, role)
}

fn require_activation_review_package_inventory(directory: &Path) -> Result<(), String> {
    let metadata = fs::symlink_metadata(directory)
        .map_err(|error| format!("cannot inspect activation review package: {error}"))?;
    if metadata.file_type().is_symlink() || !metadata.is_dir() {
        return Err("activation review package is not a real directory".to_owned());
    }
    let expected = BTreeSet::from([
        "authorization.json",
        "environment-approvals.json",
        "review-revocations.toml",
        "review-packet.json",
        "review-packet.json.sha256",
        "review.dsse.json",
        "review.dsse.json.sha256",
        "reviewed-provider-artifact.json",
        "reviewed-provider-extracted-manifest.json",
        "reviewed-provider-extracted-subject",
        "reviewed-provider-run.json",
        "reviewed-provider-workflow.yml",
        "reviewer.allowed_signers",
        "ssh-signing-keys.json",
        "surveillance-policy.toml",
        "team-membership.json",
        "trust-roots.toml",
    ])
    .into_iter()
    .map(str::to_owned)
    .collect::<BTreeSet<_>>();
    let observed = fs::read_dir(directory)
        .map_err(|error| format!("cannot enumerate activation review package: {error}"))?
        .map(|entry| {
            entry
                .map_err(|error| format!("cannot enumerate activation review package: {error}"))
                .and_then(|entry| {
                    entry
                        .file_name()
                        .into_string()
                        .map_err(|_| "activation review package name is not UTF-8".to_owned())
                })
        })
        .collect::<Result<BTreeSet<_>, _>>()?;
    if observed != expected {
        return Err("activation review package inventory is not exact".to_owned());
    }
    require_real_activation_review_tree(directory, directory)
}

fn verify_activation_review_package_binding(
    root: &Path,
    directory: &Path,
    subject: &Path,
    role: &str,
) -> Result<VerifiedActivationReviewPackage, String> {
    let authorization = directory.join("authorization.json");
    let packet = directory.join("review-packet.json");
    let packet_digest = directory.join("review-packet.json.sha256");
    let envelope = directory.join("review.dsse.json");
    let envelope_digest = directory.join("review.dsse.json.sha256");
    if subject.file_name() != Some(OsStr::new("review-subject.json")) {
        return Err("activation review package subject path is invalid".to_owned());
    }
    let subject_root = subject
        .parent()
        .ok_or_else(|| "activation review subject has no directory".to_owned())?;
    let proposal_root =
        crate::collection_custody::verify_activation_review_subject(root, subject_root)?;
    let proposal = proposal_root.join("activation-proposal.json");
    let proposal_document = parse_json(&read_text(&proposal)?)?;
    let proposal_fields = proposal_document.object()?;
    let candidate = json_member(proposal_fields, "baseCandidateCommit")?.string()?;
    let epoch = json_member(proposal_fields, "baseAssuranceEpochSha256")?.string()?;
    let (_, _, reviewed_at, _, _) =
        verify_review_authorization_at(root, &authorization, role, candidate, subject)?;
    let mut required = collection_activation_review_artifacts_at(root, subject, role)?;
    let authorization_sha256 = record_digest(&authorization)?;
    if !required.insert(authorization_sha256.clone()) {
        return Err("activation authorization duplicates a reviewed proposal root".to_owned());
    }
    let (packet_candidate, packet_epoch, packet_artifacts) =
        protected_review_subject(&packet, role)?;
    let packet_document = parse_json(&read_text(&packet)?)?;
    if packet_candidate != candidate
        || packet_epoch != epoch
        || packet_artifacts != required
        || activation_review_timestamp_matches(&packet_document, &reviewed_at).is_err()
    {
        return Err(
            "activation review packet does not bind exact proposal and authorization".to_owned(),
        );
    }
    let packet_sha256 = record_digest(&packet)?;
    if read_text(&packet_digest)? != format!("{packet_sha256}\n") {
        return Err("activation review packet digest sibling differs".to_owned());
    }
    let policy = directory.join("reviewer.allowed_signers");
    let (subject, signer_fingerprint) = verify_review_binding_payload(
        &envelope, &packet, &policy, role, candidate, epoch, &required,
    )?;
    if read_text(&envelope_digest)? != format!("{}\n", record_digest(&envelope)?) {
        return Err("activation review envelope digest sibling differs".to_owned());
    }
    if git_output(root, &["rev-parse", "HEAD"])?.trim() != candidate {
        return Err("activation review package differs from current reviewed base".to_owned());
    }
    Ok(VerifiedActivationReviewPackage {
        subject,
        signer_fingerprint,
        envelope: read_regular_file(&envelope)?,
        authorization_sha256,
        packet_sha256,
    })
}

pub(crate) fn activation_review_timestamp_matches(
    packet: &JsonValue,
    reviewed_at: &str,
) -> Result<(), String> {
    validate_utc_timestamp(reviewed_at)?;
    let issued_at = json_member(packet.object()?, "issuedAt")?.string()?;
    validate_utc_timestamp(issued_at)?;
    if issued_at != reviewed_at {
        return Err("activation authorization and packet timestamps differ".to_owned());
    }
    Ok(())
}

pub(crate) fn require_real_activation_review_tree(
    root: &Path,
    directory: &Path,
) -> Result<(), String> {
    for entry in fs::read_dir(directory)
        .map_err(|error| format!("cannot enumerate activation review package: {error}"))?
    {
        let entry = entry
            .map_err(|error| format!("cannot enumerate activation review package: {error}"))?;
        let metadata = fs::symlink_metadata(entry.path())
            .map_err(|error| format!("cannot inspect activation review package: {error}"))?;
        if metadata.file_type().is_symlink() {
            return Err("activation review package contains a symlink".to_owned());
        }
        if metadata.is_dir() {
            require_real_activation_review_tree(root, &entry.path())?;
        } else if !metadata.is_file() {
            return Err("activation review package contains a non-regular node".to_owned());
        }
        entry
            .path()
            .strip_prefix(root)
            .map_err(|_| "activation review package entry escapes root".to_owned())?;
    }
    Ok(())
}

pub(crate) struct UnsignedReviewPayloadInput<'a> {
    pub(crate) reviewer: &'a str,
    pub(crate) issued_at: &'a str,
    pub(crate) candidate: &'a str,
    pub(crate) epoch: &'a str,
    pub(crate) reviewed_artifacts: &'a BTreeSet<String>,
}

pub(crate) fn render_unsigned_custody_review_payload(
    allowed_signers: &Path,
    input: &UnsignedReviewPayloadInput<'_>,
) -> Result<(Vec<u8>, String), String> {
    require_git_sha_text(input.candidate, "custody review candidate")?;
    require_digest(input.epoch, "custody review assurance epoch")?;
    if !input.reviewer.starts_with("custody-reviewer:") || input.reviewer == "custody-reviewer:" {
        return Err("custody review principal does not match its role".to_owned());
    }
    allowed_signer_key_fingerprint(allowed_signers, input.reviewer)?;
    required_signature_schemes(allowed_signers)?;
    if input.reviewed_artifacts.is_empty() {
        return Err("custody review has no reviewed artifacts".to_owned());
    }
    for artifact in input.reviewed_artifacts {
        require_digest(artifact, "custody reviewed artifact")?;
    }
    validate_utc_timestamp(input.issued_at)?;
    let issued_seconds = utc_timestamp_seconds(input.issued_at)?;
    let current_seconds = current_utc_seconds()?;
    if issued_seconds > current_seconds {
        return Err("custody review statement is future-dated".to_owned());
    }
    let config_root = allowed_signers
        .parent()
        .ok_or_else(|| "allowed signers has no policy directory".to_owned())?;
    let surveillance = read_text(&config_root.join("surveillance-policy.toml"))?;
    let maximum_age_days = assignment_u64(&surveillance, "mutation_report_maximum_age_days")?;
    let maximum_age = maximum_age_days
        .checked_mul(86_400)
        .filter(|maximum| *maximum > 0)
        .ok_or_else(|| "review maximum age must be nonzero and bounded".to_owned())?;
    if current_seconds.saturating_sub(issued_seconds) > maximum_age {
        return Err("custody review statement is stale".to_owned());
    }
    let empty_claim_groups = BTreeMap::new();
    let findings_sha256 = sha256_bytes(b"[]\n").hex();
    let derived_id = review_statement_id(&ReviewStatementIdentity {
        candidate: input.candidate,
        epoch: input.epoch,
        role: "custody-reviewer",
        reviewer: input.reviewer,
        decision: "accept",
        issued_at: input.issued_at,
        artifacts: input.reviewed_artifacts,
        claim_groups: &empty_claim_groups,
        findings_sha256: &findings_sha256,
    });
    let revocations = read_text(&config_root.join("review-revocations.toml"))?;
    if assignment_string_array(&revocations, "revoked_review_ids")?
        .iter()
        .any(|revoked| revoked == &derived_id)
    {
        return Err("custody review statement is revoked".to_owned());
    }
    let reviewed_artifacts = input
        .reviewed_artifacts
        .iter()
        .map(|artifact| json_string(artifact))
        .collect::<Vec<_>>()
        .join(",");
    let payload = format!(
        "{{\"schemaVersion\":1,\"reviewId\":{},\"role\":\"custody-reviewer\",\"reviewer\":{},\"decision\":\"accept\",\"candidateCommit\":{},\"assuranceEpochSha256\":{},\"reviewedArtifacts\":[{reviewed_artifacts}],\"distinctSubjects\":1,\"independenceViolations\":[],\"findings\":[],\"issuedAt\":{}}}\n",
        json_string(&derived_id),
        json_string(input.reviewer),
        json_string(input.candidate),
        json_string(input.epoch),
        json_string(input.issued_at),
    );
    let document = parse_json(&payload)?;
    admit_review_payload(document.object()?)?;
    Ok((payload.into_bytes(), derived_id))
}

pub(crate) struct VerifiedUnsignedCustodyReview {
    pub(crate) reviewer: String,
    pub(crate) issued_at: String,
    pub(crate) review_id: String,
    pub(crate) candidate: String,
    pub(crate) epoch: String,
    pub(crate) reviewed_artifacts: BTreeSet<String>,
}

pub(crate) fn verify_unsigned_custody_review_payload(
    allowed_signers: &Path,
    bytes: &[u8],
) -> Result<VerifiedUnsignedCustodyReview, String> {
    let text = std::str::from_utf8(bytes)
        .map_err(|_| "unsigned custody review payload is not UTF-8".to_owned())?;
    let document = parse_json(text)?;
    let payload = document.object()?;
    admit_review_payload(payload)?;
    if json_member(payload, "role")?.string()? != "custody-reviewer"
        || json_member(payload, "decision")?.string()? != "accept"
    {
        return Err("unsigned custody review payload has the wrong role or decision".to_owned());
    }
    let reviewed_artifacts = json_member(payload, "reviewedArtifacts")?
        .array()?
        .iter()
        .map(|artifact| artifact.string().map(str::to_owned))
        .collect::<Result<BTreeSet<_>, _>>()?;
    let facts = VerifiedUnsignedCustodyReview {
        reviewer: json_member(payload, "reviewer")?.string()?.to_owned(),
        issued_at: json_member(payload, "issuedAt")?.string()?.to_owned(),
        review_id: json_member(payload, "reviewId")?.string()?.to_owned(),
        candidate: json_member(payload, "candidateCommit")?
            .string()?
            .to_owned(),
        epoch: json_member(payload, "assuranceEpochSha256")?
            .string()?
            .to_owned(),
        reviewed_artifacts,
    };
    let (canonical, derived_review_id) = render_unsigned_custody_review_payload(
        allowed_signers,
        &UnsignedReviewPayloadInput {
            reviewer: &facts.reviewer,
            issued_at: &facts.issued_at,
            candidate: &facts.candidate,
            epoch: &facts.epoch,
            reviewed_artifacts: &facts.reviewed_artifacts,
        },
    )?;
    if canonical != bytes || derived_review_id != facts.review_id {
        return Err("unsigned custody review payload is not canonical and exact".to_owned());
    }
    Ok(facts)
}

fn verify_historical_review_binding(
    input: &Path,
    policy: &Path,
    current_revocations: &Path,
    role: &str,
    candidate: &str,
    epoch: &str,
    required_artifacts: &BTreeSet<String>,
) -> Result<(String, String), String> {
    let review = verify_review_envelope_with_context(
        input,
        policy,
        ReviewValidationContext::Historical {
            current_revocations,
        },
    )?;
    if review.role != role
        || review.candidate_commit != candidate
        || review.assurance_epoch != epoch
        || review.reviewed_artifacts != *required_artifacts
    {
        return Err(
            "historical review envelope does not exactly bind the committed subject".to_owned(),
        );
    }
    Ok((review.subject, review.signer_fingerprint))
}

pub(crate) struct HistoricalActivationReviewBinding<'a> {
    pub(crate) input: &'a Path,
    pub(crate) policy: &'a Path,
    pub(crate) current_revocations: &'a Path,
    pub(crate) role: &'a str,
    pub(crate) candidate: &'a str,
    pub(crate) epoch: &'a str,
    pub(crate) required_artifacts: &'a BTreeSet<String>,
    pub(crate) current_trust_roots: &'a Path,
}

pub(crate) fn verify_historical_activation_review_binding(
    request: &HistoricalActivationReviewBinding<'_>,
) -> Result<(String, String), String> {
    let &HistoricalActivationReviewBinding {
        input,
        policy,
        current_revocations,
        role,
        candidate,
        epoch,
        required_artifacts,
        current_trust_roots,
    } = request;
    if !matches!(role, "claim-author" | "claim-reviewer") {
        return Err("historical activation review role is unsupported".to_owned());
    }
    let directory = input
        .parent()
        .ok_or_else(|| "historical activation review lacks a directory".to_owned())?;
    require_activation_review_package_inventory(directory)?;
    let packet_path = directory.join("review-packet.json");
    let packet_bytes = read_regular_file(&packet_path)?;
    let (packet_candidate, packet_epoch, packet_artifacts) =
        protected_review_subject(&packet_path, role)?;
    if packet_candidate != candidate
        || packet_epoch != epoch
        || packet_artifacts != *required_artifacts
        || read_text(&directory.join("review-packet.json.sha256"))?
            != format!("{}\n", sha256_bytes(&packet_bytes).hex())
        || read_text(&directory.join("review.dsse.json.sha256"))?
            != format!("{}\n", record_digest(input)?)
    {
        return Err("historical activation review package binding differs".to_owned());
    }
    let binding = verify_historical_review_binding(
        input,
        policy,
        current_revocations,
        role,
        candidate,
        epoch,
        required_artifacts,
    )?;
    let envelope = parse_json(&read_text(input)?)?;
    let payload = decode_base64(json_member(envelope.object()?, "payload")?.string()?)?;
    if payload != packet_bytes {
        return Err("historical activation DSSE payload differs from retained packet".to_owned());
    }
    let signatures = json_member(envelope.object()?, "signatures")?.array()?;
    let sigstore = signatures
        .iter()
        .map(JsonValue::object)
        .collect::<Result<Vec<_>, _>>()?
        .into_iter()
        .find(|signature| {
            json_member(signature, "scheme").and_then(JsonValue::string) == Ok("sigstore")
        })
        .ok_or_else(|| "historical activation review lacks Sigstore authority".to_owned())?;
    verify_sigstore_signature_with_trust_roots(current_trust_roots, sigstore, &payload)?;
    Ok(binding)
}

fn verify_sigstore_signature_with_trust_roots(
    trust_roots: &Path,
    signature: &BTreeMap<String, JsonValue>,
    payload: &[u8],
) -> Result<(), String> {
    let temporary = create_private_temp_directory("hell-current-activation-trust")?;
    let policy = temporary.join("reviewer.allowed_signers");
    let roots = temporary.join("trust-roots.toml");
    write_atomic(&policy, b"historical-activation no-key\n")?;
    write_atomic(&roots, &read_regular_file(trust_roots)?)?;
    let result = verify_sigstore_signature(&policy, signature, payload);
    let _ = fs::remove_dir_all(&temporary);
    result
}

pub(crate) fn verify_reviewed_claim_groups(
    input: &Path,
    policy: &Path,
    candidate: &str,
    epoch: &str,
) -> Result<BTreeSet<String>, String> {
    let review = verify_review_envelope(input, policy)?;
    if !matches!(
        review.role.as_str(),
        "claim-reviewer" | "review-graph-reviewer"
    ) || review.candidate_commit != candidate
        || review.assurance_epoch != epoch
        || review.reviewed_claim_groups.is_empty()
    {
        return Err(
            "claim-group review does not bind the candidate, epoch, and group set".to_owned(),
        );
    }
    Ok(review
        .reviewed_claim_groups
        .into_iter()
        .map(|(group, (cells, evidence, reviews))| {
            format!("{group}\n{cells}\n{evidence}\n{reviews}")
        })
        .collect())
}

fn verify_review_envelope(input: &Path, allowed_signers: &Path) -> Result<VerifiedReview, String> {
    verify_review_envelope_with_context(input, allowed_signers, ReviewValidationContext::Fresh)
}

#[derive(Clone, Copy)]
enum ReviewValidationContext<'a> {
    Fresh,
    Historical { current_revocations: &'a Path },
}

fn verify_review_envelope_with_context(
    input: &Path,
    allowed_signers: &Path,
    context: ReviewValidationContext<'_>,
) -> Result<VerifiedReview, String> {
    verify_review_envelope_with_context_at(input, allowed_signers, context, current_utc_seconds()?)
}

#[allow(clippy::too_many_lines)]
fn verify_review_envelope_with_context_at(
    input: &Path,
    allowed_signers: &Path,
    context: ReviewValidationContext<'_>,
    current_seconds: u64,
) -> Result<VerifiedReview, String> {
    let document = read_text(input)?;
    admit_review_envelope_bytes(document.as_bytes())?;
    let envelope = parse_json(&document)?;
    let envelope = envelope.object()?;
    exact_keys(envelope, &["payload", "payloadType", "signatures"])?;
    let payload_type = json_member(envelope, "payloadType")?.string()?;
    if payload_type != "application/vnd.hell-rs.assurance+json" {
        return Err(format!("unsupported review payload type {payload_type:?}"));
    }
    let payload = decode_base64(json_member(envelope, "payload")?.string()?)?;
    let payload_text =
        std::str::from_utf8(&payload).map_err(|_| "review payload is not UTF-8".to_owned())?;
    let payload_json = parse_json(payload_text)?;
    let payload_object = payload_json.object()?;
    let schema_version = json_member(payload_object, "schemaVersion")?.number()?;
    let mut payload_keys = vec![
        "assuranceEpochSha256",
        "candidateCommit",
        "decision",
        "distinctSubjects",
        "findings",
        "independenceViolations",
        "issuedAt",
        "reviewId",
        "reviewedArtifacts",
        "reviewer",
        "role",
        "schemaVersion",
    ];
    if schema_version == 2 {
        payload_keys.push("reviewedClaimGroups");
        payload_keys.sort_unstable();
    } else if schema_version != 1 {
        return Err("review payload schemaVersion is unsupported".to_owned());
    }
    exact_keys(payload_object, &payload_keys)?;
    let reviewed_claim_groups = if schema_version == 2 {
        reviewed_claim_group_bindings(json_member(payload_object, "reviewedClaimGroups")?)?
    } else {
        BTreeMap::new()
    };
    let decision = json_member(payload_object, "decision")?.string()?;
    if decision != "accept" {
        return Err("review decision is not accept".to_owned());
    }
    let candidate_commit = json_member(payload_object, "candidateCommit")?
        .string()?
        .to_owned();
    require_git_sha_text(&candidate_commit, "review candidate")?;
    let assurance_epoch = json_member(payload_object, "assuranceEpochSha256")?
        .string()?
        .to_owned();
    require_digest(&assurance_epoch, "review assurance epoch")?;
    let artifacts = json_member(payload_object, "reviewedArtifacts")?.array()?;
    if artifacts.is_empty() {
        return Err("reviewedArtifacts must not be empty".to_owned());
    }
    let mut reviewed_artifacts = BTreeSet::new();
    for artifact in artifacts {
        let artifact = artifact.string()?.to_owned();
        require_digest(&artifact, "reviewed artifact")?;
        if !reviewed_artifacts.insert(artifact) {
            return Err("reviewedArtifacts contains a duplicate digest".to_owned());
        }
    }
    if json_member(payload_object, "distinctSubjects")?.number()? == 0 {
        return Err("review payload has no accountable subject".to_owned());
    }
    if !json_member(payload_object, "independenceViolations")?
        .array()?
        .is_empty()
    {
        return Err("review contains separation-of-duties violations".to_owned());
    }
    let findings_sha256 = validate_review_findings(
        json_member(payload_object, "findings")?,
        true,
        &reviewed_artifacts,
    )?;
    let issued_at = json_member(payload_object, "issuedAt")?
        .string()?
        .to_owned();
    validate_utc_timestamp(&issued_at)?;
    let issued_seconds = utc_timestamp_seconds(&issued_at)?;
    let config_root = allowed_signers
        .parent()
        .ok_or_else(|| "allowed signers has no policy directory".to_owned())?;
    if issued_seconds > current_seconds {
        return Err("review statement is future-dated".to_owned());
    }
    if matches!(context, ReviewValidationContext::Fresh) {
        let surveillance = read_text(&config_root.join("surveillance-policy.toml"))?;
        let maximum_age_days = assignment_u64(&surveillance, "mutation_report_maximum_age_days")?;
        if maximum_age_days == 0 {
            return Err("review maximum age must be nonzero".to_owned());
        }
        let maximum_age = maximum_age_days
            .checked_mul(86_400)
            .ok_or_else(|| "review maximum age overflows".to_owned())?;
        if current_seconds.saturating_sub(issued_seconds) > maximum_age {
            return Err("review statement is stale".to_owned());
        }
    }
    let review_id = json_member(payload_object, "reviewId")?.string()?;
    require_digest(review_id, "review statement ID")?;
    let reviewer = json_member(payload_object, "reviewer")?
        .string()?
        .to_owned();
    let role = json_member(payload_object, "role")?.string()?.to_owned();
    if !matches!(
        role.as_str(),
        "artifact-trust-reviewer"
            | "claim-author"
            | "claim-reviewer"
            | "custody-provider"
            | "custody-reviewer"
            | "divergence-reviewer"
            | "divergence-platform-reviewer"
            | "divergence-implementation-reviewer"
            | "divergence-product-reviewer"
            | "divergence-security-reviewer"
            | "mutation-reviewer"
            | "normalizer-reviewer"
            | "oracle-builder"
            | "platform-reviewer"
            | "promotion-approver"
            | "review-graph-reviewer"
            | "regression-reviewer"
            | "residual-risk-reviewer"
    ) {
        return Err(format!("review role {role:?} is not authorized by policy"));
    }
    if !reviewer.starts_with(&format!("{role}:")) {
        return Err("reviewer principal is not authorized for the signed role".to_owned());
    }
    if review_id
        != review_statement_id(&ReviewStatementIdentity {
            candidate: &candidate_commit,
            epoch: &assurance_epoch,
            role: &role,
            reviewer: &reviewer,
            decision,
            issued_at: &issued_at,
            artifacts: &reviewed_artifacts,
            claim_groups: &reviewed_claim_groups,
            findings_sha256: &findings_sha256,
        })
    {
        return Err("review statement ID is not derived from signed content".to_owned());
    }
    let revocations_path = match context {
        ReviewValidationContext::Fresh => config_root.join("review-revocations.toml"),
        ReviewValidationContext::Historical {
            current_revocations,
        } => current_revocations.to_path_buf(),
    };
    let revocations = read_text(&revocations_path)?;
    if assignment_string_array(&revocations, "revoked_review_ids")?
        .iter()
        .any(|revoked| revoked == review_id)
    {
        return Err("review statement has been revoked by governance".to_owned());
    }
    let signatures = json_member(envelope, "signatures")?.array()?;
    let required_schemes = required_signature_schemes(allowed_signers)?;
    if signatures.len() != required_schemes.len() {
        return Err("review envelope signature count does not match trust policy".to_owned());
    }
    let mut observed_schemes = BTreeSet::new();
    let mut signer_fingerprint = None;
    for signature in signatures {
        let signature = signature.object()?;
        let scheme = json_member(signature, "scheme")?.string()?;
        if !observed_schemes.insert(scheme.to_owned()) || !required_schemes.contains(scheme) {
            return Err(
                "review envelope has a duplicate or unauthorized signature scheme".to_owned(),
            );
        }
        match scheme {
            "ssh" => {
                exact_keys(signature, &["keyid", "scheme", "sig"])?;
                let key_id = json_member(signature, "keyid")?.string()?;
                if key_id != reviewer {
                    return Err("signature key identity does not match reviewer".to_owned());
                }
                let signature_bytes = decode_base64(json_member(signature, "sig")?.string()?)?;
                verify_ssh_signature(allowed_signers, key_id, &payload, &signature_bytes)?;
                signer_fingerprint = Some(allowed_signer_key_fingerprint(allowed_signers, key_id)?);
            }
            "sigstore" => {
                exact_keys(
                    signature,
                    &[
                        "bundle",
                        "certificateIdentity",
                        "certificateIssuer",
                        "scheme",
                    ],
                )?;
                verify_sigstore_signature(allowed_signers, signature, &payload)?;
            }
            _ => return Err(format!("unsupported signature scheme {scheme:?}")),
        }
    }
    if observed_schemes != required_schemes {
        return Err("review envelope omits a required signature scheme".to_owned());
    }
    let subject = reviewer
        .split_once(':')
        .map(|(_, subject)| subject)
        .filter(|subject| !subject.is_empty())
        .ok_or_else(|| "reviewer principal lacks a stable subject ID".to_owned())?
        .to_owned();
    Ok(VerifiedReview {
        role,
        reviewer,
        subject,
        signer_fingerprint: signer_fingerprint
            .ok_or_else(|| "review envelope lacks the required SSH identity".to_owned())?,
        candidate_commit,
        assurance_epoch,
        issued_at,
        artifact_count: artifacts.len(),
        reviewed_artifacts,
        reviewed_claim_groups,
    })
}

pub fn fuzz_admit_dsse_envelope(bytes: &[u8]) -> Result<(), String> {
    admit_review_envelope_bytes(bytes)
}

fn admit_review_envelope_bytes(bytes: &[u8]) -> Result<(), String> {
    let document = std::str::from_utf8(bytes)
        .map_err(|_| "review envelope is not canonical UTF-8".to_owned())?;
    let envelope = parse_json(document)?;
    let envelope = envelope.object()?;
    exact_keys(envelope, &["payload", "payloadType", "signatures"])?;
    if json_member(envelope, "payloadType")?.string()? != "application/vnd.hell-rs.assurance+json" {
        return Err("review envelope has the wrong payload type".to_owned());
    }
    let payload = decode_base64(json_member(envelope, "payload")?.string()?)?;
    let payload = std::str::from_utf8(&payload)
        .map_err(|_| "review payload is not canonical UTF-8".to_owned())?;
    admit_review_payload(parse_json(payload)?.object()?)?;
    admit_review_signatures(json_member(envelope, "signatures")?.array()?)
}

fn admit_review_payload(payload: &BTreeMap<String, JsonValue>) -> Result<(), String> {
    let schema = json_member(payload, "schemaVersion")?.number()?;
    let mut keys = vec![
        "assuranceEpochSha256",
        "candidateCommit",
        "decision",
        "distinctSubjects",
        "findings",
        "independenceViolations",
        "issuedAt",
        "reviewId",
        "reviewedArtifacts",
        "reviewer",
        "role",
        "schemaVersion",
    ];
    if schema == 2 {
        keys.push("reviewedClaimGroups");
        keys.sort_unstable();
    } else if schema != 1 {
        return Err("review payload schema is unsupported".to_owned());
    }
    exact_keys(payload, &keys)?;
    if json_member(payload, "decision")?.string()? != "accept"
        || json_member(payload, "distinctSubjects")?.number()? == 0
        || !json_member(payload, "independenceViolations")?
            .array()?
            .is_empty()
    {
        return Err("review payload state is invalid".to_owned());
    }
    let candidate = json_member(payload, "candidateCommit")?.string()?;
    let epoch = json_member(payload, "assuranceEpochSha256")?.string()?;
    require_git_sha_text(candidate, "review candidate")?;
    require_digest(epoch, "review epoch")?;
    let role = json_member(payload, "role")?.string()?;
    let reviewer = json_member(payload, "reviewer")?.string()?;
    if !reviewer.starts_with(&format!("{role}:")) {
        return Err("review payload role and reviewer differ".to_owned());
    }
    let mut artifacts = BTreeSet::new();
    for artifact in json_member(payload, "reviewedArtifacts")?.array()? {
        require_digest(artifact.string()?, "reviewed artifact")?;
        if !artifacts.insert(artifact.string()?.to_owned()) {
            return Err("review payload repeats an artifact".to_owned());
        }
    }
    if artifacts.is_empty() {
        return Err("review payload has no artifact".to_owned());
    }
    let findings = validate_review_findings(json_member(payload, "findings")?, true, &artifacts)?;
    let claim_groups = if schema == 2 {
        reviewed_claim_group_bindings(json_member(payload, "reviewedClaimGroups")?)?
    } else {
        BTreeMap::new()
    };
    let issued_at = json_member(payload, "issuedAt")?.string()?;
    validate_utc_timestamp(issued_at)?;
    let expected = review_statement_id(&ReviewStatementIdentity {
        candidate,
        epoch,
        role,
        reviewer,
        decision: "accept",
        issued_at,
        artifacts: &artifacts,
        claim_groups: &claim_groups,
        findings_sha256: &findings,
    });
    if json_member(payload, "reviewId")?.string()? != expected {
        return Err("review payload ID is not content-derived".to_owned());
    }
    Ok(())
}

fn admit_review_signatures(signatures: &[JsonValue]) -> Result<(), String> {
    let mut schemes = BTreeSet::new();
    for signature in signatures {
        let signature = signature.object()?;
        let scheme = json_member(signature, "scheme")?.string()?;
        if !schemes.insert(scheme) {
            return Err("review envelope repeats a signature scheme".to_owned());
        }
        match scheme {
            "ssh" => {
                exact_keys(signature, &["keyid", "scheme", "sig"])?;
                if json_member(signature, "keyid")?.string()?.is_empty()
                    || decode_base64(json_member(signature, "sig")?.string()?)?.is_empty()
                {
                    return Err("review SSH signature is incomplete".to_owned());
                }
            }
            "sigstore" => {
                exact_keys(
                    signature,
                    &[
                        "bundle",
                        "certificateIdentity",
                        "certificateIssuer",
                        "scheme",
                    ],
                )?;
                if decode_base64(json_member(signature, "bundle")?.string()?)?.is_empty()
                    || json_member(signature, "certificateIdentity")?
                        .string()?
                        .is_empty()
                    || json_member(signature, "certificateIssuer")?
                        .string()?
                        .is_empty()
                {
                    return Err("review Sigstore signature is incomplete".to_owned());
                }
            }
            _ => return Err("review envelope has an unsupported signature scheme".to_owned()),
        }
    }
    if schemes.is_empty() {
        return Err("review envelope has no signature".to_owned());
    }
    Ok(())
}

fn allowed_signer_key_fingerprint(path: &Path, identity: &str) -> Result<String, String> {
    let document = read_text(path)?;
    let mut matched = None;
    for line in document.lines().map(str::trim) {
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let fields = line.split_whitespace().collect::<Vec<_>>();
        if fields.len() < 3 || !fields[0].split(',').any(|principal| principal == identity) {
            continue;
        }
        let fingerprint = sha256_bytes(format!("{} {}", fields[1], fields[2]).as_bytes()).hex();
        if matched.replace(fingerprint).is_some() {
            return Err(format!("allowed-signers repeats principal {identity:?}"));
        }
    }
    matched.ok_or_else(|| format!("allowed-signers does not authorize principal {identity:?}"))
}

fn stage_allowed_signer_public_key(
    policy: &Path,
    identity: &str,
    output: &Path,
) -> Result<(), String> {
    let document = read_text(policy)?;
    let mut matched = None;
    for line in document.lines().map(str::trim) {
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let fields = line.split_whitespace().collect::<Vec<_>>();
        if fields.len() < 3 || !fields[0].split(',').any(|principal| principal == identity) {
            continue;
        }
        let key = format!("{} {}\n", fields[1], fields[2]);
        if matched.replace(key).is_some() {
            return Err(format!("allowed-signers repeats principal {identity:?}"));
        }
    }
    let key = matched
        .ok_or_else(|| format!("allowed-signers does not authorize principal {identity:?}"))?;
    let mut file = fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(output)
        .map_err(|error| format!("cannot stage reviewer public key: {error}"))?;
    file.write_all(key.as_bytes())
        .map_err(|error| format!("cannot write reviewer public key: {error}"))?;
    file.sync_all()
        .map_err(|error| format!("cannot sync reviewer public key: {error}"))
}

fn required_signature_schemes(allowed_signers: &Path) -> Result<BTreeSet<String>, String> {
    let Some(directory) = allowed_signers.parent() else {
        return Ok(BTreeSet::from(["ssh".to_owned()]));
    };
    let trust_roots = directory.join("trust-roots.toml");
    if !trust_roots.is_file() {
        return Ok(BTreeSet::from(["ssh".to_owned()]));
    }
    let document = read_text(&trust_roots)?;
    let schemes = assignment_string_array(&document, "required_signature_types")?;
    if schemes.iter().collect::<BTreeSet<_>>().len() != schemes.len() {
        return Err("trust roots repeat a required signature type".to_owned());
    }
    let observed = schemes.into_iter().collect::<BTreeSet<_>>();
    let expected = BTreeSet::from(["sigstore".to_owned(), "ssh".to_owned()]);
    if observed != expected {
        return Err("trust roots must require exactly Sigstore and SSH".to_owned());
    }
    Ok(observed)
}

fn assignment_string_array(document: &str, key: &str) -> Result<Vec<String>, String> {
    let mut lines = document.lines().map(str::trim).peekable();
    let mut value = None;
    while let Some(line) = lines.next() {
        if line.starts_with('#') || line.is_empty() {
            continue;
        }
        let Some((candidate, first)) = line.split_once('=') else {
            continue;
        };
        if candidate.trim() != key {
            continue;
        }
        let mut collected = first.trim().to_owned();
        while !collected.ends_with(']') {
            let continuation = lines
                .next()
                .ok_or_else(|| format!("assignment {key} has an unterminated array"))?;
            if continuation.starts_with('#') {
                continue;
            }
            collected.push_str(continuation);
        }
        value = Some(collected);
        break;
    }
    let value = value.ok_or_else(|| format!("missing assignment {key}"))?;
    let inner = value
        .strip_prefix('[')
        .and_then(|value| value.strip_suffix(']'))
        .ok_or_else(|| format!("assignment {key} is not an array"))?;
    if inner.trim().is_empty() {
        return Ok(Vec::new());
    }
    let mut values = Vec::new();
    for value in inner
        .split(',')
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        let value = value
            .strip_prefix('"')
            .and_then(|value| value.strip_suffix('"'))
            .ok_or_else(|| format!("assignment {key} has a non-string member"))?;
        values.push(value.to_owned());
    }
    Ok(values)
}

fn verify_ssh_signature(
    allowed_signers: &Path,
    identity: &str,
    payload: &[u8],
    signature: &[u8],
) -> Result<(), String> {
    let directory = create_private_temp_directory("hell-review-verify")?;
    let temporary = directory.join("signature.sig");
    let result = (|| {
        let mut file = fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&temporary)
            .map_err(|error| format!("cannot create temporary signature: {error}"))?;
        file.write_all(signature)
            .map_err(|error| format!("cannot write temporary signature: {error}"))?;
        let mut child = Command::new("ssh-keygen")
            .args([
                OsStr::new("-Y"),
                OsStr::new("verify"),
                OsStr::new("-f"),
                allowed_signers.as_os_str(),
                OsStr::new("-I"),
                OsStr::new(identity),
                OsStr::new("-n"),
                OsStr::new("hell-rs-promotion-review"),
                OsStr::new("-s"),
                temporary.as_os_str(),
            ])
            .stdin(Stdio::piped())
            .stdout(Stdio::null())
            .stderr(Stdio::piped())
            .spawn()
            .map_err(|error| format!("cannot run ssh-keygen signature verifier: {error}"))?;
        child
            .stdin
            .as_mut()
            .ok_or_else(|| "ssh-keygen verifier stdin is unavailable".to_owned())?
            .write_all(payload)
            .map_err(|error| format!("cannot send payload to signature verifier: {error}"))?;
        let output = child
            .wait_with_output()
            .map_err(|error| format!("cannot wait for signature verifier: {error}"))?;
        if !output.status.success() {
            return Err(format!(
                "SSH review signature verification failed: {}",
                String::from_utf8_lossy(&output.stderr)
            ));
        }
        Ok(())
    })();
    let _ = fs::remove_dir_all(&directory);
    result
}

fn verify_sigstore_signature(
    allowed_signers: &Path,
    signature: &BTreeMap<String, JsonValue>,
    payload: &[u8],
) -> Result<(), String> {
    let directory = allowed_signers
        .parent()
        .ok_or_else(|| "allowed-signers policy has no trust-root directory".to_owned())?;
    let trust_roots = read_text(&directory.join("trust-roots.toml"))?;
    let issuer = json_member(signature, "certificateIssuer")?.string()?;
    let identity = json_member(signature, "certificateIdentity")?.string()?;
    let accepted_issuer = assignment_string(&trust_roots, "github_oidc_issuer")?;
    let repository = assignment_string(&trust_roots, "repository")?;
    let trusted_ref = assignment_string(&trust_roots, "trusted_workflow_ref")?;
    if trusted_ref != "refs/heads/main" {
        return Err("trust roots must bind protected workflow identity to main".to_owned());
    }
    let payload_document = parse_json(
        std::str::from_utf8(payload).map_err(|_| "Sigstore payload is not UTF-8".to_owned())?,
    )?;
    let payload_role = json_member(payload_document.object()?, "role")?.string()?;
    let workflow_keys = sigstore_workflow_keys(payload_role)?;
    let workflows = workflow_keys
        .iter()
        .map(|key| exact_assignment_string(&trust_roots, key))
        .collect::<Result<Vec<_>, _>>()?;
    validate_linux_release_workflow_domain(payload_role, &workflows)?;
    let identity_allowed = workflows.iter().any(|workflow| {
        github_workflow_identity_matches(identity, &repository, workflow, &trusted_ref)
    });
    if issuer != accepted_issuer || !identity_allowed {
        return Err("Sigstore certificate issuer or workflow identity is not trusted".to_owned());
    }
    let bundle = decode_base64(json_member(signature, "bundle")?.string()?)?;
    let bundle_text = std::str::from_utf8(&bundle)
        .map_err(|_| "Sigstore verification bundle is not UTF-8".to_owned())?;
    parse_json(bundle_text)?;
    let temporary = create_private_temp_directory("hell-sigstore-verify")?;
    let payload_path = temporary.join("payload.json");
    let bundle_path = temporary.join("bundle.json");
    for (path, bytes) in [(&payload_path, payload), (&bundle_path, bundle.as_slice())] {
        let mut file = fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(path)
            .map_err(|error| format!("cannot stage Sigstore input: {error}"))?;
        file.write_all(bytes)
            .map_err(|error| format!("cannot write Sigstore input: {error}"))?;
        file.sync_all()
            .map_err(|error| format!("cannot sync Sigstore input: {error}"))?;
    }
    let result = run_sigstore_verify_blob(&bundle_path, identity, issuer, &payload_path);
    let _ = fs::remove_dir_all(&temporary);
    result
}

fn sigstore_verify_blob_arguments(
    bundle: &Path,
    identity: &str,
    issuer: &str,
    payload: &Path,
) -> Vec<OsString> {
    vec![
        OsString::from("verify-blob"),
        OsString::from("--bundle"),
        bundle.as_os_str().to_owned(),
        OsString::from("--certificate-identity"),
        OsString::from(identity),
        OsString::from("--certificate-oidc-issuer"),
        OsString::from(issuer),
        payload.as_os_str().to_owned(),
    ]
}

fn run_sigstore_verify_blob(
    bundle: &Path,
    identity: &str,
    issuer: &str,
    payload: &Path,
) -> Result<(), String> {
    let invocation = SigstoreVerifyInvocation {
        arguments: sigstore_verify_blob_arguments(bundle, identity, issuer, payload),
        #[cfg(test)]
        bundle: bundle.to_owned(),
        #[cfg(test)]
        payload: payload.to_owned(),
    };
    #[cfg(test)]
    if let Some(result) = invoke_test_sigstore_verifier(&invocation) {
        return result;
    }
    let result = Command::new("cosign")
        .args(&invocation.arguments)
        .stdout(Stdio::null())
        .stderr(Stdio::piped())
        .output()
        .map_err(|error| format!("cannot run Sigstore verifier: {error}"))?;
    verify_sigstore_process_result(result.status.success(), &result.stderr)
}

struct SigstoreVerifyInvocation {
    arguments: Vec<OsString>,
    #[cfg(test)]
    bundle: PathBuf,
    #[cfg(test)]
    payload: PathBuf,
}

#[cfg(test)]
type TestSigstoreVerifier = Box<dyn Fn(&SigstoreVerifyInvocation) -> Result<(), String>>;

#[cfg(test)]
std::thread_local! {
    static TEST_SIGSTORE_VERIFIER: std::cell::RefCell<Option<TestSigstoreVerifier>> =
        std::cell::RefCell::new(None);
}

#[cfg(test)]
fn invoke_test_sigstore_verifier(
    invocation: &SigstoreVerifyInvocation,
) -> Option<Result<(), String>> {
    TEST_SIGSTORE_VERIFIER.with(|verifier| {
        verifier
            .borrow()
            .as_ref()
            .map(|verifier| verifier(invocation))
    })
}

#[cfg(test)]
struct TestSigstoreVerifierGuard;

#[cfg(test)]
impl TestSigstoreVerifierGuard {
    fn install(verifier: TestSigstoreVerifier) -> Result<Self, String> {
        TEST_SIGSTORE_VERIFIER.with(|slot| {
            let mut slot = slot.borrow_mut();
            if slot.is_some() {
                return Err("test Sigstore verifier is already installed".to_owned());
            }
            *slot = Some(verifier);
            Ok(Self)
        })
    }
}

#[cfg(test)]
impl Drop for TestSigstoreVerifierGuard {
    fn drop(&mut self) {
        TEST_SIGSTORE_VERIFIER.with(|slot| {
            slot.borrow_mut().take();
        });
    }
}

fn sigstore_workflow_keys(payload_role: &str) -> Result<&'static [&'static str], String> {
    Ok(match payload_role {
        "artifact-primary-producer" => &["artifact_primary_workflow"],
        "artifact-independent-acquirer" => &["artifact_independent_workflow"],
        "artifact-trust-reviewer" => &["artifact_review_workflow"],
        "mutation-reviewer" => &["mutation_workflow", "surveillance_workflow"],
        "oracle-builder" | "platform-reviewer" => &["oracle_workflow"],
        "linux-release-acquirer" => &["release_oracle_workflow"],
        "collection-linux-release-acquirer" => &["collection_release_oracle_workflow"],
        "custody-reviewer" => &[
            "custody_workflow",
            "collection_custody_review_workflow",
            "surveillance_workflow",
            "surveillance_watchdog_workflow",
        ],
        "custody-provider" => &[
            "custody_workflow",
            "custody_scrub_workflow",
            "surveillance_workflow",
        ],
        "promotion-approver" => &["approval_workflow"],
        "claim-author" | "claim-reviewer" => &["collection_activation_workflow"],
        "review-graph-reviewer"
        | "divergence-reviewer"
        | "divergence-platform-reviewer"
        | "divergence-implementation-reviewer"
        | "divergence-product-reviewer"
        | "divergence-security-reviewer"
        | "normalizer-reviewer"
        | "residual-risk-reviewer" => &["review_workflow"],
        "regression-reviewer" => &["regression_review_workflow"],
        "assurance-transport-probe-a" => &["transport_probe_a_workflow"],
        "assurance-transport-probe-b" => &["transport_probe_b_workflow"],
        _ => return Err("Sigstore payload role has no trusted workflow mapping".to_owned()),
    })
}

fn exact_assignment_string(document: &str, key: &str) -> Result<String, String> {
    let values = document
        .lines()
        .map(str::trim)
        .filter(|line| !line.starts_with('#'))
        .filter_map(|line| {
            let (candidate, value) = line.split_once('=')?;
            (candidate.trim() == key).then_some(value.trim())
        })
        .collect::<Vec<_>>();
    let [value] = values.as_slice() else {
        return Err(format!("trust roots require exactly one {key} assignment"));
    };
    value
        .strip_prefix('"')
        .and_then(|value| value.strip_suffix('"'))
        .map(str::to_owned)
        .ok_or_else(|| format!("{key} is not a quoted string"))
}

fn validate_linux_release_workflow_domain(
    payload_role: &str,
    workflows: &[String],
) -> Result<(), String> {
    let expected = match payload_role {
        "linux-release-acquirer" => Some(".github/workflows/nightly.yml"),
        "collection-linux-release-acquirer" => Some(".github/workflows/collection-authority.yml"),
        _ => None,
    };
    if expected.is_some_and(|expected| workflows != [expected]) {
        return Err("Linux release acquisition trust domain is not exact".to_owned());
    }
    Ok(())
}

fn verify_sigstore_process_result(success: bool, stderr: &[u8]) -> Result<(), String> {
    if success {
        Ok(())
    } else {
        Err(external_service_error(
            "Sigstore certificate or transparency proof verification failed",
            ExternalServiceOperation::ProtectedAdmission,
            &String::from_utf8_lossy(stderr),
        ))
    }
}

#[allow(clippy::too_many_lines)]
fn promotion_proposal(root: &Path, options: &Options) -> Result<String, String> {
    let assurance_policy = load_assurance_policy(root)?;
    let output = required_path(&options.output, "promotion-proposal requires --output")?;
    let input = required_path(&options.input, "promotion-proposal requires --input")?;
    let source_identity = if options.github_dispatch_inputs {
        Some(validate_proposal_assembly_dispatch(root, input)?)
    } else {
        None
    };
    let (_, epoch_digest) = epoch(root)?;
    let source = git_output(root, &["rev-parse", "HEAD"])?;
    if let Some(expected) = &options.expect_source
        && source.trim() != expected
    {
        return Err(format!(
            "candidate source mismatch: expected {expected}, observed {}",
            source.trim()
        ));
    }
    if let Some(expected) = &options.expect_epoch
        && epoch_digest.hex() != *expected
    {
        return Err(format!(
            "assurance epoch mismatch: expected {expected}, observed {}",
            epoch_digest.hex()
        ));
    }
    let manifest = input.join("merged-native-shards.json");
    let merged = read_regular_file(&manifest)?;
    let allowed_signers = root.join("compat").join("reviews.allowed_signers");
    let records = promotion_record_paths(input);
    let mut blockers = BTreeMap::<&str, u64>::new();
    blockers.insert(
        "untrustedAcquisitionReceipts",
        u64::from(
            artifact_verify(
                root,
                &Options {
                    input: records.get("artifactAuthenticity").cloned(),
                    policy: Some(allowed_signers.clone()),
                    ..Options::default()
                },
            )
            .is_err(),
        ),
    );
    let mut oracle_blockers = 0_u64;
    for name in ["oracleProvenanceMacos", "oracleProvenanceWindows"] {
        oracle_blockers += u64::from(
            oracle_provenance(
                root,
                &Options {
                    action: Some("verify".to_owned()),
                    input: records.get(name).cloned(),
                    policy: Some(allowed_signers.clone()),
                    ..Options::default()
                },
            )
            .is_err(),
        );
    }
    blockers.insert("unreviewedOracleProvenance", oracle_blockers);
    let claim_record = records
        .get("claimCoverage")
        .expect("required claim coverage record exists");
    blockers.insert(
        "ambiguousClaimScopes",
        verified_claim_report_counter(
            claim_record,
            &allowed_signers,
            source.trim(),
            &epoch_digest.hex(),
            &input.join("evidence"),
            "ambiguousClaimScopes",
        )
        .unwrap_or(1),
    );
    blockers.insert(
        "semanticCoverageGaps",
        verified_claim_report_counter(
            claim_record,
            &allowed_signers,
            source.trim(),
            &epoch_digest.hex(),
            &input.join("evidence"),
            "semanticCoverageGaps",
        )
        .unwrap_or(1),
    );
    let generic = [
        (
            "normalizerAudit",
            "normalizer-audit",
            "normalizer-reviewer",
            "unsafeNormalizers",
        ),
        (
            "divergence",
            "divergence",
            "divergence-reviewer",
            "unapprovedDivergences",
        ),
        (
            "residualRisk",
            "residual-risk",
            "residual-risk-reviewer",
            "residualRiskPolicyFailures",
        ),
        (
            "reviewRoleGraph",
            "review-role-graph",
            "review-graph-reviewer",
            "reviewIndependenceFailures",
        ),
    ];
    for (name, kind, role, blocker) in generic {
        blockers.insert(
            blocker,
            u64::from(
                verify_bound_report(
                    records.get(name).expect("required record path exists"),
                    &allowed_signers,
                    kind,
                    role,
                    source.trim(),
                    &epoch_digest.hex(),
                    &input.join("evidence"),
                )
                .is_err(),
            ),
        );
    }
    let divergence_approval_failure = u64::from(
        verify_divergence_tier_approvals(
            records
                .get("divergence")
                .expect("required divergence record exists"),
            &input.join("evidence"),
            &allowed_signers,
            source.trim(),
            &epoch_digest.hex(),
        )
        .is_err(),
    );
    blockers
        .entry("unapprovedDivergences")
        .and_modify(|count| *count = (*count).max(divergence_approval_failure));
    blockers.insert(
        "statusEvidenceMismatches",
        u64::from(
            verify_claim_status_consistency(
                records
                    .get("claimCoverage")
                    .expect("required claim coverage record exists"),
                records
                    .get("normalizerAudit")
                    .expect("required normalizer audit record exists"),
                records
                    .get("divergence")
                    .expect("required divergence record exists"),
                &input.join("evidence"),
            )
            .is_err(),
        ),
    );
    blockers.insert(
        "reviewIndependenceFailures",
        u64::from(
            verify_actual_review_graph(
                &records,
                &input.join("evidence"),
                &allowed_signers,
                source.trim(),
                &epoch_digest.hex(),
            )
            .is_err(),
        ),
    );
    let custody_blocked = u64::from(
        custody_command(&Options {
            action: Some("verify".to_owned()),
            input: records.get("custody").cloned(),
            policy: Some(allowed_signers.clone()),
            ..Options::default()
        })
        .is_err(),
    );
    blockers.insert("unverifiedCustodyReceipts", custody_blocked);
    let custody_policy = read_text(&root.join("compat").join("custody-policy.toml"));
    let scrub_interval_days =
        custody_policy.and_then(|policy| assignment_u64(&policy, "scrub_interval_days"));
    let scrub_root = input.join("evidence").join("custody").join("current-scrub");
    let primary_scrub = scrub_root.join("primary-worm");
    let secondary_scrub = scrub_root.join("secondary-worm");
    let scrub_verified = scrub_interval_days.and_then(|maximum_age_days| {
        crate::custody_ops::verify_current_scrub_set(
            &primary_scrub.join("scrub-receipt.json"),
            &primary_scrub.join("custody-maintenance-receipt.dsse.json"),
            &secondary_scrub.join("scrub-receipt.json"),
            &secondary_scrub.join("custody-maintenance-receipt.dsse.json"),
            &allowed_signers,
            records
                .get("custody")
                .expect("required custody record exists"),
            source.trim(),
            &epoch_digest.hex(),
            maximum_age_days,
        )
    });
    blockers.insert(
        "failedCustodyScrubs",
        u64::from(assurance_policy.require_current_scrub && scrub_verified.is_err()),
    );
    let mutation_blocked = u64::from(
        retained_report_command(
            root,
            &Options {
                input: records.get("mutation").cloned(),
                policy: Some(allowed_signers.clone()),
                expect_source: Some(source.trim().to_owned()),
                expect_epoch: Some(epoch_digest.hex()),
                ..Options::default()
            },
            "mutation",
        )
        .is_err(),
    );
    blockers.insert("undetectedCriticalMutants", mutation_blocked);
    blockers.insert("staleEvidenceEpochs", u64::from(source_identity.is_none()));
    blockers.insert(
        "unmappedReviewStatements",
        human_review_statement_mapping_gaps(&records, &input.join("evidence"), &allowed_signers)
            .unwrap_or(1),
    );
    if blockers.keys().copied().collect::<BTreeSet<_>>()
        != PROMOTION_BLOCKERS.iter().copied().collect()
    {
        return Err("promotion proposal blocker set drifted from policy".to_owned());
    }
    let blocker_count = blockers.values().copied().sum::<u64>();
    let blocker_document = blockers
        .iter()
        .map(|(name, count)| ((*name).to_owned(), JsonValue::Number(*count)))
        .collect::<BTreeMap<_, _>>();
    let blockers_sha256 = blocker_set_digest(&blocker_document)?;
    let merged_sha256 = sha256_bytes(&merged).hex();
    let final_merged_document = JsonValue::Object(BTreeMap::from([
        (
            "assuranceEpochSha256".to_owned(),
            JsonValue::String(epoch_digest.hex()),
        ),
        (
            "blockersSha256".to_owned(),
            JsonValue::String(blockers_sha256),
        ),
        (
            "candidateSourceCommit".to_owned(),
            JsonValue::String(source.trim().to_owned()),
        ),
        (
            "mechanicalMergedManifestSha256".to_owned(),
            JsonValue::String(merged_sha256.clone()),
        ),
        (
            "mechanicalPromotionReady".to_owned(),
            JsonValue::Bool(false),
        ),
        (
            "promotionReady".to_owned(),
            JsonValue::Bool(blocker_count == 0),
        ),
        ("schemaVersion".to_owned(), JsonValue::Number(1)),
    ]));
    let final_merged_bytes = canonical_json_bytes(&final_merged_document)?;
    let final_merged_path = output
        .parent()
        .ok_or_else(|| "promotion proposal output has no retained directory".to_owned())?
        .join("merged-native-shards.final.json");
    write_atomic(&final_merged_path, &final_merged_bytes)?;
    let final_merged_sha256 = sha256_bytes(&final_merged_bytes).hex();
    let mut json = String::from("{\n  \"schemaVersion\": 1,\n  \"candidateSourceCommit\": ");
    push_json(&mut json, source.trim());
    json.push_str(",\n  \"assuranceEpochSha256\": ");
    push_json(&mut json, &epoch_digest.hex());
    json.push_str(",\n  \"mergedManifestSha256\": ");
    push_json(&mut json, &merged_sha256);
    json.push_str(",\n  \"finalMergedManifestSha256\": ");
    push_json(&mut json, &final_merged_sha256);
    json.push_str(",\n  \"sourceEvidence\": ");
    if let Some(identity) = &source_identity {
        write!(
            json,
            "{{\"evidenceRunId\":{},\"evidenceRunAttempt\":{},\"evidenceArtifactId\":{},\"evidenceArtifactName\":\"native-oracle-merged\",\"evidenceSha256\":{},\"evidencePackageSha256\":{},\"evidenceSelectionSha256\":{},\"reviewRunId\":{},\"reviewRunAttempt\":{},\"reviewArtifactId\":{},\"reviewArtifactName\":\"promotion-final-reviewed-evidence\",\"reviewSha256\":{},\"reviewSelectionSha256\":{},\"custodyRunId\":{},\"custodyRunAttempt\":{},\"custodyArtifactId\":{},\"custodyArtifactName\":\"promotion-custody-evidence\",\"custodySha256\":{},\"custodySelectionSha256\":{},\"primaryScrubRunId\":{},\"primaryScrubRunAttempt\":{},\"primaryScrubArtifactId\":{},\"primaryScrubArtifactName\":{},\"primaryScrubSha256\":{},\"primaryScrubSelectionSha256\":{},\"secondaryScrubRunId\":{},\"secondaryScrubRunAttempt\":{},\"secondaryScrubArtifactId\":{},\"secondaryScrubArtifactName\":{},\"secondaryScrubSha256\":{},\"secondaryScrubSelectionSha256\":{}}}",
            identity.evidence_run_id,
            identity.evidence_run_attempt,
            identity.evidence_artifact_id,
            json_string(&identity.merged_sha256),
            json_string(&identity.evidence_package_sha256),
            json_string(&identity.evidence_selection_sha256),
            identity.review_run_id,
            identity.review_run_attempt,
            identity.review_artifact_id,
            json_string(&identity.review_sha256),
            json_string(&identity.review_selection_sha256),
            identity.custody_run_id,
            identity.custody_run_attempt,
            identity.custody_artifact_id,
            json_string(&identity.custody_sha256),
            json_string(&identity.custody_selection_sha256),
            identity.primary_scrub_run_id,
            identity.primary_scrub_run_attempt,
            identity.primary_scrub_artifact_id,
            json_string(&format!(
                "ephemeralEvidence-current-scrub-primary-worm-{}-{}",
                identity.primary_scrub_run_id, identity.primary_scrub_run_attempt
            )),
            json_string(&identity.primary_scrub_sha256),
            json_string(&identity.primary_scrub_selection_sha256),
            identity.secondary_scrub_run_id,
            identity.secondary_scrub_run_attempt,
            identity.secondary_scrub_artifact_id,
            json_string(&format!(
                "ephemeralEvidence-current-scrub-secondary-worm-{}-{}",
                identity.secondary_scrub_run_id, identity.secondary_scrub_run_attempt
            )),
            json_string(&identity.secondary_scrub_sha256),
            json_string(&identity.secondary_scrub_selection_sha256),
        )
        .expect("writing to String cannot fail");
    } else {
        json.push_str("null");
    }
    json.push_str(",\n  \"blockers\": {");
    for (index, (name, count)) in blockers.iter().enumerate() {
        if index != 0 {
            json.push(',');
        }
        json.push_str("\n    ");
        push_json(&mut json, name);
        write!(json, ": {count}").expect("writing to String cannot fail");
    }
    json.push_str("\n  },\n  \"blockerCount\": ");
    write!(json, "{blocker_count}").expect("writing to String cannot fail");
    json.push_str(",\n  \"readyForExplicitGate\": ");
    json.push_str(if blocker_count == 0 { "true" } else { "false" });
    json.push_str(",\n  \"records\": {");
    let evidence_root = input.join("evidence");
    for (index, (name, path)) in records.iter().enumerate() {
        if index != 0 {
            json.push(',');
        }
        let digest = record_digest(path).map_err(|error| {
            format!(
                "proposal cannot bind missing or unreadable record {}: {error}",
                path.display()
            )
        })?;
        json.push_str("\n    ");
        push_json(&mut json, name);
        json.push_str(": {\"path\": ");
        let relative = path.strip_prefix(&evidence_root).map_err(|_| {
            format!(
                "proposal record {} is outside retained evidence",
                path.display()
            )
        })?;
        push_json(&mut json, &path_text(relative)?);
        json.push_str(", \"sha256\": ");
        push_json(&mut json, &digest);
        json.push('}');
    }
    json.push_str("\n  }\n}\n");
    write_atomic(output, json.as_bytes())?;
    write_digest_sibling(output, sha256_bytes(json.as_bytes()))?;
    Ok(format!(
        "wrote fail-closed promotion proposal {}",
        output.display()
    ))
}

fn promotion_record_paths(input: &Path) -> BTreeMap<&'static str, PathBuf> {
    BTreeMap::from([
        (
            "artifactAuthenticity",
            input.join("evidence").join("acquisition"),
        ),
        (
            "claimCoverage",
            input
                .join("evidence")
                .join("coverage")
                .join("claim-coverage.json"),
        ),
        (
            "custody",
            input
                .join("evidence")
                .join("custody")
                .join("custody-receipt.json"),
        ),
        (
            "divergence",
            input
                .join("evidence")
                .join("review")
                .join("divergence-report.json"),
        ),
        (
            "mutation",
            input
                .join("evidence")
                .join("coverage")
                .join("mutation-score.json"),
        ),
        (
            "normalizerAudit",
            input
                .join("evidence")
                .join("coverage")
                .join("normalizer-audit.json"),
        ),
        (
            "oracleProvenanceMacos",
            input
                .join("evidence")
                .join("provenance")
                .join("macos-arm64")
                .join("oracle-provenance.json"),
        ),
        (
            "oracleProvenanceWindows",
            input
                .join("evidence")
                .join("provenance")
                .join("windows-amd64")
                .join("oracle-provenance.json"),
        ),
        (
            "residualRisk",
            input
                .join("evidence")
                .join("coverage")
                .join("residual-risk.json"),
        ),
        (
            "reviewRoleGraph",
            input
                .join("evidence")
                .join("review")
                .join("role-graph.json"),
        ),
    ])
}

fn compatibility_report(root: &Path, options: &Options) -> Result<String, String> {
    let proposal = required_path(
        &options.proposal,
        "compatibility-report requires --proposal",
    )?;
    let output = required_path(&options.output, "compatibility-report requires --output")?;
    let retained = proposal
        .parent()
        .ok_or_else(|| "promotion proposal has no retained package root".to_owned())?;
    let proposal_bytes = read_regular_file(proposal)?;
    let proposal_digest = sha256_bytes(&proposal_bytes).hex();
    let proposal_json = parse_json(
        std::str::from_utf8(&proposal_bytes)
            .map_err(|_| "promotion proposal is not UTF-8".to_owned())?,
    )?;
    let proposal_object = proposal_json.object()?;
    let candidate = json_member(proposal_object, "candidateSourceCommit")?.string()?;
    let epoch = json_member(proposal_object, "assuranceEpochSha256")?.string()?;
    validate_promotion_dispatch(root, retained, proposal, candidate, epoch, &proposal_digest)?;
    let records = json_member(proposal_object, "records")?.object()?;
    let evidence_root = retained.join("evidence");
    let coverage = bound_details_from_proposal(root, records, "claimCoverage", &evidence_root)?;
    let divergence_details =
        bound_details_from_proposal(root, records, "divergence", &evidence_root)?;
    let residual = bound_details_from_proposal(root, records, "residualRisk", &evidence_root)?;
    let mutation_path = proposal_record_path(root, records, "mutation", &evidence_root)?;
    let mutation = parse_json(&read_text(&mutation_path)?)?;
    let mutation = mutation.object()?;
    let (exact, normalized, platform_dependent, divergence, out_of_scope) =
        compatibility_status_counts(&coverage)?;
    let residual = residual.object()?;
    let unverified = json_member(residual, "unverifiedClaimCells")?.number()?;
    let residual_out_of_scope = json_member(residual, "outOfScopeClaimCells")?.number()?;
    if residual_out_of_scope != out_of_scope {
        return Err("residual-risk and claim-coverage out-of-scope counts disagree".to_owned());
    }
    let verified = exact
        .saturating_add(normalized)
        .saturating_add(platform_dependent)
        .saturating_add(divergence);
    let total = verified
        .saturating_add(unverified)
        .saturating_add(out_of_scope);
    verify_public_release_scope(verified, total, unverified, out_of_scope)?;
    let toolchains = proposal_toolchain_digests(root, records, &evidence_root)?;
    let toolchain_refs = toolchains.iter().map(String::as_str).collect::<Vec<_>>();
    let runners = proposal_runner_identities(root, records, &evidence_root)?;
    let runner_refs = runners.iter().map(String::as_str).collect::<Vec<_>>();
    let divergence_values = compatibility_divergence_values(&divergence_details)?;
    let accepted_divergences = divergence_values
        .iter()
        .map(|(id, scope, expires_at)| hell_docgen::AcceptedDivergence {
            id,
            scope,
            expires_at,
        })
        .collect::<Vec<_>>();
    let mut issues = Vec::new();
    if unverified != 0 {
        issues.push("unverified-claim-cells");
    }
    if out_of_scope != 0 {
        issues.push("out-of-scope-claim-cells");
    }
    let report = hell_docgen::BoundedCompatibilityReport {
        baseline: hell_builtins::LANGUAGE_VERSION,
        candidate_commit: candidate,
        assurance_epoch_sha256: epoch,
        promotion_state: "approved-for-explicit-gate",
        profiles: &["upstream"],
        platforms: REQUIRED_CLAIM_PLATFORMS,
        toolchains: &toolchain_refs,
        runner_identities: &runner_refs,
        exact_cells: bounded_count(exact, "exact cells")?,
        normalized_cells: bounded_count(normalized, "normalized cells")?,
        platform_dependent_cells: bounded_count(platform_dependent, "platform cells")?,
        deliberate_divergence_cells: bounded_count(divergence, "divergence cells")?,
        unverified_cells: bounded_count(unverified, "unverified cells")?,
        out_of_scope_cells: bounded_count(out_of_scope, "out-of-scope cells")?,
        missing_obligations: bounded_count(
            json_member(coverage.object()?, "missingObligations")?.number()?,
            "missing obligations",
        )?,
        undetected_critical_mutants: bounded_count(
            json_member(mutation, "undetectedCriticalMutants")?.number()?,
            "undetected mutants",
        )?,
        residual_risk_tier: json_member(residual, "overallTier")?.string()?,
        custody_state: "verified-two-provider-retrieval",
        open_compatibility_issues: &issues,
        accepted_divergences: &accepted_divergences,
    };
    let text = hell_docgen::render_bounded_compatibility_report(&report)
        .map_err(|field| format!("bounded compatibility report rejects {field}"))?;
    write_atomic(output, text.as_bytes())?;
    Ok(format!(
        "wrote bounded compatibility report {}",
        output.display()
    ))
}

fn verify_public_release_scope(
    claimed_verified: u64,
    total: u64,
    unverified: u64,
    out_of_scope: u64,
) -> Result<(), String> {
    let partitioned_total = claimed_verified
        .checked_add(unverified)
        .and_then(|value| value.checked_add(out_of_scope));
    if crate::assurance_control_mutant_active("universal-release-claim")
        || (claimed_verified != 0 && partitioned_total == Some(total))
    {
        Ok(())
    } else {
        Err("public release claim does not match its retained bounded cell partition".to_owned())
    }
}

fn compatibility_status_counts(coverage: &JsonValue) -> Result<(u64, u64, u64, u64, u64), String> {
    let mut counts = [0_u64; 5];
    for cell in json_member(coverage.object()?, "cells")?.array()? {
        let index = match json_member(cell.object()?, "proposedStatus")?.string()? {
            "exact" => 0,
            "normalized" => 1,
            "platform-dependent" => 2,
            "deliberate-divergence" => 3,
            "not-applicable" => 4,
            status => {
                return Err(format!(
                    "bounded report encountered unknown status {status:?}"
                ));
            }
        };
        counts[index] = counts[index].saturating_add(1);
    }
    if coverage.object()?.get("coverageScope").is_some() {
        verify_scoped_collection_coverage_counts(coverage.object()?)?;
        counts[4] = json_member(coverage.object()?, "outOfScopeClaimCells")?.number()?;
    }
    Ok((counts[0], counts[1], counts[2], counts[3], counts[4]))
}

fn compatibility_divergence_values(
    details: &JsonValue,
) -> Result<Vec<(String, String, String)>, String> {
    json_member(details.object()?, "records")?
        .array()?
        .iter()
        .map(|record| {
            let record = record.object()?;
            Ok((
                json_member(record, "divergenceId")?.string()?.to_owned(),
                format!(
                    "{}/{}/{}/{}",
                    json_member(record, "builtin")?.string()?,
                    json_member(record, "dimension")?.string()?,
                    json_member(record, "profile")?.string()?,
                    json_member(record, "platform")?.string()?,
                ),
                json_member(record, "expiresAt")?.string()?.to_owned(),
            ))
        })
        .collect()
}

fn bounded_count(value: u64, label: &str) -> Result<usize, String> {
    usize::try_from(value).map_err(|_| format!("{label} exceeds usize"))
}

fn proposal_record_path(
    root: &Path,
    records: &BTreeMap<String, JsonValue>,
    name: &str,
    evidence_root: &Path,
) -> Result<PathBuf, String> {
    let record = json_member(records, name)?.object()?;
    confined_record_path(
        root,
        evidence_root,
        Path::new(json_member(record, "path")?.string()?),
    )
}

fn bound_details_from_proposal(
    root: &Path,
    records: &BTreeMap<String, JsonValue>,
    name: &str,
    evidence_root: &Path,
) -> Result<JsonValue, String> {
    let wrapper_path = proposal_record_path(root, records, name, evidence_root)?;
    let wrapper = parse_json(&read_text(&wrapper_path)?)?;
    let wrapper = wrapper.object()?;
    let details_path = confined_record_path(
        root,
        evidence_root,
        Path::new(json_member(wrapper, "detailsPath")?.string()?),
    )?;
    parse_json(&read_text(&details_path)?)
}

fn proposal_toolchain_digests(
    root: &Path,
    records: &BTreeMap<String, JsonValue>,
    evidence_root: &Path,
) -> Result<Vec<String>, String> {
    let mut toolchains = Vec::new();
    for name in ["oracleProvenanceMacos", "oracleProvenanceWindows"] {
        let record_path = proposal_record_path(root, records, name, evidence_root)?;
        let record = parse_json(&read_text(&record_path)?)?;
        let record = record.object()?;
        let plan_path = confined_record_path(
            root,
            record_path
                .parent()
                .ok_or_else(|| "oracle provenance record has no directory".to_owned())?,
            Path::new(json_member(record, "buildPlanPath")?.string()?),
        )?;
        let plan = parse_json(&read_text(&plan_path)?)?;
        let digest = json_member(plan.object()?, "toolchainSha256")?
            .string()?
            .to_owned();
        require_digest(&digest, "bounded report toolchain")?;
        toolchains.push(digest);
    }
    toolchains.sort();
    toolchains.dedup();
    Ok(toolchains)
}

fn proposal_runner_identities(
    root: &Path,
    records: &BTreeMap<String, JsonValue>,
    evidence_root: &Path,
) -> Result<Vec<String>, String> {
    let mut identities = Vec::new();
    for name in ["oracleProvenanceMacos", "oracleProvenanceWindows"] {
        let record_path = proposal_record_path(root, records, name, evidence_root)?;
        let record = parse_json(&read_text(&record_path)?)?;
        let record = record.object()?;
        for prefix in ["first", "second"] {
            let run = json_member(record, &format!("{prefix}RunIdentity"))?.string()?;
            let domain = json_member(record, &format!("{prefix}BuilderTrustDomain"))?.string()?;
            if run.is_empty() || domain.is_empty() {
                return Err("oracle runner identity is incomplete".to_owned());
            }
            identities.push(format!("{domain}/{run}"));
        }
    }
    identities.sort();
    identities.dedup();
    Ok(identities)
}

fn regression_import(root: &Path, options: &Options) -> Result<String, String> {
    match options.action.as_deref().unwrap_or("prepare") {
        "acquire-subject" => regression_acquire_subject(root, options, false),
        "acquire-historical-subject" => regression_acquire_subject(root, options, true),
        "assemble-generated-subject" => regression_assemble_generated_subject(root, options),
        "assemble-subject" => regression_assemble_subject(root, options),
        "dispatch-automatic" => regression_dispatch_automatic(options),
        "dispatch-automatic-batch" => regression_dispatch_automatic_batch(root, options),
        "dispatch-automatic-shard" => regression_dispatch_automatic_shard(root, options),
        "emit-directory-output" => regression_emit_directory_output(options),
        "emit-integration-output" => regression_emit_integration_output(options),
        "explore-generated" => regression_explore_generated(root, options),
        "integrate" => regression_integrate(root, options),
        "integrate-batch" => regression_integrate_batch(root, options),
        "integrate-current-main" => regression_integrate_current_main(root, options, false),
        "integrate-batch-current-main" => regression_integrate_current_main(root, options, true),
        "review-subject" => regression_review_subject(root, options),
        "resolve-automatic-source" => regression_resolve_automatic_source(root, options),
        "select-subject" => regression_select_subject(root, options),
        "prepare" => regression_prepare(root, options),
        "reconcile-automatic-batch" => regression_reconcile_automatic_batch(root, options),
        "verify" => regression_verify(root, options),
        "verify-committed" => regression_verify_committed(root),
        "verify-committed-structural" => regression_verify_committed_structural(root),
        "promote" => regression_promote(root, options),
        action => Err(format!("unknown regression-import action {action:?}")),
    }
}

fn regression_dispatch_automatic(options: &Options) -> Result<String, String> {
    let context_path = required_path(
        &options.input,
        "automatic regression dispatch requires --input provider context",
    )?;
    let context_text = read_text(context_path)?;
    let context = parse_json(&context_text)?;
    let context = context.object()?;
    regression_provider_context_value(context)?;
    let template = options
        .expected
        .as_deref()
        .ok_or_else(|| "automatic regression dispatch requires --expected template".to_owned())?;
    let generated = options
        .issue
        .as_deref()
        .filter(|value| hell_builtins::validate_case_id(value))
        .ok_or_else(|| {
            "automatic regression dispatch requires canonical --issue case".to_owned()
        })?;
    let run_id = json_member(context, "runId")?.number()?;
    let run_attempt = json_member(context, "runAttempt")?.number()?;
    if json_member(context, "artifactName")?.string()?
        != format!("regression-subject-{generated}-{run_id}-{run_attempt}")
    {
        return Err(
            "automatic subject artifact does not match dispatched generated case".to_owned(),
        );
    }
    let category = regression_category(options)?;
    let stable_issue = std::env::var("REGRESSION_AUTOMATION_ISSUE")
        .map_err(|_| "automatic regression dispatch requires stable issue".to_owned())?;
    if stable_issue.trim() != stable_issue || !stable_issue.starts_with("github-run:") {
        return Err("automatic regression issue is not a stable nightly run reference".to_owned());
    }
    regression_template_case(options)?;
    let token = std::env::var("GITHUB_TOKEN")
        .map_err(|_| "automatic regression dispatch requires GITHUB_TOKEN".to_owned())?;
    dispatch_automatic_regression(
        &context_text,
        template,
        generated,
        category,
        &stable_issue,
        &token,
    )?;
    Ok("dispatched exact automatic reviewed regression pipeline".to_owned())
}

fn dispatch_automatic_regression(
    context: &str,
    template: &str,
    generated: &str,
    category: &str,
    stable_issue: &str,
    token: &str,
) -> Result<(), String> {
    let fields =
        automatic_regression_dispatch_fields(context, template, generated, category, stable_issue)?;
    let mut command = Command::new("gh");
    command.args([
        "workflow",
        "run",
        ".github/workflows/regression-corpus.yml",
        "--ref",
        "main",
    ]);
    for field in &fields {
        command.args(["--field", field]);
    }
    let status = command
        .env("GH_TOKEN", token)
        .env_remove("GITHUB_TOKEN")
        .env_remove("AWS_ACCESS_KEY_ID")
        .env_remove("AWS_SECRET_ACCESS_KEY")
        .env_remove("AWS_SESSION_TOKEN")
        .status()
        .map_err(|error| format!("cannot dispatch automatic regression pipeline: {error}"))?;
    if !status.success() {
        return Err("automatic regression pipeline dispatch failed".to_owned());
    }
    Ok(())
}

fn automatic_regression_dispatch_fields(
    context: &str,
    template: &str,
    generated: &str,
    category: &str,
    stable_issue: &str,
) -> Result<[String; 9], String> {
    let batch_id = stable_issue
        .strip_prefix("github-run:")
        .and_then(|value| value.parse::<u64>().ok())
        .filter(|value| *value != 0)
        .ok_or_else(|| "automatic regression issue has no positive batch run ID".to_owned())?;
    Ok([
        "action=automatic".to_owned(),
        format!("template_case_id={template}"),
        format!("issue={stable_issue}"),
        format!("category={category}"),
        format!("subject_provider_context={context}"),
        "proposal_provider_context={}".to_owned(),
        "review_provider_context={}".to_owned(),
        format!("generated_case_id={generated}"),
        format!("batch_id={batch_id}"),
    ])
}

struct AutomaticRegressionDispatch {
    category: String,
    context: String,
    generated: String,
    template: String,
}

fn regression_dispatch_automatic_shard(root: &Path, options: &Options) -> Result<String, String> {
    let nightly = required_path(
        &options.program,
        "automatic shard dispatch requires --program nightly root",
    )?;
    let candidate = std::env::var("REGRESSION_AUTOMATION_CANDIDATE")
        .map_err(|_| "automatic shard dispatch requires candidate commit".to_owned())?;
    require_git_sha_text(&candidate, "automatic shard candidate")?;
    let run_id = required_positive_environment_u64("REGRESSION_AUTOMATION_RUN_ID")?;
    let shard = required_positive_environment_u64("REGRESSION_AUTOMATION_SHARD").or_else(|_| {
        std::env::var("REGRESSION_AUTOMATION_SHARD")
            .ok()
            .and_then(|value| value.parse::<u64>().ok())
            .filter(|value| *value < 4)
            .ok_or_else(|| "automatic shard index is not in 0..4".to_owned())
    })?;
    if shard >= 4 {
        return Err("automatic shard index is not in 0..4".to_owned());
    }
    let stable_issue = std::env::var("REGRESSION_AUTOMATION_ISSUE")
        .map_err(|_| "automatic shard dispatch requires stable issue".to_owned())?;
    let token = std::env::var("GITHUB_TOKEN")
        .map_err(|_| "automatic shard dispatch requires GITHUB_TOKEN".to_owned())?;
    let case_ids = scheduled_generated_mismatch_ids(nightly)?;
    let plans = scheduled_automatic_regression_plans(nightly, &case_ids)?;
    let mut dispatches = Vec::new();
    for plan in plans {
        let plan = plan.object()?;
        let generated = json_member(plan, "case_id")?.string()?;
        if automatic_generated_case_shard(generated)? != shard {
            continue;
        }
        dispatches.push(preflight_automatic_regression_dispatch(
            root, &candidate, run_id, nightly, plan,
        )?);
    }
    for dispatch in &dispatches {
        dispatch_automatic_regression(
            &dispatch.context,
            &dispatch.template,
            &dispatch.generated,
            &dispatch.category,
            &stable_issue,
            &token,
        )?;
    }
    Ok(format!(
        "dispatched {} exact trusted-current automatic regressions",
        dispatches.len()
    ))
}

const AUTOMATIC_REGRESSION_RECONCILIATION_ATTEMPTS: usize = 660;

fn regression_dispatch_automatic_batch(root: &Path, options: &Options) -> Result<String, String> {
    let nightly = required_path(
        &options.program,
        "automatic batch dispatch requires --program nightly root",
    )?;
    let ready_set_path = required_path(
        &options.input,
        "automatic batch dispatch requires --input exact ready set",
    )?;
    let transaction = required_path(
        &options.to,
        "automatic batch dispatch requires --to transaction directory",
    )?;
    let nightly_selection = PathBuf::from(options.artifact.as_deref().ok_or_else(|| {
        "automatic batch dispatch requires --artifact nightly selection".to_owned()
    })?);
    let ready_set = parse_json(&read_text(ready_set_path)?)?;
    let expected_cases = verify_automatic_regression_ready_set(&ready_set)?;
    let candidate = json_member(ready_set.object()?, "candidateCommit")?.string()?;
    let batch_id = json_member(ready_set.object()?, "nightlyRunId")?.number()?;
    verify_automatic_ready_set_nightly_authority(root, &ready_set, nightly, &nightly_selection)?;
    let run_id = required_positive_environment_u64("REGRESSION_AUTOMATION_RUN_ID")?;
    let case_ids = scheduled_generated_mismatch_ids(nightly)?;
    let plans = scheduled_automatic_regression_plans(nightly, &case_ids)?;
    let retained_plan_bytes = canonical_json_bytes(&JsonValue::Array(plans.clone()))?;
    if expected_cases.is_empty()
        || sha256_bytes(&retained_plan_bytes).hex()
            != json_member(ready_set.object()?, "plansSha256")?.string()?
    {
        return Err("automatic batch ready set differs from retained nightly authority".to_owned());
    }
    let stable_issue = std::env::var("REGRESSION_AUTOMATION_ISSUE")
        .map_err(|_| "automatic batch dispatch requires stable issue".to_owned())?;
    let token = std::env::var("GITHUB_TOKEN")
        .map_err(|_| "automatic batch dispatch requires GITHUB_TOKEN".to_owned())?;
    let mut dispatches = Vec::new();
    for plan in &plans {
        dispatches.push(preflight_automatic_regression_dispatch(
            root,
            candidate,
            run_id,
            nightly,
            plan.object()?,
        )?);
    }
    for dispatch in &dispatches {
        dispatch_automatic_regression(
            &dispatch.context,
            &dispatch.template,
            &dispatch.generated,
            &dispatch.category,
            &stable_issue,
            &token,
        )?;
    }
    for attempt in 0..AUTOMATIC_REGRESSION_RECONCILIATION_ATTEMPTS {
        match collect_automatic_regression_transaction(
            root,
            ready_set_path,
            transaction,
            &expected_cases,
            candidate,
            batch_id,
            Some((nightly, &nightly_selection)),
        ) {
            Ok(()) => {
                return regression_integrate_batch(
                    root,
                    &Options {
                        action: Some("integrate-batch".to_owned()),
                        input: Some(transaction.to_path_buf()),
                        output: options.output.clone(),
                        ..Options::default()
                    },
                );
            }
            Err(error) if error == "automatic reviewed regression set is pending" => {
                if attempt + 1 != AUTOMATIC_REGRESSION_RECONCILIATION_ATTEMPTS {
                    std::thread::sleep(Duration::from_secs(30));
                }
            }
            Err(error) => return Err(error),
        }
    }
    Err("automatic reviewed regression set remained incomplete after bounded retries".to_owned())
}

fn regression_reconcile_automatic_batch(root: &Path, options: &Options) -> Result<String, String> {
    let nightly = required_path(
        &options.program,
        "automatic batch reconciliation requires --program retained nightly root",
    )?;
    let nightly_selection = PathBuf::from(options.artifact.as_deref().ok_or_else(|| {
        "automatic batch reconciliation requires --artifact nightly selection".to_owned()
    })?);
    let ready_set_path = required_path(
        &options.input,
        "automatic batch reconciliation requires --input exact ready set",
    )?;
    let transaction = required_path(
        &options.to,
        "automatic batch reconciliation requires --to transaction directory",
    )?;
    let ready_set = parse_json(&read_text(ready_set_path)?)?;
    let expected_cases = verify_automatic_regression_ready_set(&ready_set)?;
    let candidate = json_member(ready_set.object()?, "candidateCommit")?.string()?;
    let batch_id = json_member(ready_set.object()?, "nightlyRunId")?.number()?;
    if expected_cases.is_empty() {
        return Err("automatic batch reconciliation cannot select an empty set".to_owned());
    }
    verify_automatic_ready_set_nightly_authority(root, &ready_set, nightly, &nightly_selection)?;
    for attempt in 0..AUTOMATIC_REGRESSION_RECONCILIATION_ATTEMPTS {
        match collect_automatic_regression_transaction(
            root,
            ready_set_path,
            transaction,
            &expected_cases,
            candidate,
            batch_id,
            Some((nightly, &nightly_selection)),
        ) {
            Ok(()) => {
                return Ok(format!(
                    "reconciled {} exact reviewed regressions into one offline transaction",
                    expected_cases.len()
                ));
            }
            Err(error) if error == "automatic reviewed regression set is pending" => {
                if attempt + 1 != AUTOMATIC_REGRESSION_RECONCILIATION_ATTEMPTS {
                    std::thread::sleep(Duration::from_secs(30));
                }
            }
            Err(error) => return Err(error),
        }
    }
    Err("automatic reviewed regression set remained incomplete after bounded retries".to_owned())
}

fn collect_automatic_regression_transaction(
    root: &Path,
    ready_set_path: &Path,
    output: &Path,
    expected_cases: &[String],
    candidate: &str,
    batch_id: u64,
    nightly_authority: Option<(&Path, &Path)>,
) -> Result<(), String> {
    if output.exists() {
        return Err("automatic batch transaction output already exists".to_owned());
    }
    let endpoint = Path::new("repos/Portfoligno/hell-rs/actions/artifacts?per_page=100");
    let artifacts = github_api_paginated_values(endpoint, "artifacts")?;
    let temporary = create_private_temp_directory("hell-regression-batch-collect")?;
    let result = collect_automatic_regression_transaction_to(
        root,
        &temporary,
        &AutomaticRegressionCollectionAuthority {
            ready_set_path,
            expected_cases,
            candidate,
            batch_id,
            nightly_authority,
        },
        &artifacts,
    );
    match result {
        Ok(()) => {
            copy_regression_tree(&temporary, output)?;
            fs::remove_dir_all(&temporary)
                .map_err(|error| format!("cannot clean automatic batch collection: {error}"))?;
            Ok(())
        }
        Err(error) => {
            fs::remove_dir_all(&temporary)
                .map_err(|cleanup| format!("{error}; cannot clean collection: {cleanup}"))?;
            Err(error)
        }
    }
}

struct AutomaticRegressionCollectionAuthority<'a> {
    ready_set_path: &'a Path,
    expected_cases: &'a [String],
    candidate: &'a str,
    batch_id: u64,
    nightly_authority: Option<(&'a Path, &'a Path)>,
}

fn collect_automatic_regression_transaction_to(
    root: &Path,
    output: &Path,
    authority: &AutomaticRegressionCollectionAuthority<'_>,
    artifacts: &[JsonValue],
) -> Result<(), String> {
    collect_automatic_regression_transaction_to_with(
        output,
        authority,
        artifacts,
        |selected, case_id, cases_root| {
            retain_automatic_reviewed_artifact(
                root,
                selected,
                authority.batch_id,
                case_id,
                authority.candidate,
                cases_root,
            )
        },
    )
}

fn collect_automatic_regression_transaction_to_with<F>(
    output: &Path,
    authority: &AutomaticRegressionCollectionAuthority<'_>,
    artifacts: &[JsonValue],
    mut retain: F,
) -> Result<(), String>
where
    F: FnMut(&JsonValue, &str, &Path) -> Result<(), String>,
{
    let ready_set = parse_json(&read_text(authority.ready_set_path)?)?;
    let ready_cases = verify_automatic_regression_ready_set(&ready_set)?;
    if ready_cases != authority.expected_cases
        || json_member(ready_set.object()?, "candidateCommit")?.string()? != authority.candidate
        || json_member(ready_set.object()?, "nightlyRunId")?.number()? != authority.batch_id
    {
        return Err("automatic collection authority differs from its exact ready set".to_owned());
    }
    copy_record_tree(
        authority.ready_set_path,
        &output.join("automatic-regression-ready-set.json"),
    )?;
    if let Some((nightly, selection)) = authority.nightly_authority {
        copy_regression_tree(nightly, &output.join("nightly"))?;
        copy_regression_tree(selection, &output.join("nightly-selection"))?;
    }
    let cases_root = output.join("cases");
    fs::create_dir(&cases_root)
        .map_err(|error| format!("cannot create automatic batch cases: {error}"))?;
    for case_id in authority.expected_cases {
        select_authoritative_automatic_reviewed_artifact(
            artifacts,
            authority.batch_id,
            case_id,
            |selected| {
                let result = retain(selected, case_id, &cases_root);
                if result.as_ref().err().map(String::as_str)
                    == Some("automatic reviewed regression differs from ready-set authority")
                {
                    let rejected = cases_root.join(case_id);
                    if rejected.exists() {
                        fs::remove_dir_all(&rejected).map_err(|cleanup| {
                            format!("cannot clean rejected automatic reviewed artifact: {cleanup}")
                        })?;
                    }
                }
                result
            },
        )?;
    }
    Ok(())
}

fn select_authoritative_automatic_reviewed_artifact<F>(
    artifacts: &[JsonValue],
    batch_id: u64,
    case_id: &str,
    mut verify: F,
) -> Result<(), String>
where
    F: FnMut(&JsonValue) -> Result<(), String>,
{
    let mut candidates = artifacts
        .iter()
        .filter_map(|artifact| {
            let object = artifact.object().ok()?;
            let name = json_member(object, "name").ok()?.string().ok()?;
            automatic_reviewed_artifact_name(name, batch_id, case_id).map(|_| artifact)
        })
        .collect::<Vec<_>>();
    candidates.sort_by_key(|artifact| {
        std::cmp::Reverse(
            artifact
                .object()
                .ok()
                .and_then(|object| json_member(object, "id").ok())
                .and_then(|value| value.number().ok())
                .unwrap_or(0),
        )
    });
    for candidate in candidates {
        match verify(candidate) {
            Ok(()) => return Ok(()),
            Err(error)
                if error == "automatic reviewed regression differs from ready-set authority" => {}
            Err(error) => return Err(error),
        }
    }
    Err("automatic reviewed regression set is pending".to_owned())
}

fn automatic_reviewed_artifact_name(
    name: &str,
    batch_id: u64,
    case_id: &str,
) -> Option<(u64, u64)> {
    let suffix = name.strip_prefix(&format!("reviewed-regression-{batch_id}-{case_id}-"))?;
    let (run, attempt) = suffix.split_once('-')?;
    let run = run.parse::<u64>().ok().filter(|value| *value != 0)?;
    let attempt = attempt.parse::<u64>().ok().filter(|value| *value != 0)?;
    Some((run, attempt))
}

fn retain_automatic_reviewed_artifact(
    root: &Path,
    artifact: &JsonValue,
    batch_id: u64,
    case_id: &str,
    candidate: &str,
    transaction_cases: &Path,
) -> Result<(), String> {
    let listing = artifact.object()?;
    let artifact_id = json_member(listing, "id")?.number()?;
    let run_id = json_member(json_member(listing, "workflow_run")?.object()?, "id")?.number()?;
    if artifact_id == 0 || run_id == 0 || json_member(listing, "expired")?.boolean()? {
        return Err("automatic reviewed regression artifact identity is invalid".to_owned());
    }
    let artifact = github_api_json(
        &PathBuf::from("repos/Portfoligno/hell-rs/actions/artifacts").join(artifact_id.to_string()),
    )?;
    let run = github_api_json(
        &PathBuf::from("repos/Portfoligno/hell-rs/actions/runs").join(run_id.to_string()),
    )?;
    let archive = github_api_bytes(
        &PathBuf::from("repos/Portfoligno/hell-rs/actions/artifacts")
            .join(artifact_id.to_string())
            .join("zip"),
    )?;
    retain_automatic_reviewed_artifact_from_provider(
        root,
        &AutomaticReviewedProviderArtifact {
            listing: artifact_listing_value(listing),
            artifact: &artifact,
            run: &run,
            archive: &archive,
        },
        batch_id,
        case_id,
        candidate,
        transaction_cases,
    )
}

fn artifact_listing_value(listing: &BTreeMap<String, JsonValue>) -> JsonValue {
    JsonValue::Object(listing.clone())
}

struct AutomaticReviewedProviderArtifact<'a> {
    listing: JsonValue,
    artifact: &'a JsonValue,
    run: &'a JsonValue,
    archive: &'a [u8],
}

fn retain_automatic_reviewed_artifact_from_provider(
    root: &Path,
    provider: &AutomaticReviewedProviderArtifact<'_>,
    batch_id: u64,
    case_id: &str,
    candidate: &str,
    transaction_cases: &Path,
) -> Result<(), String> {
    let listing = provider.listing.object()?;
    let artifact = provider.artifact.object()?;
    let run = provider.run.object()?;
    let artifact_id = json_member(artifact, "id")?.number()?;
    let artifact_name = json_member(artifact, "name")?.string()?;
    let run_id = json_member(run, "id")?.number()?;
    let run_attempt = json_member(run, "run_attempt")?.number()?;
    if json_member(listing, "id")?.number()? != artifact_id
        || json_member(listing, "name")?.string()? != artifact_name
        || json_member(json_member(listing, "workflow_run")?.object()?, "id")?.number()? != run_id
        || json_member(listing, "expired")?.boolean()?
        || artifact_name
            != format!("reviewed-regression-{batch_id}-{case_id}-{run_id}-{run_attempt}")
        || automatic_regression_run(
            provider.run,
            json_member(run, "head_sha")?.string()?,
            ".github/workflows/regression-corpus.yml",
            "workflow_dispatch",
        )?
        .is_none()
    {
        return Err("automatic reviewed regression artifact/run binding is invalid".to_owned());
    }
    let transaction_case = transaction_cases.join(case_id);
    let promotion = transaction_case.join("promotion");
    let selection = transaction_case.join("selection");
    fs::create_dir(&transaction_case)
        .map_err(|error| format!("cannot create automatic reviewed case: {error}"))?;
    let archive_path = transaction_case.join("provider-archive.zip");
    write_atomic(&archive_path, provider.archive)?;
    extract_external_zip(&archive_path, &promotion)?;
    let record = parse_json(&read_text(&promotion.join("promoted-regression.json"))?)?;
    if json_member(record.object()?, "caseId")?.string()? != case_id
        || json_member(record.object()?, "candidateCommit")?.string()? != candidate
    {
        return Err("automatic reviewed regression differs from ready-set authority".to_owned());
    }
    let repository_tree =
        confined_promotion_component(&promotion, record.object()?, "repositoryTreePath")?;
    let proposal = parse_json(&read_text(
        &repository_tree
            .join("compat")
            .join("regressions")
            .join(case_id)
            .join("package/proposal.json"),
    )?)?;
    if json_member(proposal.object()?, "issue")?.string()? != format!("github-run:{batch_id}") {
        return Err("automatic reviewed regression differs from ready-set authority".to_owned());
    }
    retain_automatic_provider_selection(
        root,
        &promotion,
        &selection,
        provider.artifact,
        provider.run,
        provider.archive,
        candidate,
    )
}

fn retain_automatic_provider_selection(
    root: &Path,
    promotion: &Path,
    selection_root: &Path,
    artifact: &JsonValue,
    run: &JsonValue,
    archive: &[u8],
    active_candidate: &str,
) -> Result<(), String> {
    let artifact_record = artifact.object()?;
    let run_record = run.object()?;
    let artifact_id = json_member(artifact_record, "id")?.number()?;
    let run_id = json_member(run_record, "id")?.number()?;
    let run_attempt = json_member(run_record, "run_attempt")?.number()?;
    let provider_head = json_member(run_record, "head_sha")?.string()?;
    let workflow = ".github/workflows/regression-corpus.yml";
    let workflow_bytes = git_output_bytes(root, &["show", &format!("{provider_head}:{workflow}")])?;
    let artifact_bytes = canonical_json_bytes(artifact)?;
    let run_bytes = canonical_json_bytes(run)?;
    let archive_sha256 = sha256_bytes(archive).hex();
    let declared_archive = json_member(artifact_record, "digest")?
        .string()?
        .strip_prefix("sha256:")
        .ok_or_else(|| "automatic reviewed artifact digest is not SHA-256".to_owned())?;
    if archive.is_empty()
        || declared_archive != archive_sha256
        || json_member(artifact_record, "size_in_bytes")?.number()? != archive.len() as u64
        || utc_timestamp_seconds(json_member(artifact_record, "expires_at")?.string()?)?
            <= current_utc_seconds()?
    {
        return Err("automatic reviewed provider archive identity is invalid".to_owned());
    }
    let repository_id = json_member(json_member(run_record, "repository")?.object()?, "id")?
        .number()?
        .to_string();
    let directory_sha256 = record_digest(promotion)?;
    let rendered = render_provider_selection(&ProviderSelection {
        artifact_name: json_member(artifact_record, "name")?.string()?,
        workflow_path: workflow,
        event_name: "workflow_dispatch",
        run_id,
        run_attempt,
        artifact_id,
        candidate: active_candidate,
        directory_sha256: &directory_sha256,
        workflow_sha256: &sha256_bytes(&workflow_bytes).hex(),
        repository_id: &repository_id,
        artifact_bytes: &artifact_bytes,
        run_bytes: &run_bytes,
        provider_archive_sha256: &archive_sha256,
        provider_archive_size: archive.len() as u64,
        created_at: json_member(artifact_record, "created_at")?.string()?,
        expires_at: json_member(artifact_record, "expires_at")?.string()?,
        archive_download_url: json_member(artifact_record, "archive_download_url")?.string()?,
    });
    retain_provider_selection_responses(selection_root, &artifact_bytes, &run_bytes)?;
    write_atomic(&selection_root.join("selection.json"), rendered.as_bytes())?;
    write_atomic(&selection_root.join("provider-archive.zip"), archive)?;
    write_atomic(
        &selection_root.join("provider-workflow.yml"),
        &workflow_bytes,
    )?;
    reverify_provider_selection_with_distinct_head(
        root,
        promotion,
        selection_root,
        active_candidate,
        provider_head,
        workflow,
    )?;
    require_regression_artifact_class(selection_root, "reviewed-regression-")
}

fn required_positive_environment_u64(name: &str) -> Result<u64, String> {
    std::env::var(name)
        .ok()
        .and_then(|value| value.parse::<u64>().ok())
        .filter(|value| *value != 0)
        .ok_or_else(|| format!("{name} is not a positive integer"))
}

fn automatic_generated_case_shard(case_id: &str) -> Result<u64, String> {
    case_id
        .rsplit_once('-')
        .and_then(|(_, value)| value.parse::<u64>().ok())
        .filter(|value| *value < 1_024)
        .map(|value| value % 4)
        .ok_or_else(|| "automatic generated case has no bounded shard index".to_owned())
}

fn preflight_automatic_regression_dispatch(
    root: &Path,
    candidate: &str,
    run_id: u64,
    nightly: &Path,
    plan: &BTreeMap<String, JsonValue>,
) -> Result<AutomaticRegressionDispatch, String> {
    let generated = json_member(plan, "case_id")?.string()?;
    let template = json_member(plan, "template_case_id")?.string()?;
    let category = json_member(plan, "category")?.string()?;
    let source = automatic_regression_source("subject", Some(generated))?;
    let run =
        resolve_automatic_regression_run(candidate, &source.workflow, &source.event, Some(run_id))?;
    let artifact = resolve_automatic_regression_artifact(&run, &source.artifact_prefix)?;
    let context =
        automatic_regression_provider_context(root, candidate, source, &run, &artifact, None)?;
    verify_automatic_dispatch_subject(
        root, candidate, nightly, generated, template, category, &artifact,
    )?;
    Ok(AutomaticRegressionDispatch {
        category: category.to_owned(),
        context: String::from_utf8(canonical_json_bytes(&context)?)
            .map_err(|_| "automatic provider context is not UTF-8".to_owned())?,
        generated: generated.to_owned(),
        template: template.to_owned(),
    })
}

fn verify_automatic_dispatch_subject(
    root: &Path,
    candidate: &str,
    nightly: &Path,
    generated: &str,
    template: &str,
    category: &str,
    artifact: &JsonValue,
) -> Result<(), String> {
    let artifact_id = json_member(artifact.object()?, "id")?.number()?;
    let archive = github_api_bytes(
        &PathBuf::from("repos/Portfoligno/hell-rs/actions/artifacts")
            .join(artifact_id.to_string())
            .join("zip"),
    )?;
    let temporary = create_private_temp_directory("hell-regression-auto-preflight")?;
    let archive_path = temporary.join("artifact.zip");
    let subject = temporary.join("subject");
    write_atomic(&archive_path, &archive)?;
    extract_external_zip(&archive_path, &subject)?;
    let result = verify_automatic_dispatch_subject_tree(
        root, candidate, nightly, generated, template, category, &subject,
    );
    fs::remove_dir_all(&temporary)
        .map_err(|error| format!("cannot clean automatic subject preflight: {error}"))?;
    result
}

fn verify_automatic_dispatch_subject_tree(
    root: &Path,
    candidate: &str,
    nightly: &Path,
    generated: &str,
    template: &str,
    category: &str,
    subject: &Path,
) -> Result<(), String> {
    verify_regression_subject_source_chain(root, subject, candidate, template, false)?;
    let mut source = parse_json(&read_text(&subject.join("generated-source.json"))?)?;
    let source_fields = source.object()?;
    let scheduled = json_member(source_fields, "scheduledExploration")?.object()?;
    let expected_source = verify_generated_regression_source_structural(
        nightly,
        generated,
        &nightly
            .join("mismatches/proposed-regressions")
            .join(generated),
    )?;
    if json_member(source_fields, "caseId")?.string()? != generated
        || json_member(source_fields, "templateCaseId")?.string()? != template
        || json_member(scheduled, "compatibilityCategory")?.string()? != category
        || json_member(scheduled, "automationDisposition")?.string()?
            != "ready-for-protected-regression-review"
    {
        return Err("automatic subject differs from trusted-current retained plan".to_owned());
    }
    source.object_mut()?.remove("scheduledExploration");
    source.object_mut()?.remove("templateCaseId");
    if canonical_json_bytes(&source)? != canonical_json_bytes(&expected_source)? {
        return Err("automatic subject source differs from trusted nightly bytes".to_owned());
    }
    Ok(())
}

fn regression_provider_context_value(document: &BTreeMap<String, JsonValue>) -> Result<(), String> {
    exact_keys(
        document,
        &[
            "artifactId",
            "artifactName",
            "directorySha256",
            "event",
            "headSha",
            "runAttempt",
            "runId",
            "workflowPath",
        ],
    )?;
    require_git_sha_text(
        json_member(document, "headSha")?.string()?,
        "automatic subject candidate",
    )?;
    require_digest(
        json_member(document, "directorySha256")?.string()?,
        "automatic subject directory",
    )?;
    for key in ["artifactId", "runAttempt", "runId"] {
        if json_member(document, key)?.number()? == 0 {
            return Err(format!("automatic subject {key} is not positive"));
        }
    }
    if json_member(document, "workflowPath")?.string()?
        != ".github/workflows/regression-subject.yml"
        || json_member(document, "event")?.string()? != "workflow_run"
        || !json_member(document, "artifactName")?
            .string()?
            .starts_with("regression-subject-generated-")
    {
        return Err("automatic subject provider class is invalid".to_owned());
    }
    Ok(())
}

struct AutomaticRegressionSource {
    artifact_prefix: String,
    event: String,
    workflow: String,
}

fn automatic_regression_source(
    role: &str,
    case_id: Option<&str>,
) -> Result<AutomaticRegressionSource, String> {
    match role {
        "nightly" => Ok(AutomaticRegressionSource {
            artifact_prefix: "nightly-".to_owned(),
            event: "schedule".to_owned(),
            workflow: ".github/workflows/nightly.yml".to_owned(),
        }),
        "evidence" => Ok(AutomaticRegressionSource {
            artifact_prefix: "promotion-review-ready-evidence".to_owned(),
            event: "workflow_dispatch".to_owned(),
            workflow: ".github/workflows/promotion-evidence-review.yml".to_owned(),
        }),
        "public" => Ok(AutomaticRegressionSource {
            artifact_prefix: "promotion-public-current-state-".to_owned(),
            event: "workflow_dispatch".to_owned(),
            workflow: ".github/workflows/promotion-surveillance.yml".to_owned(),
        }),
        "subject" => {
            let case_id = case_id
                .filter(|value| hell_builtins::validate_case_id(value))
                .ok_or_else(|| {
                    "automatic subject source requires canonical --issue case ID".to_owned()
                })?;
            Ok(AutomaticRegressionSource {
                artifact_prefix: format!("regression-subject-{case_id}-"),
                event: "workflow_run".to_owned(),
                workflow: ".github/workflows/regression-subject.yml".to_owned(),
            })
        }
        _ => Err("automatic regression source role is unknown".to_owned()),
    }
}

fn regression_resolve_automatic_source(root: &Path, options: &Options) -> Result<String, String> {
    let role = options
        .role
        .as_deref()
        .ok_or_else(|| "automatic regression source requires --role".to_owned())?;
    let output = required_path(
        &options.output,
        "automatic regression source requires --output context",
    )?;
    let candidate = std::env::var("REGRESSION_AUTOMATION_CANDIDATE")
        .map_err(|_| "automatic regression source requires candidate commit".to_owned())?;
    require_git_sha_text(&candidate, "automatic regression candidate")?;
    let source = automatic_regression_source(role, options.issue.as_deref())?;
    let exact_run = match std::env::var("REGRESSION_AUTOMATION_RUN_ID") {
        Ok(value) => Some(
            value
                .parse::<u64>()
                .ok()
                .filter(|value| *value != 0)
                .ok_or_else(|| "automatic regression run ID is not positive".to_owned())?,
        ),
        Err(_) => None,
    };
    if matches!(role, "nightly" | "subject") && exact_run.is_none() {
        return Err("automatic run-local source requires exact triggering run ID".to_owned());
    }
    let selected =
        resolve_automatic_regression_run(&candidate, &source.workflow, &source.event, exact_run)?;
    let artifact = resolve_automatic_regression_artifact(&selected, &source.artifact_prefix)?;
    let ready_set_output =
        (role == "nightly").then(|| output.with_file_name("automatic-regression-ready-set.json"));
    let context = automatic_regression_provider_context(
        root,
        &candidate,
        source,
        &selected,
        &artifact,
        ready_set_output.as_deref(),
    )?;
    write_atomic(output, &canonical_json_bytes(&context)?)?;
    emit_automatic_regression_outputs(role, &context)?;
    Ok(format!("resolved exact automatic regression {role} source"))
}

struct AutomaticRegressionRun {
    id: u64,
    attempt: u64,
}

fn resolve_automatic_regression_run(
    candidate: &str,
    workflow: &str,
    event: &str,
    exact_run: Option<u64>,
) -> Result<AutomaticRegressionRun, String> {
    let response = if let Some(run) = exact_run {
        vec![github_api_json(
            &PathBuf::from("repos/Portfoligno/hell-rs/actions/runs").join(run.to_string()),
        )?]
    } else {
        let file = Path::new(workflow)
            .file_name()
            .ok_or_else(|| "automatic regression workflow has no filename".to_owned())?;
        let endpoint = PathBuf::from("repos/Portfoligno/hell-rs/actions/workflows")
            .join(file)
            .join("runs?branch=main&status=success&per_page=100");
        github_api_paginated_values(&endpoint, "workflow_runs")?
    };
    let mut matches = response
        .iter()
        .filter_map(|value| automatic_regression_run(value, candidate, workflow, event).transpose())
        .collect::<Result<Vec<_>, _>>()?;
    matches.sort_by_key(|run| (run.id, run.attempt));
    matches
        .pop()
        .ok_or_else(|| "no exact successful automatic regression source run exists".to_owned())
}

fn automatic_regression_run(
    value: &JsonValue,
    candidate: &str,
    workflow: &str,
    event: &str,
) -> Result<Option<AutomaticRegressionRun>, String> {
    let run = value.object()?;
    let conclusion = json_member(run, "conclusion")?.string()?;
    let accepted_conclusion = conclusion == "success"
        || (workflow == ".github/workflows/nightly.yml" && conclusion == "failure");
    let matches = json_member(run, "head_sha")?.string()? == candidate
        && json_member(run, "event")?.string()? == event
        && json_member(run, "status")?.string()? == "completed"
        && accepted_conclusion
        && provider_run_workflow_ref(json_member(run, "path")?.string()?, workflow)?
            == "refs/heads/main";
    if !matches {
        return Ok(None);
    }
    let id = json_member(run, "id")?.number()?;
    let attempt = json_member(run, "run_attempt")?.number()?;
    if id == 0 || attempt == 0 {
        return Err("automatic regression source identifiers are not positive".to_owned());
    }
    Ok(Some(AutomaticRegressionRun { id, attempt }))
}

fn resolve_automatic_regression_artifact(
    run: &AutomaticRegressionRun,
    prefix: &str,
) -> Result<JsonValue, String> {
    let endpoint = PathBuf::from("repos/Portfoligno/hell-rs/actions/runs")
        .join(run.id.to_string())
        .join("artifacts?per_page=100");
    let artifacts = github_api_paginated_values(&endpoint, "artifacts")?;
    let response = JsonValue::Object(BTreeMap::from([
        ("artifacts".to_owned(), JsonValue::Array(artifacts.clone())),
        (
            "total_count".to_owned(),
            JsonValue::Number(u64::try_from(artifacts.len()).map_err(|_| {
                "automatic artifact count exceeds canonical integer range".to_owned()
            })?),
        ),
    ]));
    select_automatic_regression_artifact(&response, run, prefix)
}

fn github_api_paginated_values(endpoint: &Path, member: &str) -> Result<Vec<JsonValue>, String> {
    const PAGE_SIZE: usize = 100;
    const MAX_PAGES: usize = 64;
    let base = endpoint
        .to_str()
        .ok_or_else(|| "GitHub API endpoint is not UTF-8".to_owned())?;
    let mut pages = Vec::new();
    for page in 1..=MAX_PAGES {
        let response = github_api_json(Path::new(&format!("{base}&page={page}")))?;
        let count = json_member(response.object()?, member)?.array()?.len();
        pages.push(response);
        if count < PAGE_SIZE {
            return validate_github_api_pages(&pages, member);
        }
    }
    Err("GitHub API pagination exceeds the bounded complete-set limit".to_owned())
}

fn validate_github_api_pages(pages: &[JsonValue], member: &str) -> Result<Vec<JsonValue>, String> {
    let mut retained = Vec::new();
    let mut retained_ids = BTreeSet::new();
    let mut prior_id = None;
    let mut expected_total = None;
    for response in pages {
        let object = response.object()?;
        let total = json_member(object, "total_count")?.number()?;
        if expected_total
            .replace(total)
            .is_some_and(|value| value != total)
        {
            return Err("GitHub API pagination total changed during acquisition".to_owned());
        }
        for value in json_member(object, member)?.array()? {
            let id = json_member(value.object()?, "id")?.number()?;
            if id == 0 || !retained_ids.insert(id) || prior_id.is_some_and(|prior| id >= prior) {
                return Err(
                    "GitHub API pagination identifiers are not unique positive descending values"
                        .to_owned(),
                );
            }
            prior_id = Some(id);
            retained.push(value.clone());
        }
    }
    if expected_total.and_then(|total| usize::try_from(total).ok()) != Some(retained.len()) {
        return Err("GitHub API pagination did not retain the exact complete set".to_owned());
    }
    Ok(retained)
}

fn select_automatic_regression_artifact(
    response: &JsonValue,
    run: &AutomaticRegressionRun,
    prefix: &str,
) -> Result<JsonValue, String> {
    let expected_name = if prefix.ends_with('-') {
        format!("{prefix}{}-{}", run.id, run.attempt)
    } else {
        prefix.to_owned()
    };
    let mut matches = json_member(response.object()?, "artifacts")?
        .array()?
        .iter()
        .filter(|value| {
            let Ok(artifact) = value.object() else {
                return false;
            };
            let Ok(name) = json_member(artifact, "name").and_then(JsonValue::string) else {
                return false;
            };
            name == expected_name
        })
        .cloned()
        .collect::<Vec<_>>();
    if matches.len() != 1 {
        return Err("automatic regression source artifact selection is ambiguous".to_owned());
    }
    Ok(matches.remove(0))
}

fn automatic_regression_provider_context(
    root: &Path,
    candidate: &str,
    source: AutomaticRegressionSource,
    run: &AutomaticRegressionRun,
    artifact: &JsonValue,
    ready_set_output: Option<&Path>,
) -> Result<JsonValue, String> {
    let artifact = artifact.object()?;
    let artifact_id = json_member(artifact, "id")?.number()?;
    let artifact_name = json_member(artifact, "name")?.string()?;
    if artifact_id == 0
        || json_member(artifact, "expired")?.boolean()?
        || json_member(json_member(artifact, "workflow_run")?.object()?, "id")?.number()? != run.id
    {
        return Err("automatic regression source artifact is invalid".to_owned());
    }
    let endpoint = PathBuf::from("repos/Portfoligno/hell-rs/actions/artifacts")
        .join(artifact_id.to_string())
        .join("zip");
    let archive = github_api_bytes(&endpoint)?;
    let temporary = create_private_temp_directory("hell-regression-auto-source")?;
    let archive_path = temporary.join("artifact.zip");
    let extracted = temporary.join("extracted");
    write_atomic(&archive_path, &archive)?;
    extract_external_zip(&archive_path, &extracted)?;
    let directory_sha256 = record_digest(&extracted)?;
    if source.workflow == ".github/workflows/nightly.yml" {
        let case_ids = scheduled_generated_mismatch_ids(&extracted)?;
        let plans = scheduled_automatic_regression_plans(&extracted, &case_ids)?;
        emit_automatic_regression_plans(&plans)?;
        let output = ready_set_output.ok_or_else(|| {
            "automatic nightly source omitted its exact ready-set output".to_owned()
        })?;
        write_automatic_regression_ready_set(output, candidate, run, &plans)?;
    } else if ready_set_output.is_some() {
        return Err("non-nightly automatic source cannot emit a ready set".to_owned());
    }
    fs::remove_dir_all(&temporary)
        .map_err(|error| format!("cannot clean automatic regression source: {error}"))?;
    let historical_workflow =
        git_output_bytes(root, &["show", &format!("{candidate}:{}", source.workflow)])?;
    if historical_workflow.is_empty() || read_regular_file(&root.join(&source.workflow))?.is_empty()
    {
        return Err("automatic regression source workflow is unavailable".to_owned());
    }
    Ok(JsonValue::Object(BTreeMap::from([
        ("artifactId".to_owned(), JsonValue::Number(artifact_id)),
        (
            "artifactName".to_owned(),
            JsonValue::String(artifact_name.to_owned()),
        ),
        (
            "directorySha256".to_owned(),
            JsonValue::String(directory_sha256),
        ),
        ("event".to_owned(), JsonValue::String(source.event)),
        (
            "headSha".to_owned(),
            JsonValue::String(candidate.to_owned()),
        ),
        ("runAttempt".to_owned(), JsonValue::Number(run.attempt)),
        ("runId".to_owned(), JsonValue::Number(run.id)),
        (
            "workflowPath".to_owned(),
            JsonValue::String(source.workflow),
        ),
    ])))
}

fn write_automatic_regression_ready_set(
    output: &Path,
    candidate: &str,
    run: &AutomaticRegressionRun,
    plans: &[JsonValue],
) -> Result<(), String> {
    let plans_value = JsonValue::Array(plans.to_vec());
    let plans_bytes = canonical_json_bytes(&plans_value)?;
    let ready_set = JsonValue::Object(BTreeMap::from([
        (
            "candidateCommit".to_owned(),
            JsonValue::String(candidate.to_owned()),
        ),
        (
            "nightlyRunAttempt".to_owned(),
            JsonValue::Number(run.attempt),
        ),
        ("nightlyRunId".to_owned(), JsonValue::Number(run.id)),
        (
            "planCount".to_owned(),
            JsonValue::Number(
                u64::try_from(plans.len())
                    .map_err(|_| "automatic ready set exceeds canonical count".to_owned())?,
            ),
        ),
        (
            "plansSha256".to_owned(),
            JsonValue::String(sha256_bytes(&plans_bytes).hex()),
        ),
        ("plans".to_owned(), plans_value),
        ("schemaVersion".to_owned(), JsonValue::Number(1)),
        (
            "state".to_owned(),
            JsonValue::String("complete-reviewed-regression-ready-set".to_owned()),
        ),
    ]));
    verify_automatic_regression_ready_set(&ready_set)?;
    write_atomic(output, &canonical_json_bytes(&ready_set)?)
}

fn verify_automatic_regression_ready_set(ready_set: &JsonValue) -> Result<Vec<String>, String> {
    let ready_set = ready_set.object()?;
    exact_keys(
        ready_set,
        &[
            "candidateCommit",
            "nightlyRunAttempt",
            "nightlyRunId",
            "planCount",
            "plans",
            "plansSha256",
            "schemaVersion",
            "state",
        ],
    )?;
    require_git_sha_text(
        json_member(ready_set, "candidateCommit")?.string()?,
        "automatic ready-set candidate",
    )?;
    require_digest(
        json_member(ready_set, "plansSha256")?.string()?,
        "automatic ready-set plan digest",
    )?;
    let plans = json_member(ready_set, "plans")?.array()?;
    if json_member(ready_set, "schemaVersion")?.number()? != 1
        || json_member(ready_set, "state")?.string()? != "complete-reviewed-regression-ready-set"
        || json_member(ready_set, "nightlyRunId")?.number()? == 0
        || json_member(ready_set, "nightlyRunAttempt")?.number()? == 0
        || json_member(ready_set, "planCount")?.number()?
            != u64::try_from(plans.len())
                .map_err(|_| "automatic ready-set plan count overflows".to_owned())?
        || json_member(ready_set, "plansSha256")?.string()?
            != sha256_bytes(&canonical_json_bytes(&JsonValue::Array(plans.to_vec()))?).hex()
    {
        return Err("automatic regression ready-set authority is inconsistent".to_owned());
    }
    let mut prior = None;
    let mut case_ids = Vec::new();
    for plan in plans {
        let plan = plan.object()?;
        exact_keys(plan, &["case_id", "category", "template_case_id"])?;
        let case_id = json_member(plan, "case_id")?.string()?;
        if !hell_builtins::validate_case_id(case_id)
            || prior.is_some_and(|prior: &str| prior >= case_id)
            || !matches!(
                json_member(plan, "category")?.string()?,
                "semantic-mismatch"
                    | "presentation-mismatch"
                    | "platform-mismatch"
                    | "resource-mismatch"
            )
            || !hell_builtins::validate_case_id(json_member(plan, "template_case_id")?.string()?)
        {
            return Err("automatic regression ready-set plan is invalid or unsorted".to_owned());
        }
        prior = Some(case_id);
        case_ids.push(case_id.to_owned());
    }
    Ok(case_ids)
}

fn verify_automatic_ready_set_nightly_authority(
    root: &Path,
    ready_set: &JsonValue,
    nightly: &Path,
    selection: &Path,
) -> Result<(), String> {
    let ready = ready_set.object()?;
    let candidate = json_member(ready, "candidateCommit")?.string()?;
    let retained_run = parse_json(&read_text(&selection.join("provider-selected-run.json"))?)?;
    let provider_head = json_member(retained_run.object()?, "head_sha")?.string()?;
    reverify_provider_selection_with_distinct_head(
        root,
        nightly,
        selection,
        candidate,
        provider_head,
        ".github/workflows/nightly.yml",
    )?;
    let retained_selection = parse_json(&read_text(&selection.join("selection.json"))?)?;
    let retained_selection = retained_selection.object()?;
    verify_automatic_ready_set_provider_record(ready, retained_selection)?;
    let case_ids = scheduled_generated_mismatch_ids(nightly)?;
    let plans = scheduled_automatic_regression_plans(nightly, &case_ids)?;
    let plan_bytes = canonical_json_bytes(&JsonValue::Array(plans))?;
    if sha256_bytes(&plan_bytes).hex() != json_member(ready, "plansSha256")?.string()? {
        return Err("automatic ready set differs from retained nightly plans".to_owned());
    }
    Ok(())
}

fn verify_automatic_ready_set_provider_record(
    ready: &BTreeMap<String, JsonValue>,
    selection: &BTreeMap<String, JsonValue>,
) -> Result<(), String> {
    let run_id = json_member(ready, "nightlyRunId")?.number()?;
    let run_attempt = json_member(ready, "nightlyRunAttempt")?.number()?;
    if json_member(selection, "candidateCommit")?.string()?
        != json_member(ready, "candidateCommit")?.string()?
        || json_member(selection, "artifact")?.string()?
            != format!("nightly-{run_id}-{run_attempt}")
        || json_member(selection, "providerRunId")?.number()? != run_id
        || json_member(selection, "providerRunAttempt")?.number()? != run_attempt
        || json_member(selection, "event")?.string()? != "schedule"
    {
        return Err("automatic ready set differs from exact nightly provider run".to_owned());
    }
    Ok(())
}

fn scheduled_automatic_regression_plans(
    nightly: &Path,
    case_ids: &[String],
) -> Result<Vec<JsonValue>, String> {
    let mut plans = Vec::new();
    for case_id in case_ids {
        let source_root = nightly
            .join("mismatches")
            .join("proposed-regressions")
            .join(case_id);
        let source = verify_generated_regression_source_structural(nightly, case_id, &source_root)?;
        let scheduled = verify_scheduled_generated_exploration(nightly, case_id, &source)?;
        let scheduled = scheduled.object()?;
        if json_member(scheduled, "automationDisposition")?.string()?
            == "ready-for-protected-regression-review"
        {
            plans.push(JsonValue::Object(BTreeMap::from([
                ("case_id".to_owned(), JsonValue::String(case_id.to_owned())),
                (
                    "category".to_owned(),
                    json_member(scheduled, "compatibilityCategory")?.clone(),
                ),
                (
                    "template_case_id".to_owned(),
                    json_member(scheduled, "templateCaseId")?.clone(),
                ),
            ])));
        }
    }
    Ok(plans)
}

fn emit_automatic_regression_plans(plans: &[JsonValue]) -> Result<(), String> {
    let mut shards = [Vec::new(), Vec::new(), Vec::new(), Vec::new()];
    for plan in plans {
        let case_id = json_member(plan.object()?, "case_id")?.string()?;
        let index = case_id
            .rsplit_once('-')
            .and_then(|(_, value)| value.parse::<usize>().ok())
            .filter(|value| *value < 1_024)
            .ok_or_else(|| "automatic generated case has no bounded index".to_owned())?;
        shards[index % shards.len()].push(plan.clone());
    }
    for (index, shard) in shards.into_iter().enumerate() {
        if shard.len() > 256 {
            return Err("automatic generated case shard exceeds workflow matrix bound".to_owned());
        }
        let value = JsonValue::Array(shard);
        let rendered = String::from_utf8(canonical_json_bytes(&value)?)
            .map_err(|_| "automatic generated case inventory is not UTF-8".to_owned())?;
        emit_github_output(&format!("generated_case_matrix_{index}"), &rendered)?;
    }
    Ok(())
}

fn emit_automatic_regression_outputs(role: &str, context: &JsonValue) -> Result<(), String> {
    let key = format!("{role}_provider_context");
    let rendered = String::from_utf8(canonical_json_bytes(context)?)
        .map_err(|_| "automatic regression context is not UTF-8".to_owned())?;
    emit_github_output(&key, &rendered)
}

fn emit_github_output(key: &str, value: &str) -> Result<(), String> {
    let Some(path) = std::env::var_os("GITHUB_OUTPUT") else {
        return Ok(());
    };
    validate_provider_atom(key, "GitHub output key")?;
    if value.contains(['\n', '\r']) {
        return Err("GitHub output value is not single-line canonical data".to_owned());
    }
    let mut file = fs::OpenOptions::new()
        .append(true)
        .open(path)
        .map_err(|error| format!("cannot open GITHUB_OUTPUT: {error}"))?;
    writeln!(file, "{key}={value}")
        .and_then(|()| file.sync_all())
        .map_err(|error| format!("cannot retain automatic regression output: {error}"))
}

fn regression_verify_committed(root: &Path) -> Result<String, String> {
    verify_committed_regression_catalog(root, true)
}

fn regression_verify_committed_structural(root: &Path) -> Result<String, String> {
    verify_committed_regression_catalog(root, false)
}

fn verify_committed_regression_catalog(
    root: &Path,
    execute_subject: bool,
) -> Result<String, String> {
    let catalog = read_text(&root.join("compat").join("regression-corpus.tsv"))?;
    let mut lines = catalog.lines();
    if lines.next() != Some("schema_version\t2")
        || lines.next()
            != Some(
                "columns\tcase_id\ttemplate_case_id\tsource_hex\tsource_sha256\tcandidate_commit\tassurance_epoch_sha256\tpackage_sha256\tproposal_sha256\treview_sha256\tbundle_sha256\ttargets_hex\tproof_path\tproof_manifest_sha256",
            )
    {
        return Err("committed regression catalog header is invalid".to_owned());
    }
    let mut verified_count = 0_usize;
    for line in lines.filter(|line| !line.is_empty()) {
        verify_committed_regression_row(root, root, line, execute_subject)?;
        verified_count = verified_count.saturating_add(1);
    }
    Ok(format!(
        "cryptographically reverified {verified_count} committed regression proofs"
    ))
}

fn verify_committed_regression_row(
    root: &Path,
    proof_repository: &Path,
    line: &str,
    execute_subject: bool,
) -> Result<(), String> {
    let fields = line.split('\t').collect::<Vec<_>>();
    let [
        case_id,
        _template_case_id,
        _source_hex,
        _source_sha256,
        _candidate_commit,
        _assurance_epoch,
        _package_sha256,
        _proposal_sha256,
        review_sha256,
        _bundle_sha256,
        _targets_hex,
        proof_path,
        proof_sha256,
    ] = fields.as_slice()
    else {
        return Err("committed regression catalog row is incomplete".to_owned());
    };
    let expected_path = format!("compat/regressions/{case_id}/proof.tsv");
    if *proof_path != expected_path {
        return Err("committed regression proof path is not canonical".to_owned());
    }
    let proof = proof_repository.join(proof_path);
    if record_digest(&proof)? != *proof_sha256 {
        return Err("committed regression proof manifest digest differs".to_owned());
    }
    let proof_root = proof
        .parent()
        .ok_or_else(|| "committed regression proof has no directory".to_owned())?;
    let package = proof_root.join("package");
    let verified = if execute_subject {
        verify_regression_package(root, &package)?
    } else {
        verify_regression_package_structure(root, &package, false)?.verified
    };
    verify_regression_catalog_row_identity(&verified, &fields)?;
    let review_root = proof_root.join("review");
    let review = review_root.join("review.dsse.json");
    if record_digest(&review)? != *review_sha256 {
        return Err("committed regression review digest differs from the catalog row".to_owned());
    }
    let review_subject = review_root.join("review-subject.json");
    let proposal_selection = proof_root.join("proposal-selection");
    let review_selection = proof_root.join("review-selection");
    require_regression_artifact_class(&review_selection, "regression-review-")?;
    reverify_regression_provider_selection(
        root,
        &review_root,
        &review_selection,
        &verified.candidate_commit,
        ".github/workflows/regression-corpus.yml",
    )?;
    verify_regression_review_subject(
        root,
        &package,
        &review_subject,
        &proposal_selection,
        &verified,
    )?;
    verify_historical_review_binding(
        &review,
        &review_root.join("reviewer.allowed_signers"),
        &root.join("compat").join("review-revocations.toml"),
        "regression-reviewer",
        &verified.candidate_commit,
        &verified.assurance_epoch,
        &BTreeSet::from([record_digest(&review_subject)?]),
    )?;
    Ok(())
}

fn verify_regression_catalog_row_identity(
    verified: &VerifiedRegressionProposal,
    fields: &[&str],
) -> Result<(), String> {
    if fields.len() != 13
        || verified.case_id != fields[0]
        || verified.template_case_id != fields[1]
        || hex_text(&verified.source) != fields[2]
        || verified.source_sha256 != fields[3]
        || verified.candidate_commit != fields[4]
        || verified.assurance_epoch != fields[5]
        || verified.package_sha256 != fields[6]
        || verified.proposal_sha256 != fields[7]
        || verified.bundle_sha256 != fields[9]
        || hex_text(&verified.targets_descriptor) != fields[10]
    {
        return Err("committed regression package differs from the catalog row".to_owned());
    }
    Ok(())
}

fn regression_integrate(root: &Path, options: &Options) -> Result<String, String> {
    let input = required_path(
        &options.input,
        "regression-import integrate requires --input reviewed promotion artifact",
    )?;
    let selection = PathBuf::from(options.artifact.as_deref().ok_or_else(|| {
        "regression-import integrate requires --artifact provider selection".to_owned()
    })?);
    let delta = verify_regression_integration_delta(root, input, &selection)?;
    let current_updated = regression_apply_catalog_delta(root, &delta.case_id, &delta.row)?;
    install_regression_delta(root, &delta)?;
    write_atomic(
        &root.join("compat").join("regression-corpus.tsv"),
        current_updated.as_bytes(),
    )?;
    verify_committed_regression_row(root, root, delta.row.trim_end(), false)?;
    Ok(format!(
        "integrated reviewed regression {} into the controlled repository tree",
        delta.case_id
    ))
}

struct VerifiedRegressionDelta {
    case_id: String,
    candidate: String,
    epoch: String,
    historical_base_sha256: String,
    issue: String,
    row: String,
    proof_source: PathBuf,
}

fn verify_regression_integration_delta(
    root: &Path,
    input: &Path,
    selection: &Path,
) -> Result<VerifiedRegressionDelta, String> {
    let record_path = input.join("promoted-regression.json");
    let record = parse_json(&read_text(&record_path)?)?;
    let record = record.object()?;
    exact_keys(
        record,
        &[
            "assuranceEpochSha256",
            "bundleSha256",
            "candidateCommit",
            "caseId",
            "claimEligible",
            "corpusEntryPath",
            "corpusEntrySha256",
            "packageSha256",
            "proofManifestSha256",
            "proposalSha256",
            "repositoryTreePath",
            "repositoryTreeSha256",
            "reviewSha256",
            "schemaVersion",
            "sourceSha256",
            "state",
            "updatedCorpusPath",
            "updatedCorpusSha256",
        ],
    )?;
    if json_member(record, "schemaVersion")?.number()? != 1
        || json_member(record, "claimEligible")?.boolean()?
        || json_member(record, "state")?.string()?
            != "reviewed-awaiting-controlled-repository-integration"
    {
        return Err("reviewed regression integration record is not fail-closed".to_owned());
    }
    require_regression_artifact_class(selection, "reviewed-regression-")?;
    let retained_run = parse_json(&read_text(&selection.join("provider-selected-run.json"))?)?;
    let provider_head = json_member(retained_run.object()?, "head_sha")?.string()?;
    reverify_provider_selection_with_distinct_head(
        root,
        input,
        selection,
        json_member(record, "candidateCommit")?.string()?,
        provider_head,
        ".github/workflows/regression-corpus.yml",
    )?;
    let tree = confined_promotion_component(input, record, "repositoryTreePath")?;
    let updated = confined_promotion_component(input, record, "updatedCorpusPath")?;
    if record_digest(&tree)? != json_member(record, "repositoryTreeSha256")?.string()?
        || record_digest(&updated)? != json_member(record, "updatedCorpusSha256")?.string()?
    {
        return Err(
            "reviewed regression integration bytes differ from promotion record".to_owned(),
        );
    }
    let entry = confined_promotion_component(input, record, "corpusEntryPath")?;
    let added = read_text(&entry)?;
    if added.lines().count() != 1 || added.is_empty() || !added.ends_with('\n') {
        return Err("reviewed regression delta is not exactly one canonical row".to_owned());
    }
    let historical_updated = read_text(&updated)?;
    let historical_base = historical_updated.strip_suffix(&added).ok_or_else(|| {
        "reviewed regression historical catalog does not bind its row delta".to_owned()
    })?;
    if historical_base.is_empty() {
        return Err(
            "reviewed regression historical catalog does not bind its row delta".to_owned(),
        );
    }
    verify_regression_integration_record(input, record, &added)?;
    verify_committed_regression_row(root, &tree, added.trim_end(), false)?;
    let case_id = json_member(record, "caseId")?.string()?;
    let proof_source = tree.join("compat").join("regressions").join(case_id);
    let proposal = parse_json(&read_text(&proof_source.join("package/proposal.json"))?)?;
    let issue = json_member(proposal.object()?, "issue")?
        .string()?
        .to_owned();
    Ok(VerifiedRegressionDelta {
        case_id: case_id.to_owned(),
        candidate: json_member(record, "candidateCommit")?.string()?.to_owned(),
        epoch: json_member(record, "assuranceEpochSha256")?
            .string()?
            .to_owned(),
        historical_base_sha256: sha256_bytes(historical_base.as_bytes()).hex(),
        issue,
        row: added,
        proof_source,
    })
}

fn install_regression_delta(root: &Path, delta: &VerifiedRegressionDelta) -> Result<(), String> {
    let proof_destination = root.join("compat").join("regressions").join(&delta.case_id);
    copy_regression_tree(&delta.proof_source, &proof_destination)
}

fn regression_apply_catalog_delta(
    root: &Path,
    case_id: &str,
    canonical_row: &str,
) -> Result<String, String> {
    if canonical_row.lines().count() != 1
        || canonical_row.is_empty()
        || !canonical_row.ends_with('\n')
        || canonical_row.split('\t').count() != 13
        || canonical_row.split('\t').next() != Some(case_id)
    {
        return Err("reviewed regression row delta is not canonical".to_owned());
    }
    regression_updated_catalog(root, case_id, canonical_row)
}

fn regression_integrate_batch(root: &Path, options: &Options) -> Result<String, String> {
    let input = required_path(
        &options.input,
        "regression-import integrate-batch requires --input transaction directory",
    )?;
    let ready_set_path = input.join("automatic-regression-ready-set.json");
    let ready_set = parse_json(&read_text(&ready_set_path)?)?;
    let expected_cases = verify_automatic_regression_ready_set(&ready_set)?;
    if expected_cases.is_empty() {
        return Err("automatic regression batch cannot integrate an empty ready set".to_owned());
    }
    verify_automatic_ready_set_nightly_authority(
        root,
        &ready_set,
        &input.join("nightly"),
        &input.join("nightly-selection"),
    )?;
    let expected_candidate = json_member(ready_set.object()?, "candidateCommit")?.string()?;
    let expected_issue = format!(
        "github-run:{}",
        json_member(ready_set.object()?, "nightlyRunId")?.number()?
    );
    let cases_root = input.join("cases");
    let actual_cases = strict_directory_names(&cases_root)?;
    if actual_cases != expected_cases.iter().cloned().collect::<BTreeSet<_>>() {
        return Err("automatic regression batch is missing or adds a reviewed case".to_owned());
    }
    let mut deltas = Vec::new();
    for case_id in &expected_cases {
        let case_directory = cases_root.join(case_id);
        let delta = verify_regression_integration_delta(
            root,
            &case_directory.join("promotion"),
            &case_directory.join("selection"),
        )?;
        if delta.case_id != *case_id
            || delta.candidate != expected_candidate
            || delta.issue != expected_issue
        {
            return Err(
                "automatic regression batch case/candidate/issue authority differs".to_owned(),
            );
        }
        deltas.push(delta);
    }
    verify_regression_delta_transaction(&deltas)?;
    let mut updated = read_text(&root.join("compat").join("regression-corpus.tsv"))?;
    for delta in &deltas {
        updated = regression_updated_catalog_text(updated, &delta.case_id, &delta.row)?;
    }
    for delta in &deltas {
        install_regression_delta(root, delta)?;
    }
    write_atomic(
        &root.join("compat").join("regression-corpus.tsv"),
        updated.as_bytes(),
    )?;
    for delta in &deltas {
        verify_committed_regression_row(root, root, delta.row.trim_end(), false)?;
    }
    let result = automatic_regression_batch_result(&ready_set_path, &deltas)?;
    if let Some(output) = options.output.as_deref() {
        write_atomic(output, &canonical_json_bytes(&result)?)?;
    }
    Ok(format!(
        "atomically prepared {} exact reviewed regression deltas for one controlled commit",
        deltas.len()
    ))
}

fn regression_integrate_current_main(
    root: &Path,
    options: &Options,
    batch: bool,
) -> Result<String, String> {
    let input = required_path(
        &options.input,
        "current-main regression integration requires --input",
    )?;
    let input = fs::canonicalize(input)
        .map_err(|error| format!("cannot resolve current-main regression input: {error}"))?;
    let artifact =
        if batch {
            None
        } else {
            let selection = options.artifact.as_deref().ok_or_else(|| {
                "current-main regression integration requires --artifact".to_owned()
            })?;
            Some(fs::canonicalize(selection).map_err(|error| {
                format!("cannot resolve current-main provider selection: {error}")
            })?)
        };
    let output = options.output.as_deref().map(|path| {
        if path.is_absolute() {
            path.to_path_buf()
        } else {
            root.join(path)
        }
    });
    retry_current_main_regression_transaction(root, |attempt_root| {
        let attempt_options = Options {
            input: Some(input.clone()),
            output: output.clone(),
            artifact: artifact
                .as_ref()
                .map(|path| path.to_string_lossy().into_owned()),
            ..Options::default()
        };
        prepare_current_main_regression_commit(attempt_root, &attempt_options, batch)
    })?;
    Ok(if batch {
        "integrated one complete reviewed regression batch against exact current main".to_owned()
    } else {
        "integrated one reviewed regression against exact current main".to_owned()
    })
}

fn prepare_current_main_regression_commit(
    root: &Path,
    options: &Options,
    batch: bool,
) -> Result<(), String> {
    if batch {
        regression_integrate_batch(root, options)?;
    } else {
        regression_integrate(root, options)?;
    }
    crate::catalog_lock::write_repository_locks(root)?;
    crate::catalog_lock::verify_repository_locks(root)?;
    verify_regression_transaction_paths(root)?;
    git_output(
        root,
        &[
            "add",
            "--",
            "compat/regression-corpus.tsv",
            "compat/regressions",
            "compat/locks/catalog-digests.json",
            "compat/locks/assurance-epoch.json",
        ],
    )?;
    git_output(root, &["diff", "--cached", "--check"])?;
    let message = if batch {
        "Integrate complete reviewed scheduled regression batch"
    } else {
        "Integrate reviewed regression corpus proof"
    };
    git_output(
        root,
        &[
            "-c",
            "user.name=github-actions[bot]",
            "-c",
            "user.email=41898282+github-actions[bot]@users.noreply.github.com",
            "commit",
            "--no-gpg-sign",
            "-m",
            message,
        ],
    )?;
    Ok(())
}

fn verify_regression_transaction_paths(root: &Path) -> Result<(), String> {
    let status = git_output(root, &["status", "--porcelain=v1", "--untracked-files=all"])?;
    let allowed = [
        "compat/regression-corpus.tsv",
        "compat/regressions/",
        "compat/locks/catalog-digests.json",
        "compat/locks/assurance-epoch.json",
    ];
    for line in status.lines() {
        let path = line
            .get(3..)
            .ok_or_else(|| "current-main regression status is malformed".to_owned())?;
        if !allowed
            .iter()
            .any(|allowed| path == *allowed || path.starts_with(allowed))
        {
            return Err(format!(
                "current-main regression transaction changed an unauthorized path {path:?}"
            ));
        }
    }
    (!status.is_empty()).then_some(()).ok_or_else(|| {
        "current-main regression transaction produced no repository delta".to_owned()
    })
}

fn retry_current_main_regression_transaction(
    root: &Path,
    prepare: impl FnMut(&Path) -> Result<(), String>,
) -> Result<(), String> {
    retry_current_main_regression_transaction_with(root, 32, prepare, |attempt| {
        let exponential = 1_u64 << u32::from(attempt.min(4));
        let jitter = (u64::from(attempt) * 37) % 251;
        std::thread::sleep(Duration::from_millis(exponential * 100 + jitter));
    })
}

fn retry_current_main_regression_transaction_with(
    root: &Path,
    maximum_attempts: u8,
    mut prepare: impl FnMut(&Path) -> Result<(), String>,
    mut wait_after_race: impl FnMut(u8),
) -> Result<(), String> {
    if maximum_attempts == 0 {
        return Err("current-main regression retry budget is empty".to_owned());
    }
    let temporary = create_private_temp_directory("hell-current-main-regression")?;
    let mut last_push_error = String::new();
    for attempt in 1..=maximum_attempts {
        git_output(
            root,
            &[
                "fetch",
                "--no-tags",
                "origin",
                "refs/heads/main:refs/remotes/origin/main",
            ],
        )?;
        verify_current_main_retry_authority(root, "refs/remotes/origin/main")?;
        let worktree = temporary.join(format!("attempt-{attempt}"));
        let worktree_text = path_text(&worktree)?;
        git_output(
            root,
            &[
                "worktree",
                "add",
                "--detach",
                &worktree_text,
                "refs/remotes/origin/main",
            ],
        )?;
        let prepared = prepare(&worktree);
        if let Err(error) = prepared {
            remove_regression_worktree(root, &worktree_text);
            let _ = fs::remove_dir_all(&temporary);
            return Err(error);
        }
        let push = Command::new("git")
            .args(["push", "origin", "HEAD:refs/heads/main"])
            .current_dir(&worktree)
            .output();
        remove_regression_worktree(root, &worktree_text);
        let push = match push {
            Ok(push) => push,
            Err(error) => {
                let _ = fs::remove_dir_all(&temporary);
                return Err(format!(
                    "cannot push current-main regression transaction: {error}"
                ));
            }
        };
        if push.status.success() {
            let _ = fs::remove_dir_all(&temporary);
            return Ok(());
        }
        last_push_error = String::from_utf8_lossy(&push.stderr).into_owned();
        if attempt != maximum_attempts {
            wait_after_race(attempt);
        }
    }
    let _ = fs::remove_dir_all(&temporary);
    Err(format!(
        "current-main regression transaction lost {maximum_attempts} consecutive ref-update races; the retained reviewed transaction remains retryable: {last_push_error}"
    ))
}

fn verify_current_main_retry_authority(root: &Path, current: &str) -> Result<(), String> {
    let trusted = git_output(root, &["rev-parse", "HEAD"])?;
    let trusted = trusted.trim();
    let ancestor = Command::new("git")
        .args(["merge-base", "--is-ancestor", trusted, current])
        .current_dir(root)
        .status()
        .map_err(|error| format!("cannot verify current-main ancestry: {error}"))?;
    if !ancestor.success() {
        return Err(
            "current main no longer descends from the trusted integration authority; the retained reviewed transaction must be rerun"
                .to_owned(),
        );
    }
    let changed = git_output(
        root,
        &[
            "diff",
            "--name-only",
            "--no-renames",
            trusted,
            current,
            "--",
        ],
    )?;
    for path in changed.lines() {
        if path != "compat/regression-corpus.tsv"
            && path != "compat/locks/catalog-digests.json"
            && path != "compat/locks/assurance-epoch.json"
            && !path.starts_with("compat/regressions/")
        {
            return Err(format!(
                "trusted current-main integration authority changed at {path:?}; the retained reviewed transaction must be rerun by a fresh protected job"
            ));
        }
    }
    Ok(())
}

fn remove_regression_worktree(root: &Path, worktree: &str) {
    let _ = Command::new("git")
        .args(["worktree", "remove", "--force", worktree])
        .current_dir(root)
        .status();
}

fn strict_directory_names(directory: &Path) -> Result<BTreeSet<String>, String> {
    let mut names = BTreeSet::new();
    for entry in fs::read_dir(directory)
        .map_err(|error| format!("cannot enumerate automatic regression batch: {error}"))?
    {
        let entry = entry.map_err(|error| format!("cannot read automatic batch entry: {error}"))?;
        let name = entry
            .file_name()
            .into_string()
            .map_err(|_| "automatic batch case path is not UTF-8".to_owned())?;
        if !entry
            .file_type()
            .map_err(|error| format!("cannot inspect automatic batch case: {error}"))?
            .is_dir()
            || !hell_builtins::validate_case_id(&name)
            || !names.insert(name)
        {
            return Err("automatic regression batch case inventory is invalid".to_owned());
        }
    }
    Ok(names)
}

fn verify_regression_delta_transaction(deltas: &[VerifiedRegressionDelta]) -> Result<(), String> {
    let Some(first) = deltas.first() else {
        return Err("automatic regression transaction is empty".to_owned());
    };
    let mut cases = BTreeSet::new();
    let mut proof_paths = BTreeSet::new();
    for delta in deltas {
        if delta.candidate != first.candidate
            || delta.epoch != first.epoch
            || delta.historical_base_sha256 != first.historical_base_sha256
            || delta.issue != first.issue
            || !cases.insert(delta.case_id.as_str())
            || !proof_paths.insert(delta.proof_source.clone())
        {
            return Err(
                "automatic regression deltas do not share one unique historical transaction"
                    .to_owned(),
            );
        }
    }
    Ok(())
}

fn automatic_regression_batch_result(
    ready_set_path: &Path,
    deltas: &[VerifiedRegressionDelta],
) -> Result<JsonValue, String> {
    let cases = deltas
        .iter()
        .map(|delta| {
            JsonValue::Object(BTreeMap::from([
                (
                    "caseId".to_owned(),
                    JsonValue::String(delta.case_id.clone()),
                ),
                (
                    "rowSha256".to_owned(),
                    JsonValue::String(sha256_bytes(delta.row.as_bytes()).hex()),
                ),
                (
                    "state".to_owned(),
                    JsonValue::String("integrated-in-complete-batch".to_owned()),
                ),
            ]))
        })
        .collect::<Vec<_>>();
    Ok(JsonValue::Object(BTreeMap::from([
        (
            "caseCount".to_owned(),
            JsonValue::Number(
                u64::try_from(cases.len())
                    .map_err(|_| "automatic batch result count overflows".to_owned())?,
            ),
        ),
        ("cases".to_owned(), JsonValue::Array(cases)),
        (
            "readySetSha256".to_owned(),
            JsonValue::String(record_digest(ready_set_path)?),
        ),
        ("schemaVersion".to_owned(), JsonValue::Number(1)),
        (
            "state".to_owned(),
            JsonValue::String("complete-set-integrated".to_owned()),
        ),
    ])))
}

fn verify_regression_integration_record(
    input: &Path,
    record: &BTreeMap<String, JsonValue>,
    added_row: &str,
) -> Result<(), String> {
    let fields = added_row.trim_end().split('\t').collect::<Vec<_>>();
    if fields.len() != 13
        || json_member(record, "caseId")?.string()? != fields[0]
        || json_member(record, "sourceSha256")?.string()? != fields[3]
        || json_member(record, "candidateCommit")?.string()? != fields[4]
        || json_member(record, "assuranceEpochSha256")?.string()? != fields[5]
        || json_member(record, "packageSha256")?.string()? != fields[6]
        || json_member(record, "proposalSha256")?.string()? != fields[7]
        || json_member(record, "reviewSha256")?.string()? != fields[8]
        || json_member(record, "bundleSha256")?.string()? != fields[9]
        || json_member(record, "proofManifestSha256")?.string()? != fields[12]
    {
        return Err(
            "reviewed regression promotion record differs from added corpus row".to_owned(),
        );
    }
    let entry = confined_promotion_component(input, record, "corpusEntryPath")?;
    if record_digest(&entry)? != json_member(record, "corpusEntrySha256")?.string()?
        || read_text(&entry)? != added_row
    {
        return Err("reviewed regression corpus entry differs from added row".to_owned());
    }
    Ok(())
}

fn confined_promotion_component(
    input: &Path,
    record: &BTreeMap<String, JsonValue>,
    key: &str,
) -> Result<PathBuf, String> {
    let value = json_member(record, key)?.string()?;
    if value.is_empty() || Path::new(value).components().count() != 1 {
        return Err(format!(
            "reviewed regression {key} is not a canonical artifact component"
        ));
    }
    Ok(input.join(value))
}

fn regression_explore_generated(root: &Path, options: &Options) -> Result<String, String> {
    let nightly = required_path(
        &options.input,
        "generated regression exploration requires --input nightly root",
    )?;
    let output = required_path(
        &options.output,
        "generated regression exploration requires --output",
    )?;
    if output.exists() {
        return Err("generated regression exploration output already exists".to_owned());
    }
    crate::suite::verify_retained_native_summary(nightly)
        .map_err(|error| format!("scheduled nightly summary is invalid: {error}"))?;
    let case_ids = scheduled_generated_mismatch_ids(nightly)?;
    verify_scheduled_generated_inventory(nightly, &case_ids)?;
    fs::create_dir(output)
        .map_err(|error| format!("cannot create regression exploration output: {error}"))?;
    for case_id in &case_ids {
        explore_one_generated_regression(root, nightly, output, case_id)?;
    }
    let manifest = JsonValue::Object(BTreeMap::from([
        (
            "caseIds".to_owned(),
            JsonValue::Array(case_ids.iter().cloned().map(JsonValue::String).collect()),
        ),
        ("schemaVersion".to_owned(), JsonValue::Number(1)),
        (
            "state".to_owned(),
            JsonValue::String(if case_ids.is_empty() {
                "no-generated-mismatches".to_owned()
            } else {
                "minimized-unreviewed-nonclaim".to_owned()
            }),
        ),
    ]));
    write_atomic(
        &output.join("manifest.json"),
        &canonical_json_bytes(&manifest)?,
    )?;
    Ok(format!(
        "retained {} minimized unreviewed scheduled regressions",
        case_ids.len()
    ))
}

fn scheduled_generated_mismatch_ids(nightly: &Path) -> Result<Vec<String>, String> {
    let mismatches = nightly.join("mismatches");
    let mut retained = BTreeSet::new();
    if mismatches.exists() {
        for entry in fs::read_dir(&mismatches)
            .map_err(|error| format!("cannot enumerate nightly mismatches: {error}"))?
        {
            let entry =
                entry.map_err(|error| format!("cannot read nightly mismatch entry: {error}"))?;
            let name = entry
                .file_name()
                .into_string()
                .map_err(|_| "nightly mismatch path is not UTF-8".to_owned())?;
            if name.starts_with("generated-") {
                if !entry
                    .file_type()
                    .map_err(|error| format!("cannot inspect nightly mismatch entry: {error}"))?
                    .is_dir()
                    || !hell_builtins::validate_case_id(&name)
                {
                    return Err("generated nightly mismatch entry is not canonical".to_owned());
                }
                retained.insert(name);
            }
        }
    }
    let proposals = mismatches.join("proposed-regressions");
    let mut records = BTreeSet::new();
    let mut subjects = BTreeSet::new();
    if proposals.exists() {
        for entry in fs::read_dir(&proposals)
            .map_err(|error| format!("cannot enumerate generated regression proposals: {error}"))?
        {
            let entry = entry
                .map_err(|error| format!("cannot read generated regression proposal: {error}"))?;
            let path = entry.path();
            let file_type = entry.file_type().map_err(|error| {
                format!("cannot inspect generated regression proposal: {error}")
            })?;
            if file_type.is_dir() {
                let name = entry
                    .file_name()
                    .into_string()
                    .map_err(|_| "generated regression subject path is not UTF-8".to_owned())?;
                if !hell_builtins::validate_case_id(&name) || !name.starts_with("generated-") {
                    return Err("generated regression subject path is not canonical".to_owned());
                }
                subjects.insert(name);
            } else if file_type.is_file() && path.extension().is_some_and(|value| value == "json") {
                let name = path
                    .file_stem()
                    .and_then(std::ffi::OsStr::to_str)
                    .ok_or_else(|| "generated regression proposal path is not UTF-8".to_owned())?;
                if !hell_builtins::validate_case_id(name) || !name.starts_with("generated-") {
                    return Err("generated regression proposal path is not canonical".to_owned());
                }
                records.insert(name.to_owned());
            } else {
                return Err("generated regression proposal directory has an extra entry".to_owned());
            }
        }
    }
    if retained != records || retained != subjects {
        return Err(
            "generated mismatch bundles, proposal records, and subjects differ as exact sets"
                .to_owned(),
        );
    }
    Ok(retained.into_iter().collect())
}

fn verify_scheduled_generated_inventory(nightly: &Path, case_ids: &[String]) -> Result<(), String> {
    let path = nightly.join("generated-regression-inventory.json");
    let text = read_text(&path)?;
    let digest = sha256_bytes(text.as_bytes()).hex();
    if read_text(&nightly.join("generated-regression-inventory.sha256"))?
        != format!("{digest}  generated-regression-inventory.json\n")
    {
        return Err("scheduled generated inventory digest record is invalid".to_owned());
    }
    let inventory = parse_json(&text)?;
    let inventory = inventory.object()?;
    exact_keys(
        inventory,
        &[
            "caseIds",
            "corpusSeed",
            "generatedObservationCount",
            "generatedStressCorpusSha256",
            "schemaVersion",
        ],
    )?;
    let retained = json_member(inventory, "caseIds")?
        .array()?
        .iter()
        .map(JsonValue::string)
        .collect::<Result<Vec<_>, _>>()?;
    let summary = parse_json(&read_text(&nightly.join("summary.json"))?)?;
    let summary = summary.object()?;
    if json_member(inventory, "schemaVersion")?.number()? != 1
        || retained != case_ids.iter().map(String::as_str).collect::<Vec<_>>()
        || json_member(inventory, "corpusSeed")?.number()?
            != json_member(summary, "corpusSeed")?.number()?
        || json_member(inventory, "generatedObservationCount")?.number()?
            != json_member(summary, "generatedDifferentialObservations")?.number()?
        || json_member(inventory, "generatedStressCorpusSha256")?.string()?
            != json_member(summary, "generatedStressCorpusSha256")?.string()?
    {
        return Err("scheduled generated inventory differs from strict nightly summary".to_owned());
    }
    Ok(())
}

fn explore_one_generated_regression(
    root: &Path,
    nightly: &Path,
    output: &Path,
    case_id: &str,
) -> Result<(), String> {
    let source_root = nightly
        .join("mismatches")
        .join("proposed-regressions")
        .join(case_id);
    let source = read_text(&source_root.join("program.hell"))?;
    let generated = verify_generated_regression_source(nightly, case_id, &source_root)?;
    let mut case = DifferentialCase {
        id: std::sync::Arc::from(case_id),
        source: std::sync::Arc::from(source.as_str()),
        timeout: std::time::Duration::from_secs(5),
        ..DifferentialCase::default()
    };
    let (_, current_epoch) = epoch(root)?;
    let mut oracle = verify_executable(
        &source_root.join("oracle"),
        ExecutableRole::Oracle,
        None,
        hell_builtins::LANGUAGE_VERSION,
    )
    .map_err(|error| format!("cannot verify generated exploration oracle: {error}"))?;
    let mut candidate = verify_executable(
        &source_root.join("candidate"),
        ExecutableRole::Candidate,
        None,
        hell_builtins::LANGUAGE_VERSION,
    )
    .map_err(|error| format!("cannot verify generated exploration candidate: {error}"))?;
    oracle.assurance_epoch_sha256 = Some(current_epoch);
    candidate.assurance_epoch_sha256 = Some(current_epoch);
    let minimized = minimize_regression(&oracle, &candidate, &case)?;
    case.source = minimized.source.clone().into();
    let retained = output.join(case_id);
    fs::create_dir(&retained)
        .map_err(|error| format!("cannot create generated regression package: {error}"))?;
    write_atomic(&retained.join("original.hell"), source.as_bytes())?;
    write_atomic(
        &retained.join("minimized.hell"),
        minimized.source.as_bytes(),
    )?;
    let trials = retained.join("trials");
    fs::create_dir(&trials)
        .map_err(|error| format!("cannot create scheduled minimization trials: {error}"))?;
    for (index, (_, _, _, trial)) in minimized.attempts.iter().enumerate() {
        write_atomic(&trials.join(format!("{index:03}.hell")), trial.as_bytes())?;
    }
    let trace = regression_minimization_trace(&source, &minimized);
    write_atomic(&retained.join("minimization-trace.json"), trace.as_bytes())?;
    copy_regression_executable(&source_root.join("oracle"), &retained.join("oracle"))?;
    copy_regression_executable(&source_root.join("candidate"), &retained.join("candidate"))?;
    let bundle = retain_observation_bundle(&retained.join("evidence"), &case, &minimized.report)
        .map_err(|error| format!("cannot retain minimized generated mismatch: {error}"))?;
    let automation = retain_generated_regression_localization(
        &retained, case_id, &oracle, &candidate, &minimized,
    )?;
    let record =
        scheduled_exploration_record(&bundle, &case, generated, &minimized, &trace, &automation)?;
    write_atomic(
        &retained.join("exploration.json"),
        &canonical_json_bytes(&record)?,
    )
}

fn scheduled_exploration_record(
    bundle: &Path,
    case: &DifferentialCase,
    generated: JsonValue,
    minimized: &RegressionMinimization,
    trace: &str,
    automation: &GeneratedRegressionAutomationPlan,
) -> Result<JsonValue, String> {
    let classification = hell_testkit::classify_retained_observation_bundle(bundle, case)
        .map_err(|error| format!("cannot replay minimized generated mismatch: {error}"))?;
    let hell_testkit::RetainedObservationClassification::Mismatch {
        fingerprint_sha256, ..
    } = classification
    else {
        return Err("scheduled minimized regression no longer reproduces its mismatch".to_owned());
    };
    let oracle_sha256 = retained_observation_executable_sha256(bundle, "oracle")?;
    let candidate_sha256 = retained_observation_executable_sha256(bundle, "candidate")?;
    let record = JsonValue::Object(BTreeMap::from([
        (
            "automationDisposition".to_owned(),
            JsonValue::String(automation.disposition.to_owned()),
        ),
        (
            "bundleSha256".to_owned(),
            JsonValue::String(record_digest(bundle)?),
        ),
        (
            "candidateExecutableSha256".to_owned(),
            JsonValue::String(candidate_sha256.hex()),
        ),
        ("claimEligible".to_owned(), JsonValue::Bool(false)),
        (
            "compatibilityCategory".to_owned(),
            automation
                .category
                .map_or(JsonValue::Null, |value| JsonValue::String(value.to_owned())),
        ),
        (
            "executionInputSha256".to_owned(),
            JsonValue::String(record_digest(&bundle.join("execution-input.json"))?),
        ),
        (
            "fingerprintSha256".to_owned(),
            JsonValue::String(fingerprint_sha256.hex()),
        ),
        ("generatedSource".to_owned(), generated),
        (
            "localizationBundleSha256".to_owned(),
            automation
                .localization_bundle_sha256
                .as_ref()
                .map_or(JsonValue::Null, |value| JsonValue::String(value.clone())),
        ),
        (
            "localizationCandidateTypedSha256".to_owned(),
            automation
                .candidate_typed_sha256
                .as_ref()
                .map_or(JsonValue::Null, |value| JsonValue::String(value.clone())),
        ),
        (
            "localizationOracleExpectedTypedSha256".to_owned(),
            automation
                .oracle_expected_typed_sha256
                .as_ref()
                .map_or(JsonValue::Null, |value| JsonValue::String(value.clone())),
        ),
        (
            "minimizedSourceSha256".to_owned(),
            JsonValue::String(sha256_bytes(minimized.source.as_bytes()).hex()),
        ),
        (
            "oracleExecutableSha256".to_owned(),
            JsonValue::String(oracle_sha256.hex()),
        ),
        ("reviewed".to_owned(), JsonValue::Bool(false)),
        ("schemaVersion".to_owned(), JsonValue::Number(1)),
        (
            "templateCaseId".to_owned(),
            automation
                .template_case_id
                .map_or(JsonValue::Null, |value| JsonValue::String(value.to_owned())),
        ),
        (
            "traceSha256".to_owned(),
            JsonValue::String(sha256_bytes(trace.as_bytes()).hex()),
        ),
    ]));
    Ok(record)
}

fn regression_emit_directory_output(options: &Options) -> Result<String, String> {
    let input = required_path(
        &options.input,
        "regression directory output requires --input directory",
    )?;
    let output = std::env::var_os("GITHUB_OUTPUT")
        .ok_or_else(|| "regression directory output requires GITHUB_OUTPUT".to_owned())?;
    let digest = record_digest(input)?;
    let mut file = fs::OpenOptions::new()
        .append(true)
        .open(&output)
        .map_err(|error| format!("cannot open GITHUB_OUTPUT: {error}"))?;
    writeln!(file, "directory_sha256={digest}")
        .and_then(|()| file.sync_all())
        .map_err(|error| format!("cannot retain regression directory output: {error}"))?;
    Ok("retained exact regression directory output".to_owned())
}

fn regression_emit_integration_output(options: &Options) -> Result<String, String> {
    let input = required_path(
        &options.input,
        "regression integration output requires --input promotion record",
    )?;
    let record = parse_json(&read_text(input)?)?;
    let record = record.object()?;
    let candidate = json_member(record, "candidateCommit")?.string()?;
    let epoch = json_member(record, "assuranceEpochSha256")?.string()?;
    require_git_sha_text(candidate, "regression integration candidate")?;
    require_digest(epoch, "regression integration epoch")?;
    let output = std::env::var_os("GITHUB_OUTPUT")
        .ok_or_else(|| "regression integration output requires GITHUB_OUTPUT".to_owned())?;
    let mut file = fs::OpenOptions::new()
        .append(true)
        .open(&output)
        .map_err(|error| format!("cannot open GITHUB_OUTPUT: {error}"))?;
    writeln!(
        file,
        "candidate_sha={candidate}\nassurance_epoch_sha256={epoch}"
    )
    .and_then(|()| file.sync_all())
    .map_err(|error| format!("cannot retain regression integration output: {error}"))?;
    Ok("retained exact regression integration outputs".to_owned())
}

fn regression_review_subject(root: &Path, options: &Options) -> Result<String, String> {
    let package = required_path(
        &options.input,
        "regression review subject requires --input package",
    )?;
    let selection = PathBuf::from(options.artifact.as_deref().ok_or_else(|| {
        "regression review subject requires --artifact provider selection".to_owned()
    })?);
    let output = required_path(
        &options.output,
        "regression review subject requires --output",
    )?;
    let verified = verify_regression_package(root, package)?;
    reverify_regression_provider_selection(
        root,
        package,
        &selection,
        &verified.candidate_commit,
        ".github/workflows/regression-corpus.yml",
    )?;
    let provider_run = parse_json(&read_text(&selection.join("provider-selected-run.json"))?)?;
    let proposer_account_id = json_member(
        json_member(provider_run.object()?, "actor")?.object()?,
        "id",
    )?
    .number()?;
    if proposer_account_id == 0 {
        return Err("regression proposal run has no stable proposer account".to_owned());
    }
    let record = JsonValue::Object(BTreeMap::from([
        (
            "assuranceEpochSha256".to_owned(),
            JsonValue::String(verified.assurance_epoch),
        ),
        (
            "candidateCommit".to_owned(),
            JsonValue::String(verified.candidate_commit),
        ),
        (
            "packageSha256".to_owned(),
            JsonValue::String(verified.package_sha256),
        ),
        (
            "providerSelectionSha256".to_owned(),
            JsonValue::String(record_digest(&selection)?),
        ),
        (
            "proposerAccountId".to_owned(),
            JsonValue::Number(proposer_account_id),
        ),
        ("schemaVersion".to_owned(), JsonValue::Number(1)),
        (
            "state".to_owned(),
            JsonValue::String("requires-regression-review".to_owned()),
        ),
    ]));
    write_atomic(output, &canonical_json_bytes(&record)?)?;
    Ok("prepared exact provider-bound regression review subject".to_owned())
}

fn regression_assemble_subject(root: &Path, options: &Options) -> Result<String, String> {
    let program = required_path(&options.program, "regression subject requires --program")?;
    let coverage = required_path(
        &options.input,
        "regression subject requires --input claim coverage",
    )?;
    let oracle_path = required_path(&options.from, "regression subject requires --from oracle")?;
    let candidate_path = required_path(&options.to, "regression subject requires --to candidate")?;
    let output = required_path(&options.output, "regression subject requires --output")?;
    let program_selection =
        PathBuf::from(options.artifact.as_deref().ok_or_else(|| {
            "regression subject requires --artifact program selection".to_owned()
        })?);
    let evidence_selection = required_path(
        &options.policy,
        "regression subject requires --policy evidence selection",
    )?;
    regression_assemble_subject_paths(
        root,
        options,
        &RegressionAssemblyPaths {
            program,
            coverage,
            oracle: oracle_path,
            candidate: candidate_path,
            program_root: program
                .parent()
                .ok_or_else(|| "regression program artifact has no root".to_owned())?,
            evidence_root: coverage
                .parent()
                .ok_or_else(|| "regression evidence artifact has no root".to_owned())?,
            public_root: None,
            program_selection: &program_selection,
            evidence_selection,
            public_selection: None,
            output,
        },
    )
}

fn regression_assemble_generated_subject(root: &Path, options: &Options) -> Result<String, String> {
    let nightly = required_path(
        &options.program,
        "generated regression requires --program nightly root",
    )?;
    let reviewed = required_path(
        &options.input,
        "generated regression requires --input reviewed root",
    )?;
    let generated = options
        .issue
        .as_deref()
        .ok_or_else(|| "generated regression requires --issue generated case id".to_owned())?;
    if !hell_builtins::validate_case_id(generated) || !generated.starts_with("generated-") {
        return Err("generated regression case id is not canonical".to_owned());
    }
    let source = nightly
        .join("mismatches")
        .join("proposed-regressions")
        .join(generated);
    let exploration = nightly.join("regression-exploration").join(generated);
    let coverage = reviewed.join("coverage").join("claim-coverage.json");
    let program_selection =
        PathBuf::from(options.artifact.as_deref().ok_or_else(|| {
            "generated regression requires --artifact nightly selection".to_owned()
        })?);
    let evidence_selection = required_path(
        &options.policy,
        "generated regression requires --policy reviewed selection",
    )?;
    let public_root = required_path(
        &options.proposal,
        "generated regression requires --proposal current public state root",
    )?;
    let public_selection = required_path(
        &options.findings,
        "generated regression requires --findings current public selection",
    )?;
    let output = required_path(&options.output, "generated regression requires --output")?;
    let mut generated_source = verify_generated_regression_source(nightly, generated, &source)?;
    let scheduled = verify_scheduled_generated_exploration(nightly, generated, &generated_source)?;
    let template = regression_template_case(options)?;
    let scheduled_fields = scheduled.object()?;
    if json_member(scheduled_fields, "automationDisposition")?.string()?
        != "ready-for-protected-regression-review"
        || json_member(scheduled_fields, "templateCaseId")?.string()? != template.id.as_ref()
    {
        return Err(
            "generated regression is not eligible for its selected reviewed template".to_owned(),
        );
    }
    generated_source.object_mut()?.insert(
        "templateCaseId".to_owned(),
        JsonValue::String(template.id.to_string()),
    );
    generated_source
        .object_mut()?
        .insert("scheduledExploration".to_owned(), scheduled);
    regression_assemble_subject_paths(
        root,
        options,
        &RegressionAssemblyPaths {
            program: &exploration.join("minimized.hell"),
            coverage: &coverage,
            oracle: &exploration.join("oracle"),
            candidate: &exploration.join("candidate"),
            program_root: nightly,
            evidence_root: reviewed,
            public_root: Some(public_root),
            program_selection: &program_selection,
            evidence_selection,
            public_selection: Some(public_selection),
            output,
        },
    )?;
    write_atomic(
        &output.join("generated-source.json"),
        &canonical_json_bytes(&generated_source)?,
    )?;
    Ok("assembled exact generated regression execution subject".to_owned())
}

fn verify_generated_regression_source(
    nightly: &Path,
    generated: &str,
    source_root: &Path,
) -> Result<JsonValue, String> {
    let record = verify_generated_regression_source_structural(nightly, generated, source_root)?;
    let fields = record.object()?;
    for (path, role, digest_field) in [
        (
            source_root.join("oracle"),
            ExecutableRole::Oracle,
            "oracleExecutableSha256",
        ),
        (
            source_root.join("candidate"),
            ExecutableRole::Candidate,
            "candidateExecutableSha256",
        ),
    ] {
        let retained = verify_executable(&path, role, None, hell_builtins::LANGUAGE_VERSION)
            .map_err(|error| format!("generated regression executable is invalid: {error}"))?;
        if retained.sha256.hex() != json_member(fields, digest_field)?.string()? {
            return Err(
                "generated regression executable probe differs from its retained identity"
                    .to_owned(),
            );
        }
    }
    Ok(record)
}

fn verify_generated_regression_source_structural(
    nightly: &Path,
    generated: &str,
    source_root: &Path,
) -> Result<JsonValue, String> {
    let proposal_path = nightly
        .join("mismatches")
        .join("proposed-regressions")
        .join(format!("{generated}.json"));
    let proposal_bytes = read_text(&proposal_path)?;
    let program_path = source_root.join("program.hell");
    let program = read_text(&program_path)?;
    let source_sha256 = sha256_bytes(program.as_bytes());
    let facts =
        generated_regression_proposal_facts(&proposal_bytes, generated, &program, source_sha256)?;
    let bundle = nightly.join("mismatches").join(generated);
    let case = hell_testkit::DifferentialCase {
        id: std::sync::Arc::from(generated),
        source: std::sync::Arc::from(program.as_str()),
        timeout: std::time::Duration::from_secs(5),
        ..hell_testkit::DifferentialCase::default()
    };
    let classification = hell_testkit::classify_retained_observation_bundle(&bundle, &case)
        .map_err(|error| format!("generated regression mismatch bundle is invalid: {error}"))?;
    let hell_testkit::RetainedObservationClassification::Mismatch {
        fingerprint_sha256, ..
    } = classification
    else {
        return Err("generated regression proposal does not retain a mismatch".to_owned());
    };
    let oracle_sha256 = retained_observation_executable_sha256(&bundle, "oracle")?;
    let candidate_sha256 = retained_observation_executable_sha256(&bundle, "candidate")?;
    for (path, expected) in [
        (source_root.join("oracle"), oracle_sha256),
        (source_root.join("candidate"), candidate_sha256),
    ] {
        let retained_sha256 = Digest::from_hex(&record_digest(&path)?)
            .map_err(|_| "generated regression executable digest is invalid".to_owned())?;
        if retained_sha256 != expected {
            return Err(
                "generated regression executable differs from its mismatch bundle".to_owned(),
            );
        }
    }
    Ok(JsonValue::Object(BTreeMap::from([
        ("astSha256".to_owned(), JsonValue::String(facts.ast_sha256)),
        (
            "bundleSha256".to_owned(),
            JsonValue::String(record_digest(&bundle)?),
        ),
        (
            "candidateExecutableSha256".to_owned(),
            JsonValue::String(candidate_sha256.hex()),
        ),
        ("caseId".to_owned(), JsonValue::String(generated.to_owned())),
        (
            "executionInputSha256".to_owned(),
            JsonValue::String(record_digest(&bundle.join("execution-input.json"))?),
        ),
        (
            "fingerprintSha256".to_owned(),
            JsonValue::String(fingerprint_sha256.hex()),
        ),
        (
            "oracleExecutableSha256".to_owned(),
            JsonValue::String(oracle_sha256.hex()),
        ),
        (
            "proposalSha256".to_owned(),
            JsonValue::String(sha256_bytes(proposal_bytes.as_bytes()).hex()),
        ),
        (
            "resultType".to_owned(),
            JsonValue::String(facts.result_type),
        ),
        ("schemaVersion".to_owned(), JsonValue::Number(1)),
        ("seed".to_owned(), JsonValue::Number(facts.seed)),
        (
            "shrinkPlan".to_owned(),
            JsonValue::String(facts.shrink_plan),
        ),
        (
            "sourceSha256".to_owned(),
            JsonValue::String(source_sha256.hex()),
        ),
    ])))
}

struct GeneratedRegressionProposalFacts {
    ast_sha256: String,
    result_type: String,
    seed: u64,
    shrink_plan: String,
}

struct GeneratedRegressionAutomationPlan {
    category: Option<&'static str>,
    candidate_typed_sha256: Option<String>,
    disposition: &'static str,
    localization_bundle_sha256: Option<String>,
    oracle_expected_typed_sha256: Option<String>,
    template_case_id: Option<&'static str>,
}

#[derive(Clone, Copy)]
struct GeneratedRegressionAutomationCandidate {
    category: &'static str,
    template_case_id: &'static str,
}

fn generated_regression_automation_candidate(
    case_id: &str,
) -> Result<Option<GeneratedRegressionAutomationCandidate>, String> {
    let (family, index) = case_id
        .strip_prefix("generated-")
        .and_then(|value| value.rsplit_once('-'))
        .ok_or_else(|| "generated regression automation case ID is invalid".to_owned())?;
    if index.len() != 4 || !index.bytes().all(|byte| byte.is_ascii_digit()) {
        return Err("generated regression automation index is not canonical".to_owned());
    }
    let selected = match family {
        "int-boundary" => ("runtime-typed-int-plus", "semantic-mismatch"),
        "short-circuit-unused-error" => ("bool-typed-result", "semantic-mismatch"),
        "record-field" => ("runtime-record-get-age", "semantic-mismatch"),
        "nested-maybe-list" | "either-tuple" | "productive-list" | "stable-ordering"
        | "text-roundtrip" | "json-object" | "variant-case" => return Ok(None),
        _ => return Err("generated regression automation family is unknown".to_owned()),
    };
    let (template, category) = selected;
    let reviewed = committed_differential_cases()
        .into_iter()
        .find(|case| case.id.as_ref() == template)
        .ok_or_else(|| "generated regression automation template disappeared".to_owned())?;
    if reviewed.claim_evidence.is_none() {
        return Err("generated regression automation template is not reviewed".to_owned());
    }
    Ok(Some(GeneratedRegressionAutomationCandidate {
        category,
        template_case_id: template,
    }))
}

fn no_generated_regression_automation(
    disposition: &'static str,
) -> GeneratedRegressionAutomationPlan {
    GeneratedRegressionAutomationPlan {
        category: None,
        candidate_typed_sha256: None,
        disposition,
        localization_bundle_sha256: None,
        oracle_expected_typed_sha256: None,
        template_case_id: None,
    }
}

fn regression_localization_case(
    template: &DifferentialCase,
    _case_id: &str,
    source: &str,
) -> DifferentialCase {
    let mut case = template.clone();
    case.id = template.id.clone();
    case.source = source.into();
    case.claim_evidence = None;
    case
}

fn regression_localization_target(template: &DifferentialCase) -> Result<&str, String> {
    let targets = &template
        .claim_evidence
        .as_ref()
        .ok_or_else(|| "generated localization template is not reviewed".to_owned())?
        .semantic_targets;
    let [target] = targets.as_slice() else {
        return Err("generated localization template does not select one target".to_owned());
    };
    Ok(target.builtin.as_ref())
}

fn retain_generated_regression_localization(
    retained: &Path,
    case_id: &str,
    oracle: &ExecutableIdentity,
    candidate: &ExecutableIdentity,
    minimized: &RegressionMinimization,
) -> Result<GeneratedRegressionAutomationPlan, String> {
    let Some(selected) = generated_regression_automation_candidate(case_id)? else {
        return Ok(no_generated_regression_automation(
            "retained-nonclaim-no-objectively-localized-reviewed-target",
        ));
    };
    let template = committed_differential_cases()
        .into_iter()
        .find(|case| case.id.as_ref() == selected.template_case_id)
        .ok_or_else(|| "generated regression localization template disappeared".to_owned())?;
    let case = regression_localization_case(&template, case_id, &minimized.source);
    let target = regression_localization_target(&template)?;
    let report = differential_with_nonclaim_trace_target(oracle, candidate, &case, target)
        .map_err(|error| format!("cannot execute generated regression localization: {error}"))?;
    if report.mismatches != minimized.report.mismatches
        || !same_regression_observation_behavior(&report.oracle, &minimized.report.oracle)
        || !same_regression_observation_behavior(&report.candidate, &minimized.report.candidate)
    {
        return Err("generated regression localization changed the exact mismatch".to_owned());
    }
    let bundle = retain_observation_bundle(&retained.join("localization"), &case, &report)
        .map_err(|error| format!("cannot retain generated regression localization: {error}"))?;
    generated_regression_automation_plan_from_bundle(retained, case_id, &case, &bundle, selected)
}

fn generated_regression_automation_plan_from_localization(
    retained: &Path,
    case_id: &str,
    minimized: &str,
) -> Result<GeneratedRegressionAutomationPlan, String> {
    let Some(selected) = generated_regression_automation_candidate(case_id)? else {
        if retained.join("localization").exists() {
            return Err(
                "unsupported generated regression retains localization evidence".to_owned(),
            );
        }
        return Ok(no_generated_regression_automation(
            "retained-nonclaim-no-objectively-localized-reviewed-target",
        ));
    };
    let template = committed_differential_cases()
        .into_iter()
        .find(|case| case.id.as_ref() == selected.template_case_id)
        .ok_or_else(|| "generated regression localization template disappeared".to_owned())?;
    let case = regression_localization_case(&template, case_id, minimized);
    let bundle = retained
        .join("localization")
        .join(selected.template_case_id);
    generated_regression_automation_plan_from_bundle(retained, case_id, &case, &bundle, selected)
}

fn generated_regression_automation_plan_from_bundle(
    retained: &Path,
    case_id: &str,
    case: &DifferentialCase,
    bundle: &Path,
    selected: GeneratedRegressionAutomationCandidate,
) -> Result<GeneratedRegressionAutomationPlan, String> {
    let observation = parse_json(&read_text(&bundle.join("candidate/observation.json"))?)?;
    hell_testkit::verify_observation_bundle_for_case(bundle, case)
        .map_err(|error| format!("generated regression localization is invalid: {error}"))?;
    let classification = hell_testkit::classify_retained_observation_bundle(bundle, case)
        .map_err(|error| format!("cannot classify generated regression localization: {error}"))?;
    let hell_testkit::RetainedObservationClassification::Mismatch {
        raw_mismatches,
        normalized_mismatches,
        ..
    } = classification
    else {
        return Err("generated regression localization no longer mismatches".to_owned());
    };
    let original_case = DifferentialCase {
        id: case_id.into(),
        source: case.source.clone(),
        timeout: case.timeout,
        ..DifferentialCase::default()
    };
    let original = hell_testkit::classify_retained_observation_bundle(
        &retained.join("evidence").join(case_id),
        &original_case,
    )
    .map_err(|error| format!("cannot reclassify original generated regression: {error}"))?;
    let hell_testkit::RetainedObservationClassification::Mismatch {
        raw_mismatches: original_raw_mismatches,
        normalized_mismatches: original_mismatches,
        ..
    } = original
    else {
        return Err("original generated regression no longer mismatches".to_owned());
    };
    if raw_mismatches != original_raw_mismatches || normalized_mismatches != original_mismatches {
        return Err("generated localization differs from original mismatch identity".to_owned());
    }
    verify_localization_behavior_join(&retained.join("evidence").join(case_id), bundle)?;
    let template = committed_differential_cases()
        .into_iter()
        .find(|template| template.id.as_ref() == selected.template_case_id)
        .ok_or_else(|| "generated localization template disappeared".to_owned())?;
    let target = regression_localization_target(&template)?;
    let target_id = hell_builtins::lookup(target)
        .ok_or_else(|| "generated localization target disappeared".to_owned())?
        .id
        .0;
    let typed_sha256 = match json_member(observation.object()?, "semanticTypedResultSha256")? {
        JsonValue::Null => {
            return Ok(GeneratedRegressionAutomationPlan {
                category: None,
                candidate_typed_sha256: None,
                disposition: "retained-nonclaim-reviewed-target-not-implicated",
                localization_bundle_sha256: Some(record_digest(&retained.join("localization"))?),
                oracle_expected_typed_sha256: Some(
                    sha256_bytes(generated_expected_int_typed_result(case_id, bundle)?.as_bytes())
                        .hex(),
                ),
                template_case_id: None,
            });
        }
        JsonValue::String(value) => Digest::from_hex(value)
            .map_err(|_| "generated localization typed digest is invalid".to_owned())?,
        _ => return Err("generated localization typed digest has invalid type".to_owned()),
    };
    let expected = generated_expected_int_typed_result(case_id, bundle)?;
    let candidate_typed = read_text(&bundle.join("candidate/semantic-typed-result.json"))?;
    let candidate_typed = candidate_typed
        .strip_suffix('\n')
        .ok_or_else(|| "generated localization typed result is noncanonical".to_owned())?;
    let expected_sha256 = sha256_bytes(expected.as_bytes()).hex();
    let candidate_sha256 = sha256_bytes(candidate_typed.as_bytes()).hex();
    let implicated = normalized_mismatches.len() == 1
        && normalized_mismatches[0].category == hell_testkit::MismatchKind::Stdout
        && json_member(observation.object()?, "semanticTypedResultBuiltinId")?.number()?
            == u64::from(target_id)
        && typed_sha256.hex() == candidate_sha256
        && candidate_sha256 != expected_sha256;
    Ok(GeneratedRegressionAutomationPlan {
        category: implicated.then_some(selected.category),
        candidate_typed_sha256: Some(candidate_sha256),
        disposition: if implicated {
            "ready-for-protected-regression-review"
        } else {
            "retained-nonclaim-reviewed-target-not-implicated"
        },
        localization_bundle_sha256: Some(record_digest(&retained.join("localization"))?),
        oracle_expected_typed_sha256: Some(expected_sha256),
        template_case_id: implicated.then_some(selected.template_case_id),
    })
}

fn same_regression_observation_behavior(
    left: &hell_testkit::Observation,
    right: &hell_testkit::Observation,
) -> bool {
    left.identity.sha256 == right.identity.sha256
        && left.environment_profile == right.environment_profile
        && left.process_helper_sha256 == right.process_helper_sha256
        && left.mode == right.mode
        && left.status == right.status
        && left.stdout == right.stdout
        && left.raw_stderr == right.raw_stderr
        && left.claim_input_stderr == right.claim_input_stderr
        && left.stderr == right.stderr
        && left.timed_out == right.timed_out
        && left.diagnostic == right.diagnostic
        && left.filesystem == right.filesystem
        && left.harness_normalizers == right.harness_normalizers
        && left.claim_normalizers == right.claim_normalizers
        && left.resource_audit == right.resource_audit
}

fn verify_localization_behavior_join(original: &Path, localization: &Path) -> Result<(), String> {
    for role in ["oracle", "candidate"] {
        let mut original_observation =
            parse_json(&read_text(&original.join(role).join("observation.json"))?)?
                .object()?
                .clone();
        let mut localized_observation = parse_json(&read_text(
            &localization.join(role).join("observation.json"),
        )?)?
        .object()?
        .clone();
        for field in [
            "caseId",
            "semanticBoundaries",
            "semanticCoverage",
            "semanticEffectTrace",
            "semanticEventOrder",
            "semanticObligationTrace",
            "semanticResourceTrace",
            "semanticTaskTrace",
            "semanticTypedResultBuiltinId",
            "semanticTypedResultSha256",
        ] {
            if original_observation.remove(field).is_none()
                || localized_observation.remove(field).is_none()
            {
                return Err("generated localization observation schema is incomplete".to_owned());
            }
        }
        if original_observation != localized_observation {
            return Err(
                "generated localization changed retained nonsemantic observation behavior"
                    .to_owned(),
            );
        }
        for file in [
            "stderr.bin",
            "stderr.claim-input.bin",
            "stderr.raw.bin",
            "stdout.bin",
        ] {
            if read_regular_file(&original.join(role).join(file))?
                != read_regular_file(&localization.join(role).join(file))?
            {
                return Err(format!(
                    "generated localization changed retained {role}/{file}"
                ));
            }
        }
    }
    if read_text(&original.join("candidate/resource-audit.json"))?
        != read_text(&localization.join("candidate/resource-audit.json"))?
    {
        return Err("generated localization changed retained resource behavior".to_owned());
    }
    Ok(())
}

fn generated_expected_int_typed_result(case_id: &str, bundle: &Path) -> Result<String, String> {
    if !matches!(
        case_id
            .strip_prefix("generated-")
            .and_then(|value| value.rsplit_once('-'))
            .map(|(family, _)| family),
        Some("int-boundary" | "short-circuit-unused-error" | "record-field")
    ) {
        return Err("generated regression has no supported independent typed oracle".to_owned());
    }
    let stdout = read_regular_file(&bundle.join("oracle/stdout.bin"))?;
    let value = std::str::from_utf8(&stdout)
        .ok()
        .and_then(|text| text.strip_suffix('\n'))
        .filter(|text| !text.contains('\n'))
        .and_then(|text| text.parse::<i64>().ok())
        .ok_or_else(|| "generated regression oracle output is not one canonical Int".to_owned())?;
    let value = format!("{{\"type\":\"Int\",\"value\":\"{value}\"}}");
    let boundary = if case_id.contains("short-circuit-unused-error") {
        "conditional-selected"
    } else {
        "adapter-result"
    };
    Ok(format!(
        "{{\"type\":\"TypedResult\",\"argument\":0,\"boundary\":\"{boundary}\",\"value\":{value}}}"
    ))
}

fn generated_regression_proposal_facts(
    proposal_bytes: &str,
    generated: &str,
    program: &str,
    source_sha256: Digest,
) -> Result<GeneratedRegressionProposalFacts, String> {
    let proposal = parse_json(proposal_bytes)?;
    let proposal = proposal.object()?;
    exact_keys(
        proposal,
        &[
            "astSha256",
            "caseId",
            "claimEligible",
            "minimizationStatus",
            "mismatchBundlePath",
            "resultType",
            "reviewState",
            "schemaVersion",
            "seed",
            "shrinkPlan",
            "sourceSha256",
        ],
    )?;
    let ast_sha256 = json_member(proposal, "astSha256")?.string()?;
    let seed = json_member(proposal, "seed")?.number()?;
    let result_type = json_member(proposal, "resultType")?.string()?;
    let shrink_plan = json_member(proposal, "shrinkPlan")?.string()?;
    require_digest(ast_sha256, "generated regression AST")?;
    let index_text = generated
        .rsplit_once('-')
        .map(|(_, index)| index)
        .ok_or_else(|| "generated regression case index is invalid".to_owned())?;
    if index_text.len() != 4 || !index_text.bytes().all(|byte| byte.is_ascii_digit()) {
        return Err("generated regression case index is not canonical".to_owned());
    }
    let index = index_text
        .parse::<usize>()
        .map_err(|_| "generated regression case index is invalid".to_owned())?;
    if index >= 1_024 {
        return Err("generated regression case index exceeds the bounded corpus".to_owned());
    }
    let reproduced = hell_testkit::generated_typed_cases(seed, index.saturating_add(1))
        .into_iter()
        .nth(index)
        .ok_or_else(|| "generated regression case cannot be reproduced".to_owned())?;
    if json_member(proposal, "schemaVersion")?.number()? != 1
        || json_member(proposal, "caseId")?.string()? != generated
        || reproduced.id.as_ref() != generated
        || reproduced.source.as_ref() != program
        || reproduced.ast_sha256.hex() != ast_sha256
        || format!("{:?}", reproduced.result_type) != result_type
        || reproduced.shrink_description.as_ref() != shrink_plan
        || json_member(proposal, "sourceSha256")?.string()? != source_sha256.hex()
        || json_member(proposal, "mismatchBundlePath")?.string()?
            != format!("mismatches/{generated}")
        || json_member(proposal, "minimizationStatus")?.string()? != "pending"
        || json_member(proposal, "reviewState")?.string()? != "unreviewed"
        || json_member(proposal, "claimEligible")?.boolean()?
        || seed == 0
    {
        return Err(
            "generated regression proposal is not an exact pending nightly mismatch".to_owned(),
        );
    }
    Ok(GeneratedRegressionProposalFacts {
        ast_sha256: ast_sha256.to_owned(),
        result_type: result_type.to_owned(),
        seed,
        shrink_plan: shrink_plan.to_owned(),
    })
}

fn verify_scheduled_generated_exploration(
    nightly: &Path,
    generated: &str,
    generated_source: &JsonValue,
) -> Result<JsonValue, String> {
    let root = nightly.join("regression-exploration");
    let manifest_text = read_text(&root.join("manifest.json"))?;
    let manifest = parse_json(&manifest_text)?;
    let manifest = manifest.object()?;
    exact_keys(manifest, &["caseIds", "schemaVersion", "state"])?;
    let case_ids = json_member(manifest, "caseIds")?
        .array()?
        .iter()
        .map(JsonValue::string)
        .collect::<Result<Vec<_>, _>>()?;
    if json_member(manifest, "schemaVersion")?.number()? != 1
        || json_member(manifest, "state")?.string()? != "minimized-unreviewed-nonclaim"
        || !case_ids.windows(2).all(|pair| pair[0] < pair[1])
        || case_ids.binary_search(&generated).is_err()
    {
        return Err("scheduled regression exploration manifest is invalid".to_owned());
    }
    verify_scheduled_exploration_inventory(&root, &case_ids)?;
    let retained = root.join(generated);
    let record_text = read_text(&retained.join("exploration.json"))?;
    let record = parse_json(&record_text)?;
    let record = record.object()?;
    exact_keys(
        record,
        &[
            "automationDisposition",
            "bundleSha256",
            "candidateExecutableSha256",
            "claimEligible",
            "compatibilityCategory",
            "executionInputSha256",
            "fingerprintSha256",
            "generatedSource",
            "localizationBundleSha256",
            "localizationCandidateTypedSha256",
            "localizationOracleExpectedTypedSha256",
            "minimizedSourceSha256",
            "oracleExecutableSha256",
            "reviewed",
            "schemaVersion",
            "templateCaseId",
            "traceSha256",
        ],
    )?;
    let minimized = read_text(&retained.join("minimized.hell"))?;
    let automation =
        generated_regression_automation_plan_from_localization(&retained, generated, &minimized)?;
    if !scheduled_automation_record_matches(record, generated_source, &automation)? {
        return Err("scheduled regression exploration record is invalid".to_owned());
    }
    let original = read_text(&retained.join("original.hell"))?;
    if sha256_bytes(original.as_bytes()).hex()
        != json_member(generated_source.object()?, "sourceSha256")?.string()?
    {
        return Err(
            "scheduled exploration original source differs from nightly proposal".to_owned(),
        );
    }
    if minimized.is_empty()
        || !minimized.ends_with('\n')
        || sha256_bytes(minimized.as_bytes()).hex()
            != json_member(record, "minimizedSourceSha256")?.string()?
    {
        return Err("scheduled minimized regression source is not canonical".to_owned());
    }
    verify_scheduled_minimization_trace(&retained, &original, &minimized, record)?;
    verify_scheduled_exploration_evidence(&retained, generated, &minimized, record)?;
    scheduled_exploration_fact(record, &record_text, &manifest_text)
}

fn scheduled_automation_record_matches(
    record: &BTreeMap<String, JsonValue>,
    generated_source: &JsonValue,
    automation: &GeneratedRegressionAutomationPlan,
) -> Result<bool, String> {
    let category_matches = match automation.category {
        Some(value) => json_member(record, "compatibilityCategory")?.string()? == value,
        None => matches!(
            json_member(record, "compatibilityCategory")?,
            JsonValue::Null
        ),
    };
    let template_matches = match automation.template_case_id {
        Some(value) => json_member(record, "templateCaseId")?.string()? == value,
        None => matches!(json_member(record, "templateCaseId")?, JsonValue::Null),
    };
    Ok(json_member(record, "schemaVersion")?.number()? == 1
        && !json_member(record, "claimEligible")?.boolean()?
        && !json_member(record, "reviewed")?.boolean()?
        && json_member(record, "automationDisposition")?.string()? == automation.disposition
        && category_matches
        && template_matches
        && json_member(record, "localizationBundleSha256")?
            == &automation
                .localization_bundle_sha256
                .clone()
                .map_or(JsonValue::Null, JsonValue::String)
        && json_member(record, "localizationCandidateTypedSha256")?
            == &automation
                .candidate_typed_sha256
                .clone()
                .map_or(JsonValue::Null, JsonValue::String)
        && json_member(record, "localizationOracleExpectedTypedSha256")?
            == &automation
                .oracle_expected_typed_sha256
                .clone()
                .map_or(JsonValue::Null, JsonValue::String)
        && canonical_json_bytes(json_member(record, "generatedSource")?)?
            == canonical_json_bytes(generated_source)?)
}

fn verify_scheduled_exploration_evidence(
    retained: &Path,
    generated: &str,
    minimized: &str,
    record: &BTreeMap<String, JsonValue>,
) -> Result<(), String> {
    let case = DifferentialCase {
        id: std::sync::Arc::from(generated),
        source: std::sync::Arc::from(minimized),
        timeout: std::time::Duration::from_secs(5),
        ..DifferentialCase::default()
    };
    let bundle = retained.join("evidence").join(generated);
    let classification = hell_testkit::classify_retained_observation_bundle(&bundle, &case)
        .map_err(|error| format!("scheduled minimized mismatch is invalid: {error}"))?;
    let hell_testkit::RetainedObservationClassification::Mismatch {
        fingerprint_sha256, ..
    } = classification
    else {
        return Err("scheduled minimized evidence is not a mismatch".to_owned());
    };
    for (key, actual) in [
        ("bundleSha256", record_digest(&bundle)?),
        (
            "executionInputSha256",
            record_digest(&bundle.join("execution-input.json"))?,
        ),
        ("fingerprintSha256", fingerprint_sha256.hex()),
        (
            "oracleExecutableSha256",
            retained_observation_executable_sha256(&bundle, "oracle")?.hex(),
        ),
        (
            "candidateExecutableSha256",
            retained_observation_executable_sha256(&bundle, "candidate")?.hex(),
        ),
    ] {
        if json_member(record, key)?.string()? != actual {
            return Err(format!(
                "scheduled exploration {key} differs from retained evidence"
            ));
        }
    }
    for (side, key) in [
        ("oracle", "oracleExecutableSha256"),
        ("candidate", "candidateExecutableSha256"),
    ] {
        if record_digest(&retained.join(side))? != json_member(record, key)?.string()? {
            return Err(format!(
                "scheduled exploration {side} executable differs from evidence"
            ));
        }
    }
    Ok(())
}

fn scheduled_exploration_fact(
    record: &BTreeMap<String, JsonValue>,
    record_text: &str,
    manifest_text: &str,
) -> Result<JsonValue, String> {
    Ok(JsonValue::Object(BTreeMap::from([
        (
            "automationDisposition".to_owned(),
            json_member(record, "automationDisposition")?.clone(),
        ),
        (
            "bundleSha256".to_owned(),
            json_member(record, "bundleSha256")?.clone(),
        ),
        (
            "candidateExecutableSha256".to_owned(),
            json_member(record, "candidateExecutableSha256")?.clone(),
        ),
        (
            "compatibilityCategory".to_owned(),
            json_member(record, "compatibilityCategory")?.clone(),
        ),
        (
            "executionInputSha256".to_owned(),
            json_member(record, "executionInputSha256")?.clone(),
        ),
        (
            "explorationRecordSha256".to_owned(),
            JsonValue::String(sha256_bytes(record_text.as_bytes()).hex()),
        ),
        (
            "fingerprintSha256".to_owned(),
            json_member(record, "fingerprintSha256")?.clone(),
        ),
        (
            "manifestSha256".to_owned(),
            JsonValue::String(sha256_bytes(manifest_text.as_bytes()).hex()),
        ),
        (
            "localizationBundleSha256".to_owned(),
            json_member(record, "localizationBundleSha256")?.clone(),
        ),
        (
            "localizationCandidateTypedSha256".to_owned(),
            json_member(record, "localizationCandidateTypedSha256")?.clone(),
        ),
        (
            "localizationOracleExpectedTypedSha256".to_owned(),
            json_member(record, "localizationOracleExpectedTypedSha256")?.clone(),
        ),
        (
            "minimizedSourceSha256".to_owned(),
            json_member(record, "minimizedSourceSha256")?.clone(),
        ),
        (
            "oracleExecutableSha256".to_owned(),
            json_member(record, "oracleExecutableSha256")?.clone(),
        ),
        ("schemaVersion".to_owned(), JsonValue::Number(1)),
        (
            "templateCaseId".to_owned(),
            json_member(record, "templateCaseId")?.clone(),
        ),
        (
            "traceSha256".to_owned(),
            json_member(record, "traceSha256")?.clone(),
        ),
    ])))
}

fn verify_scheduled_exploration_inventory(root: &Path, case_ids: &[&str]) -> Result<(), String> {
    let expected = case_ids.iter().copied().collect::<BTreeSet<_>>();
    let mut actual = BTreeSet::new();
    for entry in fs::read_dir(root)
        .map_err(|error| format!("cannot enumerate scheduled exploration: {error}"))?
    {
        let entry = entry.map_err(|error| format!("cannot read scheduled exploration: {error}"))?;
        let name = entry
            .file_name()
            .into_string()
            .map_err(|_| "scheduled exploration path is not UTF-8".to_owned())?;
        if name == "manifest.json" {
            if !entry
                .file_type()
                .map_err(|error| format!("cannot inspect exploration manifest: {error}"))?
                .is_file()
            {
                return Err("scheduled exploration manifest is not a file".to_owned());
            }
        } else if entry
            .file_type()
            .map_err(|error| format!("cannot inspect exploration case: {error}"))?
            .is_dir()
            && hell_builtins::validate_case_id(&name)
        {
            actual.insert(name);
        } else {
            return Err("scheduled exploration contains an extra entry".to_owned());
        }
    }
    if actual.iter().map(String::as_str).collect::<BTreeSet<_>>() != expected {
        return Err("scheduled exploration manifest differs from retained case set".to_owned());
    }
    Ok(())
}

fn verify_scheduled_minimization_trace(
    retained: &Path,
    original: &str,
    minimized: &str,
    record: &BTreeMap<String, JsonValue>,
) -> Result<(), String> {
    let trace_text = read_text(&retained.join("minimization-trace.json"))?;
    if sha256_bytes(trace_text.as_bytes()).hex() != json_member(record, "traceSha256")?.string()? {
        return Err("scheduled minimization trace digest differs from exploration".to_owned());
    }
    let trace = parse_json(&trace_text)?;
    let trace = trace.object()?;
    exact_keys(
        trace,
        &[
            "algorithm",
            "attempts",
            "minimizedBytes",
            "originalBytes",
            "schemaVersion",
        ],
    )?;
    if json_member(trace, "schemaVersion")?.number()? != 1
        || json_member(trace, "algorithm")?.string()? != "deterministic-character-ddmin-v1"
        || json_member(trace, "originalBytes")?.number()? != original.len() as u64
        || json_member(trace, "minimizedBytes")?.number()? != minimized.len() as u64
    {
        return Err("scheduled minimization trace header is invalid".to_owned());
    }
    let mut last_preserved = original.to_owned();
    for (index, attempt) in json_member(trace, "attempts")?.array()?.iter().enumerate() {
        let attempt = attempt.object()?;
        exact_keys(
            attempt,
            &[
                "bytes",
                "path",
                "preservedExactMismatchAndClaimEvidence",
                "sourceSha256",
            ],
        )?;
        let expected_path = format!("trials/{index:03}.hell");
        if json_member(attempt, "path")?.string()? != expected_path {
            return Err("scheduled minimization trial path is noncanonical".to_owned());
        }
        let trial = read_text(&retained.join(&expected_path))?;
        if json_member(attempt, "bytes")?.number()? != trial.len() as u64
            || json_member(attempt, "sourceSha256")?.string()?
                != sha256_bytes(trial.as_bytes()).hex()
        {
            return Err("scheduled minimization trial differs from trace".to_owned());
        }
        if json_member(attempt, "preservedExactMismatchAndClaimEvidence")?.boolean()? {
            last_preserved = trial;
        }
    }
    if last_preserved != minimized {
        return Err("scheduled minimization trace does not derive minimized source".to_owned());
    }
    Ok(())
}

fn retained_observation_executable_sha256(bundle: &Path, side: &str) -> Result<Digest, String> {
    let observation = parse_json(&read_text(&bundle.join(side).join("observation.json"))?)?;
    let identity = json_member(observation.object()?, "identity")?.object()?;
    Digest::from_hex(json_member(identity, "sha256")?.string()?)
        .map_err(|error| format!("invalid retained {side} executable digest: {error}"))
}

struct RegressionAssemblyPaths<'a> {
    program: &'a Path,
    coverage: &'a Path,
    oracle: &'a Path,
    candidate: &'a Path,
    program_root: &'a Path,
    evidence_root: &'a Path,
    public_root: Option<&'a Path>,
    program_selection: &'a Path,
    evidence_selection: &'a Path,
    public_selection: Option<&'a Path>,
    output: &'a Path,
}

fn regression_assemble_subject_paths(
    root: &Path,
    options: &Options,
    paths: &RegressionAssemblyPaths<'_>,
) -> Result<String, String> {
    let RegressionAssemblyPaths {
        program,
        coverage,
        oracle: oracle_path,
        candidate: candidate_path,
        program_root,
        evidence_root,
        public_root,
        program_selection,
        evidence_selection,
        public_selection,
        output,
    } = *paths;
    if output.exists() {
        return Err("regression subject output already exists".to_owned());
    }
    let source = read_text(program)?;
    if source.is_empty() || !source.ends_with('\n') {
        return Err("regression subject program is not canonical text".to_owned());
    }
    let template = regression_template_case(options)?;
    let (_, assurance_epoch) = epoch(root)?;
    let candidate_commit = git_output(root, &["rev-parse", "HEAD"])?;
    verify_bound_details(
        coverage,
        "claim-coverage",
        candidate_commit.trim(),
        &assurance_epoch.hex(),
    )?;
    let oracle = verify_executable(
        oracle_path,
        ExecutableRole::Oracle,
        None,
        hell_builtins::LANGUAGE_VERSION,
    )
    .map_err(|error| format!("cannot verify regression subject oracle: {error}"))?;
    let candidate = verify_executable(
        candidate_path,
        ExecutableRole::Candidate,
        None,
        hell_builtins::LANGUAGE_VERSION,
    )
    .map_err(|error| format!("cannot verify regression subject candidate: {error}"))?;
    regression_candidate_build_info(&candidate, candidate_commit.trim())?;
    let expected = regression_coverage_executable_identities(
        coverage,
        &template,
        regression_host_platform()?,
    )?;
    if (oracle.sha256, candidate.sha256) != expected {
        return Err(
            "regression subject executable pair differs from finalized coverage".to_owned(),
        );
    }
    fs::create_dir(output).map_err(|error| format!("cannot create regression subject: {error}"))?;
    write_atomic(&output.join("program.hell"), source.as_bytes())?;
    copy_regression_executable(oracle_path, &output.join("oracle"))?;
    copy_regression_executable(candidate_path, &output.join("candidate"))?;
    fs::copy(coverage, output.join("claim-coverage.json"))
        .map_err(|error| format!("cannot retain finalized regression claim coverage: {error}"))?;
    let sources = output.join("sources");
    let selections = output.join("source-selection");
    copy_regression_tree(program_root, &sources.join("program"))?;
    copy_regression_tree(evidence_root, &sources.join("evidence"))?;
    copy_regression_tree(program_selection, &selections.join("program"))?;
    copy_regression_tree(evidence_selection, &selections.join("evidence"))?;
    match (public_root, public_selection) {
        (Some(public), Some(selection)) => {
            copy_regression_tree(public, &sources.join("public"))?;
            copy_regression_tree(selection, &selections.join("public"))?;
        }
        (None, None) => {}
        _ => {
            return Err(
                "regression public source and provider selection must be supplied together"
                    .to_owned(),
            );
        }
    }
    Ok("assembled exact regression execution subject".to_owned())
}

struct RegressionProviderContext {
    artifact_name: String,
    workflow_path: String,
    event: String,
    head_sha: String,
    directory_sha256: String,
    archive_sha256: String,
    run_id: u64,
    run_attempt: u64,
    artifact_id: u64,
}

fn regression_provider_context() -> Result<RegressionProviderContext, String> {
    let text = std::env::var("REGRESSION_PROVIDER_CONTEXT").map_err(|_| {
        "regression provider acquisition requires REGRESSION_PROVIDER_CONTEXT".to_owned()
    })?;
    let document = parse_json(&text)?;
    let document = document.object()?;
    exact_keys(
        document,
        &[
            "artifactId",
            "artifactName",
            "archiveSha256",
            "directorySha256",
            "event",
            "headSha",
            "runAttempt",
            "runId",
            "workflowPath",
        ],
    )?;
    let positive = |key: &str| -> Result<u64, String> {
        json_member(document, key)?.number().and_then(|value| {
            (value != 0)
                .then_some(value)
                .ok_or_else(|| format!("regression provider {key} is not positive"))
        })
    };
    Ok(RegressionProviderContext {
        artifact_name: json_member(document, "artifactName")?.string()?.to_owned(),
        workflow_path: json_member(document, "workflowPath")?.string()?.to_owned(),
        event: json_member(document, "event")?.string()?.to_owned(),
        head_sha: json_member(document, "headSha")?.string()?.to_owned(),
        directory_sha256: json_member(document, "directorySha256")?
            .string()?
            .to_owned(),
        archive_sha256: json_member(document, "archiveSha256")?.string()?.to_owned(),
        run_id: positive("runId")?,
        run_attempt: positive("runAttempt")?,
        artifact_id: positive("artifactId")?,
    })
}

fn regression_acquire_subject(
    root: &Path,
    options: &Options,
    historical: bool,
) -> Result<String, String> {
    let subject = required_path(
        &options.output,
        "regression acquisition requires --output subject directory",
    )?;
    let selection = PathBuf::from(options.artifact.as_deref().ok_or_else(|| {
        "regression acquisition requires --artifact selection directory".to_owned()
    })?);
    if subject.exists() || selection.exists() {
        return Err("regression acquisition output already exists".to_owned());
    }
    let context = regression_provider_context()?;
    let endpoint = PathBuf::from("repos")
        .join("Portfoligno")
        .join("hell-rs")
        .join("actions")
        .join("artifacts")
        .join(context.artifact_id.to_string())
        .join("zip");
    let bytes = github_api_bytes(&endpoint)?;
    if sha256_bytes(&bytes).hex() != context.archive_sha256 {
        return Err("regression provider archive differs from dispatch".to_owned());
    }
    let temporary = create_private_temp_directory("hell-regression-acquire")?;
    let archive = temporary.join("artifact.zip");
    write_atomic(&archive, &bytes)?;
    extract_external_zip(&archive, subject)?;
    fs::remove_dir_all(&temporary)
        .map_err(|error| format!("cannot clean regression acquisition: {error}"))?;
    let rendered = verify_provider_artifact_selection_to(
        root,
        subject,
        &selection,
        &context.artifact_name,
        &context.workflow_path,
        &context.event,
        context.run_id,
        context.run_attempt,
        context.artifact_id,
        &context.head_sha,
        &context.directory_sha256,
        &context.archive_sha256,
    )?;
    write_atomic(&selection.join("selection.json"), rendered.as_bytes())?;
    verify_regression_provider_archive(subject, &selection, context.artifact_id, &rendered)?;
    if historical {
        verify_and_retain_historical_regression_workflow(root, &selection, &rendered)?;
    } else {
        verify_acquired_regression_workflow(root, &selection, &rendered)?;
        retain_regression_provider_workflow(root, &selection, &context.workflow_path)?;
    }
    Ok("acquired exact immutable regression artifact and provider proof".to_owned())
}

fn verify_and_retain_historical_regression_workflow(
    root: &Path,
    selection_root: &Path,
    rendered: &str,
) -> Result<(), String> {
    let required = std::env::var("REGRESSION_REQUIRED_WORKFLOW_PATH").map_err(|_| {
        "regression acquisition requires REGRESSION_REQUIRED_WORKFLOW_PATH".to_owned()
    })?;
    let selection = parse_json(rendered)?;
    let selection = selection.object()?;
    let run = parse_json(&read_text(
        &selection_root.join("provider-selected-run.json"),
    )?)?;
    if json_member(selection, "workflowPath")?.string()? != required
        || json_member(selection, "event")?.string()? != "schedule"
        || provider_run_workflow_ref(json_member(run.object()?, "path")?.string()?, &required)?
            != "refs/heads/main"
    {
        return Err("historical regression provider workflow identity is invalid".to_owned());
    }
    let provider_head = json_member(run.object()?, "head_sha")?.string()?;
    let workflow = git_output_bytes(root, &["show", &format!("{provider_head}:{required}")])?;
    if workflow.is_empty()
        || sha256_bytes(&workflow).hex()
            != json_member(selection, "workflowBlobSha256")?.string()?
    {
        return Err("historical regression provider workflow bytes differ".to_owned());
    }
    write_atomic(&selection_root.join("provider-workflow.yml"), &workflow)
}

fn retain_regression_provider_workflow(
    root: &Path,
    selection: &Path,
    workflow: &str,
) -> Result<(), String> {
    let relative = validate_provider_workflow_path(workflow)?;
    write_atomic(
        &selection.join("provider-workflow.yml"),
        &read_regular_file(&root.join(relative))?,
    )
}

fn verify_acquired_regression_workflow(
    root: &Path,
    selection_root: &Path,
    rendered: &str,
) -> Result<(), String> {
    let required = std::env::var("REGRESSION_REQUIRED_WORKFLOW_PATH").map_err(|_| {
        "regression acquisition requires REGRESSION_REQUIRED_WORKFLOW_PATH".to_owned()
    })?;
    let selection = parse_json(rendered)?;
    let selection = selection.object()?;
    let selected_event = json_member(selection, "event")?.string()?;
    let accepted_event = match required.as_str() {
        ".github/workflows/nightly.yml" => selected_event == "schedule",
        ".github/workflows/regression-subject.yml" => {
            matches!(selected_event, "workflow_dispatch" | "workflow_run")
        }
        _ => selected_event == "workflow_dispatch",
    };
    if json_member(selection, "workflowPath")?.string()? != required || !accepted_event {
        return Err("regression artifact has the wrong producing workflow or event".to_owned());
    }
    let run = parse_json(&read_text(
        &selection_root.join("provider-selected-run.json"),
    )?)?;
    if provider_run_workflow_ref(json_member(run.object()?, "path")?.string()?, &required)?
        != "refs/heads/main"
    {
        return Err("regression artifact producer ref is not exact main".to_owned());
    }
    let head = json_member(selection, "candidateCommit")?.string()?;
    let remote = github_raw_source_at("Portfoligno/hell-rs", &required, head)?;
    if sha256_bytes(&remote).hex() != json_member(selection, "workflowBlobSha256")?.string()?
        || record_digest(&root.join(&required))?
            != json_member(selection, "workflowBlobSha256")?.string()?
    {
        return Err("regression artifact producer blob is not trusted current source".to_owned());
    }
    Ok(())
}

fn regression_select_subject(root: &Path, options: &Options) -> Result<String, String> {
    let input = required_path(
        &options.input,
        "regression subject selection requires --input extracted artifact",
    )?;
    let output = required_path(
        &options.output,
        "regression subject selection requires --output directory",
    )?;
    let required = |name: &str| {
        std::env::var(name).map_err(|_| format!("regression subject selection requires {name}"))
    };
    let positive = |name: &str| -> Result<u64, String> {
        required(name)?
            .parse::<u64>()
            .ok()
            .filter(|value| *value != 0)
            .ok_or_else(|| format!("regression subject selection {name} is not positive"))
    };
    let artifact = required("REGRESSION_PROVIDER_ARTIFACT_NAME")?;
    let workflow = required("REGRESSION_PROVIDER_WORKFLOW_PATH")?;
    let event = required("REGRESSION_PROVIDER_EVENT")?;
    let head = required("REGRESSION_PROVIDER_HEAD_SHA")?;
    let directory = required("REGRESSION_PROVIDER_DIRECTORY_SHA256")?;
    let archive = required("REGRESSION_PROVIDER_ARCHIVE_SHA256")?;
    let artifact_id = positive("REGRESSION_PROVIDER_ARTIFACT_ID")?;
    let selection = verify_provider_artifact_selection_to(
        root,
        input,
        output,
        &artifact,
        &workflow,
        &event,
        positive("REGRESSION_PROVIDER_RUN_ID")?,
        positive("REGRESSION_PROVIDER_RUN_ATTEMPT")?,
        artifact_id,
        &head,
        &directory,
        &archive,
    )?;
    write_atomic(&output.join("selection.json"), selection.as_bytes())?;
    verify_regression_provider_archive(input, output, artifact_id, &selection)?;
    retain_regression_provider_workflow(root, output, &workflow)?;
    Ok("verified exact regression subject provider selection".to_owned())
}

fn verify_regression_provider_archive(
    subject: &Path,
    selection_root: &Path,
    artifact_id: u64,
    selection: &str,
) -> Result<(), String> {
    let selection = parse_json(selection)?;
    let selection = selection.object()?;
    let expected_sha256 = json_member(selection, "providerArchiveSha256")?.string()?;
    let expected_size = json_member(selection, "providerArchiveSize")?.number()?;
    let endpoint = PathBuf::from("repos")
        .join("Portfoligno")
        .join("hell-rs")
        .join("actions")
        .join("artifacts")
        .join(artifact_id.to_string())
        .join("zip");
    let archive_bytes = github_api_bytes(&endpoint)?;
    if archive_bytes.len() as u64 != expected_size
        || sha256_bytes(&archive_bytes).hex() != expected_sha256
    {
        return Err("regression provider archive bytes differ from provider API".to_owned());
    }
    let temporary = create_private_temp_directory("hell-regression-provider-archive")?;
    let archive = temporary.join("artifact.zip");
    let extracted = temporary.join("extracted");
    write_atomic(&archive, &archive_bytes)?;
    extract_external_zip(&archive, &extracted)?;
    let comparison = record_digest(&extracted)? == record_digest(subject)?;
    let cleanup = fs::remove_dir_all(&temporary)
        .map_err(|error| format!("cannot clean regression provider archive: {error}"));
    if !comparison {
        return Err("regression provider archive tree differs from downloaded subject".to_owned());
    }
    cleanup?;
    write_atomic(&selection_root.join("provider-archive.zip"), &archive_bytes)
}

fn github_api_bytes(endpoint: &Path) -> Result<Vec<u8>, String> {
    let token = std::env::var("GITHUB_TOKEN")
        .map_err(|_| "provider archive query requires GITHUB_TOKEN".to_owned())?;
    let response = Command::new("gh")
        .args([
            OsStr::new("api"),
            OsStr::new("--method"),
            OsStr::new("GET"),
            endpoint.as_os_str(),
        ])
        .env("GH_TOKEN", token)
        .env_remove("GITHUB_TOKEN")
        .env_remove("AWS_ACCESS_KEY_ID")
        .env_remove("AWS_SECRET_ACCESS_KEY")
        .env_remove("AWS_SESSION_TOKEN")
        .output()
        .map_err(|error| format!("cannot download provider archive: {error}"))?;
    if !response.status.success() || response.stdout.is_empty() {
        return Err("provider archive query failed or returned empty bytes".to_owned());
    }
    Ok(response.stdout)
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) struct VerifiedCollectionProviderArtifact {
    pub platform: String,
    pub repository_id: u64,
    pub run_id: u64,
    pub run_attempt: u64,
    pub artifact_id: u64,
    pub artifact_name: String,
    pub archive_size: u64,
    pub workflow_ref: String,
    pub event: String,
    pub provider_head_commit: String,
    pub candidate_commit: String,
    pub observed_at: String,
    pub selection_sha256: Digest,
    pub artifact_api_sha256: Digest,
    pub job_api_sha256: Digest,
    pub run_api_sha256: Digest,
    pub workflow_sha256: Digest,
    pub archive_sha256: Digest,
    pub tree_sha256: Digest,
    pub provider_subject_sha256: Digest,
}

const COLLECTION_AUTHORITY_WORKFLOW_PATH: &str = ".github/workflows/collection-authority.yml";
const COLLECTION_AUTHORITY_WORKFLOW_REF: &str =
    "Portfoligno/hell-rs/.github/workflows/collection-authority.yml@refs/heads/main";

pub(crate) fn verify_collection_provider_artifact(
    root: &Path,
    provider_root: &Path,
    copied_shard: &Path,
    platform: &str,
) -> Result<VerifiedCollectionProviderArtifact, String> {
    let configured_repository_id = load_acquisition_policy(root)?
        .repository_id
        .ok_or_else(|| {
            "collection provider repository ID remains REVIEW_REQUIRED in retained policy"
                .to_owned()
        })?
        .parse::<u64>()
        .map_err(|_| "collection configured repository ID is malformed".to_owned())?;
    verify_collection_provider_artifact_with_repository_id(
        root,
        provider_root,
        copied_shard,
        platform,
        configured_repository_id,
    )
}

fn verify_collection_provider_artifact_with_repository_id(
    root: &Path,
    provider_root: &Path,
    copied_shard: &Path,
    platform: &str,
    configured_repository_id: u64,
) -> Result<VerifiedCollectionProviderArtifact, String> {
    let directory = provider_root.join(platform);
    let selection_bytes = read_regular_file(&directory.join("selection.json"))?;
    let selection = parse_json_bytes(&selection_bytes)?;
    let selection = selection.object()?;
    exact_keys(
        selection,
        &[
            "artifact",
            "candidateCommit",
            "canonicalShardRoot",
            "inventoryCount",
            "observedAt",
            "platform",
            "providerArchiveSha256",
            "providerArchiveSize",
            "providerArtifactApiPage",
            "providerArtifactId",
            "providerGhExecutableSha256",
            "providerGhInstallManifestSha256",
            "providerHeadCommit",
            "providerJobApiPage",
            "providerJobId",
            "providerJobName",
            "providerRunAttempt",
            "providerRunId",
            "providerTreeSha256",
            "schemaVersion",
            "workflowPath",
        ],
    )?;
    verify_collection_provider_transport(provider_root, selection)?;
    let facts = collection_selection_facts(selection, platform)?;
    let run_bytes = read_regular_file(&directory.join("provider-selected-run.json"))?;
    let run = parse_json_bytes(&run_bytes)?;
    let repository_id = verify_collection_provider_run(run.object()?, &facts)?;
    if repository_id != configured_repository_id {
        return Err(
            "collection provider repository ID differs from retained trust root".to_owned(),
        );
    }
    verify_collection_provider_workflow(root, &directory, &facts)?;
    let artifact_pages = collection_complete_api_pages(
        &provider_root.join("artifact-api-pages"),
        "artifacts",
        true,
    )?;
    let job_pages =
        collection_complete_api_pages(&provider_root.join("job-api-pages"), "jobs", false)?;
    let artifact = verify_collection_selected_artifact(&directory, &facts, &artifact_pages.pages)?;
    verify_collection_selected_job(&facts, &job_pages.pages)?;
    let archive = directory.join("provider-archive.zip");
    let archive_bytes = read_regular_file(&archive)?;
    if archive_bytes.len() as u64 != facts.archive_size
        || sha256_bytes(&archive_bytes) != facts.archive_sha256
        || json_member(artifact, "size_in_bytes")?.number()? != facts.archive_size
        || json_member(artifact, "digest")?.string()?
            != format!("sha256:{}", facts.archive_sha256.hex())
    {
        return Err("collection provider archive differs from selected API object".to_owned());
    }
    let retained_tree = directory.join("extracted").join(platform);
    verify_collection_provider_archive(
        &archive,
        &retained_tree,
        &facts.tree_sha256.hex(),
        facts.inventory_count,
    )?;
    if record_digest(&retained_tree)? != record_digest(copied_shard)? {
        return Err("collection copied shard differs from authenticated ZIP tree".to_owned());
    }
    let subject = retained_tree.join("collection-evidence/provider-subject.json");
    let subject_sha256 = sha256_file(&subject)
        .map_err(|error| format!("cannot hash collection provider subject: {error}"))?;
    Ok(VerifiedCollectionProviderArtifact {
        platform: platform.to_owned(),
        repository_id,
        run_id: facts.run_id,
        run_attempt: facts.run_attempt,
        artifact_id: facts.artifact_id,
        artifact_name: facts.artifact,
        archive_size: facts.archive_size,
        workflow_ref: COLLECTION_AUTHORITY_WORKFLOW_REF.to_owned(),
        event: json_member(run.object()?, "event")?.string()?.to_owned(),
        provider_head_commit: facts.provider_head_commit,
        candidate_commit: facts.candidate_commit,
        observed_at: facts.observed_at,
        selection_sha256: sha256_bytes(&selection_bytes),
        artifact_api_sha256: artifact_pages.root_sha256,
        job_api_sha256: job_pages.root_sha256,
        run_api_sha256: sha256_bytes(&run_bytes),
        workflow_sha256: sha256_file(&directory.join("provider-workflow.yml"))
            .map_err(|error| format!("cannot hash collection provider workflow: {error}"))?,
        archive_sha256: facts.archive_sha256,
        tree_sha256: facts.tree_sha256,
        provider_subject_sha256: subject_sha256,
    })
}

fn verify_collection_provider_transport(
    provider_root: &Path,
    selection: &BTreeMap<String, JsonValue>,
) -> Result<(), String> {
    let directory = provider_root.join("transport");
    let manifest_path = directory.join("gh-install-manifest.json");
    let manifest_bytes = read_regular_file(&manifest_path)?;
    crate::collection_custody::verify_gh_install_manifest(&manifest_bytes)?;
    if json_member(selection, "providerGhExecutableSha256")?.string()?
        != crate::collection_transport::reviewed_gh_binary_sha256()
        || json_member(selection, "providerGhInstallManifestSha256")?.string()?
            != sha256_bytes(&manifest_bytes).hex()
    {
        return Err("retained provider gh identity differs".to_owned());
    }
    Ok(())
}

struct CollectionSelectionFacts {
    platform: String,
    artifact: String,
    candidate_commit: String,
    provider_head_commit: String,
    run_id: u64,
    run_attempt: u64,
    artifact_id: u64,
    job_id: u64,
    job_name: String,
    artifact_api_page: String,
    job_api_page: String,
    archive_sha256: Digest,
    archive_size: u64,
    tree_sha256: Digest,
    inventory_count: u64,
    observed_at: String,
}

fn collection_selection_facts(
    selection: &BTreeMap<String, JsonValue>,
    platform: &str,
) -> Result<CollectionSelectionFacts, String> {
    if json_member(selection, "schemaVersion")?.number()? != 1
        || json_member(selection, "platform")?.string()? != platform
        || json_member(selection, "canonicalShardRoot")?.string()? != platform
        || json_member(selection, "workflowPath")?.string()? != COLLECTION_AUTHORITY_WORKFLOW_PATH
    {
        return Err("collection provider selection identity is invalid".to_owned());
    }
    let candidate_commit = json_member(selection, "candidateCommit")?.string()?;
    let provider_head_commit = json_member(selection, "providerHeadCommit")?.string()?;
    require_git_sha_text(candidate_commit, "collection candidate commit")?;
    require_git_sha_text(provider_head_commit, "collection provider head")?;
    let run_id = json_member(selection, "providerRunId")?.number()?;
    let run_attempt = json_member(selection, "providerRunAttempt")?.number()?;
    let artifact_id = json_member(selection, "providerArtifactId")?.number()?;
    let job_id = json_member(selection, "providerJobId")?.number()?;
    let archive_size = json_member(selection, "providerArchiveSize")?.number()?;
    let inventory_count = json_member(selection, "inventoryCount")?.number()?;
    if [
        run_id,
        run_attempt,
        artifact_id,
        job_id,
        archive_size,
        inventory_count,
    ]
    .contains(&0)
    {
        return Err("collection provider selection contains a zero identifier/count".to_owned());
    }
    Ok(CollectionSelectionFacts {
        platform: platform.to_owned(),
        artifact: json_member(selection, "artifact")?.string()?.to_owned(),
        candidate_commit: candidate_commit.to_owned(),
        provider_head_commit: provider_head_commit.to_owned(),
        run_id,
        run_attempt,
        artifact_id,
        job_id,
        job_name: json_member(selection, "providerJobName")?
            .string()?
            .to_owned(),
        artifact_api_page: json_member(selection, "providerArtifactApiPage")?
            .string()?
            .to_owned(),
        job_api_page: json_member(selection, "providerJobApiPage")?
            .string()?
            .to_owned(),
        archive_sha256: Digest::from_hex(
            json_member(selection, "providerArchiveSha256")?.string()?,
        )
        .map_err(str::to_owned)?,
        archive_size,
        tree_sha256: Digest::from_hex(json_member(selection, "providerTreeSha256")?.string()?)
            .map_err(str::to_owned)?,
        inventory_count,
        observed_at: json_member(selection, "observedAt")?.string()?.to_owned(),
    })
}

fn verify_collection_provider_run(
    run: &BTreeMap<String, JsonValue>,
    facts: &CollectionSelectionFacts,
) -> Result<u64, String> {
    let repository = json_member(run, "repository")?.object()?;
    let repository_id = json_member(repository, "id")?.number()?;
    let event = json_member(run, "event")?.string()?;
    if repository_id == 0
        || json_member(repository, "full_name")?.string()? != "Portfoligno/hell-rs"
        || json_member(run, "id")?.number()? != facts.run_id
        || json_member(run, "run_attempt")?.number()? != facts.run_attempt
        || json_member(run, "head_sha")?.string()? != facts.provider_head_commit
        || json_member(run, "path")?.string()? != COLLECTION_AUTHORITY_WORKFLOW_PATH
        || json_member(run, "head_branch")?.string()? != "main"
        || event != "workflow_dispatch"
        || !matches!(
            json_member(run, "status")?.string()?,
            "in_progress" | "completed"
        )
    {
        return Err("collection provider run differs from exact campaign root".to_owned());
    }
    Ok(repository_id)
}

fn verify_collection_provider_workflow(
    root: &Path,
    directory: &Path,
    facts: &CollectionSelectionFacts,
) -> Result<(), String> {
    let retained = read_regular_file(&directory.join("provider-workflow.yml"))?;
    let committed = git_output_bytes(
        root,
        &[
            "show",
            &format!(
                "{}:{COLLECTION_AUTHORITY_WORKFLOW_PATH}",
                facts.provider_head_commit
            ),
        ],
    )?;
    if retained != committed || !retained.starts_with(b"name: Collection Authority\n") {
        return Err("collection provider workflow differs from exact run head".to_owned());
    }
    Ok(())
}

struct CollectionApiPages {
    pages: BTreeMap<String, JsonValue>,
    root_sha256: Digest,
}

fn collection_complete_api_pages(
    directory: &Path,
    member: &str,
    descending_ids: bool,
) -> Result<CollectionApiPages, String> {
    let mut paths = fs::read_dir(directory)
        .map_err(|error| format!("cannot enumerate collection provider API pages: {error}"))?
        .collect::<Result<Vec<_>, _>>()
        .map_err(|error| format!("cannot enumerate collection provider API pages: {error}"))?;
    paths.sort_by_key(std::fs::DirEntry::file_name);
    if paths.is_empty() || paths.len() > 100 {
        return Err("collection provider pagination page count is outside its bound".to_owned());
    }
    let mut output = BTreeMap::new();
    let mut expected_total = None;
    let mut observed = 0_u64;
    let mut identifiers = BTreeSet::new();
    let mut previous_identifier = None;
    let mut root_bytes = b"hell-collection-provider-api-pages-v1\0".to_vec();
    root_bytes.extend_from_slice(&(member.len() as u64).to_be_bytes());
    root_bytes.extend_from_slice(member.as_bytes());
    for (index, entry) in paths.into_iter().enumerate() {
        if expected_total.is_some_and(|total| observed == total) {
            return Err("collection provider pagination has a trailing empty page".to_owned());
        }
        let expected_name = format!("page-{:04}.json", index + 1);
        if entry.file_name() != OsStr::new(&expected_name) {
            return Err(
                "collection provider API pages are missing, extra, or unordered".to_owned(),
            );
        }
        let page_bytes = read_regular_file(&entry.path())?;
        let value = parse_json_bytes(&page_bytes)?;
        let object = value.object()?;
        let total = json_member(object, "total_count")?.number()?;
        if expected_total
            .replace(total)
            .is_some_and(|prior| prior != total)
        {
            return Err("collection provider pagination total drifts by page".to_owned());
        }
        let values = json_member(object, member)?.array()?;
        let remaining = total.saturating_sub(observed);
        if values.len() as u64 != remaining.min(100) {
            return Err("collection provider API page length is not exact".to_owned());
        }
        observed = observed.saturating_add(values.len() as u64);
        for value in values {
            let id = json_member(value.object()?, "id")?.number()?;
            if id == 0 || !identifiers.insert(id) {
                return Err("collection provider API pages duplicate an identifier".to_owned());
            }
            if descending_ids && previous_identifier.is_some_and(|previous| previous <= id) {
                return Err(
                    "collection provider artifact IDs are not strictly descending".to_owned(),
                );
            }
            previous_identifier = Some(id);
        }
        root_bytes.extend_from_slice(&(expected_name.len() as u64).to_be_bytes());
        root_bytes.extend_from_slice(expected_name.as_bytes());
        root_bytes.extend_from_slice(sha256_bytes(&page_bytes).hex().as_bytes());
        output.insert(
            format!(
                "../{}/{}",
                directory
                    .file_name()
                    .and_then(OsStr::to_str)
                    .unwrap_or_default(),
                expected_name
            ),
            value,
        );
    }
    let total = expected_total.unwrap_or_default();
    let exact_pages = usize::try_from(total.div_ceil(100)).unwrap_or(usize::MAX);
    if total == 0 || total != observed || output.len() != exact_pages {
        return Err("collection provider API pages are incomplete".to_owned());
    }
    Ok(CollectionApiPages {
        pages: output,
        root_sha256: sha256_bytes(&root_bytes),
    })
}

fn verify_collection_selected_artifact<'a>(
    directory: &Path,
    facts: &CollectionSelectionFacts,
    pages: &'a BTreeMap<String, JsonValue>,
) -> Result<&'a BTreeMap<String, JsonValue>, String> {
    let page = pages
        .get(&facts.artifact_api_page)
        .ok_or_else(|| "collection selected artifact page is not retained".to_owned())?;
    let matches = json_member(page.object()?, "artifacts")?
        .array()?
        .iter()
        .filter(|value| {
            value
                .object()
                .ok()
                .and_then(|object| json_member(object, "id").ok())
                .and_then(|value| value.number().ok())
                == Some(facts.artifact_id)
        })
        .collect::<Vec<_>>();
    let [selected] = matches.as_slice() else {
        return Err("collection selected artifact is not unique on retained page".to_owned());
    };
    let selected = selected.object()?;
    let retained = parse_json_bytes(&read_regular_file(
        &directory.join("provider-selected-artifact.json"),
    )?)?;
    if retained.object()? != selected {
        return Err("collection selected artifact copy differs from complete API page".to_owned());
    }
    let workflow_run = json_member(selected, "workflow_run")?.object()?;
    let expected_name = format!(
        "collection-authority-{}-{}-{}",
        facts.platform, facts.run_id, facts.run_attempt
    );
    let name_count = pages
        .values()
        .filter_map(|page| {
            json_member(page.object().ok()?, "artifacts")
                .ok()?
                .array()
                .ok()
        })
        .flatten()
        .filter(|value| {
            value
                .object()
                .ok()
                .and_then(|object| json_member(object, "name").ok())
                .and_then(|value| value.string().ok())
                == Some(expected_name.as_str())
        })
        .count();
    let created = json_member(selected, "created_at")?.string()?;
    let expires = json_member(selected, "expires_at")?.string()?;
    validate_utc_timestamp(created)?;
    validate_utc_timestamp(&facts.observed_at)?;
    validate_utc_timestamp(expires)?;
    let current = crate::custody_ops::current_utc_timestamp()?;
    let expected_url = format!(
        "https://api.github.com/repos/Portfoligno/hell-rs/actions/artifacts/{}/zip",
        facts.artifact_id
    );
    if facts.artifact != expected_name
        || name_count != 1
        || json_member(selected, "name")?.string()? != expected_name
        || json_member(workflow_run, "id")?.number()? != facts.run_id
        || json_member(workflow_run, "head_sha")?.string()? != facts.provider_head_commit
        || json_member(selected, "archive_download_url")?.string()? != expected_url
        || utc_timestamp_seconds(created)? >= utc_timestamp_seconds(&facts.observed_at)?
        || utc_timestamp_seconds(&facts.observed_at)? >= utc_timestamp_seconds(expires)?
        || utc_timestamp_seconds(&facts.observed_at)? > utc_timestamp_seconds(&current)?
        || json_member(selected, "expired")?.boolean()?
    {
        return Err("collection selected artifact identity is invalid".to_owned());
    }
    Ok(selected)
}

fn verify_collection_selected_job(
    facts: &CollectionSelectionFacts,
    pages: &BTreeMap<String, JsonValue>,
) -> Result<(), String> {
    let expected_name = match facts.platform.as_str() {
        "linux-amd64" => "Collection authority / Linux amd64",
        "macos-arm64" => "Collection authority / macOS arm64",
        "windows-amd64" => "Collection authority / Windows amd64",
        _ => return Err("collection provider platform is unknown".to_owned()),
    };
    let page = pages
        .get(&facts.job_api_page)
        .ok_or_else(|| "collection selected job page is not retained".to_owned())?;
    let matches = json_member(page.object()?, "jobs")?
        .array()?
        .iter()
        .filter(|value| {
            value
                .object()
                .ok()
                .and_then(|object| json_member(object, "id").ok())
                .and_then(|value| value.number().ok())
                == Some(facts.job_id)
        })
        .collect::<Vec<_>>();
    let name_count = pages
        .values()
        .filter_map(|page| json_member(page.object().ok()?, "jobs").ok()?.array().ok())
        .flatten()
        .filter(|value| {
            value
                .object()
                .ok()
                .and_then(|object| json_member(object, "name").ok())
                .and_then(|value| value.string().ok())
                == Some(expected_name)
        })
        .count();
    let [job] = matches.as_slice() else {
        return Err("collection selected producer job is not unique".to_owned());
    };
    let job = job.object()?;
    if name_count != 1
        || facts.job_name != expected_name
        || json_member(job, "name")?.string()? != expected_name
        || json_member(job, "status")?.string()? != "completed"
        || json_member(job, "conclusion")?.string()? != "success"
        || json_member(job, "run_id")?.number()? != facts.run_id
        || json_member(job, "run_attempt")?.number()? != facts.run_attempt
    {
        return Err("collection selected producer job identity is invalid".to_owned());
    }
    Ok(())
}

fn reverify_regression_provider_selection(
    root: &Path,
    subject: &Path,
    selection_root: &Path,
    candidate_commit: &str,
    expected_workflow: &str,
) -> Result<String, String> {
    let retained_run = parse_json(&read_text(
        &selection_root.join("provider-selected-run.json"),
    )?)?;
    let provider_head = json_member(retained_run.object()?, "head_sha")?.string()?;
    reverify_provider_selection_with_distinct_head(
        root,
        subject,
        selection_root,
        candidate_commit,
        provider_head,
        expected_workflow,
    )
}

fn reverify_provider_selection_with_distinct_head(
    root: &Path,
    subject: &Path,
    selection_root: &Path,
    active_candidate: &str,
    provider_head: &str,
    expected_workflow: &str,
) -> Result<String, String> {
    let committed_workflow = git_output_bytes(
        root,
        &["show", &format!("{provider_head}:{expected_workflow}")],
    )?;
    reverify_provider_selection_with_workflow_bytes(
        subject,
        selection_root,
        active_candidate,
        provider_head,
        expected_workflow,
        &committed_workflow,
    )
}

fn reverify_provider_selection_with_workflow_bytes(
    subject: &Path,
    selection_root: &Path,
    active_candidate: &str,
    provider_head: &str,
    expected_workflow: &str,
    committed_workflow: &[u8],
) -> Result<String, String> {
    let retained = read_text(&selection_root.join("selection.json"))?;
    let selection = parse_json(&retained)?;
    let selection = selection.object()?;
    exact_keys(
        selection,
        &[
            "artifact",
            "candidateCommit",
            "directorySha256",
            "event",
            "providerArchiveSha256",
            "providerArchiveSize",
            "providerArchiveUrl",
            "providerArtifactApiPath",
            "providerArtifactApiSha256",
            "providerArtifactId",
            "providerCreatedAt",
            "providerExpiresAt",
            "providerRunApiPath",
            "providerRunApiSha256",
            "providerRunAttempt",
            "providerRunId",
            "repositoryId",
            "schemaVersion",
            "selectionState",
            "workflowBlobSha256",
            "workflowPath",
        ],
    )?;
    if json_member(selection, "schemaVersion")?.number()? != 1
        || json_member(selection, "selectionState")?.string()? != "exact-provider-object"
        || json_member(selection, "candidateCommit")?.string()? != active_candidate
    {
        return Err("regression provider selection state is invalid".to_owned());
    }
    verify_retained_regression_provider_selection(
        subject,
        selection_root,
        selection,
        provider_head,
        expected_workflow,
        committed_workflow,
    )?;
    Ok(sha256_bytes(retained.as_bytes()).hex())
}

fn require_regression_artifact_class(
    selection_root: &Path,
    expected_prefix: &str,
) -> Result<(), String> {
    let selection = parse_json(&read_text(&selection_root.join("selection.json"))?)?;
    let artifact = json_member(selection.object()?, "artifact")?.string()?;
    if !artifact.starts_with(expected_prefix) || artifact.len() == expected_prefix.len() {
        return Err(format!(
            "regression provider artifact is not in required {expected_prefix} class"
        ));
    }
    Ok(())
}

fn verify_retained_regression_provider_selection(
    subject: &Path,
    selection_root: &Path,
    selection: &BTreeMap<String, JsonValue>,
    provider_head: &str,
    expected_workflow: &str,
    committed_workflow: &[u8],
) -> Result<(), String> {
    verify_retained_regression_provider_workflow(
        selection_root,
        selection,
        expected_workflow,
        committed_workflow,
    )?;
    let artifact_bytes =
        read_regular_file(&selection_root.join("provider-selected-artifact.json"))?;
    let run_bytes = read_regular_file(&selection_root.join("provider-selected-run.json"))?;
    if sha256_bytes(&artifact_bytes).hex()
        != json_member(selection, "providerArtifactApiSha256")?.string()?
        || sha256_bytes(&run_bytes).hex()
            != json_member(selection, "providerRunApiSha256")?.string()?
    {
        return Err("retained regression provider API bytes differ from selection".to_owned());
    }
    let artifact = parse_json_bytes(&artifact_bytes)?;
    let run = parse_json_bytes(&run_bytes)?;
    verify_retained_regression_provider_api_with_head(
        selection,
        artifact.object()?,
        run.object()?,
        provider_head,
    )?;
    verify_retained_regression_archive(subject, selection_root, selection)
}

fn parse_json_bytes(bytes: &[u8]) -> Result<JsonValue, String> {
    let text =
        std::str::from_utf8(bytes).map_err(|_| "retained provider JSON is not UTF-8".to_owned())?;
    parse_json(text)
}

#[cfg(test)]
fn verify_retained_regression_provider_api(
    selection: &BTreeMap<String, JsonValue>,
    artifact: &BTreeMap<String, JsonValue>,
    run: &BTreeMap<String, JsonValue>,
) -> Result<(), String> {
    let provider_head = json_member(selection, "candidateCommit")?.string()?;
    verify_retained_regression_provider_api_with_head(selection, artifact, run, provider_head)
}

fn verify_retained_regression_provider_api_with_head(
    selection: &BTreeMap<String, JsonValue>,
    artifact: &BTreeMap<String, JsonValue>,
    run: &BTreeMap<String, JsonValue>,
    provider_head: &str,
) -> Result<(), String> {
    if json_member(selection, "providerArtifactApiPath")?.string()?
        != "provider-selected-artifact.json"
        || json_member(selection, "providerRunApiPath")?.string()? != "provider-selected-run.json"
    {
        return Err("retained regression provider API paths are not canonical".to_owned());
    }
    let artifact_run = json_member(artifact, "workflow_run")?.object()?;
    let repository = json_member(run, "repository")?.object()?;
    let repository_id = json_member(selection, "repositoryId")?
        .string()?
        .parse::<u64>()
        .ok()
        .filter(|value| *value != 0)
        .ok_or_else(|| "retained regression repository ID is not positive".to_owned())?;
    let archive_digest = json_member(artifact, "digest")?
        .string()?
        .strip_prefix("sha256:")
        .ok_or_else(|| "retained regression artifact digest is not SHA-256".to_owned())?;
    let artifact_id = json_member(selection, "providerArtifactId")?.number()?;
    let run_id = json_member(selection, "providerRunId")?.number()?;
    let run_attempt = json_member(selection, "providerRunAttempt")?.number()?;
    let archive_size = json_member(selection, "providerArchiveSize")?.number()?;
    if artifact_id == 0 || run_id == 0 || run_attempt == 0 || archive_size == 0 {
        return Err("retained regression provider identifiers are not positive".to_owned());
    }
    if json_member(artifact, "id")?.number()?
        != json_member(selection, "providerArtifactId")?.number()?
        || json_member(artifact, "name")?.string()?
            != json_member(selection, "artifact")?.string()?
        || json_member(artifact_run, "id")?.number()?
            != json_member(selection, "providerRunId")?.number()?
        || json_member(artifact, "size_in_bytes")?.number()?
            != json_member(selection, "providerArchiveSize")?.number()?
        || archive_digest != json_member(selection, "providerArchiveSha256")?.string()?
        || json_member(run, "id")?.number()? != json_member(selection, "providerRunId")?.number()?
        || json_member(run, "run_attempt")?.number()?
            != json_member(selection, "providerRunAttempt")?.number()?
        || json_member(run, "head_sha")?.string()? != provider_head
        || json_member(run, "event")?.string()? != json_member(selection, "event")?.string()?
        || json_member(repository, "id")?.number()? != repository_id
        || json_member(repository, "full_name")?.string()? != "Portfoligno/hell-rs"
        || json_member(artifact, "expired")?.boolean()?
    {
        return Err("retained regression provider API facts differ from selection".to_owned());
    }
    for (field, selected) in [
        ("created_at", "providerCreatedAt"),
        ("expires_at", "providerExpiresAt"),
        ("archive_download_url", "providerArchiveUrl"),
    ] {
        if json_member(artifact, field)?.string()? != json_member(selection, selected)?.string()? {
            return Err("retained regression artifact metadata differs from selection".to_owned());
        }
    }
    let created = json_member(selection, "providerCreatedAt")?.string()?;
    let expires = json_member(selection, "providerExpiresAt")?.string()?;
    validate_utc_timestamp(created)?;
    validate_utc_timestamp(expires)?;
    if utc_timestamp_seconds(created)? >= utc_timestamp_seconds(expires)? {
        return Err("retained regression artifact lifetime is invalid".to_owned());
    }
    let expected_url = format!(
        "https://api.github.com/repos/Portfoligno/hell-rs/actions/artifacts/{artifact_id}/zip"
    );
    if json_member(selection, "providerArchiveUrl")?.string()? != expected_url {
        return Err("retained regression artifact URL is not repository-confined".to_owned());
    }
    Ok(())
}

fn verify_retained_regression_archive(
    subject: &Path,
    selection_root: &Path,
    selection: &BTreeMap<String, JsonValue>,
) -> Result<(), String> {
    let archive_bytes = read_regular_file(&selection_root.join("provider-archive.zip"))?;
    if archive_bytes.len() as u64 != json_member(selection, "providerArchiveSize")?.number()?
        || sha256_bytes(&archive_bytes).hex()
            != json_member(selection, "providerArchiveSha256")?.string()?
        || record_digest(subject)? != json_member(selection, "directorySha256")?.string()?
    {
        return Err("retained regression archive identity differs from selection".to_owned());
    }
    let temporary = create_private_temp_directory("hell-regression-offline-archive")?;
    let archive = temporary.join("artifact.zip");
    let extracted = temporary.join("extracted");
    write_atomic(&archive, &archive_bytes)?;
    extract_external_zip(&archive, &extracted)?;
    let equal = record_digest(&extracted)? == record_digest(subject)?;
    fs::remove_dir_all(&temporary)
        .map_err(|error| format!("cannot clean retained regression archive: {error}"))?;
    if !equal {
        return Err("retained regression archive tree differs from subject".to_owned());
    }
    Ok(())
}

fn verify_retained_regression_provider_workflow(
    selection_root: &Path,
    selection: &BTreeMap<String, JsonValue>,
    expected_workflow: &str,
    committed_workflow: &[u8],
) -> Result<(), String> {
    let workflow = json_member(selection, "workflowPath")?.string()?;
    let selected_event = json_member(selection, "event")?.string()?;
    let accepted_event = match expected_workflow {
        ".github/workflows/nightly.yml" => selected_event == "schedule",
        ".github/workflows/regression-subject.yml" => {
            matches!(selected_event, "workflow_dispatch" | "workflow_run")
        }
        _ => selected_event == "workflow_dispatch",
    };
    if workflow != expected_workflow || !accepted_event {
        return Err(
            "regression subject was not emitted by the trusted producer workflow".to_owned(),
        );
    }
    let run = parse_json(&read_text(
        &selection_root.join("provider-selected-run.json"),
    )?)?;
    let workflow_ref =
        provider_run_workflow_ref(json_member(run.object()?, "path")?.string()?, workflow)?;
    if workflow_ref != "refs/heads/main" {
        return Err("regression subject producer did not run from exact main ref".to_owned());
    }
    let expected = json_member(selection, "workflowBlobSha256")?.string()?;
    let retained = selection_root.join("provider-workflow.yml");
    let retained_bytes = read_regular_file(&retained)?;
    if sha256_bytes(&retained_bytes).hex() != expected {
        return Err("retained regression producer workflow differs from exact run head".to_owned());
    }
    if committed_workflow != retained_bytes {
        return Err("retained regression workflow differs from the committed run head".to_owned());
    }
    Ok(())
}

fn regression_prepare(root: &Path, options: &Options) -> Result<String, String> {
    if options.proposal.is_some() || options.policy.is_some() {
        return Err("regression-import prepare does not accept review inputs".to_owned());
    }
    let output = required_path(&options.output, "regression-import requires --output")?;
    let paths = regression_subject_paths(options, output)?;
    let preparation = prepare_regression_data(root, options, &paths)?;
    write_regression_package(
        root,
        output,
        regression_issue(options)?,
        regression_category(options)?,
        &preparation,
    )?;
    Ok(format!(
        "wrote minimized, replayable regression proposal package {}",
        output.display()
    ))
}

struct RegressionSubjectPaths {
    program: PathBuf,
    subject_root: PathBuf,
    oracle: PathBuf,
    candidate: PathBuf,
    claim_coverage: PathBuf,
    selection_root: PathBuf,
}

fn regression_subject_paths(
    options: &Options,
    output: &Path,
) -> Result<RegressionSubjectPaths, String> {
    let input = required_path(&options.program, "regression-import requires --program")?;
    let canonical_input = fs::canonicalize(input).map_err(|error| {
        format!(
            "cannot resolve regression program {}: {error}",
            input.display()
        )
    })?;
    let output_name = output
        .file_name()
        .ok_or_else(|| "regression-import output package directory has no filename".to_owned())?;
    let output_parent = fs::canonicalize(output.parent().unwrap_or_else(|| Path::new(".")))
        .map_err(|error| format!("cannot resolve regression output directory: {error}"))?;
    if canonical_input == output_parent.join(output_name) {
        return Err("regression-import output must not replace the source program".to_owned());
    }
    if output.exists() {
        return Err("regression-import output package already exists".to_owned());
    }
    let subject_root = input
        .parent()
        .ok_or_else(|| "regression program has no provider subject root".to_owned())?;
    let oracle_path = required_path(
        &options.from,
        "regression-import prepare requires --from oracle executable",
    )?;
    let candidate_path = required_path(
        &options.to,
        "regression-import prepare requires --to candidate executable",
    )?;
    let claim_coverage = required_path(
        &options.input,
        "regression-import prepare requires --input finalized claim coverage",
    )?;
    for path in [oracle_path, candidate_path, claim_coverage] {
        if !fs::canonicalize(path)
            .map_err(|error| format!("cannot resolve regression subject path: {error}"))?
            .starts_with(
                fs::canonicalize(subject_root)
                    .map_err(|error| format!("cannot resolve regression subject root: {error}"))?,
            )
        {
            return Err("regression subject component escapes provider artifact".to_owned());
        }
    }
    for (path, expected) in [
        (input, "program.hell"),
        (oracle_path, "oracle"),
        (candidate_path, "candidate"),
        (claim_coverage, "claim-coverage.json"),
    ] {
        if path.strip_prefix(subject_root) != Ok(Path::new(expected)) {
            return Err("regression provider subject layout is not canonical".to_owned());
        }
    }
    let selection_root =
        PathBuf::from(options.artifact.as_deref().ok_or_else(|| {
            "regression prepare requires --artifact provider selection".to_owned()
        })?);
    Ok(RegressionSubjectPaths {
        program: input.to_path_buf(),
        subject_root: subject_root.to_path_buf(),
        oracle: oracle_path.to_path_buf(),
        candidate: candidate_path.to_path_buf(),
        claim_coverage: claim_coverage.to_path_buf(),
        selection_root,
    })
}

fn prepare_regression_data(
    root: &Path,
    options: &Options,
    paths: &RegressionSubjectPaths,
) -> Result<RegressionPreparation, String> {
    let source = read_text(&paths.program)?;
    if source.is_empty() || !source.ends_with('\n') {
        return Err("regression source is not canonical nonempty text".to_owned());
    }
    let template = regression_template_case(options)?;
    let case_id = format!(
        "regression-{}",
        &sha256_bytes(source.as_bytes()).hex()[..16]
    );
    let execution_case = regression_trace_case(&template, &case_id, &source)?;
    let RegressionIdentityAuthority {
        oracle,
        candidate,
        candidate_commit,
        candidate_build_info_sha256,
        assurance_epoch,
    } = regression_preparation_identities(paths)?;
    reverify_regression_provider_selection(
        root,
        &paths.subject_root,
        &paths.selection_root,
        &candidate_commit,
        ".github/workflows/regression-subject.yml",
    )?;
    require_regression_artifact_class(&paths.selection_root, "regression-subject-")?;
    verify_regression_subject_source_chain(
        root,
        &paths.subject_root,
        &candidate_commit,
        template.id.as_ref(),
        true,
    )?;
    verify_scheduled_regression_plan(paths, options, &template, &execution_case)?;
    verify_bound_details(
        &paths.claim_coverage,
        "claim-coverage",
        &candidate_commit,
        &assurance_epoch.hex(),
    )?;
    let platform = regression_host_platform()?;
    let (expected_oracle, expected_candidate) =
        regression_coverage_executable_identities(&paths.claim_coverage, &template, platform)?;
    if oracle.sha256 != expected_oracle || candidate.sha256 != expected_candidate {
        return Err(
            "regression executables differ from finalized current claim evidence".to_owned(),
        );
    }
    let minimized = minimize_regression(&oracle, &candidate, &execution_case)?;
    let case = regression_trace_case(&template, &case_id, &minimized.source)?;
    let current_claim_root = retained_evidence_root(&paths.claim_coverage)?.to_path_buf();
    let current_claim_relative = paths
        .claim_coverage
        .strip_prefix(&current_claim_root)
        .map_err(|_| "claim coverage is outside its retained evidence root".to_owned())?
        .to_path_buf();
    Ok(RegressionPreparation {
        template,
        case,
        source,
        minimized,
        oracle,
        candidate,
        candidate_commit,
        candidate_build_info_sha256,
        assurance_epoch,
        current_claim_root,
        current_claim_relative,
        provider_subject_root: paths.subject_root.clone(),
        provider_selection_root: paths.selection_root.clone(),
    })
}

struct RegressionIdentityAuthority {
    oracle: ExecutableIdentity,
    candidate: ExecutableIdentity,
    candidate_commit: String,
    candidate_build_info_sha256: Digest,
    assurance_epoch: Digest,
}

fn regression_preparation_identities(
    paths: &RegressionSubjectPaths,
) -> Result<RegressionIdentityAuthority, String> {
    let coverage = parse_json(&read_text(&paths.claim_coverage)?)?;
    let coverage = coverage.object()?;
    let candidate_commit = json_member(coverage, "candidateSourceCommit")?
        .string()?
        .to_owned();
    require_git_sha_text(&candidate_commit, "regression subject candidate")?;
    let assurance_epoch =
        Digest::from_hex(json_member(coverage, "assuranceEpochSha256")?.string()?)
            .map_err(|_| "regression subject assurance epoch is invalid".to_owned())?;
    let mut oracle = verify_executable(
        &paths.oracle,
        ExecutableRole::Oracle,
        None,
        hell_builtins::LANGUAGE_VERSION,
    )
    .map_err(|error| format!("cannot verify regression oracle: {error}"))?;
    let mut candidate = verify_executable(
        &paths.candidate,
        ExecutableRole::Candidate,
        None,
        hell_builtins::LANGUAGE_VERSION,
    )
    .map_err(|error| format!("cannot verify regression candidate: {error}"))?;
    let candidate_build_info_sha256 =
        regression_candidate_build_info(&candidate, &candidate_commit)?;
    oracle.assurance_epoch_sha256 = Some(assurance_epoch);
    candidate.assurance_epoch_sha256 = Some(assurance_epoch);
    Ok(RegressionIdentityAuthority {
        oracle,
        candidate,
        candidate_commit,
        candidate_build_info_sha256,
        assurance_epoch,
    })
}

fn verify_scheduled_regression_plan(
    paths: &RegressionSubjectPaths,
    options: &Options,
    template: &DifferentialCase,
    execution_case: &DifferentialCase,
) -> Result<(), String> {
    let generated = parse_json(&read_text(
        &paths.subject_root.join("generated-source.json"),
    )?)?;
    if let Ok(expected_case) = std::env::var("REGRESSION_GENERATED_CASE")
        && !expected_case.is_empty()
        && (!hell_builtins::validate_case_id(&expected_case)
            || json_member(generated.object()?, "caseId")?.string()? != expected_case)
    {
        return Err("regression dispatch generated case differs from retained source".to_owned());
    }
    let scheduled = json_member(generated.object()?, "scheduledExploration")?.object()?;
    if json_member(scheduled, "automationDisposition")?.string()?
        != "ready-for-protected-regression-review"
        || json_member(scheduled, "templateCaseId")?.string()? != template.id.as_ref()
        || json_member(scheduled, "compatibilityCategory")?.string()?
            != regression_category(options)?
    {
        return Err("regression dispatch differs from retained scheduled review plan".to_owned());
    }
    if hell_testkit::case_execution_input_sha256(execution_case)
        .map_err(|error| format!("cannot derive regression execution input: {error}"))?
        .hex()
        != json_member(scheduled, "executionInputSha256")?.string()?
    {
        return Err(
            "regression minimized execution input differs from scheduled evidence".to_owned(),
        );
    }
    Ok(())
}

fn regression_trace_case(
    template: &DifferentialCase,
    case_id: &str,
    source: &str,
) -> Result<DifferentialCase, String> {
    let mut case = template.clone();
    let descriptor = case
        .claim_evidence
        .as_mut()
        .ok_or_else(|| "regression template has no trace-enabling descriptor".to_owned())?;
    case.id = case_id.into();
    case.source = source.into();
    descriptor.source_sha256 = sha256_bytes(source.as_bytes());
    descriptor.review_statement =
        "template-scoped unprivileged trace-enablement only; never claim evidence".into();
    Ok(case)
}

fn verify_regression_subject_source_chain(
    root: &Path,
    subject: &Path,
    candidate_commit: &str,
    expected_template: &str,
    probe_executables: bool,
) -> Result<(), String> {
    let generated_text = read_text(&subject.join("generated-source.json"))?;
    let generated = parse_json(&generated_text)?;
    let generated = generated.object()?;
    exact_keys(
        generated,
        &[
            "astSha256",
            "bundleSha256",
            "candidateExecutableSha256",
            "caseId",
            "executionInputSha256",
            "fingerprintSha256",
            "oracleExecutableSha256",
            "proposalSha256",
            "resultType",
            "schemaVersion",
            "seed",
            "shrinkPlan",
            "scheduledExploration",
            "sourceSha256",
            "templateCaseId",
        ],
    )?;
    if json_member(generated, "schemaVersion")?.number()? != 1 {
        return Err("generated regression source record schema is invalid".to_owned());
    }
    let case_id = json_member(generated, "caseId")?.string()?;
    if json_member(generated, "templateCaseId")?.string()? != expected_template
        || !committed_differential_cases()
            .iter()
            .any(|case| case.id.as_ref() == expected_template)
    {
        return Err(
            "generated regression template identity differs from the reviewed subject".to_owned(),
        );
    }
    if !hell_builtins::validate_case_id(case_id) || !case_id.starts_with("generated-") {
        return Err("generated regression source record case is invalid".to_owned());
    }
    let nightly = subject.join("sources").join("program");
    let nightly_source = nightly
        .join("mismatches")
        .join("proposed-regressions")
        .join(case_id);
    let nightly_exploration = nightly.join("regression-exploration").join(case_id);
    let mut recomputed = if probe_executables {
        verify_generated_regression_source(&nightly, case_id, &nightly_source)?
    } else {
        verify_generated_regression_source_structural(&nightly, case_id, &nightly_source)?
    };
    let scheduled = verify_scheduled_generated_exploration(&nightly, case_id, &recomputed)?;
    recomputed.object_mut()?.insert(
        "templateCaseId".to_owned(),
        JsonValue::String(expected_template.to_owned()),
    );
    recomputed
        .object_mut()?
        .insert("scheduledExploration".to_owned(), scheduled);
    if canonical_json_bytes(&recomputed)?
        != canonical_json_bytes(&JsonValue::Object(generated.clone()))?
    {
        return Err(
            "generated regression source record differs from retained nightly evidence".to_owned(),
        );
    }
    let evidence = subject.join("sources").join("evidence");
    let public = subject.join("sources").join("public");
    verify_regression_subject_provider_chain(
        root,
        subject,
        candidate_commit,
        &nightly,
        &evidence,
        &public,
    )?;
    for (retained, canonical) in [
        (
            nightly_exploration.join("minimized.hell"),
            subject.join("program.hell"),
        ),
        (nightly_exploration.join("oracle"), subject.join("oracle")),
        (
            nightly_exploration.join("candidate"),
            subject.join("candidate"),
        ),
        (
            evidence.join("coverage").join("claim-coverage.json"),
            subject.join("claim-coverage.json"),
        ),
    ] {
        if record_digest(&retained)? != record_digest(&canonical)? {
            return Err("regression canonical subject differs from its retained source".to_owned());
        }
    }
    Ok(())
}

fn verify_regression_subject_provider_chain(
    root: &Path,
    subject: &Path,
    candidate_commit: &str,
    nightly: &Path,
    evidence: &Path,
    public: &Path,
) -> Result<(), String> {
    let selections = subject.join("source-selection");
    for (source, selection, workflow) in [
        (nightly, "program", ".github/workflows/nightly.yml"),
        (
            evidence,
            "evidence",
            ".github/workflows/promotion-evidence-review.yml",
        ),
        (
            public,
            "public",
            ".github/workflows/promotion-surveillance.yml",
        ),
    ] {
        reverify_regression_provider_selection(
            root,
            source,
            &selections.join(selection),
            candidate_commit,
            workflow,
        )?;
        let expected_prefix = match selection {
            "program" => "nightly-",
            "evidence" => "promotion-review-ready-evidence",
            "public" => "promotion-public-current-state-",
            _ => unreachable!(),
        };
        require_regression_artifact_class(&selections.join(selection), expected_prefix)?;
    }
    let public_selection = parse_json(&read_text(
        &selections.join("public").join("selection.json"),
    )?)?;
    if !json_member(public_selection.object()?, "artifact")?
        .string()?
        .starts_with("promotion-public-current-state-")
    {
        return Err(
            "regression public source is not the exact published current-state class".to_owned(),
        );
    }
    Ok(())
}

fn regression_host_platform() -> Result<&'static str, String> {
    match (std::env::consts::OS, std::env::consts::ARCH) {
        ("linux", "x86_64") => Ok("linux-amd64"),
        ("macos", "aarch64") => Ok("macos-arm64"),
        ("windows", "x86_64") => Ok("windows-amd64"),
        _ => Err("regression preparation host is not a reviewed native platform".to_owned()),
    }
}

fn regression_coverage_executable_identities(
    coverage: &Path,
    template: &DifferentialCase,
    platform: &str,
) -> Result<(Digest, Digest), String> {
    let document = parse_json(&read_text(coverage)?)?;
    let cells = json_member(document.object()?, "cells")?.array()?;
    let descriptor = template
        .claim_evidence
        .as_ref()
        .ok_or_else(|| "regression template has no claim descriptor".to_owned())?;
    let mut identities = BTreeSet::new();
    for target in &descriptor.semantic_targets {
        let Some(cell) = cells.iter().find(|cell| {
            let Ok(cell) = cell.object() else {
                return false;
            };
            json_member(cell, "builtin").and_then(JsonValue::string) == Ok(target.builtin.as_ref())
                && json_member(cell, "dimension").and_then(JsonValue::string)
                    == Ok(target.dimension.as_str())
                && json_member(cell, "platform").and_then(JsonValue::string) == Ok(platform)
        }) else {
            continue;
        };
        let cell = cell.object()?;
        for reference in json_member(cell, "evidenceRefs")?.array()? {
            let reference = reference.object()?;
            let root = retained_evidence_root(coverage)?;
            let repository = repository_root()?;
            let bundle = confined_record_path(
                &repository,
                root,
                Path::new(json_member(reference, "bundlePath")?.string()?),
            )?;
            let (oracle, candidate) = regression_bundle_executable_pair(&bundle)?;
            identities.insert((oracle.hex(), candidate.hex()));
        }
    }
    if identities.len() != 1 {
        return Err("finalized claim evidence has no unique oracle/candidate identity".to_owned());
    }
    let (oracle, candidate) = identities
        .pop_first()
        .ok_or_else(|| "finalized claim evidence has no executable identity".to_owned())?;
    Ok((
        Digest::from_hex(&oracle)
            .map_err(|_| "finalized claim evidence oracle digest is invalid".to_owned())?,
        Digest::from_hex(&candidate)
            .map_err(|_| "finalized claim evidence candidate digest is invalid".to_owned())?,
    ))
}

fn regression_bundle_executable_pair(bundle: &Path) -> Result<(Digest, Digest), String> {
    let digest = |side: &str| -> Result<Digest, String> {
        let observation = parse_json(&read_text(&bundle.join(side).join("observation.json"))?)?;
        Digest::from_hex(
            json_member(
                json_member(observation.object()?, "identity")?.object()?,
                "sha256",
            )?
            .string()?,
        )
        .map_err(|_| format!("{side} claim evidence executable digest is invalid"))
    };
    Ok((digest("oracle")?, digest("candidate")?))
}

struct RegressionPreparation {
    template: DifferentialCase,
    case: DifferentialCase,
    source: String,
    minimized: RegressionMinimization,
    oracle: ExecutableIdentity,
    candidate: ExecutableIdentity,
    candidate_commit: String,
    candidate_build_info_sha256: Digest,
    assurance_epoch: Digest,
    current_claim_root: PathBuf,
    current_claim_relative: PathBuf,
    provider_subject_root: PathBuf,
    provider_selection_root: PathBuf,
}

fn write_regression_package(
    root: &Path,
    output: &Path,
    issue: &str,
    category: &str,
    preparation: &RegressionPreparation,
) -> Result<(), String> {
    fs::create_dir(output).map_err(|error| {
        format!(
            "cannot create regression package {}: {error}",
            output.display()
        )
    })?;
    let executable_directory = output.join("executables");
    fs::create_dir(&executable_directory)
        .map_err(|error| format!("cannot create regression executable directory: {error}"))?;
    copy_regression_executable(
        &preparation.oracle.path,
        &executable_directory.join("oracle"),
    )?;
    copy_regression_executable(
        &preparation.candidate.path,
        &executable_directory.join("candidate"),
    )?;
    let trial_directory = output.join("trials");
    fs::create_dir(&trial_directory)
        .map_err(|error| format!("cannot create regression trial directory: {error}"))?;
    for (index, (_, _, _, trial)) in preparation.minimized.attempts.iter().enumerate() {
        write_atomic(
            &trial_directory.join(format!("{index:03}.hell")),
            trial.as_bytes(),
        )?;
    }
    let retained_claim_root = output.join("current-claim-evidence");
    copy_regression_tree(&preparation.current_claim_root, &retained_claim_root)?;
    let retained_subject_root = output.join("provider-subject");
    copy_regression_tree(&preparation.provider_subject_root, &retained_subject_root)?;
    let retained_selection_root = output.join("provider-selection");
    copy_regression_tree(
        &preparation.provider_selection_root,
        &retained_selection_root,
    )?;
    write_atomic(&output.join("original.hell"), preparation.source.as_bytes())?;
    write_atomic(
        &output.join("minimized.hell"),
        preparation.minimized.source.as_bytes(),
    )?;
    let mut execution_case = preparation.case.clone();
    execution_case.claim_evidence = None;
    let (bundle, reviewed_case) = hell_testkit::retain_reviewed_regression_bundle(
        &output.join("evidence"),
        &execution_case,
        &preparation.minimized.report,
        "oracle-derived minimized regression descriptor proposed for protected review v1",
    )
    .map_err(|error| format!("cannot retain minimized regression evidence: {error}"))?;
    let bundle_sha256 =
        hell_testkit::verify_regression_observation_bundle_for_case(&bundle, &reviewed_case)
            .map_err(|error| format!("cannot reverify minimized regression evidence: {error}"))?;
    let reached_inventory =
        hell_testkit::retained_regression_reached_claim_targets(&bundle, &reviewed_case)
            .map_err(|error| format!("cannot derive reached regression claim cells: {error}"))?;
    let reached = hell_testkit::retained_regression_reviewed_claim_targets(&bundle, &reviewed_case)
        .map_err(|error| format!("cannot derive reviewed regression claim cells: {error}"))?;
    let retained_claim_coverage = retained_claim_root.join(&preparation.current_claim_relative);
    let observed_platform = regression_host_platform()?;
    let surveillance_policy = read_text(&root.join("compat").join("surveillance-policy.toml"))?;
    write_atomic(
        &output.join("surveillance-policy.toml"),
        surveillance_policy.as_bytes(),
    )?;
    let claim_impact = regression_claim_impact(
        &retained_claim_coverage,
        &retained_subject_root.join("sources").join("public"),
        &reached,
        observed_platform,
        &preparation.candidate_commit,
        &preparation.assurance_epoch.hex(),
        &surveillance_policy,
    )?;
    let trace = regression_minimization_trace(&preparation.source, &preparation.minimized);
    write_atomic(&output.join("minimization-trace.json"), trace.as_bytes())?;
    let proposal = regression_proposal_json(&RegressionProposalInputs {
        root,
        issue,
        category,
        template: &preparation.template,
        case: &reviewed_case,
        original: &preparation.source,
        minimized: &preparation.minimized,
        oracle: &preparation.oracle,
        candidate: &preparation.candidate,
        candidate_build_info_sha256: preparation.candidate_build_info_sha256,
        assurance_epoch: preparation.assurance_epoch,
        bundle_sha256,
        trace_sha256: sha256_bytes(trace.as_bytes()),
        reached: &reached,
        reached_inventory: &reached_inventory,
        claim_impact: &claim_impact,
        current_claim_path: &preparation.current_claim_relative,
        current_claim_root_sha256: record_digest(&retained_claim_root)?,
        provider_subject_sha256: record_digest(&retained_subject_root)?,
        provider_selection_sha256: record_digest(&retained_selection_root)?,
        observed_platform,
    })?;
    write_atomic(&output.join("proposal.json"), proposal.as_bytes())?;
    Ok(())
}

fn copy_regression_executable(source: &Path, destination: &Path) -> Result<(), String> {
    fs::copy(source, destination).map_err(|error| {
        format!(
            "cannot retain regression executable {}: {error}",
            source.display()
        )
    })?;
    let permissions = fs::metadata(source)
        .map_err(|error| format!("cannot inspect regression executable: {error}"))?
        .permissions();
    fs::set_permissions(destination, permissions)
        .map_err(|error| format!("cannot retain regression executable permissions: {error}"))
}

fn copy_regression_tree(source: &Path, destination: &Path) -> Result<(), String> {
    fs::create_dir(destination)
        .map_err(|error| format!("cannot create retained claim evidence root: {error}"))?;
    let mut pending = vec![(source.to_path_buf(), destination.to_path_buf())];
    while let Some((current, target)) = pending.pop() {
        let mut entries = fs::read_dir(&current)
            .map_err(|error| format!("cannot read retained claim evidence: {error}"))?
            .collect::<Result<Vec<_>, _>>()
            .map_err(|error| format!("cannot list retained claim evidence: {error}"))?;
        entries.sort_by_key(fs::DirEntry::file_name);
        for entry in entries {
            let kind = entry
                .file_type()
                .map_err(|error| format!("cannot inspect retained claim evidence: {error}"))?;
            let next = target.join(entry.file_name());
            if kind.is_dir() {
                fs::create_dir(&next)
                    .map_err(|error| format!("cannot create retained claim directory: {error}"))?;
                pending.push((entry.path(), next));
            } else if kind.is_file() {
                fs::copy(entry.path(), next)
                    .map_err(|error| format!("cannot copy retained claim evidence: {error}"))?;
            } else {
                return Err("retained claim evidence contains a special file".to_owned());
            }
        }
    }
    Ok(())
}

fn regression_issue(options: &Options) -> Result<&str, String> {
    let issue = options
        .issue
        .as_deref()
        .ok_or_else(|| "regression-import requires --issue".to_owned())?;
    if issue.trim() != issue || issue.len() < 5 || !issue.contains(':') {
        return Err("regression issue must be a stable provider-kind:number reference".to_owned());
    }
    Ok(issue)
}

fn regression_category(options: &Options) -> Result<&str, String> {
    let category = options
        .category
        .as_deref()
        .ok_or_else(|| "regression-import requires --category".to_owned())?;
    if !matches!(
        category,
        "semantic-mismatch" | "presentation-mismatch" | "platform-mismatch" | "resource-mismatch"
    ) {
        return Err("regression category is not a reviewed compatibility category".to_owned());
    }
    Ok(category)
}

fn regression_template_case(options: &Options) -> Result<DifferentialCase, String> {
    let expected = options.expected.as_deref().ok_or_else(|| {
        "regression-import prepare requires --expected reviewed template case id".to_owned()
    })?;
    let template = committed_differential_cases()
        .into_iter()
        .find(|case| case.id.as_ref() == expected)
        .ok_or_else(|| format!("reviewed regression template case {expected:?} is unknown"))?;
    if template.claim_evidence.is_none() {
        return Err("regression template must have reviewed claim evidence".to_owned());
    }
    Ok(template)
}

fn regression_candidate_build_info(
    candidate: &ExecutableIdentity,
    source_commit: &str,
) -> Result<Digest, String> {
    require_git_sha_text(source_commit, "regression candidate build source")?;
    let expected = regression_expected_build_info(source_commit);
    let observed = candidate
        .build_info
        .as_ref()
        .ok_or_else(|| "regression candidate has no build-info payload".to_owned())?;
    if observed
        .lines
        .iter()
        .map(AsRef::as_ref)
        .ne(expected.iter().map(String::as_str))
    {
        return Err(
            "regression candidate build info is not exact current source policy".to_owned(),
        );
    }
    Ok(regression_build_info_sha256(&expected))
}

fn regression_expected_build_info(source_commit: &str) -> [String; 7] {
    [
        format!("hell-rs {}", env!("CARGO_PKG_VERSION")),
        format!("language baseline {}", hell_builtins::LANGUAGE_VERSION),
        format!("upstream {}", hell_builtins::UPSTREAM_COMMIT),
        format!("source commit {source_commit}"),
        "compatibility evidence schema 1".to_owned(),
        format!(
            "compiler policy {:?}",
            hell_compiler::CompilerConfig::upstream()
        ),
        format!(
            "runtime policy {:?}",
            hell_runtime::policy::RuntimePolicy::upstream()
        ),
    ]
}

fn regression_build_info_sha256(lines: &[String]) -> Digest {
    let mut canonical = lines.join("\n");
    canonical.push('\n');
    sha256_bytes(canonical.as_bytes())
}

struct RegressionMinimization {
    source: String,
    report: hell_testkit::DifferentialReport,
    attempts: Vec<(Digest, usize, bool, String)>,
}

fn minimize_regression(
    oracle: &ExecutableIdentity,
    candidate: &ExecutableIdentity,
    case: &DifferentialCase,
) -> Result<RegressionMinimization, String> {
    let baseline = differential_with_identities(oracle, candidate, case)
        .map_err(|error| format!("cannot execute regression baseline: {error}"))?;
    if baseline.mismatches.is_empty() {
        return Err("regression source does not reproduce an oracle/candidate mismatch".to_owned());
    }
    verify_regression_trial(case, &baseline)?;
    let expected = baseline.mismatches.clone();
    let mut current = case.source.to_string();
    let mut report = baseline;
    let mut attempts = Vec::new();
    let mut granularity = 2_usize;
    while current.chars().count() > 1 && attempts.len() < 32 {
        let characters = current.chars().collect::<Vec<_>>();
        let chunk = characters.len().div_ceil(granularity);
        let mut reduced = false;
        for start in (0..characters.len()).step_by(chunk) {
            if attempts.len() == 32 {
                break;
            }
            let end = usize::min(start.saturating_add(chunk), characters.len());
            let mut trial = characters[..start]
                .iter()
                .chain(&characters[end..])
                .collect::<String>();
            if trial.trim().is_empty() {
                continue;
            }
            if !trial.ends_with('\n') {
                trial.push('\n');
            }
            let mut trial_case = case.clone();
            trial_case.source = trial.clone().into();
            if let Some(descriptor) = &mut trial_case.claim_evidence {
                descriptor.source_sha256 = sha256_bytes(trial.as_bytes());
            }
            let Ok(trial_report) = differential_with_identities(oracle, candidate, &trial_case)
            else {
                attempts.push((sha256_bytes(trial.as_bytes()), trial.len(), false, trial));
                continue;
            };
            let preserved = trial_report.mismatches == expected
                && verify_regression_trial(&trial_case, &trial_report).is_ok();
            attempts.push((
                sha256_bytes(trial.as_bytes()),
                trial.len(),
                preserved,
                trial.clone(),
            ));
            if preserved {
                current = trial;
                report = trial_report;
                granularity = granularity.saturating_sub(1).max(2);
                reduced = true;
                break;
            }
        }
        if !reduced {
            if granularity >= characters.len() {
                break;
            }
            granularity = usize::min(characters.len(), granularity.saturating_mul(2));
        }
    }
    Ok(RegressionMinimization {
        source: current,
        report,
        attempts,
    })
}

fn verify_regression_trial(
    case: &DifferentialCase,
    report: &hell_testkit::DifferentialReport,
) -> Result<(), String> {
    let temporary = create_private_temp_directory("hell-regression-trial")?;
    let mut execution_case = case.clone();
    execution_case.claim_evidence = None;
    let result = retain_observation_bundle(&temporary, &execution_case, report)
        .map_err(|error| format!("cannot retain regression trial: {error}"))
        .and_then(|bundle| {
            hell_testkit::verify_observation_bundle_for_case(&bundle, &execution_case)
                .map(|_| ())
                .map_err(|error| format!("regression trial lacks exact evidence: {error}"))
        });
    let cleanup = fs::remove_dir_all(&temporary)
        .map_err(|error| format!("cannot remove regression trial directory: {error}"));
    result.and(cleanup)
}

fn regression_minimization_trace(original: &str, minimized: &RegressionMinimization) -> String {
    let mut document = format!(
        concat!(
            "{{\n  \"schemaVersion\": 1,\n",
            "  \"algorithm\": \"deterministic-character-ddmin-v1\",\n",
            "  \"originalBytes\": {},\n",
            "  \"minimizedBytes\": {},\n",
            "  \"attempts\": ["
        ),
        original.len(),
        minimized.source.len()
    );
    for (index, (digest, bytes, preserved, _)) in minimized.attempts.iter().enumerate() {
        if index != 0 {
            document.push(',');
        }
        write!(
            document,
            "\n    {{\"path\": \"trials/{index:03}.hell\", \"sourceSha256\": \"{}\", \"bytes\": {bytes}, \"preservedExactMismatchAndClaimEvidence\": {preserved}}}", digest.hex()
        )
        .expect("writing to String cannot fail");
    }
    document.push_str("\n  ]\n}\n");
    document
}

struct RegressionProposalInputs<'a> {
    root: &'a Path,
    issue: &'a str,
    category: &'a str,
    template: &'a DifferentialCase,
    case: &'a DifferentialCase,
    original: &'a str,
    minimized: &'a RegressionMinimization,
    oracle: &'a ExecutableIdentity,
    candidate: &'a ExecutableIdentity,
    candidate_build_info_sha256: Digest,
    assurance_epoch: Digest,
    bundle_sha256: Digest,
    trace_sha256: Digest,
    reached: &'a [hell_testkit::RetainedReachedClaimTarget],
    reached_inventory: &'a [hell_testkit::RetainedReachedClaimTarget],
    claim_impact: &'a JsonValue,
    current_claim_path: &'a Path,
    current_claim_root_sha256: String,
    provider_subject_sha256: String,
    provider_selection_sha256: String,
    observed_platform: &'a str,
}

fn regression_proposal_json(inputs: &RegressionProposalInputs<'_>) -> Result<String, String> {
    let targets = regression_target_values(inputs.reached, inputs.case)?;
    let candidate_commit = git_output(inputs.root, &["rev-parse", "HEAD"])?;
    let mut fields = BTreeMap::new();
    fields.extend(regression_proposal_identity_fields(
        inputs,
        &candidate_commit,
    ));
    fields.extend(regression_proposal_evidence_fields(inputs));
    fields.extend(regression_proposal_review_fields(inputs, targets));
    fields.insert(
        "observedPlatform".to_owned(),
        JsonValue::String(inputs.observed_platform.to_owned()),
    );
    let proposal = JsonValue::Object(fields);
    Ok(String::from_utf8(canonical_json_bytes(&proposal)?).expect("canonical JSON is valid UTF-8"))
}

fn regression_target_values(
    reached: &[hell_testkit::RetainedReachedClaimTarget],
    case: &DifferentialCase,
) -> Result<Vec<JsonValue>, String> {
    let descriptor = case
        .claim_evidence
        .as_ref()
        .ok_or_else(|| "regression case has no reviewed claim descriptor".to_owned())?;
    let reviewed_targets = descriptor
        .semantic_targets
        .iter()
        .map(|target| {
            (
                target.builtin.to_string(),
                target.dimension.as_str().to_owned(),
            )
        })
        .collect::<BTreeSet<_>>();
    let reached_targets = reached
        .iter()
        .map(|target| {
            (
                target.builtin.to_string(),
                target.dimension.as_str().to_owned(),
            )
        })
        .collect::<BTreeSet<_>>();
    if reviewed_targets != reached_targets || reviewed_targets.len() != reached.len() {
        return Err(
            "regression reached target set is not one exact full reviewed descriptor".to_owned(),
        );
    }
    let mut targets = reached
        .iter()
        .map(|target| regression_target_value(target, descriptor))
        .collect::<Result<Vec<_>, _>>()?;
    targets.sort_by_key(|target| {
        let target = target.object().expect("constructed target is an object");
        (
            json_member(target, "builtin")
                .and_then(JsonValue::string)
                .unwrap_or_default()
                .to_owned(),
            json_member(target, "dimension")
                .and_then(JsonValue::string)
                .unwrap_or_default()
                .to_owned(),
        )
    });
    if targets.is_empty() {
        return Err("regression proposal has no reached semantic target".to_owned());
    }
    Ok(targets)
}

fn regression_target_value(
    target: &hell_testkit::RetainedReachedClaimTarget,
    descriptor: &hell_testkit::ClaimEvidenceDescriptor,
) -> Result<JsonValue, String> {
    let required =
        hell_testkit::required_obligations_for_target(&target.builtin, target.dimension)?;
    let observed = target
        .obligations
        .iter()
        .map(|value| value.0.clone())
        .collect::<BTreeSet<_>>();
    if observed != required {
        return Err(format!(
            "regression target {}/{} lacks its complete required obligation set",
            target.builtin,
            target.dimension.as_str()
        ));
    }
    let reviewed = descriptor
        .semantic_targets
        .iter()
        .find(|reviewed| {
            reviewed.builtin == target.builtin && reviewed.dimension == target.dimension
        })
        .ok_or_else(|| {
            format!(
                "regression reached target {}/{} has no full reviewed descriptor",
                target.builtin,
                target.dimension.as_str()
            )
        })?;
    if reviewed
        .obligations
        .iter()
        .map(|obligation| obligation.0.clone())
        .collect::<BTreeSet<_>>()
        != required
    {
        return Err(format!(
            "regression reviewed target {}/{} has a different obligation set",
            target.builtin,
            target.dimension.as_str()
        ));
    }
    Ok(JsonValue::Object(BTreeMap::from([
        (
            "builtin".to_owned(),
            JsonValue::String(target.builtin.to_string()),
        ),
        (
            "dimension".to_owned(),
            JsonValue::String(target.dimension.as_str().to_owned()),
        ),
        (
            "obligations".to_owned(),
            JsonValue::Array(
                required
                    .into_iter()
                    .map(|value| JsonValue::String(value.to_string()))
                    .collect(),
            ),
        ),
    ])))
}

fn regression_proposal_identity_fields(
    inputs: &RegressionProposalInputs<'_>,
    candidate_commit: &str,
) -> BTreeMap<String, JsonValue> {
    BTreeMap::from([
        (
            "assuranceEpochSha256".to_owned(),
            JsonValue::String(inputs.assurance_epoch.hex()),
        ),
        (
            "candidateBuildInfoSha256".to_owned(),
            JsonValue::String(inputs.candidate_build_info_sha256.hex()),
        ),
        (
            "candidateCommit".to_owned(),
            JsonValue::String(candidate_commit.trim().to_owned()),
        ),
        (
            "candidateExecutableSha256".to_owned(),
            JsonValue::String(inputs.candidate.sha256.hex()),
        ),
        (
            "candidateExecutablePath".to_owned(),
            JsonValue::String("executables/candidate".to_owned()),
        ),
        (
            "caseId".to_owned(),
            JsonValue::String(inputs.case.id.to_string()),
        ),
        (
            "category".to_owned(),
            JsonValue::String(inputs.category.to_owned()),
        ),
        (
            "issue".to_owned(),
            JsonValue::String(inputs.issue.to_owned()),
        ),
        (
            "oracleExecutableSha256".to_owned(),
            JsonValue::String(inputs.oracle.sha256.hex()),
        ),
        (
            "oracleExecutablePath".to_owned(),
            JsonValue::String("executables/oracle".to_owned()),
        ),
        (
            "templateCaseId".to_owned(),
            JsonValue::String(inputs.template.id.to_string()),
        ),
    ])
}

fn regression_proposal_evidence_fields(
    inputs: &RegressionProposalInputs<'_>,
) -> BTreeMap<String, JsonValue> {
    BTreeMap::from([
        (
            "bundle".to_owned(),
            JsonValue::Object(BTreeMap::from([
                (
                    "path".to_owned(),
                    JsonValue::String(format!("evidence/{}", inputs.case.id)),
                ),
                (
                    "sha256".to_owned(),
                    JsonValue::String(inputs.bundle_sha256.hex()),
                ),
            ])),
        ),
        (
            "currentClaimEvidence".to_owned(),
            JsonValue::Object(BTreeMap::from([
                (
                    "path".to_owned(),
                    JsonValue::String(
                        Path::new("current-claim-evidence")
                            .join(inputs.current_claim_path)
                            .to_string_lossy()
                            .replace('\\', "/"),
                    ),
                ),
                (
                    "rootSha256".to_owned(),
                    JsonValue::String(inputs.current_claim_root_sha256.clone()),
                ),
            ])),
        ),
        (
            "minimization".to_owned(),
            JsonValue::Object(BTreeMap::from([
                (
                    "acceptedReductions".to_owned(),
                    JsonValue::Number(
                        inputs
                            .minimized
                            .attempts
                            .iter()
                            .filter(|(_, _, accepted, _)| *accepted)
                            .count() as u64,
                    ),
                ),
                (
                    "attemptedReductions".to_owned(),
                    JsonValue::Number(inputs.minimized.attempts.len() as u64),
                ),
                (
                    "tracePath".to_owned(),
                    JsonValue::String("minimization-trace.json".to_owned()),
                ),
                (
                    "traceSha256".to_owned(),
                    JsonValue::String(inputs.trace_sha256.hex()),
                ),
            ])),
        ),
        (
            "providerSelection".to_owned(),
            JsonValue::Object(BTreeMap::from([
                (
                    "selectionRootPath".to_owned(),
                    JsonValue::String("provider-selection".to_owned()),
                ),
                (
                    "selectionRootSha256".to_owned(),
                    JsonValue::String(inputs.provider_selection_sha256.clone()),
                ),
                (
                    "subjectRootPath".to_owned(),
                    JsonValue::String("provider-subject".to_owned()),
                ),
                (
                    "subjectRootSha256".to_owned(),
                    JsonValue::String(inputs.provider_subject_sha256.clone()),
                ),
            ])),
        ),
        (
            "minimizedProgram".to_owned(),
            regression_program_record("minimized.hell", &inputs.minimized.source),
        ),
        (
            "originalProgram".to_owned(),
            regression_program_record("original.hell", inputs.original),
        ),
    ])
}

fn regression_proposal_review_fields(
    inputs: &RegressionProposalInputs<'_>,
    targets: Vec<JsonValue>,
) -> BTreeMap<String, JsonValue> {
    BTreeMap::from([
        ("claimEligible".to_owned(), JsonValue::Bool(false)),
        ("claimImpact".to_owned(), inputs.claim_impact.clone()),
        ("promotionRequired".to_owned(), JsonValue::Bool(true)),
        (
            "reachedTargetInventory".to_owned(),
            JsonValue::Array(regression_reached_target_inventory(inputs)),
        ),
        (
            "reviewState".to_owned(),
            JsonValue::String("proposed".to_owned()),
        ),
        ("schemaVersion".to_owned(), JsonValue::Number(2)),
        ("targets".to_owned(), JsonValue::Array(targets)),
    ])
}

fn regression_reached_target_inventory(inputs: &RegressionProposalInputs<'_>) -> Vec<JsonValue> {
    regression_reached_inventory_values(inputs.reached_inventory, inputs.reached)
}

fn regression_reached_inventory_values(
    reached_inventory: &[hell_testkit::RetainedReachedClaimTarget],
    reviewed_targets: &[hell_testkit::RetainedReachedClaimTarget],
) -> Vec<JsonValue> {
    reached_inventory
        .iter()
        .map(|target| {
            let reviewed = reviewed_targets.iter().any(|candidate| {
                candidate.builtin == target.builtin && candidate.dimension == target.dimension
            });
            JsonValue::Object(BTreeMap::from([
                (
                    "builtin".to_owned(),
                    JsonValue::String(target.builtin.to_string()),
                ),
                (
                    "dimension".to_owned(),
                    JsonValue::String(target.dimension.as_str().to_owned()),
                ),
                (
                    "disposition".to_owned(),
                    JsonValue::String(
                        if reviewed {
                            "complete-reviewed-descriptor"
                        } else {
                            "reached-incomplete-nonclaim"
                        }
                        .to_owned(),
                    ),
                ),
                (
                    "observedObligations".to_owned(),
                    JsonValue::Array(
                        target
                            .obligations
                            .iter()
                            .map(|obligation| JsonValue::String(obligation.0.to_string()))
                            .collect(),
                    ),
                ),
            ]))
        })
        .collect()
}

fn regression_claim_impact(
    coverage: &Path,
    public_root: &Path,
    reached: &[hell_testkit::RetainedReachedClaimTarget],
    observed_platform: &str,
    candidate_commit: &str,
    assurance_epoch: &str,
    surveillance_policy: &str,
) -> Result<JsonValue, String> {
    if !matches!(
        observed_platform,
        "linux-amd64" | "macos-arm64" | "windows-amd64"
    ) {
        return Err("regression observation platform is not reviewed".to_owned());
    }
    require_git_sha_text(candidate_commit, "regression claim impact candidate")?;
    require_digest(assurance_epoch, "regression claim impact epoch")?;
    require_assignment(surveillance_policy, "promoted_claim_regression", "true")?;
    let automatic = assignment_string_array(surveillance_policy, "automatic_critical_events")?;
    let automatic_revocation = automatic
        .iter()
        .any(|event| event == "promoted-claim-regression");
    let mapping_root = retained_evidence_root(coverage)?.to_path_buf();
    let coverage = parse_json(&read_text(coverage)?)?;
    let coverage = coverage.object()?;
    verify_regression_public_state(public_root, candidate_commit, assurance_epoch)?;
    let public_mappings = crate::surveillance_impact::verified_claim_public_mappings(
        &mapping_root,
        public_root,
        candidate_commit,
        assurance_epoch,
    )?;
    let impact = regression_claim_impact_cells(
        coverage,
        reached,
        observed_platform,
        automatic_revocation,
        &public_mappings,
    )?;
    let statements = JsonValue::Array(
        impact
            .statements
            .into_iter()
            .map(
                |(group, statement, report_digest, mapping_digest, packet_digest)| {
                    JsonValue::Object(BTreeMap::from([
                        ("claimReviewGroupId".to_owned(), JsonValue::String(group)),
                        (
                            "currentStatementDigest".to_owned(),
                            JsonValue::String(report_digest),
                        ),
                        (
                            "mappingPacketSha256".to_owned(),
                            JsonValue::String(packet_digest),
                        ),
                        (
                            "mappingSha256".to_owned(),
                            JsonValue::String(mapping_digest),
                        ),
                        ("publicStatementId".to_owned(), JsonValue::String(statement)),
                        (
                            "state".to_owned(),
                            JsonValue::String("current-signed-public-statement-bound".to_owned()),
                        ),
                    ]))
                },
            )
            .collect(),
    );
    Ok(JsonValue::Object(BTreeMap::from([
        ("affectedPublicStatements".to_owned(), statements),
        (
            "affectedReviewGroupIds".to_owned(),
            JsonValue::Array(impact.groups.into_iter().map(JsonValue::String).collect()),
        ),
        ("cells".to_owned(), JsonValue::Array(impact.cells)),
        ("claimStatusChanged".to_owned(), JsonValue::Bool(true)),
        (
            "immediateRevocationRequired".to_owned(),
            JsonValue::Bool(automatic_revocation),
        ),
        (
            "proposedEvidenceTransition".to_owned(),
            JsonValue::String(
                if automatic_revocation {
                    "automatic-policy-revocation"
                } else {
                    "at-risk-review-required"
                }
                .to_owned(),
            ),
        ),
        (
            "surveillancePolicySha256".to_owned(),
            JsonValue::String(sha256_bytes(surveillance_policy.as_bytes()).hex()),
        ),
        (
            "staleEvidenceRefs".to_owned(),
            JsonValue::Array(impact.stale.into_iter().map(JsonValue::String).collect()),
        ),
        (
            "targetCount".to_owned(),
            JsonValue::Number(reached.len() as u64),
        ),
    ])))
}

type RegressionPublicStatement = (String, String, String, String, String);

struct RegressionClaimImpactParts {
    cells: Vec<JsonValue>,
    groups: BTreeSet<String>,
    stale: BTreeSet<String>,
    statements: BTreeSet<RegressionPublicStatement>,
}

fn regression_claim_impact_cells(
    coverage: &BTreeMap<String, JsonValue>,
    reached: &[hell_testkit::RetainedReachedClaimTarget],
    observed_platform: &str,
    automatic_revocation: bool,
    public_mappings: &BTreeMap<String, crate::surveillance_impact::VerifiedClaimPublicMapping>,
) -> Result<RegressionClaimImpactParts, String> {
    let mut result = RegressionClaimImpactParts {
        cells: Vec::new(),
        groups: BTreeSet::new(),
        stale: BTreeSet::new(),
        statements: BTreeSet::new(),
    };
    let mut matched = reached
        .iter()
        .map(|target| {
            (
                (
                    target.builtin.to_string(),
                    target.dimension.as_str().to_owned(),
                ),
                0_u8,
            )
        })
        .collect::<BTreeMap<_, _>>();
    for cell in json_member(coverage, "cells")?.array()? {
        let cell = cell.object()?;
        let Some(target) = reached.iter().find(|target| {
            json_member(cell, "builtin").and_then(JsonValue::string) == Ok(target.builtin.as_ref())
                && json_member(cell, "dimension").and_then(JsonValue::string)
                    == Ok(target.dimension.as_str())
                && json_member(cell, "platform").and_then(JsonValue::string)
                    == Ok(observed_platform)
                && json_member(cell, "profile").and_then(JsonValue::string) == Ok("upstream")
        }) else {
            continue;
        };
        let (impact, group, references) =
            regression_impacted_claim_cell(cell, target, automatic_revocation)?;
        let claim_cell_id = format!(
            "{}:{}:{}:{}",
            target.builtin,
            target.dimension.as_str(),
            observed_platform,
            json_member(cell, "proposedStatus")?.string()?,
        );
        let mapping = public_mappings
            .get(&claim_cell_id)
            .ok_or_else(|| "regression impact lacks a signed current public mapping".to_owned())?;
        if mapping.review_group_id != group {
            return Err(
                "regression public mapping differs from the impacted review group".to_owned(),
            );
        }
        result.statements.insert((
            mapping.review_group_id.clone(),
            mapping.statement_id.clone(),
            mapping.public_report_sha256.clone(),
            mapping.mapping_sha256.clone(),
            mapping.packet_sha256.clone(),
        ));
        let count = matched
            .get_mut(&(
                target.builtin.to_string(),
                target.dimension.as_str().to_owned(),
            ))
            .ok_or_else(|| "regression impact matched an unknown target".to_owned())?;
        *count = count.saturating_add(1);
        if *count != 1 {
            return Err("regression target maps to multiple finalized claim cells".to_owned());
        }
        result.groups.insert(group);
        result.stale.extend(references);
        result.cells.push(impact);
    }
    if result.cells.len() != reached.len() || matched.values().any(|count| *count != 1) {
        return Err(
            "regression reached targets do not map one-to-one to finalized claim cells".to_owned(),
        );
    }
    Ok(result)
}

fn verify_regression_public_state(
    public_root: &Path,
    candidate: &str,
    epoch: &str,
) -> Result<(), String> {
    let record = crate::custody_ops::verify_retained_published_current_transition(public_root)?;
    let record = parse_json(&record)?;
    if json_member(record.object()?, "candidateCommit")?.string()? != candidate
        || json_member(record.object()?, "assuranceEpochSha256")?.string()? != epoch
    {
        return Err("regression public state differs from the observed candidate epoch".to_owned());
    }
    Ok(())
}

fn regression_impacted_claim_cell(
    cell: &BTreeMap<String, JsonValue>,
    target: &hell_testkit::RetainedReachedClaimTarget,
    automatic_revocation: bool,
) -> Result<(JsonValue, String, Vec<String>), String> {
    let group = claim_decision_group_id(cell)?;
    let references = json_member(cell, "evidenceRefs")?
        .array()?
        .iter()
        .map(canonical_json_digest)
        .collect::<Result<Vec<_>, _>>()?;
    let required =
        hell_testkit::required_obligations_for_target(&target.builtin, target.dimension)?;
    let observed = target
        .obligations
        .iter()
        .map(|value| value.0.clone())
        .collect::<BTreeSet<_>>();
    let value = JsonValue::Object(BTreeMap::from([
        (
            "builtin".to_owned(),
            JsonValue::String(target.builtin.to_string()),
        ),
        (
            "claimReviewGroupId".to_owned(),
            JsonValue::String(group.clone()),
        ),
        (
            "completeObligationSet".to_owned(),
            JsonValue::Bool(observed == required),
        ),
        (
            "currentClaimStatus".to_owned(),
            JsonValue::String(json_member(cell, "proposedStatus")?.string()?.to_owned()),
        ),
        (
            "currentEvidenceRefs".to_owned(),
            JsonValue::Array(references.iter().cloned().map(JsonValue::String).collect()),
        ),
        (
            "dimension".to_owned(),
            JsonValue::String(target.dimension.as_str().to_owned()),
        ),
        (
            "immediateRevocationRequired".to_owned(),
            JsonValue::Bool(automatic_revocation),
        ),
        (
            "platform".to_owned(),
            JsonValue::String(json_member(cell, "platform")?.string()?.to_owned()),
        ),
        (
            "profile".to_owned(),
            JsonValue::String(json_member(cell, "profile")?.string()?.to_owned()),
        ),
        (
            "proposedClaimStatus".to_owned(),
            JsonValue::String("at-risk-regression".to_owned()),
        ),
        (
            "proposedEvidenceStatus".to_owned(),
            JsonValue::String("qualification-required-pending-regression-review".to_owned()),
        ),
        (
            "staleEvidenceRefs".to_owned(),
            JsonValue::Array(references.iter().cloned().map(JsonValue::String).collect()),
        ),
    ]));
    Ok((value, group, references))
}

fn regression_program_record(path: &str, source: &str) -> JsonValue {
    JsonValue::Object(BTreeMap::from([
        ("bytes".to_owned(), JsonValue::Number(source.len() as u64)),
        ("path".to_owned(), JsonValue::String(path.to_owned())),
        (
            "sha256".to_owned(),
            JsonValue::String(sha256_bytes(source.as_bytes()).hex()),
        ),
    ]))
}

struct VerifiedRegressionProposal {
    package_sha256: String,
    candidate_commit: String,
    assurance_epoch: String,
    case_id: String,
    source_sha256: String,
    bundle_sha256: String,
    proposal_sha256: String,
    template_case_id: String,
    source: String,
    targets_descriptor: String,
}

fn regression_verify(root: &Path, options: &Options) -> Result<String, String> {
    let package = required_path(
        &options.input,
        "regression-import verify requires --input package",
    )?;
    let verified = verify_regression_package(root, package)?;
    Ok(format!(
        "verified minimized regression proposal {} ({})",
        verified.case_id, verified.package_sha256
    ))
}

fn verify_regression_package(
    root: &Path,
    package: &Path,
) -> Result<VerifiedRegressionProposal, String> {
    let structure = verify_regression_package_structure(root, package, true)?;
    let proposal = parse_json(&read_text(&package.join("proposal.json"))?)?;
    replay_regression_minimization(root, package, proposal.object()?, &structure.case)?;
    Ok(structure.verified)
}

struct VerifiedRegressionPackageStructure {
    verified: VerifiedRegressionProposal,
    case: DifferentialCase,
}

fn verify_regression_package_structure(
    root: &Path,
    package: &Path,
    probe_subject: bool,
) -> Result<VerifiedRegressionPackageStructure, String> {
    let proposal_path = package.join("proposal.json");
    let proposal_text = read_text(&proposal_path)?;
    let proposal = parse_json(&proposal_text)?;
    let proposal = proposal.object()?;
    verify_regression_proposal_shape(proposal)?;
    let (original, minimized) = verify_regression_minimization(root, package, proposal)?;
    if minimized.len() > original.len() {
        return Err("regression minimization increased the reproducer size".to_owned());
    }
    let template_id = json_member(proposal, "templateCaseId")?.string()?;
    committed_differential_cases()
        .into_iter()
        .find(|case| case.id.as_ref() == template_id)
        .ok_or_else(|| "regression proposal template disappeared".to_owned())?;
    let case_id = json_member(proposal, "caseId")?.string()?.to_owned();
    let execution_case = DifferentialCase {
        id: case_id.clone().into(),
        source: minimized.as_str().into(),
        ..DifferentialCase::default()
    };
    let bundle = json_member(proposal, "bundle")?.object()?;
    let bundle_path = confined_record_path(
        root,
        package,
        Path::new(json_member(bundle, "path")?.string()?),
    )?;
    let case = hell_testkit::reviewed_regression_case_from_bundle(
        &bundle_path,
        &execution_case,
        "oracle-derived minimized regression descriptor proposed for protected review v1",
    )
    .map_err(|error| format!("cannot rederive reviewed regression descriptor: {error}"))?;
    let bundle_sha256 = verify_regression_bundle(root, package, proposal, &case)?;
    verify_regression_identity_fields(proposal)?;
    verify_regression_provider_selection(root, package, proposal, probe_subject)?;
    let package_sha256 = record_digest(package)?;
    Ok(VerifiedRegressionPackageStructure {
        verified: VerifiedRegressionProposal {
            package_sha256,
            candidate_commit: json_member(proposal, "candidateCommit")?
                .string()?
                .to_owned(),
            assurance_epoch: json_member(proposal, "assuranceEpochSha256")?
                .string()?
                .to_owned(),
            case_id,
            source_sha256: sha256_bytes(minimized.as_bytes()).hex(),
            bundle_sha256,
            proposal_sha256: sha256_bytes(proposal_text.as_bytes()).hex(),
            template_case_id: template_id.to_owned(),
            source: minimized,
            targets_descriptor: read_text(&bundle_path.join("case.toml"))?,
        },
        case,
    })
}

fn verify_regression_provider_selection(
    root: &Path,
    package: &Path,
    proposal: &BTreeMap<String, JsonValue>,
    probe_subject: bool,
) -> Result<(), String> {
    let retained = json_member(proposal, "providerSelection")?.object()?;
    exact_keys(
        retained,
        &[
            "selectionRootPath",
            "selectionRootSha256",
            "subjectRootPath",
            "subjectRootSha256",
        ],
    )?;
    if json_member(retained, "selectionRootPath")?.string()? != "provider-selection"
        || json_member(retained, "subjectRootPath")?.string()? != "provider-subject"
    {
        return Err("regression provider roots are not canonical".to_owned());
    }
    let subject = package.join("provider-subject");
    let selection = package.join("provider-selection");
    if record_digest(&subject)? != json_member(retained, "subjectRootSha256")?.string()?
        || record_digest(&selection)? != json_member(retained, "selectionRootSha256")?.string()?
    {
        return Err("regression provider subject or selection digest differs".to_owned());
    }
    reverify_regression_provider_selection(
        root,
        &subject,
        &selection,
        json_member(proposal, "candidateCommit")?.string()?,
        ".github/workflows/regression-subject.yml",
    )?;
    require_regression_artifact_class(&selection, "regression-subject-")?;
    verify_regression_subject_source_chain(
        root,
        &subject,
        json_member(proposal, "candidateCommit")?.string()?,
        json_member(proposal, "templateCaseId")?.string()?,
        probe_subject,
    )?;
    for (provider_path, package_path) in [
        ("program.hell", "original.hell"),
        ("oracle", "executables/oracle"),
        ("candidate", "executables/candidate"),
    ] {
        if record_digest(&subject.join(provider_path))?
            != record_digest(&package.join(package_path))?
        {
            return Err(
                "regression packaged subject differs from provider-selected bytes".to_owned(),
            );
        }
    }
    let current = json_member(proposal, "currentClaimEvidence")?.object()?;
    let current_path = confined_record_path(
        root,
        package,
        Path::new(json_member(current, "path")?.string()?),
    )?;
    if record_digest(&subject.join("claim-coverage.json"))? != record_digest(&current_path)? {
        return Err("regression claim coverage differs from provider-selected bytes".to_owned());
    }
    Ok(())
}

fn verify_regression_proposal_shape(proposal: &BTreeMap<String, JsonValue>) -> Result<(), String> {
    exact_keys(
        proposal,
        &[
            "assuranceEpochSha256",
            "bundle",
            "candidateBuildInfoSha256",
            "candidateCommit",
            "candidateExecutableSha256",
            "candidateExecutablePath",
            "caseId",
            "category",
            "claimEligible",
            "claimImpact",
            "currentClaimEvidence",
            "issue",
            "minimization",
            "minimizedProgram",
            "oracleExecutableSha256",
            "oracleExecutablePath",
            "observedPlatform",
            "originalProgram",
            "promotionRequired",
            "providerSelection",
            "reachedTargetInventory",
            "reviewState",
            "schemaVersion",
            "targets",
            "templateCaseId",
        ],
    )?;
    if json_member(proposal, "schemaVersion")?.number()? != 2
        || json_member(proposal, "claimEligible")?.boolean()?
        || !json_member(proposal, "promotionRequired")?.boolean()?
        || json_member(proposal, "reviewState")?.string()? != "proposed"
    {
        return Err("regression proposal state is not fail-closed".to_owned());
    }
    if !matches!(
        json_member(proposal, "category")?.string()?,
        "semantic-mismatch" | "presentation-mismatch" | "platform-mismatch" | "resource-mismatch"
    ) || !json_member(proposal, "issue")?.string()?.contains(':')
        || json_member(proposal, "targets")?.array()?.is_empty()
    {
        return Err("regression proposal classification or target set is invalid".to_owned());
    }
    let impact = json_member(proposal, "claimImpact")?.object()?;
    exact_keys(
        impact,
        &[
            "affectedPublicStatements",
            "affectedReviewGroupIds",
            "cells",
            "claimStatusChanged",
            "immediateRevocationRequired",
            "proposedEvidenceTransition",
            "staleEvidenceRefs",
            "surveillancePolicySha256",
            "targetCount",
        ],
    )?;
    if !json_member(impact, "claimStatusChanged")?.boolean()?
        || json_member(impact, "immediateRevocationRequired")?.boolean()?
        || json_member(impact, "proposedEvidenceTransition")?.string()? != "at-risk-review-required"
        || json_member(impact, "targetCount")?.number()?
            != json_member(proposal, "targets")?.array()?.len() as u64
    {
        return Err("regression claim impact is not derived from its exact target set".to_owned());
    }
    Ok(())
}

fn verify_regression_minimization(
    root: &Path,
    package: &Path,
    proposal: &BTreeMap<String, JsonValue>,
) -> Result<(String, String), String> {
    let original =
        verify_regression_program(root, package, json_member(proposal, "originalProgram")?)?;
    let minimized =
        verify_regression_program(root, package, json_member(proposal, "minimizedProgram")?)?;
    let minimization = json_member(proposal, "minimization")?.object()?;
    exact_keys(
        minimization,
        &[
            "acceptedReductions",
            "attemptedReductions",
            "tracePath",
            "traceSha256",
        ],
    )?;
    let trace_path = confined_record_path(
        root,
        package,
        Path::new(json_member(minimization, "tracePath")?.string()?),
    )?;
    if record_digest(&trace_path)? != json_member(minimization, "traceSha256")?.string()? {
        return Err("regression minimization trace digest differs".to_owned());
    }
    let trace = parse_json(&read_text(&trace_path)?)?;
    let trace = trace.object()?;
    exact_keys(
        trace,
        &[
            "algorithm",
            "attempts",
            "minimizedBytes",
            "originalBytes",
            "schemaVersion",
        ],
    )?;
    if json_member(trace, "schemaVersion")?.number()? != 1
        || json_member(trace, "algorithm")?.string()? != "deterministic-character-ddmin-v1"
        || json_member(trace, "originalBytes")?.number()? != original.len() as u64
        || json_member(trace, "minimizedBytes")?.number()? != minimized.len() as u64
        || json_member(trace, "attempts")?.array()?.len() as u64
            != json_member(minimization, "attemptedReductions")?.number()?
    {
        return Err("regression minimization trace is inconsistent".to_owned());
    }
    verify_regression_attempts(root, package, trace, minimization)?;
    Ok((original, minimized))
}

fn verify_regression_attempts(
    root: &Path,
    package: &Path,
    trace: &BTreeMap<String, JsonValue>,
    minimization: &BTreeMap<String, JsonValue>,
) -> Result<(), String> {
    let attempts = json_member(trace, "attempts")?.array()?;
    if attempts.is_empty() {
        return Err("regression minimization did not execute a reduction trial".to_owned());
    }
    let mut accepted = 0_u64;
    for (index, attempt) in attempts.iter().enumerate() {
        let attempt = attempt.object()?;
        exact_keys(
            attempt,
            &[
                "bytes",
                "path",
                "preservedExactMismatchAndClaimEvidence",
                "sourceSha256",
            ],
        )?;
        let source_path = confined_record_path(
            root,
            package,
            Path::new(json_member(attempt, "path")?.string()?),
        )?;
        if json_member(attempt, "path")?.string()? != format!("trials/{index:03}.hell") {
            return Err("regression minimization trial path is not canonical".to_owned());
        }
        let source = read_text(&source_path)?;
        if json_member(attempt, "sourceSha256")?.string()? != sha256_bytes(source.as_bytes()).hex()
            || json_member(attempt, "bytes")?.number()? != source.len() as u64
            || source.is_empty()
            || !source.ends_with('\n')
        {
            return Err("regression minimization trial is empty".to_owned());
        }
        accepted = accepted.saturating_add(u64::from(
            json_member(attempt, "preservedExactMismatchAndClaimEvidence")?.boolean()?,
        ));
    }
    if accepted != json_member(minimization, "acceptedReductions")?.number()? {
        return Err("regression accepted-reduction count differs from the trace".to_owned());
    }
    Ok(())
}

fn replay_regression_minimization(
    root: &Path,
    package: &Path,
    proposal: &BTreeMap<String, JsonValue>,
    case: &DifferentialCase,
) -> Result<(), String> {
    let epoch = Digest::from_hex(json_member(proposal, "assuranceEpochSha256")?.string()?)
        .map_err(|_| "regression assurance epoch is invalid".to_owned())?;
    let mut oracle = retained_regression_executable(
        root,
        package,
        proposal,
        "oracleExecutablePath",
        "oracleExecutableSha256",
        ExecutableRole::Oracle,
    )?;
    let mut candidate = retained_regression_executable(
        root,
        package,
        proposal,
        "candidateExecutablePath",
        "candidateExecutableSha256",
        ExecutableRole::Candidate,
    )?;
    regression_candidate_build_info(
        &candidate,
        json_member(proposal, "candidateCommit")?.string()?,
    )?;
    oracle.assurance_epoch_sha256 = Some(epoch);
    candidate.assurance_epoch_sha256 = Some(epoch);
    let baseline = differential_with_identities(&oracle, &candidate, case)
        .map_err(|error| format!("cannot replay minimized regression: {error}"))?;
    if baseline.mismatches.is_empty() {
        return Err("replayed minimized regression no longer mismatches".to_owned());
    }
    verify_regression_trial(case, &baseline)?;
    let minimization = json_member(proposal, "minimization")?.object()?;
    let trace_path = confined_record_path(
        root,
        package,
        Path::new(json_member(minimization, "tracePath")?.string()?),
    )?;
    let trace = parse_json(&read_text(&trace_path)?)?;
    for attempt in json_member(trace.object()?, "attempts")?.array()? {
        replay_regression_attempt(
            root,
            package,
            attempt.object()?,
            case,
            &oracle,
            &candidate,
            &baseline.mismatches,
        )?;
    }
    Ok(())
}

fn retained_regression_executable(
    root: &Path,
    package: &Path,
    proposal: &BTreeMap<String, JsonValue>,
    path_key: &str,
    digest_key: &str,
    role: ExecutableRole,
) -> Result<ExecutableIdentity, String> {
    let path = confined_record_path(
        root,
        package,
        Path::new(json_member(proposal, path_key)?.string()?),
    )?;
    let digest = Digest::from_hex(json_member(proposal, digest_key)?.string()?)
        .map_err(|_| format!("regression {digest_key} is invalid"))?;
    verify_executable(&path, role, Some(digest), hell_builtins::LANGUAGE_VERSION)
        .map_err(|error| format!("cannot verify retained regression executable: {error}"))
}

fn replay_regression_attempt(
    root: &Path,
    package: &Path,
    attempt: &BTreeMap<String, JsonValue>,
    case: &DifferentialCase,
    oracle: &ExecutableIdentity,
    candidate: &ExecutableIdentity,
    expected: &[hell_testkit::DifferentialMismatch],
) -> Result<(), String> {
    let path = confined_record_path(
        root,
        package,
        Path::new(json_member(attempt, "path")?.string()?),
    )?;
    let source = read_text(&path)?;
    let mut trial = case.clone();
    trial.source = source.clone().into();
    if let Some(descriptor) = &mut trial.claim_evidence {
        descriptor.source_sha256 = sha256_bytes(source.as_bytes());
    }
    let report = differential_with_identities(oracle, candidate, &trial)
        .map_err(|error| format!("cannot replay regression reduction trial: {error}"))?;
    let preserved =
        report.mismatches == expected && verify_regression_trial(&trial, &report).is_ok();
    if preserved != json_member(attempt, "preservedExactMismatchAndClaimEvidence")?.boolean()? {
        return Err("regression minimization trial result does not replay".to_owned());
    }
    Ok(())
}

fn verify_regression_bundle(
    root: &Path,
    package: &Path,
    proposal: &BTreeMap<String, JsonValue>,
    case: &DifferentialCase,
) -> Result<String, String> {
    let bundle = json_member(proposal, "bundle")?.object()?;
    exact_keys(bundle, &["path", "sha256"])?;
    let bundle_path = confined_record_path(
        root,
        package,
        Path::new(json_member(bundle, "path")?.string()?),
    )?;
    let bundle_sha256 =
        hell_testkit::verify_regression_observation_bundle_for_case(&bundle_path, case)
            .map_err(|error| format!("cannot verify regression observation bundle: {error}"))?
            .hex();
    if bundle_sha256 != json_member(bundle, "sha256")?.string()? {
        return Err("regression bundle digest differs from proposal".to_owned());
    }
    if !matches!(
        hell_testkit::classify_retained_observation_bundle(&bundle_path, case)
            .map_err(|error| format!("cannot classify regression observation bundle: {error}"))?,
        hell_testkit::RetainedObservationClassification::Mismatch { .. }
    ) {
        return Err("regression bundle no longer demonstrates a mismatch".to_owned());
    }
    let reached_inventory =
        hell_testkit::retained_regression_reached_claim_targets(&bundle_path, case)
            .map_err(|error| format!("cannot rederive reached regression claim cells: {error}"))?;
    let reached = hell_testkit::retained_regression_reviewed_claim_targets(&bundle_path, case)
        .map_err(|error| format!("cannot rederive reviewed regression claim cells: {error}"))?;
    if json_member(proposal, "reachedTargetInventory")?
        != &JsonValue::Array(regression_reached_inventory_values(
            &reached_inventory,
            &reached,
        ))
    {
        return Err("regression reached target inventory differs from retained trace".to_owned());
    }
    verify_regression_targets(proposal, &reached)?;
    verify_regression_current_claim_impact(root, package, proposal, &reached)?;
    verify_regression_bundle_identities(&bundle_path, proposal)?;
    Ok(bundle_sha256)
}

fn verify_regression_current_claim_impact(
    root: &Path,
    package: &Path,
    proposal: &BTreeMap<String, JsonValue>,
    reached: &[hell_testkit::RetainedReachedClaimTarget],
) -> Result<(), String> {
    let source = json_member(proposal, "currentClaimEvidence")?.object()?;
    exact_keys(source, &["path", "rootSha256"])?;
    let retained_root = package.join("current-claim-evidence");
    if record_digest(&retained_root)? != json_member(source, "rootSha256")?.string()? {
        return Err("regression current claim evidence root digest differs".to_owned());
    }
    let coverage = confined_record_path(
        root,
        package,
        Path::new(json_member(source, "path")?.string()?),
    )?;
    verify_bound_details(
        &coverage,
        "claim-coverage",
        json_member(proposal, "candidateCommit")?.string()?,
        json_member(proposal, "assuranceEpochSha256")?.string()?,
    )?;
    let rederived = regression_claim_impact(
        &coverage,
        &package
            .join("provider-subject")
            .join("sources")
            .join("public"),
        reached,
        json_member(proposal, "observedPlatform")?.string()?,
        json_member(proposal, "candidateCommit")?.string()?,
        json_member(proposal, "assuranceEpochSha256")?.string()?,
        &read_text(&package.join("surveillance-policy.toml"))?,
    )?;
    if json_member(proposal, "claimImpact")? != &rederived {
        return Err("regression claim impact differs from finalized current coverage".to_owned());
    }
    Ok(())
}

fn verify_regression_identity_fields(proposal: &BTreeMap<String, JsonValue>) -> Result<(), String> {
    if json_member(proposal, "oracleExecutablePath")?.string()? != "executables/oracle"
        || json_member(proposal, "candidateExecutablePath")?.string()? != "executables/candidate"
    {
        return Err("regression retained executable paths are not canonical".to_owned());
    }
    for key in [
        "assuranceEpochSha256",
        "candidateBuildInfoSha256",
        "candidateExecutableSha256",
        "oracleExecutableSha256",
    ] {
        require_digest(json_member(proposal, key)?.string()?, key)?;
    }
    require_git_sha_text(
        json_member(proposal, "candidateCommit")?.string()?,
        "regression candidate commit",
    )?;
    Ok(())
}

fn verify_regression_bundle_identities(
    bundle: &Path,
    proposal: &BTreeMap<String, JsonValue>,
) -> Result<(), String> {
    for (side, digest_key, role) in [
        ("oracle", "oracleExecutableSha256", "Oracle"),
        ("candidate", "candidateExecutableSha256", "Candidate"),
    ] {
        let observation = parse_json(&read_text(&bundle.join(side).join("observation.json"))?)?;
        let identity = json_member(observation.object()?, "identity")?.object()?;
        if json_member(identity, "role")?.string()? != role
            || json_member(identity, "sha256")?.string()?
                != json_member(proposal, digest_key)?.string()?
            || json_member(identity, "assuranceEpochSha256")?.string()?
                != json_member(proposal, "assuranceEpochSha256")?.string()?
        {
            return Err(format!(
                "regression {side} executable identity differs from the proposal"
            ));
        }
        if side == "candidate" {
            let expected =
                regression_expected_build_info(json_member(proposal, "candidateCommit")?.string()?);
            let observed = json_member(identity, "buildInfo")?
                .array()?
                .iter()
                .map(JsonValue::string)
                .collect::<Result<Vec<_>, _>>()?;
            if observed != expected.iter().map(String::as_str).collect::<Vec<_>>()
                || json_member(proposal, "candidateBuildInfoSha256")?.string()?
                    != regression_build_info_sha256(&expected).hex()
            {
                return Err(
                    "regression candidate build info differs from current source".to_owned(),
                );
            }
        }
    }
    Ok(())
}

fn verify_regression_program(
    root: &Path,
    package: &Path,
    value: &JsonValue,
) -> Result<String, String> {
    let record = value.object()?;
    exact_keys(record, &["bytes", "path", "sha256"])?;
    let path = confined_record_path(
        root,
        package,
        Path::new(json_member(record, "path")?.string()?),
    )?;
    let source = read_text(&path)?;
    if json_member(record, "bytes")?.number()? != source.len() as u64
        || json_member(record, "sha256")?.string()? != sha256_bytes(source.as_bytes()).hex()
        || source.is_empty()
        || !source.ends_with('\n')
    {
        return Err("regression program record is not exact canonical source".to_owned());
    }
    Ok(source)
}

fn verify_regression_targets(
    proposal: &BTreeMap<String, JsonValue>,
    reached: &[hell_testkit::RetainedReachedClaimTarget],
) -> Result<(), String> {
    let observed = json_member(proposal, "targets")?.array()?;
    let mut targets = reached.iter().collect::<Vec<_>>();
    targets.sort_by(|left, right| {
        (left.builtin.as_ref(), left.dimension.as_str())
            .cmp(&(right.builtin.as_ref(), right.dimension.as_str()))
    });
    if observed.len() != targets.len() {
        return Err("regression target set cardinality differs".to_owned());
    }
    for (record, target) in observed.iter().zip(targets) {
        let record = record.object()?;
        exact_keys(record, &["builtin", "dimension", "obligations"])?;
        let obligations = json_member(record, "obligations")?
            .array()?
            .iter()
            .map(JsonValue::string)
            .collect::<Result<Vec<_>, _>>()?;
        let mut expected_obligations = target
            .obligations
            .iter()
            .map(|value| value.0.as_ref())
            .collect::<Vec<_>>();
        expected_obligations.sort_unstable();
        if json_member(record, "builtin")?.string()? != target.builtin.as_ref()
            || json_member(record, "dimension")?.string()? != target.dimension.as_str()
            || obligations != expected_obligations
        {
            return Err(
                "regression target or obligation set differs from reviewed template".to_owned(),
            );
        }
    }
    Ok(())
}

fn regression_promote(root: &Path, options: &Options) -> Result<String, String> {
    let package = required_path(
        &options.input,
        "regression-import promote requires --input package",
    )?;
    let review = required_path(
        &options.proposal,
        "regression-import promote requires --proposal signed review",
    )?;
    let policy = required_path(
        &options.policy,
        "regression-import promote requires --policy",
    )?;
    let output = required_path(
        &options.output,
        "regression-import promote requires --output",
    )?;
    let review_subject = required_path(
        &options.from,
        "regression-import promote requires --from provider-bound review subject",
    )?;
    let proposal_selection = PathBuf::from(options.artifact.as_deref().ok_or_else(|| {
        "regression-import promote requires --artifact proposal provider selection".to_owned()
    })?);
    let review_selection = required_path(
        &options.to,
        "regression-import promote requires --to review provider selection",
    )?;
    let verified = verify_regression_package(root, package)?;
    verify_regression_review_subject(
        root,
        package,
        review_subject,
        &proposal_selection,
        &verified,
    )?;
    reverify_regression_provider_selection(
        root,
        review
            .parent()
            .ok_or_else(|| "regression review has no artifact root".to_owned())?,
        review_selection,
        &verified.candidate_commit,
        ".github/workflows/regression-corpus.yml",
    )?;
    require_regression_artifact_class(review_selection, "regression-review-")?;
    let artifacts = BTreeSet::from([record_digest(review_subject)?]);
    verify_review_binding(
        review,
        policy,
        "regression-reviewer",
        &verified.candidate_commit,
        &verified.assurance_epoch,
        &artifacts,
    )?;
    let review_sha256 = record_digest(review)?;
    write_regression_promotion(
        root,
        output,
        verified,
        review_sha256,
        &RegressionDurableSources {
            package,
            review_root: review
                .parent()
                .ok_or_else(|| "regression review has no artifact root".to_owned())?,
            proposal_selection: &proposal_selection,
            review_selection,
        },
    )
}

struct RegressionDurableSources<'a> {
    package: &'a Path,
    review_root: &'a Path,
    proposal_selection: &'a Path,
    review_selection: &'a Path,
}

fn write_regression_promotion(
    root: &Path,
    output: &Path,
    verified: VerifiedRegressionProposal,
    review_sha256: String,
    durable: &RegressionDurableSources<'_>,
) -> Result<String, String> {
    let (proof_path, proof_sha256, repository_tree) =
        write_regression_durable_tree(output, &verified, &review_sha256, durable)?;
    let catalog_entry =
        regression_catalog_entry(&verified, &review_sha256, &proof_path, &proof_sha256);
    let catalog_entry_path = output.with_extension("corpus-entry.tsv");
    write_atomic(&catalog_entry_path, catalog_entry.as_bytes())?;
    let catalog_entry_sha256 = sha256_bytes(catalog_entry.as_bytes()).hex();
    let updated_catalog = regression_updated_catalog(root, &verified.case_id, &catalog_entry)?;
    let updated_catalog_path = output.with_extension("updated-regression-corpus.tsv");
    write_atomic(&updated_catalog_path, updated_catalog.as_bytes())?;
    let updated_catalog_sha256 = sha256_bytes(updated_catalog.as_bytes()).hex();
    let record = JsonValue::Object(BTreeMap::from([
        (
            "assuranceEpochSha256".to_owned(),
            JsonValue::String(verified.assurance_epoch),
        ),
        (
            "bundleSha256".to_owned(),
            JsonValue::String(verified.bundle_sha256),
        ),
        (
            "candidateCommit".to_owned(),
            JsonValue::String(verified.candidate_commit),
        ),
        ("caseId".to_owned(), JsonValue::String(verified.case_id)),
        ("claimEligible".to_owned(), JsonValue::Bool(false)),
        (
            "corpusEntryPath".to_owned(),
            JsonValue::String(path_text(
                catalog_entry_path
                    .file_name()
                    .map(Path::new)
                    .ok_or_else(|| "regression corpus entry has no filename".to_owned())?,
            )?),
        ),
        (
            "corpusEntrySha256".to_owned(),
            JsonValue::String(catalog_entry_sha256),
        ),
        (
            "updatedCorpusPath".to_owned(),
            JsonValue::String(path_text(
                updated_catalog_path
                    .file_name()
                    .map(Path::new)
                    .ok_or_else(|| "updated regression corpus has no filename".to_owned())?,
            )?),
        ),
        (
            "updatedCorpusSha256".to_owned(),
            JsonValue::String(updated_catalog_sha256),
        ),
        (
            "packageSha256".to_owned(),
            JsonValue::String(verified.package_sha256),
        ),
        (
            "proposalSha256".to_owned(),
            JsonValue::String(verified.proposal_sha256),
        ),
        ("reviewSha256".to_owned(), JsonValue::String(review_sha256)),
        (
            "repositoryTreePath".to_owned(),
            JsonValue::String(path_text(
                repository_tree
                    .file_name()
                    .map(Path::new)
                    .ok_or_else(|| "regression repository tree has no filename".to_owned())?,
            )?),
        ),
        (
            "repositoryTreeSha256".to_owned(),
            JsonValue::String(record_digest(&repository_tree)?),
        ),
        (
            "proofManifestSha256".to_owned(),
            JsonValue::String(proof_sha256),
        ),
        ("schemaVersion".to_owned(), JsonValue::Number(1)),
        (
            "sourceSha256".to_owned(),
            JsonValue::String(verified.source_sha256),
        ),
        (
            "state".to_owned(),
            JsonValue::String("reviewed-awaiting-controlled-repository-integration".to_owned()),
        ),
    ]));
    write_atomic(output, &canonical_json_bytes(&record)?)?;
    Ok(format!(
        "promoted reviewed regression descriptor {}",
        output.display()
    ))
}

fn write_regression_durable_tree(
    output: &Path,
    verified: &VerifiedRegressionProposal,
    review_sha256: &str,
    durable: &RegressionDurableSources<'_>,
) -> Result<(String, String, PathBuf), String> {
    let repository_tree = output.with_extension("repository-tree");
    if repository_tree.exists() {
        return Err("regression durable repository tree already exists".to_owned());
    }
    let proof_root = repository_tree
        .join("compat")
        .join("regressions")
        .join(&verified.case_id);
    fs::create_dir_all(&proof_root)
        .map_err(|error| format!("cannot create regression durable proof root: {error}"))?;
    copy_regression_tree(durable.package, &proof_root.join("package"))?;
    copy_regression_tree(durable.review_root, &proof_root.join("review"))?;
    copy_regression_tree(
        durable.proposal_selection,
        &proof_root.join("proposal-selection"),
    )?;
    copy_regression_tree(
        durable.review_selection,
        &proof_root.join("review-selection"),
    )?;
    if record_digest(&proof_root.join("package"))? != verified.package_sha256
        || record_digest(&proof_root.join("review").join("review.dsse.json"))? != review_sha256
    {
        return Err("regression durable proof copy differs from reviewed bytes".to_owned());
    }
    let proof_path = format!("compat/regressions/{}/proof.tsv", verified.case_id);
    let proof = format!(
        "schema_version\t1\ncase_id\t{}\npackage_sha256\t{}\nproposal_sha256\t{}\nreview_sha256\t{}\nbundle_sha256\t{}\nsource_sha256\t{}\ntargets_hex\t{}\n",
        verified.case_id,
        verified.package_sha256,
        verified.proposal_sha256,
        review_sha256,
        verified.bundle_sha256,
        verified.source_sha256,
        hex_text(&verified.targets_descriptor),
    );
    write_atomic(&proof_root.join("proof.tsv"), proof.as_bytes())?;
    Ok((
        proof_path,
        sha256_bytes(proof.as_bytes()).hex(),
        repository_tree,
    ))
}

fn hex_text(value: &str) -> String {
    let mut output = String::with_capacity(value.len().saturating_mul(2));
    for byte in value.as_bytes() {
        write!(output, "{byte:02x}").expect("writing to String cannot fail");
    }
    output
}

fn verify_regression_review_subject(
    root: &Path,
    package: &Path,
    path: &Path,
    selection: &Path,
    verified: &VerifiedRegressionProposal,
) -> Result<(), String> {
    let document = parse_json(&read_text(path)?)?;
    let document = document.object()?;
    exact_keys(
        document,
        &[
            "assuranceEpochSha256",
            "candidateCommit",
            "packageSha256",
            "providerSelectionSha256",
            "proposerAccountId",
            "schemaVersion",
            "state",
        ],
    )?;
    if json_member(document, "schemaVersion")?.number()? != 1
        || json_member(document, "state")?.string()? != "requires-regression-review"
        || json_member(document, "candidateCommit")?.string()? != verified.candidate_commit
        || json_member(document, "assuranceEpochSha256")?.string()? != verified.assurance_epoch
        || json_member(document, "packageSha256")?.string()? != verified.package_sha256
        || json_member(document, "providerSelectionSha256")?.string()? != record_digest(selection)?
    {
        return Err(
            "regression review subject differs from exact package/provider facts".to_owned(),
        );
    }
    reverify_regression_provider_selection(
        root,
        package,
        selection,
        &verified.candidate_commit,
        ".github/workflows/regression-corpus.yml",
    )?;
    require_regression_artifact_class(selection, "regression-proposal-")?;
    let run = parse_json(&read_text(&selection.join("provider-selected-run.json"))?)?;
    if json_member(json_member(run.object()?, "actor")?.object()?, "id")?.number()?
        != json_member(document, "proposerAccountId")?.number()?
    {
        return Err("regression review subject proposer identity differs".to_owned());
    }
    Ok(())
}

fn regression_updated_catalog(
    root: &Path,
    case_id: &str,
    catalog_entry: &str,
) -> Result<String, String> {
    let path = root.join("compat").join("regression-corpus.tsv");
    regression_updated_catalog_text(read_text(&path)?, case_id, catalog_entry)
}

fn regression_updated_catalog_text(
    mut catalog: String,
    case_id: &str,
    catalog_entry: &str,
) -> Result<String, String> {
    if !catalog.ends_with('\n')
        || !catalog.starts_with("schema_version\t2\ncolumns\tcase_id\ttemplate_case_id\t")
    {
        return Err("committed regression corpus header is not canonical".to_owned());
    }
    let prefix = format!("{case_id}\t");
    if catalog.lines().any(|line| line.starts_with(&prefix)) {
        return Err("reviewed regression case already exists in committed corpus".to_owned());
    }
    let row = catalog_entry.strip_suffix('\n').ok_or_else(|| {
        "reviewed regression catalog entry lacks its canonical newline".to_owned()
    })?;
    let columns = row.split('\t').collect::<Vec<_>>();
    if row.contains(['\r', '\n'])
        || columns.len() != 13
        || columns.iter().any(|column| column.is_empty())
        || columns.first().copied() != Some(case_id)
        || !catalog_entry.starts_with(&prefix)
    {
        return Err("reviewed regression catalog entry is not one canonical row".to_owned());
    }
    catalog.push_str(catalog_entry);
    Ok(catalog)
}

fn regression_catalog_entry(
    verified: &VerifiedRegressionProposal,
    review_sha256: &str,
    proof_path: &str,
    proof_sha256: &str,
) -> String {
    let source_hex = hex_text(&verified.source);
    let targets_hex = hex_text(&verified.targets_descriptor);
    format!(
        "{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\n",
        verified.case_id,
        verified.template_case_id,
        source_hex,
        verified.source_sha256,
        verified.candidate_commit,
        verified.assurance_epoch,
        verified.package_sha256,
        verified.proposal_sha256,
        review_sha256,
        verified.bundle_sha256,
        targets_hex,
        proof_path,
        proof_sha256,
    )
}

fn directory_manifest(root: &Path) -> Result<String, String> {
    let mut files = Vec::new();
    collect_manifest_files(root, root, &mut files)?;
    files.sort_by(|left, right| left.0.cmp(&right.0));
    Ok(render_directory_manifest(&files))
}

fn directory_manifest_excluding(root: &Path, excluded: &Path) -> Result<String, String> {
    let mut files = Vec::new();
    collect_manifest_files(root, root, &mut files)?;
    files.retain(|(path, _, _)| !Path::new(path).starts_with(excluded));
    files.sort_by(|left, right| left.0.cmp(&right.0));
    Ok(render_directory_manifest(&files))
}

fn render_directory_manifest(files: &[(String, Digest, u64)]) -> String {
    let mut json = String::from(
        "{\n  \"schemaVersion\": 1,\n  \"format\": \"merkle-directory-v1\",\n  \"files\": [",
    );
    for (index, (path, digest, size)) in files.iter().enumerate() {
        if index != 0 {
            json.push(',');
        }
        json.push_str("\n    {\"path\": ");
        push_json(&mut json, path);
        write!(
            json,
            ", \"sha256\": \"{}\", \"size\": {size}}}",
            digest.hex()
        )
        .expect("writing to String cannot fail");
    }
    json.push_str("\n  ]\n}\n");
    json
}

pub(crate) fn record_digest(path: &Path) -> Result<String, String> {
    let metadata = fs::symlink_metadata(path)
        .map_err(|error| format!("cannot inspect record {}: {error}", path.display()))?;
    if metadata.file_type().is_symlink() {
        return Err(format!("record {} must not be a symlink", path.display()));
    }
    if metadata.is_dir() {
        Ok(sha256_bytes(directory_manifest(path)?.as_bytes()).hex())
    } else if metadata.is_file() {
        let bytes = read_regular_file(path)?;
        Ok(sha256_bytes(&bytes).hex())
    } else {
        Err(format!(
            "record {} is not a regular file or directory",
            path.display()
        ))
    }
}

fn record_size(path: &Path) -> Result<u64, String> {
    let metadata = fs::symlink_metadata(path)
        .map_err(|error| format!("cannot inspect record {}: {error}", path.display()))?;
    if metadata.file_type().is_symlink() {
        return Err(format!("record {} must not be a symlink", path.display()));
    }
    if metadata.is_file() {
        return Ok(metadata.len());
    }
    if !metadata.is_dir() {
        return Err(format!(
            "record {} is not a regular file or directory",
            path.display()
        ));
    }
    let mut total = 0_u64;
    let mut entries = fs::read_dir(path)
        .map_err(|error| format!("cannot enumerate {}: {error}", path.display()))?
        .collect::<Result<Vec<_>, _>>()
        .map_err(|error| format!("cannot enumerate {}: {error}", path.display()))?;
    entries.sort_by_key(std::fs::DirEntry::file_name);
    for entry in entries {
        total = total
            .checked_add(record_size(&entry.path())?)
            .ok_or_else(|| "record size exceeds u64".to_owned())?;
    }
    Ok(total)
}

fn confined_record_path(
    root: &Path,
    retained_root: &Path,
    declared: &Path,
) -> Result<PathBuf, String> {
    let retained = if retained_root.is_absolute() {
        retained_root.to_path_buf()
    } else {
        root.join(retained_root)
    };
    let candidate = if declared.is_absolute() {
        declared.to_path_buf()
    } else {
        retained.join(declared)
    };
    let retained = fs::canonicalize(&retained).map_err(|error| {
        format!(
            "cannot resolve retained evidence root {}: {error}",
            retained.display()
        )
    })?;
    let candidate = fs::canonicalize(&candidate).map_err(|error| {
        format!(
            "cannot resolve retained record {}: {error}",
            candidate.display()
        )
    })?;
    if !candidate.starts_with(&retained) || candidate == retained {
        return Err(format!(
            "retained record {} escapes evidence root {}",
            candidate.display(),
            retained.display()
        ));
    }
    record_digest(&candidate)?;
    Ok(candidate)
}

fn verify_file_digest(path: &Path, expected: &str, label: &str) -> Result<(), String> {
    require_digest(expected, label)?;
    let observed = sha256_bytes(&read_regular_file(path)?).hex();
    verify_retained_artifact_digest(expected, &observed, label)
}

fn verify_retained_artifact_digest(
    expected: &str,
    observed: &str,
    label: &str,
) -> Result<(), String> {
    require_digest(expected, label)?;
    require_digest(observed, label)?;
    if expected != observed
        && !crate::assurance_control_mutant_active("artifact-bytes-declared-hash")
    {
        return Err(format!(
            "{label} mismatch: expected {expected}, observed {observed}"
        ));
    }
    Ok(())
}

fn verify_provider_run_attempt(expected: u64, observed: u64) -> Result<(), String> {
    if expected == 0 || observed == 0 {
        return Err("provider run attempt must be nonzero".to_owned());
    }
    if expected != observed
        && !crate::assurance_control_mutant_active("artifact-run-attempt-substitution")
    {
        return Err("provider run attempt was substituted".to_owned());
    }
    Ok(())
}

fn verify_provider_repository(expected: &str, observed: &str) -> Result<(), String> {
    if expected.is_empty() || observed.is_empty() {
        return Err("provider repository identity is empty".to_owned());
    }
    if expected != observed
        && !crate::assurance_control_mutant_active("artifact-repository-fork-substitution")
    {
        return Err("provider repository was substituted with a fork".to_owned());
    }
    Ok(())
}

fn verify_independent_trust_domains(primary: &str, independent: &str) -> Result<(), String> {
    if primary == independent
        && !crate::assurance_control_mutant_active("acquisition-trust-domain-alias")
    {
        return Err("acquisition receipts do not span two trust domains".to_owned());
    }
    Ok(())
}

fn collect_manifest_files(
    root: &Path,
    directory: &Path,
    files: &mut Vec<(String, Digest, u64)>,
) -> Result<(), String> {
    let mut entries = fs::read_dir(directory)
        .map_err(|error| format!("cannot enumerate {}: {error}", directory.display()))?
        .collect::<Result<Vec<_>, _>>()
        .map_err(|error| format!("cannot enumerate {}: {error}", directory.display()))?;
    entries.sort_by_key(std::fs::DirEntry::file_name);
    for entry in entries {
        let path = entry.path();
        let kind = entry
            .file_type()
            .map_err(|error| format!("cannot inspect {}: {error}", path.display()))?;
        if kind.is_dir() {
            collect_manifest_files(root, &path, files)?;
        } else if kind.is_file() {
            let bytes = read_regular_file(&path)?;
            let relative = path
                .strip_prefix(root)
                .map_err(|_| "manifest path escaped root".to_owned())?;
            files.push((
                path_text(relative)?,
                sha256_bytes(&bytes),
                u64::try_from(bytes.len()).map_err(|_| "file size exceeds u64".to_owned())?,
            ));
        } else {
            return Err(format!(
                "manifest entry {} is a symlink or special file",
                path.display()
            ));
        }
    }
    Ok(())
}

fn read_regular_file(path: &Path) -> Result<Vec<u8>, String> {
    let before = fs::symlink_metadata(path)
        .map_err(|error| format!("cannot inspect {}: {error}", path.display()))?;
    if !before.is_file() || before.file_type().is_symlink() {
        return Err(format!(
            "{} is not a regular non-symlink file",
            path.display()
        ));
    }
    let bytes =
        fs::read(path).map_err(|error| format!("cannot read {}: {error}", path.display()))?;
    let after = fs::symlink_metadata(path)
        .map_err(|error| format!("cannot re-inspect {}: {error}", path.display()))?;
    if !after.is_file()
        || after.file_type().is_symlink()
        || before.len() != after.len()
        || u64::try_from(bytes.len()).map_err(|_| "file size exceeds u64".to_owned())?
            != after.len()
    {
        return Err(format!("{} changed while it was hashed", path.display()));
    }
    Ok(bytes)
}

fn line_diff(from: &str, to: &str) -> String {
    let old = from.lines().collect::<BTreeSet<_>>();
    let new = to.lines().collect::<BTreeSet<_>>();
    let mut output = String::from("# Assurance epoch diff\n");
    for line in old.difference(&new) {
        writeln!(output, "- {line}").expect("writing to String cannot fail");
    }
    for line in new.difference(&old) {
        writeln!(output, "+ {line}").expect("writing to String cannot fail");
    }
    output
}

fn assurance_report(passed: bool, blockers: &[&str]) -> String {
    let mut json = format!(
        "{{\n  \"schemaVersion\": 1,\n  \"scope\": \"repository-structure\",\n  \"passed\": {passed},\n  \"promotionReady\": false,\n  \"blockers\": ["
    );
    for (index, blocker) in blockers.iter().enumerate() {
        if index != 0 {
            json.push_str(", ");
        }
        push_json(&mut json, blocker);
    }
    json.push_str("]\n}\n");
    json
}

#[allow(clippy::ref_option)]
fn required_path<'a>(path: &'a Option<PathBuf>, message: &str) -> Result<&'a Path, String> {
    path.as_deref().ok_or_else(|| message.to_owned())
}

fn read_text(path: &Path) -> Result<String, String> {
    fs::read_to_string(path).map_err(|error| format!("cannot read {}: {error}", path.display()))
}

fn write_atomic(path: &Path, bytes: &[u8]) -> Result<(), String> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)
            .map_err(|error| format!("cannot create {}: {error}", parent.display()))?;
    }
    let file_name = path
        .file_name()
        .and_then(OsStr::to_str)
        .ok_or_else(|| format!("output name {} is not UTF-8", path.display()))?;
    let nonce = TEMPORARY_NONCE.fetch_add(1, Ordering::Relaxed);
    let temporary = path.with_file_name(format!(
        ".{file_name}.hell-ci-{}-{nonce}",
        std::process::id()
    ));
    if fs::symlink_metadata(path)
        .is_ok_and(|metadata| metadata.file_type().is_symlink() || !metadata.is_file())
    {
        return Err(format!(
            "refusing to replace non-regular output {}",
            path.display()
        ));
    }
    let mut file = fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(&temporary)
        .map_err(|error| format!("cannot create {}: {error}", temporary.display()))?;
    if let Err(error) = file.write_all(bytes).and_then(|()| file.sync_all()) {
        drop(file);
        let _ = fs::remove_file(&temporary);
        return Err(format!("cannot write {}: {error}", temporary.display()));
    }
    drop(file);
    fs::rename(&temporary, path)
        .map_err(|error| format!("cannot replace {}: {error}", path.display()))
}

fn create_private_temp_directory(prefix: &str) -> Result<PathBuf, String> {
    loop {
        let nonce = TEMPORARY_NONCE.fetch_add(1, Ordering::Relaxed);
        let directory =
            std::env::temp_dir().join(format!("{prefix}-{}-{nonce}", std::process::id()));
        match fs::create_dir(&directory) {
            Ok(()) => {
                #[cfg(unix)]
                {
                    use std::os::unix::fs::PermissionsExt as _;
                    fs::set_permissions(&directory, fs::Permissions::from_mode(0o700)).map_err(
                        |error| format!("cannot protect {}: {error}", directory.display()),
                    )?;
                }
                return Ok(directory);
            }
            Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => {}
            Err(error) => {
                return Err(format!(
                    "cannot create private temporary directory: {error}"
                ));
            }
        }
    }
}

fn write_digest_sibling(path: &Path, digest: Digest) -> Result<(), String> {
    let name = path
        .file_name()
        .and_then(OsStr::to_str)
        .ok_or_else(|| "output name must be UTF-8".to_owned())?;
    let digest_path = path.with_extension("sha256");
    write_atomic(
        &digest_path,
        format!("{}  {name}\n", digest.hex()).as_bytes(),
    )
}

fn git_output(root: &Path, arguments: &[&str]) -> Result<String, String> {
    String::from_utf8(git_output_bytes(root, arguments)?)
        .map_err(|_| "git output is not UTF-8".to_owned())
}

fn git_output_bytes(root: &Path, arguments: &[&str]) -> Result<Vec<u8>, String> {
    let output = Command::new("git")
        .args(arguments)
        .current_dir(root)
        .output()
        .map_err(|error| format!("cannot run git: {error}"))?;
    if !output.status.success() {
        return Err(format!(
            "git {:?} failed: {}",
            arguments,
            String::from_utf8_lossy(&output.stderr)
        ));
    }
    Ok(output.stdout)
}

fn path_text(path: &Path) -> Result<String, String> {
    let mut text = path
        .to_str()
        .ok_or_else(|| format!("path {} is not UTF-8", path.display()))?
        .replace('\\', "/");
    while let Some(stripped) = text.strip_prefix("./") {
        text = stripped.to_owned();
    }
    Ok(text)
}

fn require_digest(value: &str, label: &str) -> Result<(), String> {
    Digest::from_hex(value)
        .map(|_| ())
        .map_err(|error| format!("{label}: {error}"))
}

pub(crate) fn json_string(value: &str) -> String {
    let mut output = String::new();
    push_json(&mut output, value);
    output
}

fn push_json(output: &mut String, value: &str) {
    output.push('"');
    for character in value.chars() {
        match character {
            '"' => output.push_str("\\\""),
            '\\' => output.push_str("\\\\"),
            '\n' => output.push_str("\\n"),
            '\r' => output.push_str("\\r"),
            '\t' => output.push_str("\\t"),
            character if character <= '\u{1f}' => {
                write!(output, "\\u{:04x}", u32::from(character))
                    .expect("writing to String cannot fail");
            }
            character => output.push(character),
        }
    }
    output.push('"');
}

fn push_json_value(output: &mut String, value: &JsonValue) -> Result<(), String> {
    match value {
        JsonValue::Null => output.push_str("null"),
        JsonValue::Bool(value) => output.push_str(if *value { "true" } else { "false" }),
        JsonValue::Number(value) => write!(output, "{value}")
            .map_err(|error| format!("cannot serialize JSON number: {error}"))?,
        JsonValue::String(value) => push_json(output, value),
        JsonValue::Array(values) => {
            output.push('[');
            for (index, value) in values.iter().enumerate() {
                if index != 0 {
                    output.push(',');
                }
                push_json_value(output, value)?;
            }
            output.push(']');
        }
        JsonValue::Object(values) => {
            output.push('{');
            for (index, (key, value)) in values.iter().enumerate() {
                if index != 0 {
                    output.push(',');
                }
                push_json(output, key);
                output.push(':');
                push_json_value(output, value)?;
            }
            output.push('}');
        }
    }
    Ok(())
}

pub(crate) fn decode_base64(value: &str) -> Result<Vec<u8>, String> {
    if !value.len().is_multiple_of(4) {
        return Err("base64 length is not divisible by four".to_owned());
    }
    let mut output = Vec::with_capacity(value.len() / 4 * 3);
    for chunk in value.as_bytes().chunks_exact(4) {
        let first = base64_value(chunk[0])?;
        let second = base64_value(chunk[1])?;
        let third_padding = chunk[2] == b'=';
        let fourth_padding = chunk[3] == b'=';
        if third_padding && !fourth_padding {
            return Err("invalid base64 padding".to_owned());
        }
        let third = if third_padding {
            0
        } else {
            base64_value(chunk[2])?
        };
        let fourth = if fourth_padding {
            0
        } else {
            base64_value(chunk[3])?
        };
        output.push((first << 2) | (second >> 4));
        if !third_padding {
            output.push((second << 4) | (third >> 2));
        }
        if !fourth_padding {
            output.push((third << 6) | fourth);
        }
    }
    Ok(output)
}

pub(crate) fn encode_base64(bytes: &[u8]) -> String {
    const ALPHABET: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut output = String::with_capacity(bytes.len().div_ceil(3) * 4);
    for chunk in bytes.chunks(3) {
        let first = chunk[0];
        let second = chunk.get(1).copied().unwrap_or(0);
        let third = chunk.get(2).copied().unwrap_or(0);
        output.push(char::from(ALPHABET[usize::from(first >> 2)]));
        output.push(char::from(
            ALPHABET[usize::from(((first & 0x03) << 4) | (second >> 4))],
        ));
        if chunk.len() > 1 {
            output.push(char::from(
                ALPHABET[usize::from(((second & 0x0f) << 2) | (third >> 6))],
            ));
        } else {
            output.push('=');
        }
        if chunk.len() > 2 {
            output.push(char::from(ALPHABET[usize::from(third & 0x3f)]));
        } else {
            output.push('=');
        }
    }
    output
}

fn base64_value(byte: u8) -> Result<u8, String> {
    match byte {
        b'A'..=b'Z' => Ok(byte - b'A'),
        b'a'..=b'z' => Ok(byte - b'a' + 26),
        b'0'..=b'9' => Ok(byte - b'0' + 52),
        b'+' => Ok(62),
        b'/' => Ok(63),
        _ => Err("invalid base64 character".to_owned()),
    }
}

fn require_git_sha_text(value: &str, label: &str) -> Result<(), String> {
    if value.len() != hell_builtins::UPSTREAM_COMMIT.len()
        || value.bytes().all(|byte| byte == b'0')
        || !value
            .bytes()
            .all(|byte| byte.is_ascii_digit() || matches!(byte, b'a'..=b'f'))
    {
        return Err(format!("{label} is not a lowercase full Git SHA"));
    }
    Ok(())
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) enum JsonValue {
    Null,
    Bool(bool),
    Number(u64),
    String(String),
    Array(Vec<Self>),
    Object(BTreeMap<String, Self>),
}

impl JsonValue {
    pub(crate) fn object(&self) -> Result<&BTreeMap<String, Self>, String> {
        match self {
            Self::Object(value) => Ok(value),
            _ => Err("expected JSON object".to_owned()),
        }
    }

    fn object_mut(&mut self) -> Result<&mut BTreeMap<String, Self>, String> {
        match self {
            Self::Object(value) => Ok(value),
            _ => Err("expected JSON object".to_owned()),
        }
    }

    pub(crate) fn string(&self) -> Result<&str, String> {
        match self {
            Self::String(value) => Ok(value),
            _ => Err("expected JSON string".to_owned()),
        }
    }

    pub(crate) fn number(&self) -> Result<u64, String> {
        match self {
            Self::Number(value) => Ok(*value),
            _ => Err("expected unsigned JSON integer".to_owned()),
        }
    }

    pub(crate) fn boolean(&self) -> Result<bool, String> {
        match self {
            Self::Bool(value) => Ok(*value),
            _ => Err("expected JSON boolean".to_owned()),
        }
    }

    pub(crate) fn array(&self) -> Result<&[Self], String> {
        match self {
            Self::Array(value) => Ok(value),
            _ => Err("expected JSON array".to_owned()),
        }
    }

    fn array_mut(&mut self) -> Result<&mut Vec<Self>, String> {
        match self {
            Self::Array(value) => Ok(value),
            _ => Err("expected JSON array".to_owned()),
        }
    }
}

pub(crate) fn parse_json(document: &str) -> Result<JsonValue, String> {
    let document = crate::fuzz_surfaces::strict_json_record(document.as_bytes())?;
    let mut parser = JsonParser {
        bytes: document.as_bytes(),
        index: 0,
    };
    let value = parser.value()?;
    parser.whitespace();
    if parser.index != parser.bytes.len() {
        return Err(format!("trailing JSON data at byte {}", parser.index));
    }
    Ok(value)
}

struct JsonParser<'a> {
    bytes: &'a [u8],
    index: usize,
}

impl JsonParser<'_> {
    fn value(&mut self) -> Result<JsonValue, String> {
        self.whitespace();
        match self.peek() {
            Some(b'{') => self.object(),
            Some(b'[') => self.array(),
            Some(b'"') => self.string().map(JsonValue::String),
            Some(b't') => self.keyword(b"true", JsonValue::Bool(true)),
            Some(b'f') => self.keyword(b"false", JsonValue::Bool(false)),
            Some(b'n') => self.keyword(b"null", JsonValue::Null),
            Some(b'0'..=b'9') => self.number(),
            Some(byte) => Err(format!("unexpected JSON byte {byte:?} at {}", self.index)),
            None => Err("unexpected end of JSON".to_owned()),
        }
    }

    fn object(&mut self) -> Result<JsonValue, String> {
        self.take(b'{')?;
        let mut values = BTreeMap::new();
        self.whitespace();
        if self.consume(b'}') {
            return Ok(JsonValue::Object(values));
        }
        loop {
            self.whitespace();
            let key = self.string()?;
            self.whitespace();
            self.take(b':')?;
            let value = self.value()?;
            if values.insert(key.clone(), value).is_some() {
                return Err(format!("duplicate JSON object key {key:?}"));
            }
            self.whitespace();
            if self.consume(b'}') {
                break;
            }
            self.take(b',')?;
        }
        Ok(JsonValue::Object(values))
    }

    fn array(&mut self) -> Result<JsonValue, String> {
        self.take(b'[')?;
        let mut values = Vec::new();
        self.whitespace();
        if self.consume(b']') {
            return Ok(JsonValue::Array(values));
        }
        loop {
            values.push(self.value()?);
            self.whitespace();
            if self.consume(b']') {
                break;
            }
            self.take(b',')?;
        }
        Ok(JsonValue::Array(values))
    }

    fn string(&mut self) -> Result<String, String> {
        self.take(b'"')?;
        let mut output = String::new();
        loop {
            let byte = self
                .next()
                .ok_or_else(|| "unterminated JSON string".to_owned())?;
            match byte {
                b'"' => return Ok(output),
                b'\\' => {
                    let escaped = self
                        .next()
                        .ok_or_else(|| "unterminated JSON escape".to_owned())?;
                    match escaped {
                        b'"' => output.push('"'),
                        b'\\' => output.push('\\'),
                        b'/' => output.push('/'),
                        b'b' => output.push('\u{8}'),
                        b'f' => output.push('\u{c}'),
                        b'n' => output.push('\n'),
                        b'r' => output.push('\r'),
                        b't' => output.push('\t'),
                        b'u' => output.push(self.unicode_escape()?),
                        _ => return Err(format!("invalid JSON escape at byte {}", self.index)),
                    }
                }
                0..=31 => return Err(format!("control byte in JSON string at {}", self.index)),
                32..=127 => output.push(char::from(byte)),
                _ => {
                    let start = self.index - 1;
                    let width = utf8_width(byte)?;
                    let end = start
                        .checked_add(width)
                        .ok_or_else(|| "JSON index overflow".to_owned())?;
                    let bytes = self
                        .bytes
                        .get(start..end)
                        .ok_or_else(|| "truncated UTF-8 in JSON string".to_owned())?;
                    let text = std::str::from_utf8(bytes)
                        .map_err(|_| "invalid UTF-8 in JSON string".to_owned())?;
                    output.push_str(text);
                    self.index = end;
                }
            }
        }
    }

    fn unicode_escape(&mut self) -> Result<char, String> {
        let mut value = 0_u32;
        for _ in 0..4 {
            let byte = self
                .next()
                .ok_or_else(|| "truncated JSON unicode escape".to_owned())?;
            let nibble = u32::from(hex_nibble(byte)?);
            value = value
                .checked_mul(16)
                .and_then(|value| value.checked_add(nibble))
                .ok_or_else(|| "JSON unicode escape overflow".to_owned())?;
        }
        char::from_u32(value).ok_or_else(|| "invalid JSON unicode scalar".to_owned())
    }

    fn number(&mut self) -> Result<JsonValue, String> {
        let start = self.index;
        if self.consume(b'0') {
            if self.peek().is_some_and(|byte| byte.is_ascii_digit()) {
                return Err("JSON integer has a leading zero".to_owned());
            }
        } else {
            while self.peek().is_some_and(|byte| byte.is_ascii_digit()) {
                self.index += 1;
            }
        }
        let text = std::str::from_utf8(&self.bytes[start..self.index])
            .map_err(|_| "JSON number is not UTF-8".to_owned())?;
        let value = text
            .parse::<u64>()
            .map_err(|_| "JSON integer is out of range".to_owned())?;
        Ok(JsonValue::Number(value))
    }

    fn keyword(&mut self, keyword: &[u8], value: JsonValue) -> Result<JsonValue, String> {
        if self.bytes.get(self.index..self.index + keyword.len()) != Some(keyword) {
            return Err(format!("invalid JSON keyword at byte {}", self.index));
        }
        self.index += keyword.len();
        Ok(value)
    }

    fn whitespace(&mut self) {
        while self
            .peek()
            .is_some_and(|byte| matches!(byte, b' ' | b'\n' | b'\r' | b'\t'))
        {
            self.index += 1;
        }
    }

    fn take(&mut self, expected: u8) -> Result<(), String> {
        if self.consume(expected) {
            Ok(())
        } else {
            Err(format!("expected JSON byte {expected:?} at {}", self.index))
        }
    }

    fn consume(&mut self, expected: u8) -> bool {
        if self.peek() == Some(expected) {
            self.index += 1;
            true
        } else {
            false
        }
    }

    fn peek(&self) -> Option<u8> {
        self.bytes.get(self.index).copied()
    }

    fn next(&mut self) -> Option<u8> {
        let byte = self.peek()?;
        self.index += 1;
        Some(byte)
    }
}

fn utf8_width(first: u8) -> Result<usize, String> {
    match first {
        0xc2..=0xdf => Ok(2),
        0xe0..=0xef => Ok(3),
        0xf0..=0xf4 => Ok(4),
        _ => Err("invalid UTF-8 leading byte in JSON string".to_owned()),
    }
}

fn hex_nibble(byte: u8) -> Result<u8, String> {
    match byte {
        b'0'..=b'9' => Ok(byte - b'0'),
        b'a'..=b'f' => Ok(byte - b'a' + 10),
        b'A'..=b'F' => Ok(byte - b'A' + 10),
        _ => Err("invalid hexadecimal JSON escape".to_owned()),
    }
}

pub(crate) fn json_member<'a>(
    object: &'a BTreeMap<String, JsonValue>,
    name: &str,
) -> Result<&'a JsonValue, String> {
    object
        .get(name)
        .ok_or_else(|| format!("missing JSON field {name}"))
}

fn json_member_mut<'a>(
    object: &'a mut BTreeMap<String, JsonValue>,
    name: &str,
) -> Result<&'a mut JsonValue, String> {
    object
        .get_mut(name)
        .ok_or_else(|| format!("missing JSON field {name}"))
}

fn exact_keys(object: &BTreeMap<String, JsonValue>, expected: &[&str]) -> Result<(), String> {
    let expected = expected.iter().copied().collect::<BTreeSet<_>>();
    let observed = object.keys().map(String::as_str).collect::<BTreeSet<_>>();
    if observed != expected {
        return Err(format!(
            "JSON object keys differ: expected {expected:?}, observed {observed:?}"
        ));
    }
    Ok(())
}

pub(crate) fn require_exact_json_keys(
    object: &BTreeMap<String, JsonValue>,
    expected: &[&str],
) -> Result<(), String> {
    exact_keys(object, expected)
}

