    #[test]
    fn synthetic_finalized_claim_rejects_counter_and_source_substitution() {
        let directory = create_private_temp_directory("hell-synthetic-finalized-claim").unwrap();
        let candidate = test_git_sha('a');
        let epoch = test_digest(b"synthetic finalized epoch");
        let shards = REQUIRED_CLAIM_PLATFORMS
            .iter()
            .map(|platform| (*platform, test_digest(platform.as_bytes())))
            .collect::<Vec<_>>();
        let finalized =
            build_synthetic_finalized_claim_authority(&directory, &candidate, &epoch, &shards)
                .unwrap();
        assert!(
            verify_with_production_claim_coverage_parser(&finalized, &candidate, &epoch).is_err()
        );

        let original = read_regular_file(&finalized).unwrap();
        let mut changed = parse_json(std::str::from_utf8(&original).unwrap())
            .unwrap()
            .object()
            .unwrap()
            .clone();
        changed.insert("ambiguousClaimScopes".to_owned(), JsonValue::Number(1));
        write_atomic(
            &finalized,
            &canonical_json_bytes(&JsonValue::Object(changed)).unwrap(),
        )
        .unwrap();
        assert!(
            verify_synthetic_finalized_claim_authority(&finalized, &candidate, &epoch, &shards)
                .is_err()
        );
        write_atomic(&finalized, &original).unwrap();

        let source = directory.join("synthetic-finalized-claim/source.json");
        let mut source_document = parse_json(&read_text(&source).unwrap())
            .unwrap()
            .object()
            .unwrap()
            .clone();
        source_document.insert("totalClaimCells".to_owned(), JsonValue::Number(4));
        write_atomic(
            &source,
            &canonical_json_bytes(&JsonValue::Object(source_document)).unwrap(),
        )
        .unwrap();
        let mut finalized_document = parse_json(&read_text(&finalized).unwrap())
            .unwrap()
            .object()
            .unwrap()
            .clone();
        finalized_document.insert(
            "sourceCoverageSha256".to_owned(),
            JsonValue::String(record_digest(&source).unwrap()),
        );
        write_atomic(
            &finalized,
            &canonical_json_bytes(&JsonValue::Object(finalized_document)).unwrap(),
        )
        .unwrap();
        assert!(
            verify_synthetic_finalized_claim_authority(&finalized, &candidate, &epoch, &shards)
                .is_err()
        );
        fs::remove_dir_all(directory).unwrap();
    }

