    #[test]
    fn divergence_prototype_manifest_is_canonical_and_fail_closed() {
        let repository = root();
        let manifest = parse_divergence_prototype_manifest(
            &repository,
            &repository.join("compat").join("divergence-prototypes.json"),
        )
        .unwrap();
        assert!(manifest.entries.is_empty());
        assert_eq!(manifest.policy.changed_files, 1);
        assert_eq!(manifest.policy.elapsed_seconds, 900);
        assert_eq!(manifest.policy.patch_bytes, 65_536);

        let directory = create_private_temp_directory("hell-prototype-manifest-test").unwrap();
        let substituted = directory.join("manifest.json");
        fs::write(
            &substituted,
            b"{\"entries\":[],\"policy\":{\"maxChangedFiles\":1,\"maxElapsedSeconds\":900,\"maxPatchBytes\":65536},\"schemaVersion\":1,\"unexpected\":true}\n",
        )
        .unwrap();
        assert!(parse_divergence_prototype_manifest(&repository, &substituted).is_err());
        let _ = fs::remove_dir_all(directory);
    }

    #[test]
    fn divergence_prototype_cost_and_failure_facts_reject_substitution() {
        let repository = root();
        let case = committed_differential_cases()
            .into_iter()
            .find(|case| case.id.as_ref() == "int-plus-boundary-positive-value")
            .unwrap();
        let entry = synthetic_prototype_entry(&repository, &case);
        let cost_manifest = DivergencePrototypeManifest {
            entries: BTreeMap::from([(case.id.to_string(), entry.clone())]),
            policy: DivergencePrototypePolicy {
                changed_files: 1,
                elapsed_seconds: 1,
                patch_bytes: 65_536,
            },
            sha256: test_digest(b"cost manifest"),
        };
        let estimate = divergence_prototype_experiment_budget_milliseconds(&case, &entry).unwrap();
        let cost = cost_exceeded_divergence_prototype(&repository, &case, &cost_manifest, estimate)
            .unwrap();
        assert_eq!(
            verify_cost_exceeded_divergence_prototype(
                &repository,
                &case,
                &cost_manifest,
                cost.object().unwrap(),
            )
            .unwrap(),
            "not-currently-fixable"
        );
        let mut changed_cost = cost.clone();
        *json_member_mut(
            changed_cost.object_mut().unwrap(),
            "estimatedExecutionMilliseconds",
        )
        .unwrap() = JsonValue::Number(estimate.saturating_add(1));
        assert!(
            verify_cost_exceeded_divergence_prototype(
                &repository,
                &case,
                &cost_manifest,
                changed_cost.object().unwrap(),
            )
            .is_err()
        );

        let failure_manifest = DivergencePrototypeManifest {
            entries: BTreeMap::from([(case.id.to_string(), entry.clone())]),
            policy: DivergencePrototypePolicy {
                changed_files: 1,
                elapsed_seconds: 900,
                patch_bytes: 65_536,
            },
            sha256: test_digest(b"failure manifest"),
        };
        let tree = git_output(&repository, &["rev-parse", "HEAD^{tree}"])
            .unwrap()
            .trim()
            .to_owned();
        let trees = DivergencePrototypeTreeFacts {
            base_sha256: sha256_bytes(tree.as_bytes()).hex(),
            patched_sha256: sha256_bytes(tree.as_bytes()).hex(),
            base_id: tree.clone(),
            patched_id: tree,
        };
        let executable = std::env::current_exe().unwrap();
        let build = CommandSpec::new(executable, std::time::Duration::from_secs(5))
            .argument("--definitely-not-a-valid-test-argument")
            .run()
            .unwrap();
        assert!(!build.status.success());
        let failure = failed_divergence_prototype_evidence(
            &repository,
            &case,
            &entry,
            &failure_manifest,
            &trees,
            1,
            &build,
        )
        .unwrap();
        assert_eq!(
            verify_failed_divergence_prototype(
                &repository,
                &case,
                &failure_manifest,
                failure.object().unwrap(),
            )
            .unwrap(),
            "undetermined"
        );
        let mut changed_failure = failure;
        *json_member_mut(changed_failure.object_mut().unwrap(), "patchSha256").unwrap() =
            JsonValue::String(test_digest(b"changed failure patch"));
        assert!(
            verify_failed_divergence_prototype(
                &repository,
                &case,
                &failure_manifest,
                changed_failure.object().unwrap(),
            )
            .is_err()
        );
    }

    fn synthetic_prototype_entry(
        repository: &Path,
        case: &DifferentialCase,
    ) -> DivergencePrototypeEntry {
        DivergencePrototypeEntry {
            after_source_sha256: test_digest(b"after source"),
            before_source_sha256: test_digest(b"before source"),
            builtin: "Int.plus".to_owned(),
            case_id: case.id.to_string(),
            dimension: CompatibilityDimension::PureRuntime,
            patch_path: repository.join("synthetic.patch"),
            patch_sha256: test_digest(b"synthetic patch"),
            plan_issue_number: 1,
            plan_owner: "compatibility-team".to_owned(),
            plan_rationale: "Synthetic reviewed repair plan for focused verifier coverage."
                .to_owned(),
            source_path: repository.join("crates/hell-runtime/src/lib.rs"),
        }
    }

    #[test]
    #[ignore = "builds and replays two release executables in isolated git worktrees"]
    fn divergence_prototype_successful_patch_runs_and_replays_end_to_end() {
        let repository = root();
        let temporary = create_private_temp_directory("hell-prototype-e2e").unwrap();
        let subject = temporary.join("subject");
        synthetic_repository_snapshot(&repository, &subject).unwrap();
        let result = synthetic_divergence_prototype_roundtrip(&repository, &subject, &temporary);
        let _ = fs::remove_dir_all(&temporary);
        result.unwrap();
    }

    fn synthetic_repository_snapshot(repository: &Path, subject: &Path) -> Result<(), String> {
        fs::create_dir(subject)
            .map_err(|error| format!("cannot create synthetic repository: {error}"))?;
        let listed = std::process::Command::new("git")
            .args([
                "ls-files",
                "--cached",
                "--others",
                "--exclude-standard",
                "-z",
            ])
            .current_dir(repository)
            .output()
            .map_err(|error| format!("cannot inventory synthetic repository: {error}"))?;
        if !listed.status.success() {
            return Err("cannot inventory synthetic repository".to_owned());
        }
        for bytes in listed.stdout.split(|byte| *byte == 0) {
            if bytes.is_empty() {
                continue;
            }
            let relative = std::str::from_utf8(bytes)
                .map_err(|_| "synthetic repository path is not UTF-8".to_owned())?;
            if relative == ".serena" || relative.starts_with(".serena/") {
                continue;
            }
            let source = repository.join(relative);
            if !source.is_file() {
                continue;
            }
            let destination = subject.join(relative);
            fs::create_dir_all(
                destination
                    .parent()
                    .ok_or_else(|| "synthetic repository file has no parent".to_owned())?,
            )
            .map_err(|error| format!("cannot create synthetic repository directory: {error}"))?;
            fs::copy(&source, &destination)
                .map_err(|error| format!("cannot copy synthetic repository file: {error}"))?;
        }
        let commands = [
            vec!["init", "--quiet"],
            vec!["add", "--all"],
            vec![
                "-c",
                "user.name=Prototype Test",
                "-c",
                "user.email=prototype@example.invalid",
                "commit",
                "--quiet",
                "--no-gpg-sign",
                "-m",
                "synthetic current source snapshot",
            ],
        ];
        for arguments in commands {
            let status = std::process::Command::new("git")
                .args(arguments)
                .current_dir(subject)
                .env("GIT_AUTHOR_DATE", "2026-08-11T00:00:00Z")
                .env("GIT_COMMITTER_DATE", "2026-08-11T00:00:00Z")
                .status()
                .map_err(|error| format!("cannot initialize synthetic repository: {error}"))?;
            if !status.success() {
                return Err("cannot initialize synthetic repository".to_owned());
            }
        }
        Ok(())
    }

    fn synthetic_divergence_prototype_roundtrip(
        repository: &Path,
        subject: &Path,
        temporary: &Path,
    ) -> Result<(), String> {
        let source_relative = Path::new("crates/hell-runtime/src/lib.rs");
        let source = subject.join(source_relative);
        let clean = read_text(&source)?;
        let original = "            \"int_plus\" => value(Value::Int(\n                self.force_int(&arguments[0])?\n                    .wrapping_add(self.force_int(&arguments[1])?),\n            )),";
        let generated_source = hell_testkit::generated_typed_cases(0x4845_4c4c_2026, 1)
            .into_iter()
            .next()
            .ok_or_else(|| "synthetic generated case disappeared".to_owned())?
            .source;
        let operands = generated_source
            .split_once("Int.plus ")
            .and_then(|(_, operands)| operands.trim_end().split_once(' '))
            .ok_or_else(|| "synthetic generated Int.plus source changed".to_owned())?;
        let defective = format!(
            "            \"int_plus\" => {{\n                let left = self.force_int(&arguments[0])?;\n                let right = self.force_int(&arguments[1])?;\n                let result = if (left == 1 && right == 2) || (left == {} && right == {}) {{ left.wrapping_add(right).wrapping_add(1) }} else {{ left.wrapping_add(right) }};\n                value(Value::Int(result))\n            }},",
            operands.0, operands.1
        );
        if clean.matches(original).count() != 1 {
            return Err("synthetic prototype source anchor changed".to_owned());
        }
        fs::write(&source, clean.replacen(original, &defective, 1))
            .map_err(|error| format!("cannot write synthetic defective source: {error}"))?;
        synthetic_git_commit(subject, source_relative)?;
        let defective_source = fs::read(&source)
            .map_err(|error| format!("cannot read synthetic defective source: {error}"))?;
        fs::write(&source, clean.as_bytes())
            .map_err(|error| format!("cannot stage synthetic repaired source: {error}"))?;
        let patch = synthetic_git_diff(subject, source_relative)?;
        fs::write(&source, &defective_source)
            .map_err(|error| format!("cannot restore synthetic defective source: {error}"))?;
        let patch_path = subject.join("prototype.patch");
        fs::write(&patch_path, &patch)
            .map_err(|error| format!("cannot write synthetic prototype patch: {error}"))?;
        let manifest_path = synthetic_prototype_manifest(
            subject,
            source_relative,
            &patch_path,
            &defective_source,
            clean.as_bytes(),
        )?;
        let manifest = parse_divergence_prototype_manifest(subject, &manifest_path)?;
        let case = committed_differential_cases()
            .into_iter()
            .find(|case| case.id.as_ref() == "int-plus-boundary-positive-value")
            .ok_or_else(|| "synthetic prototype case disappeared".to_owned())?;
        let entry = manifest
            .entries
            .get(case.id.as_ref())
            .ok_or_else(|| "synthetic prototype manifest entry disappeared".to_owned())?;
        let (oracle, candidate) =
            prepare_synthetic_prototype_bundles(repository, subject, temporary, &case, entry)?;
        assert_synthetic_regression_descriptor_roundtrip(temporary, &case, &oracle, &candidate)?;
        assert_synthetic_scheduled_exploration_roundtrip(subject, temporary, &oracle, &candidate)?;
        let artifact_root = temporary.join("artifact");
        let output = artifact_root
            .join("divergence-objective")
            .join(case.id.as_ref())
            .join("fix-prototype");
        fs::create_dir_all(&output)
            .map_err(|error| format!("cannot create synthetic prototype output: {error}"))?;
        let evidence = run_targeted_divergence_prototype(
            subject,
            &artifact_root,
            &output,
            &case,
            entry,
            &manifest,
        )?;
        assert_eq!(
            json_member(evidence.object()?, "result")?.string()?,
            "prototype-succeeded"
        );
        assert_eq!(
            verify_retained_divergence_prototype(
                subject,
                artifact_root
                    .parent()
                    .ok_or_else(|| { "synthetic artifact root has no native parent".to_owned() })?,
                "artifact",
                &case,
                &entry.builtin,
                entry.dimension,
                &output,
                &manifest,
                &evidence,
            )?,
            "fix-planned"
        );
        assert_successful_prototype_fact_substitutions(
            subject,
            &artifact_root,
            &case,
            entry,
            &output,
            &manifest,
            &evidence,
        );
        Ok(())
    }

    fn assert_synthetic_regression_descriptor_roundtrip(
        temporary: &Path,
        source_case: &DifferentialCase,
        oracle: &ExecutableIdentity,
        candidate: &ExecutableIdentity,
    ) -> Result<(), String> {
        let trace_case = regression_trace_case(
            source_case,
            "regression-synthetic-int-plus",
            source_case.source.as_ref(),
        )?;
        let report = differential_with_identities(oracle, candidate, &trace_case)
            .map_err(|error| format!("cannot execute synthetic regression discovery: {error}"))?;
        if report.mismatches.is_empty() || report.candidate.semantic.is_none() {
            return Err("synthetic regression did not retain a traced mismatch".to_owned());
        }
        let mut execution_case = trace_case;
        execution_case.claim_evidence = None;
        let descriptor_root = temporary.join("regression-descriptor-e2e");
        let (bundle, reviewed) = hell_testkit::retain_reviewed_regression_bundle(
            &descriptor_root,
            &execution_case,
            &report,
            "synthetic actual-executable regression descriptor review",
        )
        .map_err(|error| format!("cannot retain synthetic regression descriptor: {error}"))?;
        let targets = hell_testkit::retained_regression_reviewed_claim_targets(&bundle, &reviewed)
            .map_err(|error| format!("cannot replay synthetic regression descriptor: {error}"))?;
        let int_plus = targets.iter().find(|target| {
            target.builtin.as_ref() == "Int.plus"
                && target.dimension == CompatibilityDimension::PureRuntime
        });
        let authoritative = hell_testkit::applicable_runtime_obligation_cells()
            .into_iter()
            .find(|cell| {
                cell.builtin.as_ref() == "Int.plus"
                    && cell.dimension == CompatibilityDimension::PureRuntime
            })
            .ok_or_else(|| "Int.plus authority cell disappeared".to_owned())?;
        if int_plus.map(|target| &target.obligations) != Some(&authoritative.obligations) {
            return Err(
                "synthetic regression descriptor lost the complete reached Int.plus cell"
                    .to_owned(),
            );
        }
        let reconstructed = hell_testkit::reviewed_regression_case_from_bundle(
            &bundle,
            &execution_case,
            "synthetic actual-executable regression descriptor review",
        )
        .map_err(|error| format!("cannot reconstruct synthetic regression descriptor: {error}"))?;
        if reconstructed.claim_evidence != reviewed.claim_evidence {
            return Err("synthetic regression descriptor did not round trip".to_owned());
        }
        Ok(())
    }

    fn assert_synthetic_scheduled_exploration_roundtrip(
        subject: &Path,
        temporary: &Path,
        oracle: &ExecutableIdentity,
        candidate: &ExecutableIdentity,
    ) -> Result<(), String> {
        let generated = hell_testkit::generated_typed_cases(0x4845_4c4c_2026, 1)
            .into_iter()
            .next()
            .ok_or_else(|| "synthetic generated case disappeared".to_owned())?;
        let case = DifferentialCase {
            id: std::sync::Arc::clone(&generated.id),
            source: std::sync::Arc::clone(&generated.source),
            timeout: std::time::Duration::from_secs(5),
            ..DifferentialCase::default()
        };
        let report = differential_with_identities(oracle, candidate, &case)
            .map_err(|error| format!("cannot execute scheduled generated mismatch: {error}"))?;
        if report.mismatches.is_empty() {
            return Err("synthetic generated Int.plus defect did not mismatch".to_owned());
        }
        let nightly = temporary.join("scheduled-nightly");
        let mismatches = nightly.join("mismatches");
        fs::create_dir_all(&mismatches)
            .map_err(|error| format!("cannot create scheduled mismatch root: {error}"))?;
        retain_observation_bundle(&mismatches, &case, &report)
            .map_err(|error| format!("cannot retain scheduled original mismatch: {error}"))?;
        retain_synthetic_generated_proposal(&nightly, &generated, &oracle.path, &candidate.path)?;
        assert_synthetic_generated_inventory(&nightly, generated.id.as_ref())?;
        let exploration = nightly.join("regression-exploration");
        fs::create_dir(&exploration)
            .map_err(|error| format!("cannot create scheduled exploration root: {error}"))?;
        explore_one_generated_regression(subject, &nightly, &exploration, generated.id.as_ref())?;
        let manifest = JsonValue::Object(BTreeMap::from([
            (
                "caseIds".to_owned(),
                JsonValue::Array(vec![JsonValue::String(generated.id.to_string())]),
            ),
            ("schemaVersion".to_owned(), JsonValue::Number(1)),
            (
                "state".to_owned(),
                JsonValue::String("minimized-unreviewed-nonclaim".to_owned()),
            ),
        ]));
        write_atomic(
            &exploration.join("manifest.json"),
            &canonical_json_bytes(&manifest)?,
        )?;
        let source_root = nightly
            .join("mismatches/proposed-regressions")
            .join(generated.id.as_ref());
        let source =
            verify_generated_regression_source(&nightly, generated.id.as_ref(), &source_root)?;
        verify_scheduled_generated_exploration(&nightly, generated.id.as_ref(), &source)?;
        assert_scheduled_exploration_substitutions(&nightly, generated.id.as_ref(), &source)?;
        assert_nonselected_localization_remains_nonclaim(oracle, candidate)?;
        Ok(())
    }

    fn assert_nonselected_localization_remains_nonclaim(
        oracle: &ExecutableIdentity,
        candidate: &ExecutableIdentity,
    ) -> Result<(), String> {
        let case = DifferentialCase {
            id: "generated-int-boundary-0000".into(),
            source: "main = IO.print 0\n".into(),
            timeout: std::time::Duration::from_secs(5),
            ..DifferentialCase::default()
        };
        let report = differential_with_nonclaim_trace_target(oracle, candidate, &case, "Int.plus")
            .map_err(|error| format!("cannot execute nonselected localization: {error}"))?;
        if case.claim_evidence.is_some()
            || report
                .candidate
                .semantic
                .as_ref()
                .and_then(|semantic| semantic.typed_result_sha256)
                .is_some()
        {
            return Err("nonselected localization acquired claim or typed authority".to_owned());
        }
        let disposition =
            no_generated_regression_automation("retained-nonclaim-reviewed-target-not-implicated");
        if disposition.category.is_some()
            || disposition.template_case_id.is_some()
            || disposition.disposition != "retained-nonclaim-reviewed-target-not-implicated"
        {
            return Err("nonselected localization did not remain explicitly nonclaim".to_owned());
        }
        Ok(())
    }

    fn assert_synthetic_generated_inventory(nightly: &Path, case_id: &str) -> Result<(), String> {
        let generated_corpus = test_digest(b"synthetic generated corpus");
        let summary = JsonValue::Object(BTreeMap::from([
            ("corpusSeed".to_owned(), JsonValue::Number(0x4845_4c4c_2026)),
            (
                "generatedDifferentialObservations".to_owned(),
                JsonValue::Number(1_024),
            ),
            (
                "generatedStressCorpusSha256".to_owned(),
                JsonValue::String(generated_corpus.clone()),
            ),
        ]));
        write_atomic(
            &nightly.join("summary.json"),
            &canonical_json_bytes(&summary)?,
        )?;
        let inventory = JsonValue::Object(BTreeMap::from([
            (
                "caseIds".to_owned(),
                JsonValue::Array(vec![JsonValue::String(case_id.to_owned())]),
            ),
            ("corpusSeed".to_owned(), JsonValue::Number(0x4845_4c4c_2026)),
            (
                "generatedObservationCount".to_owned(),
                JsonValue::Number(1_024),
            ),
            (
                "generatedStressCorpusSha256".to_owned(),
                JsonValue::String(generated_corpus),
            ),
            ("schemaVersion".to_owned(), JsonValue::Number(1)),
        ]));
        write_synthetic_generated_inventory(nightly, &inventory)?;
        let expected = vec![case_id.to_owned()];
        assert_eq!(scheduled_generated_mismatch_ids(nightly)?, expected);
        verify_scheduled_generated_inventory(nightly, &expected)?;
        for ids in [
            Vec::new(),
            vec![case_id.to_owned(), "generated-extra-0001".to_owned()],
        ] {
            let mut changed = inventory.clone();
            *json_member_mut(changed.object_mut()?, "caseIds")? =
                JsonValue::Array(ids.into_iter().map(JsonValue::String).collect());
            write_synthetic_generated_inventory(nightly, &changed)?;
            assert!(verify_scheduled_generated_inventory(nightly, &expected).is_err());
        }
        write_synthetic_generated_inventory(nightly, &inventory)
    }

    fn write_synthetic_generated_inventory(
        nightly: &Path,
        inventory: &JsonValue,
    ) -> Result<(), String> {
        let bytes = canonical_json_bytes(inventory)?;
        write_atomic(&nightly.join("generated-regression-inventory.json"), &bytes)?;
        write_atomic(
            &nightly.join("generated-regression-inventory.sha256"),
            format!(
                "{}  generated-regression-inventory.json\n",
                sha256_bytes(&bytes).hex()
            )
            .as_bytes(),
        )
    }

    fn retain_synthetic_generated_proposal(
        nightly: &Path,
        generated: &hell_testkit::GeneratedCase,
        oracle: &Path,
        candidate: &Path,
    ) -> Result<(), String> {
        let proposals = nightly.join("mismatches/proposed-regressions");
        let source_root = proposals.join(generated.id.as_ref());
        fs::create_dir_all(&source_root)
            .map_err(|error| format!("cannot create synthetic generated proposal: {error}"))?;
        let proposal = JsonValue::Object(BTreeMap::from([
            (
                "astSha256".to_owned(),
                JsonValue::String(generated.ast_sha256.hex()),
            ),
            (
                "caseId".to_owned(),
                JsonValue::String(generated.id.to_string()),
            ),
            ("claimEligible".to_owned(), JsonValue::Bool(false)),
            (
                "minimizationStatus".to_owned(),
                JsonValue::String("pending".to_owned()),
            ),
            (
                "mismatchBundlePath".to_owned(),
                JsonValue::String(format!("mismatches/{}", generated.id)),
            ),
            (
                "resultType".to_owned(),
                JsonValue::String(format!("{:?}", generated.result_type)),
            ),
            (
                "reviewState".to_owned(),
                JsonValue::String("unreviewed".to_owned()),
            ),
            ("schemaVersion".to_owned(), JsonValue::Number(1)),
            ("seed".to_owned(), JsonValue::Number(generated.seed)),
            (
                "shrinkPlan".to_owned(),
                JsonValue::String(generated.shrink_description.to_string()),
            ),
            (
                "sourceSha256".to_owned(),
                JsonValue::String(sha256_bytes(generated.source.as_bytes()).hex()),
            ),
        ]));
        write_atomic(
            &proposals.join(format!("{}.json", generated.id)),
            &canonical_json_bytes(&proposal)?,
        )?;
        write_atomic(
            &source_root.join("program.hell"),
            generated.source.as_bytes(),
        )?;
        copy_regression_executable(oracle, &source_root.join("oracle"))?;
        copy_regression_executable(candidate, &source_root.join("candidate"))
    }

    fn assert_scheduled_exploration_substitutions(
        nightly: &Path,
        case_id: &str,
        source: &JsonValue,
    ) -> Result<(), String> {
        let root = nightly.join("regression-exploration");
        let case = root.join(case_id);
        let record_path = case.join("exploration.json");
        let record_bytes = fs::read(&record_path)
            .map_err(|error| format!("cannot read scheduled test record: {error}"))?;
        for field in [
            "bundleSha256",
            "candidateExecutableSha256",
            "executionInputSha256",
            "fingerprintSha256",
            "localizationBundleSha256",
            "localizationCandidateTypedSha256",
            "localizationOracleExpectedTypedSha256",
            "minimizedSourceSha256",
            "oracleExecutableSha256",
            "traceSha256",
        ] {
            let mut changed =
                parse_json(std::str::from_utf8(&record_bytes).map_err(|_| {
                    "scheduled exploration record fixture is not UTF-8".to_owned()
                })?)?;
            *json_member_mut(changed.object_mut()?, field)? =
                JsonValue::String(test_digest(field.as_bytes()));
            write_atomic(&record_path, &canonical_json_bytes(&changed)?)?;
            assert!(verify_scheduled_generated_exploration(nightly, case_id, source).is_err());
            write_atomic(&record_path, &record_bytes)?;
        }
        for relative in [
            "minimized.hell",
            "minimization-trace.json",
            "candidate",
            "evidence/generated-int-boundary-0000/execution-input.json",
            "evidence/generated-int-boundary-0000/candidate/stdout.bin",
        ] {
            let path = case.join(relative);
            let bytes = fs::read(&path).map_err(|error| {
                format!("cannot read scheduled substitution {relative}: {error}")
            })?;
            let mut changed = bytes.clone();
            changed.push(b'!');
            write_atomic(&path, &changed)?;
            assert!(verify_scheduled_generated_exploration(nightly, case_id, source).is_err());
            write_atomic(&path, &bytes)?;
        }
        assert_localization_substitutions(nightly, case_id, source)?;
        let manifest_path = root.join("manifest.json");
        let manifest = fs::read(&manifest_path)
            .map_err(|error| format!("cannot read scheduled manifest fixture: {error}"))?;
        write_atomic(
            &manifest_path,
            b"{\"caseIds\":[],\"schemaVersion\":1,\"state\":\"minimized-unreviewed-nonclaim\"}\n",
        )?;
        assert!(verify_scheduled_generated_exploration(nightly, case_id, source).is_err());
        write_atomic(&manifest_path, &manifest)?;
        let mut changed_source = source.clone();
        *json_member_mut(changed_source.object_mut()?, "sourceSha256")? =
            JsonValue::String(test_digest(b"scheduled source substitution"));
        assert!(verify_scheduled_generated_exploration(nightly, case_id, &changed_source).is_err());
        Ok(())
    }

    fn assert_localization_substitutions(
        nightly: &Path,
        case_id: &str,
        source: &JsonValue,
    ) -> Result<(), String> {
        let case = nightly.join("regression-exploration").join(case_id);
        let original = case.join("evidence").join(case_id);
        let localization = case.join("localization/runtime-typed-int-plus");
        let observation = localization.join("candidate/observation.json");
        let observation_bytes = fs::read(&observation)
            .map_err(|error| format!("cannot read localization observation: {error}"))?;
        let mut changed = parse_json(
            std::str::from_utf8(&observation_bytes)
                .map_err(|_| "localization observation fixture is not UTF-8".to_owned())?,
        )?;
        *json_member_mut(changed.object_mut()?, "semanticTypedResultBuiltinId")? =
            JsonValue::Number(u64::MAX);
        write_atomic(&observation, &canonical_json_bytes(&changed)?)?;
        assert!(verify_scheduled_generated_exploration(nightly, case_id, source).is_err());
        write_atomic(&observation, &observation_bytes)?;

        for relative in [
            "candidate/semantic-typed-result.json",
            "candidate/stderr.raw.bin",
            "candidate/resource-audit.json",
        ] {
            let path = localization.join(relative);
            let bytes = fs::read(&path)
                .map_err(|error| format!("cannot read localization {relative}: {error}"))?;
            let mut changed = bytes.clone();
            changed.push(b'!');
            write_atomic(&path, &changed)?;
            assert!(verify_scheduled_generated_exploration(nightly, case_id, source).is_err());
            write_atomic(&path, &bytes)?;
        }

        let mut changed = parse_json(
            std::str::from_utf8(&observation_bytes)
                .map_err(|_| "localization observation fixture is not UTF-8".to_owned())?,
        )?;
        *json_member_mut(changed.object_mut()?, "timedOut")? = JsonValue::Bool(true);
        write_atomic(&observation, &canonical_json_bytes(&changed)?)?;
        assert!(verify_localization_behavior_join(&original, &localization).is_err());
        write_atomic(&observation, &observation_bytes)?;

        let mut changed = parse_json(
            std::str::from_utf8(&observation_bytes)
                .map_err(|_| "localization observation fixture is not UTF-8".to_owned())?,
        )?;
        *json_member_mut(changed.object_mut()?, "filesystem")? =
            JsonValue::String("substituted-filesystem".to_owned());
        write_atomic(&observation, &canonical_json_bytes(&changed)?)?;
        assert!(verify_localization_behavior_join(&original, &localization).is_err());
        write_atomic(&observation, &observation_bytes)?;

        let stderr = localization.join("candidate/stderr.raw.bin");
        let stderr_bytes = fs::read(&stderr)
            .map_err(|error| format!("cannot read localization stderr: {error}"))?;
        let mut changed_stderr = stderr_bytes.clone();
        changed_stderr.push(b'!');
        write_atomic(&stderr, &changed_stderr)?;
        assert!(verify_localization_behavior_join(&original, &localization).is_err());
        write_atomic(&stderr, &stderr_bytes)?;

        let resources = localization.join("candidate/resource-audit.json");
        let resource_bytes = fs::read(&resources)
            .map_err(|error| format!("cannot read localization resources: {error}"))?;
        let mut changed_resources = resource_bytes.clone();
        changed_resources.push(b'!');
        write_atomic(&resources, &changed_resources)?;
        assert!(verify_localization_behavior_join(&original, &localization).is_err());
        write_atomic(&resources, &resource_bytes)
    }

    fn synthetic_git_commit(subject: &Path, source: &Path) -> Result<(), String> {
        let source = path_text(source)?;
        let commands = [
            vec!["add".to_owned(), "--".to_owned(), source],
            [
                "-c",
                "user.name=Prototype Test",
                "-c",
                "user.email=prototype@example.invalid",
                "commit",
                "--no-gpg-sign",
                "-m",
                "synthetic prototype defect",
            ]
            .into_iter()
            .map(str::to_owned)
            .collect(),
        ];
        for arguments in commands {
            let status = std::process::Command::new("git")
                .args(arguments)
                .current_dir(subject)
                .status()
                .map_err(|error| format!("cannot run synthetic git command: {error}"))?;
            if !status.success() {
                return Err("synthetic git command failed".to_owned());
            }
        }
        Ok(())
    }

    fn synthetic_git_diff(subject: &Path, source: &Path) -> Result<Vec<u8>, String> {
        let output = std::process::Command::new("git")
            .args(["diff", "--", &path_text(source)?])
            .current_dir(subject)
            .output()
            .map_err(|error| format!("cannot render synthetic prototype patch: {error}"))?;
        if !output.status.success() || output.stdout.is_empty() {
            return Err("synthetic prototype patch is empty".to_owned());
        }
        Ok(output.stdout)
    }

    fn synthetic_prototype_manifest(
        subject: &Path,
        source: &Path,
        patch: &Path,
        defective_source: &[u8],
        repaired_source: &[u8],
    ) -> Result<PathBuf, String> {
        let entry = JsonValue::Object(BTreeMap::from([
            (
                "afterSourceSha256".to_owned(),
                JsonValue::String(sha256_bytes(repaired_source).hex()),
            ),
            (
                "beforeSourceSha256".to_owned(),
                JsonValue::String(sha256_bytes(defective_source).hex()),
            ),
            (
                "builtin".to_owned(),
                JsonValue::String("Int.plus".to_owned()),
            ),
            (
                "caseId".to_owned(),
                JsonValue::String("int-plus-boundary-positive-value".to_owned()),
            ),
            (
                "dimension".to_owned(),
                JsonValue::String("pure-runtime".to_owned()),
            ),
            (
                "patchPath".to_owned(),
                JsonValue::String(path_text(
                    patch
                        .strip_prefix(subject)
                        .map_err(|_| "synthetic patch is outside subject worktree".to_owned())?,
                )?),
            ),
            (
                "patchSha256".to_owned(),
                JsonValue::String(record_digest(patch)?),
            ),
            ("planIssueNumber".to_owned(), JsonValue::Number(1)),
            (
                "planOwner".to_owned(),
                JsonValue::String("compatibility-team".to_owned()),
            ),
            (
                "planRationale".to_owned(),
                JsonValue::String(
                    "Synthetic reviewed repair restores the exact Int.plus result.".to_owned(),
                ),
            ),
            (
                "sourcePath".to_owned(),
                JsonValue::String(path_text(source)?),
            ),
        ]));
        let manifest = JsonValue::Object(BTreeMap::from([
            ("entries".to_owned(), JsonValue::Array(vec![entry])),
            (
                "policy".to_owned(),
                divergence_prototype_policy_json(DivergencePrototypePolicy {
                    changed_files: 1,
                    elapsed_seconds: 900,
                    patch_bytes: 65_536,
                }),
            ),
            ("schemaVersion".to_owned(), JsonValue::Number(1)),
        ]));
        let manifest_path = subject.join("prototype-manifest.json");
        fs::write(&manifest_path, canonical_json_bytes(&manifest)?)
            .map_err(|error| format!("cannot write synthetic prototype manifest: {error}"))?;
        Ok(manifest_path)
    }

    fn prepare_synthetic_prototype_bundles(
        repository: &Path,
        subject: &Path,
        temporary: &Path,
        case: &DifferentialCase,
        entry: &DivergencePrototypeEntry,
    ) -> Result<(ExecutableIdentity, ExecutableIdentity), String> {
        let build = build_divergence_prototype(subject, 600)?;
        if build.timed_out || !build.status.success() {
            return Err("cannot build synthetic defective candidate".to_owned());
        }
        let executable_name = if cfg!(windows) { "hell.exe" } else { "hell" };
        let candidate_path = subject.join("target/release").join(executable_name);
        fs::create_dir_all(
            candidate_path
                .parent()
                .ok_or_else(|| "synthetic candidate output has no parent".to_owned())?,
        )
        .map_err(|error| format!("cannot create synthetic candidate output: {error}"))?;
        fs::copy(
            divergence_prototype_target_directory(subject)
                .join("release")
                .join(executable_name),
            &candidate_path,
        )
        .map_err(|error| format!("cannot retain synthetic defective candidate: {error}"))?;
        let oracle_path = repository.join("target/debug").join(executable_name);
        if !oracle_path.is_file() {
            let build = CommandSpec::new("cargo", std::time::Duration::from_mins(10))
                .arguments([
                    "build",
                    "--locked",
                    "--package",
                    "hell-cli",
                    "--bin",
                    "hell",
                ])
                .current_directory(repository)
                .run()
                .map_err(|error| format!("cannot build synthetic oracle: {error}"))?;
            if build.timed_out || !build.status.success() {
                return Err("cannot build synthetic oracle".to_owned());
            }
        }
        let mut oracle = verify_executable(
            &oracle_path,
            ExecutableRole::Oracle,
            None,
            hell_builtins::LANGUAGE_VERSION,
        )
        .map_err(|error| format!("cannot verify synthetic oracle: {error}"))?;
        let mut candidate = verify_executable(
            &candidate_path,
            ExecutableRole::Candidate,
            None,
            hell_builtins::LANGUAGE_VERSION,
        )
        .map_err(|error| format!("cannot verify synthetic candidate: {error}"))?;
        let retained_epoch = epoch(subject)?.1;
        oracle.assurance_epoch_sha256 = Some(retained_epoch);
        candidate.assurance_epoch_sha256 = Some(retained_epoch);
        let observations = temporary.join("artifact/evidence/observations");
        let mut cases = committed_differential_cases();
        crate::suite::bind_runtime_process_helper(&mut cases)?;
        for retained_case in cases.iter().filter(|retained_case| {
            retained_case.id == case.id
                || exact_case_target(retained_case, &entry.builtin, entry.dimension)
                    .is_ok_and(|target| !target.boundary_classes.is_empty())
        }) {
            let report =
                hell_testkit::differential_with_identities(&oracle, &candidate, retained_case)
                    .map_err(|error| format!("cannot run synthetic prototype baseline: {error}"))?;
            if retained_case.id == case.id && report.mismatches.is_empty() {
                return Err("synthetic prototype defect did not create a mismatch".to_owned());
            }
            hell_testkit::retain_observation_bundle(&observations, retained_case, &report)
                .map_err(|error| format!("cannot retain synthetic prototype baseline: {error}"))?;
        }
        Ok((oracle, candidate))
    }

    #[allow(clippy::too_many_arguments)]
    fn assert_successful_prototype_fact_substitutions(
        subject: &Path,
        artifact_root: &Path,
        case: &DifferentialCase,
        entry: &DivergencePrototypeEntry,
        output: &Path,
        manifest: &DivergencePrototypeManifest,
        evidence: &JsonValue,
    ) {
        for field in [
            "candidateExecutableSha256",
            "prototypeExecutableSha256",
            "patchSha256",
            "patchedTreeSha256",
        ] {
            let mut substituted = evidence.clone();
            *json_member_mut(substituted.object_mut().unwrap(), field).unwrap() =
                JsonValue::String(test_digest(field.as_bytes()));
            assert!(
                verify_retained_divergence_prototype(
                    subject,
                    artifact_root.parent().unwrap(),
                    "artifact",
                    case,
                    &entry.builtin,
                    entry.dimension,
                    output,
                    manifest,
                    &substituted,
                )
                .is_err(),
                "substituted successful prototype field {field} passed"
            );
        }
        let mut neighbor = evidence.clone();
        let first = json_member_mut(neighbor.object_mut().unwrap(), "neighborCases")
            .unwrap()
            .array_mut()
            .unwrap()
            .first_mut()
            .unwrap();
        *json_member_mut(first.object_mut().unwrap(), "accepted").unwrap() = JsonValue::Bool(false);
        assert!(
            verify_retained_divergence_prototype(
                subject,
                artifact_root.parent().unwrap(),
                "artifact",
                case,
                &entry.builtin,
                entry.dimension,
                output,
                manifest,
                &neighbor,
            )
            .is_err()
        );
    }

    #[test]
    fn proposal_scrub_digest_inputs_are_typed_and_exact() {
        let package = test_digest(b"scrub package");
        let archive = test_digest(b"scrub archive");
        let encoded =
            format!("{{\"packageSha256\":\"{package}\",\"providerArchiveSha256\":\"{archive}\"}}");
        let inputs = BTreeMap::from([
            (
                "primary_scrub_digests".to_owned(),
                JsonValue::String(encoded.clone()),
            ),
            (
                "secondary_scrub_digests".to_owned(),
                JsonValue::String(encoded),
            ),
        ]);
        let expanded = expand_scrub_digest_inputs(&inputs).unwrap();
        assert_eq!(
            json_member(&expanded, "primary_scrub_package_sha256")
                .unwrap()
                .string()
                .unwrap(),
            package
        );
        assert_eq!(
            json_member(&expanded, "secondary_scrub_provider_archive_sha256")
                .unwrap()
                .string()
                .unwrap(),
            archive
        );
        let forged = BTreeMap::from([
            (
                "primary_scrub_digests".to_owned(),
                JsonValue::String("{\"packageSha256\":\"forged\"}".to_owned()),
            ),
            (
                "secondary_scrub_digests".to_owned(),
                JsonValue::String("{}".to_owned()),
            ),
        ]);
        assert!(expand_scrub_digest_inputs(&forged).is_err());
    }

