    #[test]
    fn applicability_never_automatically_marks_not_applicable() {
        assert!(!generated_claim_policy_allows_unsafe_evidence());
        assert!(applicability_json(false).contains("\"automaticNotApplicable\": false"));
        let rows = applicability_rows();
        assert_eq!(
            rows.len(),
            hell_builtins::UNIQUE_NAME_COUNT * CompatibilityDimension::ALL.len()
        );
        assert!(rows.iter().all(|row| row.2 != "not-applicable-derived"));
        assert!(rows.iter().any(|row| row.2 == "ambiguous-needs-review"));
    }

