    #[test]
    fn retained_epoch_rejects_commit_tree_substitution() {
        let repository = root();
        let directory = repository
            .join("target")
            .join("retained-epoch-tree-substitution");
        let _ = fs::remove_dir_all(&directory);
        fs::create_dir_all(&directory).unwrap();
        let (document, _) = epoch(&repository).unwrap();
        let candidate = git_output(&repository, &["rev-parse", "HEAD"]).unwrap();
        let tree = git_output(&repository, &["rev-parse", "HEAD^{tree}"]).unwrap();
        let substituted = document.replace(tree.trim(), candidate.trim());
        let path = directory.join("assurance-epoch.json");
        fs::write(&path, substituted.as_bytes()).unwrap();
        let digest = sha256_bytes(substituted.as_bytes()).hex();
        fs::write(
            path.with_extension("sha256"),
            format!("{digest}  assurance-epoch.json\n"),
        )
        .unwrap();
        assert!(retained_epoch_digest(&path).is_err());
        fs::remove_dir_all(directory).unwrap();
    }

