    #[test]
    fn final_readiness_binds_false_mechanical_manifest_and_zero_blockers() {
        let blockers = PROMOTION_BLOCKERS
            .iter()
            .map(|name| ((*name).to_owned(), JsonValue::Number(0)))
            .collect::<BTreeMap<_, _>>();
        let merged = b"{\"promotionReady\":false}\n";
        let candidate = test_git_sha('7');
        let epoch = test_digest(b"final readiness epoch");
        let final_document = JsonValue::Object(BTreeMap::from([
            (
                "assuranceEpochSha256".to_owned(),
                JsonValue::String(epoch.clone()),
            ),
            (
                "blockersSha256".to_owned(),
                JsonValue::String(blocker_set_digest(&blockers).unwrap()),
            ),
            (
                "candidateSourceCommit".to_owned(),
                JsonValue::String(candidate.clone()),
            ),
            (
                "mechanicalMergedManifestSha256".to_owned(),
                JsonValue::String(sha256_bytes(merged).hex()),
            ),
            (
                "mechanicalPromotionReady".to_owned(),
                JsonValue::Bool(false),
            ),
            ("promotionReady".to_owned(), JsonValue::Bool(true)),
            ("schemaVersion".to_owned(), JsonValue::Number(1)),
        ]));
        let final_merged = canonical_json_bytes(&final_document).unwrap();
        let mut proposal = BTreeMap::from([
            ("assuranceEpochSha256".to_owned(), JsonValue::String(epoch)),
            ("blockers".to_owned(), JsonValue::Object(blockers.clone())),
            (
                "candidateSourceCommit".to_owned(),
                JsonValue::String(candidate),
            ),
            (
                "finalMergedManifestSha256".to_owned(),
                JsonValue::String(sha256_bytes(&final_merged).hex()),
            ),
        ]);
        assert!(verify_final_merged_readiness(&proposal, merged, &final_merged).is_ok());
        assert!(
            verify_final_merged_readiness(
                &proposal,
                b"{\"promotionReady\":true}\n",
                &final_merged,
            )
            .is_err()
        );
        let mut nonzero = blockers;
        nonzero.insert(PROMOTION_BLOCKERS[0].to_owned(), JsonValue::Number(1));
        proposal.insert("blockers".to_owned(), JsonValue::Object(nonzero));
        assert!(verify_final_merged_readiness(&proposal, merged, &final_merged).is_err());
    }

    #[test]
    fn semantic_fuzz_target_final_evidence_graph_calls_the_exact_merge_validator() {
        let blockers = PROMOTION_BLOCKERS
            .iter()
            .map(|name| ((*name).to_owned(), JsonValue::Number(0)))
            .collect::<BTreeMap<_, _>>();
        let merged = b"{\"promotionReady\":false}\n";
        let candidate = test_git_sha('6');
        let epoch = test_digest(b"evidence graph fuzz epoch");
        let document = JsonValue::Object(BTreeMap::from([
            (
                "assuranceEpochSha256".to_owned(),
                JsonValue::String(epoch.clone()),
            ),
            (
                "blockersSha256".to_owned(),
                JsonValue::String(blocker_set_digest(&blockers).unwrap()),
            ),
            (
                "candidateSourceCommit".to_owned(),
                JsonValue::String(candidate.clone()),
            ),
            (
                "mechanicalMergedManifestSha256".to_owned(),
                JsonValue::String(sha256_bytes(merged).hex()),
            ),
            (
                "mechanicalPromotionReady".to_owned(),
                JsonValue::Bool(false),
            ),
            ("promotionReady".to_owned(), JsonValue::Bool(true)),
            ("schemaVersion".to_owned(), JsonValue::Number(1)),
        ]));
        let canonical = canonical_json_bytes(&document).unwrap();
        let mut proposal = BTreeMap::from([
            ("assuranceEpochSha256".to_owned(), JsonValue::String(epoch)),
            ("blockers".to_owned(), JsonValue::Object(blockers)),
            (
                "candidateSourceCommit".to_owned(),
                JsonValue::String(candidate),
            ),
            (
                "finalMergedManifestSha256".to_owned(),
                JsonValue::String(sha256_bytes(&canonical).hex()),
            ),
        ]);
        assert!(verify_final_merged_readiness(&proposal, merged, &canonical).is_ok());
        for index in (0..canonical.len()).step_by(canonical.len().div_ceil(256)) {
            let mut mutated = canonical.clone();
            mutated[index] = 0;
            proposal.insert(
                "finalMergedManifestSha256".to_owned(),
                JsonValue::String(sha256_bytes(&mutated).hex()),
            );
            let outcome = std::panic::catch_unwind(|| {
                verify_final_merged_readiness(&proposal, merged, &mutated)
            });
            assert!(
                outcome.is_ok(),
                "evidence graph validator panicked at {index}"
            );
            assert!(
                outcome.unwrap().is_err(),
                "evidence graph accepted NUL at {index}"
            );
        }
    }

