    #[test]
    fn required_claim_cell_scope_rejects_every_expansion_reduction_and_reordering() {
        let expected = canonical_claim_cell_scope();
        let cells = expected
            .iter()
            .map(|(builtin, dimension, profile, platform)| {
                claim_scope_cell(builtin, dimension, profile, platform)
            })
            .collect::<Vec<_>>();
        assert!(verify_canonical_claim_cell_scope(&cells).is_ok());

        for index in [0, cells.len() / 2, cells.len() - 1] {
            let mut reduced = cells.clone();
            reduced.remove(index);
            assert!(verify_canonical_claim_cell_scope(&reduced).is_err());

            let mut duplicated = cells.clone();
            duplicated.insert(index, cells[index].clone());
            assert!(verify_canonical_claim_cell_scope(&duplicated).is_err());
        }
        let mut reordered = cells.clone();
        reordered.swap(0, 1);
        assert!(verify_canonical_claim_cell_scope(&reordered).is_err());

        for (builtin, dimension, _, platform) in &expected {
            let dimension = compatibility_dimension(dimension).unwrap();
            let required = claim_obligations(builtin, dimension, platform).unwrap();
            if let Some(obligation) = required.iter().next().cloned() {
                let mut reduced = required.clone();
                reduced.remove(&obligation);
                assert_ne!(reduced, required);
            }
            let mut expanded = required.clone();
            expanded.insert("forged-scope-obligation".to_owned());
            assert_ne!(expanded, required);
        }
    }

