    #[test]
    fn platform_dependent_status_requires_three_distinct_normalized_platform_facts() {
        let fingerprints = ["linux", "macos", "windows"].map(|value| test_digest(value.as_bytes()));
        let mut rows = REQUIRED_CLAIM_PLATFORMS
            .iter()
            .zip(fingerprints.iter())
            .map(|(platform, fingerprint)| ClaimCoverageRow {
                builtin: "Bool.bool",
                dimension: CompatibilityDimension::Presentation,
                decision: "applicable-reviewed",
                platform,
                references: Vec::new(),
                normalizers: vec!["diagnostic-path-separator-v1".to_owned()],
                application_refs: vec![test_digest(platform.as_bytes())],
                complete: true,
                normalized_fingerprints: BTreeSet::from([fingerprint.clone()]),
                has_exact_evidence: false,
                status: "normalized",
            })
            .collect::<Vec<_>>();
        derive_platform_dependent_statuses(&mut rows);
        assert!(rows.iter().all(|row| row.status == "platform-dependent"));

        for row in &mut rows {
            row.status = "normalized";
            row.normalized_fingerprints = BTreeSet::from([test_digest(b"same")]);
        }
        derive_platform_dependent_statuses(&mut rows);
        assert!(rows.iter().all(|row| row.status == "normalized"));
    }

