    #[test]
    fn divergence_authored_decision_fields_are_typed_bounded_and_non_generic() {
        let mut decision = BTreeMap::from([
            (
                "alternativesConsidered".to_owned(),
                JsonValue::Array(vec![JsonValue::String(
                    "Implement a candidate-side semantic compatibility adapter.".to_owned(),
                )]),
            ),
            (
                "category".to_owned(),
                JsonValue::String("runtime-semantics".to_owned()),
            ),
            (
                "documentationTarget".to_owned(),
                JsonValue::String("bounded-compatibility-report/accepted-divergences".to_owned()),
            ),
            (
                "impact".to_owned(),
                JsonValue::String(
                    "Users observe a bounded semantic result difference in this operation."
                        .to_owned(),
                ),
            ),
            ("owner".to_owned(), JsonValue::Number(42)),
            (
                "rationale".to_owned(),
                JsonValue::String(
                    "Retained evidence supports accepting this exact scoped incompatibility."
                        .to_owned(),
                ),
            ),
            (
                "whyNotFixCandidate".to_owned(),
                JsonValue::String(
                    "A candidate-side fix would violate the separately reviewed runtime policy."
                        .to_owned(),
                ),
            ),
        ]);
        assert!(validate_divergence_authored_fields(&decision, "high").is_ok());
        decision.insert("owner".to_owned(), JsonValue::Number(0));
        assert!(validate_divergence_authored_fields(&decision, "high").is_err());
        decision.insert("owner".to_owned(), JsonValue::Number(42));
        assert!(validate_divergence_authored_fields(&decision, "medium").is_err());
        decision.insert(
            "documentationTarget".to_owned(),
            JsonValue::String("../generic-waiver".to_owned()),
        );
        assert!(validate_divergence_authored_fields(&decision, "high").is_err());
    }

    #[test]
    fn divergence_acceptance_blocks_incomplete_objective_experiments() {
        let evidence = test_divergence_objective_evidence("objective-incomplete");
        let evidence = evidence.object().unwrap();
        verify_divergence_objective_evidence(&JsonValue::Object(evidence.clone())).unwrap();
        assert!(
            verify_divergence_objective_decision(
                evidence,
                "not-currently-fixable",
                "unknown",
                "baseline-inherent",
            )
            .is_err()
        );
        let mut substituted = evidence.clone();
        let JsonValue::Object(neighbors) = substituted
            .get_mut("neighboringBoundaryFacts")
            .expect("neighbor packet")
        else {
            panic!("neighbor packet must be an object")
        };
        let JsonValue::Array(cases) = neighbors.get_mut("cases").expect("neighbor cases") else {
            panic!("neighbor cases must be an array")
        };
        let duplicate = cases[0].clone();
        cases.push(duplicate);
        assert!(verify_divergence_objective_evidence(&JsonValue::Object(substituted)).is_err());

        let mut profile_substitution = evidence.clone();
        let JsonValue::Object(profile) = profile_substitution
            .get_mut("profileComparison")
            .expect("profile comparison")
        else {
            panic!("profile comparison must be an object")
        };
        let JsonValue::Array(profiles) = profile.get_mut("profiles").expect("profiles") else {
            panic!("profiles must be an array")
        };
        let JsonValue::Object(sandboxed) = &mut profiles[1] else {
            panic!("sandboxed profile must be an object")
        };
        sandboxed.insert(
            "executableSha256".to_owned(),
            JsonValue::String(test_digest(b"substituted profile executable")),
        );
        assert!(
            verify_divergence_objective_evidence(&JsonValue::Object(profile_substitution)).is_err()
        );

        let mut relation_substitution = evidence.clone();
        let JsonValue::Object(profile) = relation_substitution
            .get_mut("profileComparison")
            .expect("profile comparison")
        else {
            panic!("profile comparison must be an object")
        };
        profile.insert(
            "relation".to_owned(),
            JsonValue::String("sandboxed-resolves-upstream-mismatch".to_owned()),
        );
        assert!(
            verify_divergence_objective_evidence(&JsonValue::Object(relation_substitution))
                .is_err()
        );

        let mut policy_driven = evidence.clone();
        policy_driven.insert(
            "automatedOriginClassification".to_owned(),
            JsonValue::String("policy-driven".to_owned()),
        );
        let JsonValue::Object(profile) = policy_driven
            .get_mut("profileComparison")
            .expect("profile comparison")
        else {
            panic!("profile comparison must be an object")
        };
        profile.insert(
            "relation".to_owned(),
            JsonValue::String("sandboxed-resolves-upstream-mismatch".to_owned()),
        );
        let JsonValue::Array(profiles) = profile.get_mut("profiles").expect("profiles") else {
            panic!("profiles must be an array")
        };
        let JsonValue::Object(sandboxed) = &mut profiles[1] else {
            panic!("sandboxed profile must be an object")
        };
        sandboxed.insert(
            "classification".to_owned(),
            JsonValue::String("exact".to_owned()),
        );
        sandboxed.insert("fingerprintSha256".to_owned(), JsonValue::Null);
        assert!(verify_divergence_objective_evidence(&JsonValue::Object(policy_driven)).is_ok());

        assert_platform_origin_derivation(evidence);
    }

    fn assert_platform_origin_derivation(evidence: &BTreeMap<String, JsonValue>) {
        let mut platform_inherent = evidence.clone();
        let JsonValue::Array(platforms) = platform_inherent
            .get_mut("upstreamPlatformFacts")
            .expect("platform facts")
        else {
            panic!("platform facts must be an array")
        };
        let JsonValue::Object(second) = &mut platforms[1] else {
            panic!("platform fact must be an object")
        };
        second.insert(
            "fingerprintSha256".to_owned(),
            JsonValue::String(test_digest(b"platform-specific fingerprint")),
        );
        assert!(
            verify_divergence_objective_evidence(&JsonValue::Object(platform_inherent.clone()))
                .is_err()
        );
        platform_inherent.insert(
            "automatedOriginClassification".to_owned(),
            JsonValue::String("platform-inherent".to_owned()),
        );
        assert!(
            verify_divergence_objective_evidence(&JsonValue::Object(platform_inherent)).is_ok()
        );
    }

    #[test]
    fn prior_public_divergence_facts_reject_identity_and_approval_substitution() {
        let directory = std::env::temp_dir().join(format!(
            "hell-prior-divergence-facts-{}",
            std::process::id()
        ));
        let _ = fs::remove_dir_all(&directory);
        fs::create_dir(&directory).unwrap();
        let candidate = test_git_sha('8');
        let epoch = test_digest(b"prior epoch");
        let details = JsonValue::Object(BTreeMap::from([
            ("activeDivergences".to_owned(), JsonValue::Number(0)),
            ("approvedDivergences".to_owned(), JsonValue::Number(0)),
            (
                "assuranceEpochSha256".to_owned(),
                JsonValue::String(epoch.clone()),
            ),
            (
                "candidateSourceCommit".to_owned(),
                JsonValue::String(candidate.clone()),
            ),
            ("expiredDivergences".to_owned(), JsonValue::Number(0)),
            ("fingerprintMismatches".to_owned(), JsonValue::Number(0)),
            ("missingImpactApprovals".to_owned(), JsonValue::Number(0)),
            ("proposedRecords".to_owned(), JsonValue::Array(Vec::new())),
            ("records".to_owned(), JsonValue::Array(Vec::new())),
            ("schemaVersion".to_owned(), JsonValue::Number(2)),
            ("wildcardScopes".to_owned(), JsonValue::Number(0)),
        ]));
        let path = directory.join("accepted-divergences.json");
        fs::write(&path, canonical_json_bytes(&details).unwrap()).unwrap();
        let availability = BTreeMap::from([
            ("candidateCommit".to_owned(), JsonValue::String(candidate)),
            ("assuranceEpochSha256".to_owned(), JsonValue::String(epoch)),
        ]);
        assert!(verified_prior_divergence_details(&path, &availability).is_ok());
        let mut changed = details.object().unwrap().clone();
        changed.insert("missingImpactApprovals".to_owned(), JsonValue::Number(1));
        fs::write(
            &path,
            canonical_json_bytes(&JsonValue::Object(changed)).unwrap(),
        )
        .unwrap();
        assert!(verified_prior_divergence_details(&path, &availability).is_err());
        fs::remove_dir_all(directory).unwrap();
    }

    #[test]
    fn prior_divergence_resolution_is_exact_and_source_bound() {
        let fingerprint = test_digest(b"current mismatch");
        let source_sha256 = test_digest(b"current case source");
        let divergence_id = test_digest(b"prior divergence");
        let record = JsonValue::Object(BTreeMap::from([
            (
                "builtin".to_owned(),
                JsonValue::String("Bool.bool".to_owned()),
            ),
            (
                "caseId".to_owned(),
                JsonValue::String("bool-roundtrip".to_owned()),
            ),
            (
                "dimension".to_owned(),
                JsonValue::String("pure-runtime".to_owned()),
            ),
            (
                "divergenceId".to_owned(),
                JsonValue::String(divergence_id.clone()),
            ),
            (
                "mismatchEvidence".to_owned(),
                JsonValue::Object(BTreeMap::from([(
                    "caseSourceSha256".to_owned(),
                    JsonValue::String(source_sha256.clone()),
                )])),
            ),
            (
                "mismatchFingerprint".to_owned(),
                JsonValue::String(fingerprint.clone()),
            ),
            (
                "platform".to_owned(),
                JsonValue::String("linux-amd64".to_owned()),
            ),
            (
                "profile".to_owned(),
                JsonValue::String("upstream".to_owned()),
            ),
        ]));
        let inputs = PriorDivergenceMatchInputs {
            case_id: "bool-roundtrip",
            builtin: "Bool.bool",
            dimension: "pure-runtime",
            platform: "linux-amd64",
            current_fingerprint: &fingerprint,
            current_source_sha256: &source_sha256,
        };
        let details = BTreeMap::from([("records".to_owned(), JsonValue::Array(vec![record]))]);
        let resolved = resolve_prior_divergence(&details, &inputs).unwrap();
        assert!(resolved.same);
        assert_eq!(
            resolved.divergence_id.as_deref(),
            Some(divergence_id.as_str())
        );

        let mut changed_source = details.clone();
        let JsonValue::Array(records) = changed_source.get_mut("records").unwrap() else {
            panic!("records must be an array")
        };
        let JsonValue::Object(record) = &mut records[0] else {
            panic!("record must be an object")
        };
        let JsonValue::Object(evidence) = record.get_mut("mismatchEvidence").unwrap() else {
            panic!("mismatch evidence must be an object")
        };
        evidence.insert(
            "caseSourceSha256".to_owned(),
            JsonValue::String(test_digest(b"changed source")),
        );
        let unresolved = resolve_prior_divergence(&changed_source, &inputs).unwrap();
        assert!(!unresolved.same);
        assert!(unresolved.divergence_id.is_none());

        let no_match = BTreeMap::from([("records".to_owned(), JsonValue::Array(Vec::new()))]);
        let unresolved = resolve_prior_divergence(&no_match, &inputs).unwrap();
        assert!(!unresolved.same);
        assert!(unresolved.divergence_id.is_none());

        let JsonValue::Array(records) = details.get("records").unwrap() else {
            panic!("records must be an array")
        };
        let duplicate = BTreeMap::from([(
            "records".to_owned(),
            JsonValue::Array(vec![records[0].clone(), records[0].clone()]),
        )]);
        assert!(resolve_prior_divergence(&duplicate, &inputs).is_err());
    }

    #[test]
    fn divergence_implementation_sources_resolve_across_runtime_modules() {
        for (builtin, expected_path) in [
            ("Bool.bool", "hell-runtime/src/lib.rs:"),
            ("List.zipWith", "hell-runtime/src/native_list.rs:"),
            ("Map.fromList", "hell-runtime/src/native_collections.rs:"),
            ("Http.run", "hell-runtime/src/native_http.rs:"),
            ("Tuple.(,)", "hell-runtime/src/lib.rs:"),
            ("Record.get", "hell-compiler/src/lib.rs:"),
        ] {
            let (implementation, location, digest) =
                builtin_implementation_source_facts(builtin).unwrap();
            assert!(!implementation.is_empty());
            assert!(location.contains(expected_path), "{builtin}: {location}");
            require_digest(&digest, "test implementation source").unwrap();
        }
    }

