    #[test]
    fn normalizer_order_or_precision_loss_is_rejected() {
        let directory = std::env::temp_dir().join(format!(
            "hell-assurance-normalizer-mutant-{}",
            std::process::id()
        ));
        let _ = fs::remove_dir_all(&directory);
        fs::create_dir(&directory).unwrap();
        let input = directory.join("before.json");
        let output = directory.join("after.json");
        let context = directory.join("normalizer-context.json");
        fs::write(
            &input,
            b"{\"diagnostic\":{\"paths\":[\"/tmp/case/main.hell\"]},\"numericBits\":[\"9007199254740993\"],\"stderr\":{\"path_tokens\":[\"/tmp/case/main.hell\"]},\"stdout\":[\"first\",\"second\"]}\n",
        )
        .unwrap();
        fs::write(
            &output,
            b"{\"diagnostic\":{\"paths\":[\"<SANDBOX>/main.hell\"]},\"numericBits\":[\"9007199254740992\"],\"stderr\":{\"path_tokens\":[\"<SANDBOX>/main.hell\"]},\"stdout\":[\"second\",\"first\"]}\n",
        )
        .unwrap();
        fs::write(
            &context,
            b"{\"sandboxPath\":\"/tmp/case\",\"schemaVersion\":1,\"scriptPath\":\"/tmp/case/main.hell\"}\n",
        )
        .unwrap();
        let before = parse_json(&read_text(&input).unwrap()).unwrap();
        let after = parse_json(&read_text(&output).unwrap()).unwrap();
        let mut changed = BTreeSet::new();
        collect_changed_json_paths(&before, &after, "", &mut changed);
        let changed_values = u64::try_from(changed.len()).unwrap();
        let removed_bytes = changed_json_removed_bytes(&before, &after).unwrap();
        let implementation_sha256 = hell_builtins::normalizer_contract(
            hell_builtins::NormalizerId::DiagnosticSandboxPathV1,
        )
        .unwrap()
        .implementation_sha256;
        let application = BTreeMap::from([
            (
                "applicationScope".to_owned(),
                JsonValue::String("claim-json".to_owned()),
            ),
            (
                "changedPaths".to_owned(),
                JsonValue::Array(changed.into_iter().map(JsonValue::String).collect()),
            ),
            (
                "changedValues".to_owned(),
                JsonValue::Number(changed_values),
            ),
            ("idempotent".to_owned(), JsonValue::Bool(true)),
            (
                "implementationSha256".to_owned(),
                JsonValue::String(implementation_sha256.to_owned()),
            ),
            (
                "normalizerId".to_owned(),
                JsonValue::String("diagnostic-sandbox-path-v1".to_owned()),
            ),
            ("protectedFieldsUnchanged".to_owned(), JsonValue::Bool(true)),
            ("removedBytes".to_owned(), JsonValue::Number(removed_bytes)),
            (
                "sandboxPath".to_owned(),
                JsonValue::String("/tmp/case".to_owned()),
            ),
            (
                "scriptPath".to_owned(),
                JsonValue::String("/tmp/case/main.hell".to_owned()),
            ),
        ]);
        assert!(
            verify_normalizer_application_files(&application, &input, &output, &output, &context)
                .is_err()
        );
        fs::remove_dir_all(directory).unwrap();
    }

    #[test]
    fn every_production_normalizer_is_idempotent_and_preserves_diagnostic_scope() {
        let sandbox = Path::new(r"C:\work\sandbox");
        let script = Path::new(r"C:\work\sandbox\main.hell");
        let input = br"first: keep order
C:\work\sandbox\main.hell:4:2: error[H0200]
last: value=9007199254740993";
        let catalog_ids = hell_builtins::assurance_catalogs::NORMALIZER_CONTRACTS
            .iter()
            .map(|contract| contract.id.as_str())
            .collect::<BTreeSet<_>>();
        let runtime_ids = hell_builtins::NormalizerId::ALL
            .iter()
            .map(|normalizer| normalizer.as_str())
            .collect::<BTreeSet<_>>();
        assert_eq!(catalog_ids, runtime_ids);
        for normalizer in hell_builtins::NormalizerId::ALL {
            let observation: &[u8] = match normalizer {
                hell_builtins::NormalizerId::DiagnosticSandboxPathV1 => input,
                hell_builtins::NormalizerId::DiagnosticPathSeparatorV1 => {
                    br"first: keep order
<SANDBOX>\main.hell:4:2: error[H0200]
last: value=9007199254740993"
                }
            };
            let passes = hell_testkit::apply_retained_normalizer_twice(
                hell_testkit::RetainedNormalizerInput {
                    normalizer: *normalizer,
                    observation,
                    sandbox,
                    script,
                },
            );
            assert_eq!(passes.first_pass, passes.second_pass);
            let output = std::str::from_utf8(&passes.first_pass).unwrap();
            assert!(output.starts_with("first: keep order\n"));
            assert!(output.ends_with("\nlast: value=9007199254740993"));
            assert_eq!(output.matches("error[H0200]").count(), 1);
            match normalizer {
                hell_builtins::NormalizerId::DiagnosticSandboxPathV1 => {
                    assert!(output.contains(r"<SANDBOX>\main.hell:4:2"));
                }
                hell_builtins::NormalizerId::DiagnosticPathSeparatorV1 => {
                    assert!(output.contains("<SANDBOX>/main.hell:4:2"));
                }
            }
        }
    }

