    #[test]
    fn normalizer_authorship_requires_exact_changed_provider_files() {
        let file = |name: &str, sha: &str| {
            JsonValue::Object(BTreeMap::from([
                ("filename".to_owned(), JsonValue::String(name.to_owned())),
                ("sha".to_owned(), JsonValue::String(sha.to_owned())),
                (
                    "status".to_owned(),
                    JsonValue::String("modified".to_owned()),
                ),
            ]))
        };
        let repository = root();
        let catalog_relative = PathBuf::from("compat").join("normalizers.toml");
        let source_relative = PathBuf::from("crates")
            .join("hell-testkit")
            .join("src")
            .join("lib.rs");
        let catalog_sha = git_output(
            &repository,
            &["hash-object", "--", "compat/normalizers.toml"],
        )
        .unwrap()
        .trim()
        .to_owned();
        let source_sha = git_output(
            &repository,
            &["hash-object", "--", "crates/hell-testkit/src/lib.rs"],
        )
        .unwrap()
        .trim()
        .to_owned();
        let commit = BTreeMap::from([(
            "files".to_owned(),
            JsonValue::Array(vec![
                file("compat/normalizers.toml", &catalog_sha),
                file("crates/hell-testkit/src/lib.rs", &source_sha),
            ]),
        )]);
        assert_eq!(
            provider_authored_file_blob(&commit, "compat/normalizers.toml").unwrap(),
            catalog_sha
        );
        assert_eq!(
            provider_authored_file_blob(&commit, "crates/hell-testkit/src/lib.rs").unwrap(),
            source_sha
        );
        assert!(provider_authored_file_blob(&commit, "compat/other.toml").is_err());
        verify_authored_provider_file(&repository, &commit, &catalog_relative).unwrap();
        verify_authored_provider_file(&repository, &commit, &source_relative).unwrap();
        let mut substituted = commit.clone();
        substituted.insert(
            "files".to_owned(),
            JsonValue::Array(vec![file("compat/normalizers.toml", &test_git_sha('c'))]),
        );
        assert!(
            verify_authored_provider_file(&repository, &substituted, &catalog_relative).is_err()
        );
        let duplicated = BTreeMap::from([(
            "files".to_owned(),
            JsonValue::Array(vec![
                file("compat/normalizers.toml", &catalog_sha),
                file("compat/normalizers.toml", &catalog_sha),
            ]),
        )]);
        assert!(provider_authored_file_blob(&duplicated, "compat/normalizers.toml").is_err());
    }

    #[test]
    fn governed_authorship_unions_every_merge_parent_delta() {
        let repository = create_private_temp_directory("hell-authorship-merge").unwrap();
        git_output(&repository, &["init", "-q", "-b", "main"]).unwrap();
        fs::create_dir(repository.join("compat")).unwrap();
        let governed = PathBuf::from("compat").join("governed.toml");
        fs::write(repository.join(&governed), "state = 1\n").unwrap();
        git_output(&repository, &["add", "--", "compat/governed.toml"]).unwrap();
        git_output(
            &repository,
            &[
                "-c",
                "user.name=Assurance Test",
                "-c",
                "user.email=assurance@example.invalid",
                "commit",
                "-q",
                "-m",
                "base",
            ],
        )
        .unwrap();
        git_output(&repository, &["checkout", "-q", "-b", "governed-change"]).unwrap();
        fs::write(repository.join(&governed), "state = 2\n").unwrap();
        git_output(&repository, &["add", "--", "compat/governed.toml"]).unwrap();
        git_output(
            &repository,
            &[
                "-c",
                "user.name=Assurance Test",
                "-c",
                "user.email=assurance@example.invalid",
                "commit",
                "-q",
                "-m",
                "governed change",
            ],
        )
        .unwrap();
        git_output(&repository, &["checkout", "-q", "main"]).unwrap();
        fs::write(repository.join("unrelated.txt"), "unrelated\n").unwrap();
        git_output(&repository, &["add", "--", "unrelated.txt"]).unwrap();
        git_output(
            &repository,
            &[
                "-c",
                "user.name=Assurance Test",
                "-c",
                "user.email=assurance@example.invalid",
                "commit",
                "-q",
                "-m",
                "unrelated change",
            ],
        )
        .unwrap();
        git_output(
            &repository,
            &[
                "-c",
                "user.name=Assurance Test",
                "-c",
                "user.email=assurance@example.invalid",
                "merge",
                "-q",
                "--no-ff",
                "governed-change",
                "-m",
                "merge governed change",
            ],
        )
        .unwrap();
        let candidate = git_output(&repository, &["rev-parse", "HEAD"]).unwrap();
        assert_eq!(
            changed_governed_paths(
                &repository,
                candidate.trim(),
                std::slice::from_ref(&governed)
            )
            .unwrap(),
            vec![governed]
        );
        fs::remove_dir_all(repository).unwrap();
    }

