    #[test]
    fn linux_release_sigstore_roles_are_exactly_workflow_domain_scoped() {
        let document = read_text(&root().join("compat/trust-roots.toml")).unwrap();
        let repository = "Portfoligno/hell-rs";
        let trusted_ref = "refs/heads/main";
        let domains = [
            (
                "linux-release-acquirer",
                "release_oracle_workflow",
                ".github/workflows/nightly.yml",
                "Portfoligno/hell-rs/.github/workflows/nightly.yml@refs/heads/main",
            ),
            (
                "collection-linux-release-acquirer",
                "collection_release_oracle_workflow",
                COLLECTION_AUTHORITY_WORKFLOW_PATH,
                COLLECTION_AUTHORITY_WORKFLOW_REF,
            ),
        ];
        for (role, key, workflow, workflow_ref) in domains {
            assert_eq!(sigstore_workflow_keys(role).unwrap(), &[key]);
            assert_eq!(linux_release_acquisition_role(workflow_ref).unwrap(), role);
            let retained = exact_assignment_string(&document, key).unwrap();
            assert_eq!(retained, workflow);
            validate_linux_release_workflow_domain(role, std::slice::from_ref(&retained)).unwrap();
            let identity = format!("https://github.com/{repository}/{workflow}@{trusted_ref}");
            assert!(github_workflow_identity_matches(
                &identity,
                repository,
                &retained,
                trusted_ref
            ));
        }
        for (role, substituted) in [
            ("linux-release-acquirer", COLLECTION_AUTHORITY_WORKFLOW_PATH),
            (
                "collection-linux-release-acquirer",
                ".github/workflows/nightly.yml",
            ),
        ] {
            assert!(
                validate_linux_release_workflow_domain(role, &[substituted.to_owned()]).is_err()
            );
        }
        let duplicated = format!(
            "{document}\ncollection_release_oracle_workflow = \"{COLLECTION_AUTHORITY_WORKFLOW_PATH}\"\n"
        );
        assert!(
            exact_assignment_string(&duplicated, "collection_release_oracle_workflow").is_err()
        );
        assert!(
            linux_release_acquisition_role(
                "Portfoligno/hell-rs/.github/workflows/other.yml@refs/heads/main"
            )
            .is_err()
        );
    }

