    #[test]
    fn mutation_detection_requires_one_exact_nonignored_test() {
        let test = "assurance::tests::exact_mutant";
        let passing = format!(
            "running 1 test\ntest {test} ... ok\n\ntest result: ok. 1 passed; 0 failed; 0 ignored; 0 measured; 72 filtered out; finished in 0.00s\n"
        );
        assert!(exact_test_harness_success(passing.as_bytes(), test).unwrap());
        let rejected = format!(
            "running 1 test\ntest {test} ... FAILED\n\ntest result: FAILED. 0 passed; 1 failed; 0 ignored; 0 measured; 72 filtered out; finished in 0.00s\n"
        );
        assert!(exact_test_harness_failure(rejected.as_bytes(), test).unwrap());
        let zero = "running 0 tests\n\ntest result: ok. 0 passed; 0 failed; 0 ignored; 0 measured; 73 filtered out; finished in 0.00s\n";
        assert!(!exact_test_harness_success(zero.as_bytes(), test).unwrap());
        assert!(
            !exact_test_harness_success(
                passing.replace(" ... ok", " ... ignored").as_bytes(),
                test,
            )
            .unwrap()
        );
        assert!(
            !exact_test_harness_success(format!("{passing}test {test} ... ok\n").as_bytes(), test,)
                .unwrap()
        );
        assert!(!exact_test_harness_failure(passing.as_bytes(), test).unwrap());
    }

