    #[test]
    fn noncritical_survivor_is_governed_by_the_committed_family_threshold() {
        let issued_at = crate::custody_ops::current_utc_timestamp().unwrap();
        let report = parse_json(&format!(
            "{{\"issuedAt\":{issued_at:?},\"assuranceMutantsRequired\":0,\"assuranceMutantsDetected\":0,\"criticalMutantsRequired\":0,\"criticalMutantsDetected\":0,\"undetectedCriticalMutants\":0,\"familyScoresPerMille\":{{\"numeric\":500}}}}"
        ))
        .unwrap();
        let mutants = parse_json(
            "[{\"class\":\"semantic\",\"criticality\":\"noncritical\",\"detected\":true,\"family\":\"numeric\"},{\"class\":\"semantic\",\"criticality\":\"noncritical\",\"detected\":false,\"family\":\"numeric\"}]",
        )
        .unwrap();
        let families = BTreeSet::from(["numeric"]);
        let accepted_policy = "required_assurance_mutants_detected = \"all\"\ncritical_mutants_must_all_be_detected = true\nminimum_semantic_family_score_per_mille = 500\nmaximum_report_age_days = 14\n";
        assert!(
            verify_mutation_totals(
                report.object().unwrap(),
                mutants.array().unwrap(),
                &families,
                accepted_policy,
            )
            .is_ok()
        );
        let rejected_policy = accepted_policy.replace(
            "minimum_semantic_family_score_per_mille = 500",
            "minimum_semantic_family_score_per_mille = 501",
        );
        assert!(
            verify_mutation_totals(
                report.object().unwrap(),
                mutants.array().unwrap(),
                &families,
                &rejected_policy,
            )
            .is_err()
        );
        let critical_report = parse_json(&format!(
            "{{\"issuedAt\":{issued_at:?},\"assuranceMutantsRequired\":0,\"assuranceMutantsDetected\":0,\"criticalMutantsRequired\":1,\"criticalMutantsDetected\":0,\"undetectedCriticalMutants\":1,\"familyScoresPerMille\":{{\"numeric\":500}}}}"
        ))
        .unwrap();
        let critical_mutants = parse_json(
            "[{\"class\":\"semantic\",\"criticality\":\"critical\",\"detected\":false,\"family\":\"numeric\"},{\"class\":\"semantic\",\"criticality\":\"noncritical\",\"detected\":true,\"family\":\"numeric\"}]",
        )
        .unwrap();
        assert!(
            verify_mutation_totals(
                critical_report.object().unwrap(),
                critical_mutants.array().unwrap(),
                &families,
                accepted_policy,
            )
            .is_err()
        );
    }

    #[test]
    fn custody_policy_rejects_identity_and_retention_substitution() {
        let digest = test_digest(b"custody-manifest");
        let mut copy = parse_json(&format!(
            "{{\"accountOrTenant\":\"1001\",\"candidateEpochMatch\":true,\"contentSha256\":\"{digest}\",\"encryptionAtRest\":true,\"innerManifestValid\":true,\"objectLock\":true,\"objectVersion\":\"v1\",\"provider\":\"primary\",\"retentionYears\":7,\"retrievedBy\":\"retriever\",\"retrievedPath\":\"copy\",\"retrieverStableId\":\"role-b\",\"retrievedSha256\":\"{digest}\",\"scrubAgeDays\":0,\"trustDomain\":\"domain-a\",\"uploadReceiptSha256\":\"{digest}\",\"uploadedBy\":\"uploader\",\"uploaderStableId\":\"role-a\"}}"
        ))
        .unwrap()
        .object()
        .unwrap()
        .clone();
        let original = custody_copy_core_digest(&copy).unwrap();
        copy.insert("retentionYears".to_owned(), JsonValue::Number(1));
        assert_ne!(custody_copy_core_digest(&copy).unwrap(), original);
        copy.insert(
            "uploaderStableId".to_owned(),
            JsonValue::String("role-b".to_owned()),
        );
        assert_eq!(
            json_member(&copy, "uploaderStableId")
                .unwrap()
                .string()
                .unwrap(),
            json_member(&copy, "retrieverStableId")
                .unwrap()
                .string()
                .unwrap()
        );
    }

    #[test]
    fn semantic_mutant_families_have_named_gate_checks() {
        let catalog = read_text(&root().join("compat").join("mutants.toml")).unwrap();
        require_assignment(&catalog, "schema_version", "2").unwrap();
        require_assignment(
            &catalog,
            "execution_strategy",
            "\"baseline-pass-mutant-fail\"",
        )
        .unwrap();
        let ids = assignment_string_array(&catalog, "ids").unwrap();
        let families = assignment_string_array(&catalog, "families").unwrap();
        let tests = assignment_string_array(&catalog, "tests").unwrap();
        let packages = assignment_string_array(&catalog, "packages").unwrap();
        let targets = assignment_string_array(&catalog, "targets").unwrap();
        let sites = assignment_string_array(&catalog, "mutation_sites").unwrap();
        let obligations = assignment_string_array(&catalog, "obligation_ids").unwrap();
        let claim_groups = assignment_string_array(&catalog, "claim_group_ids").unwrap();
        let classes = assignment_string_array(&catalog, "classes").unwrap();
        let criticalities = assignment_string_array(&catalog, "criticalities").unwrap();
        assert_eq!(ids.len(), families.len());
        assert_eq!(ids.len(), tests.len());
        assert_eq!(ids.len(), packages.len());
        assert_eq!(ids.len(), targets.len());
        assert_eq!(ids.len(), sites.len());
        assert_eq!(ids.len(), obligations.len());
        assert_eq!(ids.len(), claim_groups.len());
        assert_eq!(ids.len(), classes.len());
        assert_eq!(ids.len(), criticalities.len());
        assert_eq!(tests.iter().collect::<BTreeSet<_>>().len(), tests.len());
        for family in [
            "strictness-laziness",
            "numeric",
            "text-utf8",
            "collection-ordering",
            "json-precision",
            "date-time",
            "process-cancellation",
            "resource-cleanup",
            "http-streaming",
            "options-parsing",
            "diagnostic-normalization",
        ] {
            assert!(families.iter().any(|observed| observed == family));
        }
        assert!(
            tests
                .iter()
                .all(|test| !test.contains("active_assurance_mutant"))
        );
        assert!(packages.iter().all(|package| matches!(
            package.as_str(),
            "hell-ci" | "hell-runtime" | "hell-testkit"
        )));
        for ((package, target), test) in packages.iter().zip(&targets).zip(&tests) {
            assert!(mutation_cargo_arguments(package, target, test).is_ok());
        }
    }

    #[test]
    #[ignore = "runs the retained baseline/activated production mutation campaign"]
    fn committed_mutation_campaign_kills_every_named_mutant() {
        let catalog = read_text(&root().join("compat").join("mutants.toml")).unwrap();
        let ids = assignment_string_array(&catalog, "ids").unwrap();
        let families = assignment_string_array(&catalog, "families").unwrap();
        let tests = assignment_string_array(&catalog, "tests").unwrap();
        let packages = assignment_string_array(&catalog, "packages").unwrap();
        let targets = assignment_string_array(&catalog, "targets").unwrap();
        let sites = assignment_string_array(&catalog, "mutation_sites").unwrap();
        let obligations = assignment_string_array(&catalog, "obligation_ids").unwrap();
        let claim_groups = assignment_string_array(&catalog, "claim_group_ids").unwrap();
        let classes = assignment_string_array(&catalog, "classes").unwrap();
        let criticalities = assignment_string_array(&catalog, "criticalities").unwrap();
        let directory = root()
            .join("target")
            .join("assurance-mutation-campaign-test");
        let _ = fs::remove_dir_all(&directory);
        fs::create_dir_all(&directory).unwrap();
        let results = directory.join("mutation-results");
        fs::create_dir(&results).unwrap();
        let mut survivors = Vec::new();
        let mut records = Vec::new();
        for index in 0..ids.len() {
            let record = run_assurance_mutant(
                &results,
                index,
                MutationSpec {
                    id: &ids[index],
                    family: &families[index],
                    package: &packages[index],
                    target: &targets[index],
                    test: &tests[index],
                    mutation_site: &sites[index],
                    obligation_id: &obligations[index],
                    claim_group_id: &claim_groups[index],
                    class: &classes[index],
                    criticality: &criticalities[index],
                },
            )
            .unwrap();
            if !json_member(record.object().unwrap(), "detected")
                .unwrap()
                .boolean()
                .unwrap()
            {
                survivors.push(ids[index].as_str());
            }
            records.push(record);
        }
        let candidate = git_output(&root(), &["rev-parse", "HEAD"]).unwrap();
        let (_, epoch) = epoch(&root()).unwrap();
        let issued_at = crate::custody_ops::current_utc_timestamp().unwrap();
        let report = mutation_report_json(
            candidate.trim(),
            &epoch.hex(),
            &issued_at,
            &record_digest(&root().join("compat").join("mutants.toml")).unwrap(),
            &record_digest(&root().join("compat").join("mutation-policy.toml")).unwrap(),
            &records,
        )
        .unwrap();
        fs::write(directory.join("mutation-score.pending.json"), report).unwrap();
        assert!(
            survivors.is_empty(),
            "mutants survived their exact named checks: {survivors:?}"
        );
    }

    #[test]
    fn bound_detail_schemas_reject_forged_zero_blocker_wrappers() {
        let directory = std::env::temp_dir().join(format!(
            "hell-assurance-bound-details-{}",
            std::process::id()
        ));
        let _ = fs::remove_dir_all(&directory);
        fs::create_dir(&directory).unwrap();
        let candidate = test_git_sha('4');
        let epoch = test_digest(b"bound-epoch");
        let path = directory.join("details.json");
        fs::write(
            &path,
            format!(
                "{{\"schemaVersion\":1,\"candidateSourceCommit\":\"{candidate}\",\"assuranceEpochSha256\":\"{epoch}\",\"totalClaimCells\":8,\"explicitDispositionCells\":8,\"ambiguousClaimScopes\":0,\"missingObligations\":0,\"requiredPlatformGaps\":0,\"semanticCoverageGaps\":0,\"unreachedTargets\":0}}\n"
            ),
        )
        .unwrap();
        assert!(verify_bound_details(&path, "claim-coverage", &candidate, &epoch).is_err());
        let forged = fs::read_to_string(&path)
            .unwrap()
            .replace("\"semanticCoverageGaps\":0", "\"semanticCoverageGaps\":1");
        fs::write(&path, forged).unwrap();
        assert!(verify_bound_details(&path, "claim-coverage", &candidate, &epoch).is_err());
        fs::write(
            &path,
            format!(
                "{{\"schemaVersion\":1,\"candidateSourceCommit\":\"{candidate}\",\"assuranceEpochSha256\":\"{epoch}\",\"applications\":2,\"auditedApplications\":1,\"exactClaimsUsingNormalizers\":0,\"failedMutants\":0,\"protectedFieldChanges\":0,\"unsafeNormalizers\":0}}\n"
            ),
        )
        .unwrap();
        assert!(verify_bound_details(&path, "normalizer-audit", &candidate, &epoch).is_err());
        fs::remove_dir_all(directory).unwrap();
    }

    #[test]
    fn claim_status_references_exact_signed_audit_records() {
        let directory = std::env::temp_dir().join(format!(
            "hell-assurance-status-links-{}",
            std::process::id()
        ));
        let _ = fs::remove_dir_all(&directory);
        fs::create_dir(&directory).unwrap();
        let evidence = test_digest(b"raw-evidence");
        let candidate = test_git_sha('8');
        let epoch = test_digest(b"status-epoch");
        let application_ref = normalizer_application_ref(
            "Bool.bool",
            "presentation",
            "linux-amd64",
            &evidence,
            "candidate",
            "diagnostic-path-separator-v1",
            "claim-stderr",
        )
        .unwrap();
        let application_text = format!(
            "{{\"applicationRef\":\"{application_ref}\",\"applicationScope\":\"claim-stderr\",\"assuranceEpochSha256\":\"{epoch}\",\"builtin\":\"Bool.bool\",\"candidateSourceCommit\":\"{candidate}\",\"dimension\":\"presentation\",\"evidenceRef\":\"{evidence}\",\"idempotent\":true,\"inputSha256\":\"{}\",\"mutationSuiteSha256\":\"{}\",\"normalizerId\":\"diagnostic-path-separator-v1\",\"observationRole\":\"candidate\",\"outputSha256\":\"{}\",\"platform\":\"linux-amd64\",\"profile\":\"upstream\",\"protectedFieldsUnchanged\":true}}",
            test_digest(b"raw"),
            test_digest(b"mutants"),
            test_digest(b"normalized"),
        );
        let claim_details = directory.join("claim-details.json");
        let normalizer_details = directory.join("normalizer-details.json");
        let divergence_details = directory.join("divergence-details.json");
        fs::write(
            &claim_details,
            format!(
                "{{\"cells\":[{{\"builtin\":\"Bool.bool\",\"dimension\":\"presentation\",\"profile\":\"upstream\",\"platform\":\"linux-amd64\",\"proposedStatus\":\"normalized\",\"evidenceRefs\":[{{\"bundleSha256\":\"{evidence}\"}}],\"normalizerIds\":[\"diagnostic-path-separator-v1\"],\"normalizerApplicationRefs\":[\"{application_ref}\"],\"divergenceRecordRef\":null}}]}}\n"
            ),
        )
        .unwrap();
        fs::write(
            &normalizer_details,
            format!("{{\"applicationRecords\":[{application_text}]}}\n"),
        )
        .unwrap();
        fs::write(&divergence_details, "{\"records\":[]}\n").unwrap();
        let wrapper = |details: &Path| {
            format!(
                "{{\"detailsPath\":{},\"detailsSha256\":\"{}\"}}\n",
                json_string(&path_text(details).unwrap()),
                record_digest(details).unwrap(),
            )
        };
        let claim = directory.join("claim.json");
        let normalizer = directory.join("normalizer.json");
        let divergence = directory.join("divergence.json");
        fs::write(&claim, wrapper(&claim_details)).unwrap();
        fs::write(&normalizer, wrapper(&normalizer_details)).unwrap();
        fs::write(&divergence, wrapper(&divergence_details)).unwrap();
        assert!(
            verify_claim_status_consistency(&claim, &normalizer, &divergence, &directory,).is_ok()
        );
        let forged = fs::read_to_string(&claim_details)
            .unwrap()
            .replace("linux-amd64", "windows-amd64");
        fs::write(&claim_details, forged).unwrap();
        fs::write(&claim, wrapper(&claim_details)).unwrap();
        assert!(
            verify_claim_status_consistency(&claim, &normalizer, &divergence, &directory,).is_err()
        );
        fs::remove_dir_all(directory).unwrap();
    }

