    fn semantic_fuzz_build_plan() -> JsonValue {
        let digest = test_digest(b"semantic fuzz provenance");
        let command = |name: &str| {
            JsonValue::Object(BTreeMap::from([
                ("name".to_owned(), JsonValue::String(name.to_owned())),
                ("status".to_owned(), JsonValue::Number(0)),
                ("stderrSha256".to_owned(), JsonValue::String(digest.clone())),
                ("stdoutSha256".to_owned(), JsonValue::String(digest.clone())),
            ]))
        };
        let package = JsonValue::Object(BTreeMap::from([
            ("name".to_owned(), JsonValue::String("base".to_owned())),
            (
                "providerUrls".to_owned(),
                JsonValue::Array(vec![JsonValue::String(
                    "https://packages.example.invalid/base.tar.gz".to_owned(),
                )]),
            ),
            (
                "retainedPath".to_owned(),
                JsonValue::String("package-sources/base.tar.gz".to_owned()),
            ),
            (
                "sourceChecksumSha256".to_owned(),
                JsonValue::String(digest.clone()),
            ),
            (
                "sourceKind".to_owned(),
                JsonValue::String("archive".to_owned()),
            ),
            ("version".to_owned(), JsonValue::String("1.0".to_owned())),
        ]));
        let mut plan = BTreeMap::from([
            ("buildOffline".to_owned(), JsonValue::Bool(true)),
            (
                "commands".to_owned(),
                JsonValue::Array(vec![command("prefetch"), command("build")]),
            ),
            (
                "declaredCompilerOptions".to_owned(),
                JsonValue::Array(Vec::new()),
            ),
            (
                "declaredResolver".to_owned(),
                JsonValue::String("resolver".to_owned()),
            ),
            (
                "executableTarget".to_owned(),
                JsonValue::String("hell".to_owned()),
            ),
            (
                "localDependencies".to_owned(),
                JsonValue::Array(vec![JsonValue::String("hell".to_owned())]),
            ),
            (
                "localDependencyEscapes".to_owned(),
                JsonValue::Array(Vec::new()),
            ),
            (
                "mutableVcsDependencies".to_owned(),
                JsonValue::Array(Vec::new()),
            ),
            ("packageDigestsComplete".to_owned(), JsonValue::Bool(true)),
            ("packageFlags".to_owned(), JsonValue::Array(Vec::new())),
            ("packages".to_owned(), JsonValue::Array(vec![package])),
            ("reviewRequired".to_owned(), JsonValue::Array(Vec::new())),
            ("schemaVersion".to_owned(), JsonValue::Number(2)),
            (
                "sourceAcquisitionComplete".to_owned(),
                JsonValue::Bool(true),
            ),
            (
                "sourceCommit".to_owned(),
                JsonValue::String(test_git_sha('5')),
            ),
            ("sourceTreeClean".to_owned(), JsonValue::Bool(true)),
            (
                "stackVersion".to_owned(),
                JsonValue::String("2.15".to_owned()),
            ),
        ]);
        for field in [
            "compilerInfoSha256",
            "resolverSha256",
            "sourceArchiveSha256",
            "sourceFilesSha256",
            "sourceTree",
            "stackExecutableSha256",
            "stackYamlSha256",
            "toolchainSha256",
        ] {
            plan.insert(field.to_owned(), JsonValue::String(digest.clone()));
        }
        JsonValue::Object(plan)
    }

    #[test]
    fn semantic_fuzz_target_provenance_calls_the_exact_build_plan_validator() {
        let directory = create_private_temp_directory("hell-provenance-semantic-fuzz").unwrap();
        let path = directory.join("build-plan.json");
        let canonical = canonical_json_bytes(&semantic_fuzz_build_plan()).unwrap();
        fs::write(&path, &canonical).unwrap();
        assert!(verify_build_plan(&path).is_ok());
        for index in (0..canonical.len()).step_by(canonical.len().div_ceil(256)) {
            let mut mutated = canonical.clone();
            mutated[index] = 0;
            fs::write(&path, mutated).unwrap();
            let outcome = std::panic::catch_unwind(|| verify_build_plan(&path));
            assert!(outcome.is_ok(), "provenance validator panicked at {index}");
            assert!(
                outcome.unwrap().is_err(),
                "provenance accepted NUL at {index}"
            );
        }
        fs::remove_dir_all(directory).unwrap();
    }

