    fn collection_fixture_repository(temporary: &Path) -> (PathBuf, String) {
        let repository = temporary.join("repository");
        let workflow_path = repository.join(COLLECTION_AUTHORITY_WORKFLOW_PATH);
        fs::create_dir_all(workflow_path.parent().unwrap()).unwrap();
        fs::write(
            &workflow_path,
            include_bytes!("../../../.github/workflows/collection-authority.yml"),
        )
        .unwrap();
        for arguments in [
            &["init", "--quiet"][..],
            &["add", COLLECTION_AUTHORITY_WORKFLOW_PATH][..],
            &[
                "-c",
                "commit.gpgsign=false",
                "-c",
                "user.name=Collection Fixture",
                "-c",
                "user.email=collection-fixture@example.invalid",
                "commit",
                "--quiet",
                "-m",
                "fixture",
            ][..],
        ] {
            assert!(
                Command::new("git")
                    .arg("-C")
                    .arg(&repository)
                    .args(arguments)
                    .status()
                    .unwrap()
                    .success()
            );
        }
        let head = git_output(&repository, &["rev-parse", "HEAD"])
            .unwrap()
            .trim()
            .to_owned();
        (repository, head)
    }

