    #[test]
    fn collection_provider_replay_binds_pages_run_time_archive_tree_and_subject() {
        let fixture = collection_provider_fixture();
        let baseline = verify_collection_provider_artifact_with_repository_id(
            &fixture.repository,
            &fixture.provider,
            &fixture.copied,
            "linux-amd64",
            123,
        )
        .unwrap();
        assert_eq!(baseline.repository_id, 123);
        assert_eq!(baseline.workflow_ref, COLLECTION_AUTHORITY_WORKFLOW_REF);
        assert_eq!(baseline.event, "workflow_dispatch");

        fs::write(
            fixture.provider.join("artifact-api-pages/page-0002.json"),
            b"{\"artifacts\":[],\"total_count\":1}\n",
        )
        .unwrap();
        assert!(
            verify_collection_provider_artifact_with_repository_id(
                &fixture.repository,
                &fixture.provider,
                &fixture.copied,
                "linux-amd64",
                123
            )
            .is_err()
        );
        fs::remove_file(fixture.provider.join("artifact-api-pages/page-0002.json")).unwrap();

        fs::write(
            fixture.provider.join("job-api-pages/page-0002.json"),
            b"{\"jobs\":[],\"total_count\":1}\n",
        )
        .unwrap();
        assert!(
            verify_collection_provider_artifact_with_repository_id(
                &fixture.repository,
                &fixture.provider,
                &fixture.copied,
                "linux-amd64",
                123
            )
            .is_err()
        );
        fs::remove_file(fixture.provider.join("job-api-pages/page-0002.json")).unwrap();

        assert!(
            verify_collection_provider_artifact_with_repository_id(
                &fixture.repository,
                &fixture.provider,
                &fixture.copied,
                "linux-amd64",
                124
            )
            .is_err()
        );
        let mut run = fixture.run;
        run.object_mut()
            .unwrap()
            .get_mut("repository")
            .unwrap()
            .object_mut()
            .unwrap()
            .insert("id".to_owned(), JsonValue::Number(124));
        fs::write(
            fixture.platform_root.join("provider-selected-run.json"),
            canonical_json_bytes(&run).unwrap(),
        )
        .unwrap();
        assert!(
            verify_collection_provider_artifact_with_repository_id(
                &fixture.repository,
                &fixture.provider,
                &fixture.copied,
                "linux-amd64",
                123
            )
            .is_err()
        );
        fs::remove_dir_all(fixture.temporary).unwrap();
    }

