    fn assert_committed_review_policy(policy: &ReviewPolicy) {
        assert!(
            policy
                .claim_reviewer_may_not_be_evidence_run_actor
                .required()
        );
        assert!(
            policy
                .platform_reviewer_may_not_be_oracle_build_trigger
                .required()
        );
        assert!(
            policy
                .promotion_approver_may_not_be_claim_proposer
                .required()
        );
        assert!(
            !policy
                .promotion_approver_may_not_be_candidate_commit_author
                .required()
        );
    }

    #[test]
    fn review_policy_is_strict_and_all_separation_rules_are_authoritative() {
        let directory = std::env::temp_dir().join(format!(
            "hell-assurance-review-policy-{}",
            std::process::id()
        ));
        let _ = fs::remove_dir_all(&directory);
        fs::create_dir_all(directory.join("compat")).unwrap();
        let committed = read_text(&root().join("compat").join("review-policy.toml")).unwrap();
        let policy = directory.join("compat").join("review-policy.toml");
        fs::write(&policy, &committed).unwrap();
        let loaded = load_review_policy(&directory).unwrap();
        assert_committed_review_policy(&loaded);

        for key in [
            "claim_reviewer_may_not_be_evidence_run_actor",
            "platform_reviewer_may_not_be_oracle_build_trigger",
            "promotion_approver_may_not_be_claim_proposer",
            "require_external_or_separate_team_for_artifact_authenticity",
        ] {
            fs::write(
                &policy,
                committed.replace(&format!("{key} = true"), &format!("{key} = false")),
            )
            .unwrap();
            assert!(
                load_review_policy(&directory).is_ok(),
                "policy rejected {key}=false"
            );
        }
        fs::write(
            &policy,
            committed.replace(
                "promotion_approver_may_not_be_candidate_commit_author = false",
                "promotion_approver_may_not_be_candidate_commit_author = true",
            ),
        )
        .unwrap();
        let strict_candidate_author = load_review_policy(&directory).unwrap();
        assert!(
            strict_candidate_author
                .promotion_approver_may_not_be_candidate_commit_author
                .required()
        );
        fs::write(&policy, format!("{committed}unknown_review_rule = true\n")).unwrap();
        assert!(load_review_policy(&directory).is_err());
        fs::write(
            &policy,
            committed.replace("minimum_distinct_people = 2", "minimum_distinct_people = 3"),
        )
        .unwrap();
        let raised = load_review_policy(&directory).unwrap();
        assert!(require_minimum_distinct_people(2, raised.minimum_distinct_people).is_err());
        assert!(require_minimum_distinct_people(3, raised.minimum_distinct_people).is_ok());

        let action = |role: &str, account: &str| ReviewGraphAction {
            action_kind: review_action_kind(role).to_owned(),
            stable_account_id: account.to_owned(),
            subject: format!("subject-{account}"),
            signer_fingerprint: test_digest(format!("key-{account}").as_bytes()),
            role: role.to_owned(),
            review_sha256: test_digest(format!("review-{role}-{account}").as_bytes()),
            environment: "test-environment".to_owned(),
            team: "Portfoligno/test-team".to_owned(),
            provider_run_id: 1,
            provider_run_attempt: 1,
        };
        let mut actions = BTreeSet::from([
            action("claim-reviewer", "101"),
            action("oracle-builder", "201"),
            action("custody-provider", "301"),
            action("candidate-author", "401"),
        ]);
        assert_eq!(human_reviewer_subject_count(&actions), 1);
        actions.insert(action("platform-reviewer", "102"));
        assert_eq!(human_reviewer_subject_count(&actions), 2);

        let candidate_author = BTreeSet::from([action("candidate-author", "500")]);
        assert!(verify_promotion_approver_independence(&candidate_author, "500", &loaded,).is_ok());
        assert!(
            verify_promotion_approver_independence(
                &candidate_author,
                "500",
                &strict_candidate_author,
            )
            .is_err()
        );
        fs::remove_dir_all(directory).unwrap();
    }

    #[test]
    fn observed_acquisition_network_schema_rejects_old_and_extra_fields() {
        let directory = std::env::temp_dir().join(format!(
            "hell-assurance-observed-network-{}",
            std::process::id()
        ));
        let _ = fs::remove_dir_all(&directory);
        fs::create_dir(&directory).unwrap();
        let output_digest = test_digest(b"oracle-command-output");
        let package_digest = test_digest(b"retained-package-source");
        let current = format!(
            concat!(
                "{{\"schemaVersion\":2,\"buildOffline\":true,",
                "\"networkMode\":\"observed-acquisition-then-isolated-offline-build\",",
                "\"resolverLockSha256\":\"{output_digest}\",",
                "\"acquisitionStdoutSha256\":\"{output_digest}\",",
                "\"acquisitionStderrSha256\":\"{output_digest}\",",
                "\"offlineDependencyStdoutSha256\":\"{output_digest}\",",
                "\"offlineDependencyStderrSha256\":\"{output_digest}\",",
                "\"offlineBuildStdoutSha256\":\"{output_digest}\",",
                "\"offlineBuildStderrSha256\":\"{output_digest}\",",
                "\"recordedDownloads\":[{{\"kind\":\"observed-https-access\",",
                "\"url\":\"https://hackage.haskell.org/package/example-1.0.tar.gz\"}}],",
                "\"retainedPackageSources\":[{{\"name\":\"example\",\"version\":\"1.0\",",
                "\"sourceChecksumSha256\":\"{package_digest}\",",
                "\"retainedPath\":\"package-sources/0\",",
                "\"providerUrls\":[\"https://hackage.haskell.org/package/example-1.0.tar.gz\"]}}],",
                "\"unexpectedEndpoints\":[],\"unrecordedDownloads\":[]}}\n"
            ),
            output_digest = output_digest,
            package_digest = package_digest,
        );
        let path = directory.join("network.json");
        fs::write(&path, &current).unwrap();
        assert!(verify_network_inventory(&path).is_ok());

        let old_mode = current.replace(
            "observed-acquisition-then-isolated-offline-build",
            "stack-offline-preprovisioned-cache",
        );
        fs::write(&path, old_mode).unwrap();
        assert!(verify_network_inventory(&path).is_err());

        let extra_key = current.replacen(
            "{\"schemaVersion\":2",
            "{\"schemaVersion\":2,\"uncheckedComplete\":true",
            1,
        );
        fs::write(&path, extra_key).unwrap();
        assert!(verify_network_inventory(&path).is_err());
        fs::remove_dir_all(directory).unwrap();
    }

