    #[test]
    fn signed_review_verification_binds_payload_role_identity_and_artifacts() {
        let (directory, envelope_path, allowed, review_id, signature, payload) =
            signed_review_fixture();
        let verified = verify_review_envelope(&envelope_path, &allowed).unwrap();
        assert_eq!(verified.role, "claim-reviewer");
        assert!(
            verified
                .reviewed_artifacts
                .contains(&test_digest(b"reviewed-artifact"))
        );
        assert_signed_review_historical_policy(
            &directory,
            &envelope_path,
            &allowed,
            &review_id,
            &verified.issued_at,
        );
        let mut invalid_signature = signature;
        invalid_signature[0] ^= 1;
        let tampered = format!(
            "{{\"payloadType\":\"application/vnd.hell-rs.assurance+json\",\"payload\":{},\"signatures\":[{{\"scheme\":\"ssh\",\"keyid\":\"claim-reviewer:alice\",\"sig\":{}}}]}}\n",
            json_string(&encode_base64(payload.as_bytes())),
            json_string(&encode_base64(&invalid_signature))
        );
        fs::write(&envelope_path, tampered).unwrap();
        assert!(verify_review_envelope(&envelope_path, &allowed).is_err());
        fs::remove_dir_all(directory).unwrap();
    }

    fn signed_review_fixture() -> (PathBuf, PathBuf, PathBuf, String, Vec<u8>, String) {
        let directory = std::env::temp_dir().join(format!(
            "hell-assurance-signed-review-{}",
            std::process::id()
        ));
        let _ = fs::remove_dir_all(&directory);
        fs::create_dir(&directory).unwrap();
        let key = directory.join("review-key");
        let generated = Command::new("ssh-keygen")
            .args([
                OsStr::new("-q"),
                OsStr::new("-t"),
                OsStr::new("ed25519"),
                OsStr::new("-N"),
                OsStr::new(""),
                OsStr::new("-f"),
                key.as_os_str(),
            ])
            .status()
            .unwrap();
        assert!(generated.success());
        let public = fs::read_to_string(key.with_extension("pub")).unwrap();
        let allowed = directory.join("allowed_signers");
        fs::write(
            &allowed,
            format!("claim-reviewer:alice {}\n", public.trim()),
        )
        .unwrap();
        fs::write(
            directory.join("surveillance-policy.toml"),
            "mutation_report_maximum_age_days = 14\n",
        )
        .unwrap();
        fs::write(
            directory.join("review-revocations.toml"),
            "revoked_review_ids = []\n",
        )
        .unwrap();
        let candidate = test_git_sha('7');
        let epoch = test_digest(b"review-epoch");
        let artifact = test_digest(b"reviewed-artifact");
        let artifacts = BTreeSet::from([artifact.clone()]);
        let issued_at = crate::custody_ops::current_utc_timestamp().unwrap();
        let findings_sha256 = canonical_json_digest(&JsonValue::Array(Vec::new())).unwrap();
        let review_id = review_statement_id(&ReviewStatementIdentity {
            candidate: &candidate,
            epoch: &epoch,
            role: "claim-reviewer",
            reviewer: "claim-reviewer:alice",
            decision: "accept",
            issued_at: &issued_at,
            artifacts: &artifacts,
            claim_groups: &BTreeMap::new(),
            findings_sha256: &findings_sha256,
        });
        let payload = format!(
            "{{\"schemaVersion\":1,\"reviewId\":\"{review_id}\",\"role\":\"claim-reviewer\",\"reviewer\":\"claim-reviewer:alice\",\"decision\":\"accept\",\"candidateCommit\":\"{candidate}\",\"assuranceEpochSha256\":\"{epoch}\",\"reviewedArtifacts\":[\"{artifact}\"],\"distinctSubjects\":1,\"independenceViolations\":[],\"findings\":[],\"issuedAt\":\"{issued_at}\"}}\n"
        );
        let payload_path = directory.join("payload.json");
        fs::write(&payload_path, payload.as_bytes()).unwrap();
        let signed = Command::new("ssh-keygen")
            .args([
                OsStr::new("-Y"),
                OsStr::new("sign"),
                OsStr::new("-f"),
                key.as_os_str(),
                OsStr::new("-n"),
                OsStr::new("hell-rs-promotion-review"),
                payload_path.as_os_str(),
            ])
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .status()
            .unwrap();
        assert!(signed.success());
        let signature = fs::read(directory.join("payload.json.sig")).unwrap();
        let envelope_path = directory.join("review.dsse.json");
        let envelope = format!(
            "{{\"payloadType\":\"application/vnd.hell-rs.assurance+json\",\"payload\":{},\"signatures\":[{{\"scheme\":\"ssh\",\"keyid\":\"claim-reviewer:alice\",\"sig\":{}}}]}}\n",
            json_string(&encode_base64(payload.as_bytes())),
            json_string(&encode_base64(&signature))
        );
        fs::write(&envelope_path, &envelope).unwrap();
        (
            directory,
            envelope_path,
            allowed,
            review_id,
            signature,
            payload,
        )
    }

