    #[test]
    fn signed_regression_review_binds_exact_provider_subject_digest() {
        let directory = create_private_temp_directory("hell-signed-regression-review").unwrap();
        let review_root = directory.join("review");
        let candidate = test_git_sha('7');
        let epoch = test_digest(b"regression-review-epoch");
        let subject = test_digest(b"provider-bound-regression-review-subject");
        let (review, allowed) =
            signed_regression_review_fixture(&review_root, &candidate, &epoch, &subject).unwrap();
        verify_review_binding(
            &review,
            &allowed,
            "regression-reviewer",
            &candidate,
            &epoch,
            &BTreeSet::from([subject.clone()]),
        )
        .unwrap();
        assert!(
            verify_review_binding(
                &review,
                &allowed,
                "regression-reviewer",
                &candidate,
                &epoch,
                &BTreeSet::from([test_digest(b"substituted-review-subject")]),
            )
            .is_err()
        );
        fs::copy(
            root().join("compat").join("trust-roots.toml"),
            review_root.join("trust-roots.toml"),
        )
        .unwrap();
        assert!(
            verify_review_binding(
                &review,
                &allowed,
                "regression-reviewer",
                &candidate,
                &epoch,
                &BTreeSet::from([subject]),
            )
            .is_err()
        );
        fs::remove_dir_all(directory).unwrap();
    }

    fn assert_signed_review_historical_policy(
        directory: &Path,
        envelope_path: &Path,
        allowed: &Path,
        review_id: &str,
        issued_at: &str,
    ) {
        fs::write(
            directory.join("surveillance-policy.toml"),
            "mutation_report_maximum_age_days = 0\n",
        )
        .unwrap();
        let issued_seconds = utc_timestamp_seconds(issued_at).unwrap();
        assert!(
            verify_review_envelope_with_context_at(
                envelope_path,
                allowed,
                ReviewValidationContext::Fresh,
                issued_seconds,
            )
            .is_err()
        );
        fs::write(
            directory.join("surveillance-policy.toml"),
            "mutation_report_maximum_age_days = 1\n",
        )
        .unwrap();
        assert!(
            verify_review_envelope_with_context_at(
                envelope_path,
                allowed,
                ReviewValidationContext::Fresh,
                issued_seconds + 86_400,
            )
            .is_ok()
        );
        assert!(
            verify_review_envelope_with_context_at(
                envelope_path,
                allowed,
                ReviewValidationContext::Fresh,
                issued_seconds + 86_401,
            )
            .is_err()
        );
        let current_revocations = directory.join("current-review-revocations.toml");
        fs::write(&current_revocations, "revoked_review_ids = []\n").unwrap();
        assert!(
            verify_review_envelope_with_context(
                envelope_path,
                allowed,
                ReviewValidationContext::Historical {
                    current_revocations: &current_revocations,
                },
            )
            .is_ok()
        );
        fs::write(
            &current_revocations,
            format!("revoked_review_ids = [\"{review_id}\"]\n"),
        )
        .unwrap();
        assert!(
            verify_review_envelope_with_context(
                envelope_path,
                allowed,
                ReviewValidationContext::Historical {
                    current_revocations: &current_revocations,
                },
            )
            .is_err()
        );
    }

    #[test]
    fn proposal_approval_rejects_substitution_and_missing_component_bindings() {
        let candidate = test_git_sha('8');
        let epoch = test_digest(b"approval-epoch");
        let merged = test_digest(b"merged-evidence");
        let final_merged = test_digest(b"final-merged-evidence");
        let first = test_digest(b"first-component");
        let second = test_digest(b"second-component");
        let blockers = PROMOTION_BLOCKERS
            .iter()
            .map(|name| format!("{}:0", json_string(name)))
            .collect::<Vec<_>>()
            .join(",");
        let proposal_text = format!(
            "{{\"blockers\":{{{blockers}}},\"mergedManifestSha256\":\"{merged}\",\"finalMergedManifestSha256\":\"{final_merged}\",\"records\":{{\"first\":{{\"path\":\"evidence/first.json\",\"sha256\":\"{first}\"}},\"second\":{{\"path\":\"evidence/second.json\",\"sha256\":\"{second}\"}}}}}}"
        );
        let proposal = parse_json(&proposal_text).unwrap();
        let proposal = proposal.object().unwrap();
        let proposal_digest = sha256_bytes(proposal_text.as_bytes()).hex();
        let provider_selection = test_digest(b"proposal-provider-selection");
        let mut required = proposal_review_artifacts(proposal, &proposal_digest).unwrap();
        required.insert(provider_selection.clone());
        let mut approval = VerifiedReview {
            role: "promotion-approver".to_owned(),
            reviewer: "promotion-approver:alice".to_owned(),
            subject: "alice".to_owned(),
            signer_fingerprint: test_digest(b"alice-key"),
            candidate_commit: candidate.clone(),
            assurance_epoch: epoch.clone(),
            issued_at: "2026-08-09T00:00:00Z".to_owned(),
            artifact_count: required.len(),
            reviewed_artifacts: required,
            reviewed_claim_groups: BTreeMap::new(),
        };
        assert!(
            validate_proposal_approval(
                proposal,
                &proposal_digest,
                &provider_selection,
                &candidate,
                &epoch,
                &approval,
            )
            .is_ok()
        );
        approval.reviewed_artifacts.remove(&first);
        assert!(
            validate_proposal_approval(
                proposal,
                &proposal_digest,
                &provider_selection,
                &candidate,
                &epoch,
                &approval,
            )
            .is_err()
        );
        approval.reviewed_artifacts.insert(first);
        let substituted = test_digest(b"substituted-proposal");
        assert!(
            validate_proposal_approval(
                proposal,
                &substituted,
                &provider_selection,
                &candidate,
                &epoch,
                &approval,
            )
            .is_err()
        );
    }

