    fn write_unavailable_attestation_fixture(directory: &Path) -> (String, Vec<u8>) {
        let primary_directory = directory.join("acquisition").join("primary");
        fs::create_dir_all(&primary_directory).unwrap();
        fs::write(primary_directory.join("payload.bin"), b"artifact payload").unwrap();
        let artifact_set = record_digest(&primary_directory).unwrap();
        let subject = JsonValue::Object(BTreeMap::from([
            (
                "artifact".to_owned(),
                JsonValue::String("native-oracle-merged".to_owned()),
            ),
            (
                "artifactSetSha256".to_owned(),
                JsonValue::String(artifact_set.clone()),
            ),
            (
                "candidateCommit".to_owned(),
                JsonValue::String(test_git_sha('9')),
            ),
            ("schemaVersion".to_owned(), JsonValue::Number(1)),
        ]));
        let subject_path = primary_directory.join("provider-attestation-subject.json");
        fs::write(&subject_path, canonical_json_bytes(&subject).unwrap()).unwrap();
        let subject_sha256 = record_digest(&subject_path).unwrap();
        let artifact = record_digest(&primary_directory).unwrap();
        let lookup = JsonValue::Object(BTreeMap::from([
            (
                "endpoint".to_owned(),
                JsonValue::String("repos/Portfoligno/hell-rs/attestations/test".to_owned()),
            ),
            (
                "error".to_owned(),
                JsonValue::String("not found".to_owned()),
            ),
            (
                "errorSha256".to_owned(),
                JsonValue::String(sha256_bytes(b"not found").hex()),
            ),
            ("schemaVersion".to_owned(), JsonValue::Number(1)),
            ("state".to_owned(), JsonValue::String("absent".to_owned())),
            (
                "subjectSha256".to_owned(),
                JsonValue::String(subject_sha256.clone()),
            ),
        ]));
        let lookup_bytes = canonical_json_bytes(&lookup).unwrap();
        fs::write(
            directory.join("provider-attestation-lookup.json"),
            &lookup_bytes,
        )
        .unwrap();
        let report = JsonValue::Object(BTreeMap::from([
            (
                "artifactSetSha256".to_owned(),
                JsonValue::String(artifact_set),
            ),
            (
                "artifactSha256".to_owned(),
                JsonValue::String(artifact.clone()),
            ),
            (
                "attestedSubjectPath".to_owned(),
                JsonValue::String(
                    "acquisition/primary/provider-attestation-subject.json".to_owned(),
                ),
            ),
            (
                "attestedSubjectSha256".to_owned(),
                JsonValue::String(subject_sha256),
            ),
            (
                "lookupPath".to_owned(),
                JsonValue::String("provider-attestation-lookup.json".to_owned()),
            ),
            (
                "lookupSha256".to_owned(),
                JsonValue::String(sha256_bytes(&lookup_bytes).hex()),
            ),
            (
                "lookupState".to_owned(),
                JsonValue::String("absent".to_owned()),
            ),
            (
                "reason".to_owned(),
                JsonValue::String("provider lookup proved absence".to_owned()),
            ),
            ("schemaVersion".to_owned(), JsonValue::Number(2)),
            (
                "state".to_owned(),
                JsonValue::String("unavailable-reviewed".to_owned()),
            ),
            ("verificationPath".to_owned(), JsonValue::Null),
            ("verificationSha256".to_owned(), JsonValue::Null),
        ]));
        let bytes = canonical_json_bytes(&report).unwrap();
        fs::write(directory.join("attestation-verification.json"), &bytes).unwrap();
        (artifact, bytes)
    }

