    #[test]
    fn committed_regression_row_binds_every_package_authority_column() {
        let verified = VerifiedRegressionProposal {
            package_sha256: test_digest(b"package"),
            candidate_commit: test_git_sha('a'),
            assurance_epoch: test_digest(b"epoch"),
            case_id: "regression-0011223344556677".to_owned(),
            source_sha256: test_digest(b"source"),
            bundle_sha256: test_digest(b"bundle"),
            proposal_sha256: test_digest(b"proposal"),
            template_case_id: "int-plus-boundary-minimum-value".to_owned(),
            source: "main = IO.print $ Int.plus 1 2\n".to_owned(),
            targets_descriptor: "Int.plus:Value:typed-result".to_owned(),
        };
        let mut fields = vec![
            verified.case_id.clone(),
            verified.template_case_id.clone(),
            hex_text(&verified.source),
            verified.source_sha256.clone(),
            verified.candidate_commit.clone(),
            verified.assurance_epoch.clone(),
            verified.package_sha256.clone(),
            verified.proposal_sha256.clone(),
            test_digest(b"review"),
            verified.bundle_sha256.clone(),
            hex_text(&verified.targets_descriptor),
            format!("compat/regressions/{}/proof.tsv", verified.case_id),
            test_digest(b"proof"),
        ];
        let references = fields.iter().map(String::as_str).collect::<Vec<_>>();
        verify_regression_catalog_row_identity(&verified, &references).unwrap();
        for index in [0_usize, 1, 2, 3, 4, 5, 6, 7, 9, 10] {
            let original = fields[index].clone();
            fields[index] = "substituted".to_owned();
            let references = fields.iter().map(String::as_str).collect::<Vec<_>>();
            assert!(verify_regression_catalog_row_identity(&verified, &references).is_err());
            fields[index] = original;
        }
    }

