    #[test]
    fn automatic_regression_source_selection_is_exact_and_fail_closed() {
        let candidate = test_git_sha('b');
        let workflow = ".github/workflows/nightly.yml";
        let mut run = JsonValue::Object(BTreeMap::from([
            (
                "conclusion".to_owned(),
                JsonValue::String("failure".to_owned()),
            ),
            ("event".to_owned(), JsonValue::String("schedule".to_owned())),
            ("head_sha".to_owned(), JsonValue::String(candidate.clone())),
            ("id".to_owned(), JsonValue::Number(71)),
            (
                "path".to_owned(),
                JsonValue::String(format!("{workflow}@main")),
            ),
            ("run_attempt".to_owned(), JsonValue::Number(2)),
            (
                "status".to_owned(),
                JsonValue::String("completed".to_owned()),
            ),
        ]));
        let selected = automatic_regression_run(&run, &candidate, workflow, "schedule")
            .unwrap()
            .unwrap();
        assert_eq!((selected.id, selected.attempt), (71, 2));
        for (field, value) in [
            ("event", JsonValue::String("push".to_owned())),
            ("head_sha", JsonValue::String(test_git_sha('c'))),
            ("conclusion", JsonValue::String("cancelled".to_owned())),
            (
                "path",
                JsonValue::String(format!("{workflow}@refs/heads/feature")),
            ),
        ] {
            let original = run
                .object_mut()
                .unwrap()
                .insert(field.to_owned(), value)
                .unwrap();
            let result = automatic_regression_run(&run, &candidate, workflow, "schedule");
            if field == "path" {
                assert!(result.is_err());
            } else {
                assert!(result.unwrap().is_none());
            }
            run.object_mut().unwrap().insert(field.to_owned(), original);
        }

        let artifact = |id, name: &str| {
            JsonValue::Object(BTreeMap::from([
                ("id".to_owned(), JsonValue::Number(id)),
                ("name".to_owned(), JsonValue::String(name.to_owned())),
            ]))
        };
        let mut response = JsonValue::Object(BTreeMap::from([(
            "artifacts".to_owned(),
            JsonValue::Array(vec![artifact(91, "nightly-71-2")]),
        )]));
        assert_eq!(
            json_member(
                select_automatic_regression_artifact(&response, &selected, "nightly-")
                    .unwrap()
                    .object()
                    .unwrap(),
                "id",
            )
            .unwrap()
            .number()
            .unwrap(),
            91
        );
        json_member_mut(response.object_mut().unwrap(), "artifacts")
            .unwrap()
            .array_mut()
            .unwrap()
            .push(artifact(92, "nightly-copy-71-2"));
        assert!(select_automatic_regression_artifact(&response, &selected, "nightly-").is_ok());
        *json_member_mut(response.object_mut().unwrap(), "artifacts")
            .unwrap()
            .array_mut()
            .unwrap() = vec![artifact(92, "nightly-copy-71-2")];
        assert!(select_automatic_regression_artifact(&response, &selected, "nightly-").is_err());
    }

    #[test]
    fn automatic_regression_pagination_is_complete_unique_and_ordered() {
        let value =
            |id| JsonValue::Object(BTreeMap::from([("id".to_owned(), JsonValue::Number(id))]));
        let page = |total, ids: &[u64]| {
            JsonValue::Object(BTreeMap::from([
                (
                    "artifacts".to_owned(),
                    JsonValue::Array(ids.iter().copied().map(value).collect()),
                ),
                ("total_count".to_owned(), JsonValue::Number(total)),
            ]))
        };
        let first = (51..=150).rev().collect::<Vec<_>>();
        let second = (1..=50).rev().collect::<Vec<_>>();
        let pages = vec![page(150, &first), page(150, &second)];
        assert_eq!(
            validate_github_api_pages(&pages, "artifacts")
                .unwrap()
                .len(),
            150
        );
        for replacement in [
            vec![page(150, &first), page(150, &[51])],
            vec![page(150, &first), page(150, &[49, 50])],
            vec![page(150, &first), page(149, &second)],
        ] {
            assert!(validate_github_api_pages(&replacement, "artifacts").is_err());
        }
    }

    #[test]
    fn external_service_failure_policy_distinguishes_retryable_collection_from_admission() {
        for diagnostic in [
            "HTTP 429: rate limit exceeded",
            "HTTP 503: service unavailable",
            "connection reset by peer",
            "request timed out",
        ] {
            assert_eq!(
                external_service_failure_disposition(
                    ExternalServiceOperation::EvidenceCollection,
                    diagnostic,
                ),
                ExternalServiceFailureDisposition::RetryCollection
            );
            assert_eq!(
                external_service_failure_disposition(
                    ExternalServiceOperation::ProtectedAdmission,
                    diagnostic,
                ),
                ExternalServiceFailureDisposition::RejectAdmission
            );
        }
        assert_eq!(
            external_service_failure_disposition(
                ExternalServiceOperation::EvidenceCollection,
                "HTTP 401: bad credentials",
            ),
            ExternalServiceFailureDisposition::RejectAdmission
        );
        assert!(verify_sigstore_process_result(true, b"").is_ok());
        let unavailable =
            verify_sigstore_process_result(false, b"HTTP 503: transparency log unavailable")
                .unwrap_err();
        assert!(unavailable.contains("admission-rejected"));
        assert!(!unavailable.contains("retryable-collection-failure"));
    }

