    #[test]
    fn review_graph_monotonicity_and_scope_preservation_properties_hold() {
        let actions = BTreeSet::from([
            property_review_action("101", "claim-reviewer"),
            property_review_action("102", "platform-reviewer"),
        ]);
        let roles = actions
            .iter()
            .map(|action| action.role.clone())
            .collect::<BTreeSet<_>>();
        let graph = parse_json(&render_review_graph(
            &test_git_sha('a'),
            &test_digest(b"graph epoch"),
            &actions,
            &roles,
        ))
        .unwrap();
        assert!(
            verify_declared_review_graph(graph.object().unwrap(), &actions, &roles, 2, 2, 2)
                .is_ok()
        );

        for removed in &actions {
            let mut reduced = actions.clone();
            reduced.remove(removed);
            assert!(
                verify_declared_review_graph(graph.object().unwrap(), &reduced, &roles, 2, 2, 2,)
                    .is_err()
            );
        }
        for (field, replacement) in [
            ("role", JsonValue::String("custody-provider".to_owned())),
            (
                "stableAccountId",
                JsonValue::String("scope-expanded-account".to_owned()),
            ),
            (
                "reviewSha256",
                JsonValue::String(test_digest(b"foreign review")),
            ),
        ] {
            let mut changed = graph.clone();
            let first = json_member_mut(changed.object_mut().unwrap(), "actions")
                .unwrap()
                .array_mut()
                .unwrap()
                .first_mut()
                .unwrap()
                .object_mut()
                .unwrap();
            first.insert(field.to_owned(), replacement);
            assert!(
                verify_declared_review_graph(changed.object().unwrap(), &actions, &roles, 2, 2, 2)
                    .is_err()
            );
        }
        let mut prohibited_actions = actions.clone();
        let mut prohibited = property_review_action("103", "custody-provider");
        prohibited.action_kind = "signed-review".to_owned();
        prohibited_actions.insert(prohibited);
        let mut prohibited_roles = roles.clone();
        prohibited_roles.insert("custody-provider".to_owned());
        let prohibited_graph = parse_json(&render_review_graph(
            &test_git_sha('a'),
            &test_digest(b"graph epoch"),
            &prohibited_actions,
            &prohibited_roles,
        ))
        .unwrap();
        assert!(
            verify_declared_review_graph(
                prohibited_graph.object().unwrap(),
                &prohibited_actions,
                &prohibited_roles,
                3,
                2,
                2,
            )
            .is_err()
        );
    }

    #[test]
    fn reviewer_minimum_policy_is_monotone_for_every_small_scope_partition() {
        for people in 0..=12 {
            let mut prior_failed = false;
            for minimum in 0..=14 {
                let accepted = require_minimum_distinct_people(people, minimum).is_ok();
                assert_eq!(accepted, u64::try_from(people).unwrap() >= minimum);
                assert!(!prior_failed || !accepted);
                prior_failed |= !accepted;
            }
        }
    }

    #[test]
    fn fuzz_target_review_graph_parser_and_semantic_verifier_is_fail_closed() {
        let actions = BTreeSet::from([property_review_action("101", "claim-reviewer")]);
        let roles = BTreeSet::from(["claim-reviewer".to_owned()]);
        let canonical = render_review_graph(
            &test_git_sha('b'),
            &test_digest(b"fuzz graph epoch"),
            &actions,
            &roles,
        );
        let actions_start = canonical.find("\"actions\": [").unwrap();
        let actions_end = canonical.find("],\n  \"policyViolations\"").unwrap();
        for index in actions_start..actions_end {
            let mut bytes = canonical.as_bytes().to_vec();
            bytes[index] = match bytes[index] {
                b'a' => b'z',
                b'0' => b'9',
                _ => b'!',
            };
            let input = String::from_utf8(bytes).unwrap();
            let outcome = std::panic::catch_unwind(|| {
                parse_json(&input).and_then(|value| {
                    verify_declared_review_graph(value.object()?, &actions, &roles, 1, 1, 1)
                })
            });
            assert!(outcome.is_ok(), "graph parser panicked at byte {index}");
            assert!(
                outcome.unwrap().is_err(),
                "mutated graph was accepted at byte {index}"
            );
        }
    }

    #[test]
    fn regression_catalog_canonicalization_round_trips_one_exact_row() {
        let directory = create_private_temp_directory("hell-regression-catalog-property").unwrap();
        let compatibility = directory.join("compat");
        fs::create_dir(&compatibility).unwrap();
        let catalog_path = compatibility.join("regression-corpus.tsv");
        let header = "schema_version\t2\ncolumns\tcase_id\ttemplate_case_id\tsource_hex\tsource_sha256\tcandidate_commit\tassurance_epoch_sha256\tpackage_sha256\tproposal_sha256\treview_sha256\tbundle_sha256\ttargets_hex\tproof_path\tproof_manifest_sha256\n";
        fs::write(&catalog_path, header).unwrap();
        let case_id = "regression-property-0001";
        let row = format!("{case_id}\t{}\n", ["value"; 12].join("\t"));
        let updated = regression_updated_catalog(&directory, case_id, &row).unwrap();
        assert_eq!(updated, format!("{header}{row}"));
        fs::write(&catalog_path, &updated).unwrap();
        assert!(regression_updated_catalog(&directory, case_id, &row).is_err());

        fs::write(&catalog_path, header).unwrap();
        for malformed in [
            row.trim_end().to_owned(),
            format!("{case_id}\t{}\n", ["value"; 11].join("\t")),
            format!("{case_id}\t{}\textra\n", ["value"; 12].join("\t")),
            row.replace('\n', "\r\n"),
        ] {
            assert!(regression_updated_catalog(&directory, case_id, &malformed).is_err());
        }
        fs::remove_dir_all(directory).unwrap();
    }

    #[test]
    fn regression_catalog_property_matrix_round_trips_arbitrary_canonical_rows() {
        let directory = create_private_temp_directory("hell-regression-catalog-matrix").unwrap();
        let compatibility = directory.join("compat");
        fs::create_dir(&compatibility).unwrap();
        let catalog_path = compatibility.join("regression-corpus.tsv");
        let header = "schema_version\t2\ncolumns\tcase_id\ttemplate_case_id\tsource_hex\tsource_sha256\tcandidate_commit\tassurance_epoch_sha256\tpackage_sha256\tproposal_sha256\treview_sha256\tbundle_sha256\ttargets_hex\tproof_path\tproof_manifest_sha256\n";
        fs::write(&catalog_path, header).unwrap();
        let mut expected = header.to_owned();
        for index in 0..128_u64 {
            let case_id = format!("regression-property-{index:04}");
            let columns = (0..12)
                .map(|column| test_digest(format!("{index}:{column}").as_bytes()))
                .collect::<Vec<_>>();
            let row = format!("{case_id}\t{}\n", columns.join("\t"));
            expected.push_str(&row);
            let updated = regression_updated_catalog(&directory, &case_id, &row).unwrap();
            assert_eq!(updated, expected);
            fs::write(&catalog_path, updated).unwrap();
        }
        assert_eq!(
            fs::read_to_string(&catalog_path).unwrap().lines().count(),
            130
        );
        fs::remove_dir_all(directory).unwrap();
    }

    #[test]
    fn merkle_directory_digest_is_order_independent_and_scope_sensitive() {
        let directory = create_private_temp_directory("hell-merkle-property").unwrap();
        let first = directory.join("first");
        let second = directory.join("second");
        fs::create_dir_all(first.join("nested")).unwrap();
        fs::create_dir_all(second.join("nested")).unwrap();
        fs::write(first.join("z.txt"), b"z").unwrap();
        fs::write(first.join("nested/a.txt"), b"a").unwrap();
        fs::write(second.join("nested/a.txt"), b"a").unwrap();
        fs::write(second.join("z.txt"), b"z").unwrap();
        assert_eq!(
            record_digest(&first).unwrap(),
            record_digest(&second).unwrap()
        );
        let original = record_digest(&first).unwrap();
        fs::write(first.join("nested/a.txt"), b"changed").unwrap();
        assert_ne!(record_digest(&first).unwrap(), original);
        fs::write(first.join("nested/a.txt"), b"a").unwrap();
        fs::rename(first.join("nested/a.txt"), first.join("a.txt")).unwrap();
        assert_ne!(record_digest(&first).unwrap(), original);
        fs::remove_dir_all(directory).unwrap();
    }

