    #[test]
    fn regression_catalog_deltas_compose_against_current_state_in_any_completion_order() {
        let directory = create_private_temp_directory("hell-regression-delta-composition").unwrap();
        let compatibility = directory.join("compat");
        fs::create_dir(&compatibility).unwrap();
        let catalog = compatibility.join("regression-corpus.tsv");
        let header = "schema_version\t2\ncolumns\tcase_id\ttemplate_case_id\tsource_hex\tsource_sha256\tcandidate_commit\tassurance_epoch_sha256\tpackage_sha256\tproposal_sha256\treview_sha256\tbundle_sha256\ttargets_hex\tproof_path\tproof_manifest_sha256\n";
        fs::write(&catalog, header).unwrap();
        let row = |case_id: &str, marker: u8| {
            let columns = [
                "template".to_owned(),
                format!("{marker:02x}"),
                test_digest(&[marker, 1]),
                test_git_sha(char::from(b'a' + marker)),
                test_digest(&[marker, 2]),
                test_digest(&[marker, 3]),
                test_digest(&[marker, 4]),
                test_digest(&[marker, 5]),
                test_digest(&[marker, 6]),
                format!("{marker:02x}"),
                format!("compat/regressions/{case_id}/proof.tsv"),
                test_digest(&[marker, 7]),
            ];
            format!("{case_id}\t{}\n", columns.join("\t"))
        };
        let first_id = "regression-delta-0001";
        let second_id = "regression-delta-0002";
        let first = row(first_id, 1);
        let second = row(second_id, 2);

        let after_second = regression_apply_catalog_delta(&directory, second_id, &second).unwrap();
        fs::write(&catalog, after_second).unwrap();
        let after_both = regression_apply_catalog_delta(&directory, first_id, &first).unwrap();
        fs::write(&catalog, &after_both).unwrap();
        assert!(after_both.ends_with(&format!("{second}{first}")));
        assert!(regression_apply_catalog_delta(&directory, first_id, &first).is_err());
        assert!(regression_apply_catalog_delta(&directory, second_id, &first).is_err());

        fs::write(&catalog, header).unwrap();
        let after_first = regression_apply_catalog_delta(&directory, first_id, &first).unwrap();
        fs::write(&catalog, after_first).unwrap();
        let reversed = regression_apply_catalog_delta(&directory, second_id, &second).unwrap();
        assert!(reversed.ends_with(&format!("{first}{second}")));
        fs::remove_dir_all(directory).unwrap();
    }

    struct OfflineAutomaticReviewedArtifact {
        subject: PathBuf,
        listing: JsonValue,
        artifact: JsonValue,
        run: JsonValue,
        archive: Vec<u8>,
    }

    impl OfflineAutomaticReviewedArtifact {
        fn provider(&self) -> AutomaticReviewedProviderArtifact<'_> {
            AutomaticReviewedProviderArtifact {
                listing: self.listing.clone(),
                artifact: &self.artifact,
                run: &self.run,
                archive: &self.archive,
            }
        }

        fn rebind_archive(&mut self) {
            self.archive = canonical_stored_zip(&self.subject).unwrap();
            let artifact = self.artifact.object_mut().unwrap();
            artifact.insert(
                "digest".to_owned(),
                JsonValue::String(format!("sha256:{}", sha256_bytes(&self.archive).hex())),
            );
            artifact.insert(
                "size_in_bytes".to_owned(),
                JsonValue::Number(self.archive.len() as u64),
            );
            self.listing = self.artifact.clone();
        }
    }

    struct OfflineAutomaticReviewedIdentity<'a> {
        batch_id: u64,
        case_id: &'a str,
        active_candidate: &'a str,
        provider_head: &'a str,
        artifact_id: u64,
        run_id: u64,
    }

    fn offline_automatic_reviewed_artifact(
        fixture_root: &Path,
        identity: &OfflineAutomaticReviewedIdentity<'_>,
    ) -> OfflineAutomaticReviewedArtifact {
        let subject = fixture_root.join(identity.case_id);
        let tree = subject.join("repository-tree");
        let package = tree
            .join("compat")
            .join("regressions")
            .join(identity.case_id)
            .join("package");
        fs::create_dir_all(&package).unwrap();
        let record = JsonValue::Object(BTreeMap::from([
            (
                "candidateCommit".to_owned(),
                JsonValue::String(identity.active_candidate.to_owned()),
            ),
            (
                "caseId".to_owned(),
                JsonValue::String(identity.case_id.to_owned()),
            ),
            (
                "repositoryTreePath".to_owned(),
                JsonValue::String("repository-tree".to_owned()),
            ),
        ]));
        write_atomic(
            &subject.join("promoted-regression.json"),
            &canonical_json_bytes(&record).unwrap(),
        )
        .unwrap();
        let proposal = JsonValue::Object(BTreeMap::from([(
            "issue".to_owned(),
            JsonValue::String(format!("github-run:{}", identity.batch_id)),
        )]));
        write_atomic(
            &package.join("proposal.json"),
            &canonical_json_bytes(&proposal).unwrap(),
        )
        .unwrap();
        offline_automatic_reviewed_provider(identity, subject)
    }

    fn offline_automatic_reviewed_provider(
        identity: &OfflineAutomaticReviewedIdentity<'_>,
        subject: PathBuf,
    ) -> OfflineAutomaticReviewedArtifact {
        let archive = canonical_stored_zip(&subject).unwrap();
        let name = format!(
            "reviewed-regression-{}-{}-{}-2",
            identity.batch_id, identity.case_id, identity.run_id
        );
        let archive_url = format!(
            "https://api.github.com/repos/Portfoligno/hell-rs/actions/artifacts/{}/zip",
            identity.artifact_id
        );
        let artifact = JsonValue::Object(BTreeMap::from([
            (
                "archive_download_url".to_owned(),
                JsonValue::String(archive_url),
            ),
            (
                "created_at".to_owned(),
                JsonValue::String("2026-08-11T00:00:00Z".to_owned()),
            ),
            (
                "digest".to_owned(),
                JsonValue::String(format!("sha256:{}", sha256_bytes(&archive).hex())),
            ),
            ("expired".to_owned(), JsonValue::Bool(false)),
            (
                "expires_at".to_owned(),
                JsonValue::String("2099-08-11T00:00:00Z".to_owned()),
            ),
            ("id".to_owned(), JsonValue::Number(identity.artifact_id)),
            ("name".to_owned(), JsonValue::String(name)),
            (
                "size_in_bytes".to_owned(),
                JsonValue::Number(archive.len() as u64),
            ),
            (
                "workflow_run".to_owned(),
                JsonValue::Object(BTreeMap::from([(
                    "id".to_owned(),
                    JsonValue::Number(identity.run_id),
                )])),
            ),
        ]));
        let run = offline_automatic_reviewed_run(identity);
        OfflineAutomaticReviewedArtifact {
            subject,
            listing: artifact.clone(),
            artifact,
            run,
            archive,
        }
    }

    fn offline_automatic_reviewed_run(
        identity: &OfflineAutomaticReviewedIdentity<'_>,
    ) -> JsonValue {
        JsonValue::Object(BTreeMap::from([
            (
                "conclusion".to_owned(),
                JsonValue::String("success".to_owned()),
            ),
            (
                "event".to_owned(),
                JsonValue::String("workflow_dispatch".to_owned()),
            ),
            (
                "head_sha".to_owned(),
                JsonValue::String(identity.provider_head.to_owned()),
            ),
            ("id".to_owned(), JsonValue::Number(identity.run_id)),
            (
                "path".to_owned(),
                JsonValue::String(".github/workflows/regression-corpus.yml@main".to_owned()),
            ),
            (
                "repository".to_owned(),
                JsonValue::Object(BTreeMap::from([
                    (
                        "full_name".to_owned(),
                        JsonValue::String("Portfoligno/hell-rs".to_owned()),
                    ),
                    ("id".to_owned(), JsonValue::Number(23)),
                ])),
            ),
            ("run_attempt".to_owned(), JsonValue::Number(2)),
            (
                "status".to_owned(),
                JsonValue::String("completed".to_owned()),
            ),
        ]))
    }

    fn advance_offline_provider_repository(repository: &Path) {
        write_atomic(&repository.join("unrelated-current-main"), b"advanced\n").unwrap();
        for arguments in [
            vec!["add", "unrelated-current-main"],
            vec![
                "-c",
                "user.name=Offline Collector Fixture",
                "-c",
                "user.email=offline-collector@example.invalid",
                "commit",
                "--quiet",
                "--no-gpg-sign",
                "-m",
                "advance current main after reviewed artifacts",
            ],
        ] {
            assert!(
                std::process::Command::new("git")
                    .args(arguments)
                    .current_dir(repository)
                    .env("GIT_AUTHOR_DATE", "2026-08-12T00:00:00Z")
                    .env("GIT_COMMITTER_DATE", "2026-08-12T00:00:00Z")
                    .status()
                    .unwrap()
                    .success()
            );
        }
    }

    fn write_offline_automatic_ready_set(
        path: &Path,
        candidate: &str,
        case_ids: &[&str],
    ) -> Vec<String> {
        let plans = case_ids
            .iter()
            .map(|case_id| {
                JsonValue::Object(BTreeMap::from([
                    (
                        "case_id".to_owned(),
                        JsonValue::String((*case_id).to_owned()),
                    ),
                    (
                        "category".to_owned(),
                        JsonValue::String("semantic-mismatch".to_owned()),
                    ),
                    (
                        "template_case_id".to_owned(),
                        JsonValue::String("int-plus-boundary-positive-value".to_owned()),
                    ),
                ]))
            })
            .collect::<Vec<_>>();
        write_automatic_regression_ready_set(
            path,
            candidate,
            &AutomaticRegressionRun { id: 41, attempt: 2 },
            &plans,
        )
        .unwrap();
        case_ids.iter().map(|value| (*value).to_owned()).collect()
    }

    fn collect_offline_automatic_reviewed_artifacts(
        repository: &Path,
        output: &Path,
        authority: &AutomaticRegressionCollectionAuthority<'_>,
        artifacts: &[JsonValue],
        fixtures: &BTreeMap<u64, OfflineAutomaticReviewedArtifact>,
    ) -> (Result<(), String>, Vec<u64>) {
        fs::create_dir(output).unwrap();
        let mut attempts = Vec::new();
        let result = collect_automatic_regression_transaction_to_with(
            output,
            authority,
            artifacts,
            |selected, case_id, cases_root| {
                let artifact_id = json_member(selected.object()?, "id")?.number()?;
                attempts.push(artifact_id);
                let fixture = fixtures
                    .get(&artifact_id)
                    .ok_or_else(|| "offline provider fixture is missing".to_owned())?;
                retain_automatic_reviewed_artifact_from_provider(
                    repository,
                    &fixture.provider(),
                    authority.batch_id,
                    case_id,
                    authority.candidate,
                    cases_root,
                )
            },
        );
        (result, attempts)
    }

    fn offline_automatic_reviewed_candidates(
        fixture_root: &Path,
        active_candidate: &str,
        provider_head: &str,
    ) -> (
        Vec<JsonValue>,
        BTreeMap<u64, OfflineAutomaticReviewedArtifact>,
    ) {
        let first_id = "generated-batch-0001";
        let first = offline_automatic_reviewed_artifact(
            fixture_root,
            &OfflineAutomaticReviewedIdentity {
                batch_id: 41,
                case_id: first_id,
                active_candidate,
                provider_head,
                artifact_id: 81,
                run_id: 71,
            },
        );
        let second = offline_automatic_reviewed_artifact(
            fixture_root,
            &OfflineAutomaticReviewedIdentity {
                batch_id: 41,
                case_id: "generated-batch-0002",
                active_candidate,
                provider_head,
                artifact_id: 82,
                run_id: 72,
            },
        );
        let third = offline_automatic_reviewed_artifact(
            fixture_root,
            &OfflineAutomaticReviewedIdentity {
                batch_id: 41,
                case_id: "generated-batch-0003",
                active_candidate,
                provider_head,
                artifact_id: 83,
                run_id: 73,
            },
        );
        let stale_candidate = offline_automatic_reviewed_artifact(
            &fixture_root.join("stale-candidate"),
            &OfflineAutomaticReviewedIdentity {
                batch_id: 41,
                case_id: first_id,
                active_candidate: &test_git_sha('b'),
                provider_head,
                artifact_id: 92,
                run_id: 92,
            },
        );
        let mut stale_issue = offline_automatic_reviewed_artifact(
            &fixture_root.join("stale-issue"),
            &OfflineAutomaticReviewedIdentity {
                batch_id: 41,
                case_id: first_id,
                active_candidate,
                provider_head,
                artifact_id: 91,
                run_id: 91,
            },
        );
        change_offline_automatic_issue(&mut stale_issue, first_id);
        let artifacts = vec![
            third.listing.clone(),
            second.listing.clone(),
            first.listing.clone(),
            stale_issue.listing.clone(),
            stale_candidate.listing.clone(),
        ];
        (
            artifacts,
            BTreeMap::from([
                (81, first),
                (82, second),
                (83, third),
                (91, stale_issue),
                (92, stale_candidate),
            ]),
        )
    }

    fn change_offline_automatic_issue(
        fixture: &mut OfflineAutomaticReviewedArtifact,
        case_id: &str,
    ) {
        let proposal_path = fixture
            .subject
            .join("repository-tree/compat/regressions")
            .join(case_id)
            .join("package/proposal.json");
        let mut proposal = parse_json(&read_text(&proposal_path).unwrap()).unwrap();
        proposal.object_mut().unwrap().insert(
            "issue".to_owned(),
            JsonValue::String("github-run:40".to_owned()),
        );
        write_atomic(&proposal_path, &canonical_json_bytes(&proposal).unwrap()).unwrap();
        fixture.rebind_archive();
    }

    #[test]
    fn automatic_reviewed_collector_replays_more_than_two_historical_provider_artifacts_offline() {
        let directory = create_private_temp_directory("hell-automatic-provider-collector").unwrap();
        let repository = directory.join("repository");
        synthetic_minimal_provider_repository(
            &repository,
            ".github/workflows/regression-corpus.yml",
        )
        .unwrap();
        let provider_head = git_output(&repository, &["rev-parse", "HEAD"])
            .unwrap()
            .trim()
            .to_owned();
        let active_candidate = test_git_sha('a');
        let first_id = "generated-batch-0001";
        let second_id = "generated-batch-0002";
        let third_id = "generated-batch-0003";
        let fixture_root = directory.join("fixtures");
        let (artifacts, fixtures) =
            offline_automatic_reviewed_candidates(&fixture_root, &active_candidate, &provider_head);
        advance_offline_provider_repository(&repository);
        assert_ne!(
            git_output(&repository, &["rev-parse", "HEAD"])
                .unwrap()
                .trim(),
            provider_head
        );
        let ready_set = directory.join("automatic-regression-ready-set.json");
        let expected_cases = write_offline_automatic_ready_set(
            &ready_set,
            &active_candidate,
            &[first_id, second_id, third_id],
        );
        let authority = AutomaticRegressionCollectionAuthority {
            ready_set_path: &ready_set,
            expected_cases: &expected_cases,
            candidate: &active_candidate,
            batch_id: 41,
            nightly_authority: None,
        };
        let transaction = directory.join("transaction");
        let (result, attempts) = collect_offline_automatic_reviewed_artifacts(
            &repository,
            &transaction,
            &authority,
            &artifacts,
            &fixtures,
        );
        result.unwrap();
        assert_eq!(attempts, vec![92, 91, 81, 82, 83]);
        let cases = transaction.join("cases");
        for case_id in [first_id, second_id, third_id] {
            let case_root = cases.join(case_id);
            reverify_provider_selection_with_distinct_head(
                &repository,
                &case_root.join("promotion"),
                &case_root.join("selection"),
                &active_candidate,
                &provider_head,
                ".github/workflows/regression-corpus.yml",
            )
            .unwrap();
        }
        assert_eq!(
            strict_directory_names(&cases).unwrap(),
            BTreeSet::from([
                first_id.to_owned(),
                second_id.to_owned(),
                third_id.to_owned(),
            ])
        );
        assert_automatic_collection_set_substitutions(
            &directory,
            &repository,
            &authority,
            &artifacts,
            &fixtures,
        );
        let first_selection = cases.join(first_id).join("selection");
        fs::write(first_selection.join("provider-archive.zip"), b"changed").unwrap();
        assert!(
            reverify_provider_selection_with_distinct_head(
                &repository,
                &cases.join(first_id).join("promotion"),
                &first_selection,
                &active_candidate,
                &provider_head,
                ".github/workflows/regression-corpus.yml",
            )
            .is_err()
        );
        fs::remove_dir_all(directory).unwrap();
    }

    fn assert_automatic_collection_set_substitutions(
        directory: &Path,
        repository: &Path,
        authority: &AutomaticRegressionCollectionAuthority<'_>,
        artifacts: &[JsonValue],
        fixtures: &BTreeMap<u64, OfflineAutomaticReviewedArtifact>,
    ) {
        let missing = artifacts
            .iter()
            .filter(|value| {
                json_member(value.object().unwrap(), "id")
                    .unwrap()
                    .number()
                    .unwrap()
                    != 82
            })
            .cloned()
            .collect::<Vec<_>>();
        let (result, _) = collect_offline_automatic_reviewed_artifacts(
            repository,
            &directory.join("missing-case"),
            authority,
            &missing,
            fixtures,
        );
        assert_eq!(
            result.unwrap_err(),
            "automatic reviewed regression set is pending"
        );
        let wrong_candidate = test_git_sha('c');
        for (label, cases, candidate, batch_id) in [
            (
                "extra-case",
                vec![
                    "generated-batch-0001".to_owned(),
                    "generated-batch-0002".to_owned(),
                    "generated-batch-0003".to_owned(),
                    "generated-batch-0004".to_owned(),
                ],
                authority.candidate,
                authority.batch_id,
            ),
            (
                "duplicate-case",
                vec![
                    "generated-batch-0001".to_owned(),
                    "generated-batch-0001".to_owned(),
                ],
                authority.candidate,
                authority.batch_id,
            ),
            (
                "wrong-candidate",
                authority.expected_cases.to_vec(),
                wrong_candidate.as_str(),
                authority.batch_id,
            ),
            (
                "wrong-batch",
                authority.expected_cases.to_vec(),
                authority.candidate,
                42,
            ),
        ] {
            let changed = AutomaticRegressionCollectionAuthority {
                ready_set_path: authority.ready_set_path,
                expected_cases: &cases,
                candidate,
                batch_id,
                nightly_authority: None,
            };
            let (result, attempts) = collect_offline_automatic_reviewed_artifacts(
                repository,
                &directory.join(label),
                &changed,
                artifacts,
                fixtures,
            );
            assert!(result.is_err());
            assert!(attempts.is_empty());
        }
    }

