    fn assert_automatic_provider_metadata_substitutions(
        directory: &Path,
        repository: &Path,
        identity: &OfflineAutomaticReviewedIdentity<'_>,
    ) {
        for (label, target, key, value) in [
            ("listing-id", "listing", "id", JsonValue::Number(82)),
            (
                "listing-name",
                "listing",
                "name",
                JsonValue::String(
                    "reviewed-regression-41-generated-batch-0001-copy-71-2".to_owned(),
                ),
            ),
            ("listing-run", "listing-run", "id", JsonValue::Number(72)),
            (
                "listing-expired",
                "listing",
                "expired",
                JsonValue::Bool(true),
            ),
            (
                "artifact-digest",
                "artifact",
                "digest",
                JsonValue::String(format!("sha256:{}", test_digest(b"other archive"))),
            ),
            (
                "artifact-size",
                "artifact",
                "size_in_bytes",
                JsonValue::Number(1),
            ),
            ("run-attempt", "run", "run_attempt", JsonValue::Number(3)),
            (
                "run-event",
                "run",
                "event",
                JsonValue::String("push".to_owned()),
            ),
            (
                "run-path",
                "run",
                "path",
                JsonValue::String(
                    ".github/workflows/regression-corpus.yml@refs/heads/feature".to_owned(),
                ),
            ),
            ("repository-id", "repository", "id", JsonValue::Number(0)),
        ] {
            let mut fixture = offline_automatic_reviewed_artifact(
                &directory.join(format!("fixture-{label}")),
                identity,
            );
            let record = match target {
                "listing" => fixture.listing.object_mut().unwrap(),
                "artifact" => fixture.artifact.object_mut().unwrap(),
                "run" => fixture.run.object_mut().unwrap(),
                "listing-run" => {
                    json_member_mut(fixture.listing.object_mut().unwrap(), "workflow_run")
                        .unwrap()
                        .object_mut()
                        .unwrap()
                }
                "repository" => json_member_mut(fixture.run.object_mut().unwrap(), "repository")
                    .unwrap()
                    .object_mut()
                    .unwrap(),
                _ => unreachable!(),
            };
            record.insert(key.to_owned(), value);
            automatic_provider_fixture_rejects(directory, repository, identity, &fixture, label);
        }
    }

    fn assert_automatic_provider_subject_substitutions(
        directory: &Path,
        repository: &Path,
        identity: &OfflineAutomaticReviewedIdentity<'_>,
    ) {
        let mutations = ["case", "candidate", "issue"];
        for label in mutations {
            let mut fixture = offline_automatic_reviewed_artifact(
                &directory.join(format!("fixture-subject-{label}")),
                identity,
            );
            let target = if label == "issue" {
                fixture
                    .subject
                    .join("repository-tree/compat/regressions")
                    .join(identity.case_id)
                    .join("package/proposal.json")
            } else {
                fixture.subject.join("promoted-regression.json")
            };
            let mut value = parse_json(&read_text(&target).unwrap()).unwrap();
            let (key, replacement) = match label {
                "case" => ("caseId", "generated-batch-0002".to_owned()),
                "candidate" => ("candidateCommit", test_git_sha('b')),
                "issue" => ("issue", "github-run:42".to_owned()),
                _ => unreachable!(),
            };
            value
                .object_mut()
                .unwrap()
                .insert(key.to_owned(), JsonValue::String(replacement));
            write_atomic(&target, &canonical_json_bytes(&value).unwrap()).unwrap();
            fixture.rebind_archive();
            automatic_provider_fixture_rejects(directory, repository, identity, &fixture, label);
        }
    }

    #[test]
    fn automatic_ready_set_requires_and_composes_every_reviewed_delta_once() {
        let directory = create_private_temp_directory("hell-regression-batch-transaction").unwrap();
        let first_id = "generated-batch-0001";
        let second_id = "generated-batch-0002";
        let third_id = "generated-batch-0003";
        let plans = [first_id, second_id, third_id]
            .into_iter()
            .map(|case_id| {
                JsonValue::Object(BTreeMap::from([
                    ("case_id".to_owned(), JsonValue::String(case_id.to_owned())),
                    (
                        "category".to_owned(),
                        JsonValue::String("semantic-mismatch".to_owned()),
                    ),
                    (
                        "template_case_id".to_owned(),
                        JsonValue::String("int-plus-boundary-positive-value".to_owned()),
                    ),
                ]))
            })
            .collect::<Vec<_>>();
        let ready_set_path = directory.join("automatic-regression-ready-set.json");
        write_automatic_regression_ready_set(
            &ready_set_path,
            &test_git_sha('a'),
            &AutomaticRegressionRun { id: 41, attempt: 2 },
            &plans,
        )
        .unwrap();
        let ready_set = parse_json(&fs::read_to_string(&ready_set_path).unwrap()).unwrap();
        assert_eq!(
            verify_automatic_regression_ready_set(&ready_set).unwrap(),
            vec![
                first_id.to_owned(),
                second_id.to_owned(),
                third_id.to_owned(),
            ]
        );
        assert_automatic_batch_provider_selection(&ready_set, first_id);

        let delta = |case_id: &str, marker: u8| VerifiedRegressionDelta {
            case_id: case_id.to_owned(),
            candidate: test_git_sha('a'),
            epoch: test_digest(b"batch epoch"),
            historical_base_sha256: test_digest(b"batch historical catalog"),
            issue: "github-run:41".to_owned(),
            row: format!("{case_id}\t{}\n", ["field"; 12].join("\t")),
            proof_source: directory.join("proofs").join(marker.to_string()),
        };
        let first = delta(first_id, 1);
        let second = delta(second_id, 2);
        let third = delta(third_id, 3);
        verify_regression_delta_transaction(&[first, second, third]).unwrap();

        let duplicate = delta(first_id, 3);
        assert!(verify_regression_delta_transaction(&[delta(first_id, 1), duplicate]).is_err());
        let mut conflicting = delta(second_id, 2);
        conflicting.historical_base_sha256 = test_digest(b"conflicting historical catalog");
        assert!(verify_regression_delta_transaction(&[delta(first_id, 1), conflicting]).is_err());
        let mut wrong_issue = delta(second_id, 2);
        wrong_issue.issue = "github-run:42".to_owned();
        assert!(verify_regression_delta_transaction(&[delta(first_id, 1), wrong_issue]).is_err());

        let cases = directory.join("cases");
        fs::create_dir(&cases).unwrap();
        fs::create_dir(cases.join(first_id)).unwrap();
        assert_ne!(
            strict_directory_names(&cases).unwrap(),
            BTreeSet::from([first_id.to_owned(), second_id.to_owned()])
        );
        fs::create_dir(cases.join(second_id)).unwrap();
        assert_eq!(
            strict_directory_names(&cases).unwrap(),
            BTreeSet::from([first_id.to_owned(), second_id.to_owned()])
        );
        fs::remove_dir_all(directory).unwrap();
    }

    fn initialize_current_main_retry_fixture(directory: &Path) -> (PathBuf, PathBuf) {
        let seed = directory.join("seed");
        synthetic_minimal_provider_repository(&seed, ".github/workflows/regression-corpus.yml")
            .unwrap();
        write_atomic(&seed.join("trusted-integrator-version"), b"0\n").unwrap();
        let policy = seed.join("crates/hell-ci/src/policy.rs");
        fs::create_dir_all(policy.parent().unwrap()).unwrap();
        write_atomic(&policy, b"// trusted integration policy v0\n").unwrap();
        git_output(
            &seed,
            &[
                "add",
                "trusted-integrator-version",
                "crates/hell-ci/src/policy.rs",
            ],
        )
        .unwrap();
        git_output(
            &seed,
            &[
                "-c",
                "user.name=Retry Fixture",
                "-c",
                "user.email=retry@example.invalid",
                "commit",
                "--no-gpg-sign",
                "-m",
                "add trusted integrator identity",
            ],
        )
        .unwrap();
        let remote = directory.join("remote.git");
        let remote_text = path_text(&remote).unwrap();
        git_output(
            directory,
            &["init", "--bare", "--initial-branch=main", &remote_text],
        )
        .unwrap();
        git_output(&seed, &["remote", "add", "origin", &remote_text]).unwrap();
        git_output(&seed, &["push", "-u", "origin", "main"]).unwrap();
        let runner = directory.join("runner");
        let runner_text = path_text(&runner).unwrap();
        git_output(directory, &["clone", &remote_text, &runner_text]).unwrap();
        let contender = directory.join("contender");
        let contender_text = path_text(&contender).unwrap();
        git_output(directory, &["clone", &remote_text, &contender_text]).unwrap();
        (runner, contender)
    }

    fn commit_retry_fixture_change(repository: &Path, version: u8) {
        let proof = repository
            .join("compat/regressions")
            .join(format!("concurrent-{version}.proof"));
        fs::create_dir_all(proof.parent().unwrap()).unwrap();
        write_atomic(
            &proof,
            format!("controlled concurrent regression {version}\n").as_bytes(),
        )
        .unwrap();
        git_output(repository, &["add", "compat/regressions"]).unwrap();
        git_output(
            repository,
            &[
                "-c",
                "user.name=Concurrent Main Writer",
                "-c",
                "user.email=concurrent@example.invalid",
                "commit",
                "--no-gpg-sign",
                "-m",
                "advance trusted main integrator",
            ],
        )
        .unwrap();
        git_output(repository, &["push", "origin", "HEAD:refs/heads/main"]).unwrap();
    }

    #[test]
    fn current_main_transaction_survives_six_controlled_ref_update_winners() {
        let directory = create_private_temp_directory("hell-current-main-retry-test").unwrap();
        let (runner, contender) = initialize_current_main_retry_fixture(&directory);
        let mut prepared_attempts = 0_u8;
        let mut waited_attempts = Vec::new();
        retry_current_main_regression_transaction_with(
            &runner,
            8,
            |worktree| {
                prepared_attempts += 1;
                let version = read_text(&worktree.join("trusted-integrator-version")).unwrap();
                let proof = worktree.join("compat/regressions/transaction-observed-integrator");
                fs::create_dir_all(proof.parent().unwrap()).unwrap();
                write_atomic(&proof, version.as_bytes()).unwrap();
                git_output(
                    worktree,
                    &[
                        "add",
                        "trusted-integrator-version",
                        "compat/regressions/transaction-observed-integrator",
                    ],
                )
                .unwrap();
                git_output(
                    worktree,
                    &[
                        "-c",
                        "user.name=Current Main Transaction",
                        "-c",
                        "user.email=transaction@example.invalid",
                        "commit",
                        "--no-gpg-sign",
                        "-m",
                        "prepare current-main transaction",
                    ],
                )
                .unwrap();
                if prepared_attempts <= 6 {
                    commit_retry_fixture_change(&contender, prepared_attempts);
                }
                Ok(())
            },
            |attempt| waited_attempts.push(attempt),
        )
        .unwrap();
        assert_eq!(prepared_attempts, 7);
        assert_eq!(waited_attempts, vec![1, 2, 3, 4, 5, 6]);
        git_output(
            &runner,
            &[
                "fetch",
                "origin",
                "refs/heads/main:refs/remotes/origin/main",
            ],
        )
        .unwrap();
        assert_eq!(
            git_output(
                &runner,
                &[
                    "show",
                    "refs/remotes/origin/main:compat/regressions/transaction-observed-integrator"
                ]
            )
            .unwrap(),
            "0\n"
        );
        fs::remove_dir_all(directory).unwrap();
    }

    #[test]
    fn current_main_transaction_rejects_integrator_policy_movement_before_retry() {
        let directory = create_private_temp_directory("hell-current-main-authority-test").unwrap();
        let (runner, contender) = initialize_current_main_retry_fixture(&directory);
        let mut prepared_attempts = 0_u8;
        let error = retry_current_main_regression_transaction_with(
            &runner,
            8,
            |worktree| {
                prepared_attempts += 1;
                let proof = worktree.join("compat/regressions/pending-transaction");
                fs::create_dir_all(proof.parent().unwrap()).unwrap();
                write_atomic(&proof, b"pending reviewed transaction\n").unwrap();
                git_output(worktree, &["add", "compat/regressions/pending-transaction"]).unwrap();
                git_output(
                    worktree,
                    &[
                        "-c",
                        "user.name=Current Main Transaction",
                        "-c",
                        "user.email=transaction@example.invalid",
                        "commit",
                        "--no-gpg-sign",
                        "-m",
                        "prepare transaction before authority movement",
                    ],
                )
                .unwrap();
                if prepared_attempts == 1 {
                    write_atomic(
                        &contender.join("crates/hell-ci/src/policy.rs"),
                        b"// trusted integration policy v1\n",
                    )
                    .unwrap();
                    git_output(&contender, &["add", "crates/hell-ci/src/policy.rs"]).unwrap();
                    git_output(
                        &contender,
                        &[
                            "-c",
                            "user.name=Policy Update",
                            "-c",
                            "user.email=policy@example.invalid",
                            "commit",
                            "--no-gpg-sign",
                            "-m",
                            "update current-main integration policy",
                        ],
                    )
                    .unwrap();
                    git_output(&contender, &["push", "origin", "HEAD:refs/heads/main"]).unwrap();
                }
                Ok(())
            },
            |_| {},
        )
        .unwrap_err();
        assert_eq!(prepared_attempts, 1);
        assert!(error.contains("trusted current-main integration authority changed"));
        assert!(error.contains("fresh protected job"));
        git_output(
            &runner,
            &[
                "fetch",
                "origin",
                "refs/heads/main:refs/remotes/origin/main",
            ],
        )
        .unwrap();
        assert!(
            git_output(
                &runner,
                &[
                    "show",
                    "refs/remotes/origin/main:compat/regressions/pending-transaction"
                ]
            )
            .is_err()
        );
        fs::remove_dir_all(directory).unwrap();
    }

    #[test]
    fn semantic_fuzz_workspace_is_isolated_and_rejects_untracked_corpus_output() {
        let directory = create_private_temp_directory("hell-fuzz-corpus-isolation").unwrap();
        let repository = directory.join("repository");
        synthetic_minimal_provider_repository(
            &repository,
            ".github/workflows/regression-corpus.yml",
        )
        .unwrap();
        let corpus = repository.join("crates/hell-ci/fuzz/corpus");
        for target in SEMANTIC_FUZZ_TARGETS {
            let target_root = corpus.join(target);
            fs::create_dir_all(&target_root).unwrap();
            write_atomic(&target_root.join("seed"), format!("{target}\n").as_bytes()).unwrap();
        }
        git_output(&repository, &["add", "crates/hell-ci/fuzz/corpus"]).unwrap();
        git_output(
            &repository,
            &[
                "-c",
                "user.name=Fuzz Corpus Fixture",
                "-c",
                "user.email=fuzz@example.invalid",
                "commit",
                "--no-gpg-sign",
                "-m",
                "add reviewed fuzz seeds",
            ],
        )
        .unwrap();
        let prepare = Options {
            action: Some("prepare".to_owned()),
            input: Some(corpus.clone()),
            output: Some(repository.join("ci-out/fuzz-corpora")),
            to: Some(repository.join("ci-out/fuzz-artifacts")),
            ..Options::default()
        };
        semantic_fuzz_corpus(&repository, &prepare).unwrap();
        for target in SEMANTIC_FUZZ_TARGETS {
            assert!(repository.join("ci-out/fuzz-corpora").join(target).is_dir());
            assert!(
                repository
                    .join("ci-out/fuzz-artifacts")
                    .join(target)
                    .is_dir()
            );
        }
        let verify = Options {
            action: Some("verify-clean".to_owned()),
            input: Some(corpus.clone()),
            ..Options::default()
        };
        semantic_fuzz_corpus(&repository, &verify).unwrap();
        let untracked_output = corpus.join("claim_toml/hash-named-fuzzer-output");
        write_atomic(&untracked_output, b"mutation\n").unwrap();
        assert!(semantic_fuzz_corpus(&repository, &verify).is_err());
        fs::remove_file(untracked_output).unwrap();
        semantic_fuzz_corpus(&repository, &verify).unwrap();

        let workflow = repository.join(".github/workflows/regression-corpus.yml");
        let mut changed_workflow = fs::read(&workflow).unwrap();
        changed_workflow.extend_from_slice(b"# tracked mutation outside fuzz corpus\n");
        write_atomic(&workflow, &changed_workflow).unwrap();
        assert!(semantic_fuzz_corpus(&repository, &verify).is_err());
        fs::remove_dir_all(directory).unwrap();
    }

    fn assert_automatic_batch_provider_selection(ready_set: &JsonValue, case_id: &str) {
        let dispatch_fields = automatic_regression_dispatch_fields(
            "provider-context",
            "int-plus-boundary-positive-value",
            case_id,
            "semantic-mismatch",
            "github-run:41",
        )
        .unwrap();
        assert_eq!(
            dispatch_fields.iter().collect::<BTreeSet<_>>().len(),
            dispatch_fields.len()
        );
        assert_eq!(dispatch_fields.last().unwrap(), "batch_id=41");
        let provider_record = JsonValue::Object(BTreeMap::from([
            (
                "artifact".to_owned(),
                JsonValue::String("nightly-41-2".to_owned()),
            ),
            (
                "candidateCommit".to_owned(),
                JsonValue::String(test_git_sha('a')),
            ),
            ("event".to_owned(), JsonValue::String("schedule".to_owned())),
            ("providerRunAttempt".to_owned(), JsonValue::Number(2)),
            ("providerRunId".to_owned(), JsonValue::Number(41)),
        ]));
        verify_automatic_ready_set_provider_record(
            ready_set.object().unwrap(),
            provider_record.object().unwrap(),
        )
        .unwrap();
        for (key, value) in [
            (
                "artifact",
                JsonValue::String("nightly-copy-41-2".to_owned()),
            ),
            ("providerRunId", JsonValue::Number(42)),
            ("providerRunAttempt", JsonValue::Number(3)),
            ("event", JsonValue::String("workflow_dispatch".to_owned())),
            ("candidateCommit", JsonValue::String(test_git_sha('b'))),
        ] {
            let mut changed = provider_record.clone();
            changed.object_mut().unwrap().insert(key.to_owned(), value);
            assert!(
                verify_automatic_ready_set_provider_record(
                    ready_set.object().unwrap(),
                    changed.object().unwrap(),
                )
                .is_err()
            );
        }
        assert_eq!(
            automatic_reviewed_artifact_name(
                "reviewed-regression-41-generated-batch-0001-71-2",
                41,
                case_id,
            ),
            Some((71, 2))
        );
        assert_eq!(
            automatic_reviewed_artifact_name(
                "reviewed-regression-41-generated-batch-0001-copy-71-2",
                41,
                case_id,
            ),
            None
        );
        let artifact = |id: u64, name: &str| {
            JsonValue::Object(BTreeMap::from([
                ("id".to_owned(), JsonValue::Number(id)),
                ("name".to_owned(), JsonValue::String(name.to_owned())),
            ]))
        };
        let artifacts = vec![
            artifact(90, "reviewed-regression-42-generated-batch-0001-90-1"),
            artifact(80, "reviewed-regression-41-generated-batch-0001-80-1"),
            artifact(70, "reviewed-regression-41-generated-batch-0001-70-1"),
        ];
        let mut attempted = Vec::new();
        select_authoritative_automatic_reviewed_artifact(&artifacts, 41, case_id, |artifact| {
            let id = json_member(artifact.object()?, "id")?.number()?;
            attempted.push(id);
            (id != 80).then_some(()).ok_or_else(|| {
                "automatic reviewed regression differs from ready-set authority".to_owned()
            })
        })
        .unwrap();
        assert_eq!(attempted, vec![80, 70]);
    }

